_AIXRAY_SESSION_KEYS=""
  # ssh_permituserenv — assess the global value normalized by `sshd -T`.
  typeset SSH_PUE_RAW SSH_PUE_CAPTURE_RC SSH_PUE_PARSED SSH_PUE_VALUE
  typeset SSH_PUE_STATUS SSH_PUE_OBSERVED SSH_PUE_MEANING SSH_PUE_FIX
