      SSH_PUE_RAW=$SSHT
      SSH_PUE_CAPTURE_RC=$SSHT_RC
    else
      SSH_PUE_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_PUE_CAPTURE_RC=$?
    fi
    if [ "$SSH_PUE_CAPTURE_RC" -ne 0 ]; then
      SSH_PUE_REASON="sshd -T failed (rc=$SSH_PUE_CAPTURE_RC)"
    elif [ -z "$SSH_PUE_RAW" ]; then
      SSH_PUE_REASON='sshd -T returned empty output'
    else
      SSH_PUE_PARSED=$(printf '%s\n' "$SSH_PUE_RAW" | awk '
        $1 == "permituserenvironment" {
          count++
          if (NF != 2) invalid=1
          else value=$2
        }
        END {
          if (count != 1) print "__COUNT__"
          else if (invalid || value == "") print "__INVALID__"
          else print value
        }')
      case "$SSH_PUE_PARSED" in
        no)
          SSH_PUE_VALUE=no
          SSH_PUE_STATUS=PASS
          SSH_PUE_OBSERVED='PermitUserEnvironment no'
          SSH_PUE_MEANING='sshd does not process user-controlled environment settings during authentication.'
          SSH_PUE_FIX='n/a'
          ;;
        __COUNT__)
          SSH_PUE_REASON='effective row is missing or duplicate'
          ;;
        __INVALID__)
          SSH_PUE_REASON='effective value is unparseable'
          ;;
        *)
          SSH_PUE_VALUE=$SSH_PUE_PARSED
          SSH_PUE_STATUS=FAIL
          SSH_PUE_OBSERVED="PermitUserEnvironment $SSH_PUE_VALUE"
          SSH_PUE_MEANING='sshd accepts user-controlled environment settings, which can bypass restrictions in configurations that trust environment-sensitive programs.'
