    PW_MX_PARSED=$(printf '%s\n' "$PW_MX_RAW" | awk '
      {
        rows++
        if ($0 ~ /^[[:space:]]*#/) { comment=1; next }
        if ($1 != "default") { stanza=1; next }
        if (rows != 1) { duplicate=1; next }
        if (NF != 3) { row=1; next }
        if ($0 !~ /^default maxexpired=[^[:space:]]* maxage=[^[:space:]]*$/) {
          row=1
          next
