      END {
        if (rows != 1 || comment || stanza || duplicate || row) {
          print "shape||"
        } else if (mx !~ /^(-1|-[1-9][0-9]*|0|[1-9][0-9]*)$/ ||
                   ma !~ /^(0|[1-9][0-9]*)$/) {
          print "values||"
        } else {
          print "value|" mx "|" ma
        }
      }')
