      PW_MX_VALUES=${PW_MX_PARSED#*\|}
      PW_MX_VALUE=${PW_MX_VALUES%%\|*}
      PW_MX_MAXAGE=${PW_MX_VALUES#*\|}
      case "$PW_MX_STATE" in
