_AIXRAY_SESSION_KEYS=""
  # pw_maxage — maximum password age inherited from the default stanza.
  # This diagnostic fragment accepts only one exact attribute-scoped assignment.
  typeset PW_AGE_RAW PW_AGE_RC PW_AGE_PARSED PW_AGE_STATE PW_AGE_VALUE
  typeset PW_AGE_STATUS PW_AGE_OBSERVED PW_AGE_REASON

  PW_AGE_RAW=""
  PW_AGE_RC=126
  PW_AGE_PARSED=""
  PW_AGE_STATE=""
  PW_AGE_VALUE=""
  PW_AGE_STATUS=NOT_ASSESSED
  PW_AGE_OBSERVED=""
  PW_AGE_REASON=""

  if [ "${MYUID:-0}" != "0" ]; then
    PW_AGE_REASON="requires root privileges"
  else
    PW_AGE_RAW=$(aix pw_maxage lssec -f /etc/security/user -s default -a maxage)
    PW_AGE_RC=$?
    if [ "$PW_AGE_RC" -ne 0 ]; then
      PW_AGE_REASON="capture failed (rc=$PW_AGE_RC)"
    elif [ -z "$PW_AGE_RAW" ]; then
      PW_AGE_REASON="capture returned empty output"
    else
      PW_AGE_PARSED=$(printf '%s\n' "$PW_AGE_RAW" | awk '
        /^[[:space:]]*$/ { next }
        {
          rows++
          if ($0 !~ /^default maxage=/) {
            bad=1
            next
          }
          value=$0
          sub(/^default maxage=/, "", value)
          if (value == "") {
            empty=1
          } else if (value !~ /^[0-9]+$/) {
            bad=1
          }
        }
        END {
          if (rows != 1 || bad) {
            print "bad|"
          } else if (empty) {
            print "empty|"
          } else {
            normalized=value
            sub(/^0+/, "", normalized)
            if (normalized == "") normalized="0"
            if (normalized ~ /^[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]/) {
              print "huge|"
            } else {
              number=normalized + 0
              if (number >= 1 && number <= 8) {
                print "pass|" normalized
              } else {
                print "fail|" normalized
              }
            }
          }
