_AIXRAY_SESSION_KEYS=""
  # pw_maxulogs — simultaneous login limit inherited from the default stanza.
  # This diagnostic fragment accepts only one exact attribute-scoped assignment.
  #
  # The probe runs through aixv (stderr merged), not aix, because lssec writes
  # diagnostics such as 'Attribute "maxulogs" is not valid.' to STDERR and
  # leaves stdout empty; under aix()'s blanket '2>/dev/null' that would arrive
  # as an empty value. maxulogs IS a valid attribute at AIX 7.2 and 7.3
  # (verified on both lab boxes on 2026-08-06: lssec accepts it with rc=0 and
  # no diagnostic), so a default stanza that leaves it unset is a determinate
  # observation, not a failed read. The empty branch below handles that case:
  # a valid attribute that is unset imposes no configured bound, so the check
  # returns FAIL. The attribute-not-valid branch remains for AIX levels where
  # the attribute does not exist, rendering NOT_APPLICABLE. A genuine refusal
  # is kept for the case where the attribute IS valid but its value is
  # unreadable or untrustworthy.
  typeset PW_MAXULOGS_RAW PW_MAXULOGS_RC PW_MAXULOGS_PARSED PW_MAXULOGS_STATE PW_MAXULOGS_VALUE
  typeset PW_MAXULOGS_STATUS PW_MAXULOGS_OBSERVED PW_MAXULOGS_REASON
  typeset PW_MAXULOGS_INVALID PW_MAXULOGS_LEVEL

  PW_MAXULOGS_RAW=""
  PW_MAXULOGS_RC=126
  PW_MAXULOGS_PARSED=""
  PW_MAXULOGS_STATE=""
  PW_MAXULOGS_VALUE=""
  PW_MAXULOGS_STATUS=NOT_ASSESSED
  PW_MAXULOGS_OBSERVED=""
  PW_MAXULOGS_REASON=""
  PW_MAXULOGS_INVALID=0
  PW_MAXULOGS_LEVEL=${OSLEVEL:-}

  if [ "${MYUID:-0}" != "0" ]; then
    PW_MAXULOGS_REASON="requires root privileges"
  else
    PW_MAXULOGS_RAW=$(aixv pw_maxulogs lssec -f /etc/security/user -s default -a maxulogs)
    PW_MAXULOGS_RC=$?
    # lssec's rejection is conclusive on either channel and at any exit status,
    # so it is read before the rc gate: the attribute not existing is an answer,
    # not a failed read.
    case "$PW_MAXULOGS_RAW" in
      *'Attribute "maxulogs" is not valid'*)
        PW_MAXULOGS_INVALID=1
        ;;
    esac
    if [ "$PW_MAXULOGS_INVALID" -eq 1 ]; then
      PW_MAXULOGS_STATUS=NOT_APPLICABLE
      if [ -n "$PW_MAXULOGS_LEVEL" ]; then
        PW_MAXULOGS_OBSERVED="maxulogs is not an attribute of /etc/security/user at AIX level $PW_MAXULOGS_LEVEL; lssec rejected it (rc=$PW_MAXULOGS_RC): Attribute \"maxulogs\" is not valid."
      else
        PW_MAXULOGS_OBSERVED="maxulogs is not an attribute of /etc/security/user at the running AIX level; lssec rejected it (rc=$PW_MAXULOGS_RC): Attribute \"maxulogs\" is not valid."
      fi
    elif [ "$PW_MAXULOGS_RC" -ne 0 ]; then
      PW_MAXULOGS_REASON="capture failed (rc=$PW_MAXULOGS_RC)"
    elif [ -z "$PW_MAXULOGS_RAW" ]; then
      PW_MAXULOGS_REASON="capture returned empty output"
    else
      PW_MAXULOGS_PARSED=$(printf '%s\n' "$PW_MAXULOGS_RAW" | awk '
        /^[[:space:]]*$/ { next }
        {
          rows++
          if ($0 !~ /^default maxulogs=/) {
            bad=1
            next
          }
          value=$0
          sub(/^default maxulogs=/, "", value)
          if (value == "") {
            empty=1
          } else if (value !~ /^[0-9]+$/) {
            bad=1
          }
        }
        END {
          if (rows != 1 || bad) {
            print "bad|"
          } else if (empty) {
            print "empty|"
          } else {
            normalized=value
            sub(/^0+/, "", normalized)
            if (normalized == "") normalized="0"
            if (normalized ~ /^[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]/) {
              print "huge|"
            } else {
              number=normalized + 0
              if (number >= 1 && number <= 10) {
                print "pass|" normalized
              } else {
                print "fail|" normalized
              }
            }
          }
        }')
      PW_MAXULOGS_STATE=${PW_MAXULOGS_PARSED%%\|*}
      PW_MAXULOGS_VALUE=${PW_MAXULOGS_PARSED#*\|}
      case "$PW_MAXULOGS_STATE" in
        pass)
          PW_MAXULOGS_STATUS=PASS
          PW_MAXULOGS_OBSERVED="maxulogs=$PW_MAXULOGS_VALUE"
          ;;
        fail)
          PW_MAXULOGS_STATUS=FAIL
          PW_MAXULOGS_OBSERVED="maxulogs=$PW_MAXULOGS_VALUE; required between 1 and 10 inclusive"
          ;;
        huge)
          PW_MAXULOGS_REASON="value was too large to compare safely"
          ;;
        empty)
          PW_MAXULOGS_STATUS=FAIL
          PW_MAXULOGS_OBSERVED="maxulogs is unset in the default stanza; required between 1 and 10 inclusive"
          ;;
        *)
          PW_MAXULOGS_REASON="output was not one exact unsigned-decimal assignment"
          ;;
      esac
    fi
  fi

  case "$PW_MAXULOGS_STATUS" in
    PASS)
      add security pw_maxulogs "Simultaneous login limit" PASS high \
          "$PW_MAXULOGS_OBSERVED" \
          "The default policy bounds simultaneous login sessions at the approved boundary." \
          "n/a" ""
      ;;
    FAIL)
      add security pw_maxulogs "Simultaneous login limit" FAIL high \
          "$PW_MAXULOGS_OBSERVED" \
          "Accounts inheriting the default stanza receive a weaker maxulogs policy." \
          "after access-impact review, set maxulogs to the boundary with 'chsec -f /etc/security/user -s default -a maxulogs=10'; PTxray only recommends this command." \
          ""
