  # pw_dictionlist — configured password dictionary paths inherited from the
  # default stanza. This diagnostic fragment never reads the referenced files.
  typeset PW_DICT_RAW PW_DICT_RC PW_DICT_PARSED PW_DICT_STATE PW_DICT_VALUE
  typeset PW_DICT_STATUS PW_DICT_OBSERVED PW_DICT_REASON PW_DICT_MEANING

  PW_DICT_RAW=""
  PW_DICT_RC=126
  PW_DICT_PARSED=""
  PW_DICT_STATE=""
  PW_DICT_VALUE=""
  PW_DICT_STATUS=NOT_ASSESSED
  PW_DICT_OBSERVED=""
  PW_DICT_REASON=""
  PW_DICT_MEANING=""

  if [ "${MYUID:-0}" != "0" ]; then
    PW_DICT_REASON="requires root"
  else
    PW_DICT_RAW=$(aix pw_dictionlist lssec -f /etc/security/user -s default -a dictionlist)
    PW_DICT_RC=$?
    if [ "$PW_DICT_RC" -ne 0 ]; then
      PW_DICT_REASON="capture failed (rc=$PW_DICT_RC)"
    elif [ -z "$PW_DICT_RAW" ]; then
      PW_DICT_REASON="capture empty (rc=0)"
    else
      PW_DICT_PARSED=$(printf '%s\n' "$PW_DICT_RAW" | awk '
        /^[[:space:]]*$/ { next }
        {
          rows++
          if ($0 !~ /^default dictionlist=/) {
            bad=1
            next
          }
          raw=$0
          sub(/^default dictionlist=/, "", raw)
          if (raw ~ /[[:space:]][A-Za-z][A-Za-z0-9_]*=/) {
            bad=1
            next
          }
          if (raw ~ /^"/) {
            if (raw !~ /^"[^"]*"$/) {
              bad=1
              next
            }
            value=substr(raw, 2)
            sub(/"$/, "", value)
          } else {
            if (raw ~ /"/) {
              bad=1
              next
            }
            value=raw
          }
        }
        END {
          if (rows != 1 || bad) {
            print "bad|"
          } else if (value == "") {
            print "empty|"
          } else if (value ~ /[[:space:][:cntrl:]]/) {
            print "invalid|" value
          } else {
            count=split(value, item, ",")
            invalid=0
            for (i=1; i<=count; i++) {
              if (item[i] == "" || substr(item[i], 1, 1) != "/") invalid=1
            }
            if (invalid) print "invalid|" value
            else print "pass|" value
          }
        }')
      PW_DICT_STATE=${PW_DICT_PARSED%%\|*}
      PW_DICT_VALUE=${PW_DICT_PARSED#*\|}
