        empty)
          PW_DICT_STATUS=FAIL
          PW_DICT_OBSERVED="dictionlist is unset"
          ;;
        invalid)
          PW_DICT_STATUS=FAIL
          PW_DICT_OBSERVED="dictionlist=$PW_DICT_VALUE (invalid absolute-path list)"
