# minalpha is the minimum number of alphabetic password characters. Trust
# only one exact attribute-scoped lssec assignment.

  typeset PW_MA_RAW PW_MA_RC PW_MA_NONBLANK PW_MA_LINE
  typeset PW_MA_VALUE PW_MA_DIGITS PW_MA_NORM
  typeset PW_MA_REASON PW_MA_FAILURE PW_MA_STATUS
