    PW_MA_RC=$?
    if [ "$PW_MA_RC" -ne 0 ]; then
      PW_MA_REASON="capture failed (rc=$PW_MA_RC)"
    elif [ -z "$PW_MA_RAW" ]; then
      PW_MA_REASON="capture returned empty output"
    else
      PW_MA_NONBLANK=$(printf '%s\n' "$PW_MA_RAW" |
        awk 'NF { count++ } END { print count + 0 }')
      if [ "$PW_MA_NONBLANK" -ne 1 ]; then
        PW_MA_REASON="output was not one exact assignment"
      else
        PW_MA_LINE=$(printf '%s\n' "$PW_MA_RAW" |
          awk 'NF { print; exit }')
