          if [ -z "$PW_MDG_VALUE" ]; then
            PW_MDG_STATUS=FAIL
            PW_MDG_OBSERVED="mindigit absent; documented AIX default 0 (no digit required)"
          else
            case "$PW_MDG_VALUE" in
              *[!0-9]*)
                PW_MDG_STATUS=NOT_ASSESSED
                PW_MDG_REASON="value was not a digits-only decimal"
                ;;
              *)
                PW_MDG_NORM=$PW_MDG_VALUE
                while [ "${#PW_MDG_NORM}" -gt 1 ] &&
                    [ "${PW_MDG_NORM#0}" != "$PW_MDG_NORM" ]; do
                  PW_MDG_NORM=${PW_MDG_NORM#0}
                done
                if [ "${#PW_MDG_NORM}" -gt 3 ] ||
                    [ "$PW_MDG_NORM" -gt 255 ]; then
                  PW_MDG_STATUS=FAIL
                  PW_MDG_OBSERVED="mindigit=$PW_MDG_VALUE (outside documented range 0..255)"
                elif [ "$PW_MDG_NORM" -ge 1 ]; then
