  typeset PW_NCK_RAW PW_NCK_RC PW_NCK_SCANNED PW_NCK_COUNT PW_NCK_USERS PW_NCK_TAIL
  typeset PW_NCK_STATUS PW_NCK_OBSERVED PW_NCK_REASON

