    PW_NCK_RC=$?
    if [ "$PW_NCK_RC" -ne 0 ]; then
      PW_NCK_STATUS=NOT_ASSESSED
      PW_NCK_REASON="scan failed (rc=$PW_NCK_RC)"
    else
      case "$PW_NCK_RAW" in
        *'
'*)
          PW_NCK_STATUS=NOT_ASSESSED
          PW_NCK_REASON="returned multiple lines"
          ;;
        "scanned="*" nocheck="*" users="*)
          PW_NCK_SCANNED=${PW_NCK_RAW#scanned=}
          PW_NCK_SCANNED=${PW_NCK_SCANNED%% *}
          PW_NCK_COUNT=${PW_NCK_RAW#*nocheck=}
