              PW_NCK_REASON="summary counters were not decimal"
              ;;
            *)
              if [ "$PW_NCK_SCANNED" -lt 1 ]; then
                PW_NCK_STATUS=NOT_ASSESSED
                PW_NCK_REASON="no stanzas parsed from /etc/security/passwd"
              elif [ "$PW_NCK_COUNT" -eq 0 ]; then
                PW_NCK_STATUS=PASS
                PW_NCK_OBSERVED="$PW_NCK_SCANNED stanza(s) scanned; no NOCHECK flag"
              else
                PW_NCK_TAIL=""
                [ "$PW_NCK_COUNT" -gt 6 ] && PW_NCK_TAIL=" (+$((PW_NCK_COUNT - 6)) more)"
                PW_NCK_STATUS=FAIL
                PW_NCK_OBSERVED="NOCHECK set for $PW_NCK_COUNT account(s): $PW_NCK_USERS$PW_NCK_TAIL"
