  # is usernames and counts only; hash material is never captured.
  typeset PW_SHH_RAW PW_SHH_RC PW_SHH_SCANNED PW_SHH_COUNT PW_SHH_USERS PW_SHH_TAIL
  typeset PW_SHH_STATUS PW_SHH_OBSERVED PW_SHH_REASON

