          PW_SHH_SCANNED=${PW_SHH_SCANNED%% *}
          PW_SHH_COUNT=${PW_SHH_RAW#*crypt=}
          PW_SHH_COUNT=${PW_SHH_COUNT%% *}
          PW_SHH_USERS=${PW_SHH_RAW#*users=}
