                PW_SHH_STATUS=NOT_ASSESSED
                PW_SHH_REASON="no stanzas parsed from /etc/security/passwd"
              elif [ "$PW_SHH_COUNT" -eq 0 ]; then
                PW_SHH_STATUS=PASS
                PW_SHH_OBSERVED="$PW_SHH_SCANNED stanza(s) scanned; no legacy crypt hash"
              else
                PW_SHH_TAIL=""
                [ "$PW_SHH_COUNT" -gt 6 ] && PW_SHH_TAIL=" (+$((PW_SHH_COUNT - 6)) more)"
                PW_SHH_STATUS=FAIL
                PW_SHH_OBSERVED="legacy crypt hash for $PW_SHH_COUNT account(s): $PW_SHH_USERS$PW_SHH_TAIL"
