          "cis-l1"
      ;;
    *)
      add security pw_stored_hash "Legacy crypt password hashes" NOT_ASSESSED high \
          "not assessed — crypt-hash scan $PW_SHH_REASON" \
          "PTxray could not scan /etc/security/passwd stored password hashes trustworthily." \
          "verify /etc/security/passwd is readable as root, resolve the evidence problem, and rerun." \
          "cis-l1"
      ;;
  esac
_AIXRAY_SESSION_KEYS=""

  # core_pathconf — persistent system-default core compression, path, location,
  # and naming. An insecure setting risks core files landing in the wrong
  # directory or overwriting existing diagnostics. This check is diagnostic
  # only: chcore appears in fix prose but is never invoked.
  typeset CORE_PC_RAW CORE_PC_RC CORE_PC_PARSED CORE_PC_SHAPE CORE_PC_TAB
  typeset _PC_COMPRESSION _PC_PATH _PC_LOCATION _PC_NAMING
  if [ "${MYUID:-0}" != "0" ]; then
    CORE_PC_RAW=""
    CORE_PC_RC=126
  else
    CORE_PC_RAW=$(aix core_pathconf lscore -d); CORE_PC_RC=$?
  fi
  if [ "$CORE_PC_RC" -ne 0 ]; then
    add security core_pathconf "Core file path and naming" NOT_ASSESSED med \
        "not assessed — lscore -d returned exit code $CORE_PC_RC" \
        "PTxray did not obtain one trustworthy complete set of default core path and naming fields." \
        "run 'lscore -d' with system authority, verify all four rows, and rerun PTxray." \
        ""
  else
    # Parse the four required rows. Output format: OK<TAB>X<TAB>X<TAB>X<TAB>X
    # where fields are: compression_val, path_val, location_val, naming_val.
    # Shape: exactly 4 non-blank rows, each of the 4 keys present exactly once,
    # compression is one token, path/naming in {on,off,default}, location non-empty.
    CORE_PC_PARSED=$(printf '%s\n' "$CORE_PC_RAW" | awk '
      BEGIN { FS=":" }
      NF {
        rows++
        if (NF != 2) {
          bad=1
          next
        }
        key=$1
        val=$2
        sub(/^[ \t]*/, "", key)
        sub(/[ \t]*$/, "", key)
        sub(/^[ \t]*/, "", val)
        sub(/[ \t]*$/, "", val)
        if (key == "compression") {
          comp_count++
          if (val == "" || val ~ /[ \t]/) bad=1
          else comp_val = val
        } else if (key == "path specification") {
          path_count++
          v = tolower(val)
          if (v != "on" && v != "off" && v != "default") bad=1
          else path_val = v
        } else if (key == "corefile location") {
          loc_count++
          if (val == "" || (val != "not set" && val ~ /[ \t]/)) bad=1
          else loc_val = val
        } else if (key == "naming specification") {
          name_count++
          v = tolower(val)
          if (v != "on" && v != "off" && v != "default") bad=1
          else name_val = v
        } else {
          bad=1
        }
      }
      END {
        ok = (rows == 4 && comp_count == 1 && path_count == 1 && loc_count == 1 && name_count == 1 && !bad)
        if (ok)
          printf "OK\t%s\t%s\t%s\t%s\n", comp_val, path_val, loc_val, name_val
        else
          print "BAD"
      }')
    CORE_PC_TAB=$(printf '\t')
    # The existing whitespace fence guarantees tabs cannot occur in values.
    # read consumes the record without shell field splitting or pathname expansion.
    IFS="$CORE_PC_TAB" read -r CORE_PC_SHAPE _PC_COMPRESSION _PC_PATH \
      _PC_LOCATION _PC_NAMING <<EOF
$CORE_PC_PARSED
EOF
    case "$CORE_PC_SHAPE" in
      BAD)
        add security core_pathconf "Core file path and naming" NOT_ASSESSED med \
            "not assessed — lscore -d output was unparseable (rc=0)" \
            "PTxray did not obtain one trustworthy complete set of default core path and naming fields." \
            "run 'lscore -d' with system authority, verify all four rows, and rerun PTxray." \
            ""
        ;;
      OK)
        # Decision: fail if path is off/default, location is default/relative/root, naming != on
        if [ "$_PC_PATH" = "off" ] || [ "$_PC_PATH" = "default" ]; then
          add security core_pathconf "Core file path and naming" FAIL med \
              "path specification $_PC_PATH; corefile location $_PC_LOCATION; naming specification $_PC_NAMING" \
              "AIX process core files are not fully controlled by both a dedicated absolute path and unique naming, risking misplaced or overwritten diagnostic evidence." \
              "configure persistent system defaults with 'chcore -p on -l /approved/core/path -n on -d' after choosing and protecting an appropriately sized directory; PTxray only recommends this command." \
              ""
        elif [ "$_PC_LOCATION" = "default" ] || [ "$_PC_LOCATION" = "/" ] || \
             [ -z "$_PC_LOCATION" ]; then
          add security core_pathconf "Core file path and naming" FAIL med \
              "path specification $_PC_PATH; corefile location $_PC_LOCATION; naming specification $_PC_NAMING" \
              "AIX process core files are not fully controlled by both a dedicated absolute path and unique naming, risking misplaced or overwritten diagnostic evidence." \
              "configure persistent system defaults with 'chcore -p on -l /approved/core/path -n on -d' after choosing and protecting an appropriately sized directory; PTxray only recommends this command." \
              ""
        else
          case "$_PC_LOCATION" in
            /*)
              # Absolute path — only / handled above, so this is safe
              if [ "$_PC_NAMING" = "on" ]; then
                add security core_pathconf "Core file path and naming" PASS med \
                    "path specification on; corefile location $_PC_LOCATION; naming specification on" \
                    "AIX directs process core files to one controlled absolute location and gives them unique names." \
                    "n/a" \
                    ""
              else
                add security core_pathconf "Core file path and naming" FAIL med \
                    "path specification $_PC_PATH; corefile location $_PC_LOCATION; naming specification $_PC_NAMING" \
                    "AIX process core files are not fully controlled by both a dedicated absolute path and unique naming, risking misplaced or overwritten diagnostic evidence." \
                    "configure persistent system defaults with 'chcore -p on -l /approved/core/path -n on -d' after choosing and protecting an appropriately sized directory; PTxray only recommends this command." \
                    ""
              fi
              ;;
            *)
              # Relative path (no leading /)
              add security core_pathconf "Core file path and naming" FAIL med \
                  "path specification $_PC_PATH; corefile location $_PC_LOCATION; naming specification $_PC_NAMING" \
                  "AIX process core files are not fully controlled by both a dedicated absolute path and unique naming, risking misplaced or overwritten diagnostic evidence." \
                  "configure persistent system defaults with 'chcore -p on -l /approved/core/path -n on -d' after choosing and protecting an appropriately sized directory; PTxray only recommends this command." \
                  ""
              ;;
          esac
        fi
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""
  # ssh_logingracetime — assess global effective seconds from `sshd -T`.
  typeset SSH_LGT_RAW SSH_LGT_CAPTURE_RC SSH_LGT_PARSED SSH_LGT_VALUE
  typeset SSH_LGT_STATUS SSH_LGT_OBSERVED SSH_LGT_MEANING SSH_LGT_FIX
  typeset SSH_LGT_REASON
  SSH_LGT_STATUS=NOT_ASSESSED
  SSH_LGT_OBSERVED=''
  SSH_LGT_MEANING='PTxray did not obtain one trustworthy global effective LoginGraceTime value, so it cannot establish the pre-authentication deadline.'
  SSH_LGT_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  SSH_LGT_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    SSH_LGT_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      SSH_LGT_RAW=$SSHT
      SSH_LGT_CAPTURE_RC=$SSHT_RC
    else
      SSH_LGT_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_LGT_CAPTURE_RC=$?
    fi
    if [ "$SSH_LGT_CAPTURE_RC" -ne 0 ]; then
      SSH_LGT_REASON="sshd -T failed (rc=$SSH_LGT_CAPTURE_RC)"
    elif [ -z "$SSH_LGT_RAW" ]; then
      SSH_LGT_REASON='sshd -T returned empty output'
    else
      SSH_LGT_PARSED=$(printf '%s\n' "$SSH_LGT_RAW" | awk '
        $1 == "logingracetime" {
          count++
          if (NF != 2 || $2 !~ /^(0|[1-9][0-9]*)$/) invalid=1
          else value=$2
        }
        END {
          if (count != 1) print "__COUNT__"
          else if (invalid) print "__INVALID__"
          else print value
        }')
      case "$SSH_LGT_PARSED" in
        __COUNT__)
          SSH_LGT_REASON='effective row is missing or duplicate'
          ;;
        __INVALID__)
          SSH_LGT_REASON='effective value is unparseable'
          ;;
        *)
          SSH_LGT_VALUE=$SSH_LGT_PARSED
          if [ "${#SSH_LGT_VALUE}" -le 2 ] &&
             [ "$SSH_LGT_VALUE" != 0 ] &&
             [ "$SSH_LGT_VALUE" -le 60 ]; then
            SSH_LGT_STATUS=PASS
            SSH_LGT_OBSERVED="LoginGraceTime $SSH_LGT_VALUE seconds"
            SSH_LGT_MEANING='sshd limits unauthenticated login time to a nonzero interval of no more than 60 seconds.'
            SSH_LGT_FIX='n/a'
          else
            SSH_LGT_STATUS=FAIL
            SSH_LGT_OBSERVED="LoginGraceTime $SSH_LGT_VALUE seconds"
            SSH_LGT_MEANING='The global effective SSH pre-authentication window is disabled or exceeds 60 seconds, leaving unauthenticated connections open too long.'
            SSH_LGT_FIX="set 'LoginGraceTime 60' or a lower nonzero duration in sshd_config, validate the global effective seconds with 'sshd -T', and restart sshd; PTxray only recommends these actions."
          fi
          ;;
      esac
    fi
  fi

  if [ "$SSH_LGT_STATUS" = NOT_ASSESSED ]; then
    SSH_LGT_OBSERVED="not assessed — LoginGraceTime $SSH_LGT_REASON"
  fi
  add security ssh_logingracetime "SSH login grace time" "$SSH_LGT_STATUS" med \
      "$SSH_LGT_OBSERVED" "$SSH_LGT_MEANING" "$SSH_LGT_FIX" ""
_AIXRAY_SESSION_KEYS=""

  # shell_timeout — ensure an idle-shell auto-logout timeout is bounded.
  # A positive TMOUT set in /etc/profile or /etc/environment forces the shell
  # to log out after N seconds of inactivity; without it, an abandoned session
  # remains open indefinitely. /etc/security/.profile is intentionally excluded:
  # it is a mkuser skeleton copied into new home directories, not a login-time
  # source, and its permissions also make the otherwise non-root check unreadable.
  typeset ST_RAW ST_RC ST_PARSED ST_STATE ST_DETAIL ST_VAL
  ST_RAW=$(aix profile_tmout grep -E 'TMOUT|TIMEOUT' /etc/profile /etc/environment); ST_RC=$?
  if [ "$ST_RC" -ge 2 ]; then
    add security shell_timeout "Idle-shell auto-logout timeout" \
        NOT_ASSESSED low \
        "not assessed — TMOUT/TIMEOUT capture failed (rc=$ST_RC)" \
        "Could not read TMOUT/TIMEOUT evidence from /etc/profile and /etc/environment, so idle-shell enforcement is unknown." \
        "restore read access to /etc/profile and /etc/environment, then rerun PTxray." "cis-l1"
  elif [ "$ST_RC" -eq 1 ]; then
    add security shell_timeout "Idle-shell auto-logout timeout" FAIL med \
        "no active TMOUT/TIMEOUT match (grep rc=1)" \
        "No idle-shell timeout is enforced; interactive shell sessions can remain open indefinitely." \
        "set TMOUT=900 (or less) in /etc/profile (for example, TMOUT=900; export TMOUT), make TMOUT readonly with the approved AIX shell syntax, then rerun PTxray." "cis-l1"
  else
    # A leading comment is not evidence; a shell-style trailing comment is
    # removed before the numeric shape check. Because assignments are
    # sequential and grep output across both files is not a trustworthy
    # effective-precedence model, PASS requires every active assignment to be
    # numeric, positive, and bounded. Values above 900 are classified without
    # feeding an arbitrarily large attacker-controlled integer into arithmetic.
    ST_PARSED=$(printf '%s\n' "$ST_RAW" | awk '
      function trim(value) {
        sub(/^[ \t]+/, "", value)
        sub(/[ \t]+$/, "", value)
        return value
      }
      function remember(value) {
        if (!seen_value[value]++) {
          if (values != "") values=values ", "
          values=values value
          distinct_values++
        }
      }
      {
        line=$0
        sub(/^[ \t]+/, "", line)
        # grep prefixes matches with a filename when both declared files are
        # read. Strip only those two trusted capture-source prefixes.
        sub(/^\/etc\/profile:/, "", line)
        sub(/^\/etc\/environment:/, "", line)
        sub(/^[ \t]+/, "", line)
        if (line ~ /^#/) next
        sub(/[ \t]+#.*/, "", line)
        line=trim(line)
        if (line == "") next
        low=tolower(line)

        if (low ~ /^unset[ \t]+/) {
          target=low
          sub(/^unset[ \t]+/, "", target)
          if (target ~ /^-v[ \t]+/) sub(/^-v[ \t]+/, "", target)
          target=trim(target)
          if (target == "tmout" || target == "timeout") {
            unsets++
          } else {
            invalid=1
          }
          next
        }

        if (low ~ /^export[ \t]+(tmout|timeout)[ \t]*$/) {
          exports++
          next
        }

        if (low ~ /^(export[ \t]+)?(tmout|timeout)[ \t]*=/) {
          assignments++
          work=low
          sub(/^export[ \t]+/, "", work)
          variable=work
          sub(/[ \t]*=.*/, "", variable)
          variable=trim(variable)
          sub(/^[^=]*=[ \t]*/, "", work)
          work=trim(work)

          separator=index(work, ";")
          if (separator > 0) {
            suffix=trim(substr(work, separator+1))
            work=trim(substr(work, 1, separator-1))
            sub(/[ \t]*;[ \t]*$/, "", suffix)
            suffix=trim(suffix)
            gsub(/[ \t]+/, " ", suffix)
            if (suffix != "export " variable) invalid=1
          }

          if (work !~ /^[0-9]+$/) {
            invalid=1
            next
          }
          canon=work
          sub(/^0+/, "", canon)
          if (canon == "") canon="0"
          remember(canon)
          next
        }

        if (low ~ /^readonly[ \t]+/) {
          # A readonly declaration assigns nothing, so it is compliance-neutral:
          # naming the timeout variables -- or any other variable -- must not
          # poison otherwise determinate evidence. A tmout/timeout=VALUE inside
          # the declaration is a real assignment and is classified exactly like a
          # plain one, with the same conflict tracking.
          work=low
          sub(/^readonly[ \t]+/, "", work)
          work=trim(work)
          if (work == "") next
          gsub(/[ \t,]+/, " ", work)
          tcount=split(work, tokens, " ")
          for (tidx=1; tidx<=tcount; tidx++) {
            token=tokens[tidx]
            if (token ~ /^(tmout|timeout)=/) {
              assignments++
              aval=token
              sub(/^[^=]*=[ \t]*/, "", aval)
              if (aval !~ /^[0-9]+$/) {
                invalid=1
                next
              }
              canon=aval
              sub(/^0+/, "", canon)
              if (canon == "") canon="0"
              remember(canon)
            }
          }
          next
        }

        invalid=1
      }
      END {
        if (invalid) {
          print "invalid|"
        } else if (assignments > 0 && unsets > 0) {
          print "assignment_unset_conflict|"
        } else if (distinct_values > 1) {
          print "value_conflict|" values
        } else if (unsets > 0) {
          print "unset|"
        } else if (assignments == 0) {
          print "empty|"
        } else if (values == "0") {
          print "zero|0"
        } else if (length("" values) > 3 ||
                   (length("" values) == 3 && values + 0 > 900)) {
          print "over|" values
        } else {
          print "safe|" values
        }
      }
    ')
    ST_STATE=${ST_PARSED%%\|*}
    ST_DETAIL=${ST_PARSED#*\|}
    case "$ST_STATE" in
      over)
        ST_VAL=$ST_DETAIL
        add security shell_timeout "Idle-shell auto-logout timeout" WARN low "${ST_VAL}s" \
            "TMOUT is set to ${ST_VAL} seconds, which exceeds the 900-second bounded-session cap." \
            "reduce TMOUT to 900 seconds or less in /etc/profile or /etc/environment." "cis-l1"
        ;;
      assignment_unset_conflict)
        add security shell_timeout "Idle-shell auto-logout timeout" NOT_ASSESSED low \
            "not assessed — TMOUT/TIMEOUT assignment conflicts with unset directive" \
            "PTxray observed both an assignment and an unset directive, but concatenated grep output from two files does not establish effective shell precedence." \
            "inspect active TMOUT/TIMEOUT directives in /etc/profile and /etc/environment, remove the conflict, and rerun PTxray." "cis-l1"
        ;;
      value_conflict)
        add security shell_timeout "Idle-shell auto-logout timeout" NOT_ASSESSED low \
            "not assessed — conflicting TMOUT/TIMEOUT assignments (values: $ST_DETAIL)" \
            "PTxray observed different timeout values, but concatenated grep output from two files does not establish which assignment is effective." \
            "converge /etc/profile and /etc/environment on one bounded value from 1 through 900, then rerun PTxray." "cis-l1"
        ;;
      invalid)
        add security shell_timeout "Idle-shell auto-logout timeout" NOT_ASSESSED low \
            "not assessed — TMOUT/TIMEOUT capture unparseable (rc=0)" \
            "PTxray did not obtain one active numeric TMOUT/TIMEOUT assignment, so it cannot claim an idle-shell timeout is enforced." \
            "inspect active TMOUT/TIMEOUT assignments in /etc/profile and /etc/environment, correct malformed or commented settings, and rerun PTxray." "cis-l1"
        ;;
      empty)
        add security shell_timeout "Idle-shell auto-logout timeout" FAIL med \
            "no active TMOUT/TIMEOUT directive in successful capture (rc=0)" \
            "No idle-shell timeout is enforced; interactive shell sessions can remain open indefinitely." \
            "set TMOUT=900 (or less) in /etc/profile (for example, TMOUT=900; export TMOUT), make TMOUT readonly with the approved AIX shell syntax, then rerun PTxray." "cis-l1"
        ;;
      unset)
        add security shell_timeout "Idle-shell auto-logout timeout" FAIL med \
            "TMOUT/TIMEOUT explicitly unset" \
            "An active unset directive removes the idle-shell timeout, so an abandoned session can remain open indefinitely." \
            "replace the unset directive with one bounded TMOUT assignment from 1 through 900." "cis-l1"
        ;;
      zero)
        add security shell_timeout "Idle-shell auto-logout timeout" FAIL med "0s" \
            "TMOUT is zero, so idle-shell auto-logout is disabled." \
            "set TMOUT to a value from 1 through 900 in /etc/profile or /etc/environment." "cis-l1"
        ;;
      safe)
        ST_VAL=$ST_DETAIL
        add security shell_timeout "Idle-shell auto-logout timeout" PASS med "${ST_VAL}s" \
            "An idle session auto-logs out after ${ST_VAL} seconds of inactivity." \
            "n/a" "cis-l1"
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""

  # ssh_clientalive — assess global effective idle-session timeout values.
  typeset CA_RAW CA_CAPTURE_RC CA_PARSED CAI_VAL CAM_VAL CA_MAX_COUNT
  typeset CA_STATUS CA_OBSERVED CA_MEANING CA_FIX CA_REASON CA_TOTAL
  CA_STATUS=NOT_ASSESSED
  CA_OBSERVED=''
  CA_MEANING='PTxray did not obtain one trustworthy global effective ClientAlive policy, so it cannot establish an idle-session timeout.'
  CA_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  CA_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    CA_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      CA_RAW=$SSHT
      CA_CAPTURE_RC=$SSHT_RC
    else
      CA_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      CA_CAPTURE_RC=$?
    fi
    if [ "$CA_CAPTURE_RC" -ne 0 ]; then
      CA_REASON="sshd -T failed (rc=$CA_CAPTURE_RC)"
    elif [ -z "$CA_RAW" ]; then
      CA_REASON='sshd -T returned empty output'
    else
      CA_PARSED=$(printf '%s\n' "$CA_RAW" | awk '
        $1 == "clientaliveinterval" {
          interval_count++
          if (NF != 2 || $2 !~ /^(0|[1-9][0-9]*)$/) invalid=1
          else interval=$2
        }
        $1 == "clientalivecountmax" {
          countmax_count++
          if (NF != 2 || $2 !~ /^(0|[1-9][0-9]*)$/) invalid=1
          else countmax=$2
        }
        END {
          if (interval_count != 1 || countmax_count != 1) print "__COUNT__"
          else if (invalid) print "__INVALID__"
          else print interval " " countmax
        }')
      case "$CA_PARSED" in
        __COUNT__)
          CA_REASON='effective rows are missing or duplicate'
          ;;
        __INVALID__)
          CA_REASON='effective value is unparseable'
          ;;
        *)
          CAI_VAL=${CA_PARSED%% *}
          CAM_VAL=${CA_PARSED##* }
          if [ "$CAI_VAL" = 0 ]; then
            CA_STATUS=FAIL
            CA_OBSERVED='ClientAliveInterval 0 (disabled)'
            CA_MEANING='ClientAliveInterval 0 disables idle-session timeout entirely — abandoned SSH sessions remain open indefinitely.'
            CA_FIX="set global 'ClientAliveInterval' and 'ClientAliveCountMax' values whose effective timeout is 900 seconds or less, validate them with 'sshd -T', and restart sshd; PTxray only recommends these actions."
          elif [ "${#CAI_VAL}" -le 3 ] && [ "$CAI_VAL" -le 900 ]; then
            CA_MAX_COUNT=$((900 / CAI_VAL - 1))
            if [ "${#CAM_VAL}" -le 3 ] &&
               [ "$CAM_VAL" -le "$CA_MAX_COUNT" ]; then
              CA_TOTAL=$((CAI_VAL * (CAM_VAL + 1)))
              CA_STATUS=PASS
              CA_OBSERVED="ClientAliveInterval $CAI_VAL, ClientAliveCountMax $CAM_VAL"
              CA_MEANING="SSH idle sessions are timed out within $CA_TOTAL seconds."
              CA_FIX='n/a'
            else
              CA_STATUS=WARN
              CA_OBSERVED="ClientAliveInterval $CAI_VAL, ClientAliveCountMax $CAM_VAL"
              CA_MEANING='The global effective ClientAlive values permit an idle timeout that exceeds the 900-second limit.'
              CA_FIX="reduce global 'ClientAliveInterval' and/or 'ClientAliveCountMax', validate the result with 'sshd -T', and restart sshd; PTxray only recommends these actions."
            fi
          else
            CA_STATUS=WARN
            CA_OBSERVED="ClientAliveInterval $CAI_VAL, ClientAliveCountMax $CAM_VAL"
            CA_MEANING='The global effective ClientAlive values permit an idle timeout that exceeds the 900-second limit.'
            CA_FIX="reduce global 'ClientAliveInterval' and/or 'ClientAliveCountMax', validate the result with 'sshd -T', and restart sshd; PTxray only recommends these actions."
          fi
          ;;
      esac
    fi
  fi

  if [ "$CA_STATUS" = NOT_ASSESSED ]; then
    CA_OBSERVED="not assessed — ClientAlive $CA_REASON"
  fi
  add security ssh_clientalive "SSH client alive timeout" "$CA_STATUS" med \
      "$CA_OBSERVED" "$CA_MEANING" "$CA_FIX" "cis-l1"

  # uid0_accounts
  UID0=$(aix passwd_uid0 awk -F: '$3==0 {print $1}' /etc/passwd)
  XTRA=$(printf '%s\n' "$UID0" | awk 'NF && $1!="root"{printf "%s%s",(n++?", ":""),$1}')
  if [ -n "$XTRA" ]; then
    add security uid0_accounts "UID 0 accounts" FAIL high "extra: $XTRA" \
        "More than one account has UID 0 — each one is effectively root, multiplying the attack surface." \
        "give each admin a unique non-zero UID and use su/sudo; remove or re-UID the extra accounts." "cis-l1 ffiec:II.C.7"
  else
    add security uid0_accounts "UID 0 accounts" PASS med "root only" \
        "root is the only UID 0 account." "n/a" "cis-l1 ffiec:II.C.7"
  fi

  # failed_logins (root-gated). The log is created on the FIRST failed login —
  # on a clean install it does not exist, and that absence is itself the answer.
  if [ "${MYUID:-0}" != "0" ]; then
    nr_warn security failed_logins "Failed login attempts" "the failed-login log" "who /etc/security/failedlogin"
  elif ! aix ls_failedlogin ls /etc/security/failedlogin >/dev/null; then
    add security failed_logins "Failed login attempts" PASS low "no log — 0 recorded" \
        "/etc/security/failedlogin does not exist, which means no failed login has ever been recorded here." "n/a"
  else
    N=$(aix failedlogin count_nonempty_lines who /etc/security/failedlogin); RC=$?
    if [ "$RC" -ne 0 ]; then
      add security failed_logins "Failed login attempts" NOT_ASSESSED med \
          "not assessed — failed-login count capture failed (rc=$RC)" \
          "The failed-login log exists, but its streamed count did not complete successfully; zero cannot be inferred from failed evidence." \
          "run 'who /etc/security/failedlogin | wc -l' manually, check that the log is readable, and rerun PTxray."
    else
      case "$N" in
        ''|0*|*[!0-9]*)
          add security failed_logins "Failed login attempts" NOT_ASSESSED med \
              "not assessed — failed-login count capture was empty or invalid" \
              "The failed-login log exists, but its streamed count was not a valid positive integer; zero cannot be inferred from empty or invalid evidence." \
              "run 'who /etc/security/failedlogin | wc -l' manually, check that the log is readable, and rerun PTxray."
          ;;
        *)
          # /etc/security/failedlogin is never auto-trimmed, so a large lifetime total is
          # near-universal and says little on its own — only a very high count is worth a WARN.
          if [ "$N" -gt 500 ]; then
            add security failed_logins "Failed login attempts" WARN med "$N recorded (lifetime total)" \
                "A high lifetime total of failed logins — someone has been knocking, whether a misconfigured app or a brute-force attempt. This log is never auto-trimmed, so review recency, not just the count." \
                "review recency ('who /etc/security/failedlogin | tail') and rotate the log; lock or investigate the source accounts/hosts."
          else
            add security failed_logins "Failed login attempts" PASS low "$N recorded" \
                "Failed-login volume is low." "n/a"
          fi
          ;;
      esac
    fi
  fi

_AIXRAY_SESSION_KEYS=""
# ck-login-herald
#
# CIS AIX 7 v1.2.0 section 4.7.1 requires a login banner (herald) to be
# configured in /etc/security/login.cfg. The herald displays before the
# login prompt and provides legal notice to users.
#
# "Configured" means the herald attribute is present and non-empty in the
# default stanza. An empty or absent herald is a finding regardless of
# content — CIS does not prescribe specific banner wording; the presence
# of any herald satisfies the requirement.

  typeset LOGIN_H_RAW LOGIN_H_RC LOGIN_H_NONBLANK LOGIN_H_LINE
  typeset LOGIN_H_VALUE LOGIN_H_STATUS LOGIN_H_REASON LOGIN_H_FAILURE
  LOGIN_H_RAW=""
  LOGIN_H_RC=126
  LOGIN_H_REASON=""
  LOGIN_H_FAILURE=""
  LOGIN_H_STATUS=""

  if [ "${MYUID:-0}" != "0" ]; then
    LOGIN_H_REASON="requires root privileges"
  else
    LOGIN_H_RAW=$(aix login_herald lssec -f /etc/security/login.cfg -s default -a herald)
    LOGIN_H_RC=$?
    if [ "$LOGIN_H_RC" -ne 0 ]; then
      LOGIN_H_REASON="capture failed (rc=$LOGIN_H_RC)"
    elif [ -z "$LOGIN_H_RAW" ]; then
      LOGIN_H_REASON="capture returned empty output"
    else
      LOGIN_H_NONBLANK=$(printf '%s\n' "$LOGIN_H_RAW" |
        awk 'NF { count++ } END { print count + 0 }')
      if [ "$LOGIN_H_NONBLANK" -ne 1 ]; then
        LOGIN_H_REASON="output was not one exact assignment"
      else
        LOGIN_H_LINE=$(printf '%s\n' "$LOGIN_H_RAW" |
          awk 'NF { print; exit }')
        case "$LOGIN_H_LINE" in
          "default herald="*)
            LOGIN_H_VALUE=${LOGIN_H_LINE#default herald=}
            # Strip surrounding double quotes if present
            case "$LOGIN_H_VALUE" in
              '"'*'"') LOGIN_H_VALUE=${LOGIN_H_VALUE#\"}; LOGIN_H_VALUE=${LOGIN_H_VALUE%\"};;
            esac
            # Treat whitespace-only as absent
            LOGIN_H_NONBLANK=$(printf '%s' "$LOGIN_H_VALUE" | awk 'NF { c++ } END { print c+0 }')
            if [ -z "$LOGIN_H_VALUE" ] || [ "$LOGIN_H_NONBLANK" -eq 0 ]; then
              LOGIN_H_FAILURE="herald absent; not configured in login.cfg default stanza"
              LOGIN_H_STATUS=FAIL
            else
              LOGIN_H_STATUS=PASS
            fi
            ;;
          *)
            LOGIN_H_REASON="output did not contain the exact requested assignment"
            ;;
        esac
      fi
    fi
  fi

  if [ -n "$LOGIN_H_REASON" ]; then
    add security login_herald "Login banner" NOT_ASSESSED med \
        "not assessed — herald $LOGIN_H_REASON" \
        "PTxray did not obtain one trustworthy herald value." \
        "inspect the default herald attribute with lssec as root, correct capture ambiguity, and rerun PTxray." \
        "cis-l1"
  elif [ "$LOGIN_H_STATUS" = "PASS" ]; then
    add security login_herald "Login banner" PASS med \
        "herald is configured" \
