    LOGIN_LR_REASON="requires root privileges"
  else
    LOGIN_LR_RAW=$(aix login_loginreenable lssec -f /etc/security/login.cfg -s default -a loginreenable)
    LOGIN_LR_RC=$?
    if [ "$LOGIN_LR_RC" -ne 0 ]; then
      LOGIN_LR_REASON="capture failed (rc=$LOGIN_LR_RC)"
    elif [ -z "$LOGIN_LR_RAW" ]; then
      LOGIN_LR_REASON="capture returned empty output"
    else
      LOGIN_LR_NONBLANK=$(printf '%s\n' "$LOGIN_LR_RAW" |
        awk 'NF { count++ } END { print count + 0 }')
      if [ "$LOGIN_LR_NONBLANK" -ne 1 ]; then
        LOGIN_LR_REASON="output was not one exact assignment"
      else
        LOGIN_LR_LINE=$(printf '%s\n' "$LOGIN_LR_RAW" |
          awk 'NF { print; exit }')
        case "$LOGIN_LR_LINE" in
          "default loginreenable="*)
            LOGIN_LR_VALUE=${LOGIN_LR_LINE#default loginreenable=}
            case "$LOGIN_LR_VALUE" in
              "")
                LOGIN_LR_FAILURE="loginreenable absent; AIX default 0 (no automatic unlock); CIS requires >=360 minutes"
                LOGIN_LR_STATUS=FAIL
                ;;
              -[0-9]*)
                LOGIN_LR_DIGITS=${LOGIN_LR_VALUE#-}
                case "$LOGIN_LR_DIGITS" in
                  ""|*[!0-9]*)
                    LOGIN_LR_REASON="value was not a signed decimal integer"
                    ;;
                  *)
                    LOGIN_LR_FAILURE="loginreenable=$LOGIN_LR_VALUE minutes (below the required positive minimum)"
                    LOGIN_LR_STATUS=FAIL
                    ;;
                esac
                ;;
              [0-9]*)
                case "$LOGIN_LR_VALUE" in
                  *[!0-9]*)
                    LOGIN_LR_REASON="value was not a signed decimal integer"
                    ;;
                  *)
                    LOGIN_LR_NORM=$LOGIN_LR_VALUE
                    while [ "${LOGIN_LR_NORM#0}" != "$LOGIN_LR_NORM" ]; do
                      LOGIN_LR_NORM=${LOGIN_LR_NORM#0}
                    done
                    [ -n "$LOGIN_LR_NORM" ] || LOGIN_LR_NORM=0
                    LOGIN_LR_LEN=${#LOGIN_LR_NORM}
                    if [ "$LOGIN_LR_LEN" -gt 3 ] ||
                       { [ "$LOGIN_LR_LEN" -eq 3 ] &&
                         [ "$LOGIN_LR_NORM" -ge 360 ]; }; then
                      LOGIN_LR_STATUS=PASS
                    else
                      LOGIN_LR_FAILURE="loginreenable=$LOGIN_LR_VALUE minutes (below 360-minute minimum)"
                      LOGIN_LR_STATUS=FAIL
                    fi
                    ;;
                esac
                ;;
              *)
                LOGIN_LR_REASON="value was not a signed decimal integer"
                ;;
            esac
            ;;
          *)
            LOGIN_LR_REASON="output did not contain the exact requested assignment"
            ;;
        esac
      fi
    fi
  fi

  if [ -n "$LOGIN_LR_REASON" ]; then
    add security login_loginreenable "Terminal automatic re-enable delay" NOT_ASSESSED med \
        "not assessed — loginreenable $LOGIN_LR_REASON" \
        "PTxray did not obtain one trustworthy numeric loginreenable value or a proved absent assignment." \
        "inspect the default loginreenable attribute with lssec as root, correct capture ambiguity, and rerun PTxray." \
        ""
  elif [ "$LOGIN_LR_STATUS" = "PASS" ]; then
    add security login_loginreenable "Terminal automatic re-enable delay" PASS med \
        "loginreenable=$LOGIN_LR_VALUE minutes" \
        "Automatically unlocked TTY ports remain locked for at least 360 minutes." \
        "n/a" ""
  else
    add security login_loginreenable "Terminal automatic re-enable delay" FAIL med \
        "$LOGIN_LR_FAILURE" \
        "The default TTY automatic re-enable setting does not contain the CIS-required positive delay of at least 360 minutes." \
        "set the default loginreenable attribute to an integer of at least 360 after validating console recovery procedures; PTxray only recommends this change." \
        ""
  fi
_AIXRAY_SESSION_KEYS=""
# Owning monolith capture; later checks reuse this normalized inventory.
  typeset CIS_SERVICES_PARSE_RC
  CIS_SERVICES_RAW=$(aix cis_services_lssrc_a lssrc -a)
  CIS_SERVICES_RC=$?
  CIS_SERVICES_ROWS=""
  CIS_SERVICES_REASON=""
  CIS_SERVICES_READY=0

  if [ "$CIS_SERVICES_RC" -ne 0 ]; then
    CIS_SERVICES_REASON="capture failed (rc=$CIS_SERVICES_RC)"
  elif [ -z "$CIS_SERVICES_RAW" ]; then
    CIS_SERVICES_REASON="capture returned empty output"
  else
    CIS_SERVICES_ROWS=$(printf '%s\n' "$CIS_SERVICES_RAW" | awk '
      NR == 1 {
        if (NF != 4 || $1 != "Subsystem" || $2 != "Group" ||
            $3 != "PID" || $4 != "Status") bad = 1
        next
      }
      # The Group column is OPTIONAL. `lssrc -a` on stock AIX emits group-less
      # subsystems -- aso, pfcdaemon, pmperfrec are present on both 7.2 and 7.3 --
      # so rows legitimately arrive with 2, 3 or 4 fields:
      #   name group pid active | name pid active | name group inoperative | name inoperative
      # Keying on a fixed field count rejected 9 of 74 real rows and, because this
      # parser fails closed, took the whole SRC inventory down with it. That made
      # CIS_SERVICES_READY=0 and refused 13 CIS controls (4.3.1.x/4.3.2.x) on every
      # real box, while the hand-authored fixture -- which happened to give every
      # subsystem a group -- parsed cleanly. Read positionally from the RIGHT, where
      # the layout is stable, and keep the shape strict so garbage still refuses.
      # Status vocabulary (R6.2): /usr/include/spc.h (the "Valid SRC status
      # ids" block, read on the AIX 7.2 lab LPAR, 2026-08-11) closes the
      # documented code set at 16. Only active, stopping and starting are
      # classified in_use here: active and stopping have been observed in
      # real subsystem rows holding a numeric PID, and starting is the
      # documented start-side twin of stopping in the same lifecycle. All
      # three are in_use for the CIS 4.3.1.x/4.3.2.x "ensure the service is
      # not in use" controls: a daemon that is starting or stopping is still
      # a running process in the scan window, and SRC itself refuses to start
      # a `stopping` subsystem with 0513-029 "already active". `inoperative`
      # is the only documented no-process rest state ever observed and stays
      # not_in_use. Every other token still discards the whole inventory: the
      # remaining documented codes have never been observed in a subsystem
      # row (several are multi-word and cannot survive this
      # whitespace-tokenized table), so classifying them would mean guessing
      # a shape never seen, and an inventory holding an unrecognised status
      # is not trustworthy evidence. No consumer may be handed a fabricated
      # PASS.
      NF {
        rows++
        name = $1
        state = $NF
        running = (state == "active" || state == "stopping" || state == "starting")
        if (running) {
          # a running or transitional subsystem always reports a numeric PID
          # immediately before its status word
          if (NF < 3 || $(NF - 1) !~ /^[0-9][0-9]*$/) bad = 1
        } else if (state == "inoperative") {
          if (NF < 2 || NF > 3) bad = 1
        } else bad = 1
        if (!bad) {
          if (running) normalized = "in_use"
          else normalized = "not_in_use"
          print name "|" normalized
        }
      }
      END { if (rows == 0 || bad) exit 1 }
    ')
    CIS_SERVICES_PARSE_RC=$?
    if [ "$CIS_SERVICES_PARSE_RC" -ne 0 ]; then
      CIS_SERVICES_ROWS=""
      CIS_SERVICES_REASON="capture was unparseable"
    else
      CIS_SERVICES_READY=1
    fi
  fi

  typeset WRITESRV_MATCH WRITESRV_COUNT WRITESRV_STATE
  if [ "$CIS_SERVICES_READY" -ne 1 ]; then
    add security writesrv "writesrv service" NOT_ASSESSED low \
        "not assessed - writesrv SRC inventory $CIS_SERVICES_REASON" \
        "PTxray did not obtain one trustworthy complete SRC inventory." \
        "make 'lssrc -a' return a complete readable inventory, then rerun PTxray." \
        "cis-l1"
  else
    WRITESRV_MATCH=$(printf '%s\n' "$CIS_SERVICES_ROWS" | awk -F'|' '$1=="writesrv"{print $2}')
    WRITESRV_COUNT=$(printf '%s\n' "$WRITESRV_MATCH" | awk 'NF{n++} END{print n+0}')
    if [ "$WRITESRV_COUNT" -gt 1 ]; then
      add security writesrv "writesrv service" NOT_ASSESSED low \
          "not assessed - writesrv has duplicate SRC inventory rows" \
          "PTxray obtained contradictory or duplicated evidence for the writesrv subsystem." \
          "inspect 'lssrc -a' output for duplicate writesrv rows, then rerun PTxray." \
          "cis-l1"
    elif [ "$WRITESRV_COUNT" -eq 0 ]; then
      add security writesrv "writesrv service" PASS low \
          "writesrv not defined in the complete SRC inventory" \
          "The writesrv subsystem is absent and therefore is not in use." "n/a" "cis-l1"
    else
      WRITESRV_STATE=$WRITESRV_MATCH
      if [ "$WRITESRV_STATE" = in_use ]; then
        add security writesrv "writesrv service" FAIL high \
            "writesrv active in the SRC inventory" \
            "The writesrv subsystem is active and adds avoidable service exposure." \
            "after service-owner approval, stop writesrv and disable its startup; PTxray only recommends these actions." \
            "cis-l1"
      else
        add security writesrv "writesrv service" PASS low \
            "writesrv inoperative in the SRC inventory" \
            "The writesrv subsystem is present but not in use." "n/a" "cis-l1"
      fi
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  typeset DT_MATCH DT_MATCH_RC DT_COUNT DT_STATE
  if [ "${CIS_SERVICES_RC:-1}" -ne 0 ] || [ "$CIS_SERVICES_READY" -ne 1 ]; then
    add security dt "dt service" NOT_ASSESSED low \
        "not assessed - dt SRC inventory $CIS_SERVICES_REASON" \
