      SNAPP_SEVERITY=low
      SNAPP_OBSERVED="not assessed - lslpp -qcL $CIS_PACKAGE_REASON"
      SNAPP_MEANING="Malformed inventory rows prevent a trustworthy absence result."
      SNAPP_FIX="capture complete, parseable 'lslpp -qcL' output and rerun PTxray."
    else
      SNAPP_STATUS=PASS
      SNAPP_SEVERITY=low
      SNAPP_OBSERVED="bos.net.snapp not installed"
      SNAPP_MEANING="The snapp fileset is absent from the installed-software inventory."
      SNAPP_FIX="n/a"
    fi
  fi

  add security snapp_installed "snapp package presence" \
    "$SNAPP_STATUS" "$SNAPP_SEVERITY" "$SNAPP_OBSERVED" \
    "$SNAPP_MEANING" "$SNAPP_FIX" "cis-l1"
