_AIXRAY_SESSION_KEYS=""
# Owning monolith capture; later rc.tcpip checks reuse this normalized boot inventory.
# See tools.d/capture/cap-cis-rctcpip/run.ksh for the standalone-tool copy.
  typeset RCTCPIP_PARSE_RC
  RCTCPIP_RAW=$(aix cis_rctcpip cat /etc/rc.tcpip)
  RCTCPIP_RC=$?
  RCTCPIP_ROWS=""
  RCTCPIP_REASON=""
  RCTCPIP_READY=0

  if [ "$RCTCPIP_RC" -ne 0 ]; then
    RCTCPIP_REASON="capture failed (rc=$RCTCPIP_RC)"
  elif [ -z "$RCTCPIP_RAW" ]; then
    RCTCPIP_REASON="capture returned empty output"
  else
    case "$RCTCPIP_RAW" in
      *tcpip*)
        RCTCPIP_ROWS=$(printf '%s\n' "$RCTCPIP_RAW" | awk '
          {
            line = $0
            sub(/^[ \t]+/, "", line)
            if (line == "" || line ~ /^#/) next
            n = split(line, w, /[ \t]+/)
            for (i = 1; i < n; i++) {
              if (w[i] == "start" && w[i + 1] ~ /^\//) {
                m = split(w[i + 1], seg, "/")
                if (seg[m] != "") print seg[m] "|boot_start"
              }
            }
          }')
        RCTCPIP_PARSE_RC=$?
        if [ "$RCTCPIP_PARSE_RC" -ne 0 ]; then
          RCTCPIP_ROWS=""
          RCTCPIP_REASON="capture was unparseable"
        else
          RCTCPIP_READY=1
        fi
        ;;
      *)
        RCTCPIP_REASON="capture does not look like /etc/rc.tcpip"
        ;;
    esac
  fi

  # rctcpip_dhcpcd — CIS IBM AIX 7 v1.2.0 4.3.2.2: dhcp client services (dhcpcd,
  # dhcpcd6) must not be in use. In use = uncommented rc.tcpip start OR active SRC
  # subsystem; either trustworthy side alone is sufficient to FAIL, a clean PASS
  # needs both sides trustworthy.
  typeset RT_DHCPCD_BOOT RT_DHCPCD_SRC RT_DHCPCD_DETAIL
  typeset RT_DHCPCD_STATUS RT_DHCPCD_SEV RT_DHCPCD_OBS RT_DHCPCD_MEAN RT_DHCPCD_FIX
  if [ "${RCTCPIP_READY:-0}" -eq 1 ]; then
    RT_DHCPCD_BOOT=$(printf '%s\n' "$RCTCPIP_ROWS" | awk -F'|' '
      $1 == "dhcpcd" || $1 == "dhcpcd6" { found = 1 }
      END { if (found) print "boot"; else print "no-boot" }')
  else
    RT_DHCPCD_BOOT=unknown
  fi
  if [ "${CIS_SERVICES_READY:-0}" -eq 1 ]; then
    RT_DHCPCD_SRC=$(printf '%s\n' "$CIS_SERVICES_ROWS" | awk -F'|' '
      $1 == "dhcpcd" || $1 == "dhcpcd6" { n++; if ($2 == "in_use") active = 1 }
      END {
        if (n > 2) print "duplicate"
        else if (active) print "in_use"
        else if (n > 0) print "not_in_use"
        else print "absent"
      }')
  else
    RT_DHCPCD_SRC=unknown
  fi

  RT_DHCPCD_DETAIL=""
  [ "$RT_DHCPCD_BOOT" = boot ] && RT_DHCPCD_DETAIL="starts at boot in /etc/rc.tcpip"
  if [ "$RT_DHCPCD_SRC" = in_use ]; then
    if [ -n "$RT_DHCPCD_DETAIL" ]; then
      RT_DHCPCD_DETAIL="$RT_DHCPCD_DETAIL and is active in the SRC inventory"
    else
      RT_DHCPCD_DETAIL="is active in the SRC inventory"
    fi
  fi

  if [ -n "$RT_DHCPCD_DETAIL" ]; then
    RT_DHCPCD_STATUS=FAIL
    RT_DHCPCD_SEV=high
    RT_DHCPCD_OBS="dhcp client (dhcpcd/dhcpcd6) $RT_DHCPCD_DETAIL"
    RT_DHCPCD_MEAN="A dhcp client daemon is in use; a statically addressed server should not accept dynamic address configuration."
    RT_DHCPCD_FIX="after service-owner approval, disable the boot entry ('chrctcp -d dhcpcd', 'chrctcp -d dhcpcd6') and stop the subsystem ('stopsrc -s dhcpcd', 'stopsrc -s dhcpcd6'); PTxray only recommends these actions."
  elif [ "$RT_DHCPCD_BOOT" = unknown ] || [ "$RT_DHCPCD_SRC" = unknown ] || [ "$RT_DHCPCD_SRC" = duplicate ]; then
    RT_DHCPCD_STATUS=NOT_ASSESSED
    RT_DHCPCD_SEV=low
    if [ "$RT_DHCPCD_SRC" = duplicate ]; then
      RT_DHCPCD_OBS="not assessed - dhcpcd has duplicate SRC inventory rows"
    elif [ "$RT_DHCPCD_BOOT" = unknown ]; then
      RT_DHCPCD_OBS="not assessed - dhcpcd rc.tcpip evidence $RCTCPIP_REASON"
    else
      RT_DHCPCD_OBS="not assessed - dhcpcd SRC inventory $CIS_SERVICES_REASON"
    fi
    RT_DHCPCD_MEAN="PTxray did not obtain trustworthy service evidence from both /etc/rc.tcpip and the SRC inventory."
    RT_DHCPCD_FIX="make /etc/rc.tcpip readable and 'lssrc -a' return one complete inventory, then rerun PTxray."
  else
    RT_DHCPCD_STATUS=PASS
    RT_DHCPCD_SEV=low
    RT_DHCPCD_OBS="dhcp client (dhcpcd/dhcpcd6) not started in /etc/rc.tcpip and not active in the SRC inventory"
    RT_DHCPCD_MEAN="The dhcp client service is not in use."
    RT_DHCPCD_FIX="n/a"
  fi

  add security rctcpip_dhcpcd "dhcp client service" \
    "$RT_DHCPCD_STATUS" "$RT_DHCPCD_SEV" \
    "$RT_DHCPCD_OBS" \
    "$RT_DHCPCD_MEAN" \
    "$RT_DHCPCD_FIX" \
    "cis-l1"
