    [ "$RT_TIMED_BOOT_RC" -ne 0 ] && RT_TIMED_BOOT=unknown
  else
    RT_TIMED_BOOT=unknown
  fi
  if [ "${CIS_SERVICES_READY:-0}" -eq 1 ]; then
    RT_TIMED_SRC=$(printf '%s\n' "$CIS_SERVICES_ROWS" | awk -F'|' '
      $1 == "timed" { n++; if ($2 == "in_use") active = 1 }
      END {
        if (n > 1) print "duplicate"
        else if (active) print "in_use"
        else if (n > 0) print "not_in_use"
        else print "absent"
