  fi

  RT_TIMED_DETAIL=""
  [ "$RT_TIMED_BOOT" = boot ] && RT_TIMED_DETAIL="starts at boot in /etc/rc.tcpip"
  if [ "$RT_TIMED_SRC" = in_use ]; then
    if [ -n "$RT_TIMED_DETAIL" ]; then
      RT_TIMED_DETAIL="$RT_TIMED_DETAIL and is active in the SRC inventory"
    else
