  add security rctcpip_timed "timed service" \
    "$RT_TIMED_STATUS" "$RT_TIMED_SEV" \
    "$RT_TIMED_OBS" \
    "$RT_TIMED_MEAN" \
    "$RT_TIMED_FIX" \
