    NCM_PARSE=$(printf '%s\n' "$NCM_RAW" | awk '
      function finish_stanza() {
        if (stanza == "") return
        if (vfs ~ /^nfs[234]?$/) print "NFS\t" stanza
      }
      {
        line=$0
        # /etc/filesystems is an AIX stanza file and comments it with * , not # .
        # Every real box opens the file with the IBM prolog, whose lines all begin
        # with * ; treating them as unparseable took the whole inventory down. The
        # * is read positionally -- comment only as the first non-blank character
        # -- so a * inside an attribute value is still parsed literally.
        if (line ~ /^[ \t]*\*/) next
        sub(/[ \t]*#.*/, "", line)
        if (line ~ /^[ \t]*$/) next
        if (line ~ /^[^ \t:][^:]*:[ \t]*$/) {
          finish_stanza()
          stanza=line
          sub(/:[ \t]*$/, "", stanza)
          vfs=""
