_AIXRAY_SESSION_KEYS=""
  # nfs_client_mount_options — require both nosuid and nodev on NFS stanzas.
  typeset NCO_EXISTS_RC NCO_RAW NCO_RC NCO_PARSE NCO_PARSE_RC
  typeset NCO_TOTAL NCO_FAIL_COUNT NCO_FAILURES NCO_OBS

