  NCO_RAW=$ETC_FILESYSTEMS_RAW
  NCO_RC=$ETC_FILESYSTEMS_RC

  if [ "$NCO_RC" -ne 0 ]; then
    if [ "$NCO_EXISTS_RC" -eq 1 ]; then
      add security nfs_client_mount_options "NFS client mount options" PASS high \
          "/etc/filesystems is absent; no NFS client mount requires option assessment" \
          "No NFS client mount definition exists in the absent configuration file." \
          "n/a" "cis-l1"
    elif [ "$NCO_EXISTS_RC" -eq 0 ]; then
      add security nfs_client_mount_options "NFS client mount options" NOT_ASSESSED high \
          "not assessed - /etc/filesystems read failed (exit=$NCO_RC)" \
