      function finish_stanza(    count,item,i,has_nosuid,has_nodev,missing) {
        if (stanza == "" || vfs !~ /^nfs[234]?$/) return
        total++
        count=split(options, item, /[ \t,]+/)
        has_nosuid=0
        has_nodev=0
        for (i=1; i<=count; i++) {
          if (tolower(item[i]) == "nosuid") has_nosuid=1
          if (tolower(item[i]) == "nodev") has_nodev=1
        }
        if (has_nosuid && has_nodev) {
          print "PASS\t" stanza
        } else {
          missing=""
          if (!has_nosuid) missing="nosuid"
          if (!has_nodev) missing=missing (missing == "" ? "" : ",") "nodev"
          print "FAIL\t" stanza "\tmissing " missing
        }
      }
      {
        line=$0
        # /etc/filesystems is an AIX stanza file and comments it with * , not # .
        # Every real box opens the file with the IBM prolog, whose lines all begin
        # with * ; treating them as unparseable took the whole inventory down. The
        # * is read positionally -- comment only as the first non-blank character
        # -- so a * inside an attribute value is still parsed literally.
        if (line ~ /^[ \t]*\*/) next
        sub(/[ \t]*#.*/, "", line)
        if (line ~ /^[ \t]*$/) next
        if (line ~ /^[^ \t:][^:]*:[ \t]*$/) {
          finish_stanza()
          stanza=line
          sub(/:[ \t]*$/, "", stanza)
          vfs=""
          options=""
