        text=line
        sub(/^[ \t]+/, "", text)
        key=text
        sub(/[ \t]*=.*/, "", key)
        value=text
        sub(/^[^=]*=[ \t]*/, "", value)
        sub(/[ \t]+$/, "", value)
        key=tolower(key)
        if (key == "vfs") {
          value=tolower(value)
          if (vfs != "" && vfs != value) bad=1
          vfs=value
        } else if (key == "options") {
          value=tolower(value)
          if (options != "" && options != value) bad=1
          options=value
        }
      }
      END {
        finish_stanza()
        if (bad) exit 1
      }
