_AIXRAY_SESSION_KEYS=""
  # nfs_localhost_aliases — ensure localhost aliases do not exist in /etc/exports.
  # Reuses the etc_exports capture already collected by ck-nfs-exports (nfs_exports).
  # All reads are fixture-routed and side-effect free.
  typeset NFS_LA_CONFIG_EXISTS_OUT NFS_LA_CONFIG_EXISTS_RC
  typeset NFS_LA_CONFIG NFS_LA_CONFIG_RC
  typeset NFS_LA_LOCALHOST_COUNT NFS_LA_LOCALHOST_EVIDENCE

  # test -e also returns 1 for some stat failures (for example an inaccessible
  # parent or dangling symlink).
  NFS_LA_CONFIG_EXISTS_OUT=$(aix etc_exports_exists test -e /etc/exports)
  NFS_LA_CONFIG_EXISTS_RC=$?
  NFS_LA_CONFIG=$(aix etc_exports cat /etc/exports); NFS_LA_CONFIG_RC=$?

  if [ "$NFS_LA_CONFIG_RC" -ne 0 ]; then
    if [ "$NFS_LA_CONFIG_EXISTS_RC" -eq 1 ]; then
      # /etc/exports absent — PASS (no exports to abuse)
      add security nfs_localhost_aliases "NFS localhost aliases" PASS high \
          "this host has no /etc/exports definition file" \
          "No /etc/exports definition file exists; without an export configuration there is nothing for localhost aliases to abuse." \
          "n/a" "cis-l1"
    elif [ "$NFS_LA_CONFIG_EXISTS_RC" -eq 0 ]; then
      add security nfs_localhost_aliases "NFS localhost aliases" NOT_ASSESSED high \
          "not assessed — /etc/exports read failed (rc=$NFS_LA_CONFIG_RC)" \
          "The existing export configuration is unreadable, so the absence of localhost aliases could not be assessed." \
          "restore read access to /etc/exports and re-run PTxray." "cis-l1"
    else
      add security nfs_localhost_aliases "NFS localhost aliases" NOT_ASSESSED high \
          "not assessed — /etc/exports existence and read state could not be established (existence rc=$NFS_LA_CONFIG_EXISTS_RC; read rc=$NFS_LA_CONFIG_RC)" \
          "PTxray could not distinguish an absent file from unreadable configuration." \
          "verify that /etc/exports exists and is readable, then re-run PTxray." "cis-l1"
    fi
  else
    # Extract uncommented lines and scan for localhost aliases (localhost, 127.0.0.1, ::1)
    # appearing as client designators. A comment line (first non-whitespace char is #) is
    # ignored. Within a valid export line, scan the uncommented text for aliases as whole
    # tokens or within comma-separated lists.
    NFS_LA_LOCALHOST_EVIDENCE=$(printf '%s\n' "$NFS_LA_CONFIG" | awk '
      {
        raw = $0
        text = $0
        # Strip comments
        sub(/[ \t]*#.*/, "", text)
        # Skip blank lines
        if (text ~ /^[ \t]*$/) next
        # Skip comment-only lines
        sub(/^[ \t]*/, "", text)
        if (text ~ /^#/) next
        # Search for localhost aliases in the uncommented remainder.
        # Check for ::1 (IPv6 loopback) as a substring bounded by
        # non-hex-non-colon characters.
        # Then split on commas, colons, and whitespace (client-list
        # delimiters in NFS exports) and check each fragment for
        # "localhost" and "127.0.0.1".
        found = 0
        if (text ~ /(^|[^0-9a-fA-F:])::1($|[^0-9a-fA-F]|:)/) {
          found = 1
        } else {
          n = split(text, frags, /[:, \t]+/)
          for (i = 1; i <= n; i++) {
            f = frags[i]
            if (f == "localhost" || f == "127.0.0.1") { found = 1; break }
            # Also check option=value pairs like access=localhost
            if (f ~ /^access=/) {
              v = substr(f, 8)
              if (v == "localhost" || v == "127.0.0.1") { found = 1; break }
            }
            if (f ~ /^root=/) {
              v = substr(f, 6)
              if (v == "localhost" || v == "127.0.0.1") { found = 1; break }
            }
            if (f ~ /^anon=/) {
              v = substr(f, 6)
              if (v == "localhost" || v == "127.0.0.1") { found = 1; break }
            }
          }
        }
        if (found) print raw
      }
    ')
    NFS_LA_LOCALHOST_COUNT=$(printf '%s\n' "$NFS_LA_LOCALHOST_EVIDENCE" \
      | awk 'NF {n++} END {print n+0}')

    if [ "$NFS_LA_LOCALHOST_COUNT" -gt 0 ]; then
      add security nfs_localhost_aliases "NFS localhost aliases" FAIL high "$NFS_LA_LOCALHOST_EVIDENCE" \
          "One or more NFS export definitions include a localhost alias (localhost, 127.0.0.1, ::1) as a client designator." \
          "remove every localhost alias from the client list in /etc/exports; only explicitly named trusted hosts or IP addresses should be used as NFS clients." "cis-l1"
    else
      add security nfs_localhost_aliases "NFS localhost aliases" PASS high \
          "no localhost alias found in /etc/exports" \
          "/etc/exports is present and no uncommented line contains a localhost alias as a client designator." \
          "n/a" "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # inetd_bootps — detect whether the legacy bootps service is active in
  # /etc/inetd.conf.  An active bootps entry exposes a clear-text service
  # that can be abused for amplification or as a foothold; CIS requires it
  # disabled.  Capture: grep for the exact first-field token bootps followed
  # by whitespace (not a comment, not bootpsd, not a later-field match).
  #
  # Verdict logic:
  #   rc=0  AND  every nonblank row starts with exactly "bootps "  => FAIL
  #   rc=1  AND  empty output                                       => PASS
  #   anything else                                                 => NOT_ASSESSED
  #
  typeset ID_BOOTPS_RC ID_BOOTPS_RAW ID_BOOTPS_PARSED ID_BOOTPS_SHAPE
  typeset ID_BOOTPS_STATUS ID_BOOTPS_OBSERVED ID_BOOTPS_MEANING
  typeset ID_BOOTPS_FIX SEVERITY
  ID_BOOTPS_RC=0
  ID_BOOTPS_RAW=""
  ID_BOOTPS_PARSED="absent"
  ID_BOOTPS_SHAPE=1

  ID_BOOTPS_RAW=$(aix inetd_bootps grep -E '^[	 ]*bootps[	 ]' /etc/inetd.conf)
  ID_BOOTPS_RC=$?

  if [ "$ID_BOOTPS_RC" -eq 0 ] && [ -n "$ID_BOOTPS_RAW" ]; then
    # Validate that every nonblank row has first field exactly "bootps"
    # and is well-shaped (has at least a service name, socket type, protocol,
    # wait flag, user, path — ≥6 nonblank fields).
    ID_BOOTPS_PARSED=$(printf '%s\n' "$ID_BOOTPS_RAW" | awk '
      /^[ \t]*$/ { next }
      {
        rows++
        # Strip leading whitespace and check first field
        line = $0
        sub(/^[ \t]+/, "", line)
        split(line, fields, /[ \t]+/)
        if (fields[1] != "bootps") {
          bad_first = 1
        }
        if (NF < 6) {
          malformed++
        }
      }
      END {
        if (bad_first) {
          print "non-bootps-first"
        } else if (malformed) {
          print "malformed"
        } else if (rows == 1) {
          print "single"
        } else if (rows > 1) {
          print "multiple"
        } else {
          print "absent"
        }
      }')
    case "$ID_BOOTPS_PARSED" in
      single) ID_BOOTPS_SHAPE=1 ;;
      multiple) ID_BOOTPS_SHAPE=1 ;;
      *) ID_BOOTPS_SHAPE=0 ;;
    esac
  fi

  # Compute verdict, then severity, then emit single finding.
  case "$ID_BOOTPS_RC" in
    0)
      if [ "$ID_BOOTPS_SHAPE" -eq 1 ] && [ "$ID_BOOTPS_PARSED" != "absent" ]; then
        ID_BOOTPS_STATUS=FAIL
        ID_BOOTPS_OBSERVED="bootps active in /etc/inetd.conf"
        ID_BOOTPS_MEANING="The legacy bootps service is exposed through inetd and adds avoidable remote attack surface."
        ID_BOOTPS_FIX="after service-owner approval, comment the exact bootps definition and refresh inetd; PTxray only recommends these actions."
      else
        ID_BOOTPS_STATUS=NOT_ASSESSED
        case "$ID_BOOTPS_PARSED" in
          non-bootps-first)
            ID_BOOTPS_OBSERVED="not assessed - bootps inetd probe captured output contains non-bootps-first rows" ;;
          malformed)
            ID_BOOTPS_OBSERVED="not assessed - bootps inetd probe captured rows are malformed" ;;
          *)
            ID_BOOTPS_OBSERVED="not assessed - bootps inetd probe rc=0 but output was empty after grep" ;;
        esac
        ID_BOOTPS_MEANING="PTxray did not obtain trustworthy service-definition evidence."
        ID_BOOTPS_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      fi
      ;;
    1)
      if [ -z "$ID_BOOTPS_RAW" ]; then
        ID_BOOTPS_STATUS=PASS
        ID_BOOTPS_OBSERVED="bootps not active in /etc/inetd.conf"
        ID_BOOTPS_MEANING="The inetd service is not enabled."
        ID_BOOTPS_FIX="n/a"
      else
        ID_BOOTPS_STATUS=NOT_ASSESSED
        ID_BOOTPS_OBSERVED="not assessed - bootps inetd probe rc=1 but output was non-empty (contradictory)"
        ID_BOOTPS_MEANING="PTxray did not obtain trustworthy service-definition evidence."
        ID_BOOTPS_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      fi
      ;;
    *)
      ID_BOOTPS_STATUS=NOT_ASSESSED
      ID_BOOTPS_OBSERVED="not assessed - bootps inetd probe grep failed (rc=$ID_BOOTPS_RC)"
      ID_BOOTPS_MEANING="PTxray did not obtain trustworthy service-definition evidence."
      ID_BOOTPS_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      ;;
  esac

  case "$ID_BOOTPS_STATUS" in
    FAIL) SEVERITY=high ;;
    *) SEVERITY=low ;;
  esac

  add security inetd_bootps "inetd bootps service" \
    "$ID_BOOTPS_STATUS" "$SEVERITY" \
    "$ID_BOOTPS_OBSERVED" \
    "$ID_BOOTPS_MEANING" \
    "$ID_BOOTPS_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
# inetd_chargen — detect whether the legacy chargen service is active in
  # /etc/inetd.conf.  An active chargen entry exposes a clear-text service
  # that can be abused for amplification or as a foothold; CIS requires it
  # disabled.  Capture: grep for the exact first-field token chargen followed
  # by whitespace (not a comment, not chargen-new, not a later-field match).
  #
  # Verdict logic:
  #   rc=0  AND  every nonblank row starts with exactly "chargen "  => FAIL
  #   rc=1  AND  empty output                                       => PASS
  #   anything else                                                 => NOT_ASSESSED
  #
  typeset IC_STATUS IC_RAW IC_RC IC_MATCH IC_OBSERVED IC_MEANING IC_FIX SEVERITY
  IC_STATUS=NOT_ASSESSED
  IC_RAW=""
  IC_RC=126
  IC_MATCH=0
  IC_OBSERVED=""
