            ID_XMQUERY_OBSERVED="not assessed - xmquery inetd probe rc=0 but output was empty after grep" ;;
        esac
        ID_XMQUERY_MEANING="PTxray did not obtain trustworthy service-definition evidence."
        ID_XMQUERY_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      fi
      ;;
    1)
      if [ -z "$ID_XMQUERY_RAW" ]; then
        ID_XMQUERY_STATUS=PASS
        ID_XMQUERY_OBSERVED="xmquery not active in /etc/inetd.conf"
        ID_XMQUERY_MEANING="The inetd service is not enabled."
        ID_XMQUERY_FIX="n/a"
      else
        ID_XMQUERY_STATUS=NOT_ASSESSED
        ID_XMQUERY_OBSERVED="not assessed - xmquery inetd probe rc=1 but output was non-empty (contradictory)"
        ID_XMQUERY_MEANING="PTxray did not obtain trustworthy service-definition evidence."
        ID_XMQUERY_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      fi
      ;;
    *)
      ID_XMQUERY_STATUS=NOT_ASSESSED
      ID_XMQUERY_OBSERVED="not assessed - xmquery inetd probe grep failed (rc=$ID_XMQUERY_RC)"
      ID_XMQUERY_MEANING="PTxray did not obtain trustworthy service-definition evidence."
      ID_XMQUERY_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      ;;
  esac

  case "$ID_XMQUERY_STATUS" in
    FAIL) SEVERITY=high ;;
    *) SEVERITY=low ;;
  esac

  add security inetd_xmquery "inetd xmquery service" \
    "$ID_XMQUERY_STATUS" "$SEVERITY" \
    "$ID_XMQUERY_OBSERVED" \
    "$ID_XMQUERY_MEANING" \
    "$ID_XMQUERY_FIX" \
    "cis-l1"

  # inetd_cleartext
  INE=$(aix inetd_conf grep -E '^[[:space:]]*(telnet|telnetd|ftp|ftpd|shell|login|exec|rsh|rlogin)[[:space:]]' /etc/inetd.conf) # network-lint: allow -- reads the LOCAL /etc/inetd.conf capture text (via the aix wrapper), never a network call
  SVCS=$(printf '%s\n' "$INE" | awk 'NF{printf "%s%s",(n++?", ":""),$1}')
  if [ -n "$SVCS" ]; then
    add security inetd_cleartext "Cleartext inetd services" FAIL high "enabled: $SVCS" \
        "Cleartext remote-access services are enabled — credentials cross the wire readable." \
        "disable telnet/ftp/rsh/rlogin in /etc/inetd.conf and 'refresh -s inetd'; use ssh/sftp." "stig:V-215258 stig:V-215259 cis-l1" # network-lint: allow -- remediation-advice prose, not a network call
  else
    add security inetd_cleartext "Cleartext inetd services" PASS med "none enabled" \
        "No cleartext remote-access services are enabled in inetd." "n/a" "stig:V-215258 stig:V-215259 cis-l1"
  fi

  # rhosts
  # The probe always emits a completion marker after checking both paths. That
  # makes a clean result positive evidence instead of inferring absence from an
  # empty/nonzero compound ls. Legacy real captures with one exact present path
  # and rc 1/2 remain strong adverse evidence for the #76 partial-presence case.
  RH=$(aix ls_rhosts sh -c '
    for path in /.rhosts /etc/hosts.equiv; do
      if [ -f "$path" ] || [ -L "$path" ]; then
        printf "%s\n" "$path"
      fi
    done
    printf "%s\n" __AIXRAY_RHOSTS_PROBE_COMPLETE__
  '); RHRC=$?
  RHPRESENT=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv" {printf "%s%s",(n++?", ":""),$0}')
  RHCOMP=$(printf '%s\n' "$RH" | awk '$0=="__AIXRAY_RHOSTS_PROBE_COMPLETE__"{n++} END{print n+0}')
  RHBAD=$(printf '%s\n' "$RH" | awk 'NF && $0!="/.rhosts" && $0!="/etc/hosts.equiv" && $0!="__AIXRAY_RHOSTS_PROBE_COMPLETE__"{n++} END{print n+0}')
  RHCOUNT=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv"{n++} END{print n+0}')
  RHUNIQ=$(printf '%s\n' "$RH" | awk '$0=="/.rhosts" || $0=="/etc/hosts.equiv"{seen[$0]=1} END{for(k in seen)n++; print n+0}')
  if [ -n "$RHPRESENT" ] && [ "$RHBAD" -eq 0 ] && [ "$RHCOMP" -eq 0 ] &&
     [ "$RHCOUNT" -eq "$RHUNIQ" ] &&
     { [ "$RHRC" -eq 0 ] || [ "$RHRC" -eq 1 ] || [ "$RHRC" -eq 2 ]; }; then
    add security rhosts "Trust files (.rhosts)" FAIL high "present: $RHPRESENT" \
        "Host-trust files allow passwordless login from named hosts — a classic lateral-movement path." \
        "remove /.rhosts and /etc/hosts.equiv; rely on key-based ssh instead." "stig:V-215432" # network-lint: allow -- remediation-advice prose, not a network call
  elif [ "$RHRC" -ne 0 ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe failed (rc=$RHRC)" \
        "The trust-file probe did not complete, so absence of .rhosts/hosts.equiv cannot be asserted." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun PTxray." "stig:V-215432"
  elif [ -z "$RH" ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe empty (rc=0)" \
        "The trust-file probe returned no evidence, so absence of .rhosts/hosts.equiv cannot be asserted." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun PTxray." "stig:V-215432"
  elif [ "$RHCOMP" -ne 1 ] || [ "$RHBAD" -ne 0 ] || [ "$RHCOUNT" -ne "$RHUNIQ" ]; then
    add security rhosts "Trust files (.rhosts)" NOT_ASSESSED high "not assessed — rhosts probe unparseable (rc=0)" \
        "The trust-file probe output was incomplete, contradictory, duplicated, or did not match its completion protocol." \
        "check /.rhosts and /etc/hosts.equiv manually, then rerun PTxray." "stig:V-215432"
  elif [ -n "$RHPRESENT" ]; then
    add security rhosts "Trust files (.rhosts)" FAIL high "present: $RHPRESENT" \
        "Host-trust files allow passwordless login from named hosts — a classic lateral-movement path." \
        "remove /.rhosts and /etc/hosts.equiv; rely on key-based ssh instead." "stig:V-215432" # network-lint: allow -- remediation-advice prose, not a network call
  else
    add security rhosts "Trust files (.rhosts)" PASS low "none present" \
        "No .rhosts or hosts.equiv trust files present." "n/a" "stig:V-215432"
  fi

_AIXRAY_SESSION_KEYS=""

  # net_tcp_pmtu_discover — CIS AIX baseline requires tcp_pmtu_discover=0 to
  # remove an ICMP-driven state/DoS avenue on untrusted networks. The no -o
  # wrapper prints "tcp_pmtu_discover = <n>"; parse the value after "=".

  typeset NTP_RAW NTP_RC NTP_VAL
  NTP_RAW=$(aix net_tcp_pmtu_discover no -o tcp_pmtu_discover); NTP_RC=$?
  if [ "$NTP_RC" -ne 0 ]; then
    add security net_tcp_pmtu_discover "TCP path-MTU discovery" NOT_ASSESSED low \
        "not assessed — no -o tcp_pmtu_discover failed (rc=$NTP_RC)" \
        "The no -o command returned nonzero rc=$NTP_RC, so the tunable value cannot be read on this AIX level." \
        "run 'no -o tcp_pmtu_discover' manually and check that the tunable is supported on this AIX release." "cis-l1"
  else
    NTP_VAL=$(printf '%s\n' "$NTP_RAW" | awk '/tcp_pmtu_discover/ && $2=="=" && NF>=3 && $3 ~ /^[0-9]+$/ {print $3}')
    if [ -z "$NTP_VAL" ]; then
      # rc=0 but output has no parseable "tcp_pmtu_discover = <digit+>" — could be empty,
      # malformed line, or a line with no numeric value after "=".
      add security net_tcp_pmtu_discover "TCP path-MTU discovery" NOT_ASSESSED low \
          "not assessed — no -o tcp_pmtu_discover returned empty or unparseable output" \
          "The command returned rc=0 but did not produce a parseable 'tcp_pmtu_discover = <value>' line." \
          "run 'no -o tcp_pmtu_discover' manually and inspect the output shape." "cis-l1"
    elif [ "$NTP_VAL" -eq 0 ]; then
      add security net_tcp_pmtu_discover "TCP path-MTU discovery" PASS low "tcp_pmtu_discover=0" \
          "TCP path-MTU discovery is disabled (0), matching the CIS AIX baseline." "n/a" "cis-l1"
    else
      add security net_tcp_pmtu_discover "TCP path-MTU discovery" WARN low "tcp_pmtu_discover=$NTP_VAL" \
          "TCP path-MTU discovery is enabled ($NTP_VAL) — per-path ICMP-driven state that can be abused for DoS." \
          "set 'no -p -o tcp_pmtu_discover=0' to disable per CIS AIX baseline." "cis-l1"
    fi
  fi
