      add security net_udp_pmtu_discover "UDP path-MTU discovery" NOT_ASSESSED low \
          "not assessed — no -o udp_pmtu_discover returned empty or unparseable output" \
          "The command returned rc=0 but did not produce a parseable 'udp_pmtu_discover = <value>' line." \
          "run 'no -o udp_pmtu_discover' manually and inspect the output shape." "cis-l1"
    elif [ "$NUP_VAL" -eq 0 ]; then
      add security net_udp_pmtu_discover "UDP path-MTU discovery" PASS low "udp_pmtu_discover=0" \
