            NOT_ASSESSED high \
            "not assessed — capture did not contain exactly one ip6srcrouteforward assignment (rc=0)" \
            "The output did not contain the requested tunable assignment, so PTxray cannot determine whether source-routed IPv6 packets are forwarded." \
            "run 'no -o ip6srcrouteforward' manually and inspect the output shape." "cis-l1"
        ;;
      *)
        add security net_ip6srcrouteforward "Source-routed IPv6 forwarding" \
            NOT_ASSESSED high \
            "not assessed — ip6srcrouteforward capture unparseable (rc=0)" \
            "The requested assignment had unmodelled syntax or trailing fields, so PTxray could not extract one numeric value." \
            "run 'no -o ip6srcrouteforward' manually and inspect the output shape." "cis-l1"
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""

  # net_nfs_use_reserved_ports — CIS AIX baseline requires nfs_use_reserved_ports=1
  # so that NFS clients use privileged ports for connections. This hardens the
  # NFS stack against spoofed responses from unprivileged ports.
  # nfs_use_reserved_ports is an nfso tunable; 'no -o' rejects it (1485-110, verified live on AIX 7200-05 2026-08-04).
  typeset NFS_RR_RAW NFS_RR_RC NFS_RR_VAL
  NFS_RR_RAW=$(aix net_nfs_use_reserved_ports nfso -o nfs_use_reserved_ports); NFS_RR_RC=$?
  if [ "$NFS_RR_RC" -ne 0 ]; then
    add security net_nfs_use_reserved_ports "NFS reserved ports" NOT_ASSESSED low \
        "not assessed — nfs_use_reserved_ports capture failed (rc=$NFS_RR_RC)" \
        "The nfso -o command returned nonzero rc=$NFS_RR_RC, so the tunable value cannot be read on this AIX level." \
        "run 'nfso -o nfs_use_reserved_ports' manually and check that the tunable is supported on this AIX release." "cis-l1"
  elif [ -z "$NFS_RR_RAW" ]; then
    add security net_nfs_use_reserved_ports "NFS reserved ports" NOT_ASSESSED low \
        "not assessed — nfs_use_reserved_ports capture empty (rc=0)" \
        "The command returned rc=0 but produced no output, so the tunable value cannot be read." \
        "run 'nfso -o nfs_use_reserved_ports' manually and inspect the output." "cis-l1"
  else
    NFS_RR_VAL=$(printf '%s\n' "$NFS_RR_RAW" | awk '/nfs_use_reserved_ports/ && $2=="=" && NF>=3 && $3 ~ /^[0-9]+$/ {print $3}')
    if [ -z "$NFS_RR_VAL" ]; then
      if printf '%s\n' "$NFS_RR_RAW" | awk '/nfs_use_reserved_ports/ { found=1 } END { exit !found }'; then
        add security net_nfs_use_reserved_ports "NFS reserved ports" NOT_ASSESSED low \
            "not assessed — nfso -o nfs_use_reserved_ports returned empty or unparseable output" \
            "The command returned rc=0 but the nfs_use_reserved_ports assignment was unparseable." \
            "run 'nfso -o nfs_use_reserved_ports' manually and inspect the output shape." "cis-l1"
      else
        add security net_nfs_use_reserved_ports "NFS reserved ports" NOT_ASSESSED low \
            "not assessed — no parseable nfs_use_reserved_ports assignment (rc=0)" \
            "The command returned rc=0 but did not include the requested nfs_use_reserved_ports assignment." \
            "run 'nfso -o nfs_use_reserved_ports' manually and inspect the output shape." "cis-l1"
      fi
    elif [ "$NFS_RR_VAL" -eq 1 ]; then
      add security net_nfs_use_reserved_ports "NFS reserved ports" PASS low "nfs_use_reserved_ports=1" \
          "NFS reserved ports are enabled (1), matching the CIS AIX baseline." "n/a" "cis-l1"
    else
      add security net_nfs_use_reserved_ports "NFS reserved ports" WARN low "nfs_use_reserved_ports=$NFS_RR_VAL" \
          "NFS reserved ports are NOT enabled ($NFS_RR_VAL) — NFS clients may use unprivileged ports, weakening NFS client authentication." \
          "set 'nfso -p -o nfs_use_reserved_ports=1' to enable per CIS AIX baseline." "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # net_icmptimestamp — CIS AIX baseline requires icmptimestamp=0 to prevent
  # local time disclosure via ICMP timestamp replies. An attacker can use
  # timestamp replies to determine host system time and refine other attacks.
  typeset ITC_RAW ITC_RC ITC_VAL
  ITC_RAW=$(aix net_icmptimestamp no -o icmptimestamp); ITC_RC=$?
  if [ "$ITC_RC" -ne 0 ]; then
    add security net_icmptimestamp "ICMP timestamp reply" NOT_ASSESSED low \
        "not assessed — icmptimestamp capture failed (rc=$ITC_RC)" \
        "The no -o command returned nonzero rc=$ITC_RC, so the tunable value cannot be read on this AIX level." \
        "run 'no -o icmptimestamp' manually and check that the tunable is supported on this AIX release." "cis-l1"
  elif [ -z "$ITC_RAW" ]; then
    add security net_icmptimestamp "ICMP timestamp reply" NOT_ASSESSED low \
        "not assessed — icmptimestamp capture empty (rc=0)" \
        "The command returned rc=0 but produced no output, so the tunable value cannot be read." \
        "run 'no -o icmptimestamp' manually and inspect the output." "cis-l1"
  else
    ITC_VAL=$(printf '%s\n' "$ITC_RAW" | awk '/icmptimestamp/ && $2=="=" && NF>=3 && $3 ~ /^[0-9]+$/ {print $3}')
    if [ -z "$ITC_VAL" ]; then
      if printf '%s\n' "$ITC_RAW" | awk '/icmptimestamp/ { found=1 } END { exit !found }'; then
        add security net_icmptimestamp "ICMP timestamp reply" NOT_ASSESSED low \
            "not assessed — no -o icmptimestamp returned empty or unparseable output" \
            "The command returned rc=0 but the icmptimestamp assignment was unparseable." \
            "run 'no -o icmptimestamp' manually and inspect the output shape." "cis-l1"
      else
        add security net_icmptimestamp "ICMP timestamp reply" NOT_ASSESSED low \
            "not assessed — no parseable icmptimestamp assignment (rc=0)" \
            "The command returned rc=0 but did not include the requested icmptimestamp assignment." \
            "run 'no -o icmptimestamp' manually and inspect the output shape." "cis-l1"
      fi
    elif [ "$ITC_VAL" -eq 0 ]; then
      add security net_icmptimestamp "ICMP timestamp reply" PASS low "icmptimestamp=0" \
          "ICMP timestamp reply is disabled (0), matching the CIS AIX baseline." "n/a" "cis-l1"
    else
      add security net_icmptimestamp "ICMP timestamp reply" WARN low "icmptimestamp=$ITC_VAL" \
          "ICMP timestamp reply is enabled ($ITC_VAL) — the host leaks local time via ICMP timestamp replies." \
          "set 'no -p -o icmptimestamp=0' to disable per CIS AIX baseline." "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # net_sockthresh — CIS IBM AIX 7 v1.2.0 4.5.1 "Ensure sockthresh is configured".
  # sockthresh caps new socket allocation once the given percentage of network
  # memory (thewall) is in use; the AIX shipped default is 85. A hardened host
  # lowers it so runaway socket creation cannot exhaust network memory.
  # TODO-VERIFY(CIS IBM AIX 7 v1.2.0 4.5.1): the PASS threshold (<= 60) is common
  # AIX hardening practice, NOT read from the CIS benchmark text. Verify against
  # the benchmark PDF before presenting this threshold as CIS-sourced. Do not
  # remove this marker without that verification on record.
  typeset STH_RAW STH_RC STH_VAL
  STH_RAW=$(aix net_sockthresh no -o sockthresh); STH_RC=$?
  if [ "$STH_RC" -ne 0 ]; then
    add security net_sockthresh "Socket creation threshold (sockthresh)" NOT_ASSESSED low \
        "not assessed — sockthresh capture failed (rc=$STH_RC)" \
        "The no -o command returned nonzero rc=$STH_RC, so the tunable value cannot be read on this AIX level." \
        "run 'no -o sockthresh' manually and check that the tunable is supported on this AIX release." "cis-l1"
  elif [ -z "$STH_RAW" ]; then
    add security net_sockthresh "Socket creation threshold (sockthresh)" NOT_ASSESSED low \
        "not assessed — sockthresh capture empty (rc=0)" \
        "The command returned rc=0 but produced no output, so the tunable value cannot be read." \
        "run 'no -o sockthresh' manually and inspect the output." "cis-l1"
  else
    STH_VAL=$(printf '%s\n' "$STH_RAW" | awk '/sockthresh/ && $2=="=" && NF>=3 && $3 ~ /^[0-9]+$/ {print $3}')
    if [ -z "$STH_VAL" ]; then
      if printf '%s\n' "$STH_RAW" | awk '/sockthresh/ { found=1 } END { exit !found }'; then
        add security net_sockthresh "Socket creation threshold (sockthresh)" NOT_ASSESSED low \
            "not assessed — no -o sockthresh returned empty or unparseable output" \
            "The command returned rc=0 but the sockthresh assignment was unparseable." \
            "run 'no -o sockthresh' manually and inspect the output shape." "cis-l1"
      else
        add security net_sockthresh "Socket creation threshold (sockthresh)" NOT_ASSESSED low \
            "not assessed — no parseable sockthresh assignment (rc=0)" \
            "The command returned rc=0 but did not include the requested sockthresh assignment." \
            "run 'no -o sockthresh' manually and inspect the output shape." "cis-l1"
      fi
    elif [ "$STH_VAL" -ge 1 ] && [ "$STH_VAL" -le 60 ]; then
      add security net_sockthresh "Socket creation threshold (sockthresh)" PASS low "sockthresh=$STH_VAL" \
          "sockthresh is configured below the AIX default (85), limiting socket-driven network memory exhaustion. Threshold 60 is pending verification against the CIS benchmark text." \
          "n/a" "cis-l1"
    else
      add security net_sockthresh "Socket creation threshold (sockthresh)" WARN low "sockthresh=$STH_VAL" \
          "sockthresh=$STH_VAL — at or above the AIX shipped default, so the socket-creation memory cap is not configured for hardening." \
          "set 'no -p -o sockthresh=60' (verify the exact CIS value before customer delivery)." "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # net_tcp_tcpsecure — CIS IBM AIX 7 v1.2.0 4.5.17 "Ensure tcp_tcpsecure is configured".
  # tcp_tcpsecure is a bitmask (0-7) enabling TCP protection against spoofed SYN,
  # spoofed RST, and data-injection attacks. The AIX shipped default is 0 (off).
  # TODO-VERIFY(CIS IBM AIX 7 v1.2.0 4.5.17): the exact mode bits CIS requires are
  # unverified against the benchmark text. This check PASSes only the strictest
  # setting (7); a CIS-acceptable lesser mask (e.g. 5) would show WARN until the
  # benchmark text is verified. Do not remove this marker without that
  # verification on record.
  typeset TSEC_RAW TSEC_RC TSEC_VAL
  TSEC_RAW=$(aix net_tcp_tcpsecure no -o tcp_tcpsecure); TSEC_RC=$?
  if [ "$TSEC_RC" -ne 0 ]; then
    add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" NOT_ASSESSED med \
        "not assessed — tcp_tcpsecure capture failed (rc=$TSEC_RC)" \
        "The no -o command returned nonzero rc=$TSEC_RC, so the tunable value cannot be read on this AIX level." \
        "run 'no -o tcp_tcpsecure' manually and check that the tunable is supported on this AIX release." "cis-l1"
  elif [ -z "$TSEC_RAW" ]; then
    add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" NOT_ASSESSED med \
        "not assessed — tcp_tcpsecure capture empty (rc=0)" \
        "The command returned rc=0 but produced no output, so the tunable value cannot be read." \
        "run 'no -o tcp_tcpsecure' manually and inspect the output." "cis-l1"
  else
    TSEC_VAL=$(printf '%s\n' "$TSEC_RAW" | awk '/tcp_tcpsecure/ && $2=="=" && NF>=3 && $3 ~ /^[0-9]+$/ {print $3}')
    if [ -z "$TSEC_VAL" ]; then
      if printf '%s\n' "$TSEC_RAW" | awk '/tcp_tcpsecure/ { found=1 } END { exit !found }'; then
        add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" NOT_ASSESSED med \
            "not assessed — no -o tcp_tcpsecure returned empty or unparseable output" \
            "The command returned rc=0 but the tcp_tcpsecure assignment was unparseable." \
            "run 'no -o tcp_tcpsecure' manually and inspect the output shape." "cis-l1"
      else
        add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" NOT_ASSESSED med \
            "not assessed — no parseable tcp_tcpsecure assignment (rc=0)" \
            "The command returned rc=0 but did not include the requested tcp_tcpsecure assignment." \
            "run 'no -o tcp_tcpsecure' manually and inspect the output shape." "cis-l1"
      fi
    elif [ "$TSEC_VAL" -eq 7 ]; then
      add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" PASS low "tcp_tcpsecure=7" \
          "tcp_tcpsecure=7 — all TCP spoofed-SYN, spoofed-RST, and data-injection protections are enabled." \
          "n/a" "cis-l1"
    else
      add security net_tcp_tcpsecure "TCP connection attack protection (tcp_tcpsecure)" WARN med "tcp_tcpsecure=$TSEC_VAL" \
          "tcp_tcpsecure=$TSEC_VAL — TCP connection attack protection is not fully configured (0 is the unhardened AIX default; this check accepts only 7 pending CIS text verification)." \
          "set 'no -p -o tcp_tcpsecure=7' (verify the exact CIS-accepted mask before customer delivery)." "cis-l1"
    fi
  fi

  # world_writable (scope bounded to /etc and /usr/local/bin on purpose)
  WW=$(aix find_ww find /etc /usr/local/bin -xdev -type f -perm -002)
  if [ -n "$WW" ]; then
    WWN=$(printf '%s\n' "$WW" | awk 'NR<=3{printf "%s%s",(NR>1?", ":""),$0} END{if(NR>3)printf " +%d more",NR-3}')
    add security world_writable "World-writable files" WARN high "$WWN" \
        "World-writable files in /etc and /usr/local/bin (scope bounded to those on purpose) let any user alter system content." \
        "remove world write with 'chmod o-w <file>'; find the process that created them." "cis-l1"
  else
    add security world_writable "World-writable files" PASS low "none in /etc, /usr/local/bin" \
        "No world-writable files in the scanned directories (scope bounded to /etc and /usr/local/bin)." "n/a" "cis-l1"
  fi

  # snmp_community — grep rc>=2 means the config was UNREADABLE (permissions),
  # which must never masquerade as a clean PASS on an unprivileged run.
  SNMP=$(aix snmp_conf grep -E '^community[ 	]+(public|private)' /etc/snmpd.conf /etc/snmpdv3.conf); RC=$?
  if [ -n "$SNMP" ]; then
    add security snmp_community "SNMP community strings" FAIL med "default community in use" \
        "SNMP uses a default community string (public/private) — anyone on the network can read, or write, system data." \
        "replace public/private with a strong community in /etc/snmpd.conf and refresh snmpd." "stig:V-215231 cis-l1"
  elif [ "$RC" -ge 2 ] && [ "${MYUID:-0}" != "0" ]; then
    nr_warn security snmp_community "SNMP community strings" "the SNMP configuration" "grep community /etc/snmpd.conf" "stig:V-215231 cis-l1"
  elif [ "$RC" -ge 2 ]; then
    add security snmp_community "SNMP community strings" PASS low "no snmpd configuration" \
        "No SNMP daemon configuration present on this box." "n/a" "stig:V-215231 cis-l1"
  else
    add security snmp_community "SNMP community strings" PASS low "no default community" \
        "No default public/private SNMP community strings configured." "n/a" "stig:V-215231 cis-l1"
  fi

  # audit_active (root-gated)
  AUD=$(aix audit_query audit query); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security audit_active "Audit subsystem" "the audit state" "audit query" "cis-l1 ffiec:II.C.22"
  elif printf '%s\n' "$AUD" | grep -qi 'auditing on'; then
    add security audit_active "Audit subsystem" PASS med "auditing on" \
        "The audit subsystem is running — you can answer 'who did what'." "n/a" "cis-l1 ffiec:II.C.22"
  else
    add security audit_active "Audit subsystem" WARN high "auditing off" \
        "No audit trail — you cannot answer 'who did what' after an incident." \
        "configure and start audit ('audit start'; set it to start at boot)." "cis-l1 ffiec:II.C.22"
  fi

  # trusted_exec (root-gated; skip on older AIX without TE — but rc 127 proves
  # absence only as root: trustchk is mode 500, invisible to non-root PATH search)
  TE=$(aix trustchk_p trustchk -p TE); RC=$?
  if [ "$RC" -eq 127 ] && [ "${MYUID:-0}" = "0" ]; then
    :  # Trusted Execution not present on this AIX — nothing to report
  elif [ "$RC" -ne 0 ]; then
    nr_warn security trusted_exec "Trusted Execution" "the Trusted Execution policy" "trustchk -p TE"
  elif printf '%s\n' "$TE" | grep -q 'TE=ON'; then
    add security trusted_exec "Trusted Execution" PASS low "TE=ON" \
        "Trusted Execution is enabled — the kernel checks binary integrity at load." "n/a"
  else
    add security trusted_exec "Trusted Execution" WARN low "TE=OFF" \
        "Trusted Execution is off (informational) — no runtime binary-integrity enforcement." \
        "consider enabling TE ('trustchk -p TE=ON') if your change control supports it."
  fi

  # login_banner (root-gated)
  HERALD=$(aix login_herald lssec -f /etc/security/login.cfg -s default -a herald); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security login_banner "Login banner" "the login herald" "lssec -f /etc/security/login.cfg -s default -a herald"
  else
    HV=$(printf '%s\n' "$HERALD" | sed -n 's/.*herald=//p')
    case "$HV" in
      ''|'""') add security login_banner "Login banner" WARN low "no herald set" \
                 "No legal login banner is set — auditors ask for one and it deters casual access." \
                 "set a herald in the /etc/security/login.cfg default stanza (chsec -a herald=...)." "stig:V-215200";;
      *) add security login_banner "Login banner" PASS low "herald set" \
                 "A login banner is configured." "n/a" "stig:V-215200";;
    esac
  fi

  # account_hygiene — non-system accounts whose password never expires (root-gated)
  LSUA=$(aix lsuser_all lsuser -a account_locked maxage ALL); RC=$?
  if [ "$RC" -ne 0 ]; then
    nr_warn security account_hygiene "Account password aging" "the per-user password aging" "lsuser -a account_locked maxage ALL" "cis-l1 ffiec:II.C.7"
  else
    NEVERLIST=$(printf '%s\n' "$LSUA" | awk '
      BEGIN{split("root daemon bin sys adm uucp guest nobody lpd lp invscout snapp ipsec nuucp pconsole sshd esaadmin",s," "); for(i in s)sysu[s[i]]=1}
      {u=$1; ma="x"; for(i=2;i<=NF;i++)if(index($i,"maxage=")==1)ma=substr($i,8)
       if(u!="" && !(u in sysu) && ma=="0") print u}')
    NNEVER=$(printf '%s\n' "$NEVERLIST" | awk 'NF{n++} END{print n+0}')
    NEVER5=$(printf '%s\n' "$NEVERLIST" | awk 'NF{if(n<5){printf "%s%s",(n?", ":""),$0; n++}} END{if(NR>5)printf " +%d more",NR-5}')
    LOCKED=$(printf '%s\n' "$LSUA" | awk '{for(i=1;i<=NF;i++)if($i=="account_locked=true")n++} END{print n+0}')
    if [ "${NNEVER:-0}" -gt 0 ]; then
      add security account_hygiene "Account password aging" WARN med "$NNEVER never-expire: $NEVER5 ($LOCKED locked)" \
          "Non-system accounts have maxage=0 — passwords that never expire outlive the people who set them." \
          "set aging on these accounts (chuser maxage=13 <user>), or lock/remove ones no longer in use." "cis-l1 ffiec:II.C.7"
    else
      add security account_hygiene "Account password aging" PASS low "no non-system account with maxage=0 ($LOCKED locked)" \
          "Every non-system account has password aging set." "n/a" "cis-l1 ffiec:II.C.7"
    fi
  fi

  # suid_unexpected — setuid/setgid files outside the system paths
  #   rc=0    + empty output  -> PASS           no unexpected setuid/setgid files
  #   rc=0    + output        -> WARN           at least one unexpected file
  #   rc!=0   + output        -> WARN           scan hit errors but files still found
  #   rc!=0   + empty output  -> NOT_ASSESSED   scan failed; filesystem state unknown
  SUID=$(aix find_suid find /home /tmp /var/tmp /usr/local -xdev -type f \( -perm -4000 -o -perm -2000 \))
  SUID_RC=$?
  if [ -n "$SUID" ]; then
    SUID3=$(printf '%s\n' "$SUID" | awk 'NF{if(n<3){printf "%s%s",(n?", ":""),$0; n++}} END{if(NR>3)printf " +%d more",NR-3}')
    if [ "$SUID_RC" -eq 0 ]; then
      add security suid_unexpected "Unexpected setuid/setgid files" WARN high "$SUID3" \
          "setuid outside system paths is either a mistake or a foothold for privilege escalation." \
          "review each file; strip the bit (chmod u-s / g-s) or remove it if it should not be there." "cis-l1"
    else
      add security suid_unexpected "Unexpected setuid/setgid files" WARN high "$SUID3 (partial scan, rc=$SUID_RC)" \
          "setuid outside system paths is either a mistake or a foothold for privilege escalation." \
          "review each file; strip the bit (chmod u-s / g-s) or remove it if it should not be there." "cis-l1"
    fi
  else
    if [ "$SUID_RC" -eq 0 ]; then
      add security suid_unexpected "Unexpected setuid/setgid files" PASS low "none in /home /tmp /var/tmp /usr/local" \
          "No setuid/setgid files outside the system paths." "n/a" "cis-l1"
    else
      add security suid_unexpected "Unexpected setuid/setgid files" NOT_ASSESSED med "not assessed - setuid/setgid scan of /home /tmp /var/tmp /usr/local failed (rc=$SUID_RC) with no output" \
          "PTxray could not determine whether unexpected setuid/setgid files exist because the scan did not complete." \
          "run the find manually and confirm each of the four directories exists and is readable." "cis-l1"
    fi
  fi

  # listeners — count of listening sockets (attack surface)
  NSL=$(aix netstat_Aan netstat -Aan); RC=$?
  if [ "$RC" -ne 0 ] || [ -z "$NSL" ]; then
    add security listeners "Listening network sockets" WARN low "unreadable" \
        "Could not read the listening-socket list from netstat." "check 'netstat -Aan' manually."
  else
    NL=$(printf '%s\n' "$NSL" | awk '/LISTEN/{n++} END{print n+0}')
    add security listeners "Listening network sockets" PASS low "$NL listening socket(s)" \
        "Each listening socket is attack surface — review anything you do not recognize." "n/a"
  fi

  # ---- G depth: correlated privileged-access hardening (WP-K area 5) ----------------
  # Beyond the sshd-level and per-rule STIG checks: the OS account gates and delegation
  # posture a veteran hunts for — the correlated "root wide open" signals.

  # Shared account-gate capture for the nine named system-account checks.
  # lsuser omits any attribute it cannot report: an account whose /etc/passwd
  # shell field is empty produces a row with NO shell= token (proven on real
  # AIX 7.2). A missing or empty shell is evidence of an unsecured login path
  # and must reach the verdict logic — it is never an evidence failure.
  SYSACCT_RAW=$(aix system_accounts lsuser -a login rlogin shell account_locked ALL)
  SYSACCT_RC=$?; SYSACCT_OK=0; SYSACCT_WHY=""; SYSACCT_STATES=""
  if [ "$SYSACCT_RC" -ne 0 ]; then
    SYSACCT_WHY="capture failed (rc=$SYSACCT_RC)"
  elif [ -z "$SYSACCT_RAW" ]; then
    SYSACCT_WHY="capture empty (rc=0)"
  elif printf '%s\n' "$SYSACCT_RAW" | awk '
      NF {
        rows++; if ($1 !~ /^[A-Za-z0-9_.-]+$/) bad=1
        for (seen_key in seen) delete seen[seen_key]
        login=""; rlogin=""; shell=""; locked=""
        for (i=2; i<=NF; i++) {
          split($i,pair,"="); key=pair[1]
          if (seen[key]++) bad=1
          if (key=="login") login=substr($i,7)
          else if (key=="rlogin") rlogin=substr($i,8)
          else if (key=="shell") shell=substr($i,7)
          else if (key=="account_locked") locked=substr($i,16)
          else bad=1
        }
        if (!("login" in seen) || !("rlogin" in seen) ||
            !("account_locked" in seen)) bad=1
        if (login !~ /^(true|false)$/ || rlogin !~ /^(true|false)$/ ||
            locked !~ /^(true|false)$/) bad=1
        if (("shell" in seen) && shell != "" &&
            shell !~ /^\/[A-Za-z0-9_.\/-]+$/) bad=1
        if (users[$1]++) bad=1
      }
      END { exit rows>0 && !bad ? 0 : 1 }'; then
    SYSACCT_OK=1
    SYSACCT_STATES=$(printf '%s\n' "$SYSACCT_RAW" | awk '
      BEGIN {
        split("adm bin daemon guest lpd nobody nuucp sys uucp", target, " ")
        for (i=1; i<=9; i++) wanted[target[i]]=1
      }
      $1 in wanted {
        login=""; rlogin=""; shell=""; locked=""
        for (i=2; i<=NF; i++) {
          if (index($i,"login=")==1) login=substr($i,7)
          else if (index($i,"rlogin=")==1) rlogin=substr($i,8)
          else if (index($i,"shell=")==1) shell=substr($i,7)
          else if (index($i,"account_locked=")==1) locked=substr($i,16)
        }
        state=(login=="false" && rlogin=="false" &&
