        "/var/tmp/snmpdv3.log violates the required mode boundary and could let an unintended identity alter trusted configuration." \
        "remove only permissions beyond 0640 after validation: 'chmod 0640 /var/tmp/snmpdv3.log'; PTxray recommends this command and never executes it." \
        "cis-l1"
  fi

  # stig_fileperms — data-driven STIG file permission/ownership rule engine (R_FILEPERM)
  eval_fileperms
  # stig_secattr — data-driven STIG account/attribute policy rule engine (R_SECATTR)
  eval_secattr
  # stig_nettune — data-driven STIG network-tunable rule engine (R_NETTUNE)
  eval_nettune
  # stig_svcoff — data-driven STIG disabled-service rule engine (R_SVCOFF)
  eval_svcoff
}

# eval_fileperms — evaluate every R_FILEPERM row against ONE evidence capture and emit
# one grouped finding plus the per-rule detail (F_RULES). A single wrapped command
# (aix stig_fileperm_ls ls -ldn <all paths>) preserves the per-path association: a
# missing path simply produces no line (NA), and ls's nonzero rc for missing paths is
# expected. Owner/group are compared by numeric id (ls -n); mode by mask, not equality.
function eval_fileperms {
  typeset PATHS LS RAW SUM DETAIL CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  PATHS=$(printf '%s\n' "$R_FILEPERM" | awk -F'|' 'NF>=5 && $1 !~ /^#/ && $2!="" && !seen[$2]++{printf "%s ", $2}')
  [ -z "$PATHS" ] && return 0
  # ls -ldn on every distinct rule path in one shot. rc is ignored: missing paths are
  # expected and simply yield no line (parsed as NA below).
  LS=$(aix stig_fileperm_ls ls -ldn $PATHS)

  # One awk pass: build path -> (mode,uid,gid) from the ls lines, then evaluate each rule.
  RAW=$({ printf '%s\n' "$R_FILEPERM"; echo "AIXRAY_LS"; printf '%s\n' "$LS"; } | awk '
    # rwx string (10 chars, incl. suid/sgid/sticky) -> mode as decimal-octal digits (e.g. 0644->644)
    function permoct(s,  o,g,ot,sp,c){
      sp=0;o=0;g=0;ot=0
      if(substr(s,2,1)=="r")o+=4; if(substr(s,3,1)=="w")o+=2
      c=substr(s,4,1); if(c=="x")o+=1; else if(c=="s"){o+=1;sp+=4} else if(c=="S")sp+=4
      if(substr(s,5,1)=="r")g+=4; if(substr(s,6,1)=="w")g+=2
      c=substr(s,7,1); if(c=="x")g+=1; else if(c=="s"){g+=1;sp+=2} else if(c=="S")sp+=2
      if(substr(s,8,1)=="r")ot+=4; if(substr(s,9,1)=="w")ot+=2
      c=substr(s,10,1); if(c=="x")ot+=1; else if(c=="t"){ot+=1;sp+=1} else if(c=="T")sp+=1
      return sp*1000 + o*100 + g*10 + ot
    }
    # is 3-bit octal digit a a subset of b (no bit set in a that is unset in b)
    function bitle(a,b){ return (int(a/4)%2<=int(b/4)%2) && (int(a/2)%2<=int(b/2)%2) && (a%2<=b%2) }
    # does file mode fm (decimal-octal) satisfy the maxmode ceiling mm (decimal-octal)?
    function modeok(fm,mm){
      return bitle(int(fm/1000)%10,int(mm/1000)%10) && bitle(int(fm/100)%10,int(mm/100)%10) \
          && bitle(int(fm/10)%10,int(mm/10)%10) && bitle(fm%10,mm%10)
    }
    function oct4(m){ return sprintf("%04d", m) }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_LS"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="") next
      n=split($0,r,"|"); if(n<5) next
      nr++; R_id[nr]=r[1]; R_path[nr]=r[2]; R_own[nr]=r[3]; R_grp[nr]=r[4]; R_max[nr]=r[5]
      next
    }
    phase==1{
      if(NF<9) next
      p=$NF; seen[p]=1; M_mode[p]=permoct($1); M_uid[p]=$3+0; M_gid[p]=$4+0
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        p=R_path[i]
        req=""
        if(R_own[i]!="") req="owner=" R_own[i]
        if(R_grp[i]!="") req=req (req!=""?"; ":"") "group=" R_grp[i]
        if(R_max[i]!="") req=req (req!=""?"; ":"") "no mode bits beyond " oct4(R_max[i]+0)
        if(!(p in seen)){ st="NA"; obs=p" absent"; nna++ }
        else{
          fm=M_mode[p]; ok=1
          if(R_max[i]!="" && !modeok(fm,R_max[i]+0)) ok=0
          if(R_own[i]!="" && M_uid[p]!=R_own[i]+0) ok=0
          if(R_grp[i]!="" && M_gid[p]!=R_grp[i]+0) ok=0
          obs=p" "oct4(fm)" u="M_uid[p]" g="M_gid[p]
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "p" ("oct4(fm)")" }
        }
        if(req!="") obs=obs " (required: " req ")"
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  # controls = every rule id evaluated (stig: tag grammar), space-separated
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA not applicable; failing: $FLIST"
    MEAN="One or more files mandated by the DISA STIG for IBM AIX 7.x are more permissive, or wrong-owned, than the rule allows — each is a documented hardening gap an auditor will flag."
    FIX="chmod/chown the failing files to the required mode/owner per the rule list (chmod <maxmode> <path>; chown <owner>:<group> <path>); the compliance report lists every rule and its evidence."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA not applicable"
    MEAN="Every applicable STIG file-permission/ownership rule (DISA STIG for IBM AIX 7.x) passes on this box — the mandated files are no more permissive than required."
    FIX="n/a"
  fi
  add security stig_fileperms "STIG file permissions" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_secattr — evaluate every R_SECATTR row and emit one grouped finding (stig_secattr)
# plus per-rule detail (F_RULES). Attributes are grouped by (file,stanza): ONE lssec call
# captures a whole stanza's attribute list (fewest commands, and lssec aborts the entire
# call if any one attribute is invalid for the stanza — so only real attributes are grouped).
# A stanza that cannot be read (non-root: rc!=0/empty) makes its rules NA; a missing/empty
# attribute value is NA. Numeric compare only; op le treats an observed 0 as a FAIL (0 =
# disabled/unlimited on AIX). If nothing was readable at all (NAPPLIC=0) the finding is a
# root-gated WARN rather than a hollow PASS.
function eval_secattr {
  typeset PAIRS CAP RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  # distinct file|stanza pairs in first-seen (deterministic) order
  PAIRS=$(printf '%s\n' "$R_SECATTR" | awk -F'|' 'NF>=6 && $1 !~ /^#/ && $2!="" && !seen[$2 FS $3]++{print $2"|"$3}')
  [ -z "$PAIRS" ] && return 0

  # one lssec per stanza; parse "stanza attr=val attr=val" into "file|stanza|attr|value"
  # lines. An unreadable stanza (rc!=0 or empty) emits nothing -> its rules fall to NA.
  # KEEP the per-stanza attribute lists in tools/capture-fixtures.sh in sync with R_SECATTR.
  CAP=$(printf '%s\n' "$PAIRS" | while IFS='|' read SA_F SA_S; do
    [ -z "$SA_F" ] && continue
    SA_ATTRS=$(printf '%s\n' "$R_SECATTR" | awk -F'|' -v f="$SA_F" -v s="$SA_S" '$2==f && $3==s{printf " -a %s", $4}')
    SA_SLUG=$(printf '%s' "$SA_F" | sed 's|.*/||; s|\.cfg$||')_$SA_S
    SA_RAW=$(aix "stig_secattr_$SA_SLUG" lssec -f "$SA_F" -s "$SA_S" $SA_ATTRS)
    if [ $? -eq 0 ] && [ -n "$SA_RAW" ]; then
      printf '%s\n' "$SA_RAW" | awk -v f="$SA_F" -v s="$SA_S" \
        '{for(i=1;i<=NF;i++){e=index($i,"="); if(e>1) print f "|" s "|" substr($i,1,e-1) "|" substr($i,e+1)}}'
    fi
  done)

  # one awk pass: rules then captured values -> per-rule verdict + summary
  RAW=$({ printf '%s\n' "$R_SECATTR"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    function isnum(x){ return (x ~ /^-?[0-9]+$/) }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<6) next
      nr++; R_id[nr]=$1; R_file[nr]=$2; R_st[nr]=$3; R_attr[nr]=$4; R_op[nr]=$5; R_val[nr]=$6
      next
    }
    phase==1{
      if(NF<4) next
      key=$1 SUBSEP $2 SUBSEP $3; M[key]=$4; P[key]=1
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        key=R_file[i] SUBSEP R_st[i] SUBSEP R_attr[i]
        if(!(key in P) || M[key]==""){ st="NA"; obs=R_attr[i]" unset"; nna++ }
        else if(!isnum(M[key])){ st="NA"; obs=R_attr[i]"="M[key]" non-numeric"; nna++ }
        else{
          v=M[key]+0; req=R_val[i]+0; op=R_op[i]; ok=0
          if(op=="ge") ok=(v>=req)
          else if(op=="le") ok=(v!=0 && v<=req)
          else if(op=="eq") ok=(v==req)
          obs=R_attr[i]"="M[key]" (need "op" "req")"
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "R_attr[i]"="M[key]" (needs "op" "req")" }
        }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the /etc/security account-policy stanzas (needs root); no STIG account/attribute rule could be assessed on this run."
    FIX="re-run ptxray as root to evaluate the account-policy controls; or inspect 'lssec -f /etc/security/user -s default' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more account/password-policy attributes in /etc/security are weaker than the DISA STIG for IBM AIX 7.x mandates — each is a documented hardening gap an auditor will flag, and it applies to every account inheriting the default stanza."
    FIX="tighten the failing attributes with chsec (chsec -f <file> -s default -a <attr>=<value>); the compliance report lists every rule, the required value, and the observed value."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every applicable STIG account/password-policy attribute meets the DISA STIG for IBM AIX 7.x required value."
    FIX="n/a"
  fi
  add security stig_secattr "STIG account policy" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_nettune — evaluate every R_NETTUNE row and emit one grouped finding (stig_nettune)
# plus per-rule detail (F_RULES). One capture per distinct command: 'no -a' and/or 'nfso -a'
# (both are NON-root reads — listing a tunable never needs privilege, only setting one does,
# so there is no root gate here). Each captured "tunable = value" line becomes a
# command|tunable|value record; a tunable absent from the capture is NA. Numeric compare only;
# unlike R_SECATTR, op le does NOT special-case 0 — for a network tunable 0 is normally the
# SECURE value, so it is compared literally.
function eval_nettune {
  typeset CMDS CAP RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX NT_CMD NT_RAW

  # distinct commands (no, nfso) in first-seen order
  CMDS=$(printf '%s\n' "$R_NETTUNE" | awk -F'|' 'NF>=5 && $1 !~ /^#/ && $2!="" && !seen[$2]++{print $2}')
  [ -z "$CMDS" ] && return 0

  # one 'no -a' / 'nfso -a' per command; parse "tunable = value" -> "command|tunable|value".
  # An unreadable command (rc!=0 or empty) emits nothing -> its rules fall to NA.
  CAP=$(printf '%s\n' "$CMDS" | while read NT_CMD; do
    [ -z "$NT_CMD" ] && continue
    NT_RAW=$(aix "stig_${NT_CMD}_a" "$NT_CMD" -a)
    if [ $? -eq 0 ] && [ -n "$NT_RAW" ]; then
      printf '%s\n' "$NT_RAW" | awk -v cmd="$NT_CMD" 'NF>=3 && $2=="="{print cmd "|" $1 "|" $3}'
    fi
  done)

  # one awk pass: rules then captured values -> per-rule verdict + summary
  RAW=$({ printf '%s\n' "$R_NETTUNE"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    function isnum(x){ return (x ~ /^-?[0-9]+$/) }
    function relation(op){
      if(op=="eq") return "="
      if(op=="le") return "<="
      if(op=="ge") return ">="
      return op
    }
    BEGIN{ phase=0; nr=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<5) next
      nr++; R_id[nr]=$1; R_cmd[nr]=$2; R_tun[nr]=$3; R_op[nr]=$4; R_val[nr]=$5
      next
    }
    phase==1{
      if(NF<3) next
      key=$1 SUBSEP $2; M[key]=$3; P[key]=1
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        key=R_cmd[i] SUBSEP R_tun[i]
        criterion=R_tun[i] " " relation(R_op[i]) " " R_val[i]
        if(!(key in P) || M[key]==""){ st="NA"; obs=R_tun[i]" absent"; nna++ }
        else if(!isnum(M[key])){ st="NA"; obs=R_tun[i]"="M[key]" non-numeric"; nna++ }
        else{
          v=M[key]+0; req=R_val[i]+0; op=R_op[i]; ok=0
          if(op=="ge") ok=(v>=req)
          else if(op=="le") ok=(v<=req)
          else if(op=="eq") ok=(v==req)
          obs=R_tun[i]"="M[key]
          if(ok){ st="PASS"; npass++ } else { st="FAIL"; nfail++; nf++; fl[nf]=R_id[i]" "R_tun[i]"="M[key]" (needs "op" "req")" }
        }
        obs=obs " (required: " criterion ")"
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the network tunables (no -a / nfso -a); no STIG network-option rule could be assessed on this run."
    FIX="verify the 'no' subsystem is available and re-run; or inspect 'no -a' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more kernel network options are set to a value the DISA STIG for IBM AIX 7.x flags — e.g. IP forwarding on a non-router, or TCP half-open connection cleanup disabled. Each is a documented hardening gap an auditor will flag."
    FIX="set the failing tunables with 'no -p -o <tunable>=<value>' (nfso for NFS options) so the change persists across reboot; the compliance report lists every rule, the required value, and the observed value."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every applicable STIG network-option tunable (DISA STIG for IBM AIX 7.x) is at its required value."
    FIX="n/a"
  fi
  add security stig_nettune "STIG network tunables" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"
}

# eval_svcoff — evaluate every R_SVCOFF row and emit one grouped finding (stig_svcoff) plus
# per-rule detail (F_RULES). Three captures: the uncommented /etc/inetd.conf service lines
# (type inetd: the service token must NOT appear enabled), the uncommented start commands in
# /etc/rc.tcpip (type rctcp: the daemon must not start at boot), and 'lssrc -a' (type lssrc:
# the SRC subsystem must be inoperative, not active). All are non-root reads. For a
# disable-service rule the STIG treats "service enabled/running" as the finding, so a token or
# start command that is absent/commented (inetd/rctcp), or a subsystem that is inoperative/
# undefined (lssrc), is compliant = PASS, not NA. Guard: if lssrc -a yields no subsystem rows
# at all, lssrc-type rules are NA (can't assess) rather than a hollow PASS. This is the broad
# per-V-ID STIG service list; it does NOT duplicate the inetd_cleartext check (which flags
# cleartext-LOGIN daemons enabled).
function eval_svcoff {
  typeset TYPES CAP INE LSS RCT RAW DETAIL SUM CTLS NPASS NFAIL NNA NAPPLIC FLIST ST SEV OBS MEAN FIX

  [ -z "$R_SVCOFF" ] && return 0
  # space-separated (not newline): the `case " $TYPES "` tests below match on
  # spaces, so with >1 type a newline-joined list would match none of them.
  TYPES=$(printf '%s\n' "$R_SVCOFF" | awk -F'|' 'NF>=3 && $1 !~ /^#/{print $2}' | sort -u | tr '\n' ' ')
  [ -z "$TYPES" ] && return 0

  # Build the evidence: enabled inetd tokens and SRC subsystem states.
  CAP=$(
    case " $TYPES " in
      (*" inetd "*)
        INE=$(aix stig_inetd_active grep -v '^#' /etc/inetd.conf)
        printf '%s\n' "$INE" | awk 'NF>=1 && $1 !~ /^#/{print "inetd|" $1 "|on"}'
        ;;
    esac
    case " $TYPES " in
      (*" lssrc "*)
        LSS=$(aix stig_lssrc_a lssrc -a)
        printf '%s\n' "$LSS" | awk 'NR>1 && NF>=2 && $1!="Subsystem"{print "lssrc|" $1 "|" $NF}'
        ;;
    esac
    case " $TYPES " in
      (*" rctcp "*)
        # uncommented "start /path/daemon ..." lines in /etc/rc.tcpip = the daemon boots.
        # A commented rule (#start ...) does not match the anchored grep.
        RCT=$(aix stig_rctcp grep -E '^[	 ]*start ' /etc/rc.tcpip)
        printf '%s\n' "$RCT" | awk '$1=="start" && $2!=""{n=split($2,a,"/"); print "rctcp|" a[n] "|on"}'
        ;;
    esac
  )

  RAW=$({ printf '%s\n' "$R_SVCOFF"; echo "AIXRAY_CAP"; printf '%s\n' "$CAP"; } | awk -F'|' '
    BEGIN{ phase=0; nr=0; nlssrc=0 }
    $0=="AIXRAY_CAP"{ phase=1; next }
    phase==0{
      if($0 ~ /^#/ || $0=="" || NF<3) next
      nr++; R_id[nr]=$1; R_type[nr]=$2; R_name[nr]=$3
      next
    }
    phase==1{
      if(NF<3) next
      if($1=="inetd"){ enabled[$2]=1 }
      else if($1=="lssrc"){ state[$2]=$3; nlssrc++ }
      else if($1=="rctcp"){ rctcp_on[$2]=1; nrctcp++ }
      next
    }
    END{
      npass=0; nfail=0; nna=0; nf=0
      for(i=1;i<=nr;i++){
        t=R_type[i]; n=R_name[i]
        if(t=="inetd"){
          if(n in enabled){ st="FAIL"; obs=n" enabled in inetd.conf"; nfail++; nf++; fl[nf]=R_id[i]" "n }
          else { st="PASS"; obs=n" not enabled in inetd.conf"; npass++ }
        }
        else if(t=="lssrc"){
          if(nlssrc==0){ st="NA"; obs=n" (lssrc unreadable)"; nna++ }
          else if(n in state){
            if(state[n]=="active"){ st="FAIL"; obs=n" active"; nfail++; nf++; fl[nf]=R_id[i]" "n }
            else { st="PASS"; obs=n" "state[n]; npass++ }
          }
          else { st="PASS"; obs=n" not defined"; npass++ }
        }
        else if(t=="rctcp"){
          if(n in rctcp_on){ st="FAIL"; obs=n" starts at boot in /etc/rc.tcpip"; nfail++; nf++; fl[nf]=R_id[i]" "n }
          else { st="PASS"; obs=n" not started in /etc/rc.tcpip"; npass++ }
        }
        else { st="NA"; obs=n" unknown type"; nna++ }
        print "stig:" R_id[i] "|" st "|" obs
      }
      flist=""; for(i=1;i<=nf && i<=5;i++) flist=flist (i>1?", ":"") fl[i]
      if(nf>5) flist=flist ", +" (nf-5) " more"
      printf "SUMMARY\t%d\t%d\t%d\t%s\n", npass, nfail, nna, flist
    }
  ')

  DETAIL=$(printf '%s\n' "$RAW" | grep -v '^SUMMARY')
  SUM=$(printf '%s\n' "$RAW" | awk -F'\t' '$1=="SUMMARY"{print; exit}')
  NPASS=$(printf '%s' "$SUM" | awk -F'\t' '{print $2+0}')
  NFAIL=$(printf '%s' "$SUM" | awk -F'\t' '{print $3+0}')
  NNA=$(printf '%s' "$SUM" | awk -F'\t' '{print $4+0}')
  FLIST=$(printf '%s' "$SUM" | awk -F'\t' '{print $5}')
  NAPPLIC=$(( NPASS + NFAIL ))
  CTLS=$(printf '%s\n' "$DETAIL" | awk -F'|' 'NF>=3 && $1!=""{printf "%s%s",(n++?" ":""),$1}')

  if [ "$NAPPLIC" -eq 0 ]; then
    ST=WARN; SEV=med
    OBS="n/a"
    MEAN="Could not read the service inventory (/etc/inetd.conf, /etc/rc.tcpip, and lssrc -a); no STIG disabled-service rule could be assessed on this run."
    FIX="verify /etc/inetd.conf and /etc/rc.tcpip are readable and the SRC is running; or inspect 'lssrc -a' manually."
  elif [ "$NFAIL" -gt 0 ]; then
    ST=FAIL; SEV=high
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a; failing: $FLIST"
    MEAN="One or more legacy network services the DISA STIG for IBM AIX 7.x requires disabled are still enabled or running — each is an unneeded, often unauthenticated, network-facing daemon an auditor will flag."
    FIX="comment the service out of /etc/inetd.conf and 'refresh -s inetd' (inetd services), use 'chrctcp -d <daemon>' (/etc/rc.tcpip daemons), or 'stopsrc -s <subsystem>' and disable it at boot (SRC subsystems); the compliance report lists every rule and its evidence."
  else
    ST=PASS; SEV=med
    OBS="$NPASS of $NAPPLIC rules compliant, $NNA n/a"
    MEAN="Every legacy network service the DISA STIG for IBM AIX 7.x requires disabled is off on this box."
    FIX="n/a"
  fi
  add security stig_svcoff "STIG disabled services" "$ST" "$SEV" "$OBS" "$MEAN" "$FIX" "$CTLS"
  F_RULES[$((NFIND-1))]="$DETAIL"

_AIXRAY_SESSION_KEYS=""
  # nfs_exports — unsafe root/anonymous mappings and unrestricted writable exports.
  # All reads are fixture-routed and side-effect free. In particular, exportfs is
  # deliberately invoked without arguments: that form only lists /etc/xtab.
  typeset NFS_CONFIG_EXISTS_OUT NFS_CONFIG_EXISTS_RC
  typeset NFS_CONFIG NFS_CONFIG_RC NFS_LIVE NFS_LIVE_RC
  typeset NFS_CONFIG_LINES NFS_LIVE_LINES NFS_CONFIG_COUNT NFS_LIVE_COUNT
  typeset NFS_LINES NFS_ASSESS NFS_HIGH_COUNT NFS_MED_COUNT NFS_RO_COUNT
  typeset NFS_RO_UNRESTRICTED_COUNT NFS_GAP_COUNT
  typeset NFS_TOTAL_COUNT NFS_EVIDENCE NFS_GAP_EVIDENCE
  typeset NFS_CONFIGURED_ONLY NFS_LIVE_NO_EXPORTS NFS_LIVE_COMMENT_ONLY
  typeset NFS_LIVE_UNASSESSED NFS_CONFIG_ABSENT NFS_CONFIG_UNREADABLE
  typeset NFS_LIVE_GAP_REASON NFS_OBS NFS_PARTIAL_NOTE

  # test -e also returns 1 for some stat failures (for example an inaccessible
  # parent or dangling symlink); the exact live exportfs sentinel below is the
  # independent backstop that prevents active exports from being called clean.
  NFS_CONFIG_EXISTS_OUT=$(aix etc_exports_exists test -e /etc/exports)
  NFS_CONFIG_EXISTS_RC=$?
  NFS_CONFIG=$(aix etc_exports cat /etc/exports); NFS_CONFIG_RC=$?
  NFS_LIVE=$(aix exportfs exportfs); NFS_LIVE_RC=$?
  NFS_CONFIG_ABSENT=0
  NFS_CONFIG_UNREADABLE=0
  if [ "$NFS_CONFIG_RC" -ne 0 ]; then
    if [ "$NFS_CONFIG_EXISTS_RC" -eq 1 ]; then
      NFS_CONFIG_ABSENT=1
    elif [ "$NFS_CONFIG_EXISTS_RC" -eq 0 ]; then
      NFS_CONFIG_UNREADABLE=1
    fi
  fi
  NFS_LIVE_NO_EXPORTS=0
  if [ "$NFS_LIVE_RC" -eq 0 ] &&
      [ "$NFS_LIVE" = "exportfs: nothing exported" ]; then
    NFS_LIVE_NO_EXPORTS=1
  fi

  NFS_CONFIG_LINES=""
  if [ "$NFS_CONFIG_RC" -eq 0 ]; then
    NFS_CONFIG_LINES=$(printf '%s\n' "$NFS_CONFIG" | awk '
      {
        raw=$0
        parsed=$0
        sub(/[ \t]*#.*/, "", parsed)
        if (parsed !~ /^[ \t]*$/) print raw
      }
    ')
  fi
  NFS_LIVE_LINES=""
  if [ "$NFS_LIVE_RC" -eq 0 ] && [ "$NFS_LIVE_NO_EXPORTS" -ne 1 ]; then
    NFS_LIVE_LINES=$(printf '%s\n' "$NFS_LIVE" | awk '
      {
        raw=$0
        parsed=$0
        sub(/[ \t]*#.*/, "", parsed)
        if (parsed !~ /^[ \t]*$/) print raw
      }
    ')
  fi

  NFS_CONFIG_COUNT=$(printf '%s\n' "$NFS_CONFIG_LINES" \
    | awk 'NF {n++} END {print n+0}')
  NFS_LIVE_COUNT=$(printf '%s\n' "$NFS_LIVE_LINES" \
    | awk 'NF {n++} END {print n+0}')
  NFS_LIVE_COMMENT_ONLY=0
  if [ "$NFS_LIVE_RC" -eq 0 ] && [ "$NFS_LIVE_NO_EXPORTS" -ne 1 ] &&
      [ "$NFS_LIVE_COUNT" -eq 0 ]; then
    NFS_LIVE_COMMENT_ONLY=$(printf '%s\n' "$NFS_LIVE" | awk '
      {
        text=$0
        sub(/^[ \t]*/, "", text)
        if (text == "") next
        nonblank=1
        if (text !~ /^#/) noncomment=1
      }
      END {print (nonblank && !noncomment) ? 1 : 0}
    ')
  fi
  NFS_LIVE_UNASSESSED=0
  NFS_LIVE_GAP_REASON=""
  if [ "$NFS_LIVE_RC" -eq 0 ] && [ "$NFS_LIVE_NO_EXPORTS" -ne 1 ] &&
      [ "$NFS_LIVE_COMMENT_ONLY" -ne 1 ] && [ "$NFS_LIVE_COUNT" -eq 0 ]; then
    NFS_LIVE_UNASSESSED=1
    if [ -z "$NFS_LIVE" ]; then
      NFS_LIVE_GAP_REASON="not assessed — current exportfs listing was empty (rc=0)"
    else
      NFS_LIVE_GAP_REASON="not assessed — current exportfs listing contained no classifiable export rows (rc=0)"
    fi
  fi
  NFS_LINES=$(printf '%s\n%s\n' "$NFS_CONFIG_LINES" "$NFS_LIVE_LINES" \
    | awk 'NF && !seen[$0]++ {print}')

  NFS_ASSESS=$(printf '%s\n' "$NFS_LINES" | awk '
    function valid_ipv4(value, octet, count, i) {
      count=split(value, octet, ".")
      if (count != 4) return 0
      for (i=1; i<=4; i++) {
        if (octet[i] !~ /^[0-9][0-9]*$/) return 0
        if ((octet[i] + 0) < 0 || (octet[i] + 0) > 255) return 0
      }
      return 1
    }
    function unsafe_root_list(value, client, count, i) {
      if (value == "") return 1
      count=split(value, client, ":")
      for (i=1; i<=count; i++) {
        if (client[i] == "") return 1
        # AIX subnet designators begin with @ and include a mask. Prefix-@
        # netgroup forms are likewise not a specific, locally-proven host.
        if (client[i] ~ /^@/ || client[i] ~ /\//) return 1
        if (client[i] ~ /[*?]/) return 1
        if (client[i] ~ /^[0-9.]+$/) {
          if (!valid_ipv4(client[i])) return 1
        } else if (client[i] !~ /^[a-z0-9][a-z0-9_.-]*$/) {
          return 1
        }
      }
      return 0
    }
    {
      row++
      raw[row]=$0
      text=$0
      sub(/[ \t]*#.*/, "", text)
      if (text ~ /^[ \t]*$/) next
      sub(/^[ \t]+/, "", text)
      sub(/[ \t]+$/, "", text)
      gsub(/[ \t]*=[ \t]*/, "=", text)
      normalized[row]=text
      if (text !~ /^\/[^ \t]*([ \t]+-[^ \t].*)?$/) {
        grade[row]="U"
        next
      }

      count=split(text, field, /[ \t]+/)
      path[row]=field[1]
      if (definition[path[row]] != "" &&
          definition[path[row]] != normalized[row]) {
        conflict[path[row]]=1
      } else {
        definition[path[row]]=normalized[row]
      }

      option_text=tolower(text)
      count=split(option_text, option, /[[:space:],]+/)
      has_ro=0
      has_rw=0
      has_access=0
      unsafe_root=0
      unsafe_anon=0
      malformed=0
      for (i=1; i<=count; i++) {
        item=option[i]
        sub(/^-+/, "", item)
        if (item == "ro" || item ~ /^ro=/) has_ro=1
        if (item == "rw" || item ~ /^rw=/) has_rw=1
        if (item ~ /^access=/) {
          if (substr(item, 8) == "") malformed=1
          else has_access=1
        }
        if (item == "anon=0") unsafe_anon=1
        if (item ~ /^root=/ && unsafe_root_list(substr(item, 6))) {
          unsafe_root=1
        }
      }
      if (malformed || (has_ro && has_rw)) grade[row]="U"
      else if (unsafe_root || unsafe_anon) grade[row]="H"
      else if (has_ro && !has_access) grade[row]="O"
      else if ((has_rw || !has_ro) && !has_access) grade[row]="M"
      else if (has_ro) grade[row]="R"
      else grade[row]="W"
    }
    END {
      for (i=1; i<=row; i++) {
        if (path[i] != "" && conflict[path[i]]) grade[i]="C"
        if (grade[i] != "") print grade[i] "\t" raw[i]
      }
    }
  ')

  NFS_HIGH_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="H" {n++} END {print n+0}')
  NFS_MED_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="M" {n++} END {print n+0}')
  NFS_RO_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="R" {n++} END {print n+0}')
  NFS_RO_UNRESTRICTED_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="O" {n++} END {print n+0}')
  NFS_GAP_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="U" || $1=="C" {n++} END {print n+0}')
  NFS_TOTAL_COUNT=$(printf '%s\n' "$NFS_ASSESS" \
    | awk -F '\t' '$1=="H" || $1=="M" || $1=="O" ||
        $1=="R" || $1=="W" {n++} END {print n+0}')
  NFS_EVIDENCE=$(printf '%s\n' "$NFS_ASSESS" | awk -F '\t' '
    $1=="H" || $1=="M" || $1=="O" {
      total++
      if (shown < 20) {
        print substr($0, 3)
        shown++
      }
    }
    END {
      if (total > 20) {
        printf "%d additional offending line(s) omitted (cap 20)", total-20
      }
    }
  ')
  NFS_GAP_EVIDENCE=$(printf '%s\n' "$NFS_ASSESS" | awk -F '\t' '
    $1=="C" {
      raw=substr($0, 3)
      split(raw, field, /[ \t]+/)
      if (!conflict_seen[field[1]]++) {
        print "conflicting NFS export definitions for " field[1]
      }
      print raw
      next
    }
    $1=="U" {
      print "unclassified NFS export line: " substr($0, 3)
    }
  ')

  NFS_CONFIGURED_ONLY=0
  if [ "$NFS_CONFIG_RC" -eq 0 ] && [ "$NFS_LIVE_RC" -eq 0 ] \
      && [ "$NFS_CONFIG_COUNT" -gt 0 ] &&
      { [ "$NFS_LIVE_NO_EXPORTS" -eq 1 ] ||
        [ "$NFS_LIVE_COMMENT_ONLY" -eq 1 ]; }; then
    NFS_CONFIGURED_ONLY=1
  fi

  NFS_PARTIAL_NOTE=""
  if [ "$NFS_CONFIG_ABSENT" -eq 1 ] && [ "$NFS_LIVE_RC" -eq 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — /etc/exports is absent; live exportfs evidence follows"
  elif [ "$NFS_CONFIG_UNREADABLE" -eq 1 ] && [ "$NFS_LIVE_RC" -eq 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — /etc/exports read failed; live exportfs evidence follows"
  elif [ "$NFS_CONFIG_RC" -ne 0 ] && [ "$NFS_LIVE_RC" -eq 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — /etc/exports existence and read state could not be established; live exportfs evidence follows"
  elif [ "$NFS_CONFIG_RC" -eq 0 ] && [ "$NFS_LIVE_RC" -ne 0 ]; then
    NFS_PARTIAL_NOTE="partially assessed — current exportfs listing failed; configured /etc/exports evidence follows"
  elif [ "$NFS_CONFIG_RC" -eq 0 ] && [ "$NFS_LIVE_UNASSESSED" -eq 1 ]; then
    NFS_PARTIAL_NOTE="partially assessed — current exportfs listing had no classifiable evidence (rc=0); configured /etc/exports evidence follows"
  fi

  if [ "$NFS_GAP_COUNT" -gt 0 ]; then
    NFS_OBS="not assessed — NFS export evidence was conflicting or unparseable (etc_exports rc=$NFS_CONFIG_RC; exportfs rc=$NFS_LIVE_RC)"
    NFS_OBS="${NFS_OBS}:
${NFS_GAP_EVIDENCE}"
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "$NFS_OBS" \
        "At least one non-comment evidence line was not exactly a /path [-options] export definition, or the same path had conflicting definitions, so PTxray cannot claim the export set was safely assessed." \
        "inspect /etc/exports and the no-argument exportfs listing, resolve conflicting definitions or diagnostics, then rerun PTxray." "cis-l1"
  elif [ "$NFS_HIGH_COUNT" -gt 0 ]; then
    NFS_OBS=$NFS_EVIDENCE
    if [ -n "$NFS_PARTIAL_NOTE" ]; then
      NFS_OBS="${NFS_PARTIAL_NOTE}
${NFS_OBS}"
    fi
    if [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
      NFS_OBS="${NFS_OBS}
configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports"
    fi
    add security nfs_exports "NFS exports" FAIL high "$NFS_OBS" \
        "One or more NFS export definitions map anonymous requests to UID 0 or grant root privileges beyond a specific host or IP address." \
        "remove anon=0 and restrict every root= list to explicit trusted hostnames or IP addresses; then re-export the corrected definitions during an approved change." "cis-l1"
  elif [ "$NFS_MED_COUNT" -gt 0 ] ||
      [ "$NFS_RO_UNRESTRICTED_COUNT" -gt 0 ]; then
    NFS_OBS=$NFS_EVIDENCE
    if [ -n "$NFS_PARTIAL_NOTE" ]; then
      NFS_OBS="${NFS_PARTIAL_NOTE}
${NFS_OBS}"
    fi
    if [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
      NFS_OBS="${NFS_OBS}
configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports"
    fi
    add security nfs_exports "NFS exports" WARN med "$NFS_OBS" \
        "One or more exports have no access= client restriction. Writable or default-mode exports expose writes, while read-only exports remain mountable by any client that can reach the NFS service." \
        "add an explicit access= host list and use ro unless the clients genuinely require writes; re-export only through the normal approved change process." "cis-l1"
  elif [ "$NFS_CONFIG_ABSENT" -eq 1 ] &&
      [ "$NFS_LIVE_RC" -eq 0 ] && [ "$NFS_LIVE_NO_EXPORTS" -eq 1 ]; then
    add security nfs_exports "NFS exports" PASS high \
        "this host exports no filesystems" \
        "No /etc/exports definition file exists and the current exportfs listing confirms that nothing is exported." \
        "n/a" "cis-l1"
  elif [ "$NFS_CONFIG_UNREADABLE" -eq 1 ] &&
      [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — both NFS evidence reads failed (/etc/exports exit=$NFS_CONFIG_RC; exportfs exit=$NFS_LIVE_RC)" \
        "Neither configured nor current NFS export evidence was readable, so absence of exports and safe export options cannot be established." \
        "restore read access to /etc/exports and the no-argument exportfs listing, then re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_ABSENT" -eq 1 ] && [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports is absent and the current exportfs listing failed (exit=$NFS_LIVE_RC)" \
        "Neither dormant export definitions nor the active export set could be established." \
        "determine whether this host should have an /etc/exports definition file, restore access to the no-argument exportfs listing, and re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_RC" -ne 0 ] && [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports existence and read state could not be established (existence exit=$NFS_CONFIG_EXISTS_RC; read exit=$NFS_CONFIG_RC), and exportfs failed (exit=$NFS_LIVE_RC)" \
        "The definition-file state and current NFS export set are both unknown." \
        "verify whether /etc/exports exists, establish the no-argument exportfs listing, and re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_ABSENT" -eq 1 ] && [ "$NFS_LIVE_COUNT" -gt 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports is absent while the current exportfs listing contains $NFS_LIVE_COUNT active export line(s)" \
        "Active exports were observed, but without the definition file PTxray cannot establish whether dormant exports exist or whether definitions are managed elsewhere." \
        "determine how this host's active NFS exports are managed; restore or recreate /etc/exports if appropriate, then re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_ABSENT" -eq 1 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports is absent; the current exportfs evidence did not establish the exact no-export state" \
        "The definition file is missing and the live evidence was not sufficient to prove that this host exports no filesystems." \
        "determine whether this host should have an /etc/exports definition file, verify the complete no-argument exportfs output, and re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_UNREADABLE" -eq 1 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports read failed (exit=$NFS_CONFIG_RC); no unsafe option was established from the current exportfs listing" \
        "The live listing alone did not establish an unsafe export, but unreadable configuration can contain dormant definitions that later become active." \
        "restore read access to /etc/exports and re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIG_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — /etc/exports existence and read state could not be established (existence exit=$NFS_CONFIG_EXISTS_RC; read exit=$NFS_CONFIG_RC)" \
        "The live listing alone did not establish an unsafe export, and the configured export state remains unknown." \
        "verify whether /etc/exports exists and can be captured, then re-run PTxray." "cis-l1"
  elif [ "$NFS_LIVE_RC" -ne 0 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "not assessed — current exportfs listing failed (exit=$NFS_LIVE_RC); no unsafe option was established from /etc/exports" \
        "The configuration alone did not establish an unsafe export, but the unreadable live listing can contain currently exported state not represented by that file." \
        "restore access to the no-argument exportfs listing and re-run PTxray." "cis-l1"
  elif [ "$NFS_LIVE_UNASSESSED" -eq 1 ]; then
    add security nfs_exports "NFS exports" NOT_ASSESSED high \
        "$NFS_LIVE_GAP_REASON; no unsafe option was established from /etc/exports" \
        "A successful live-listing capture must contain export rows or the exact AIX no-export sentinel before absence of current exports can be established." \
        "rerun the no-argument exportfs listing, verify its complete stdout and return code, then re-run PTxray." "cis-l1"
  elif [ "$NFS_CONFIGURED_ONLY" -eq 1 ]; then
    add security nfs_exports "NFS exports" WARN low \
        "configured-but-not-live: $NFS_CONFIG_COUNT uncommented /etc/exports line(s); exportfs listed no current exports" \
        "NFS exports are configured but were not present in the current exportfs listing; the configuration can become live when NFS is started or exports are refreshed." \
        "confirm whether these exports are intentionally dormant; remove stale definitions or activate only the intended host-restricted exports during an approved change." "cis-l1"
  elif [ "$NFS_TOTAL_COUNT" -eq 0 ] &&
      { [ "$NFS_LIVE_NO_EXPORTS" -eq 1 ] ||
        [ "$NFS_LIVE_COMMENT_ONLY" -eq 1 ]; }; then
    add security nfs_exports "NFS exports" PASS high \
        "NFS server not exporting" \
        "No uncommented configured export and no current exportfs entry was observed." \
        "n/a" "cis-l1"
  elif [ "$NFS_RO_COUNT" -eq "$NFS_TOTAL_COUNT" ]; then
    add security nfs_exports "NFS exports" PASS high \
        "$NFS_TOTAL_COUNT export line(s) assessed; read-only and host-restricted by parsed access= lists" \
        "Every observed export is read-only, client-restricted, and has no unsafe root or anonymous UID 0 mapping." \
        "n/a" "cis-l1"
  else
    add security nfs_exports "NFS exports" PASS high \
        "$NFS_TOTAL_COUNT export line(s) assessed; host-restricted by parsed access= lists; $NFS_RO_COUNT read-only" \
        "Every observed export has a non-empty access= client list, and no export grants root broadly or maps anonymous requests to UID 0." \
        "n/a" "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
  # ssh_banner — assess the global Banner from `sshd -T`, then prove its file.
  typeset SSH_BANNER_RAW SSH_BANNER_CAPTURE_RC SSH_BANNER_PARSED
  typeset SSH_BANNER_PATH SSH_BANNER_STATUS SSH_BANNER_OBSERVED
  typeset SSH_BANNER_MEANING SSH_BANNER_FIX SSH_BANNER_REASON
  typeset SSH_BANNER_STAT SSH_BANNER_STAT_RC SSH_BANNER_STAT_LINES
  typeset SSH_BANNER_MODE SSH_BANNER_MODE_VALID SSH_BANNER_FIRST_CHAR
  typeset SSH_BANNER_LAST_FIELD
  SSH_BANNER_STATUS=NOT_ASSESSED
  SSH_BANNER_OBSERVED=''
  SSH_BANNER_MEANING='PTxray did not obtain trustworthy global effective Banner and regular-file evidence, so it cannot establish a usable pre-authentication banner.'
  SSH_BANNER_FIX='run sshd -T as root, resolve any configuration or host-key error, verify the effective banner target, and rerun PTxray.'
  SSH_BANNER_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    SSH_BANNER_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      SSH_BANNER_RAW=$SSHT
      SSH_BANNER_CAPTURE_RC=$SSHT_RC
    else
      SSH_BANNER_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_BANNER_CAPTURE_RC=$?
    fi
    if [ "$SSH_BANNER_CAPTURE_RC" -ne 0 ]; then
      SSH_BANNER_REASON="sshd -T failed (rc=$SSH_BANNER_CAPTURE_RC)"
    elif [ -z "$SSH_BANNER_RAW" ]; then
      SSH_BANNER_REASON='sshd -T returned empty output'
    else
      SSH_BANNER_PARSED=$(printf '%s\n' "$SSH_BANNER_RAW" | awk '
        $1 == "banner" {
          count++
          if (NF != 2) invalid=1
          else value=$2
        }
        END {
          if (count != 1) print "__COUNT__"
          else if (invalid || value == "") print "__INVALID__"
          else print value
        }')
      case "$SSH_BANNER_PARSED" in
        __COUNT__)
          SSH_BANNER_REASON='effective row is missing or duplicate'
          ;;
        __INVALID__)
          SSH_BANNER_REASON='effective value is unparseable'
          ;;
        none)
          SSH_BANNER_STATUS=FAIL
          SSH_BANNER_OBSERVED='Banner none'
          SSH_BANNER_MEANING='sshd has no usable regular-file pre-authentication banner configured.'
          SSH_BANNER_FIX="configure an approved absolute Banner file, validate the global effective path with 'sshd -T', and restart sshd; PTxray only recommends these actions."
          ;;
        /*)
          SSH_BANNER_PATH=$SSH_BANNER_PARSED
          SSH_BANNER_STAT=$(aix ssh_banner_file ls -ld "$SSH_BANNER_PATH") # network-lint: allow -- reads LOCAL file metadata for the exact effective Banner path
          SSH_BANNER_STAT_RC=$?
          if [ "$SSH_BANNER_STAT_RC" -ne 0 ]; then
            SSH_BANNER_REASON="file metadata capture failed (rc=$SSH_BANNER_STAT_RC)"
          elif [ -z "$SSH_BANNER_STAT" ]; then
            SSH_BANNER_REASON='file metadata capture returned empty output'
          else
            SSH_BANNER_STAT_LINES=$(printf '%s\n' "$SSH_BANNER_STAT" |
              awk 'NF {count++} END {print count+0}')
            SSH_BANNER_MODE=$(printf '%s\n' "$SSH_BANNER_STAT" |
              awk 'NF {print $1; exit}')
            SSH_BANNER_FIRST_CHAR=$(printf '%s\n' "$SSH_BANNER_MODE" |
              awk '{print substr($1,1,1)}')
            SSH_BANNER_LAST_FIELD=$(printf '%s\n' "$SSH_BANNER_STAT" |
              awk 'NF {print $NF; exit}')
            case "$SSH_BANNER_MODE" in
              [bcdlps-][r-][w-][xSsTt-][r-][w-][xSsTt-][r-][w-][xTt-])
                SSH_BANNER_MODE_VALID=1
                ;;
              *)
                SSH_BANNER_MODE_VALID=0
                ;;
            esac
            if [ "$SSH_BANNER_STAT_LINES" -ne 1 ]; then
              SSH_BANNER_REASON="file metadata output has $SSH_BANNER_STAT_LINES lines, expected one"
            elif [ "$SSH_BANNER_MODE_VALID" -ne 1 ]; then
              SSH_BANNER_REASON='file metadata capture returned unrelated output'
            elif [ "$SSH_BANNER_FIRST_CHAR" != "-" ]; then
              SSH_BANNER_STATUS=FAIL
              SSH_BANNER_OBSERVED="Banner $SSH_BANNER_PATH; target exists but is not a regular file"
              SSH_BANNER_MEANING='sshd has no usable regular-file pre-authentication banner configured.'
              SSH_BANNER_FIX='replace the effective Banner target with an approved regular file, validate sshd_config, and restart sshd; PTxray only recommends these actions.'
            elif [ "$SSH_BANNER_LAST_FIELD" != "$SSH_BANNER_PATH" ]; then
              SSH_BANNER_STATUS=FAIL
              SSH_BANNER_OBSERVED="Banner $SSH_BANNER_PATH; file metadata path mismatch"
              SSH_BANNER_MEANING='sshd has no positively identified regular-file pre-authentication banner target.'
              SSH_BANNER_FIX='inspect the effective Banner path and target metadata, correct the mismatch, and rerun PTxray.'
            else
              SSH_BANNER_STATUS=PASS
              SSH_BANNER_OBSERVED="Banner $SSH_BANNER_PATH; regular file present"
              SSH_BANNER_MEANING='sshd is configured to display an existing regular-file banner before authentication.'
              SSH_BANNER_FIX='n/a'
            fi
          fi
          ;;
        *)
          SSH_BANNER_PATH=$SSH_BANNER_PARSED
          SSH_BANNER_STATUS=FAIL
          SSH_BANNER_OBSERVED="Banner $SSH_BANNER_PATH; relative path is misconfiguration"
          SSH_BANNER_MEANING='sshd has no usable regular-file pre-authentication banner configured.'
          SSH_BANNER_FIX='set Banner to an approved absolute regular-file path, validate sshd_config, and restart sshd; PTxray only recommends these actions.'
          ;;
      esac
    fi
  fi

  if [ "$SSH_BANNER_STATUS" = NOT_ASSESSED ]; then
    SSH_BANNER_OBSERVED="not assessed — Banner $SSH_BANNER_REASON"
  fi
  add security ssh_banner "SSH pre-authentication banner" "$SSH_BANNER_STATUS" low \
      "$SSH_BANNER_OBSERVED" "$SSH_BANNER_MEANING" "$SSH_BANNER_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # secure_by_default — CIS IBM AIX 7 v1.2.0 1.3.4.1 (Level 1): was Secure by
  # Default (SbD) selected when this system was installed? SbD installs a
  # minimal software set in a secure configuration: LIGHTER bos.net.tcp.client
  # and bos.net.tcp.server filesets that exclude telnet, ftp, rsh, rcp and # network-lint: allow -- prose comment, no network call
  # sendmail, followed at first boot by # network-lint: allow -- prose comment, no network call
  #   /usr/sbin/aixpert -f /etc/security/aixpert/core/SbD.xml -p \
  #     2>/etc/security/aixpert/log/firstboot.log
  #
  # THE BENCHMARK SPECIFIES NO AUDIT PROCEDURE FOR THIS CONTROL — its Audit
  # section is empty. Everything below is PowerTrue-authored inference from the
  # control's Description; see this check's README before trusting a verdict.
  #
  # Two independent evidence classes:
  #   class 1 (applied-profile, the DISCRIMINATOR) — did the SbD firstboot step
  #     run? /etc/security/aixpert/log/firstboot.log is created by nothing else,
  #     and /etc/firstboot carries the aixpert SbD.xml invocation itself.
  #   class 2 (fileset content, CORROBORATING) — are the excluded binaries and
  #     the filesets that own them absent from the installed software set?
  # Class 2 can never establish the control on its own: an administrator who
  # removed telnet by hand after a normal install produces exactly the same # network-lint: allow -- prose comment, no network call
  # binary-absence picture as SbD. Class 2 therefore only DISPROVES (excluded
  # software found -> not SbD) or corroborates; only class 1 can produce PASS.
  #
  # aix vs aixv: probes 1-3 all need stderr, because the diagnostic is the only
  # thing separating "determinately absent" from "unreadable to this identity",
  # and those two states carry different verdicts. Probe 4 goes through aix():
  # the fileset inventory needs no diagnostic (lslpp -L rc alone settles it) and
  # the lslpp_L_all key is shared with ck-nfs-server-absent, which captures it
  # through aix() — using aixv() here would not change replay but would make the
  # shared key's capture contract ambiguous.
  typeset SBD_LOGDIR_RAW SBD_LOGDIR_RC SBD_LOGDIR_HIT
  typeset SBD_FIRSTBOOT_RAW SBD_FIRSTBOOT_RC SBD_FIRSTBOOT_HIT
  typeset SBD_BIN_RAW SBD_BIN_RC SBD_BIN_RAN SBD_BIN_TOKEN SBD_BIN_REST
  typeset SBD_BIN_PRESENT_N SBD_BIN_LIST
  typeset SBD_LPP_RAW SBD_LPP_RC SBD_LPP_TOKEN SBD_LPP_REST
  typeset SBD_LPP_N SBD_LPP_PAIR SBD_LPP_LIST
  typeset SBD_BIN_ABSENT_N SBD_BIN_UNKNOWN_N
  typeset SBD_CLASS1 SBD_CLASS1_WHY SBD_CLASS2
  typeset SBD_EXCL_N SBD_EXCL_LIST SBD_EVIDENCE
  typeset SBD_STATUS SBD_OBS SBD_MEAN SBD_FIX

  SBD_LOGDIR_RAW=""
  SBD_LOGDIR_RC=127
  SBD_LOGDIR_HIT=0
  SBD_FIRSTBOOT_RAW=""
  SBD_FIRSTBOOT_RC=127
  SBD_FIRSTBOOT_HIT=0
  SBD_BIN_RAW=""
  SBD_BIN_RC=127
  SBD_BIN_RAN=0
  SBD_BIN_TOKEN=""
  SBD_BIN_REST=""
  SBD_BIN_PRESENT_N=0
  SBD_BIN_ABSENT_N=0
  SBD_BIN_UNKNOWN_N=0
  SBD_BIN_LIST=""
  SBD_LPP_RAW=""
  SBD_LPP_RC=127
  SBD_LPP_TOKEN=""
  SBD_LPP_REST=""
  SBD_LPP_N=0
  SBD_LPP_PAIR=0
  SBD_LPP_LIST=""
  SBD_CLASS1=UNKNOWN
  SBD_CLASS1_WHY=""
  SBD_CLASS2=UNKNOWN
  SBD_EXCL_N=0
  SBD_EXCL_LIST=""
  SBD_EVIDENCE=""
  SBD_STATUS=""
  SBD_OBS=""
  SBD_MEAN=""
  SBD_FIX=""

  # Probe 1 — the aixpert log DIRECTORY, not the log file. Listing the parent
  # is what makes an absent firstboot.log trustworthy: if the directory itself
  # is unreadable, ls on the file inside it can report "not found" for a file
  # that exists, and that would manufacture a determinate negative out of a
  # permission problem.
  SBD_LOGDIR_RAW=$(aixv sbd_aixpert_log_dir ls -l /etc/security/aixpert/log)
  SBD_LOGDIR_RC=$?

  # Probe 2 — the firstboot script that runs the SbD profile. grep separates
  # "read it, no aixpert step" (rc 1) from "could not read it" (rc 2), and the
  # merged stderr names which of the two a non-zero rc actually was.
  SBD_FIRSTBOOT_RAW=$(aixv sbd_firstboot_aixpert grep -n aixpert /etc/firstboot)
  SBD_FIRSTBOOT_RC=$?

  # Probe 3 — the excluded binaries. ls exits non-zero when ANY operand is
  # missing, which on a compliant SbD box is the expected case, so the per-path
  # verdict is read out of the merged stream and never off the rc.
  SBD_BIN_RAW=$(aixv sbd_cleartext_binaries ls -l /usr/bin/telnet /usr/bin/ftp /usr/bin/rsh /usr/bin/rcp /usr/sbin/sendmail) # network-lint: allow -- aixv() runs the LOCAL ls on excluded binary paths; ls makes no network call
  SBD_BIN_RC=$?
  # ls itself only ever exits 0, 1 or 2. Any other value means the probe never
  # ran (127 under fixture replay of a key this capture does not carry), and
  # nothing may be concluded from its empty output.
  SBD_BIN_RAN=0
  case "$SBD_BIN_RC" in
    0|1|2) SBD_BIN_RAN=1 ;;
  esac

  # Probe 4 — the installed software inventory. Modern AIX splits the TCP/IP
  # client and server into per-application filesets (bos.net.tcp.telnet, # network-lint: allow -- prose comment, no network call
  # .ftp, .rcmd, .sendmail, ...); on the 2026-08-06 lab captures the 7.2 box # network-lint: allow -- prose comment, no network call
  # carries all seven excluded filesets and the 7.3 box carries
  # bos.net.tcp.sendmail. An installed excluded fileset is inventory-level # network-lint: allow -- prose comment, no network call
  # proof the excluded applications are in the software set.
  SBD_LPP_RAW=$(aix lslpp_L_all lslpp -L)
  SBD_LPP_RC=$?

  # ---- class 1: applied-profile evidence ----------------------------------
  if [ "$SBD_LOGDIR_RC" -eq 0 ]; then
    SBD_LOGDIR_HIT=$(printf '%s\n' "$SBD_LOGDIR_RAW" | awk '
      $NF == "firstboot.log" { hit = 1 }
      END { print hit ? 1 : 0 }')
    if [ "$SBD_LOGDIR_HIT" -eq 1 ]; then
      SBD_CLASS1=POSITIVE
      SBD_CLASS1_WHY="firstboot.log present in /etc/security/aixpert/log"
    else
      SBD_CLASS1=NEGATIVE
      SBD_CLASS1_WHY="firstboot.log absent from /etc/security/aixpert/log"
    fi
  else
    # A non-zero rc is only determinate when the diagnostic says the directory
    # is genuinely absent. Anything else (permission, unknown) stays UNKNOWN.
    case "$SBD_LOGDIR_RAW" in
      *"not found"*|*"No such file"*|*"does not exist"*)
        SBD_CLASS1=NEGATIVE
        SBD_CLASS1_WHY="/etc/security/aixpert/log does not exist"
        ;;
    esac
  fi

  # Probe 2 can raise UNKNOWN or NEGATIVE to POSITIVE, and can settle an
  # UNKNOWN as NEGATIVE, but never overrides a positive artifact: an SbD
  # artifact that is present is stronger evidence than another one missing.
  if [ "$SBD_FIRSTBOOT_RC" -eq 0 ]; then
    SBD_FIRSTBOOT_HIT=$(printf '%s\n' "$SBD_FIRSTBOOT_RAW" | awk '
      index($0, "SbD.xml") > 0 { hit = 1 }
      END { print hit ? 1 : 0 }')
    if [ "$SBD_FIRSTBOOT_HIT" -eq 1 ]; then
      SBD_CLASS1=POSITIVE
      SBD_CLASS1_WHY="/etc/firstboot runs aixpert with SbD.xml"
    elif [ "$SBD_CLASS1" = UNKNOWN ]; then
      SBD_CLASS1=NEGATIVE
      SBD_CLASS1_WHY="/etc/firstboot runs aixpert with a profile other than SbD.xml"
    fi
  elif [ "$SBD_FIRSTBOOT_RC" -eq 1 ] && [ "$SBD_CLASS1" = UNKNOWN ]; then
    # grep rc 1 is a determinate "the file was read and nothing matched".
    SBD_CLASS1=NEGATIVE
    SBD_CLASS1_WHY="/etc/firstboot contains no aixpert step"
  fi

  # ---- class 2: fileset-content evidence -----------------------------------
  # Per-path tri-state out of the merged ls stream. A path counts as present
  # only on a mode-prefixed listing line and as absent only on a line whose
  # diagnostic names it; everything else stays unknown for that path.
  # network-lint: allow-next=3 -- the awk program below matches the excluded binary pathnames in captured ls text; no network call
  SBD_BIN_TOKEN=$(printf '%s\n' "$SBD_BIN_RAW" | awk '
    BEGIN {
      n = split("/usr/bin/telnet /usr/bin/ftp /usr/bin/rsh /usr/bin/rcp /usr/sbin/sendmail", want, " ")
      for (i = 1; i <= n; i++) wanted[want[i]] = 1
    }
    {
      if (index($0, "not found") > 0 || index($0, "No such file") > 0 ||
          index($0, "does not exist") > 0) {
        for (f = 1; f <= NF; f++) {
          token = $f
          sub(/[.,:]+$/, "", token)
          if (token in wanted) absent[token] = 1
        }
        next
      }
      if (NF >= 5 && $1 ~ /^[-dlbcps]/) {
        for (f = 1; f <= NF; f++) {
          if ($f in wanted) present[$f] = 1
        }
      }
    }
    END {
      np = 0
      na = 0
      nu = 0
      list = ""
      for (i = 1; i <= n; i++) {
        p = want[i]
        if (p in present) {
          np++
          if (np <= 2) list = (list == "" ? p : list "," p)
        } else if (p in absent) {
          na++
        } else {
          nu++
        }
      }
      print np ":" na ":" nu ":" list
    }')
  SBD_BIN_PRESENT_N=${SBD_BIN_TOKEN%%:*}
  SBD_BIN_REST=${SBD_BIN_TOKEN#*:}
  SBD_BIN_ABSENT_N=${SBD_BIN_REST%%:*}
  SBD_BIN_REST=${SBD_BIN_REST#*:}
  SBD_BIN_UNKNOWN_N=${SBD_BIN_REST%%:*}
  SBD_BIN_LIST=${SBD_BIN_REST#*:}

  # The inventory is trusted only on rc 0; a failed lslpp says nothing.
  if [ "$SBD_LPP_RC" -eq 0 ]; then
    # network-lint: allow-next=3 -- the awk program below matches the excluded fileset names in captured lslpp text; no network call
    SBD_LPP_TOKEN=$(printf '%s\n' "$SBD_LPP_RAW" | awk '
      BEGIN {
        n = split("bos.net.tcp.telnet bos.net.tcp.telnetd bos.net.tcp.ftp bos.net.tcp.ftpd bos.net.tcp.rcmd bos.net.tcp.rcmd_server bos.net.tcp.sendmail", want, " ")
        for (i = 1; i <= n; i++) wanted[want[i]] = 1
      }
      $1 == "bos.net.tcp.client" || $1 == "bos.net.tcp.client_core" { cli = 1 }
      $1 == "bos.net.tcp.server" || $1 == "bos.net.tcp.server_core" { srv = 1 }
      $1 in wanted { found[$1] = 1 }
      END {
        nf = 0
        list = ""
        for (i = 1; i <= n; i++) {
          if (want[i] in found) {
            nf++
            if (nf <= 2) list = (list == "" ? want[i] : list "," want[i])
          }
        }
        print nf ":" ((cli && srv) ? 1 : 0) ":" list
      }')
    SBD_LPP_N=${SBD_LPP_TOKEN%%:*}
    SBD_LPP_REST=${SBD_LPP_TOKEN#*:}
    SBD_LPP_PAIR=${SBD_LPP_REST%%:*}
    SBD_LPP_LIST=${SBD_LPP_REST#*:}
  fi

  SBD_EXCL_N=$((SBD_BIN_PRESENT_N + SBD_LPP_N))
  if [ -n "$SBD_BIN_LIST" ] && [ -n "$SBD_LPP_LIST" ]; then
    SBD_EXCL_LIST="$SBD_BIN_LIST,$SBD_LPP_LIST"
  else
    SBD_EXCL_LIST="$SBD_BIN_LIST$SBD_LPP_LIST"
  fi

  if [ "$SBD_BIN_RAN" -eq 1 ] && [ "$SBD_BIN_PRESENT_N" -gt 0 ]; then
    SBD_CLASS2=PRESENT
  elif [ "$SBD_LPP_RC" -eq 0 ] && [ "$SBD_LPP_N" -gt 0 ]; then
    SBD_CLASS2=PRESENT
  elif [ "$SBD_BIN_RAN" -eq 1 ] && [ "$SBD_BIN_ABSENT_N" -eq 5 ] && \
       [ "$SBD_LPP_RC" -eq 0 ] && [ "$SBD_LPP_PAIR" -eq 1 ]; then
    # Every excluded binary determinately absent, no excluded fileset
    # installed, and the TCP/IP client and server software IS installed — so
    # the absence is an exclusion from the installed set, not an absence of
    # TCP/IP altogether. Corroborating only; this never reaches PASS alone.
    SBD_CLASS2=ABSENT
  fi

  # ---- verdict -------------------------------------------------------------
  # Order matters. Disproof first: excluded software found settles the control
  # whatever the applied-profile evidence says, because an SbD system never
  # carries it. PASS second, and only on class 1. Determinate class-1 absence
  # third — that is the hand-hardened normal install, and it is a FAIL, not a
  # refusal. NOT_ASSESSED last, only when nothing was established.
  if [ "$SBD_CLASS2" = PRESENT ]; then
    SBD_EVIDENCE=$(printf '%s\n' "$SBD_EXCL_LIST" | awk -v total="$SBD_EXCL_N" '
      {
        n = split($0, item, ",")
        shown = 0
        list = ""
        for (i = 1; i <= n; i++) {
          if (item[i] == "") continue
          if (shown >= 2) break
          list = (list == "" ? item[i] : list ", " item[i])
          shown++
        }
        more = total - shown
        text = "SbD-excluded software installed (" total "): " list
        if (more > 0) text = text " +" more " more"
        print text
      }')
    SBD_STATUS=FAIL
    SBD_OBS="$SBD_EVIDENCE"
    SBD_MEAN="Software that a Secure by Default installation never installs is present on this system, so this system was not installed with Secure by Default."
    SBD_FIX="Secure by Default is an installation-time option and cannot be enabled afterwards: rebuild the system with Secure by Default selected, or remove the excluded software and apply /etc/security/aixpert/core/SbD.xml through the approved change process. PTxray recommends these actions and never performs them."
  elif [ "$SBD_CLASS1" = POSITIVE ]; then
    SBD_STATUS=PASS
    SBD_OBS="SbD applied at install: $SBD_CLASS1_WHY"
    SBD_MEAN="The Secure by Default profile was applied by this system's installation, and no software that Secure by Default excludes was found installed."
    SBD_FIX="n/a"
  elif [ "$SBD_CLASS1" = NEGATIVE ]; then
    SBD_STATUS=FAIL
    SBD_OBS="no SbD install evidence: $SBD_CLASS1_WHY"
    SBD_MEAN="No artifact of the Secure by Default first-boot step exists on this system, so Secure by Default was not selected when it was installed. Absence of the excluded binaries alone does not satisfy this control: a normal install hardened by hand looks identical."
    SBD_FIX="Secure by Default is an installation-time option and cannot be enabled afterwards: rebuild the system with Secure by Default selected, or accept the residual risk on the record after confirming the excluded applications are removed and the AIX Security Expert high-level profile is applied. PTxray recommends these actions and never performs them."
  else
    SBD_STATUS=NOT_ASSESSED
    SBD_OBS="not assessed — SbD install evidence unreadable (aixpert log rc=$SBD_LOGDIR_RC, /etc/firstboot rc=$SBD_FIRSTBOOT_RC)"
    SBD_MEAN="Neither the aixpert first-boot log directory nor /etc/firstboot could be read, and no excluded software was found, so whether Secure by Default was selected at installation is unknown."
    SBD_FIX="rerun PTxray with an identity that can read /etc/security/aixpert/log and /etc/firstboot, then rerun the check."
  fi

  add security secure_by_default "Secure by Default installation" \
    "$SBD_STATUS" med "$SBD_OBS" "$SBD_MEAN" "$SBD_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_filesets — CDE (X11.Dt) fileset presence from the package inventory.
  # Publishes CDE_FS_RAW / CDE_FS_RC so later cde_* modules in the monolith
  # reuse one capture; each standalone tool re-captures the same key.
  # An uninstalled fileset query returns rc=1 with empty stdout (stderr is
  # discarded by the capture helper); that pair is positive evidence of
  # absence, not a failed probe.
  typeset CDE_FS_SHAPE CDE_FS_DETAIL CDE_FS_COUNT
  typeset CDE_FS_STATUS CDE_FS_OBSERVED CDE_FS_MEANING CDE_FS_FIX
  CDE_FS_RAW=""
  CDE_FS_RC=126

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_FS_STATUS=NOT_ASSESSED
    CDE_FS_OBSERVED="not assessed - CDE fileset query requires root"
  else
    CDE_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
    CDE_FS_RC=$?
    if [ "$CDE_FS_RC" -eq 1 ] && [ -z "$CDE_FS_RAW" ]; then
      CDE_FS_STATUS=PASS
      CDE_FS_OBSERVED="no X11.Dt fileset in the package inventory (query rc=1, empty)"
    elif [ "$CDE_FS_RC" -eq 0 ] && [ -n "$CDE_FS_RAW" ]; then
      CDE_FS_SHAPE=$(printf '%s\n' "$CDE_FS_RAW" | awk -F: '
        /^[ \t]*$/ { next }
        {
          rows++
          if (NF < 6 || $2 !~ /^X11\.Dt/) { foreign++; next }
          if ($3 !~ /^[0-9][0-9.]*$/) { malformed++; next }
          valid++
          if (valid <= 3) {
            if (detail != "") detail = detail ", "
            detail = detail $2 " " $3
          }
        }
        END {
          if (foreign) print "foreign"
          else if (malformed || valid == 0) print "malformed"
          else print valid ":" detail
        }')
      case "$CDE_FS_SHAPE" in
        foreign)
          CDE_FS_STATUS=NOT_ASSESSED
          CDE_FS_OBSERVED="not assessed - CDE fileset query returned a fileset outside X11.Dt"
          ;;
        malformed)
          CDE_FS_STATUS=NOT_ASSESSED
          CDE_FS_OBSERVED="not assessed - CDE fileset query output was malformed"
          ;;
        *)
          CDE_FS_COUNT=${CDE_FS_SHAPE%%:*}
          CDE_FS_DETAIL=${CDE_FS_SHAPE#*:}
          CDE_FS_STATUS=FAIL
          CDE_FS_OBSERVED="$CDE_FS_COUNT X11.Dt fileset(s) installed, first: $CDE_FS_DETAIL"
          ;;
      esac
    elif [ "$CDE_FS_RC" -eq 0 ]; then
      CDE_FS_STATUS=NOT_ASSESSED
      CDE_FS_OBSERVED="not assessed - CDE fileset query returned rc=0 with empty output"
    elif [ "$CDE_FS_RC" -eq 1 ]; then
      CDE_FS_STATUS=NOT_ASSESSED
      CDE_FS_OBSERVED="not assessed - CDE fileset query returned rc=1 with contradictory output"
    else
      CDE_FS_STATUS=NOT_ASSESSED
      CDE_FS_OBSERVED="not assessed - CDE fileset query failed (rc=$CDE_FS_RC)"
    fi
  fi

  case "$CDE_FS_STATUS" in
    PASS)
      CDE_FS_MEANING="The package inventory contains no CDE component, so the CDE attack surface does not exist on this host."
      CDE_FS_FIX="n/a"
      ;;
    FAIL)
      CDE_FS_MEANING="The legacy CDE desktop is installed; its daemons and setuid binaries have a long history of remotely and locally exploitable defects."
      CDE_FS_FIX="after confirming no workload needs CDE, preview removal with 'installp -up <fileset>' and remove with 'installp -ug <fileset>' for each X11.Dt fileset; PTxray only recommends these actions."
      ;;
    *)
      CDE_FS_MEANING="PTxray did not obtain trustworthy package-inventory evidence for the CDE fileset family."
      CDE_FS_FIX="run \"lslpp -qcL 'X11.Dt*'\" as root, resolve the query or output-shape problem, and rerun PTxray."
      ;;
  esac

  add security cde_filesets "CDE installed filesets" \
    "$CDE_FS_STATUS" med "$CDE_FS_OBSERVED" \
    "$CDE_FS_MEANING" "$CDE_FS_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_cmsd — detect whether the CDE calendar daemon (rpc.cmsd) is active in
  # /etc/inetd.conf.  An active cmsd entry exposes a historically exploitable
  # RPC service; CIS requires it unavailable.  Capture: grep for the exact
  # first-field token cmsd followed by whitespace (not a comment, not a
  # later-field match).
  #
  # Verdict logic:
  #   rc=0  AND  every nonblank row starts with exactly "cmsd "  => FAIL
  #   rc=1  AND  empty output                                    => PASS
  #   anything else                                              => NOT_ASSESSED
