    "$CDE_DTL_STATUS" "$CDE_DTL_SEV" \
    "$CDE_DTL_OBSERVED" \
    "$CDE_DTL_MEANING" \
    "$CDE_DTL_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_dtspc — detect whether the CDE subprocess control service (dtspcd) is active in
