  typeset CDE_DTSPC_STATUS CDE_DTSPC_OBSERVED CDE_DTSPC_MEANING
  typeset CDE_DTSPC_FIX CDE_DTSPC_SEV
  CDE_DTSPC_RC=0
  CDE_DTSPC_RAW=""
  CDE_DTSPC_PARSED="absent"
  CDE_DTSPC_SHAPE=1

