    CDE_DTSPC_PARSED=$(printf '%s\n' "$CDE_DTSPC_RAW" | awk '
      /^[ \t]*$/ { next }
      {
        rows++
        line = $0
        sub(/^[ \t]+/, "", line)
        split(line, fields, /[ \t]+/)
        if (fields[1] != "dtspc") {
          bad_first = 1
        }
        if (NF < 6) {
          malformed++
        }
      }
      END {
        if (bad_first) {
          print "non-dtspc-first"
        } else if (malformed) {
          print "malformed"
        } else if (rows == 1) {
          print "single"
        } else if (rows > 1) {
          print "multiple"
        } else {
          print "absent"
        }
      }')
    case "$CDE_DTSPC_PARSED" in
      single) CDE_DTSPC_SHAPE=1 ;;
      multiple) CDE_DTSPC_SHAPE=1 ;;
      *) CDE_DTSPC_SHAPE=0 ;;
    esac
  fi

