    "$CDE_DTSPC_MEANING" \
    "$CDE_DTSPC_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_dt_binaries — setuid/setgid state of the four CDE binaries the CIS
  # AIX benchmark family locks down.  Probe: one ls -ld over the literal
  # paths.  ls lists the rows it can resolve even when some paths are absent
  # (rc is then nonzero and stderr is discarded), so row content decides;
  # rc!=0 with zero rows, under the root gate, means none of the paths
  # exists — with no CDE binary present, nothing carries setuid/setgid.
  typeset CDE_SUID_RAW CDE_SUID_RC CDE_SUID_SHAPE CDE_SUID_DETAIL
  typeset CDE_SUID_STATUS CDE_SUID_OBSERVED CDE_SUID_MEANING CDE_SUID_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_SUID_STATUS=NOT_ASSESSED
    CDE_SUID_OBSERVED="not assessed - CDE binary probe requires root"
  else
    CDE_SUID_RAW=$(aix cde_dt_binaries ls -ld /usr/dt/bin/dtaction /usr/dt/bin/dtappgather /usr/dt/bin/dtprintinfo /usr/dt/bin/dtsession)
    CDE_SUID_RC=$?
    if [ -n "$CDE_SUID_RAW" ]; then
      CDE_SUID_SHAPE=$(printf '%s\n' "$CDE_SUID_RAW" | awk '
        /^[ \t]*$/ { next }
        {
          rows++
          mode = $1
          path = $NF
          if (path !~ /^\/usr\/dt\/bin\/(dtaction|dtappgather|dtprintinfo|dtsession)$/) { foreign = 1; next }
          if (length("" mode) < 10) { bad = 1; next }
          u = substr(mode, 4, 1)
          g = substr(mode, 7, 1)
          if (u == "s" || u == "S" || g == "s" || g == "S") {
            viol++
            if (viol == 1) first = path " " mode
          } else {
            okc++
          }
        }
        END {
          if (foreign) print "foreign"
          else if (bad) print "malformed"
          else if (viol) print "viol:" viol ":" first
          else if (okc) print "ok:" okc
          else print "none"
        }')
      case "$CDE_SUID_SHAPE" in
        foreign)
          CDE_SUID_STATUS=NOT_ASSESSED
          CDE_SUID_OBSERVED="not assessed - CDE binary probe returned an unexpected path"
          ;;
        malformed)
          CDE_SUID_STATUS=NOT_ASSESSED
          CDE_SUID_OBSERVED="not assessed - CDE binary probe rows were malformed"
          ;;
        none)
          CDE_SUID_STATUS=NOT_ASSESSED
          CDE_SUID_OBSERVED="not assessed - CDE binary probe output held no parseable rows"
          ;;
        viol:*)
          CDE_SUID_DETAIL=${CDE_SUID_SHAPE#viol:}
          CDE_SUID_STATUS=FAIL
          CDE_SUID_OBSERVED="setuid/setgid on ${CDE_SUID_DETAIL%%:*} CDE binarie(s), first: ${CDE_SUID_DETAIL#*:}"
          ;;
        *)
          CDE_SUID_STATUS=PASS
          CDE_SUID_OBSERVED="${CDE_SUID_SHAPE#ok:} CDE binarie(s) present, none setuid or setgid"
          ;;
      esac
    elif [ "$CDE_SUID_RC" -ne 0 ]; then
      CDE_SUID_STATUS=PASS
      CDE_SUID_OBSERVED="no CDE dt binaries present under /usr/dt/bin (probe rc=$CDE_SUID_RC, empty); nothing carries setuid/setgid"
    else
      CDE_SUID_STATUS=NOT_ASSESSED
      CDE_SUID_OBSERVED="not assessed - CDE binary probe returned rc=0 with empty output"
    fi
  fi

  case "$CDE_SUID_STATUS" in
    PASS)
      CDE_SUID_MEANING="No CDE binary offers a setuid/setgid privilege-escalation path."
      CDE_SUID_FIX="n/a"
      ;;
    FAIL)
      CDE_SUID_MEANING="A CDE binary still carries setuid or setgid; CDE suid programs have a history of local privilege-escalation defects."
      CDE_SUID_FIX="after confirming no CDE workflow needs the bit, remove it with 'chmod ug-s <path>' per listed binary; PTxray only recommends this action."
      ;;
    *)
      CDE_SUID_MEANING="PTxray did not obtain trustworthy file-mode evidence for the CDE binaries."
      CDE_SUID_FIX="run 'ls -ld /usr/dt/bin/dtaction /usr/dt/bin/dtappgather /usr/dt/bin/dtprintinfo /usr/dt/bin/dtsession' as root, resolve the probe problem, and rerun PTxray."
      ;;
  esac

  add security cde_dt_binaries "CDE setuid/setgid binaries" \
    "$CDE_SUID_STATUS" med "$CDE_SUID_OBSERVED" \
    "$CDE_SUID_MEANING" "$CDE_SUID_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_remote_login — XDMCP (remote CDE GUI login) posture.  With CDE absent
  # there is no dtlogin to accept XDMCP connections, so the capability is
  # disabled by absence; that verdict rides the real fileset probe.  With CDE
  # installed, the active Dtlogin requestPort resource decides: the CIS AIX
  # family requires the uncommented value 0 in the dt Xconfig.
  typeset CDE_XRP_FS_RAW CDE_XRP_FS_RC CDE_XRP_FS_STATE
  typeset CDE_XRP_RAW CDE_XRP_RC CDE_XRP_SHAPE CDE_XRP_VAL CDE_XRP_WHICH
  typeset CDE_XRP_STATUS CDE_XRP_OBSERVED CDE_XRP_MEANING CDE_XRP_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_XRP_STATUS=NOT_ASSESSED
    CDE_XRP_OBSERVED="not assessed - CDE configuration probe requires root"
  else
    # --- shared CDE fileset state ---
    if [ "${CDE_FS_RC+x}" = x ]; then
      CDE_XRP_FS_RAW=$CDE_FS_RAW
      CDE_XRP_FS_RC=$CDE_FS_RC
    else
      CDE_XRP_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
      CDE_XRP_FS_RC=$?
    fi
    if [ "$CDE_XRP_FS_RC" -eq 1 ] && [ -z "$CDE_XRP_FS_RAW" ]; then
      CDE_XRP_FS_STATE=absent
    elif [ "$CDE_XRP_FS_RC" -eq 0 ] && [ -n "$CDE_XRP_FS_RAW" ] &&
        printf '%s\n' "$CDE_XRP_FS_RAW" | awk -F: '/^[ \t]*$/ { next } { if (NF < 6 || $2 !~ /^X11\.Dt/) bad = 1 } END { exit bad }'; then
      CDE_XRP_FS_STATE=installed
    else
      CDE_XRP_FS_STATE=unknown
    fi
    # --- end shared CDE fileset state ---
    if [ "$CDE_XRP_FS_STATE" = "absent" ]; then
      CDE_XRP_STATUS=PASS
      CDE_XRP_OBSERVED="CDE not installed (fileset query empty); no dtlogin exists to accept XDMCP connections"
    elif [ "$CDE_XRP_FS_STATE" = "unknown" ]; then
      CDE_XRP_STATUS=NOT_ASSESSED
      CDE_XRP_OBSERVED="not assessed - CDE fileset query was contradictory or failed, so install state is unproven"
    else
      CDE_XRP_RAW=$(aix cde_xconfig_requestport grep -E '^[ 	]*Dtlogin[.*]requestPort[ 	]*:' /etc/dt/config/Xconfig /usr/dt/config/Xconfig)
      CDE_XRP_RC=$?
      if [ -n "$CDE_XRP_RAW" ]; then
        CDE_XRP_SHAPE=$(printf '%s\n' "$CDE_XRP_RAW" | awk '
          /^[ \t]*$/ { next }
          {
            line = $0
            p1 = index(line, ":")
            if (p1 == 0) { bad = 1; next }
            file = substr(line, 1, p1 - 1)
            rest = substr(line, p1 + 1)
            p2 = index(rest, ":")
            if (p2 == 0) { bad = 1; next }
            val = substr(rest, p2 + 1)
            gsub(/[ \t]/, "", val)
            if (file == "/etc/dt/config/Xconfig") { etc = 1; etcval = val }
            else if (file == "/usr/dt/config/Xconfig") { usr = 1; usrval = val }
            else { bad = 1 }
          }
          END {
            if (bad) print "malformed"
            else if (etc) print "etc:" etcval
            else if (usr) print "usr:" usrval
            else print "malformed"
          }')
        case "$CDE_XRP_SHAPE" in
          malformed)
            CDE_XRP_STATUS=NOT_ASSESSED
            CDE_XRP_OBSERVED="not assessed - requestPort probe rows were malformed"
            ;;
          *)
            CDE_XRP_WHICH=${CDE_XRP_SHAPE%%:*}
            CDE_XRP_VAL=${CDE_XRP_SHAPE#*:}
            if [ "$CDE_XRP_VAL" = "0" ]; then
              CDE_XRP_STATUS=PASS
              CDE_XRP_OBSERVED="Dtlogin requestPort 0 in the $CDE_XRP_WHICH dt Xconfig (XDMCP disabled)"
            elif [ -z "$CDE_XRP_VAL" ]; then
              CDE_XRP_STATUS=NOT_ASSESSED
              CDE_XRP_OBSERVED="not assessed - requestPort resource present with no parseable value"
            else
              CDE_XRP_STATUS=FAIL
              CDE_XRP_OBSERVED="Dtlogin requestPort $CDE_XRP_VAL in the $CDE_XRP_WHICH dt Xconfig (XDMCP listening)"
            fi
            ;;
        esac
      elif [ "$CDE_XRP_RC" -eq 1 ]; then
        CDE_XRP_STATUS=FAIL
        CDE_XRP_OBSERVED="CDE installed and no active Dtlogin requestPort resource in either dt Xconfig; the shipped default leaves XDMCP enabled"
      else
        CDE_XRP_STATUS=NOT_ASSESSED
        CDE_XRP_OBSERVED="not assessed - requestPort probe failed with no rows (rc=$CDE_XRP_RC); neither dt Xconfig was readable"
      fi
    fi
  fi

  case "$CDE_XRP_STATUS" in
    PASS)
      CDE_XRP_MEANING="Remote systems cannot request a CDE login session from this host over XDMCP."
      CDE_XRP_FIX="n/a"
      ;;
    FAIL)
      CDE_XRP_MEANING="XDMCP is reachable, so remote systems can request CDE login sessions; X11 traffic is unencrypted and dtlogin enlarges the remote attack surface."
      CDE_XRP_FIX="copy /usr/dt/config/Xconfig to /etc/dt/config/Xconfig if needed and set the uncommented resource 'Dtlogin.requestPort: 0', then restart dtlogin; PTxray only recommends these actions."
      ;;
    *)
      CDE_XRP_MEANING="PTxray did not obtain trustworthy evidence for the CDE XDMCP posture."
      CDE_XRP_FIX="verify the CDE fileset state with \"lslpp -qcL 'X11.Dt*'\" and the requestPort resource in the dt Xconfig files as root, then rerun PTxray."
      ;;
  esac

  add security cde_remote_login "CDE remote XDMCP login" \
    "$CDE_XRP_STATUS" med "$CDE_XRP_OBSERVED" \
    "$CDE_XRP_MEANING" "$CDE_XRP_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_screensaver — CDE session screensaver/lock timeouts.  With CDE absent
  # no CDE session manager exists to run (or fail to run) a lock; the CIS AIX
  # family scopes this item to hosts using CDE, so absence renders a PASS by
  # inapplicability, stated as such, riding the real fileset probe.  With CDE
  # installed, the merged dtsession saverTimeout/lockTimeout resources decide:
  # the sourced family value is 10 (minutes) or less, nonzero.
  typeset CDE_SCR_FS_RAW CDE_SCR_FS_RC CDE_SCR_FS_STATE
  typeset CDE_SCR_RAW CDE_SCR_RC CDE_SCR_SHAPE CDE_SCR_S CDE_SCR_L
  typeset CDE_SCR_STATUS CDE_SCR_OBSERVED CDE_SCR_MEANING CDE_SCR_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_SCR_STATUS=NOT_ASSESSED
    CDE_SCR_OBSERVED="not assessed - CDE configuration probe requires root"
  else
    # --- shared CDE fileset state ---
    if [ "${CDE_FS_RC+x}" = x ]; then
      CDE_SCR_FS_RAW=$CDE_FS_RAW
      CDE_SCR_FS_RC=$CDE_FS_RC
    else
      CDE_SCR_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
      CDE_SCR_FS_RC=$?
    fi
    if [ "$CDE_SCR_FS_RC" -eq 1 ] && [ -z "$CDE_SCR_FS_RAW" ]; then
      CDE_SCR_FS_STATE=absent
    elif [ "$CDE_SCR_FS_RC" -eq 0 ] && [ -n "$CDE_SCR_FS_RAW" ] &&
        printf '%s\n' "$CDE_SCR_FS_RAW" | awk -F: '/^[ \t]*$/ { next } { if (NF < 6 || $2 !~ /^X11\.Dt/) bad = 1 } END { exit bad }'; then
      CDE_SCR_FS_STATE=installed
    else
      CDE_SCR_FS_STATE=unknown
    fi
    # --- end shared CDE fileset state ---
    if [ "$CDE_SCR_FS_STATE" = "absent" ]; then
      CDE_SCR_STATUS=PASS
      CDE_SCR_OBSERVED="CDE not installed (fileset query empty); no CDE session manager exists to run a screensaver lock"
    elif [ "$CDE_SCR_FS_STATE" = "unknown" ]; then
      CDE_SCR_STATUS=NOT_ASSESSED
      CDE_SCR_OBSERVED="not assessed - CDE fileset query was contradictory or failed, so install state is unproven"
    else
      CDE_SCR_RAW=$(aix cde_screensaver grep -E '^[ 	]*dtsession[*](saverTimeout|lockTimeout)[ 	]*:' /etc/dt/config/*/sys.resources /usr/dt/config/*/sys.resources)
      CDE_SCR_RC=$?
      if [ -n "$CDE_SCR_RAW" ]; then
        CDE_SCR_SHAPE=$(printf '%s\n' "$CDE_SCR_RAW" | awk '
          /^[ \t]*$/ { next }
          {
            line = $0
            p1 = index(line, ":")
            if (p1 == 0) { bad = 1; next }
            file = substr(line, 1, p1 - 1)
            rest = substr(line, p1 + 1)
            p2 = index(rest, ":")
            if (p2 == 0) { bad = 1; next }
            res = substr(rest, 1, p2 - 1)
            val = substr(rest, p2 + 1)
            gsub(/[ \t]/, "", val)
            if (val !~ /^[0-9]+$/) { bad = 1; next }
            scope = (file ~ /^\/etc\/dt\/config\//) ? "e" : "u"
            if (res ~ /saverTimeout$/) v[scope "s"] = val
            else if (res ~ /lockTimeout$/) v[scope "l"] = val
            else bad = 1
          }
          END {
            if (bad) { print "malformed"; exit }
            s = ("es" in v) ? v["es"] : (("us" in v) ? v["us"] : "")
            l = ("el" in v) ? v["el"] : (("ul" in v) ? v["ul"] : "")
            if (s == "" || l == "") print "missing:" s ":" l
            else if (s + 0 >= 1 && s + 0 <= 10 && l + 0 >= 1 && l + 0 <= 10) print "ok:" s ":" l
            else print "loose:" s ":" l
          }')
        case "$CDE_SCR_SHAPE" in
          malformed)
            CDE_SCR_STATUS=NOT_ASSESSED
            CDE_SCR_OBSERVED="not assessed - screensaver resource rows were malformed or non-numeric"
            ;;
          missing:*)
            CDE_SCR_STATUS=FAIL
            CDE_SCR_OBSERVED="CDE installed with an incomplete screensaver policy (saverTimeout or lockTimeout not set); the shipped default leaves sessions locked only after 30 minutes"
            ;;
          ok:*)
            CDE_SCR_S=${CDE_SCR_SHAPE#ok:}; CDE_SCR_L=${CDE_SCR_S#*:}; CDE_SCR_S=${CDE_SCR_S%%:*}
            CDE_SCR_STATUS=PASS
            CDE_SCR_OBSERVED="dtsession saverTimeout=$CDE_SCR_S lockTimeout=$CDE_SCR_L (both within 1..10 minutes)"
            ;;
          *)
            CDE_SCR_S=${CDE_SCR_SHAPE#loose:}; CDE_SCR_L=${CDE_SCR_S#*:}; CDE_SCR_S=${CDE_SCR_S%%:*}
            CDE_SCR_STATUS=FAIL
            CDE_SCR_OBSERVED="dtsession saverTimeout=$CDE_SCR_S lockTimeout=$CDE_SCR_L (outside 1..10 minutes)"
            ;;
        esac
      elif [ "$CDE_SCR_RC" -eq 1 ]; then
        CDE_SCR_STATUS=FAIL
        CDE_SCR_OBSERVED="CDE installed and no dtsession saverTimeout/lockTimeout resource found in any sys.resources file"
      else
        CDE_SCR_STATUS=NOT_ASSESSED
        CDE_SCR_OBSERVED="not assessed - screensaver probe failed with no rows (rc=$CDE_SCR_RC); no sys.resources file was readable"
      fi
    fi
  fi

  case "$CDE_SCR_STATUS" in
    PASS)
      CDE_SCR_MEANING="Unattended CDE sessions lock within the benchmark window, or no CDE session can exist on this host."
      CDE_SCR_FIX="n/a"
      ;;
    FAIL)
      CDE_SCR_MEANING="An unattended CDE session stays unlocked beyond the benchmark window, exposing the console session to walk-up access."
      CDE_SCR_FIX="set 'dtsession*saverTimeout: 10' and 'dtsession*lockTimeout: 10' in the dt sys.resources files (site copy under /etc/dt/config preferred); PTxray only recommends these actions."
      ;;
    *)
      CDE_SCR_MEANING="PTxray did not obtain trustworthy evidence for the CDE screensaver policy."
      CDE_SCR_FIX="verify the CDE fileset state and the dtsession timeout resources as root, then rerun PTxray."
      ;;
  esac

  add security cde_screensaver "CDE screensaver lock" \
    "$CDE_SCR_STATUS" med "$CDE_SCR_OBSERVED" \
    "$CDE_SCR_MEANING" "$CDE_SCR_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_greeting — CDE login screen greeting.  With CDE absent no CDE login
  # screen exists to reveal the host name; the CIS AIX family scopes this
  # item to hosts using CDE, so absence renders a PASS by inapplicability,
  # stated as such, riding the real fileset probe.  With CDE installed, the
  # Dtlogin greeting labelString resources decide: an active custom override
  # that does not use the %LocalHost% macro masks the host name.
  typeset CDE_GRT_FS_RAW CDE_GRT_FS_RC CDE_GRT_FS_STATE
  typeset CDE_GRT_RAW CDE_GRT_RC CDE_GRT_SHAPE
  typeset CDE_GRT_STATUS CDE_GRT_OBSERVED CDE_GRT_MEANING CDE_GRT_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_GRT_STATUS=NOT_ASSESSED
    CDE_GRT_OBSERVED="not assessed - CDE configuration probe requires root"
  else
    # --- shared CDE fileset state ---
    if [ "${CDE_FS_RC+x}" = x ]; then
      CDE_GRT_FS_RAW=$CDE_FS_RAW
      CDE_GRT_FS_RC=$CDE_FS_RC
    else
      CDE_GRT_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
      CDE_GRT_FS_RC=$?
    fi
    if [ "$CDE_GRT_FS_RC" -eq 1 ] && [ -z "$CDE_GRT_FS_RAW" ]; then
      CDE_GRT_FS_STATE=absent
    elif [ "$CDE_GRT_FS_RC" -eq 0 ] && [ -n "$CDE_GRT_FS_RAW" ] &&
        printf '%s\n' "$CDE_GRT_FS_RAW" | awk -F: '/^[ \t]*$/ { next } { if (NF < 6 || $2 !~ /^X11\.Dt/) bad = 1 } END { exit bad }'; then
      CDE_GRT_FS_STATE=installed
    else
      CDE_GRT_FS_STATE=unknown
    fi
    # --- end shared CDE fileset state ---
    if [ "$CDE_GRT_FS_STATE" = "absent" ]; then
      CDE_GRT_STATUS=PASS
      CDE_GRT_OBSERVED="CDE not installed (fileset query empty); no CDE login screen exists to reveal the host name"
    elif [ "$CDE_GRT_FS_STATE" = "unknown" ]; then
      CDE_GRT_STATUS=NOT_ASSESSED
      CDE_GRT_OBSERVED="not assessed - CDE fileset query was contradictory or failed, so install state is unproven"
    else
      CDE_GRT_RAW=$(aix cde_greeting grep -E '^[ 	]*Dtlogin[*]greeting[.](labelString|persLabelString)[ 	]*:' /etc/dt/config/*/Xresources /usr/dt/config/*/Xresources)
      CDE_GRT_RC=$?
      if [ -n "$CDE_GRT_RAW" ]; then
        CDE_GRT_SHAPE=$(printf '%s\n' "$CDE_GRT_RAW" | awk '
          /^[ \t]*$/ { next }
          {
            line = $0
            p1 = index(line, ":")
            if (p1 == 0) { bad = 1; next }
            rest = substr(line, p1 + 1)
            p2 = index(rest, ":")
            if (p2 == 0) { bad = 1; next }
            res = substr(rest, 1, p2 - 1)
            val = substr(rest, p2 + 1)
            if (val ~ /%LocalHost%/) leak = 1
            if (res ~ /greeting\.labelString[ \t]*$/) labels++
          }
          END {
            if (bad) print "malformed"
            else if (leak) print "leak"
            else if (labels < 1) print "nolabel"
            else print "ok:" labels
          }')
        case "$CDE_GRT_SHAPE" in
          malformed)
            CDE_GRT_STATUS=NOT_ASSESSED
            CDE_GRT_OBSERVED="not assessed - greeting resource rows were malformed"
            ;;
          leak)
            CDE_GRT_STATUS=FAIL
            CDE_GRT_OBSERVED="a Dtlogin greeting resource still uses the %LocalHost% macro, so the login screen shows the host name"
            ;;
          nolabel)
            CDE_GRT_STATUS=FAIL
            CDE_GRT_OBSERVED="no active Dtlogin greeting.labelString override found; the default CDE greeting shows the host name"
            ;;
          *)
            CDE_GRT_STATUS=PASS
            CDE_GRT_OBSERVED="custom Dtlogin greeting override active (${CDE_GRT_SHAPE#ok:} labelString row(s), no %LocalHost% macro)"
            ;;
        esac
      elif [ "$CDE_GRT_RC" -eq 1 ]; then
        CDE_GRT_STATUS=FAIL
        CDE_GRT_OBSERVED="CDE installed and no active Dtlogin greeting override in any Xresources file; the default CDE greeting shows the host name"
      else
        CDE_GRT_STATUS=NOT_ASSESSED
        CDE_GRT_OBSERVED="not assessed - greeting probe failed with no rows (rc=$CDE_GRT_RC); no Xresources file was readable"
      fi
    fi
  fi

  case "$CDE_GRT_STATUS" in
    PASS)
      CDE_GRT_MEANING="The CDE login screen cannot hand an attacker the host identity, either because the greeting is overridden or because no CDE login screen exists."
      CDE_GRT_FIX="n/a"
      ;;
    FAIL)
      CDE_GRT_MEANING="The CDE login screen reveals the host name before authentication, giving reconnaissance information to anyone who can reach a session."
      CDE_GRT_FIX="copy the dt Xresources files under /etc/dt/config and set 'Dtlogin*greeting.labelString' and 'Dtlogin*greeting.persLabelString' to site text without the %LocalHost% macro; PTxray only recommends these actions."
      ;;
    *)
      CDE_GRT_MEANING="PTxray did not obtain trustworthy evidence for the CDE greeting configuration."
      CDE_GRT_FIX="verify the CDE fileset state and the Dtlogin greeting resources as root, then rerun PTxray."
      ;;
  esac

  add security cde_greeting "CDE login greeting" \
    "$CDE_GRT_STATUS" med "$CDE_GRT_OBSERVED" \
    "$CDE_GRT_MEANING" "$CDE_GRT_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # cde_xconfig_access — ownership and write-mode of the dt Xconfig file.
  # With CDE absent the dt config files do not exist and nothing consumes
  # them; the CIS AIX family scopes this item to hosts using CDE, so absence
  # renders a PASS by inapplicability, stated as such, riding the real
  # fileset probe.  With CDE installed, every present copy (site copy under
  # /etc/dt/config and shipped copy under /usr/dt/config) must be owned by
  # root with no group or other write access.
  typeset CDE_XCA_FS_RAW CDE_XCA_FS_RC CDE_XCA_FS_STATE
  typeset CDE_XCA_RAW CDE_XCA_RC CDE_XCA_SHAPE CDE_XCA_DETAIL
  typeset CDE_XCA_STATUS CDE_XCA_OBSERVED CDE_XCA_MEANING CDE_XCA_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_XCA_STATUS=NOT_ASSESSED
    CDE_XCA_OBSERVED="not assessed - CDE configuration probe requires root"
  else
    # --- shared CDE fileset state ---
    if [ "${CDE_FS_RC+x}" = x ]; then
      CDE_XCA_FS_RAW=$CDE_FS_RAW
      CDE_XCA_FS_RC=$CDE_FS_RC
    else
      CDE_XCA_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
      CDE_XCA_FS_RC=$?
    fi
    if [ "$CDE_XCA_FS_RC" -eq 1 ] && [ -z "$CDE_XCA_FS_RAW" ]; then
      CDE_XCA_FS_STATE=absent
    elif [ "$CDE_XCA_FS_RC" -eq 0 ] && [ -n "$CDE_XCA_FS_RAW" ] &&
        printf '%s\n' "$CDE_XCA_FS_RAW" | awk -F: '/^[ \t]*$/ { next } { if (NF < 6 || $2 !~ /^X11\.Dt/) bad = 1 } END { exit bad }'; then
      CDE_XCA_FS_STATE=installed
    else
      CDE_XCA_FS_STATE=unknown
    fi
    # --- end shared CDE fileset state ---
    if [ "$CDE_XCA_FS_STATE" = "absent" ]; then
      CDE_XCA_STATUS=PASS
      CDE_XCA_OBSERVED="CDE not installed (fileset query empty); no dt Xconfig file exists or is consumed"
    elif [ "$CDE_XCA_FS_STATE" = "unknown" ]; then
      CDE_XCA_STATUS=NOT_ASSESSED
      CDE_XCA_OBSERVED="not assessed - CDE fileset query was contradictory or failed, so install state is unproven"
    else
      CDE_XCA_RAW=$(aix cde_xconfig_access ls -ld /etc/dt/config/Xconfig /usr/dt/config/Xconfig)
      CDE_XCA_RC=$?
      if [ -n "$CDE_XCA_RAW" ]; then
        CDE_XCA_SHAPE=$(printf '%s\n' "$CDE_XCA_RAW" | awk '
          /^[ \t]*$/ { next }
          {
            rows++
            mode = $1
            owner = $3
            path = $NF
            if (path !~ /^\/(etc|usr)\/dt\/config\/Xconfig$/) { foreign = 1; next }
            if (length("" mode) < 10) { bad = 1; next }
            gw = substr(mode, 6, 1)
            ow = substr(mode, 9, 1)
            if (owner != "root" || gw == "w" || ow == "w") {
              viol++
              if (viol == 1) first = path " " mode " owner " owner
            } else {
              okc++
            }
          }
          END {
            if (foreign) print "foreign"
            else if (bad) print "malformed"
            else if (viol) print "viol:" viol ":" first
            else if (okc) print "ok:" okc
            else print "none"
          }')
        case "$CDE_XCA_SHAPE" in
          foreign)
            CDE_XCA_STATUS=NOT_ASSESSED
            CDE_XCA_OBSERVED="not assessed - file-access probe returned an unexpected path"
            ;;
          malformed)
            CDE_XCA_STATUS=NOT_ASSESSED
            CDE_XCA_OBSERVED="not assessed - file-access probe rows were malformed"
            ;;
          none)
            CDE_XCA_STATUS=NOT_ASSESSED
            CDE_XCA_OBSERVED="not assessed - file-access probe output held no parseable rows"
            ;;
          viol:*)
            CDE_XCA_DETAIL=${CDE_XCA_SHAPE#viol:}
            CDE_XCA_STATUS=FAIL
            CDE_XCA_OBSERVED="${CDE_XCA_DETAIL%%:*} dt Xconfig file(s) writable beyond root or not root-owned, first: ${CDE_XCA_DETAIL#*:}"
            ;;
          *)
            CDE_XCA_STATUS=PASS
            CDE_XCA_OBSERVED="${CDE_XCA_SHAPE#ok:} dt Xconfig file(s) root-owned with no group/other write"
            ;;
        esac
      elif [ "$CDE_XCA_RC" -ne 0 ]; then
        CDE_XCA_STATUS=NOT_ASSESSED
        CDE_XCA_OBSERVED="not assessed - CDE is installed but no dt Xconfig file was found (probe rc=$CDE_XCA_RC); the shipped copy should exist"
      else
        CDE_XCA_STATUS=NOT_ASSESSED
        CDE_XCA_OBSERVED="not assessed - file-access probe returned rc=0 with empty output"
      fi
    fi
  fi

  case "$CDE_XCA_STATUS" in
    PASS)
      CDE_XCA_MEANING="Only root can modify the dt Xconfig login-manager configuration, or no such file exists to modify."
      CDE_XCA_FIX="n/a"
      ;;
    FAIL)
      CDE_XCA_MEANING="A non-root or group/other-writable dt Xconfig lets a local user redefine dtlogin behavior, including the programs it runs as root."
      CDE_XCA_FIX="restore restrictive access with 'chown root:bin <file>' and 'chmod go-w <file>' for each listed file; PTxray only recommends these actions."
      ;;
    *)
      CDE_XCA_MEANING="PTxray did not obtain trustworthy file-access evidence for the dt Xconfig file."
      CDE_XCA_FIX="verify the CDE fileset state and 'ls -ld' the dt Xconfig files as root, then rerun PTxray."
      ;;
  esac

  add security cde_xconfig_access "CDE Xconfig file access" \
    "$CDE_XCA_STATUS" med "$CDE_XCA_OBSERVED" \
    "$CDE_XCA_MEANING" "$CDE_XCA_FIX" "cis-l1"
