  typeset CDE_XRA_FS_RAW CDE_XRA_FS_RC CDE_XRA_FS_STATE
  typeset CDE_XRA_RAW CDE_XRA_RC CDE_XRA_SHAPE CDE_XRA_DETAIL
  typeset CDE_XRA_STATUS CDE_XRA_OBSERVED CDE_XRA_MEANING CDE_XRA_FIX

  if [ "${MYUID:-0}" != "0" ]; then
    CDE_XRA_STATUS=NOT_ASSESSED
    CDE_XRA_OBSERVED="not assessed - CDE configuration probe requires root"
  else
    # --- shared CDE fileset state ---
    if [ "${CDE_FS_RC+x}" = x ]; then
      CDE_XRA_FS_RAW=$CDE_FS_RAW
      CDE_XRA_FS_RC=$CDE_FS_RC
    else
      CDE_XRA_FS_RAW=$(aix cde_filesets lslpp -qcL 'X11.Dt*')
      CDE_XRA_FS_RC=$?
    fi
    if [ "$CDE_XRA_FS_RC" -eq 1 ] && [ -z "$CDE_XRA_FS_RAW" ]; then
      CDE_XRA_FS_STATE=absent
    elif [ "$CDE_XRA_FS_RC" -eq 0 ] && [ -n "$CDE_XRA_FS_RAW" ] &&
        printf '%s\n' "$CDE_XRA_FS_RAW" | awk -F: '/^[ \t]*$/ { next } { if (NF < 6 || $2 !~ /^X11\.Dt/) bad = 1 } END { exit bad }'; then
      CDE_XRA_FS_STATE=installed
    else
      CDE_XRA_FS_STATE=unknown
    fi
    # --- end shared CDE fileset state ---
    if [ "$CDE_XRA_FS_STATE" = "absent" ]; then
      CDE_XRA_STATUS=PASS
      CDE_XRA_OBSERVED="CDE not installed (fileset query empty); no dt Xresources file exists or is consumed"
    elif [ "$CDE_XRA_FS_STATE" = "unknown" ]; then
      CDE_XRA_STATUS=NOT_ASSESSED
      CDE_XRA_OBSERVED="not assessed - CDE fileset query was contradictory or failed, so install state is unproven"
    else
      CDE_XRA_RAW=$(aix cde_xresources_access ls -ld /etc/dt/config/*/Xresources /usr/dt/config/*/Xresources)
      CDE_XRA_RC=$?
      if [ -n "$CDE_XRA_RAW" ]; then
        CDE_XRA_SHAPE=$(printf '%s\n' "$CDE_XRA_RAW" | awk '
          /^[ \t]*$/ { next }
          {
            rows++
            mode = $1
            owner = $3
            path = $NF
            if (path !~ /^\/(etc|usr)\/dt\/config\/[^\/]+\/Xresources$/) { foreign = 1; next }
            if (length("" mode) < 10) { bad = 1; next }
            gw = substr(mode, 6, 1)
            ow = substr(mode, 9, 1)
            if (owner != "root" || gw == "w" || ow == "w") {
              viol++
              if (viol == 1) first = path " " mode " owner " owner
            } else {
              okc++
            }
          }
          END {
            if (foreign) print "foreign"
            else if (bad) print "malformed"
            else if (viol) print "viol:" viol ":" first
            else if (okc) print "ok:" okc
            else print "none"
          }')
        case "$CDE_XRA_SHAPE" in
          foreign)
            CDE_XRA_STATUS=NOT_ASSESSED
            CDE_XRA_OBSERVED="not assessed - file-access probe returned an unexpected path"
            ;;
          malformed)
            CDE_XRA_STATUS=NOT_ASSESSED
            CDE_XRA_OBSERVED="not assessed - file-access probe rows were malformed"
            ;;
          none)
            CDE_XRA_STATUS=NOT_ASSESSED
            CDE_XRA_OBSERVED="not assessed - file-access probe output held no parseable rows"
            ;;
          viol:*)
            CDE_XRA_DETAIL=${CDE_XRA_SHAPE#viol:}
            CDE_XRA_STATUS=FAIL
            CDE_XRA_OBSERVED="${CDE_XRA_DETAIL%%:*} dt Xresources file(s) writable beyond root or not root-owned, first: ${CDE_XRA_DETAIL#*:}"
            ;;
          *)
            CDE_XRA_STATUS=PASS
            CDE_XRA_OBSERVED="${CDE_XRA_SHAPE#ok:} dt Xresources file(s) root-owned with no group/other write"
            ;;
        esac
      elif [ "$CDE_XRA_RC" -ne 0 ]; then
        CDE_XRA_STATUS=NOT_ASSESSED
        CDE_XRA_OBSERVED="not assessed - CDE is installed but no dt Xresources file was found (probe rc=$CDE_XRA_RC); the shipped copy should exist"
      else
        CDE_XRA_STATUS=NOT_ASSESSED
        CDE_XRA_OBSERVED="not assessed - file-access probe returned rc=0 with empty output"
      fi
    fi
  fi

  case "$CDE_XRA_STATUS" in
    PASS)
      CDE_XRA_MEANING="Only root can modify the dt Xresources login-manager configuration, or no such file exists to modify."
      CDE_XRA_FIX="n/a"
      ;;
    FAIL)
      CDE_XRA_MEANING="A non-root or group/other-writable dt Xresources lets a local user change the resources merged into every CDE login session, including the login-screen behavior."
      CDE_XRA_FIX="restore restrictive access with 'chown root:bin <file>' and 'chmod go-w <file>' for each listed file; PTxray only recommends these actions."
      ;;
    *)
      CDE_XRA_MEANING="PTxray did not obtain trustworthy file-access evidence for the dt Xresources file."
      CDE_XRA_FIX="verify the CDE fileset state and 'ls -ld' the dt Xresources files as root, then rerun PTxray."
      ;;
  esac

  add security cde_xresources_access "CDE Xresources file access" \
    "$CDE_XRA_STATUS" med "$CDE_XRA_OBSERVED" \
    "$CDE_XRA_MEANING" "$CDE_XRA_FIX" "cis-l1"

  # ---- CIS AIX 7 v1.2.0 wave 2: remaining L1 + L2 controls ----
_AIXRAY_SESSION_KEYS=""
# ssh_packages_installed — presence and health of the OpenSSH client and server
# filesets from the package inventory. Two lslpp -L captures, one per fileset.
# The discriminator is a data row naming the fileset and the state in column 3
# (a state letter, or the long state name); absence of a data row is absence of
# the fileset. An lslpp probe returning rc >= 2 is a failed probe, never
# evidence of absence, and empty stdout is never treated as a verdict signal.
typeset SSHPKG_CLIENT_RAW SSHPKG_CLIENT_RC SSHPKG_CLIENT_TOKEN SSHPKG_CLIENT_AWK_RC
typeset SSHPKG_CLIENT_STATE SSHPKG_CLIENT_STATE_NAME SSHPKG_CLIENT_RESULT SSHPKG_CLIENT_REASON
typeset SSHPKG_SERVER_RAW SSHPKG_SERVER_RC SSHPKG_SERVER_TOKEN SSHPKG_SERVER_AWK_RC
typeset SSHPKG_SERVER_STATE SSHPKG_SERVER_STATE_NAME SSHPKG_SERVER_RESULT SSHPKG_SERVER_REASON
typeset SSHPKG_STATUS SSHPKG_SEV SSHPKG_OBS SSHPKG_MEAN SSHPKG_FIX

SSHPKG_CLIENT_RAW=$(aix lslpp_openssh_client lslpp -L openssh.base.client)
SSHPKG_CLIENT_RC=$?
SSHPKG_CLIENT_RESULT=unknown
SSHPKG_CLIENT_REASON=""
SSHPKG_CLIENT_STATE=""
SSHPKG_CLIENT_STATE_NAME=""
if [ "$SSHPKG_CLIENT_RC" -ge 2 ]; then
  SSHPKG_CLIENT_REASON="client fileset probe failed (rc=$SSHPKG_CLIENT_RC)"
else
  SSHPKG_CLIENT_TOKEN=$(printf '%s\n' "$SSHPKG_CLIENT_RAW" | awk -v want='openssh.base.client' '
    /^[ \t]*$/ { next }
    /^[ \t]*Fileset[ \t]/ { next }
    /^[ \t]*-/ { next }
    /^[ \t]*State codes?[ \t]*:/ { next }
    /^[ \t]*[A-Z?] -- / { next }
    {
      if ($1 != want) next
      found = 1
      if (NF < 3) { print "malformed"; exit }
      if ($3 == "EFIX") {
        if (NF < 4) { print "malformed"; exit }
        print "state:" $3 " " $4
        exit
      }
      print "state:" $3
      exit
    }
    END { if (!found) print "absent" }')
  SSHPKG_CLIENT_AWK_RC=$?
  if [ "$SSHPKG_CLIENT_AWK_RC" -ne 0 ]; then
    SSHPKG_CLIENT_REASON="client fileset output could not be parsed (awk rc=$SSHPKG_CLIENT_AWK_RC)"
  else
    case "$SSHPKG_CLIENT_TOKEN" in
      absent)
        SSHPKG_CLIENT_RESULT=absent
        SSHPKG_CLIENT_REASON="openssh.base.client is not in the package inventory"
        ;;
      malformed)
        SSHPKG_CLIENT_REASON="openssh.base.client data row was malformed"
        ;;
      state:*)
        SSHPKG_CLIENT_STATE=${SSHPKG_CLIENT_TOKEN#state:}
        case "$SSHPKG_CLIENT_STATE" in
          C|COMMITTED)
            SSHPKG_CLIENT_RESULT=healthy
            SSHPKG_CLIENT_STATE_NAME=COMMITTED
            ;;
          A|APPLIED)
            SSHPKG_CLIENT_RESULT=healthy
            SSHPKG_CLIENT_STATE_NAME=APPLIED
            ;;
          B|BROKEN)
            SSHPKG_CLIENT_RESULT=unhealthy
            SSHPKG_CLIENT_STATE_NAME=BROKEN
            ;;
          O|OBSOLETE)
            SSHPKG_CLIENT_RESULT=unhealthy
            SSHPKG_CLIENT_STATE_NAME=OBSOLETE
            ;;
          E|"EFIX LOCKED"|EFIX_LOCKED)
            SSHPKG_CLIENT_RESULT=unhealthy
            SSHPKG_CLIENT_STATE_NAME="EFIX LOCKED"
            ;;
          [?]|INCONSISTENT)
            SSHPKG_CLIENT_RESULT=unhealthy
            SSHPKG_CLIENT_STATE_NAME=INCONSISTENT
            ;;
          *)
            SSHPKG_CLIENT_STATE_NAME="$SSHPKG_CLIENT_STATE"
            ;;
        esac
        case "$SSHPKG_CLIENT_RESULT" in
          healthy)
            SSHPKG_CLIENT_REASON="openssh.base.client is installed (state $SSHPKG_CLIENT_STATE_NAME)"
            ;;
          unhealthy)
            SSHPKG_CLIENT_REASON="openssh.base.client is installed but its state is $SSHPKG_CLIENT_STATE_NAME"
            ;;
          *)
            SSHPKG_CLIENT_REASON="openssh.base.client is installed but its state '$SSHPKG_CLIENT_STATE' is unrecognized"
            ;;
        esac
        ;;
      *)
        SSHPKG_CLIENT_REASON="openssh.base.client output was unrecognized"
        ;;
    esac
  fi
fi

SSHPKG_SERVER_RAW=$(aix lslpp_openssh_server lslpp -L openssh.base.server)
SSHPKG_SERVER_RC=$?
SSHPKG_SERVER_RESULT=unknown
SSHPKG_SERVER_REASON=""
SSHPKG_SERVER_STATE=""
SSHPKG_SERVER_STATE_NAME=""
if [ "$SSHPKG_SERVER_RC" -ge 2 ]; then
  SSHPKG_SERVER_REASON="server fileset probe failed (rc=$SSHPKG_SERVER_RC)"
else
  SSHPKG_SERVER_TOKEN=$(printf '%s\n' "$SSHPKG_SERVER_RAW" | awk -v want='openssh.base.server' '
    /^[ \t]*$/ { next }
    /^[ \t]*Fileset[ \t]/ { next }
    /^[ \t]*-/ { next }
    /^[ \t]*State codes?[ \t]*:/ { next }
    /^[ \t]*[A-Z?] -- / { next }
    {
      if ($1 != want) next
      found = 1
      if (NF < 3) { print "malformed"; exit }
      if ($3 == "EFIX") {
        if (NF < 4) { print "malformed"; exit }
        print "state:" $3 " " $4
        exit
      }
      print "state:" $3
      exit
    }
    END { if (!found) print "absent" }')
  SSHPKG_SERVER_AWK_RC=$?
  if [ "$SSHPKG_SERVER_AWK_RC" -ne 0 ]; then
    SSHPKG_SERVER_REASON="server fileset output could not be parsed (awk rc=$SSHPKG_SERVER_AWK_RC)"
  else
    case "$SSHPKG_SERVER_TOKEN" in
      absent)
        SSHPKG_SERVER_RESULT=absent
        SSHPKG_SERVER_REASON="openssh.base.server is not in the package inventory"
        ;;
      malformed)
        SSHPKG_SERVER_REASON="openssh.base.server data row was malformed"
        ;;
      state:*)
        SSHPKG_SERVER_STATE=${SSHPKG_SERVER_TOKEN#state:}
        case "$SSHPKG_SERVER_STATE" in
          C|COMMITTED)
            SSHPKG_SERVER_RESULT=healthy
            SSHPKG_SERVER_STATE_NAME=COMMITTED
            ;;
          A|APPLIED)
            SSHPKG_SERVER_RESULT=healthy
            SSHPKG_SERVER_STATE_NAME=APPLIED
            ;;
          B|BROKEN)
            SSHPKG_SERVER_RESULT=unhealthy
            SSHPKG_SERVER_STATE_NAME=BROKEN
            ;;
          O|OBSOLETE)
            SSHPKG_SERVER_RESULT=unhealthy
            SSHPKG_SERVER_STATE_NAME=OBSOLETE
            ;;
          E|"EFIX LOCKED"|EFIX_LOCKED)
            SSHPKG_SERVER_RESULT=unhealthy
            SSHPKG_SERVER_STATE_NAME="EFIX LOCKED"
            ;;
          [?]|INCONSISTENT)
            SSHPKG_SERVER_RESULT=unhealthy
            SSHPKG_SERVER_STATE_NAME=INCONSISTENT
            ;;
          *)
            SSHPKG_SERVER_STATE_NAME="$SSHPKG_SERVER_STATE"
            ;;
        esac
        case "$SSHPKG_SERVER_RESULT" in
          healthy)
            SSHPKG_SERVER_REASON="openssh.base.server is installed (state $SSHPKG_SERVER_STATE_NAME)"
            ;;
          unhealthy)
            SSHPKG_SERVER_REASON="openssh.base.server is installed but its state is $SSHPKG_SERVER_STATE_NAME"
            ;;
          *)
            SSHPKG_SERVER_REASON="openssh.base.server is installed but its state '$SSHPKG_SERVER_STATE' is unrecognized"
            ;;
        esac
        ;;
      *)
        SSHPKG_SERVER_REASON="openssh.base.server output was unrecognized"
        ;;
    esac
  fi
fi

if [ "$SSHPKG_CLIENT_RESULT" = unknown ] || [ "$SSHPKG_SERVER_RESULT" = unknown ]; then
  SSHPKG_STATUS=NOT_ASSESSED
  SSHPKG_SEV=low
  SSHPKG_OBS="not assessed"
  if [ -n "$SSHPKG_CLIENT_REASON" ]; then
    SSHPKG_OBS="$SSHPKG_OBS - $SSHPKG_CLIENT_REASON"
  fi
  if [ -n "$SSHPKG_SERVER_REASON" ]; then
    SSHPKG_OBS="$SSHPKG_OBS; $SSHPKG_SERVER_REASON"
  fi
  SSHPKG_MEAN="PTxray could not determine the installed and healthy state of the OpenSSH client and server filesets from the package inventory."
  SSHPKG_FIX="restore a readable 'lslpp -L' query for both filesets and rerun PTxray."
elif [ "$SSHPKG_CLIENT_RESULT" = absent ] || [ "$SSHPKG_SERVER_RESULT" = absent ] ||
     [ "$SSHPKG_CLIENT_RESULT" = unhealthy ] || [ "$SSHPKG_SERVER_RESULT" = unhealthy ]; then
  SSHPKG_STATUS=FAIL
  SSHPKG_SEV=high
  SSHPKG_OBS=""
  if [ "$SSHPKG_CLIENT_RESULT" = absent ] || [ "$SSHPKG_CLIENT_RESULT" = unhealthy ]; then
    SSHPKG_OBS="$SSHPKG_CLIENT_REASON"
  fi
  if [ "$SSHPKG_SERVER_RESULT" = absent ] || [ "$SSHPKG_SERVER_RESULT" = unhealthy ]; then
    if [ -n "$SSHPKG_OBS" ]; then
      SSHPKG_OBS="$SSHPKG_OBS; $SSHPKG_SERVER_REASON"
    else
      SSHPKG_OBS="$SSHPKG_SERVER_REASON"
    fi
  fi
  SSHPKG_MEAN="The OpenSSH client and server filesets must both be installed and in a healthy state; a missing fileset or a broken, obsolete, inconsistent, or efix-locked state is non-compliant."
  SSHPKG_FIX="install or repair the affected fileset(s) with 'installp' and rerun PTxray; PTxray only recommends these actions."
else
  SSHPKG_STATUS=PASS
  SSHPKG_SEV=low
  SSHPKG_OBS="openssh.base.client and openssh.base.server are both installed and healthy (client state $SSHPKG_CLIENT_STATE_NAME, server state $SSHPKG_SERVER_STATE_NAME)"
  SSHPKG_MEAN="The OpenSSH client and server filesets are installed and in a healthy state."
  SSHPKG_FIX="n/a"
fi

add security ssh_packages_installed "OpenSSH client and server installed" \
  "$SSHPKG_STATUS" "$SSHPKG_SEV" \
  "$SSHPKG_OBS" \
  "$SSHPKG_MEAN" \
  "$SSHPKG_FIX" \
  "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # system_config_capture_cron — scheduled config capture plus inventory log routing.
  typeset SCC_CRON SCC_CRON_RC SCC_SYS SCC_SYS_RC
  typeset SCC_CRON_ST SCC_SYS_ST SCC_OVERALL SCC_SEV
  typeset SCC_CRON_OBS SCC_SYS_OBS SCC_OBS SCC_MEAN SCC_FIX

  SCC_CRON=$(aix crontab_list crontab -l); SCC_CRON_RC=$?
  SCC_SYS=$(aix syslog_conf_grep egrep 'syslog/inventory.log' /etc/syslog.conf); SCC_SYS_RC=$?

  # Cron side: rc=0 plus a listed run of the capture command is PASS; rc=0
  # without it is FAIL; any other rc means the crontab could not be listed.
  SCC_CRON_ST=NOT_ASSESSED
  SCC_CRON_OBS=""
  if [ "$SCC_CRON_RC" -eq 0 ]; then
    if printf '%s\n' "$SCC_CRON" | grep -q '/usr/sbin/lsconf -v'; then
      SCC_CRON_ST=PASS
      SCC_CRON_OBS="cron schedules /usr/sbin/lsconf -v"
    else
      SCC_CRON_ST=FAIL
      SCC_CRON_OBS="no cron entry runs /usr/sbin/lsconf -v"
    fi
  else
    SCC_CRON_OBS="crontab could not be listed (rc=$SCC_CRON_RC)"
  fi

  # Syslog side: egrep rc 0 is a match, 1 is no match, 2 is a missing or
  # unreadable config file (both determinate absence), anything else is
  # genuinely unknown.
  SCC_SYS_ST=NOT_ASSESSED
  SCC_SYS_OBS=""
  case "$SCC_SYS_RC" in
    0)
      SCC_SYS_ST=PASS
      SCC_SYS_OBS="syslog directs local1.info to a path containing syslog/inventory.log"
      ;;
    1)
      SCC_SYS_ST=FAIL
      SCC_SYS_OBS="syslog.conf has no entry routing local1.info to a path containing syslog/inventory.log"
      ;;
    2)
      SCC_SYS_ST=FAIL
      SCC_SYS_OBS="syslog.conf is absent or unreadable, so local1.info cannot be routed to a path containing syslog/inventory.log"
      ;;
    *)
      SCC_SYS_OBS="syslog grep failed unexpectedly (rc=$SCC_SYS_RC)"
      ;;
  esac

  if [ "$SCC_CRON_ST" = PASS ] && [ "$SCC_SYS_ST" = PASS ]; then
    SCC_OVERALL=PASS
    SCC_SEV=low
    SCC_MEAN="System configuration is captured on a schedule and the inventory log collects the local1.info stream."
    SCC_FIX="n/a"
  elif [ "$SCC_CRON_ST" = FAIL ] || [ "$SCC_SYS_ST" = FAIL ]; then
    SCC_OVERALL=FAIL
    SCC_SEV=med
    SCC_MEAN="System configuration capture is incomplete: a scheduled run of /usr/sbin/lsconf -v or its syslog routing to a path containing syslog/inventory.log is missing."
    SCC_FIX=""
    if [ "$SCC_CRON_ST" = FAIL ]; then
      SCC_FIX="add a cron entry that runs /usr/sbin/lsconf -v on a regular schedule"
    fi
    if [ "$SCC_SYS_ST" = FAIL ]; then
      if [ -n "$SCC_FIX" ]; then SCC_FIX="$SCC_FIX; "; fi
      SCC_FIX="${SCC_FIX}add a local1.info entry in /etc/syslog.conf whose path contains syslog/inventory.log, then refresh the syslog daemon"
    fi
  else
    SCC_OVERALL=NOT_ASSESSED
    SCC_SEV=low
    SCC_MEAN="Capture evidence was incomplete, so the scheduled configuration capture and its syslog routing could not be verified."
    SCC_FIX="restore access to 'crontab -l' and /etc/syslog.conf, then rerun PTxray."
  fi

  SCC_OBS="$SCC_CRON_OBS; $SCC_SYS_OBS"

  add config system_config_capture_cron "System config capture cron" "$SCC_OVERALL" "$SCC_SEV" "$SCC_OBS" "$SCC_MEAN" "$SCC_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # trustchk_te_tep — Trusted Execution (TE) and Trusted Execution Path (TEP)
  # must both be active. CIS control 2.2 (Level 2). trustchk is mode 500 (owner
  # root): a non-root user cannot execute it, so the capture returns rc=127 and
  # empty stdout — a genuine probe failure, NOT_ASSESSED.
  #
  # `trustchk -p` writes the policy values to STDERR, not stdout, on both AIX 7.2
  # and 7.3 (verified live on two lab LPARs, 2026-08-05). The aix()
  # wrapper discards stderr, so probing without the 2>&1 merge returned rc=0 with
  # empty output on every real box — which this check then reported as
  # "unparseable" and refused. A check that can only ever refuse does not cover
  # its control, so the merge is required, not cosmetic.
  typeset TCHK_RC TCHK_OUT TCHK_PARSED TCHK_STATE TCHK_PATH
  TCHK_OUT=$(aixv trustchk_te_tep trustchk -p TE TEP); TCHK_RC=$?
  case "$TCHK_RC" in
    0)
      TCHK_PARSED=$(printf '%s\n' "$TCHK_OUT" | awk '
        BEGIN { n=0; bad=0; te_seen=0; te_val=""; bool_seen=0; bool_val=""; path_seen=0; path_val="" }
        /^[ \t]*$/ { next }
        {
          n++
          if ($0 ~ /^TE=/) {
            te_seen++
            v=$0
            sub(/^TE=/, "", v)
            if (v == "ON") te_val="ON"
            else if (v == "OFF") te_val="OFF"
            else bad=1
          } else if ($0 ~ /^TEP=/) {
            v=$0
            sub(/^TEP=/, "", v)
            if (v == "ON" || v == "OFF") { bool_seen++; bool_val=v }
            else if (v != "") { path_seen++; path_val=v }
            else { path_seen++ }
          } else {
            bad=1
          }
        }
        END {
          if (n != 3 || bad || te_seen != 1 || bool_seen != 1 || path_seen != 1)
            print "bad|"
          else if (te_val == "OFF")
            print "te_off|"
          else if (bool_val == "OFF")
            print "tep_off|"
          else if (path_val == "")
            print "path_empty|"
          else
            print "pass|" path_val
        }
      ')
      TCHK_STATE=${TCHK_PARSED%%\|*}
      TCHK_PATH=${TCHK_PARSED#*\|}
      case "$TCHK_STATE" in
        pass)
          add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
              PASS med "TE=ON TEP=ON TEP=$TCHK_PATH" \
              "Trusted Execution is ON, the Trusted Execution Path boolean is ON, and the TEP compiler PATH string is non-empty — both protections are active." \
              "n/a" "cis-l2"
          ;;
        te_off)
          add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
              FAIL med "TE=OFF" \
              "Trusted Execution is OFF — executed programs are not signature-verified against the trust database." \
              "as root, run 'trustchk -p TE=ON', then confirm with 'trustchk -p TE TEP'." "cis-l2"
          ;;
        tep_off)
          add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
              FAIL med "TEP=OFF" \
              "The Trusted Execution Path is OFF — executable search is not restricted to the configured compiler PATH." \
              "as root, run 'trustchk -p TEP=ON', then confirm with 'trustchk -p TE TEP'." "cis-l2"
          ;;
        path_empty)
          add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
              FAIL med "TEP=" \
              "Both TE and the TEP boolean are ON, but the TEP compiler PATH string is empty — the path restricts nothing." \
              "as root, set a non-empty TEP PATH with 'trustchk -p TEP=<path>', then confirm with 'trustchk -p TE TEP'." "cis-l2"
          ;;
        *)
          add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
              NOT_ASSESSED med "not assessed — trustchk -p TE TEP output unparseable (rc=0)" \
              "The successful capture did not have the expected shape (three lines: TE=, boolean TEP=, and a TEP= PATH), so PTxray cannot determine the TE/TEP state." \
              "as root, run 'trustchk -p TE TEP' manually and inspect the output shape." "cis-l2"
          ;;
      esac
      ;;
    127)
      add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
          NOT_ASSESSED med "not assessed — trustchk not executable (rc=127)" \
          "trustchk is mode 500 (owner root); a non-root run cannot execute it, and an absent binary also returns rc=127. PTxray cannot determine the TE/TEP state." \
          "run PTxray as root, or run 'trustchk -p TE TEP' manually as root." "cis-l2"
      ;;
    *)
      add security trustchk_te_tep "Trusted Execution and Trusted Execution Path enabled" \
          NOT_ASSESSED med "not assessed — trustchk -p TE TEP capture failed (rc=$TCHK_RC)" \
          "trustchk returned a non-zero exit status for an unknown reason, so PTxray cannot determine the TE/TEP state." \
          "as root, run 'trustchk -p TE TEP' manually and inspect the error." "cis-l2"
      ;;
  esac
_AIXRAY_SESSION_KEYS=""
  # trustchk_lock_kern — CIS control 2.3: kernel-loaded security policies must be
  # locked so they cannot be modified at runtime. A locked kernel enforces the
  # policy set loaded at boot and rejects runtime attempts to load, unload, or
  # replace a policy module; an unlocked kernel permits such changes.
  typeset TLS_KERN_RAW TLS_KERN_RC TLS_KERN_PARSE
  typeset TLS_STATUS TLS_SEV TLS_OBS TLS_MEAN TLS_FIX

  # `trustchk -p` writes policy values to STDERR on AIX 7.2 and 7.3 (verified live
  # 2026-08-05); aix() discards stderr, so without the 2>&1 merge this probe
  # returned rc=0 and empty output on every real box and the check refused.
  TLS_KERN_RAW=$(aixv trustchk_lock_kern trustchk -p LOCK_KERN_POLICIES)
  TLS_KERN_RC=$?

  TLS_SEV="high"
  case "$TLS_KERN_RC" in
    0)
      TLS_KERN_PARSE=$(printf '%s\n' "$TLS_KERN_RAW" | awk '
        /^LOCK_KERN_POLICIES=ON$/ { on++ }
        /^LOCK_KERN_POLICIES=OFF$/ { off++ }
        END {
          if (on == 1 && off == 0) print "on"
          else if (off == 1 && on == 0) print "off"
          else print "unparseable"
        }')
      case "$TLS_KERN_PARSE" in
        on)
          TLS_STATUS=PASS
          TLS_OBS="kernel security policies are locked (LOCK_KERN_POLICIES=ON)"
          TLS_MEAN="Kernel-loaded security policies are locked; the kernel enforces the policy set loaded at boot and rejects runtime attempts to load, unload, or replace a policy module."
          TLS_FIX="n/a"
          ;;
        off)
          TLS_STATUS=FAIL
          TLS_OBS="kernel security policies are not locked (LOCK_KERN_POLICIES=OFF)"
          TLS_MEAN="Kernel security policies are unlocked and can be modified at runtime, so the policy set in force is not necessarily the one loaded at boot."
          TLS_FIX="set LOCK_KERN_POLICIES=ON with 'trustchk -p LOCK_KERN_POLICIES=ON' and reboot so the locked policy set is loaded at boot; PTxray only recommends this action."
          ;;
        *)
          TLS_STATUS=NOT_ASSESSED
          TLS_OBS="not assessed - trustchk -p LOCK_KERN_POLICIES output was unparseable"
          TLS_MEAN="PTxray could not interpret the trustchk output, so the kernel policy lock state is unknown."
          TLS_FIX="ensure 'trustchk -p LOCK_KERN_POLICIES' returns a single LOCK_KERN_POLICIES=ON or LOCK_KERN_POLICIES=OFF line, then rerun PTxray."
          ;;
      esac
      ;;
    127)
      # aix() returns 127 for BOTH a genuinely absent trustchk and a fixture
      # that never captured this probe. Only the former is determinate
      # non-applicability; a missing capture is an honest refusal (round-3 D3).
      if aix_capture_missing trustchk_lock_kern; then
        TLS_STATUS=NOT_ASSESSED
        TLS_OBS="not assessed - trustchk_lock_kern probe was not captured for this system"
        TLS_MEAN="The trustchk -p LOCK_KERN_POLICIES capture is absent from this scan fixture set, so PTxray cannot tell whether trustchk is genuinely absent or merely unrecorded."
        TLS_FIX="capture 'trustchk -p LOCK_KERN_POLICIES' from a representative AIX host, then rerun PTxray."
      else
        TLS_STATUS=NOT_APPLICABLE
        TLS_OBS="not applicable - trustchk not found; Trusted Execution subsystem absent"
        TLS_MEAN="The trustchk command is not present, so the Trusted Execution subsystem is not installed on this system and the control does not apply."
        TLS_FIX="n/a"
      fi
      ;;
    *)
      TLS_STATUS=NOT_ASSESSED
      TLS_OBS="not assessed - trustchk -p LOCK_KERN_POLICIES capture failed (rc=$TLS_KERN_RC)"
      TLS_MEAN="PTxray could not read the kernel policy lock state, so the state is unknown."
      TLS_FIX="ensure 'trustchk -p LOCK_KERN_POLICIES' runs without error, then rerun PTxray."
      ;;
  esac

  add security trustchk_lock_kern "kernel policy lock state" \
    "$TLS_STATUS" "$TLS_SEV" \
    "$TLS_OBS" \
    "$TLS_MEAN" \
    "$TLS_FIX" \
    "cis-l2"
  if [ "$TLS_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="trustchk -p LOCK_KERN_POLICIES"
  fi
_AIXRAY_SESSION_KEYS=""

  # trustchk_chkexec — Trusted Execution (TE) must be active with CHKEXEC
  # enforcement enabled, and syslog must carry kern.info so execution
  # denials and allowances are logged.
  #
  # Probe 1: /usr/sbin/trustchk -p TE CHKEXEC
  #   rc=127 (binary absent)                        -> trustchk_absent
  #   rc=0   output has TE=ON and CHKEXEC=ON        -> te_chkexec_enabled
  #   rc=0   output missing TE=ON or CHKEXEC=ON     -> te_chkexec_disabled
  #   other nonzero rc (binary present, probe failed) -> trustchk_failed
  #
  # Probe 2: /usr/bin/grep kern.info /etc/syslog.conf
  #   rc=0 output non-empty  -> syslog_configured
  #   rc=1 no match          -> syslog_not_configured
  #   rc=2 file absent/unreadable -> syslog_file_absent
  #
  typeset TRUST_RC TRUST_RAW TRUST_TE TRUST_CHK TRUST_STATE
  typeset SYS_RC SYS_RAW SYS_STATE
  typeset TC_STATUS TC_SEV TC_OBS TC_MEAN TC_FIX

  # `trustchk -p` writes policy values to STDERR on AIX 7.2 and 7.3 (verified live
  # 2026-08-05); aix() discards stderr, so without the 2>&1 merge this probe
  # returned rc=0 and empty output on every real box and the check refused.
  TRUST_RAW=$(aixv trustchk_te_chkexec /usr/sbin/trustchk -p TE CHKEXEC)
  TRUST_RC=$?
  SYS_RAW=$(aix syslog_kern_info /usr/bin/grep kern.info /etc/syslog.conf)
  SYS_RC=$?

  # Classify probe 1.
  case "$TRUST_RC" in
    127)
      # aix() returns 127 for BOTH a genuinely absent trustchk and a fixture
      # that never captured this probe. Only the former is determinate
      # non-applicability; a missing capture is an honest refusal (round-3 D3).
      if aix_capture_missing trustchk_te_chkexec; then
        TRUST_STATE=uncaptured
      else
        TRUST_STATE=absent
      fi
      ;;
    0)
      TRUST_TE=0; TRUST_CHK=0
      case "$TRUST_RAW" in
        *TE=ON*) TRUST_TE=1 ;;
      esac
      case "$TRUST_RAW" in
        *CHKEXEC=ON*) TRUST_CHK=1 ;;
      esac
      if [ "$TRUST_TE" -eq 1 ] && [ "$TRUST_CHK" -eq 1 ]; then
        TRUST_STATE=enabled
      else
        TRUST_STATE=disabled
      fi
      ;;
    *)
      TRUST_STATE=failed
      ;;
  esac

  # Classify probe 2.
  case "$SYS_RC" in
    0)
      if [ -n "$SYS_RAW" ]; then
        SYS_STATE=configured
      else
        SYS_STATE=unknown
      fi
      ;;
    1)
      SYS_STATE=not_configured
      ;;
    2)
      SYS_STATE=file_absent
      ;;
    *)
      SYS_STATE=unknown
      ;;
  esac

  # Combine the two probe classifications into exactly one finding.
  case "$TRUST_STATE" in
    absent)
      TC_STATUS=NOT_APPLICABLE; TC_SEV=low
      TC_OBS="Trusted Execution not installed - /usr/sbin/trustchk absent"
      TC_MEAN="The Trusted Execution subsystem is not present on this host, so this control does not apply."
      TC_FIX="n/a"
      ;;
    uncaptured)
      TC_STATUS=NOT_ASSESSED; TC_SEV=low
      TC_OBS="not assessed - trustchk_te_chkexec probe was not captured for this system"
      TC_MEAN="The trustchk -p TE CHKEXEC capture is absent from this scan fixture set, so PTxray cannot tell whether Trusted Execution is genuinely absent or merely unrecorded."
      TC_FIX="capture '/usr/sbin/trustchk -p TE CHKEXEC' from a representative AIX host, then rerun PTxray."
      ;;
    disabled)
      TC_STATUS=FAIL; TC_SEV=high
      if [ "$TRUST_TE" -eq 0 ] && [ "$TRUST_CHK" -eq 0 ]; then
        TC_OBS="Trusted Execution disabled - TE and CHKEXEC are both off"
      elif [ "$TRUST_TE" -eq 0 ]; then
        TC_OBS="Trusted Execution disabled - TE is off"
      else
        TC_OBS="Trusted Execution disabled - CHKEXEC is off"
      fi
      TC_MEAN="Trusted Execution is not enforcing executable integrity with CHKEXEC; the control requires both attributes on."
      TC_FIX="enable TE and CHKEXEC with trustchk, restart the trustchk daemon, and re-run PTxray."
      ;;
    failed)
      TC_STATUS=NOT_ASSESSED; TC_SEV=high
      TC_OBS="not assessed - trustchk -p TE CHKEXEC probe failed (rc=$TRUST_RC)"
      TC_MEAN="PTxray could not read the Trusted Execution CHKEXEC state, so no enforcement verdict is possible."
      TC_FIX="run /usr/sbin/trustchk -p TE CHKEXEC manually, resolve the failure, and re-run PTxray."
      ;;
    enabled)
      case "$SYS_STATE" in
        configured)
          TC_STATUS=PASS; TC_SEV=low
          TC_OBS="Trusted Execution TE=ON CHKEXEC=ON and kern.info logging present"
          TC_MEAN="Trusted Execution enforces executable integrity with CHKEXEC, and syslog captures kern.info messages."
          TC_FIX="n/a"
          ;;
        not_configured)
          TC_STATUS=FAIL; TC_SEV=med
          TC_OBS="Trusted Execution on but syslog has no kern.info line"
          TC_MEAN="Execution denials and allowances will not be logged because syslog is not capturing kern.info messages."
          TC_FIX="add a kern.info line to /etc/syslog.conf and refresh syslogd."
          ;;
        file_absent)
          TC_STATUS=FAIL; TC_SEV=med
          TC_OBS="Trusted Execution on but /etc/syslog.conf absent or unreadable"
          TC_MEAN="kern.info logging cannot be assessed because /etc/syslog.conf is missing or unreadable."
          TC_FIX="restore /etc/syslog.conf with a kern.info line and refresh syslogd."
          ;;
        *)
          TC_STATUS=NOT_ASSESSED; TC_SEV=low
          TC_OBS="not assessed - syslog kern.info probe returned an unanticipated rc ($SYS_RC)"
          TC_MEAN="PTxray could not determine whether kern.info logging is configured."
          TC_FIX="inspect /etc/syslog.conf and re-run PTxray."
          ;;
      esac
      ;;
    *)
      TC_STATUS=NOT_ASSESSED; TC_SEV=high
      TC_OBS="not assessed - trustchk probe returned an unanticipated rc ($TRUST_RC)"
      TC_MEAN="PTxray could not read the Trusted Execution CHKEXEC state."
      TC_FIX="run /usr/sbin/trustchk -p TE CHKEXEC manually, resolve the failure, and re-run PTxray."
      ;;
  esac

  add security trustchk_chkexec "Trusted Execution CHKEXEC" \
    "$TC_STATUS" "$TC_SEV" "$TC_OBS" "$TC_MEAN" "$TC_FIX" "cis-l1"
  if [ "$TC_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="/usr/sbin/trustchk -p TE CHKEXEC"
  fi
_AIXRAY_SESSION_KEYS=""
  # trustchk_stop_untrusted — report whether the Trusted Execution policy keys
  # that gate load-time validation of untrusted executables all hold compliant
  # values. Three keys are probed: STOP_UNTRUSTD (ON or TROJAN), STOP_ON_CHKFAIL
  # (ON) and TE (ON). Any one off means the host will run binaries that were
  # never validated. Probe: one read-only trustchk -p query.
  #
  # Verdict logic:
  #   rc=0  and all three keys present and compliant  => PASS
  #   rc=0  and any key present with OFF              => FAIL
  #   rc=0  but a key missing / a key holds an
  #         unrecognised value / output is not
  #         KEY=VALUE lines                           => NOT_ASSESSED
  #   rc!=0 or not root                               => NOT_ASSESSED
  #
  typeset TRUSTCK_RC TRUSTCK_RAW TRUSTCK_SHAPE
  typeset TRUSTCK_STATUS TRUSTCK_OBSERVED TRUSTCK_MEANING TRUSTCK_FIX TRUSTCK_SEV
  TRUSTCK_RC=0
  TRUSTCK_RAW=""
  TRUSTCK_SHAPE=""

  if [ "${MYUID:-0}" != "0" ]; then
    TRUSTCK_STATUS=NOT_ASSESSED
    TRUSTCK_OBSERVED="not assessed - trustchk policy query requires root"
  else
    # `trustchk -p` writes policy values to STDERR on AIX 7.2 and 7.3 (verified
    # live 2026-08-05); aix() discards stderr, so without the 2>&1 merge this
    # probe returned rc=0 and empty output on every real box and the check
    # refused with "missing key(s)".
    TRUSTCK_RAW=$(aixv trustchk_policy trustchk -p stop_untrustd stop_on_chkfail te)
    TRUSTCK_RC=$?
    case "$TRUSTCK_RC" in
      0)
        TRUSTCK_SHAPE=$(printf '%s\n' "$TRUSTCK_RAW" | awk '
          {
            line = $0
            sub(/^[ \t]+/, "", line)
            sub(/[ \t]+$/, "", line)
            if (line == "") next
            n = index(line, "=")
            if (n == 0) { unparseable = 1; next }
            key = substr(line, 1, n - 1)
            val = substr(line, n + 1)
            if (key == "STOP_UNTRUSTD") {
              found_u = 1
              if (val == "ON" || val == "TROJAN") { u_ok = 1 }
              else if (val == "OFF") { u_bad = 1 }
              else { u_unknown = 1 }
            } else if (key == "STOP_ON_CHKFAIL") {
              found_c = 1
              if (val == "ON") { c_ok = 1 }
              else if (val == "OFF") { c_bad = 1 }
              else { c_unknown = 1 }
            } else if (key == "TE") {
              found_t = 1
              if (val == "ON") { t_ok = 1 }
              else if (val == "OFF") { t_bad = 1 }
              else { t_unknown = 1 }
            } else {
              unparseable = 1
            }
          }
          END {
            bad = ""
            if (u_bad) bad = "STOP_UNTRUSTD"
            if (c_bad) bad = bad (bad != "" ? "," : "") "STOP_ON_CHKFAIL"
            if (t_bad) bad = bad (bad != "" ? "," : "") "TE"
            missing = ""
            if (!found_u) missing = "STOP_UNTRUSTD"
            if (!found_c) missing = missing (missing != "" ? "," : "") "STOP_ON_CHKFAIL"
            if (!found_t) missing = missing (missing != "" ? "," : "") "TE"
            unknown = ""
            if (u_unknown) unknown = "STOP_UNTRUSTD"
            if (c_unknown) unknown = unknown (unknown != "" ? "," : "") "STOP_ON_CHKFAIL"
            if (t_unknown) unknown = unknown (unknown != "" ? "," : "") "TE"
            if (unparseable) print "unparseable"
            else if (bad != "") print "fail:" bad
            else if (missing != "") print "missing:" missing
            else if (unknown != "") print "unknown:" unknown
            else if (found_u && found_c && found_t) print "pass"
            else print "unparseable"
          }')
        case "$TRUSTCK_SHAPE" in
          pass)
            TRUSTCK_STATUS=PASS
            TRUSTCK_OBSERVED="trustchk policy in compliant state"
            ;;
          fail:*)
            TRUSTCK_STATUS=FAIL
            TRUSTCK_OBSERVED="trustchk policy non-compliant for key(s): ${TRUSTCK_SHAPE#fail:}"
            ;;
          missing:*)
            TRUSTCK_STATUS=NOT_ASSESSED
            TRUSTCK_OBSERVED="not assessed - trustchk policy output missing key(s): ${TRUSTCK_SHAPE#missing:}"
            ;;
          unknown:*)
            TRUSTCK_STATUS=NOT_ASSESSED
            TRUSTCK_OBSERVED="not assessed - trustchk policy key holds an unrecognised value"
            ;;
          *)
            TRUSTCK_STATUS=NOT_ASSESSED
            TRUSTCK_OBSERVED="not assessed - trustchk policy output could not be parsed into KEY=VALUE lines"
            ;;
        esac
        ;;
      *)
        TRUSTCK_STATUS=NOT_ASSESSED
        TRUSTCK_OBSERVED="not assessed - trustchk policy probe failed (rc=$TRUSTCK_RC)"
        ;;
    esac
  fi

  case "$TRUSTCK_STATUS" in
    PASS)
      TRUSTCK_MEANING="All three Trusted Execution policy keys hold compliant values, so load-time validation of untrusted executables is enforced."
      TRUSTCK_FIX="n/a"
      TRUSTCK_SEV=med
      ;;
    FAIL)
      TRUSTCK_MEANING="A Trusted Execution policy key is set so the host will run binaries that were never validated."
      TRUSTCK_FIX="as the TE admin, set each offending key to its compliant value with trustchk; PTxray only recommends these actions."
      TRUSTCK_SEV=med
      ;;
    *)
      TRUSTCK_MEANING="PTxray did not obtain trustworthy Trusted Execution policy evidence."
      TRUSTCK_FIX="run \"trustchk -p stop_untrustd stop_on_chkfail te\" as root, resolve the read or shape problem, and rerun PTxray."
      TRUSTCK_SEV=low
      ;;
  esac

  add security trustchk_stop_untrusted "TE policy gates load-time validation of untrusted executables" \
    "$TRUSTCK_STATUS" "$TRUSTCK_SEV" \
    "$TRUSTCK_OBSERVED" \
    "$TRUSTCK_MEANING" \
    "$TRUSTCK_FIX" \
    "cis-l2"
_AIXRAY_SESSION_KEYS=""
  # trustchk_untrusted_scan (CIS control 2.6, Level 2) — does every installed
  # file match the system's trusted signature database? AIX ships trustchk,
  # which compares the installed software inventory against a trusted signature
  # database and writes any unmatched (untrusted) file report to stderr. A
  # compliant system has an empty untrusted list. Read-only: the scan only reads
  # state; it never modifies the inventory or the signature database.
  #
  # trustchk exits NON-ZERO when it finds violations: rc=114 with an empty
  # stdout and the whole report on stderr is what BOTH healthy lab boxes
  # returned on 2026-08-06 (117 report lines on aix73, 167 on aix72). Refusing
  # on any non-zero rc therefore rendered NOT_ASSESSED on every real machine —
  # a refusal, not coverage. The rc is classified only AFTER the report is
  # parsed: a parsed violation line is determinate evidence of FAIL whatever
  # the rc, and only a non-zero rc with nothing parseable is genuinely unknown.
  typeset TRUSTCHK_AVAILABLE_RC TRUSTCHK_SCAN_RC
  typeset TRUSTCHK_PATH TRUSTCHK_SCAN_OUT TRUSTCHK_SUMMARY TRUSTCHK_DIAG
  TRUSTCHK_AVAILABLE_RC=127
  TRUSTCHK_SCAN_RC=127
  TRUSTCHK_PATH=""
  TRUSTCHK_SCAN_OUT=""
  TRUSTCHK_SUMMARY=""
  TRUSTCHK_DIAG=""

  # Probe 1: is the scan tool present? whence is the ksh builtin lookup; its rc
  # is 0 when trustchk resolves and non-zero when it does not.
  TRUSTCHK_PATH=$(aix trustchk_available whence trustchk)
  TRUSTCHK_AVAILABLE_RC=$?

  if [ "$TRUSTCHK_AVAILABLE_RC" -ne 0 ]; then
    add security trustchk_untrusted_scan "Untrusted file scan" NOT_ASSESSED low \
        "not assessed — trustchk not found (rc=$TRUSTCHK_AVAILABLE_RC)" \
        "The trusted-signature scan tool is not present on this system, so the installed software inventory could not be compared against the trusted signature database." \
        "install the trustchk tool and its trusted signature database, then rerun PTxray." \
        "cis-l2"
  else
    # Probe 2: run the scan. trustchk writes its report to stderr, so capture
    # stdout and stderr merged and read the combined stream.
    TRUSTCHK_SCAN_OUT=$(aixv trustchk_scan trustchk -i -n tree /)
    TRUSTCHK_SCAN_RC=$?

    # Parse the report BEFORE looking at the rc. Two verified message shapes
    # name an offending file: the unregistered set-UID/set-GID form and the
    # per-attribute verification-failure form (the attribute name varies, so it
    # is matched generically). Anything else is not treated as a violation.
    # Prints one bounded summary line, or nothing at all when no violation line
    # was recognised — emptiness is the discriminator the verdict branches on.
    # Evidence is counts and file paths only; no other capture content escapes.
    TRUSTCHK_SUMMARY=$(printf '%s\n' "$TRUSTCHK_SCAN_OUT" | awk '
      {
        path = ""
        if ($0 ~ /^trustchk: The untrusted file .* is an unregistered set-[UG]ID program$/) {
          path = $0
          sub(/^trustchk: The untrusted file /, "", path)
          sub(/ is an unregistered set-[UG]ID program$/, "", path)
        } else if ($0 ~ /^trustchk: Verification of [^ ]* attribute is failing for the file \//) {
          path = $0
          sub(/^trustchk: Verification of [^ ]* attribute is failing for the file /, "", path)
        }
        if (path !~ /^\//) next
        lines++
        if (!(path in seen)) {
          seen[path] = 1
          files++
          order[files] = path
        }
      }
      END {
        if (lines == 0) exit 0
        report_noun = "reports"
        if (lines == 1) report_noun = "report"
        file_noun = "files"
        if (files == 1) file_noun = "file"
        head = lines " untrusted-file " report_noun ", " files " " file_noun
        list = ""
        shown = 0
        for (i = 1; i <= files; i++) {
          if (shown >= 3) break
          p = order[i]
          if (length("" p) > 40) p = substr(p, 1, 37) "..."
          if (shown == 0) cand = p
          else cand = list ", " p
          more = files - (shown + 1)
          suffix = ""
          if (more > 0) suffix = " +" more " more"
          if (length("" head) + 2 + length("" cand) + length("" suffix) > 120) break
          list = cand
          shown++
        }
        if (shown == 0) { print head; exit 0 }
        more = files - shown
        if (more > 0) print head ": " list " +" more " more"
        else print head ": " list
      }')

    if [ "$TRUSTCHK_SCAN_RC" -eq 0 ] && [ -z "$TRUSTCHK_SUMMARY" ]; then
      add security trustchk_untrusted_scan "Untrusted file scan" PASS low \
          "no untrusted files reported" \
          "The trusted-signature scan completed and every installed file matched the trusted signature database; no untrusted file was reported." \
          "n/a" \
          "cis-l2"
    elif [ -n "$TRUSTCHK_SUMMARY" ]; then
      # Determinate: the scan ran far enough to name at least one file that
      # failed the trusted-signature comparison, whatever exit code it chose.
      add security trustchk_untrusted_scan "Untrusted file scan" FAIL high \
          "$TRUSTCHK_SUMMARY" \
          "At least one installed file did not match the trusted signature database. The installed inventory deviates from the system's trusted signatures and must be investigated and remediated." \
          "review the untrusted files named by 'trustchk -i -n tree /', verify their provenance, and restore or remove them, then rerun PTxray." \
          "cis-l2"
    else
      # Non-zero rc and nothing parseable: the scan did not get far enough to
      # name a file, so the state is genuinely unknown. Carry the real rc and
      # the first diagnostic line so the refusal is actionable, not opaque.
      TRUSTCHK_DIAG=$(printf '%s\n' "$TRUSTCHK_SCAN_OUT" | awk 'NF { gsub(/[ \t]+/, " "); sub(/^ /, ""); sub(/ $/, ""); if (length("" $0) > 40) $0 = substr($0, 1, 37) "..."; print; exit }')
      if [ -n "$TRUSTCHK_DIAG" ]; then
        TRUSTCHK_DIAG=": $TRUSTCHK_DIAG"
      fi
      add security trustchk_untrusted_scan "Untrusted file scan" NOT_ASSESSED low \
          "not assessed — trustchk scan failed (rc=$TRUSTCHK_SCAN_RC)$TRUSTCHK_DIAG" \
          "The trusted-signature scan itself failed without naming a single file, so whether any installed file is untrusted is unknown." \
          "run 'trustchk -i -n tree /' with the needed authority, resolve the scan failure, then rerun PTxray." \
          "cis-l2"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # dangling_symlink — a symbolic link whose target does not exist on a local
  # JFS/JFS2 filesystem. `find -L` follows symlinks; a link that cannot be
  # followed stays typed as `l`, so every `-type l` row confined to a local
  # filesystem by `-fstype` is a dangling link. The scan's stderr (mostly
  # unreadable-directory noise) is discarded by the aix() capture helper, so
  # the probe contract is exactly the documented command.
  #   rc=0    + empty output  -> PASS           no dangling symlinks
  #   rc=0    + output        -> FAIL           at least one dangling symlink
  #   rc!=0   + output        -> FAIL           scan hit errors but links still found
  #   rc!=0   + empty output  -> NOT_ASSESSED   scan failed; filesystem state unknown
  typeset SLD_OUT SLD_RC SLD_STATUS SLD_SEV SLD_OBSERVED SLD_MEANING SLD_FIX
  typeset SLD_COUNT SLD_EXCERPT

  SLD_OUT=$(aix dangling_symlink_scan find -L / \( -fstype jfs -o -fstype jfs2 \) -type l -ls)
  SLD_RC=$?

  case "$SLD_RC" in
    0)
      if [ -z "$SLD_OUT" ]; then
        SLD_STATUS=PASS
        SLD_SEV=low
        SLD_OBSERVED="no dangling symlinks on local JFS/JFS2 filesystems"
      else
        SLD_STATUS=FAIL
        SLD_SEV=med
        SLD_COUNT=$(printf '%s\n' "$SLD_OUT" | awk 'NF {n++} END {print n+0}')
        SLD_EXCERPT=$(printf '%s\n' "$SLD_OUT" | awk 'NF && shown < 3 { if (shown++) printf " | "; printf "%s", $0 }')
        SLD_OBSERVED="$SLD_COUNT dangling symlink(s) on local filesystems: $SLD_EXCERPT"
      fi
      ;;
    *)
      if [ -z "$SLD_OUT" ]; then
        SLD_STATUS=NOT_ASSESSED
        SLD_SEV=med
        SLD_OBSERVED="not assessed - dangling-symlink scan failed (rc=$SLD_RC) with no output"
      else
        SLD_STATUS=FAIL
        SLD_SEV=med
        SLD_COUNT=$(printf '%s\n' "$SLD_OUT" | awk 'NF {n++} END {print n+0}')
        SLD_EXCERPT=$(printf '%s\n' "$SLD_OUT" | awk 'NF && shown < 3 { if (shown++) printf " | "; printf "%s", $0 }')
        SLD_OBSERVED="$SLD_COUNT dangling symlink(s) found despite partial scan failure (rc=$SLD_RC): $SLD_EXCERPT"
      fi
      ;;
  esac

  case "$SLD_STATUS" in
    PASS)
      SLD_MEANING="Every symbolic link on a local JFS/JFS2 filesystem resolves to an existing target."
      SLD_FIX="n/a"
      ;;
    FAIL)
      SLD_MEANING="A symbolic link whose target does not exist on the filesystem was found. The link remains in place but resolves to nothing, and the path it names could be claimed later by a different actor."
      SLD_FIX="remove each dangling symlink, or retarget it to the path it should resolve to."
      ;;
    *)
      SLD_MEANING="PTxray could not determine whether dangling symlinks exist because the scan did not complete."
      SLD_FIX="investigate why the local-filesystem find scan did not complete, then rerun PTxray."
      ;;
  esac

  add security dangling_symlink "Dangling symbolic links on local filesystems" \
    "$SLD_STATUS" "$SLD_SEV" "$SLD_OBSERVED" \
    "$SLD_MEANING" "$SLD_FIX"
_AIXRAY_SESSION_KEYS=""
  # umask_default — default user umask boundary for control 3.1. Trust only
  # one exact attribute-scoped lssec assignment.

  typeset UD_RAW UD_RC UD_NONBLANK UD_LINE UD_MATCH
  typeset UD_REASON UD_FAILURE UD_STATUS
  UD_RAW=""
  UD_RC=126
  UD_REASON=""
  UD_FAILURE=""
  UD_STATUS=""

  UD_RAW=$(aix umask_default lssec -f /etc/security/user -s default -a umask)
  UD_RC=$?
  if [ "$UD_RC" -ne 0 ]; then
    UD_REASON="capture failed (rc=$UD_RC)"
  elif [ -z "$UD_RAW" ]; then
    UD_FAILURE="default umask attribute absent; AIX system default applies"
    UD_STATUS=FAIL
  else
    UD_NONBLANK=$(printf '%s\n' "$UD_RAW" |
      awk 'NF { count++ } END { print count + 0 }')
    if [ "$UD_NONBLANK" -ne 1 ]; then
      UD_REASON="output was not one exact assignment"
    else
      UD_LINE=$(printf '%s\n' "$UD_RAW" |
        awk 'NF { print; exit }')
      UD_MATCH=$(printf '%s\n' "$UD_LINE" |
        awk '$0 ~ /^default umask=[0-7]?[2367]7$/ { print "yes" }')
      if [ "$UD_MATCH" = "yes" ]; then
        UD_STATUS=PASS
      else
        UD_FAILURE="default umask present but less restrictive than 027"
        UD_STATUS=FAIL
      fi
    fi
  fi

  if [ -n "$UD_REASON" ]; then
    add security umask_default "Default umask" NOT_ASSESSED med \
        "not assessed — umask $UD_REASON" \
        "PTxray did not obtain one trustworthy default umask assignment, so it cannot claim the boundary is satisfied." \
        "run 'lssec -f /etc/security/user -s default -a umask', correct the capture or ambiguity, and rerun PTxray." \
        "cis-l1"
  elif [ "$UD_STATUS" = "PASS" ]; then
    add security umask_default "Default umask" PASS med \
        "default umask is at least as restrictive as 027" \
        "The default umask denies world all permissions and denies group write on newly created files and directories." \
        "n/a" "cis-l1"
  else
    add security umask_default "Default umask" FAIL med \
        "$UD_FAILURE" \
        "The default umask is missing or less restrictive than 027, so new files can be created with wider permissions than intended." \
        "set the default stanza umask attribute to 027 or stricter after validating local policy; PTxray recommends this change and never executes it." \
        "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
  # worldwrite_dirs_nosvtx — control 3.2.  A world-writable directory that
  # lacks the sticky bit (SVTX, mode 01000) lets any local user delete or
  # rename files they do not own inside it, opening denial-of-service and
  # privilege-escalation paths through predictable-name races in shared space.
  # Probe: one find over the whole tree restricted to JFS/JFS2 filesystems,
  # selecting world-writable directories that lack SVTX and emitting a
  # long-listing line per match.  find returns 0 after a complete traversal
  # whether or not it matched; per-directory permission denials go to stderr
  # and do not change rc.  A non-empty match list is the violation evidence;
  # rc 1/2 is a fatal probe failure and the state is unknown.
  typeset WWD_RAW WWD_RC WWD_STATUS WWD_SEV WWD_OBSERVED WWD_MEANING WWD_FIX
  typeset WWD_N WWD_FIRST

  if [ "${MYUID:-0}" != "0" ]; then
    WWD_STATUS=NOT_ASSESSED
    WWD_SEV=low
    WWD_OBSERVED="not assessed - world-writable directory probe requires root for a complete traversal"
  else
    WWD_RAW=$(aix worldwrite_dirs_nosvtx \
      find / \( -fstype jfs -o -fstype jfs2 \) -type d -perm -o+w ! -perm -1000 -ls)
    WWD_RC=$?
    case "$WWD_RC" in
      0)
        if [ -z "$WWD_RAW" ]; then
          WWD_STATUS=PASS
          WWD_SEV=low
          WWD_OBSERVED="no world-writable JFS/JFS2 directories missing the sticky bit"
        else
          WWD_N=$(printf '%s\n' "$WWD_RAW" | awk 'END { print NR }')
          WWD_FIRST=$(printf '%s\n' "$WWD_RAW" | awk 'NR==1 { print $3 " " $NF }')
          WWD_STATUS=FAIL
          WWD_SEV=high
          WWD_OBSERVED="${WWD_N} world-writable JFS/JFS2 directorie(s) missing the sticky bit, first: ${WWD_FIRST}"
        fi
        ;;
      1|2)
        WWD_STATUS=NOT_ASSESSED
        WWD_SEV=low
        WWD_OBSERVED="not assessed - find returned rc=$WWD_RC - traversal failed"
        ;;
      *)
        WWD_STATUS=NOT_ASSESSED
        WWD_SEV=low
        WWD_OBSERVED="not assessed - find returned rc=$WWD_RC - traversal failed"
        ;;
    esac
  fi

  case "$WWD_STATUS" in
    PASS)
      WWD_MEANING="No world-writable JFS/JFS2 directory is missing the sticky bit, so no shared directory lets an unprivileged user delete or rename files they do not own."
      WWD_FIX="n/a"
      ;;
    FAIL)
      WWD_MEANING="A world-writable JFS/JFS2 directory lacks the sticky bit, letting any local user delete or rename files they do not own inside it and enabling denial-of-service or privilege-escalation through predictable-name races."
      WWD_FIX="set the sticky bit with 'chmod +t <path>' on each listed directory, after confirming no workflow depends on unowned deletion there."
      ;;
    *)
      WWD_MEANING="PTxray did not obtain trustworthy evidence of the world-writable directory state."
      WWD_FIX="run the find probe as root, resolve the probe problem, and rerun PTxray."
      ;;
  esac

  add security worldwrite_dirs_nosvtx "World-writable JFS/JFS2 directories without sticky bit" \
    "$WWD_STATUS" "$WWD_SEV" "$WWD_OBSERVED" \
    "$WWD_MEANING" "$WWD_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # worldwrite_objects — group-writable non-directory objects on local (jfs/jfs2)
  # filesystems owned by an administrative group (control 3.3, L2). Absence is the
  # compliant state; each hit is an unreviewed group-write that needs operator triage.
  typeset WWO_RAW WWO_RC ADM_RAW ADM_RC ADM_LIST WWO_RESULT WWO_PARSE_RC
  typeset WWO_HITS WWO_PATHS

  WWO_RAW=$(aix ww_objects find -L / \( -fstype jfs -o -fstype jfs2 \) ! -type d -perm -g+w -ls)
  WWO_RC=$?
  ADM_RAW=$(aix admin_groups lsgroup -a admin ALL)
  ADM_RC=$?

  # `find -L` exits non-zero on any unreadable path or dangling symlink, which every
  # real AIX box has: on a lab LPAR the scan exits 1 while still emitting a complete
  # 120KB listing (verified 2026-08-05). Refusing on rc alone threw that evidence away
  # and made this control refuse on every real system.
  #
  # The two directions are not symmetric. An object the scan DID observe is conclusive
  # evidence of a violation, and a partial traversal cannot un-observe it -- so a hit
  # still FAILs. Absence is not provable from an incomplete traversal, so the PASS
  # direction must still refuse when the scan did not complete. That asymmetry is
  # handled at the verdict sites below; only a scan that produced nothing at all is
  # refused up front.
  if [ "$WWO_RC" -ne 0 ] && [ -z "$WWO_RAW" ]; then
    add security worldwrite_objects "group-writable admin-group objects" NOT_ASSESSED low \
        "not assessed — ww_objects failed (rc=$WWO_RC) and produced no listing" \
        "The group-writable-object scan did not complete and returned nothing, so PTxray cannot enumerate the objects that would need group-write review." \
        "Confirm the group-writable-object scan completes without error, then rerun PTxray." \
        "cis-l2"
  elif [ "$ADM_RC" -ne 0 ]; then
    add security worldwrite_objects "group-writable admin-group objects" NOT_ASSESSED low \
        "not assessed — admin_groups failed (rc=$ADM_RC)" \
        "The administrative-group enumeration did not complete, so PTxray cannot identify which objects' group-write would require review." \
        "Confirm the administrative-group enumeration completes without error, then rerun PTxray." \
        "cis-l2"
  elif [ -z "$WWO_RAW" ]; then
    # Reached only when the scan completed (rc=0), so empty output is a determinate
    # absence and PASS is earned rather than assumed.
    add security worldwrite_objects "group-writable admin-group objects" PASS low \
        "no group-writable admin-group objects on local filesystems" \
        "No non-directory group-writable object exists on a local jfs/jfs2 filesystem, so nothing requires group-write review." \
        "n/a" "cis-l2"
  elif [ -z "$ADM_RAW" ]; then
    add security worldwrite_objects "group-writable admin-group objects" PASS low \
        "no group-writable admin-group objects on local filesystems" \
        "No administrative group is defined, so no object's group-write can belong to an administrative group." \
        "n/a" "cis-l2"
  else
    ADM_LIST=$(printf '%s\n' "$ADM_RAW" | awk 'index($0,"true") {if (n++) printf " "; printf "%s", $1}')
    WWO_RESULT=$(printf '%s\n' "$WWO_RAW" | awk -v admins="$ADM_LIST" '
      BEGIN {
        na = split(admins, atmp, " ")
        for (i = 1; i <= na; i++) admin[atmp[i]] = 1
        nhits = 0
        npaths = 0
      }
      {
        # `find -ls` fields are fixed only through $6:
        #   $1 inode  $2 blocks  $3 perms  $4 links  $5 OWNER  $6 GROUP
        # After that the layout varies: a regular file has one size field, but a
        # device file has a "major," "minor" PAIR, which shifts everything right by
        # one. On a lab LPAR that is 345 of 1243 lines. So the path cannot be read
        # from a fixed index -- it is located as the first field beginning with "/",
        # and for a symlink it ends before the " -> " target.
        #
        # The group is $6. This previously tested $5, the OWNER, which is a different
        # thing entirely: on a lab LPAR it matched 40 objects where the correct
        # group test matches 1242 -- a 30x undercount on a security control, i.e. a
        # silent false NEGATIVE, the worst direction for this check to be wrong in.
        if (NF < 7) next
        if (!($6 in admin)) next
        pstart = 0
        for (i = 7; i <= NF; i++) {
          if (substr($i, 1, 1) == "/") { pstart = i; break }
        }
        if (pstart == 0) next
        nhits++
        if (npaths < 10) {
          path = $pstart
          for (i = pstart + 1; i <= NF; i++) {
            if ($i == "->") break
            path = path " " $i
          }
          paths[npaths++] = path
        }
      }
      END {
        out = ""
        for (i = 0; i < npaths; i++) {
          if (i > 0) out = out ", "
          out = out paths[i]
        }
        remaining = nhits - npaths
        if (remaining > 0) out = out " +" remaining " more"
        printf "%d|%s", nhits, out
      }')
    WWO_PARSE_RC=$?
    WWO_HITS=${WWO_RESULT%%\|*}
    WWO_PATHS=${WWO_RESULT#*\|}
    if [ "$WWO_PARSE_RC" -ne 0 ]; then
      add security worldwrite_objects "group-writable admin-group objects" NOT_ASSESSED low \
          "not assessed — worldwrite_objects parse failed (rc=$WWO_PARSE_RC)" \
          "The group-writable-object listing could not be parsed, so PTxray cannot enumerate the objects that would need group-write review." \
          "Rerun PTxray and report the parse failure." \
          "cis-l2"
    elif [ "$WWO_HITS" -eq 0 ] && [ "$WWO_RC" -ne 0 ]; then
      # Nothing found, but the traversal did not complete. Absence is exactly what an
      # incomplete scan cannot establish, so this must refuse rather than PASS.
      add security worldwrite_objects "group-writable admin-group objects" NOT_ASSESSED low \
          "not assessed — scan incomplete (rc=$WWO_RC) and no admin-group object was observed" \
          "No administratively-owned group-writable object was seen, but the filesystem traversal did not complete, so their absence is not established." \
          "Resolve the traversal errors (commonly unreadable paths or dangling symlinks under 'find -L'), then rerun PTxray." \
          "cis-l2"
    elif [ "$WWO_HITS" -eq 0 ]; then
      add security worldwrite_objects "group-writable admin-group objects" PASS low \
          "no group-writable admin-group objects on local filesystems" \
          "No non-directory group-writable object on a local jfs/jfs2 filesystem is owned by an administrative group, so none requires group-write review." \
          "n/a" "cis-l2"
    else
      add security worldwrite_objects "group-writable admin-group objects" FAIL high \
          "$WWO_PATHS" \
          "$WWO_HITS group-writable non-directory object(s) on local jfs/jfs2 filesystems are owned by an administrative group; their group-write permission has not been shown reviewed and approved." \
          "Review each listed object and either remove group-write where it is not required or record the approval. PTxray recommends the chmod command and never executes it." \
          "cis-l2"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # worldwrite_files — world-writable regular files on local JFS/JFS2 filesystems.
  # Probe: one find over / limited to jfs/jfs2 fstypes, listing regular files
  # whose mode grants write to "other". find returns rc=0 for these fstypes even
  # when nothing matches, so empty-vs-nonempty output is the whole verdict; the
  # listing is treated as raw output and never parsed field-by-field.
  typeset WW_RAW WW_RC WW_FIRST WW_STATUS WW_OBSERVED WW_MEANING WW_FIX

  WW_RAW=$(aix find_worldwrite find / \( -fstype jfs -o -fstype jfs2 \) -type f -perm -o+w -ls)
  WW_RC=$?

  case "$WW_RC" in
    0)
      if [ -z "$WW_RAW" ]; then
        WW_STATUS=PASS
        WW_OBSERVED="no world-writable regular file on any local JFS or JFS2 filesystem"
      else
        WW_FIRST=$(printf '%s\n' "$WW_RAW" | awk 'NF { print $NF; exit }')
        WW_STATUS=FAIL
        WW_OBSERVED="world-writable regular file(s) on JFS/JFS2, first: ${WW_FIRST:-unknown}"
      fi
      ;;
    *)
      WW_STATUS=NOT_ASSESSED
      WW_OBSERVED="not assessed - world-writable file probe failed (find rc=$WW_RC)"
      ;;
  esac

  case "$WW_STATUS" in
    PASS)
      WW_MEANING="Every regular file on a local JFS or JFS2 filesystem denies write permission to other users."
      WW_FIX="n/a"
      ;;
    FAIL)
      WW_MEANING="At least one regular file on a local JFS or JFS2 filesystem grants world write, exposing an unauthenticated file-modification path."
      WW_FIX="after confirming no application depends on the bit, remove world write with 'chmod o-w <path>' per listed file; PTxray only recommends this action."
      ;;
    *)
      WW_MEANING="PTxray did not obtain a trustworthy world-writable file listing."
      WW_FIX="run 'find / \\( -fstype jfs -o -fstype jfs2 \\) -type f -perm -o+w -ls' as root, resolve the probe failure, and rerun PTxray."
      ;;
  esac

  add security worldwrite_files "World-writable files on JFS/JFS2" \
    "$WW_STATUS" med "$WW_OBSERVED" \
    "$WW_MEANING" "$WW_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # groupwrite_staff_files — control 3.5. No regular file on a JFS or JFS2
  # filesystem may be both staff-group-owned and writable by that group.
  typeset GWS_RAW GWS_RC GWS_VALID GWS_REASON

  GWS_RAW=$(aix groupwrite_staff_find find / \( -fstype jfs -o -fstype jfs2 \) -type f -perm -g+w -group staff -ls)
  GWS_RC=$?
  GWS_VALID=0
  GWS_REASON=""

  if [ "$GWS_RC" -ne 0 ]; then
    GWS_REASON="probe failed (rc=$GWS_RC)"
  elif [ -z "$GWS_RAW" ]; then
    GWS_VALID=0
  else
    # Validity gate: a record is a genuine find -ls listing row — at least 11
    # space-separated fields with a mode string at field 1 (ls -l style) or, for
    # the inode-prefixed form the probe actually emits, a numeric inode with the
    # mode string at field 3. Any non-empty stdout with zero such rows refuses.
    GWS_VALID=$(printf '%s\n' "$GWS_RAW" | awk '
      function ismode(m,   n, i) {
        n = length("" m)
        if (n < 10 || n > 11) return 0
        if (substr(m, 1, 1) !~ /[-dlbcps]/) return 0
        for (i = 2; i <= 10; i++)
          if (substr(m, i, 1) !~ /[-rwxSsTt]/) return 0
        if (n == 11 && substr(m, 11, 1) !~ /[+@.]/) return 0
        return 1
      }
      NF {
        if (NF >= 11 && ismode($1)) valid++
        else if (NF >= 11 && $1 ~ /^[0-9][0-9]*$/ && ismode($3)) valid++
      }
      END { print (valid + 0) }
    ')
  fi

  if [ -n "$GWS_REASON" ]; then
    add security groupwrite_staff_files "Group-staff-writable files" NOT_ASSESSED med \
        "not assessed — $GWS_REASON" \
        "PTxray could not obtain one trustworthy file listing, so it cannot assert whether any regular file is both staff-group-owned and group-writable on a JFS or JFS2 filesystem." \
        "run 'find / \\( -fstype jfs -o -fstype jfs2 \\) -type f -perm -g+w -group staff -ls' manually, resolve the error, then rerun PTxray."
  elif [ -z "$GWS_RAW" ]; then
    add security groupwrite_staff_files "Group-staff-writable files" PASS low \
        "no matching files" \
        "No regular file on a JFS or JFS2 filesystem is both staff-group-owned and writable by that group." \
        "n/a"
  elif [ "$GWS_VALID" -gt 0 ]; then
    add security groupwrite_staff_files "Group-staff-writable files" FAIL med \
        "$GWS_VALID matching file(s)" \
        "At least one regular file on a JFS or JFS2 filesystem is both staff-group-owned and writable by that group; each such file is a violation regardless of path, mode, or content." \
        "confirm the listed files are intended, then remove group write where it is not: 'chmod g-w <path>'; PTxray recommends this command and never executes it."
  else
    add security groupwrite_staff_files "Group-staff-writable files" NOT_ASSESSED med \
        "listing unparseable" \
        "The file search returned text that is not recognizable as file-listing records, so no violation count can be trusted." \
        "rerun PTxray; if the same text persists, investigate why the find command produced it."
  fi
_AIXRAY_SESSION_KEYS=""
# unowned_files — control 3.6: local (jfs/jfs2) filesystem ownership boundary.
# One full traversal; any file or directory whose numeric owner or group does
# not resolve to a known identity is a finding. Root is required for a complete
# traversal; a non-root run exits rc=1 and reports the scan as incomplete.
typeset UF_RAW UF_RC UF_SUMMARY UF_COUNT UF_FIRST UF_OBS

UF_RAW=$(aix unowned_files_find /usr/bin/find / \( -fstype jfs -o -fstype jfs2 \) \( -type d -o -type f \) \( -nouser -o -nogroup \) -ls)
UF_RC=$?

# Trim captured stdout of leading/trailing whitespace before the empty/non-empty
# test so a trailing newline alone never reads as a finding. Each remaining
# non-empty line is one entry with an unresolvable owner or group.
UF_SUMMARY=$(printf '%s\n' "$UF_RAW" | awk '
  {
    sub(/^[ \t]+/, "")
    sub(/[ \t]+$/, "")
    if ($0 == "") next
    count++
    if (count == 1) {
      first = $11
      for (i = 12; i <= NF; i++) first = first " " $i
    }
  }
  END {
    printf "%d|%s", count, first
  }
')
UF_COUNT=${UF_SUMMARY%%\|*}
UF_FIRST=${UF_SUMMARY#*\|}

if [ "$UF_RC" -eq 0 ]; then
  if [ "$UF_COUNT" -eq 0 ]; then
    add security unowned_files "Unowned or ungrouped files on local filesystems" PASS low \
        "no unowned or ungrouped entries on jfs/jfs2 filesystems" \
        "Every file and directory on local jfs/jfs2 filesystems has an owner and group that resolve to a known identity." \
        "n/a" "cis-l1"
  else
    UF_OBS="$UF_COUNT unowned or ungrouped entries; first: $UF_FIRST"
    add security unowned_files "Unowned or ungrouped files on local filesystems" FAIL high \
        "$UF_OBS" \
        "Entries whose owner or group does not resolve to a known identity are detached from accountable identities and from any lifecycle that reassigns or removes them." \
        "Assign the correct owner and group after validating the entry, or remove it if orphaned; PTxray only recommends, never executes." "cis-l1"
  fi
elif [ "$UF_RC" -eq 1 ]; then
  if [ "$UF_COUNT" -ne 0 ]; then
    UF_OBS="$UF_COUNT unowned or ungrouped entries; first: $UF_FIRST"
    add security unowned_files "Unowned or ungrouped files on local filesystems" FAIL high \
        "$UF_OBS; scan incomplete (traversal errors)" \
        "The scan was partial because one or more paths could not be traversed, but violations were found in the traversable portion; additional violations may exist." \
        "Rerun as root for a complete traversal, then assign or remove the listed entries." "cis-l1"
  else
    add security unowned_files "Unowned or ungrouped files on local filesystems" NOT_ASSESSED low \
        "scan incomplete; no unowned or ungrouped entries in the traversable portion" \
        "Traversal errors (typically a non-root run) prevented a complete scan and no violations were found in what could be scanned, so completeness is unknown." \
        "Rerun PTxray as root for a complete traversal." "cis-l1"
  fi
else
  add security unowned_files "Unowned or ungrouped files on local filesystems" NOT_ASSESSED low \
        "probe failed (find rc=$UF_RC)" \
        "The find probe failed fatally, so the local filesystem ownership boundary could not be assessed." \
        "Inspect why find exited with rc=$UF_RC and rerun PTxray." "cis-l1"
fi
_AIXRAY_SESSION_KEYS=""
# cron_command_paths — CIS 4.1.1.17-aligned walk of every absolute-path command
# in the current user's crontab. The command file and each ancestor directory up
# to (but excluding) the filesystem root must be not group-writable, not
# world-writable, and owned by uid 0 or uid 2. Numeric ls -ldn is used so
# ownership is judged by uid, not by a passwd-derived name.
typeset CCP_CRON_RAW CCP_CRON_RC CCP_PATHS CCP_REASON CCP_P CCP_KEY
typeset CCP_LS_RAW CCP_LS_RC CCP_LS_PARSED CCP_LS_AWK_RC CCP_BAD CCP_NA CCP_VIOL

CCP_CRON_RAW=$(aix crontab_output crontab -l); CCP_CRON_RC=$?
CCP_REASON=""
CCP_BAD=0
CCP_NA=0
CCP_VIOL=""

# Phase 1: enumerate the crontab. rc=1 is the AIX no-crontab signal; anything
# greater is a genuine probe failure (rc not 0, 1, or 2 cannot be attributed).
if [ "$CCP_CRON_RC" -eq 1 ]; then
  CCP_REASON="no crontab for this user"
elif [ "$CCP_CRON_RC" -ne 0 ]; then
  CCP_REASON="crontab -l failed (rc=$CCP_CRON_RC)"
elif [ -z "$CCP_CRON_RAW" ]; then
  CCP_REASON="no crontab output"
else
  # Collect every absolute command path (cron field 6 starting with '/') plus
  # each ancestor directory, collapsing duplicates. Ancestors are the command
  # file itself, then the last path segment stripped off repeatedly; the root
  # itself is never a checked component. Comment and environment lines are not
  # commands and are skipped.
  CCP_PATHS=$(printf '%s\n' "$CCP_CRON_RAW" | awk '
    function ccp_strip(p, i, n) {
      n = length("" p)
      i = n
      while (i > 1 && substr(p, i, 1) != "/") i--
      if (i <= 1) return ""
      return substr(p, 1, i - 1)
    }
    function ccp_add(p, b, a) {
      if (p == "" || p == "/") return
      b = "\n" ccp_seen "\n"
      a = "\n" p "\n"
      if (index(b, a) == 0) ccp_seen = (ccp_seen == "" ? p : ccp_seen "\n" p)
    }
    {
      if (NF < 6) next
      if (substr($1, 1, 1) == "#") next
      if (substr($6, 1, 1) != "/") next
      ccp_add($6)
      p = ccp_strip($6)
      while (p != "") {
        ccp_add(p)
        p = ccp_strip(p)
      }
    }
    END { print ccp_seen }
  ')
  if [ -z "$CCP_PATHS" ]; then
    CCP_REASON="no absolute-path cron commands"
  else
    # Phase 2: inspect each unique path component. rc=2 means absent and is
    # silent; any other non-zero rc is a probe failure; rc=0 is parsed for the
    # group-write bit (mode char 6), the other-write bit (mode char 9) and the
    # numeric owner (field 3, allowed 0 or 2).
    while IFS= read -r CCP_P; do
      [ -n "$CCP_P" ] || continue
      CCP_KEY=$(printf '%s' "$CCP_P" | tr '/' '_')
      CCP_LS_RAW=$(aix "ls_ldn_$CCP_KEY" ls -ldn "$CCP_P"); CCP_LS_RC=$?
      if [ "$CCP_LS_RC" -eq 2 ]; then
        continue
      elif [ "$CCP_LS_RC" -ne 0 ]; then
        CCP_NA=1
        continue
      elif [ -z "$CCP_LS_RAW" ]; then
        CCP_NA=1
        continue
      fi
      CCP_LS_PARSED=$(printf '%s\n' "$CCP_LS_RAW" | awk '
        NF {
          records++
          if (records != 1 || NF < 9) { bad = 1; next }
          mode = $1
          if (length("" mode) == 11) {
            if (substr(mode, 11, 1) != "+") bad = 1
            else mode = substr(mode, 1, 10)
          } else if (length("" mode) != 10) bad = 1
          if (!bad) {
            if ($3 !~ /^[0-9][0-9]*$/) bad = 1
            else {
              if (substr(mode, 6, 1) == "w") gw = 1
              if (substr(mode, 9, 1) == "w") ow = 1
              if (($3 + 0) != 0 && ($3 + 0) != 2) owner = 1
            }
          }
        }
        END {
          if (records != 1 || bad) exit 1
          if (gw || ow || owner) print "VIOLATION"
          else print "CLEAN"
        }
      ')
      CCP_LS_AWK_RC=$?
      if [ "$CCP_LS_AWK_RC" -ne 0 ] || [ -z "$CCP_LS_PARSED" ]; then
        CCP_NA=1
      elif [ "$CCP_LS_PARSED" = "VIOLATION" ]; then
        CCP_BAD=1
        CCP_VIOL="$CCP_P"
      fi
    done <<EOF
$CCP_PATHS
EOF
  fi
fi

if [ -n "$CCP_REASON" ]; then
  case "$CCP_REASON" in
    "no crontab"*|"no absolute"*)
      add security cron_command_paths "cron command paths" NOT_APPLICABLE med \
        "n/a — $CCP_REASON" \
        "There are no absolute-path cron command paths to inspect for this user." \
        "n/a" "cis-l1"
      ;;
    *)
      add security cron_command_paths "cron command paths" NOT_ASSESSED med \
        "not assessed — $CCP_REASON" \
        "PTxray could not enumerate the crontab command paths, so it cannot assess them." \
        "run 'crontab -l', correct the probe problem, and rerun PTxray." "cis-l1"
      ;;
  esac
elif [ "$CCP_BAD" -eq 1 ]; then
  add security cron_command_paths "cron command paths" FAIL med \
    "a cron command path component is group-writable, world-writable, or owned by neither root(0) nor bin(2)" \
    "Every absolute-path command in the crontab, and each ancestor directory up to the root, must be not group-writable, not world-writable, and owned by uid 0 or 2. At least one inspected component ($CCP_VIOL) violates that boundary." \
    "after validation, correct the mode and owner of each offending path component; PTxray recommends this remediation and never executes it." "cis-l1"
elif [ "$CCP_NA" -eq 1 ]; then
  add security cron_command_paths "cron command paths" NOT_ASSESSED med \
    "not assessed — ls -ldn failed for at least one path component" \
    "PTxray could not obtain trustworthy metadata for every inspected path component, so it cannot certify the full command chain." \
    "run 'ls -ldn' on each crontab command path, correct the probe problem, and rerun PTxray." "cis-l1"
else
  add security cron_command_paths "cron command paths" PASS med \
    "all inspected cron command path components are clean" \
    "Every absolute-path command in the crontab, and each ancestor directory up to the root, is not group-writable, not world-writable, and owned by uid 0 or 2." \
    "n/a" "cis-l1"
fi
_AIXRAY_SESSION_KEYS=""
  # home_config_file_perms — user configuration files writable by group or other.
  # CIS L1-aligned. Two probes: lsuser enumeration of all local user homes, then one
  # bare-argv 'ls -lan' per qualifying home directory. Verdicts come from captured
  # output and rc only — never from a live filesystem walk. Qualifying homes are
  # non-system paths listed by 'lsuser -a home ALL'; system paths
  # (/ , /etc*, /bin*, /var*, /usr*) are excluded. Home paths are deduplicated:
  # multiple accounts naming the same directory are probed once under the first
  # account name seen.
  typeset HCFP_LSUSER_RAW HCFP_LSUSER_RC HCFP_HOME_COUNT HCFP_HOME_PARSE_RC
  typeset HCFP_CANDIDATES HCFP_CAND_RC
  typeset HCFP_PARSED_COUNT HCFP_VIOLATED HCFP_UNLISTABLE HCFP_REFUSAL
  typeset HCFP_LS_RAW HCFP_LS_RC HCFP_PARSE HCFP_PARSE_RC
  typeset HCFP_HOME_PARSED HCFP_HOME_VIOLATED
  typeset HCFP_STATUS HCFP_OBS HCFP_MEAN HCFP_FIX
  typeset HCFP_REC HCFP_ACCT HCFP_HOME

  HCFP_STATUS=NOT_ASSESSED
  HCFP_OBS=""
  HCFP_MEAN=""
  HCFP_FIX=""

  HCFP_LSUSER_RAW=$(aix home_config_lsuser lsuser -a home ALL)
  HCFP_LSUSER_RC=$?

  if [ "$HCFP_LSUSER_RC" -ne 0 ]; then
    HCFP_STATUS=NOT_ASSESSED
    HCFP_OBS="not assessed — user enumeration failed (rc=$HCFP_LSUSER_RC)"
    HCFP_MEAN="PTxray could not enumerate local users, so it cannot tell which home directories hold user configuration files."
    HCFP_FIX="run 'lsuser -a home ALL', correct the capture problem, and rerun PTxray."
  else
    HCFP_HOME_COUNT=$(printf '%s\n' "$HCFP_LSUSER_RAW" | awk '
      NF {
        if (NF != 2) next
        if (index($2, "home=") != 1) next
        home = substr($2, 6)
        if (home == "") next
        if (home ~ /^\/$|\/etc|\/bin|\/var|\/usr|\/usr\/sys/) next
        count++
      }
      END { print count + 0 }
    ')
    HCFP_HOME_PARSE_RC=$?
    if [ "$HCFP_HOME_PARSE_RC" -ne 0 ] || [ -z "$HCFP_HOME_COUNT" ]; then
      HCFP_STATUS=NOT_ASSESSED
      HCFP_OBS="not assessed — user home enumeration unparseable"
      HCFP_MEAN="PTxray could not derive the set of qualifying home directories from the captured user list."
      HCFP_FIX="run 'lsuser -a home ALL', correct the capture problem, and rerun PTxray."
    elif [ "$HCFP_HOME_COUNT" -eq 0 ]; then
      HCFP_STATUS=NOT_APPLICABLE
      HCFP_OBS="not applicable — no qualifying home directories"
      HCFP_MEAN="Every listed home directory is a system path, so there is no user configuration-file surface to assess."
      HCFP_FIX="n/a"
    else
      HCFP_CANDIDATES=$(printf '%s\n' "$HCFP_LSUSER_RAW" | awk '
        NF {
          if (NF != 2) next
          if (index($2, "home=") != 1) next
          home = substr($2, 6)
          if (home == "") next
          if (home ~ /^\/$|\/etc|\/bin|\/var|\/usr|\/usr\/sys/) next
          if (seen[home]) next
          seen[home] = 1
          print $1 "|" home
        }
      ')
      HCFP_CAND_RC=$?
      if [ "$HCFP_CAND_RC" -ne 0 ] || [ -z "$HCFP_CANDIDATES" ]; then
        HCFP_STATUS=NOT_ASSESSED
        HCFP_OBS="not assessed — could not extract candidate homes from user list"
        HCFP_MEAN="PTxray could not derive the set of qualifying home directories from the captured user list."
        HCFP_FIX="run 'lsuser -a home ALL', correct the capture problem, and rerun PTxray."
      else
        HCFP_PARSED_COUNT=0
        HCFP_VIOLATED=0
        HCFP_UNLISTABLE=""
        HCFP_REFUSAL=""

        for HCFP_REC in $HCFP_CANDIDATES; do
          HCFP_ACCT=${HCFP_REC%%\|*}
          HCFP_HOME=${HCFP_REC#*\|}

          HCFP_LS_RAW=$(aix "home_config_ls_$HCFP_ACCT" ls -lan "$HCFP_HOME")
          HCFP_LS_RC=$?

          if [ "$HCFP_LS_RC" -eq 0 ]; then
            HCFP_PARSE=$(printf '%s\n' "$HCFP_LS_RAW" | awk '
              {
                if ($1 == "total") next
                if (NF < 9) { unparsed++; next }
                mode = $1
                if (length("" mode) == 11) {
                  if (substr(mode, 11, 1) != "+") { unparsed++; next }
                  mode = substr(mode, 1, 10)
                } else if (length("" mode) != 10) {
                  unparsed++
                  next
                }
                if (substr(mode, 1, 1) != "-") next
                if ($NF !~ /^\.[a-z]/) next
                parsed++
                if (substr(mode, 6, 1) == "w" || substr(mode, 9, 1) == "w") violated++
              }
              END { print (parsed + 0) "|" (violated + 0) }
            ')
            HCFP_PARSE_RC=$?
            if [ "$HCFP_PARSE_RC" -ne 0 ] || [ -z "$HCFP_PARSE" ]; then
              HCFP_REFUSAL="home probe unparseable for account=$HCFP_ACCT home=$HCFP_HOME"
              break
            fi
            HCFP_HOME_PARSED=${HCFP_PARSE%%\|*}
            HCFP_HOME_VIOLATED=${HCFP_PARSE#*\|}
            HCFP_PARSED_COUNT=$(( HCFP_PARSED_COUNT + HCFP_HOME_PARSED ))
            HCFP_VIOLATED=$(( HCFP_VIOLATED + HCFP_HOME_VIOLATED ))
          elif [ "$HCFP_LS_RC" -eq 2 ]; then
            if [ -z "$HCFP_UNLISTABLE" ]; then
              HCFP_UNLISTABLE="$HCFP_ACCT"
            else
              HCFP_UNLISTABLE="$HCFP_UNLISTABLE $HCFP_ACCT"
            fi
          else
            HCFP_REFUSAL="home probe failed for account=$HCFP_ACCT home=$HCFP_HOME (rc=$HCFP_LS_RC)"
            break
          fi
        done

        if [ -n "$HCFP_REFUSAL" ]; then
          HCFP_STATUS=NOT_ASSESSED
          HCFP_OBS="not assessed — $HCFP_REFUSAL"
          HCFP_MEAN="PTxray could not enumerate configuration files in every qualifying home directory, so it cannot render a trustworthy verdict."
          HCFP_FIX="correct the home directory listing captures and rerun PTxray."
        elif [ "$HCFP_VIOLATED" -ne 0 ]; then
          HCFP_STATUS=FAIL
          if [ -n "$HCFP_UNLISTABLE" ]; then
            HCFP_OBS="$HCFP_VIOLATED of $HCFP_PARSED_COUNT user configuration files writable by group or other; home(s) not listable: $HCFP_UNLISTABLE"
          else
            HCFP_OBS="$HCFP_VIOLATED of $HCFP_PARSED_COUNT user configuration files writable by group or other"
          fi
          HCFP_MEAN="At least one user configuration file is writable by group or other, letting an unauthorized local identity alter a user's shell environment or stored credentials."
          HCFP_FIX="remove the group- and other-write bits after validation, e.g. 'chmod go-w <file>'; PTxray recommends this command and never executes it."
        elif [ "$HCFP_PARSED_COUNT" -gt 0 ]; then
          HCFP_STATUS=PASS
          if [ -n "$HCFP_UNLISTABLE" ]; then
            HCFP_OBS="$HCFP_PARSED_COUNT user configuration files, none writable by group or other; home(s) not listable: $HCFP_UNLISTABLE"
          else
            HCFP_OBS="$HCFP_PARSED_COUNT user configuration files, none writable by group or other"
          fi
          HCFP_MEAN="Every user configuration file found has neither the group-write nor the other-write bit set."
          HCFP_FIX="n/a"
        else
          if [ -n "$HCFP_UNLISTABLE" ]; then
            HCFP_STATUS=PASS
            HCFP_OBS="no user configuration files found; home(s) not listable: $HCFP_UNLISTABLE"
            HCFP_MEAN="No regular dotfile exists in any listable qualifying home directory, so none can carry a group- or other-write bit. One or more home directories could not be listed; their contents were not inspected."
            HCFP_FIX="verify the unlistable home directories exist and are accessible, then rerun PTxray."
          else
            HCFP_STATUS=PASS
            HCFP_OBS="no user configuration files found in any qualifying home directory"
            HCFP_MEAN="No regular dotfile exists in any qualifying home directory, so none can carry a group- or other-write bit."
            HCFP_FIX="n/a"
          fi
        fi
      fi
    fi
  fi

  add security home_config_file_perms "User configuration file permissions" \
    "$HCFP_STATUS" med "$HCFP_OBS" "$HCFP_MEAN" "$HCFP_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # Control 4.1.1.19 — every setuid/setgid file on the box must be authorized.
  #
  # Two stages, strictly in this order:
  #   1. The live inventory. One `find` restricted to the two privilege bits,
  #      with a `mount` read picking the whole-tree or JFS/JFS2 capture path.
  #      It ALWAYS runs, before any baseline decision. Until 2026-08-06 the
  #      "no baseline" branch returned first, so on every real box the find
  #      never executed and no capture ever carried suid_sgid_local /
  #      suid_sgid_all at all.
  #   2. Authorization, decided by the first layer that applies:
  #        a. site baseline   /etc/security/aixray-suid-sgid-baseline
  #        b. not-maintained  /etc/security/aixray-suid-sgid-baseline.override
  #                           (consulted only when no site baseline exists)
  #        c. shipped default: vendor ownership read from AIX's own package
  #           database, one `lslpp -w <path>` probe per discovered path.
  #      Site exceptions (…-baseline.allow) are authorized additions on top of
  #      whichever of (a) or (c) applied.
  #
  # No list of "stock AIX suid binaries" is hard-coded here. The only vendor
  # fact used is what lslpp reports on the box being assessed, and a path whose
  # ownership lslpp does not resolve is counted as unresolved, never as
  # authorized. This fragment never mutates the system and never manufactures
  # a clean result.
  typeset SSI_BASELINE SSI_ALLOW SSI_ALLOW_SRC SSI_OVERRIDE SSI_OVR
  typeset SSI_STATUS SSI_OBSERVED SSI_MEANING SSI_FIX SSI_SEV SSI_NOTE
  typeset SSI_MODE SSI_RAW SSI_RC SSI_ALL SSI_ALL_RC SSI_LOC SSI_LOC_RC SSI_MNT SSI_MNT_RC
  typeset SSI_SHAPE SSI_DELTA SSI_DRIFT SSI_EXC SSI_TOTAL SSI_UNSAFE
  typeset SSI_PATHS SSI_P SSI_KEY SSI_LW SSI_LW_RC SSI_CLASS
  typeset SSI_UNOWNED SSI_UNKNOWN

  SSI_BASELINE=/etc/security/aixray-suid-sgid-baseline
  SSI_ALLOW=${SSI_BASELINE}.allow
  SSI_OVERRIDE=${SSI_BASELINE}.override
  SSI_ALLOW_SRC=/dev/null
  SSI_OVR=""
  SSI_STATUS=NOT_ASSESSED
  SSI_OBSERVED=""
  SSI_NOTE=""
  SSI_MODE=local
  SSI_RAW=""
  SSI_RC=0
  SSI_ALL=""
  SSI_ALL_RC=0
  SSI_LOC=""
  SSI_LOC_RC=0
  SSI_SHAPE=""
  SSI_DELTA=0
  SSI_DRIFT=0
  SSI_EXC=0
  SSI_TOTAL=0
  SSI_UNSAFE=0
  SSI_PATHS=""
  SSI_P=""
  SSI_KEY=""
  SSI_LW=""
  SSI_LW_RC=0
  SSI_CLASS=unknown
  SSI_UNOWNED=0
  SSI_UNKNOWN=0

  if [ "${MYUID:-0}" != "0" ]; then
    SSI_STATUS=NOT_ASSESSED
    SSI_OBSERVED="not assessed - suid/sgid inventory probe requires root"
  else
    SSI_MNT=$(aix mount mount); SSI_MNT_RC=$?
    SSI_MODE=local
    if [ "$SSI_MNT_RC" -eq 0 ] && [ -n "$SSI_MNT" ]; then
      SSI_MODE=$(printf '%s\n' "$SSI_MNT" | awk '
        NR <= 2 { next }
        $1 ~ /^-+$/ { next }
        NF >= 3 && $3 != "jfs" && $3 != "jfs2" { nl = 1 }
        END { print (nl ? "local" : "all") }')
    fi
    [ -n "$SSI_MODE" ] || SSI_MODE=local
    # Stage 1 — the inventory probe is unconditional. A pure read.
    if [ "$SSI_MODE" = "all" ]; then
      SSI_ALL=$(aix suid_sgid_all find / \( -perm -04000 -o -perm -02000 \) -type f -ls); SSI_ALL_RC=$?
      if [ "$SSI_ALL_RC" -eq 0 ]; then
        SSI_RAW=$SSI_ALL
      fi
      SSI_RC=$SSI_ALL_RC
    else
      SSI_LOC=$(aix suid_sgid_local find / \( -fstype jfs -o -fstype jfs2 \) \( -perm -04000 -o -perm -02000 \) -type f -ls); SSI_LOC_RC=$?
      if [ "$SSI_LOC_RC" -eq 0 ]; then
        SSI_RAW=$SSI_LOC
      fi
      SSI_RC=$SSI_LOC_RC
    fi

    SSI_TOTAL=$(printf '%s\n' "$SSI_RAW" | awk 'NF && $NF ~ /^\// { n++ } END { print n+0 }')
    [ -n "$SSI_TOTAL" ] || SSI_TOTAL=0
    if [ "$SSI_RC" -ne 0 ]; then
      SSI_STATUS=NOT_ASSESSED
      SSI_OBSERVED="not assessed - suid/sgid find probe failed (rc=$SSI_RC)"
    elif [ "$SSI_TOTAL" -eq 0 ]; then
      SSI_STATUS=NOT_ASSESSED
      SSI_OBSERVED="not assessed - suid/sgid inventory returned no rows; a running AIX system always carries setuid/sgid files, so an empty inventory is not evidence"
    else
      if [ -f "$SSI_ALLOW" ] && [ -r "$SSI_ALLOW" ]; then
        SSI_ALLOW_SRC=$SSI_ALLOW
      fi
      # Stage 2 — layer precedence: site baseline, then the recorded
      # not-maintained decision, then the shipped fileset-ownership default.
      if [ -f "$SSI_BASELINE" ] && [ ! -r "$SSI_BASELINE" ]; then
        SSI_STATUS=NOT_ASSESSED
        SSI_OBSERVED="not assessed - suid/sgid inventory baseline exists but is not readable"
      elif [ -f "$SSI_BASELINE" ]; then
        # Layer (a). The baseline and the exception file are read as awk file
        # operands, dispatched by FILENAME; the live inventory arrives last on
        # stdin. An absent exception file is replaced by /dev/null so the
        # operand list never changes shape.
        SSI_SHAPE=$(printf '%s\n' "$SSI_RAW" | awk -v bl="$SSI_BASELINE" -v al="$SSI_ALLOW_SRC" '
          function clean(v) {
            sub(/^[ \t]+/, "", v)
            sub(/[ \t]+$/, "", v)
            return v
          }
          FILENAME == bl {
            if ($0 ~ /^[ \t]*$/ || $0 ~ /^[ \t]*#/) next
            entry = clean($0)
            if (entry != "") base[entry] = 1
            next
          }
          FILENAME == al {
            if ($0 ~ /^[ \t]*$/ || $0 ~ /^[ \t]*#/) next
            entry = clean($0)
            if (entry != "") allow[entry] = 1
            next
          }
          {
            if ($0 ~ /^[ \t]*$/) next
            live[$NF] = 1
            if (!($NF in base)) {
              if ($NF in allow) exc[$NF] = 1
              else delta[$NF] = 1
            }
          }
          END {
            nd = 0
            for (p in delta) nd++
            ne = 0
            for (p in exc) ne++
            ndr = 0
            for (p in base) if (!(p in live)) ndr++
            printf "delta:%d:exc:%d:drift:%d", nd, ne, ndr
          }' "$SSI_BASELINE" "$SSI_ALLOW_SRC" -)
        case "$SSI_SHAPE" in
          delta:*:exc:*:drift:*)
            SSI_DELTA=${SSI_SHAPE#delta:}
            SSI_DELTA=${SSI_DELTA%%:exc:*}
            SSI_EXC=${SSI_SHAPE#*:exc:}
            SSI_EXC=${SSI_EXC%%:drift:*}
            SSI_DRIFT=${SSI_SHAPE##*:drift:}
            if [ "$SSI_EXC" -gt 0 ]; then
              SSI_NOTE="$SSI_NOTE; +$SSI_EXC site exception(s)"
            fi
            if [ "$SSI_DRIFT" -gt 0 ]; then
              SSI_NOTE="$SSI_NOTE; $SSI_DRIFT baseline path(s) absent"
            fi
            if [ "$SSI_DELTA" -gt 0 ]; then
              SSI_STATUS=FAIL
              SSI_OBSERVED="$SSI_DELTA of $SSI_TOTAL setuid/sgid file(s) are not in the approved baseline$SSI_NOTE"
            else
              SSI_STATUS=PASS
              SSI_OBSERVED="all $SSI_TOTAL setuid/sgid file(s) are in the approved baseline$SSI_NOTE"
            fi
            ;;
          *)
            SSI_STATUS=NOT_ASSESSED
            SSI_OBSERVED="not assessed - suid/sgid baseline comparison produced no result"
            ;;
        esac
      else
        if [ -f "$SSI_OVERRIDE" ]; then
          SSI_OVR=$(awk '!/^[ \t]*$/ && !/^[ \t]*#/ { print $0; exit }' "$SSI_OVERRIDE" 2>/dev/null)
        fi
        if [ "$SSI_OVR" = "not-maintained" ]; then
          # Layer (b).
          SSI_STATUS=NOT_APPLICABLE
          SSI_OBSERVED="not applicable - a recorded decision states no suid/sgid inventory baseline is maintained"
        else
          # Layer (c). Candidates are the discovered paths minus the site
          # exceptions. A path carrying shell glob metacharacters cannot be
          # handed to the per-path probe safely, so it is counted unresolved
          # rather than dropped.
          SSI_PATHS=$(printf '%s\n' "$SSI_RAW" | awk -v al="$SSI_ALLOW_SRC" '
            FILENAME == al {
              if ($0 ~ /^[ \t]*$/ || $0 ~ /^[ \t]*#/) next
              entry = $0
              sub(/^[ \t]+/, "", entry)
              sub(/[ \t]+$/, "", entry)
              if (entry != "") allow[entry] = 1
              next
            }
            NF && $NF ~ /^\// && $NF !~ /[][*?]/ && !($NF in allow) { print $NF }' "$SSI_ALLOW_SRC" -)
          SSI_EXC=$(printf '%s\n' "$SSI_RAW" | awk -v al="$SSI_ALLOW_SRC" '
            FILENAME == al {
              if ($0 ~ /^[ \t]*$/ || $0 ~ /^[ \t]*#/) next
              entry = $0
              sub(/^[ \t]+/, "", entry)
              sub(/[ \t]+$/, "", entry)
              if (entry != "") allow[entry] = 1
              next
            }
            NF && $NF ~ /^\// && ($NF in allow) { n++ }
            END { print n+0 }' "$SSI_ALLOW_SRC" -)
          SSI_UNSAFE=$(printf '%s\n' "$SSI_RAW" | awk 'NF && $NF ~ /^\// && $NF ~ /[][*?]/ { n++ } END { print n+0 }')
          [ -n "$SSI_EXC" ] || SSI_EXC=0
          [ -n "$SSI_UNSAFE" ] || SSI_UNSAFE=0
          SSI_UNKNOWN=$SSI_UNSAFE
          for SSI_P in $SSI_PATHS; do
            # Probe keys become fixture FILENAMES and fixture directories are
            # case-insensitive on macOS, so the whole key is lowercased: two
            # keys differing only in case would silently destroy each other.
            SSI_KEY=$(printf '%s\n' "$SSI_P" | awk '{ k = $0; gsub(/[^A-Za-z0-9]/, "_", k); k = tolower(k); sub(/^_+/, "", k); print "lslpp_w_" k }')
            # aixv, not aix: lslpp reports "not installed" on stderr, and that
            # diagnostic is exactly what separates a determinate "no fileset
            # owns this" from a probe that never answered.
            SSI_LW=$(aixv "$SSI_KEY" lslpp -w "$SSI_P"); SSI_LW_RC=$?
            if [ "$SSI_LW_RC" -eq 0 ] || [ "$SSI_LW_RC" -eq 1 ]; then
              SSI_CLASS=$(printf '%s\n' "$SSI_LW" | awk -v p="$SSI_P" '
                $1 == p && NF >= 2 && $2 ~ /^[A-Za-z][A-Za-z0-9_.+-]*$/ { owned = 1 }
                $1 == "File" && $2 == "Fileset" { answered = 1 }
                /^[ \t]*-----/ { answered = 1 }
                /^[ \t]*lslpp:/ { answered = 1 }
                END {
                  if (owned) print "owned"
                  else if (answered) print "unowned"
                  else print "unknown"
                }')
            else
              SSI_CLASS=unknown
            fi
            case "$SSI_CLASS" in
              owned) : ;;
              unowned) SSI_UNOWNED=$((SSI_UNOWNED + 1)) ;;
              *) SSI_UNKNOWN=$((SSI_UNKNOWN + 1)) ;;
            esac
          done
          if [ "$SSI_EXC" -gt 0 ]; then
            SSI_NOTE="$SSI_NOTE; +$SSI_EXC site exception(s)"
          fi
          if [ "$SSI_UNKNOWN" -gt 0 ]; then
            SSI_NOTE="$SSI_NOTE; $SSI_UNKNOWN unresolved"
          fi
          if [ "$SSI_UNOWNED" -gt 0 ]; then
            SSI_STATUS=FAIL
            SSI_OBSERVED="$SSI_UNOWNED of $SSI_TOTAL setuid/sgid file(s) are not owned by any installed fileset$SSI_NOTE"
          elif [ "$SSI_UNKNOWN" -gt 0 ]; then
            SSI_STATUS=NOT_ASSESSED
            SSI_OBSERVED="not assessed - fileset ownership unresolved for $SSI_UNKNOWN of $SSI_TOTAL setuid/sgid file(s)"
          else
            SSI_STATUS=PASS
            SSI_OBSERVED="all $SSI_TOTAL setuid/sgid file(s) are owned by an installed fileset, no site baseline$SSI_NOTE"
          fi
        fi
      fi
    fi
  fi

  case "$SSI_STATUS" in
    PASS)
      SSI_MEANING="Every setuid/setgid file found on this system is authorized, either by the site baseline or by ownership in an installed fileset."
      SSI_FIX="n/a"
      SSI_SEV=high
      ;;
    FAIL)
      SSI_MEANING="At least one setuid/setgid file exists on disk that no approved baseline entry, site exception, or installed fileset accounts for; it may be unauthorized."
      SSI_FIX="review each unaccounted file, approve or remove it, then record approvals in the baseline or the .allow exception file; PTxray only recommends this action."
      SSI_SEV=high
      ;;
    NOT_APPLICABLE)
      SSI_MEANING="A recorded decision states that no setuid/setgid inventory baseline is maintained, so the control is not applied."
      SSI_FIX="n/a"
      SSI_SEV=med
      ;;
    *)
      SSI_MEANING="PTxray could not resolve every setuid/setgid file to an authorization: either the inventory probe failed or fileset ownership could not be read for at least one path."
      SSI_FIX="rerun as root, confirm lslpp can query the software vital product database, or provision a readable baseline at /etc/security/aixray-suid-sgid-baseline, then rerun PTxray."
      SSI_SEV=med
      ;;
  esac

  add security suid_sgid "setuid/sgid inventory baseline" \
    "$SSI_STATUS" "$SSI_SEV" "$SSI_OBSERVED" "$SSI_MEANING" "$SSI_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # account_inventory_delta — the change in administrator and user accounts
  # since the previous scan that wrote into the same report output directory.
  #
  # This finding carries NO control tag, deliberately. CIS IBM AIX 7 v1.2.0
  # 5.1.4 and 5.1.5 are organizational: "established and maintained" is a fact
  # about a process, and no host scan can establish it. Those two controls are
  # accounted for as manual-review interview questions in the compliance
  # report. This check does not cover them and must never be presented as if
  # it did — it is new operator value that helps maintain an inventory that
  # someone else owns.
  #
  # Both probes go through aix(), which discards stderr, rather than aixv().
  # They reuse the two account-database capture keys the monolith already owns
  # (lsuser_priv, passwd_uid0) so no new capture is introduced; their exit
  # status alone settles whether the account database was readable, and there
  # is no diagnostic string this check needs to tell two failures apart. A
  # differently-keyed aixv() capture of the same database would buy nothing.
  #
  # Account classes are the same definition stale_privileged_accounts already
  # uses in the monolith — this check does not invent a third one:
  #   system = the fixed AIX/VIOS service-account name list below
  #   admin  = every UID-0 account, plus every non-system account with
  #            admin=true
  #   user   = every other non-system account
  # admin and user are disjoint by construction, so the two counts add up and
  # an account promoted to administrator reads as one admin addition and one
  # user removal. RBAC role assignments (lsuser -a roles) are NOT in scope:
  # covering them would need a capture key that no fixture or live capture
  # carries, and the admin attribute plus UID 0 is the privileged definition
  # the rest of PTxray already reasons about.
  #
  # The snapshot lives with the report, in the operator's --out directory, and
  # never inside the audited system's configuration; writing to /etc/security
  # would mutate the customer's box and falsify the report's own READ-ONLY
  # banner. This fragment performs no write at all: check source may not
  # redirect output (tools/ci/check-tool-command-allowlist.py enforces that),
  # so it computes the snapshot body into AID_SNAPSHOT_BODY and its
  # destination into AID_SNAPSHOT_FILE, and the report writer persists them.
  # With no output directory — a stdout run — no history can be kept at all,
  # and the finding says so rather than pretending the sets matched.
  typeset AID_SNAP_DIR AID_SNAPSHOT_FILE AID_SNAPSHOT_BODY AID_HOSTKEY
  typeset AID_UID0 AID_UID0_RC AID_LSUSER AID_LSUSER_RC
  typeset AID_PREV AID_PREV_RC AID_CMP AID_TOKEN AID_DETAIL
  typeset AID_STATUS AID_SEV AID_OBS AID_MEAN AID_FIX

  AID_SNAP_DIR=""
  AID_SNAPSHOT_FILE=""
  AID_SNAPSHOT_BODY=""
  AID_HOSTKEY=""
  AID_UID0=""
  AID_UID0_RC=126
  AID_LSUSER=""
  AID_LSUSER_RC=126
  AID_PREV=""
  AID_PREV_RC=126
  AID_CMP=""
  AID_TOKEN=""
  AID_DETAIL=""
  AID_STATUS=""
  AID_SEV=""
  AID_OBS=""
  AID_MEAN=""
  AID_FIX=""

  # Snapshot name is host-scoped the same way the report file name is, so a
  # fleet run collecting several hosts into one --out directory compares each
  # host against its own history instead of against whichever host ran last.
  AID_HOSTKEY=${HOST:-}
  AID_HOSTKEY=${AID_HOSTKEY%%.*}
  AID_HOSTKEY=$(printf '%s\n' "$AID_HOSTKEY" | awk 'NR==1{gsub(/[^A-Za-z0-9_-]/,"_"); print; exit}')
  [ -n "$AID_HOSTKEY" ] || AID_HOSTKEY=unknown
  AID_SNAP_DIR=${AIXRAY_ACCOUNT_SNAPSHOT_DIR:-${OUT_DIR:-}}
  if [ -n "$AID_SNAP_DIR" ]; then
    AID_SNAPSHOT_FILE="$AID_SNAP_DIR/aixray-account-inventory-$AID_HOSTKEY.snapshot"
  fi

  AID_UID0=$(aix passwd_uid0 awk -F: '$3==0 {print $1}' /etc/passwd)
  AID_UID0_RC=$?
  AID_LSUSER=$(aix lsuser_priv lsuser -a admin maxage account_locked time_last_login ALL)
  AID_LSUSER_RC=$?

  if [ "$AID_LSUSER_RC" -ne 0 ]; then
    AID_STATUS=NOT_ASSESSED
    AID_OBS="not assessed — account database unreadable (lsuser rc=$AID_LSUSER_RC)"
  elif [ "$AID_UID0_RC" -ne 0 ]; then
    AID_STATUS=NOT_ASSESSED
    AID_OBS="not assessed — UID-0 account list unreadable (/etc/passwd rc=$AID_UID0_RC)"
  else
    # Current inventory, sorted so the snapshot body and every name list this
    # check prints are byte-stable across runs.
    AID_SNAPSHOT_BODY=$(printf '%s\n@@ACCOUNTS@@\n%s\n' "$AID_UID0" "$AID_LSUSER" | awk '
      BEGIN {
        n = split("daemon bin sys adm uucp guest nobody lpd lp invscout snapp ipsec nuucp pconsole sshd esaadmin slotd ragent smmsp", s, " ")
        for (i = 1; i <= n; i++) sysu[s[i]] = 1
        phase = 0
      }
      $0 == "@@ACCOUNTS@@" { phase = 1; next }
      phase == 0 {
        if ($1 ~ /^[A-Za-z0-9._-]+$/ && !($1 in uid0)) {
          uid0[$1] = 1
          n0++
          u0[n0] = $1
        }
        next
      }
      {
        if (NF < 2) next
        if ($1 !~ /^[A-Za-z0-9._-]+$/) next
        seen[$1] = 1
        adm = "false"
        for (i = 2; i <= NF; i++) if (index($i, "admin=") == 1) adm = substr($i, 7)
        if ($1 in uid0) { print "admin " $1; next }
        if ($1 in sysu) next
        if (adm == "true") print "admin " $1
        else print "user " $1
      }
      END {
        # A UID-0 account the account-attribute listing never mentioned is the
        # most dangerous one this check could miss, so /etc/passwd carries it
        # into the inventory on its own.
        for (i = 1; i <= n0; i++) if (!(u0[i] in seen)) print "admin " u0[i]
      }' | sort)

    if [ -z "$AID_SNAPSHOT_BODY" ]; then
      AID_STATUS=NOT_ASSESSED
      AID_OBS="not assessed — account database read back no usable account record"
    else
      # Previous snapshot. It is the tool's own prior output, read directly
      # rather than through aix(): it is not a target-host command, and under
      # AIXRAY_FIXTURES it must stay the real file the operator carries
      # forward. Any malformed line voids the whole comparison — a snapshot
      # that is partly garbage cannot prove a set matched.
      if [ -n "$AID_SNAPSHOT_FILE" ] && [ -r "$AID_SNAPSHOT_FILE" ]; then
        AID_PREV=$(awk '
          /^[ \t]*$/ { next }
          /^[ \t]*#/ { next }
          {
            if (NF != 2) { bad = 1; exit }
            if ($1 != "admin" && $1 != "user") { bad = 1; exit }
            if ($2 !~ /^[A-Za-z0-9._-]+$/) { bad = 1; exit }
            print $1 " " $2
            rows++
          }
          END { if (bad || !rows) exit 1 }
        ' "$AID_SNAPSHOT_FILE" 2>/dev/null)
        AID_PREV_RC=$?
        if [ "$AID_PREV_RC" -eq 0 ]; then
          AID_PREV=$(printf '%s\n' "$AID_PREV" | sort)
        else
          AID_PREV=""
        fi
      fi

      # Both streams arrive sorted, and every list is built by walking them in
      # order, so the names printed below are deterministic rather than
      # whatever order awk happens to hash them into.
      AID_CMP=$(printf '%s\n@@NOW@@\n%s\n' "$AID_PREV" "$AID_SNAPSHOT_BODY" | awk '
        function cap(t) {
          if (substr(t, 118, 1) != "") t = substr(t, 1, 117) "..."
          return t
        }
        function names(list, extra) {
          return (extra > 0) ? list " (+" extra " more)" : list
        }
        BEGIN { phase = 0 }
        $0 == "@@NOW@@" { phase = 1; next }
        /^[ \t]*$/ { next }
        phase == 0 { k = $1 " " $2; prev[k] = 1; np++; pline[np] = k; next }
        {
          k = $1 " " $2
          now[k] = 1
          nn++
          nline[nn] = k
          if ($1 == "admin") na++; else nu++
        }
        END {
          for (i = 1; i <= nn; i++) {
            k = nline[i]
            if (k in prev) continue
            split(k, f, " ")
            if (f[1] == "admin") {
              aa++
              if (aa <= 3) aal = aal (aal == "" ? "" : ", ") f[2]
            } else {
              ua++
              if (ua <= 3) ual = ual (ual == "" ? "" : ", ") f[2]
            }
          }
          for (i = 1; i <= np; i++) {
            k = pline[i]
            if (k in now) continue
            split(k, f, " ")
            if (f[1] == "admin") {
              ar++
              if (ar <= 3) arl = arl (arl == "" ? "" : ", ") f[2]
            } else {
              ur++
              if (ur <= 3) url = url (url == "" ? "" : ", ") f[2]
            }
          }
          counts = (na + 0) " admin, " (nu + 0) " user account(s)"
          if (np == 0) { printf "FIRST\t%s\n", counts; exit }
          if (aa + ar + ua + ur == 0) {
            printf "NOCHANGE\t%s\n", cap(counts "; unchanged since the previous scan")
            exit
          }
          detail = ""
          if (aa > 0) detail = "admin added: " names(aal, aa - 3)
          if (ar > 0) detail = detail (detail == "" ? "" : "; ") "admin removed: " names(arl, ar - 3)
          if (ua > 0) detail = detail (detail == "" ? "" : "; ") "user added: " names(ual, ua - 3)
          if (ur > 0) detail = detail (detail == "" ? "" : "; ") "user removed: " names(url, ur - 3)
          printf "%s\t%s\n", (aa > 0 ? "ADMIN_ADDED" : "CHANGED"), cap(detail "; now " counts)
        }')
      AID_TOKEN=$(printf '%s\n' "$AID_CMP" | awk -F '\t' 'NR==1{print $1}')
      AID_DETAIL=$(printf '%s\n' "$AID_CMP" | awk -F '\t' 'NR==1{print $2}')

      case "$AID_TOKEN" in
        NOCHANGE)
          AID_STATUS=PASS
          AID_OBS=$AID_DETAIL
          ;;
        ADMIN_ADDED)
          AID_STATUS=FAIL
          AID_OBS=$AID_DETAIL
          ;;
        CHANGED)
          AID_STATUS=WARN
          AID_OBS=$AID_DETAIL
          ;;
        FIRST)
          AID_STATUS=NOT_APPLICABLE
          if [ -z "$AID_SNAPSHOT_FILE" ]; then
            AID_OBS="no --out directory, so no scan history is kept; observed now: $AID_DETAIL"
          elif [ -f "$AID_SNAPSHOT_FILE" ]; then
            AID_OBS="prior snapshot unusable; reference re-established: $AID_DETAIL"
          else
            AID_OBS="first scan into this output directory; reference established: $AID_DETAIL"
          fi
          ;;
        *)
          AID_STATUS=NOT_ASSESSED
          AID_OBS="not assessed — account inventory comparison produced no verdict"
          ;;
      esac
    fi
  fi

  case "$AID_STATUS" in
    PASS)
      AID_SEV=low
      AID_MEAN="The set of administrator and user accounts is identical to the one recorded in this output directory by the previous scan."
      AID_FIX="n/a"
      ;;
    FAIL)
      AID_SEV=high
      AID_MEAN="At least one account has gained administrator standing since the previous scan. A new administrator is new standing privilege on this host, and it is the one account change that is an access grant rather than a bookkeeping event."
      AID_FIX="attribute each added administrator to an approved request, remove any that has none, and record the survivors in the account inventory; PTxray recommends this, it never changes an account."
      ;;
    WARN)
      AID_SEV=med
      AID_MEAN="The set of accounts has changed since the previous scan without any account gaining administrator standing. Nothing here grants new privilege, but the inventory is now out of date until each change is attributed."
      AID_FIX="attribute each added or removed account to an approved joiner, mover or leaver record and bring the account inventory back into line; PTxray recommends this, it never changes an account."
      ;;
    NOT_APPLICABLE)
      AID_SEV=low
      AID_MEAN="There is no prior account snapshot in this output directory to compare against, so there is no delta to report. This is the determinate first-scan state, not a failed check: the counts above are the reference this run establishes."
      AID_FIX="reuse the same --out directory for the next scan so the delta can be computed, and confirm the counts above match the account inventory of record."
      ;;
    *)
      AID_SEV=med
      AID_MEAN="PTxray did not obtain a trustworthy read of the account database, so it cannot say which accounts exist, let alone which of them changed."
      AID_FIX="rerun PTxray as an identity that can read the account database (root), then rerun to establish the comparison."
      ;;
  esac

  add security account_inventory_delta "Account inventory delta" \
    "$AID_STATUS" "$AID_SEV" "$AID_OBS" "$AID_MEAN" "$AID_FIX" ""
  if [ "$AID_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="awk -F: '\$3==0 {print \$1}' /etc/passwd|lsuser -a admin maxage account_locked time_last_login ALL"
  fi
_AIXRAY_SESSION_KEYS=""
# account_home_exists — CIS L1 control 4.1.2.1.
# Every local (files-administered) account with UID >= 200 and account_locked != true
# must have a home directory present on the filesystem. Vacuous when none qualify.
typeset AHE_RAW AHE_RC AHE_CANDIDATES AHE_PARSE_RC
typeset AHE_ACCT AHE_HOME AHE_HOME_RAW AHE_HOME_RC
typeset AHE_COUNT AHE_NAMES AHE_MISSING AHE_REC AHE_REST
typeset AHE_REFUSE

AHE_RAW=$(aix account_home_lsuser lsuser -R files -a id home account_locked ALL)
AHE_RC=$?
AHE_REFUSE=0

if [ "$AHE_RC" -ne 0 ]; then
  add security account_home_exists "account home directories exist" NOT_ASSESSED med \
      "lsuser capture failed (rc=$AHE_RC)" \
      "PTxray could not enumerate local account home attributes, so it cannot assess whether every qualifying account has an existing home directory." \
      "correct the lsuser capture failure and rerun PTxray." \
      "cis-l1"
else
  AHE_CANDIDATES=$(printf '%s\n' "$AHE_RAW" | awk '
    NF {
      records++
      acct=$1
      if (acct !~ /^[A-Za-z0-9_.][A-Za-z0-9_.-]*$/) { bad=1; next }
      id=""; home=""; locked=""
      has_id=0; has_home=0; has_lock=0
      for (i=2; i<=NF; i++) {
        tok=$i
        if (tok ~ /^id=/) { id=substr(tok,4); has_id=1 }
        else if (tok ~ /^home=/) { home=substr(tok,6); has_home=1 }
        else if (tok ~ /^account_locked=/) { locked=substr(tok,16); has_lock=1 }
        else bad=1
      }
      if (!has_id || !has_home || !has_lock) { bad=1; next }
      if (id !~ /^[0-9][0-9]*$/) { bad=1; next }
      if ((id + 0) >= 200 && locked != "true")
        print acct "|" home
    }
    END {
      if (records == 0 || bad) exit 1
    }
  ')
  AHE_PARSE_RC=$?
  if [ "$AHE_PARSE_RC" -ne 0 ]; then
    add security account_home_exists "account home directories exist" NOT_ASSESSED med \
        "capture unparseable" \
        "PTxray obtained lsuser output that did not match the expected one-line-per-account format, so it cannot determine which home directories are present." \
        "inspect the lsuser capture and rerun PTxray once the output is well-formed." \
        "cis-l1"
  elif [ -z "$AHE_CANDIDATES" ]; then
    add security account_home_exists "account home directories exist" PASS med \
        "accounts_checked=0" \
        "No local accounts with UID 200 or above and account_locked=false exist, so the home-directory requirement holds vacuously." \
        "n/a" \
        "cis-l1"
  else
    AHE_COUNT=0
    AHE_NAMES=""
    AHE_MISSING=""
    for AHE_REC in $AHE_CANDIDATES; do
      AHE_ACCT=${AHE_REC%%\|*}
      AHE_HOME=${AHE_REC#*\|}
      AHE_COUNT=$(( AHE_COUNT + 1 ))
      if [ -z "$AHE_NAMES" ]; then
        AHE_NAMES="$AHE_ACCT"
      else
        AHE_NAMES="$AHE_NAMES $AHE_ACCT"
      fi

      AHE_HOME_RAW=$(aix "account_home_ls_$AHE_ACCT" ls -ldn "$AHE_HOME")
      AHE_HOME_RC=$?

      if [ "$AHE_HOME_RC" -eq 0 ]; then
        :
      elif [ "$AHE_HOME_RC" -eq 2 ] && [ -z "$AHE_HOME_RAW" ]; then
        if [ -z "$AHE_MISSING" ]; then
          AHE_MISSING="$AHE_ACCT:$AHE_HOME"
        else
          AHE_MISSING="$AHE_MISSING $AHE_ACCT:$AHE_HOME"
        fi
      else
        add security account_home_exists "account home directories exist" NOT_ASSESSED med \
            "home probe failed for $AHE_ACCT (rc=$AHE_HOME_RC)" \
            "PTxray could not read the home directory of account $AHE_ACCT, so it cannot establish whether every qualifying account has an existing home directory." \
            "resolve why the home directory of $AHE_ACCT could not be read, then rerun PTxray." \
            "cis-l1"
        AHE_REFUSE=1
        break
      fi
    done

    if [ "$AHE_REFUSE" -eq 0 ]; then
      if [ -n "$AHE_MISSING" ]; then
        add security account_home_exists "account home directories exist" FAIL med \
            "accounts_checked=$AHE_COUNT missing=$AHE_MISSING" \
            "At least one qualifying local account has a home directory that does not exist on the filesystem." \
            "create the missing home directory or correct the account home attribute, then rerun PTxray." \
            "cis-l1"
      else
        add security account_home_exists "account home directories exist" PASS med \
            "accounts_checked=$AHE_COUNT accounts=$AHE_NAMES" \
            "Every qualifying local account has a home directory present on the filesystem." \
            "n/a" \
            "cis-l1"
      fi
    fi
  fi
fi
_AIXRAY_SESSION_KEYS=""
  # account_home_owner — CIS 4.1.2.2 account home ownership boundary.
  typeset AHO_RAW AHO_RC AHO_CANDIDATES AHO_PARSE_RC AHO_REASON AHO_REC
  typeset AHO_ACCT AHO_ID AHO_HOME AHO_HOME_RAW AHO_HOME_RC AHO_OWNER AHO_OWNER_RC
  typeset AHO_FAIL_COUNT AHO_ERR_COUNT AHO_CHECK_COUNT

  AHO_RAW=$(aix account_home_lsuser lsuser -R files -a id home account_locked ALL)
  AHO_RC=$?
  AHO_REASON=""

  if [ "$AHO_RC" -ne 0 ]; then
    AHO_REASON="lsuser capture failed (rc=$AHO_RC)"
  elif [ -z "$AHO_RAW" ]; then
    AHO_REASON="lsuser capture empty"
  else
    AHO_CANDIDATES=$(printf '%s\n' "$AHO_RAW" | awk '
      NF {
        records++
        acct=$1
        if (acct !~ /^[A-Za-z0-9_.][A-Za-z0-9_.-]*$/) { bad=1; next }
        id=""; home=""; locked=""
        has_id=0; has_home=0; has_lock=0
        for (i=2; i<=NF; i++) {
          tok=$i
          if (tok ~ /^id=/) { id=substr(tok,4); has_id=1 }
          else if (tok ~ /^home=/) { home=substr(tok,6); has_home=1 }
          else if (tok ~ /^account_locked=/) { locked=substr(tok,16); has_lock=1 }
          else bad=1
        }
        if (!has_id || !has_home || !has_lock) { bad=1; next }
        if (id !~ /^[0-9][0-9]*$/) { bad=1; next }
        if (home ~ /"/) { bad=1; next }
        while (length("" id) > 1 && substr(id,1,1) == "0") id=substr(id,2)
        if ((id + 0) >= 200 && home != "/dev/null" && locked != "true") {
          print acct "|" (id + 0) "|" home
        }
      }
      END {
        if (records == 0 || bad) exit 1
      }
    ')
    AHO_PARSE_RC=$?
    if [ "$AHO_PARSE_RC" -ne 0 ]; then
      AHO_REASON="lsuser capture unparseable"
    fi
  fi

  if [ -n "$AHO_REASON" ]; then
    add security account_home_owner "account home owner" NOT_ASSESSED high \
        "not assessed — $AHO_REASON" \
        "PTxray did not obtain a trustworthy account inventory, so it cannot claim every non-system account's home boundary is satisfied." \
        "run 'lsuser -R files -a id home account_locked ALL', correct the capture problem, and rerun PTxray." \
        "cis-l1"
  elif [ -z "$AHO_CANDIDATES" ]; then
    add security account_home_owner "account home owner" PASS med \
        "n=0 candidate accounts" \
        "Every account is locked, is a system account (uid below 200), or has home set to /dev/null, so there is no home boundary left to check." \
        "n/a" "cis-l1"
  else
    AHO_FAIL_COUNT=0
    AHO_ERR_COUNT=0
    AHO_CHECK_COUNT=0
    for AHO_REC in $AHO_CANDIDATES; do
      AHO_ACCT=${AHO_REC%%\|*}
      AHO_REST=${AHO_REC#*\|}
      AHO_ID=${AHO_REST%%\|*}
      AHO_HOME=${AHO_REST#*\|}
      AHO_CHECK_COUNT=$(( AHO_CHECK_COUNT + 1 ))
      AHO_HOME_RAW=$(aix "account_home_ls_$AHO_ACCT" ls -ldn "$AHO_HOME")
      AHO_HOME_RC=$?
      if [ "$AHO_HOME_RC" -eq 2 ]; then
        add security account_home_owner "account home owner" FAIL high \
            "account=$AHO_ACCT home=$AHO_HOME missing" \
            "The home directory of account $AHO_ACCT does not exist on the filesystem, so that account has no home boundary." \
            "create the missing home directory and set correct ownership after validation; PTxray recommends these commands and never executes them." \
            "cis-l1"
        AHO_FAIL_COUNT=$(( AHO_FAIL_COUNT + 1 ))
      elif [ "$AHO_HOME_RC" -eq 0 ]; then
        AHO_OWNER=$(printf '%s\n' "$AHO_HOME_RAW" | awk '
          NF {
            records++
            if (NF < 9 || $3 !~ /^[0-9][0-9]*$/) bad=1
            uid=$3
            while (length("" uid) > 1 && substr(uid,1,1) == "0") uid=substr(uid,2)
          }
          END {
            if (records != 1 || bad) exit 1
            print (uid + 0)
          }
        ')
        AHO_OWNER_RC=$?
        if [ "$AHO_OWNER_RC" -ne 0 ] || [ -z "$AHO_OWNER" ]; then
          add security account_home_owner "account home owner" NOT_ASSESSED high \
              "not assessed — home metadata unparseable for account=$AHO_ACCT home=$AHO_HOME" \
              "PTxray could not read a trustworthy owner for the home directory of account $AHO_ACCT, so it cannot assess that account's home boundary." \
              "run 'ls -ldn <home>' for the named account, correct the metadata problem, and rerun PTxray." \
              "cis-l1"
          AHO_ERR_COUNT=$(( AHO_ERR_COUNT + 1 ))
        elif [ "$AHO_OWNER" = "$AHO_ID" ] || [ "$AHO_OWNER" = "0" ]; then
          :
        else
          add security account_home_owner "account home owner" FAIL high \
              "account=$AHO_ACCT home=$AHO_HOME owner_uid=$AHO_OWNER" \
              "The home directory of account $AHO_ACCT is owned by uid $AHO_OWNER, which is neither the account's own uid ($AHO_ID) nor root." \
              "change only the home directory owner after validation: 'chown <uid> <home>'; PTxray recommends this command and never executes it." \
              "cis-l1"
          AHO_FAIL_COUNT=$(( AHO_FAIL_COUNT + 1 ))
        fi
      else
        add security account_home_owner "account home owner" NOT_ASSESSED high \
            "not assessed — home probe failed for account=$AHO_ACCT home=$AHO_HOME (rc=$AHO_HOME_RC)" \
            "PTxray could not read the home directory of account $AHO_ACCT, so it cannot assess that account's home boundary." \
            "run 'ls -ldn <home>' for the named account, correct the probe problem, and rerun PTxray." \
            "cis-l1"
        AHO_ERR_COUNT=$(( AHO_ERR_COUNT + 1 ))
      fi
    done
    if [ "$AHO_FAIL_COUNT" -eq 0 ] && [ "$AHO_ERR_COUNT" -eq 0 ]; then
      add security account_home_owner "account home owner" PASS med \
          "n=$AHO_CHECK_COUNT accounts compliant" \
          "Every non-system, unlocked account's home directory exists and is owned by the account or by root." \
          "n/a" "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # account_home_mode — non-system account home existence, mode, and ACL boundary
  # (CIS L1 control 4.1.2.3). In-scope: local users with UID >= 200 whose home is
  # neither / nor /dev/null. Each in-scope home must exist, grant no group or
  # world write, and carry no extended ACL. Metadata that cannot be obtained is
  # not evidence of compliance, so it refuses rather than passing.
  typeset AHM_LSUSER AHM_LSUSER_RC AHM_SCOPE AHM_LINE AHM_NAME AHM_HOME
  typeset AHM_LS AHM_LS_RC AHM_KEY AHM_MODE AHM_MODELEN AHM_ACL AHM_ANYFAIL AHM_UNASSESSED

  AHM_LSUSER=$(aix lsuser_id_home lsuser -R files -a id home ALL)
  AHM_LSUSER_RC=$?

  # lsuser_id_home is this module's OWN probe key. The shared monolith capture
  # key lsuser_all carries a different command (lsuser -a account_locked maxage
  # ALL) whose output has no id=/home= fields; reusing it made AHM_SCOPE always
  # empty and produced a false NOT_APPLICABLE with fabricated provenance (round-3
  # D1). A missing lsuser_id_home capture must refuse, never report NOT_APPLICABLE.
  if aix_capture_missing lsuser_id_home; then
    add security account_home "Account home existence and permissions" NOT_ASSESSED med \
        "not assessed — lsuser_id_home probe was not captured for this system" \
        "The lsuser -R files -a id home ALL capture is absent from this scan's fixture set, so PTxray cannot enumerate the home directories that must be constrained." \
        "capture 'lsuser -R files -a id home ALL' from a representative AIX host, then rerun PTxray." "cis-l1"
  elif [ "$AHM_LSUSER_RC" -ne 0 ]; then
    add security account_home "Account home existence and permissions" NOT_ASSESSED med \
        "not assessed — local user enumeration failed (rc=$AHM_LSUSER_RC)" \
        "PTxray could not read the local user table, so it cannot enumerate the home directories that must be constrained." \
        "restore read access to the local user database, then rerun PTxray." "cis-l1"
  else
    AHM_SCOPE=$(printf '%s\n' "$AHM_LSUSER" | awk '
      NF {
        name=$1
        id=""
        home=""
        for (i=2; i<=NF; i++) {
          if (id == "" && $i ~ /^id=[0-9][0-9]*$/) id=substr($i, 4)
          if (home == "" && $i ~ /^home=/) home=substr($i, 6)
        }
        if (id == "" || home == "") next
        if (id + 0 < 200) next
        if (home == "/" || home == "/dev/null") next
        print name "|" home
      }
    ')
    if [ -z "$AHM_SCOPE" ]; then
      add security account_home "Account home existence and permissions" NOT_APPLICABLE low \
          "no in-scope non-system account" \
          "Every local user either has a UID below 200 or is homed at / or /dev/null, so no home directory is constrained by this control." \
          "n/a" "cis-l1"
      F_EVIDENCE_COMMANDS[$((NFIND-1))]="lsuser -R files -a id home ALL"
    else
      AHM_ANYFAIL=0
      AHM_UNASSESSED=0
      while read AHM_LINE; do
        [ -z "$AHM_LINE" ] && continue
        AHM_NAME=${AHM_LINE%%\|*}
        AHM_HOME=${AHM_LINE#*\|}
        AHM_KEY=$(printf '%s' "$AHM_HOME" | tr '/' '_')
        AHM_LS=$(aix "ls_ld_home$AHM_KEY" ls -ld "$AHM_HOME")
        AHM_LS_RC=$?
        if aix_capture_missing "ls_ld_home$AHM_KEY"; then
          AHM_UNASSESSED=1
          continue
        fi
        if [ "$AHM_LS_RC" -eq 2 ] && [ -z "$AHM_LS" ]; then
          AHM_ANYFAIL=1
          add security account_home_missing "non-system account home missing" FAIL low \
              "home $AHM_HOME of $AHM_NAME is absent" \
              "The home directory of a non-system account does not exist, so the account has no constrained, usable home." \
              "create the home with the intended owner, mode, and ACL, then rerun PTxray." "cis-l1"
        elif [ "$AHM_LS_RC" -eq 0 ]; then
          AHM_MODE=$(printf '%s\n' "$AHM_LS" | awk 'NF { print $1; exit }')
          AHM_MODELEN=${#AHM_MODE}
          if [ -z "$AHM_MODE" ]; then
            AHM_UNASSESSED=1
          elif [ "$AHM_MODELEN" -ne 10 ] && [ "$AHM_MODELEN" -ne 11 ]; then
            AHM_UNASSESSED=1
          else
            AHM_ACL=0
            case "$AHM_MODE" in
              *+) AHM_ACL=1 ;;
            esac
            if [ "$(printf '%s' "$AHM_MODE" | cut -c6)" = "w" ] ||
               [ "$(printf '%s' "$AHM_MODE" | cut -c9)" = "w" ]; then
              AHM_ANYFAIL=1
              add security account_home_mode "non-system account home permissions" FAIL med \
                  "home $AHM_HOME of $AHM_NAME is group- or world-writable" \
                  "The home directory of a non-system account grants group or other users write access, so another identity can alter the account's files." \
                  "remove group and world write permission from the home, then rerun PTxray." "cis-l1"
            elif [ "$AHM_ACL" -eq 1 ]; then
              AHM_ANYFAIL=1
              add security account_home_acl "non-system account home ACL" FAIL med \
                  "home $AHM_HOME of $AHM_NAME carries an access control list" \
                  "The home directory of a non-system account carries an extended ACL, so the mode string alone does not bound who can access the account's files." \
                  "clear the extended ACL from the home, then rerun PTxray." "cis-l1"
            fi
          fi
        else
          AHM_UNASSESSED=1
        fi
      done <<AHM_SCOPE_EOF
$(printf '%s\n' "$AHM_SCOPE")
AHM_SCOPE_EOF
      if [ "$AHM_ANYFAIL" -ne 1 ]; then
        if [ "$AHM_UNASSESSED" -eq 1 ]; then
          add security account_home "Account home existence and permissions" NOT_ASSESSED med \
              "not assessed — at least one in-scope home could not be probed" \
              "PTxray could not obtain trustworthy metadata for every in-scope home, so it cannot claim the constrained-home boundary is satisfied." \
              "confirm the missing or unreadable home directories exist, then rerun PTxray." "cis-l1"
        else
          add security account_home "Account home existence and permissions" PASS low \
              "every in-scope non-system account home exists and grants no group or world write and carries no ACL" \
              "All in-scope non-system account home directories were found present, without group or world write permission, and without an extended ACL." \
              "n/a" "cis-l1"
        fi
      fi
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # login_path_empty_entry — every directory named in PATH must be a
  # non-empty, absolute, existing directory that is not group- or
  # world-writable and is owned by root or bin. Diagnostic only: reads PATH
  # and one ls -ld row per inspected entry; never writes target state.
  typeset LPE_PATH_RAW LPE_PATH_RC LPE_REST LPE_ENTRY LPE_POS
  typeset LPE_LS_RAW LPE_LS_RC LPE_OUT LPE_OWNER
  typeset LPE_OLD_REST LPE_NEW_REST
  LPE_FAIL_MSG=""
  LPE_NA_MSG=""

  if [ "${MYUID:-0}" != "0" ]; then
    add security login_path_empty_entry "PATH entry boundaries" NOT_ASSESSED low \
        "not assessed — root required to inspect all PATH directories." \
        "PTxray cannot verify every PATH directory without authority to read each one's metadata." \
        "rerun PTxray with root authority so every PATH directory can be inspected." \
        "cis-l1"
  else
    LPE_PATH_RAW=$(aix path_value echo "${PATH}")
    LPE_PATH_RC=$?
    if [ "$LPE_PATH_RC" -ne 0 ]; then
      add security login_path_empty_entry "PATH entry boundaries" NOT_ASSESSED low \
          "not assessed — cannot read PATH (rc=$LPE_PATH_RC)" \
          "PTxray could not obtain the PATH value, so no PATH directory could be verified." \
          "confirm the PATH environment variable is readable and rerun PTxray." \
          "cis-l1"
    else
      LPE_POS=1
      LPE_REST=$LPE_PATH_RAW
      while :; do
        LPE_OLD_REST=$LPE_REST
        LPE_ENTRY=${LPE_REST%%:*}
        LPE_NEW_REST=${LPE_REST#*:}
        if [ -z "$LPE_ENTRY" ]; then
          # Rule 1: an empty entry resolves to the current directory.
          LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS is empty (current directory)."
        else
          case "$LPE_ENTRY" in
            /*)
              # Rules 3-7 need the entry's ls -ld metadata.
              LPE_LS_RAW=$(aix "ls_ld_$LPE_POS" ls -ld "$LPE_ENTRY")
              LPE_LS_RC=$?
              case "$LPE_LS_RC" in
                0)
                  if [ -z "$LPE_LS_RAW" ]; then
                    LPE_NA_MSG="${LPE_NA_MSG}${LPE_NA_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" could not be inspected (empty ls output)."
                  else
                    LPE_OUT=$(printf '%s\n' "$LPE_LS_RAW" | awk '
                      NF {
                        rec = 1
                        if (NF < 3) { print "BAD"; exit }
                        mode = $1
                        if (length("" mode) == 11) mode = substr(mode, 1, 10)
                        if (length("" mode) != 10) { print "BAD"; exit }
                        if (mode ~ /^d.......w.$/) { print "WORLD"; exit }
                        if (mode ~ /^d....w....$/) { print "GROUP"; exit }
                        if ($3 != "root" && $3 != "bin") { print "OWNER=" $3; exit }
                        print "OK"
                        exit
                      }
                      END { if (rec != 1) print "BAD" }')
                    case "$LPE_OUT" in
                      WORLD)
                        LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" is world-writable."
                        ;;
                      GROUP)
                        LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" is group-writable."
                        ;;
                      OWNER=*)
                        LPE_OWNER=${LPE_OUT#OWNER=}
                        LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" owned by \"$LPE_OWNER\", not root or bin."
                        ;;
                      BAD)
                        LPE_NA_MSG="${LPE_NA_MSG}${LPE_NA_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" could not be inspected (unparseable ls output)."
                        ;;
                      OK)
                        ;;
                    esac
                  fi
                  ;;
                2)
                  if [ -z "$LPE_LS_RAW" ]; then
                    # Rule 4: the entry does not exist.
                    LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" does not exist."
                  else
                    LPE_NA_MSG="${LPE_NA_MSG}${LPE_NA_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" could not be inspected (rc=2 with output)."
                  fi
                  ;;
                *)
                  # Rule 3: an unexpected probe result leaves the state unknown.
                  LPE_NA_MSG="${LPE_NA_MSG}${LPE_NA_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" could not be inspected (rc=$LPE_LS_RC)."
                  ;;
              esac
              ;;
            *)
              # Rule 2: a relative PATH entry.
              LPE_FAIL_MSG="${LPE_FAIL_MSG}${LPE_FAIL_MSG:+; }PATH entry $LPE_POS \"$LPE_ENTRY\" is not an absolute path."
              ;;
          esac
        fi
        LPE_REST=$LPE_NEW_REST
        [ "$LPE_REST" = "$LPE_OLD_REST" ] && break
        LPE_POS=$((LPE_POS + 1))
      done
      if [ -n "$LPE_FAIL_MSG" ]; then
        add security login_path_empty_entry "PATH entry boundaries" FAIL med \
            "$LPE_FAIL_MSG" \
            "A PATH entry can place an unintended directory ahead of the system search order, or an empty entry can resolve commands against the current directory." \
            "correct the PATH definition so every entry is a non-empty, absolute, existing directory that is not group- or world-writable and is owned by root or bin." \
            "cis-l1"
      elif [ -n "$LPE_NA_MSG" ]; then
        add security login_path_empty_entry "PATH entry boundaries" NOT_ASSESSED low \
            "$LPE_NA_MSG" \
            "PTxray did not obtain a trustworthy read of every PATH directory, so it cannot confirm the PATH boundary holds." \
            "run 'ls -ld' on the named PATH entries with root authority and rerun PTxray." \
            "cis-l1"
      else
        add security login_path_empty_entry "PATH entry boundaries" PASS low \
            "all PATH entries are non-empty, absolute, existing, not group- or world-writable, and owned by root or bin." \
            "Every directory on PATH is bounded against command hijacking from the current directory or an unintended owner." \
            "n/a" \
            "cis-l1"
      fi
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # nis_client_absent — NIS client fileset absence probed with a direct
  # 'lslpp -L bos.net.nis.client' query. lslpp rc is determinate for this
  # fileset: 1 = not installed (header and state-code legend only), 0 =
  # installed (a data row is present). Discriminate on rc alone; stdout is
  # not a signal because lslpp always emits its column headers and legend
  # even when the fileset is absent.
  typeset NIS_CLIENT_RAW NIS_CLIENT_RC NIS_CLIENT_STATUS NIS_CLIENT_SEVERITY
  typeset NIS_CLIENT_OBSERVED NIS_CLIENT_MEANING NIS_CLIENT_FIX
  NIS_CLIENT_RC=126

  NIS_CLIENT_RAW=$(aix lslpp_nis_client lslpp -L bos.net.nis.client)
  NIS_CLIENT_RC=$?

  case "$NIS_CLIENT_RC" in
    1)
      NIS_CLIENT_STATUS=PASS
      NIS_CLIENT_OBSERVED="bos.net.nis.client is not installed (lslpp rc=1)"
      ;;
    0)
      NIS_CLIENT_STATUS=FAIL
      NIS_CLIENT_OBSERVED="bos.net.nis.client is installed (lslpp rc=0)"
      ;;
    *)
      NIS_CLIENT_STATUS=NOT_ASSESSED
      NIS_CLIENT_OBSERVED="not assessed - lslpp query for bos.net.nis.client failed (rc=$NIS_CLIENT_RC)"
      ;;
  esac

  case "$NIS_CLIENT_STATUS" in
    PASS)
      NIS_CLIENT_SEVERITY=low
      NIS_CLIENT_MEANING="The NIS client fileset is absent from the installed-software database; the host cannot provide NIS client services."
      NIS_CLIENT_FIX="n/a"
      ;;
    FAIL)
      NIS_CLIENT_SEVERITY=high
      NIS_CLIENT_MEANING="The NIS client fileset is present in the installed-software database; the host can provide NIS client services."
      NIS_CLIENT_FIX="after confirming no workload needs NIS client services, remove the fileset with 'installp -ug bos.net.nis.client'; PTxray only recommends these actions."
      ;;
    *)
      NIS_CLIENT_SEVERITY=low
      NIS_CLIENT_MEANING="PTxray did not obtain a determinate lslpp result for bos.net.nis.client."
      NIS_CLIENT_FIX="run 'lslpp -L bos.net.nis.client' and rerun PTxray once the query returns a determinate rc."
      ;;
  esac

  add security nis_client_installed "NIS client package presence" \
    "$NIS_CLIENT_STATUS" "$NIS_CLIENT_SEVERITY" "$NIS_CLIENT_OBSERVED" \
    "$NIS_CLIENT_MEANING" "$NIS_CLIENT_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # nis_server_absent — NIS server fileset presence from a single lslpp -L query.
  # The discriminator is whether a data row for bos.net.nis.server appears in the
  # output. lslpp -L on an absent fileset returns rc=1 with the column headers and
  # the state-code legend, so output is never keyed on emptiness.
  typeset NIS_SRV_RAW NIS_SRV_RC NIS_SRV_FOUND NIS_SRV_FILTER_RC
  typeset NIS_SRV_STATUS NIS_SRV_SEVERITY NIS_SRV_OBSERVED NIS_SRV_MEANING NIS_SRV_FIX
  NIS_SRV_RAW=""
  NIS_SRV_RC=126
  NIS_SRV_STATUS=NOT_ASSESSED
  NIS_SRV_SEVERITY=low

  NIS_SRV_RAW=$(aix lslpp_nis_server lslpp -L bos.net.nis.server)
  NIS_SRV_RC=$?

  if [ "$NIS_SRV_RC" -ne 0 ] && [ "$NIS_SRV_RC" -ne 1 ]; then
    NIS_SRV_STATUS=NOT_ASSESSED
    NIS_SRV_OBSERVED="not assessed - lslpp -L bos.net.nis.server failed (rc=$NIS_SRV_RC)"
    NIS_SRV_MEANING="PTxray did not obtain a trustworthy installed-fileset query result."
    NIS_SRV_FIX="make 'lslpp -L' return a readable result, then rerun PTxray."
  elif [ -z "$NIS_SRV_RAW" ]; then
    NIS_SRV_STATUS=NOT_ASSESSED
    NIS_SRV_OBSERVED="not assessed - lslpp -L bos.net.nis.server returned empty output (rc=$NIS_SRV_RC)"
    NIS_SRV_MEANING="PTxray did not obtain a trustworthy installed-fileset query result."
    NIS_SRV_FIX="make 'lslpp -L' return a readable result, then rerun PTxray."
  else
    NIS_SRV_FOUND=$(printf '%s\n' "$NIS_SRV_RAW" | awk '$1=="bos.net.nis.server"{found=1} END{print (found?1:0)}')
    NIS_SRV_FILTER_RC=$?
    if [ "$NIS_SRV_FILTER_RC" -ne 0 ]; then
      NIS_SRV_STATUS=NOT_ASSESSED
      NIS_SRV_OBSERVED="not assessed - NIS server inventory filter failed (rc=$NIS_SRV_FILTER_RC)"
      NIS_SRV_MEANING="PTxray could not safely filter the installed-fileset query output."
      NIS_SRV_FIX="make 'awk' available and rerun PTxray."
    elif [ "$NIS_SRV_FOUND" -eq 1 ]; then
      NIS_SRV_STATUS=FAIL
      NIS_SRV_SEVERITY=med
      NIS_SRV_OBSERVED="bos.net.nis.server is installed"
      NIS_SRV_MEANING="The NIS server fileset appears in the installed-software inventory; a present NIS server fileset widens the network-authentication attack surface."
      NIS_SRV_FIX="after local-policy approval, remove the unused fileset with 'installp -ug bos.net.nis.server'; PTxray only recommends this action."
    else
      NIS_SRV_STATUS=PASS
      NIS_SRV_OBSERVED="bos.net.nis.server not installed"
      NIS_SRV_MEANING="The NIS server fileset is absent from the installed-software inventory."
      NIS_SRV_FIX="n/a"
    fi
  fi

  add security nis_server_installed "NIS server fileset presence" \
    "$NIS_SRV_STATUS" "$NIS_SRV_SEVERITY" "$NIS_SRV_OBSERVED" \
    "$NIS_SRV_MEANING" "$NIS_SRV_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # nis_plus_entries — detect NIS compatibility '+' entries in the local
  # password and group databases (CIS 4.2.3).  A line beginning with '+' in
  # /etc/passwd or /etc/group enables NIS compatibility mode, so NIS-domain
  # users and groups that are not defined locally can take part in
  # authentication and authorization.  The compliant state is zero such lines
  # in both files.  Capture: grep for a leading '+' across both files; the
  # discriminator keys on the grep exit code only, stdout is never parsed.
  #
  # Verdict logic:
  #   rc=1  (no match in any file, stdout empty)          => PASS
  #   rc=0  (at least one match; stdout is the evidence)  => FAIL
  #   rc>=2 (grep error — a file unreadable or missing)   => NOT_ASSESSED
  #
  typeset NIS_PGP_RC NIS_PGP_RAW NIS_PGP_EVID NIS_PGP_STATUS
  typeset NIS_PGP_OBSERVED NIS_PGP_MEANING NIS_PGP_FIX NIS_PGP_SEV
  NIS_PGP_RC=0
  NIS_PGP_RAW=""
  NIS_PGP_EVID=""

  NIS_PGP_RAW=$(aix passwd_group_plus grep "^+" /etc/passwd /etc/group)
  NIS_PGP_RC=$?

  case "$NIS_PGP_RC" in
    1)
      NIS_PGP_STATUS=PASS
      NIS_PGP_SEV=low
      NIS_PGP_OBSERVED="no + entries in /etc/passwd or /etc/group"
      NIS_PGP_MEANING="Neither database contains a NIS compatibility '+' entry, so NIS-domain users and groups cannot enter local authentication and authorization through these files."
      NIS_PGP_FIX="n/a"
      ;;
    0)
      NIS_PGP_STATUS=FAIL
      NIS_PGP_SEV=high
      if [ -n "$NIS_PGP_RAW" ]; then
        NIS_PGP_EVID=$(printf '%s\n' "$NIS_PGP_RAW" | awk 'NR > 20 { print "(... further matches omitted)"; exit } { print }')
      else
        NIS_PGP_EVID="grep rc=0 but produced no matching lines"
      fi
      NIS_PGP_OBSERVED="$NIS_PGP_EVID"
      NIS_PGP_MEANING="A line beginning with '+' exists in /etc/passwd or /etc/group, enabling NIS compatibility mode so NIS-domain entries — including users and groups not locally defined — can participate in authentication and authorization."
      NIS_PGP_FIX="after service-owner approval, remove or comment every line whose first character is '+' from /etc/passwd and /etc/group, or replace the NIS entries with local definitions; PTxray only recommends these actions."
      ;;
    *)
      NIS_PGP_STATUS=NOT_ASSESSED
      NIS_PGP_SEV=low
      NIS_PGP_OBSERVED="not assessed — grep failed (rc=$NIS_PGP_RC)"
      NIS_PGP_MEANING="PTxray could not read /etc/passwd or /etc/group, so the '+' entry state is unproven."
      NIS_PGP_FIX="verify both files exist and are readable, then rerun PTxray."
      ;;
  esac

  add security nis_plus_entries "NIS + entries in passwd/group databases" \
    "$NIS_PGP_STATUS" "$NIS_PGP_SEV" \
    "$NIS_PGP_OBSERVED" \
    "$NIS_PGP_MEANING" \
    "$NIS_PGP_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # hosts_equiv_entries — assess whether /etc/hosts.equiv carries active trust
  # entries. Absent file is compliant; an existing file must have no active
  # (non-comment, non-blank) entries. Fixed-path probes; every uncertain
  # evidence shape fails closed to NOT_ASSESSED.
  typeset HHE_STAT HHE_STAT_RC HHE_ENTRIES HHE_ENTRIES_RC

  HHE_STAT=$(aix hosts_equiv_stat ls -ld /etc/hosts.equiv)
  HHE_STAT_RC=$?

  if [ "$HHE_STAT_RC" -eq 2 ] && [ -z "$HHE_STAT" ]; then
    # rc=2 with empty stdout: determinate absence of the file.
    add security hosts_equiv_entries "hosts.equiv trust entries" PASS low \
        "hosts.equiv is absent" \
        "No /etc/hosts.equiv file exists, so no host-equivalence trust entries can be active." \
        "n/a" "cis-l2"
  elif [ "$HHE_STAT_RC" -ne 0 ]; then
    # rc not in {0,2}: unexpected stat failure.
    add security hosts_equiv_entries "hosts.equiv trust entries" NOT_ASSESSED low \
        "not assessed — stat probe failed (rc=$HHE_STAT_RC)" \
        "PTxray did not establish whether /etc/hosts.equiv exists, so its content cannot be assessed." \
        "run 'ls -ld /etc/hosts.equiv', resolve the stat failure, and rerun PTxray." "cis-l2"
  elif [ -z "$HHE_STAT" ]; then
    # rc=0 with empty stdout: contradictory probe output.
    add security hosts_equiv_entries "hosts.equiv trust entries" NOT_ASSESSED low \
        "not assessed — stat probe returned empty output" \
        "PTxray obtained a zero exit status with no stat output, which is not a trustworthy existence record." \
        "run 'ls -ld /etc/hosts.equiv', correct the capture or path problem, and rerun PTxray." "cis-l2"
  else
    # rc=0 with non-empty stdout: file confirmed present; read active entries.
    HHE_ENTRIES=$(aix hosts_equiv_entries grep -v "^\s*#" /etc/hosts.equiv); HHE_ENTRIES_RC=$?

    if [ "$HHE_ENTRIES_RC" -eq 1 ] && [ -z "$HHE_ENTRIES" ]; then
      # rc=1 with empty stdout: no uncommented entries selected.
      add security hosts_equiv_entries "hosts.equiv trust entries" PASS low \
          "no active hosts.equiv entries" \
          "/etc/hosts.equiv exists but every line is blank or commented, so no host-equivalence trust is active." \
          "n/a" "cis-l2"
    elif [ "$HHE_ENTRIES_RC" -eq 0 ] && [ -n "$HHE_ENTRIES" ]; then
      # rc=0 with non-empty stdout: active entries present.
      add security hosts_equiv_entries "hosts.equiv trust entries" FAIL high \
          "active entries: $HHE_ENTRIES" \
          "/etc/hosts.equiv contains at least one active host-equivalence entry, granting unauthenticated trust to those hosts." \
          "remove every active (non-comment, non-blank) line from /etc/hosts.equiv; PTxray only recommends this action." "cis-l2"
    elif [ "$HHE_ENTRIES_RC" -eq 2 ]; then
      # rc=2 against a confirmed-present file: read error.
      add security hosts_equiv_entries "hosts.equiv trust entries" NOT_ASSESSED low \
          "not assessed — entries probe failed (rc=$HHE_ENTRIES_RC)" \
          "PTxray could not read /etc/hosts.equiv, so its active entries could not be assessed." \
          "restore read access to /etc/hosts.equiv and rerun PTxray." "cis-l2"
    else
      # rc not in {0,1,2}: unexpected grep outcome.
      add security hosts_equiv_entries "hosts.equiv trust entries" NOT_ASSESSED low \
          "not assessed — entries probe returned rc=$HHE_ENTRIES_RC" \
          "PTxray did not obtain a trustworthy read of /etc/hosts.equiv, so its active entries could not be assessed." \
          "run 'grep -v \"^[[:space:]]*#\" /etc/hosts.equiv', resolve the read problem, and rerun PTxray." "cis-l2"
    fi
