_AIXRAY_SESSION_KEYS=""
  # rhost_dotfiles_absent — assess absence of host-based trust dotfiles
  # (.netrc, .rhosts, .shosts) on every local JFS/JFS2 filesystem. Each probe
  # is a distinct find scoped to -fstype jfs/jfs2. find exits 0 whether it
  # found nothing or something, so a non-zero rc means the scan itself failed
  # and absence cannot be asserted from it.
  typeset RDA_NETRC RDA_NETRC_RC RDA_NETRC_COUNT
  typeset RDA_RHOSTS RDA_RHOSTS_RC RDA_RHOSTS_COUNT
  typeset RDA_SHOSTS RDA_SHOSTS_RC RDA_SHOSTS_COUNT
  typeset RDA_STATUS RDA_SEVERITY RDA_OBSERVED RDA_MEANING RDA_FIX
  typeset RDA_FOUND RDA_ERROR RDA_ERR_REASON RDA_PATTERNS
  typeset RDA_PATSEP RDA_ERRSEP

  if [ "${rhost_dotfiles_netrc_RC+x}" = x ]; then
    RDA_NETRC=$rhost_dotfiles_netrc
    RDA_NETRC_RC=$rhost_dotfiles_netrc_RC
  else
    RDA_NETRC=$(aix rhost_dotfiles_netrc find / \( -fstype jfs -o -fstype jfs2 \) -name ".netrc" -print); RDA_NETRC_RC=$?
  fi
  if [ "${rhost_dotfiles_rhosts_RC+x}" = x ]; then
    RDA_RHOSTS=$rhost_dotfiles_rhosts
    RDA_RHOSTS_RC=$rhost_dotfiles_rhosts_RC
  else
    RDA_RHOSTS=$(aix rhost_dotfiles_rhosts find / \( -fstype jfs -o -fstype jfs2 \) -name ".rhosts" -print); RDA_RHOSTS_RC=$?
  fi
  if [ "${rhost_dotfiles_shosts_RC+x}" = x ]; then
    RDA_SHOSTS=$rhost_dotfiles_shosts
    RDA_SHOSTS_RC=$rhost_dotfiles_shosts_RC
  else
    RDA_SHOSTS=$(aix rhost_dotfiles_shosts find / \( -fstype jfs -o -fstype jfs2 \) -name ".shosts" -print); RDA_SHOSTS_RC=$?
  fi

  RDA_FOUND=0
  RDA_ERROR=0
  RDA_ERR_REASON=''
  RDA_PATTERNS=''
  RDA_PATSEP=''
  RDA_ERRSEP=''

  # Per-pattern discriminator: rc=0 means the scan completed (empty stdout is
  # determinate absence); rc!=0 means it did not (state unknown).
  if [ "$RDA_NETRC_RC" -eq 0 ]; then
    RDA_NETRC_COUNT=$(printf '%s\n' "$RDA_NETRC" | awk 'NF { n++ } END { print n+0 }')
    if [ "$RDA_NETRC_COUNT" -gt 0 ]; then
      RDA_FOUND=1
      RDA_PATTERNS="${RDA_PATTERNS}${RDA_PATSEP}.netrc:$RDA_NETRC_COUNT path(s)"
      RDA_PATSEP=', '
    fi
  else
    RDA_ERROR=1
    RDA_ERR_REASON="${RDA_ERR_REASON}${RDA_ERRSEP}.netrc probe (rc=$RDA_NETRC_RC)"
    RDA_ERRSEP=', '
  fi
  if [ "$RDA_RHOSTS_RC" -eq 0 ]; then
    RDA_RHOSTS_COUNT=$(printf '%s\n' "$RDA_RHOSTS" | awk 'NF { n++ } END { print n+0 }')
    if [ "$RDA_RHOSTS_COUNT" -gt 0 ]; then
      RDA_FOUND=1
      RDA_PATTERNS="${RDA_PATTERNS}${RDA_PATSEP}.rhosts:$RDA_RHOSTS_COUNT path(s)"
      RDA_PATSEP=', '
    fi
  else
    RDA_ERROR=1
    RDA_ERR_REASON="${RDA_ERR_REASON}${RDA_ERRSEP}.rhosts probe (rc=$RDA_RHOSTS_RC)"
    RDA_ERRSEP=', '
  fi
  if [ "$RDA_SHOSTS_RC" -eq 0 ]; then
    RDA_SHOSTS_COUNT=$(printf '%s\n' "$RDA_SHOSTS" | awk 'NF { n++ } END { print n+0 }')
    if [ "$RDA_SHOSTS_COUNT" -gt 0 ]; then
      RDA_FOUND=1
      RDA_PATTERNS="${RDA_PATTERNS}${RDA_PATSEP}.shosts:$RDA_SHOSTS_COUNT path(s)"
      RDA_PATSEP=', '
    fi
  else
    RDA_ERROR=1
    RDA_ERR_REASON="${RDA_ERR_REASON}${RDA_ERRSEP}.shosts probe (rc=$RDA_SHOSTS_RC)"
    RDA_ERRSEP=', '
  fi

  if [ "$RDA_FOUND" -eq 1 ]; then
    RDA_STATUS=FAIL
    RDA_SEVERITY=high
    RDA_OBSERVED="present: $RDA_PATTERNS"
    RDA_MEANING='A scan of every local JFS/JFS2 filesystem found at least one host-based trust dotfile. Such files permit logins without an interactive password exchange.'
    RDA_FIX='remove every matching .netrc, .rhosts, and .shosts file from JFS/JFS2 filesystems; PTxray only recommends these actions.'
  elif [ "$RDA_ERROR" -eq 1 ]; then
    RDA_STATUS=NOT_ASSESSED
    RDA_SEVERITY=med
    RDA_OBSERVED="not assessed — $RDA_ERR_REASON"
    RDA_MEANING='The JFS/JFS2 scan did not complete for at least one trust-dotfile pattern, so absence of the remaining patterns cannot be asserted; the state is unknown.'
    RDA_FIX='resolve the scan failure (permissions or I/O), verify the filesystems are traversable, then rerun PTxray.'
  else
    RDA_STATUS=PASS
    RDA_SEVERITY=med
    RDA_OBSERVED='none present'
    RDA_MEANING='A scan of every local JFS/JFS2 filesystem found no .netrc, .rhosts, or .shosts trust dotfile.'
    RDA_FIX='n/a'
  fi

  add security rhost_dotfiles_absent "Host-based trust dotfiles (.netrc, .rhosts, .shosts)" \
      "$RDA_STATUS" "$RDA_SEVERITY" \
      "$RDA_OBSERVED" "$RDA_MEANING" "$RDA_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # remote_rcmd_filesets — mode boundary on the legacy r-command client and
  # server filesets. The client (bos.net.tcp.rcmd) and server
  # (bos.net.tcp.rcmd_server) filesets must be uninstalled, or every file they
  # own must carry no permission bits: regular files `----------`, directories
  # `d---------`. Symlinks are tolerated with a distinct meaning; vanished paths refuse.
  # Presence is keyed on lslpp -L rc (0 installed, 1 absent), never on stdout
  # emptiness — an absent-fileset query still prints column headers.
  typeset RRFS_SRV_RAW RRFS_SRV_RC RRFS_CLI_RAW RRFS_CLI_RC
  typeset RRFS_SRV_F_RAW RRFS_SRV_F_RC RRFS_SRV_F_LIST
  typeset RRFS_CLI_F_RAW RRFS_CLI_F_RC RRFS_CLI_F_LIST
  typeset RRFS_FILE_LIST RRFS_PATH RRFS_KEY
  typeset RRFS_LS_RAW RRFS_LS_RC RRFS_MODE
  typeset RRFS_STATUS RRFS_REASON RRFS_OBSERVED RRFS_MEANING RRFS_FIX
  typeset RRFS_VIOLATIONS RRFS_INSPECTED RRFS_BAD_PATH RRFS_BAD_MODE
  typeset RRFS_UNASSESSED RRFS_UNASSESSED_PATH RRFS_VANISHED RRFS_VANISHED_PATH RRFS_SYMLINKS RRFS_TOTAL
  typeset RRFS_MEANING_OVERRIDE
  RRFS_STATUS=""
  RRFS_REASON=""
  RRFS_OBSERVED=""
  RRFS_BAD_PATH=""
  RRFS_BAD_MODE=""
  RRFS_FILE_LIST=""
  RRFS_MEANING_OVERRIDE=""

  RRFS_SRV_RAW=$(aix lslpp_L_rcmd_server lslpp -L bos.net.tcp.rcmd_server)
  RRFS_SRV_RC=$?
  RRFS_CLI_RAW=$(aix lslpp_L_rcmd lslpp -L bos.net.tcp.rcmd)
  RRFS_CLI_RC=$?

  case "$RRFS_SRV_RC" in
    0|1) ;;
    *) RRFS_STATUS=NOT_ASSESSED
       RRFS_REASON="lslpp -L bos.net.tcp.rcmd_server exited $RRFS_SRV_RC (expected 0 or 1)"
       ;;
  esac
  if [ -z "$RRFS_STATUS" ]; then
    case "$RRFS_CLI_RC" in
      0|1) ;;
      *) RRFS_STATUS=NOT_ASSESSED
         RRFS_REASON="lslpp -L bos.net.tcp.rcmd exited $RRFS_CLI_RC (expected 0 or 1)"
         ;;
    esac
  fi

  if [ -z "$RRFS_STATUS" ]; then
    if [ "$RRFS_SRV_RC" -eq 1 ] && [ "$RRFS_CLI_RC" -eq 1 ]; then
      RRFS_STATUS=PASS
      RRFS_OBSERVED="neither bos.net.tcp.rcmd nor bos.net.tcp.rcmd_server is installed (lslpp -L rc=1 for both)"
    else
      # At least one fileset is installed; enumerate the files it owns.
      if [ "$RRFS_SRV_RC" -eq 0 ]; then
        RRFS_SRV_F_RAW=$(aix lslpp_f_rcmd_server lslpp -f bos.net.tcp.rcmd_server)
        RRFS_SRV_F_RC=$?
        if [ "$RRFS_SRV_F_RC" -ne 0 ]; then
          RRFS_STATUS=NOT_ASSESSED
          RRFS_REASON="lslpp -f bos.net.tcp.rcmd_server exited $RRFS_SRV_F_RC for a fileset reported installed"
        else
          RRFS_SRV_F_LIST=$(printf '%s\n' "$RRFS_SRV_F_RAW" | awk '$0 ~ /^ +\// { print $1 }')
          if [ -n "$RRFS_SRV_F_LIST" ]; then
            RRFS_FILE_LIST="$RRFS_SRV_F_LIST"
          fi
        fi
      fi
      if [ -z "$RRFS_STATUS" ] && [ "$RRFS_CLI_RC" -eq 0 ]; then
        RRFS_CLI_F_RAW=$(aix lslpp_f_rcmd lslpp -f bos.net.tcp.rcmd)
        RRFS_CLI_F_RC=$?
        if [ "$RRFS_CLI_F_RC" -ne 0 ]; then
          RRFS_STATUS=NOT_ASSESSED
          RRFS_REASON="lslpp -f bos.net.tcp.rcmd exited $RRFS_CLI_F_RC for a fileset reported installed"
        else
          RRFS_CLI_F_LIST=$(printf '%s\n' "$RRFS_CLI_F_RAW" | awk '$0 ~ /^ +\// { print $1 }')
          if [ -n "$RRFS_CLI_F_LIST" ]; then
            if [ -z "$RRFS_FILE_LIST" ]; then
              RRFS_FILE_LIST="$RRFS_CLI_F_LIST"
            else
              RRFS_FILE_LIST="$RRFS_FILE_LIST
$RRFS_CLI_F_LIST"
            fi
          fi
        fi
      fi
    fi
  fi

  if [ -z "$RRFS_STATUS" ] && [ -n "$RRFS_FILE_LIST" ]; then
    RRFS_VIOLATIONS=0
    RRFS_INSPECTED=0
    RRFS_UNASSESSED=0
    RRFS_UNASSESSED_PATH=""
    RRFS_VANISHED=0
    RRFS_VANISHED_PATH=""
    RRFS_SYMLINKS=0
    RRFS_TOTAL=0
    while read RRFS_PATH; do
      [ -n "$RRFS_PATH" ] || continue
      RRFS_TOTAL=$((RRFS_TOTAL+1))
      # A probe key becomes a FIXTURE FILENAME (<set>/<key>.out), so an
      # interpolated absolute path makes the key name a nested directory that
      # does not exist: capture mode cannot write it and replay cannot read
      # it, so aix() returns 127 and this check refuses on a file it has
      # ALREADY proven exists. Flatten the path the same way
      # ck-cron-command-paths does. The 'ls_led_' key namespace is unused
      # elsewhere in this repo, so no sanitized key can collide with an
      # existing one.
      RRFS_KEY=$(printf '%s' "$RRFS_PATH" | tr '/' '_')

      # Classify from the capture alone — never probe the scanning host.
      if aix_capture_missing "ls_led_$RRFS_KEY"; then
        RRFS_UNASSESSED=$((RRFS_UNASSESSED+1))
        if [ -z "$RRFS_UNASSESSED_PATH" ]; then
          RRFS_UNASSESSED_PATH="$RRFS_PATH"
        fi
        continue
      fi

      RRFS_LS_RAW=$(aix "ls_led_$RRFS_KEY" ls -led "$RRFS_PATH")
      RRFS_LS_RC=$?

      if [ "$RRFS_LS_RC" -ne 0 ]; then
        if [ "$RRFS_VANISHED" -eq 0 ]; then
          RRFS_VANISHED_PATH="$RRFS_PATH"
        fi
        RRFS_VANISHED=$((RRFS_VANISHED+1))
        continue
      fi

      RRFS_MODE=$(printf '%s\n' "$RRFS_LS_RAW" | awk '
        NF {
          if (mode == "") mode = $1
        }
        END { print mode }')

      if [ -z "$RRFS_MODE" ]; then
        # Genuinely corrupted capture — no mode field. If violations have
        # already been found, do not suppress them; just skip this path.
        if [ "$RRFS_VIOLATIONS" -eq 0 ]; then
          RRFS_STATUS=NOT_ASSESSED
          RRFS_REASON="ls -led on $RRFS_PATH returned empty output"
          break
        fi
        continue
      fi

      case "$RRFS_MODE" in
        l*)
          RRFS_SYMLINKS=$((RRFS_SYMLINKS+1))
          ;;
        d---------*|----------*)
          RRFS_INSPECTED=$((RRFS_INSPECTED+1))
          ;;
        *)
          if [ "$RRFS_VIOLATIONS" -eq 0 ]; then
            RRFS_BAD_PATH="$RRFS_PATH"
            RRFS_BAD_MODE="$RRFS_MODE"
          fi
          RRFS_VIOLATIONS=$((RRFS_VIOLATIONS+1))
          ;;
      esac
    done <<EOF
$RRFS_FILE_LIST
EOF
    if [ -z "$RRFS_STATUS" ]; then
      # Adverse evidence always stands — a gap must never suppress a
      # violation that was actually observed.
      if [ "$RRFS_VIOLATIONS" -gt 0 ]; then
        RRFS_STATUS=FAIL
        RRFS_OBSERVED="$RRFS_VIOLATIONS r-command file(s) carry a mode outside the 000 boundary (first: $RRFS_BAD_MODE $RRFS_BAD_PATH)"
        if [ "$RRFS_UNASSESSED" -gt 0 ]; then
          RRFS_OBSERVED="$RRFS_OBSERVED; $RRFS_UNASSESSED further path(s) had no captured evidence and were not assessed"
        fi
      elif [ "$RRFS_UNASSESSED" -gt 0 ]; then
        RRFS_STATUS=NOT_ASSESSED
        RRFS_OBSERVED="not assessed — $RRFS_UNASSESSED of $RRFS_TOTAL r-command file(s) have no captured evidence (first: $RRFS_UNASSESSED_PATH)"
      elif [ "$RRFS_INSPECTED" -gt 0 ]; then
        RRFS_STATUS=PASS
        RRFS_OBSERVED="$RRFS_INSPECTED r-command file(s) inspected, all mode 000"
        if [ "$RRFS_VANISHED" -gt 0 ]; then
          RRFS_OBSERVED="$RRFS_OBSERVED; $RRFS_VANISHED vanished path(s) excluded"
        fi
        if [ "$RRFS_SYMLINKS" -gt 0 ]; then
          if [ "$RRFS_VANISHED" -gt 0 ]; then
            RRFS_OBSERVED="$RRFS_OBSERVED, $RRFS_SYMLINKS symlink(s)"
          else
            RRFS_OBSERVED="$RRFS_OBSERVED; $RRFS_SYMLINKS symlink(s) excluded"
          fi
        fi
      elif [ "$RRFS_VANISHED" -gt 0 ]; then
        RRFS_STATUS=NOT_ASSESSED
        RRFS_OBSERVED="not assessed — $RRFS_VANISHED of $RRFS_TOTAL r-command file(s) owned by an installed fileset could not be stat'd (ls -led exited nonzero; first: $RRFS_VANISHED_PATH), so no mode was measured for any of them"
      elif [ "$RRFS_SYMLINKS" -gt 0 ]; then
        RRFS_STATUS=PASS
        RRFS_OBSERVED="$RRFS_SYMLINKS of $RRFS_TOTAL owned path(s) are symbolic links and none is a regular file or directory — no in-scope file to inspect"
        RRFS_MEANING_OVERRIDE="Every path owned by the installed r-command fileset(s) is a symbolic link. This control's mode boundary constrains regular files and directories, and the fileset owns none at these paths; the link targets belong to other filesets and were not inspected."
      else
        RRFS_STATUS=NOT_ASSESSED
        RRFS_OBSERVED="not assessed — no inspectable files, symlinks, or vanished paths accounted for in the r-command filesets"
      fi
    fi
  fi

  if [ -z "$RRFS_STATUS" ]; then
    RRFS_STATUS=NOT_ASSESSED
    RRFS_OBSERVED="not assessed — installed r-command fileset(s) reported no files"
  fi

  if [ "$RRFS_STATUS" = "NOT_ASSESSED" ] && [ -z "$RRFS_OBSERVED" ]; then
    RRFS_OBSERVED="not assessed — $RRFS_REASON"
  fi

  case "$RRFS_STATUS" in
    PASS)
      if [ -n "$RRFS_MEANING_OVERRIDE" ]; then
        RRFS_MEANING="$RRFS_MEANING_OVERRIDE"
      else
        RRFS_MEANING="No legacy r-command client or server file is readable, writable, or executable: the filesets are uninstalled, or every file they own carries no permission bits."
      fi
      RRFS_FIX="n/a"
      ;;
    FAIL)
      RRFS_MEANING="At least one file owned by the legacy r-command filesets exposes a read, write, or execute permission bit, so the r-command attack surface may be reachable."
      RRFS_FIX="after validating each path, remove every permission bit with 'chmod 000 <path>', or uninstall the filesets with 'installp -ug bos.net.tcp.rcmd' and 'installp -ug bos.net.tcp.rcmd_server' once no workload needs them; PTxray recommends these commands and never executes them."
      ;;
    *)
      RRFS_MEANING="PTxray did not obtain trustworthy package-inventory or mode evidence for the legacy r-command filesets."
      RRFS_FIX="run 'lslpp -L bos.net.tcp.rcmd_server' and 'lslpp -L bos.net.tcp.rcmd' as root, resolve the probe or output-shape problem, and rerun PTxray."
      ;;
  esac

  add security remote_rcmd_filesets "r-command client/server filesets mode" \
    "$RRFS_STATUS" low "$RRFS_OBSERVED" \
    "$RRFS_MEANING" "$RRFS_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # snmp_filesets_absent — SNMP client and server fileset absence from the
  # package inventory.  A compliant host has neither bos.net.tcp.snmp
  # (client) nor bos.net.tcp.snmpd (server) installed.  Two independent
  # lslpp -Lcq probes, discriminated on exit code alone:
  #   rc=0 — the fileset is installed (a data row names it in stdout)
  #   rc=1 — determinate absence; stdout may still carry column headers or
  #          a state-code legend that varies by AIX level, so stdout is
  #          never used to decide presence or absence
  #   any other rc — probe failure, fileset state unknown
  #
  # Verdict logic:
  #   rc=0 with empty stdout              => NOT_ASSESSED (rc=0 promises a row)
  #   either probe rc outside {0,1}       => NOT_ASSESSED (that fileset unknown)
  #   either probe rc=0                   => FAIL         (at least one installed)
  #   both probes rc=1                    => PASS         (both absent)
  #
  typeset SNMP_CLIENT_RC SNMP_SERVER_RC
  typeset SNMP_CLIENT_RAW SNMP_SERVER_RAW
  typeset SNMP_STATUS SNMP_SEV SNMP_OBSERVED SNMP_MEANING SNMP_FIX
  SNMP_CLIENT_RAW=""
  SNMP_CLIENT_RC=126
  SNMP_SERVER_RAW=""
  SNMP_SERVER_RC=126
  SNMP_STATUS=""
  SNMP_SEV=""
  SNMP_OBSERVED=""
  SNMP_MEANING=""
  SNMP_FIX=""

  SNMP_CLIENT_RAW=$(aix lslpp_snmp_client lslpp -Lcq bos.net.tcp.snmp)
  SNMP_CLIENT_RC=$?
  SNMP_SERVER_RAW=$(aix lslpp_snmp_server lslpp -Lcq bos.net.tcp.snmpd)
  SNMP_SERVER_RC=$?

  if [ "$SNMP_CLIENT_RC" -eq 0 ] && [ -z "$SNMP_CLIENT_RAW" ]; then
    SNMP_STATUS=NOT_ASSESSED
    SNMP_SEV=low
    SNMP_OBSERVED="not assessed - SNMP client fileset probe returned rc=0 with no data row"
    SNMP_MEANING="PTxray did not obtain trustworthy package-inventory evidence for the SNMP client fileset."
    SNMP_FIX="run \"lslpp -Lcq bos.net.tcp.snmp\" as root, resolve the query problem, and rerun PTxray."
  elif [ "$SNMP_SERVER_RC" -eq 0 ] && [ -z "$SNMP_SERVER_RAW" ]; then
    SNMP_STATUS=NOT_ASSESSED
    SNMP_SEV=low
    SNMP_OBSERVED="not assessed - SNMP server fileset probe returned rc=0 with no data row"
    SNMP_MEANING="PTxray did not obtain trustworthy package-inventory evidence for the SNMP server fileset."
    SNMP_FIX="run \"lslpp -Lcq bos.net.tcp.snmpd\" as root, resolve the query problem, and rerun PTxray."
  elif [ "$SNMP_CLIENT_RC" -ne 0 ] && [ "$SNMP_CLIENT_RC" -ne 1 ]; then
    SNMP_STATUS=NOT_ASSESSED
    SNMP_SEV=low
    SNMP_OBSERVED="not assessed - SNMP client fileset probe failed (rc=$SNMP_CLIENT_RC)"
    SNMP_MEANING="PTxray did not obtain trustworthy package-inventory evidence for the SNMP client fileset."
    SNMP_FIX="run \"lslpp -Lcq bos.net.tcp.snmp\" as root, resolve the query failure, and rerun PTxray."
  elif [ "$SNMP_SERVER_RC" -ne 0 ] && [ "$SNMP_SERVER_RC" -ne 1 ]; then
    SNMP_STATUS=NOT_ASSESSED
    SNMP_SEV=low
    SNMP_OBSERVED="not assessed - SNMP server fileset probe failed (rc=$SNMP_SERVER_RC)"
    SNMP_MEANING="PTxray did not obtain trustworthy package-inventory evidence for the SNMP server fileset."
    SNMP_FIX="run \"lslpp -Lcq bos.net.tcp.snmpd\" as root, resolve the query failure, and rerun PTxray."
  elif [ "$SNMP_CLIENT_RC" -eq 0 ] || [ "$SNMP_SERVER_RC" -eq 0 ]; then
    SNMP_STATUS=FAIL
    SNMP_SEV=med
    if [ "$SNMP_CLIENT_RC" -eq 0 ]; then
      SNMP_OBSERVED="SNMP client fileset bos.net.tcp.snmp is installed"
      if [ "$SNMP_SERVER_RC" -eq 0 ]; then
        SNMP_OBSERVED="$SNMP_OBSERVED and the SNMP server fileset bos.net.tcp.snmpd is installed"
      fi
    else
      SNMP_OBSERVED="SNMP server fileset bos.net.tcp.snmpd is installed"
    fi
    SNMP_MEANING="An SNMP package is registered in the package inventory, so the SNMP service is part of this host's exposed software surface."
    SNMP_FIX="after confirming no workload needs SNMP, preview removal with 'installp -up <fileset>' and remove with 'installp -ug <fileset>' for each installed SNMP fileset; PTxray only recommends these actions."
  else
    SNMP_STATUS=PASS
    SNMP_SEV=low
    SNMP_OBSERVED="neither the SNMP client fileset nor the SNMP server fileset is installed"
    SNMP_MEANING="The SNMP client and server filesets are absent from the package inventory, so the SNMP service does not exist on this host."
    SNMP_FIX="n/a"
  fi

  add security snmp_filesets_absent "SNMP client and server filesets absent" \
    "$SNMP_STATUS" "$SNMP_SEV" \
    "$SNMP_OBSERVED" \
    "$SNMP_MEANING" \
    "$SNMP_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # rcnfs_lsitab — whether the rcnfs inittab entry is disabled (or absent).
  # NFS daemons are started at boot through the rcnfs inittab entry; when the
  # entry is absent, or its action field is "off", the daemons are not started.
  # Any other action value (wait, once, boot, ...) leaves the entry active.
  #
  # Probe: `lsitab rcnfs` (capture key rcnfs_lsitab).  The grep -v "off" filter
  # below is part of the discriminator, applied to the captured stdout in a
  # second step — it is not a separate capture.
  #
  # Verdicts:
  #   rc=0, raw stdout empty                     -> NOT_ASSESSED (contradictory)
  #   rc=0, filtered stdout empty (action "off") -> PASS
  #   rc=0, filtered stdout non-empty            -> FAIL
  #   rc!=0, raw stdout empty                    -> PASS (entry absent)
  #   rc!=0, raw stdout non-empty                -> NOT_ASSESSED (contradictory)
  typeset RCNFS_RC RCNFS_RAW RCNFS_FILTERED
  typeset RCNFS_STATUS RCNFS_OBSERVED RCNFS_MEANING RCNFS_FIX RCNFS_SEV
  RCNFS_RC=0
  RCNFS_RAW=""
  RCNFS_FILTERED=""

  RCNFS_RAW=$(aix rcnfs_lsitab lsitab rcnfs)
  RCNFS_RC=$?

  case "$RCNFS_RC" in
    0)
      if [ -z "$RCNFS_RAW" ]; then
        RCNFS_STATUS=NOT_ASSESSED
        RCNFS_OBSERVED="not assessed - lsitab rcnfs rc=0 but produced no output (contradictory)"
      else
        RCNFS_FILTERED=$(printf '%s\n' "$RCNFS_RAW" | grep -v "off")
        if [ -n "$RCNFS_FILTERED" ]; then
          RCNFS_STATUS=FAIL
          RCNFS_OBSERVED="rcnfs inittab entry is active (action is not off): $RCNFS_FILTERED"
        else
          RCNFS_STATUS=PASS
          RCNFS_OBSERVED="rcnfs inittab entry is present with action off (NFS not started at boot)"
        fi
      fi
      ;;
    *)
      # lsitab returned nonzero: the entry is absent (the normal not-found rc)
      # or the probe failed.  Verdicts follow the spec by captured stdout:
      # empty output is positive evidence of absence and passes; non-empty
      # output beside a nonzero rc is contradictory and cannot be assessed.
      if [ -z "$RCNFS_RAW" ]; then
        RCNFS_STATUS=PASS
        RCNFS_OBSERVED="no rcnfs entry in the inittab (NFS daemons not started at boot)"
      else
        RCNFS_STATUS=NOT_ASSESSED
        RCNFS_OBSERVED="not assessed - lsitab rcnfs rc=$RCNFS_RC but output was non-empty (contradictory)"
      fi
      ;;
  esac

  case "$RCNFS_STATUS" in
    PASS)
      RCNFS_MEANING="The rcnfs boot entry is absent or has action off, so the NFS daemon set is not started at boot."
      RCNFS_FIX="n/a"
      ;;
    FAIL)
      RCNFS_MEANING="The rcnfs boot entry is present with an action other than off, so the NFS daemon set starts at boot."
      RCNFS_FIX="after confirming the host needs no NFS service, disable the boot entry (lsitab -d rcnfs, or set its action field to off); PTxray only recommends this action."
      ;;
    *)
      RCNFS_MEANING="PTxray did not obtain trustworthy inittab evidence for the rcnfs entry."
      RCNFS_FIX="run 'lsitab rcnfs' as root, resolve the probe problem, and rerun PTxray."
      ;;
  esac

  case "$RCNFS_STATUS" in
    FAIL) RCNFS_SEV=high ;;
    *) RCNFS_SEV=low ;;
  esac

  add security rcnfs_lsitab "rcnfs inittab entry (NFS boot start)" \
    "$RCNFS_STATUS" "$RCNFS_SEV" \
    "$RCNFS_OBSERVED" \
    "$RCNFS_MEANING" \
    "$RCNFS_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # rctcpip_mrouted — CIS control 4.3.2.7: detect whether the mrouted multicast
  # routing daemon is enabled. Two read-only probes: a grep for the start line
  # in /etc/rc.tcpip and an lssrc -s status query. Non-compliant on either side
  # alone is FAIL; both compliant is PASS; a probe returning an unanticipated
  # rc or a contradictory rc/output pair is NOT_ASSESSED.
  #
  # Verdict logic:
  #   rc.tcpip: rc=0 and every nonblank matched line starts with '#'  => compliant
  #             rc=0 and any nonblank matched line is uncommented      => non-compliant
  #             rc=1 and empty output (no entry)                       => compliant
  #             anything else                                          => unknown
  #   lssrc:    rc=0 and output contains "active"                      => non-compliant
  #             rc=0 and output contains "inoperative"                 => compliant
  #             rc!=0 and output contains "not on file" (not installed)=> compliant
  #             anything else                                          => unknown
  #
  # Combined: either side non-compliant => FAIL; both compliant => PASS;
  # neither non-compliant with at least one unknown => NOT_ASSESSED.
  #
  typeset MR_BOOT_RC MR_BOOT_RAW MR_BOOT_STATE
  typeset MR_SRC_RC MR_SRC_RAW MR_SRC_STATE
  typeset MR_STATUS MR_SEV MR_OBS MR_MEAN MR_FIX MR_DETAIL

  MR_BOOT_RC=0
  MR_BOOT_RAW=""
  MR_BOOT_STATE=unknown
  MR_SRC_RC=0
  MR_SRC_RAW=""
  MR_SRC_STATE=unknown

  MR_BOOT_RAW=$(aix rc_tcpip_mrouted /usr/bin/grep "start[[:blank:]]/usr/sbin/mrouted" /etc/rc.tcpip)
  MR_BOOT_RC=$?

  if [ "$MR_BOOT_RC" -eq 0 ]; then
    if [ -z "$MR_BOOT_RAW" ]; then
      MR_BOOT_STATE=unknown
    else
      MR_BOOT_STATE=$(printf '%s\n' "$MR_BOOT_RAW" | awk '
        /^[[:blank:]]*$/ { next }
        {
          line = $0
          sub(/^[[:blank:]]+/, "", line)
          if (substr(line, 1, 1) != "#") { uncommented = 1 }
        }
        END {
          if (uncommented) print "non-compliant"; else print "compliant"
        }')
      [ -z "$MR_BOOT_STATE" ] && MR_BOOT_STATE=unknown
    fi
  elif [ "$MR_BOOT_RC" -eq 1 ]; then
    if [ -z "$MR_BOOT_RAW" ]; then
      MR_BOOT_STATE=compliant
    else
      MR_BOOT_STATE=unknown
    fi
  else
    MR_BOOT_STATE=unknown
  fi

  MR_SRC_RAW=$(aix mrouted_status /usr/bin/lssrc -s mrouted)
  MR_SRC_RC=$?

  if [ "$MR_SRC_RC" -eq 0 ]; then
    case "$MR_SRC_RAW" in
      *active*) MR_SRC_STATE=non-compliant ;;
      *inoperative*) MR_SRC_STATE=compliant ;;
      *) MR_SRC_STATE=unknown ;;
    esac
  else
    case "$MR_SRC_RAW" in
      *"not on file"*) MR_SRC_STATE=compliant ;;
      *) MR_SRC_STATE=unknown ;;
    esac
  fi

  MR_STATUS=NOT_ASSESSED
  MR_SEV=low
  MR_OBS="not assessed"
  MR_MEAN="PTxray did not obtain trustworthy evidence about whether the mrouted multicast routing daemon is enabled."
  MR_FIX="make /etc/rc.tcpip readable and the mrouted subsystem status queryable, then rerun PTxray."

  if [ "$MR_BOOT_STATE" = "non-compliant" ] || [ "$MR_SRC_STATE" = "non-compliant" ]; then
    MR_STATUS=FAIL
    MR_SEV=med
    MR_DETAIL=""
    [ "$MR_BOOT_STATE" = "non-compliant" ] && MR_DETAIL="starts at boot in /etc/rc.tcpip"
    if [ "$MR_SRC_STATE" = "non-compliant" ]; then
      if [ -n "$MR_DETAIL" ]; then
        MR_DETAIL="$MR_DETAIL and is active in the SRC subsystem"
      else
        MR_DETAIL="is active in the SRC subsystem"
      fi
    fi
    MR_OBS="mrouted $MR_DETAIL"
    MR_MEAN="An enabled mrouted daemon runs multicast routing that is not required on a normal host, adding avoidable network service exposure."
    MR_FIX="after service-owner approval, comment out the mrouted start line in /etc/rc.tcpip and stop the subsystem ('stopsrc -s mrouted'); PTxray only recommends these actions."
  elif [ "$MR_BOOT_STATE" = "compliant" ] && [ "$MR_SRC_STATE" = "compliant" ]; then
    MR_STATUS=PASS
    MR_SEV=low
    MR_OBS="mrouted not started in /etc/rc.tcpip and not active in the SRC subsystem"
    MR_MEAN="The mrouted multicast routing daemon is not enabled."
    MR_FIX="n/a"
  else
    MR_STATUS=NOT_ASSESSED
    MR_SEV=low
    MR_OBS="not assessed"
    if [ "$MR_BOOT_STATE" = "unknown" ]; then
      MR_OBS="$MR_OBS - rc.tcpip evidence unclear (rc=$MR_BOOT_RC)"
    fi
    if [ "$MR_SRC_STATE" = "unknown" ]; then
      MR_OBS="$MR_OBS - SRC status unclear (rc=$MR_SRC_RC)"
    fi
  fi

  add security rctcpip_mrouted "mrouted service" \
    "$MR_STATUS" "$MR_SEV" \
    "$MR_OBS" \
    "$MR_MEAN" \
    "$MR_FIX" \
    "cis-l2"
_AIXRAY_SESSION_KEYS=""
  # rctcpip_autoconf6 — CIS IBM AIX 7 v1.2.0 4.3.3.1: the IPv6 stateless
  # autoconfiguration daemon must be configured to start from /etc/rc.tcpip.
  # One grep probe decides: an uncommented '#start' line for /usr/sbin/autoconf6
  # is PASS; a readable rc.tcpip without one is FAIL; an unreadable rc.tcpip
  # (grep rc=2) is NOT_ASSESSED.
  typeset RT_AUTOCONF6_RAW RT_AUTOCONF6_RC
  typeset RT_AUTOCONF6_STATUS RT_AUTOCONF6_SEV RT_AUTOCONF6_OBS RT_AUTOCONF6_MEAN RT_AUTOCONF6_FIX

  RT_AUTOCONF6_RAW=$(aix grep_autoconf6_rc_tcpip grep "^#start[[:blank:]]/usr/sbin/autoconf6" /etc/rc.tcpip)
  RT_AUTOCONF6_RC=$?

  case "$RT_AUTOCONF6_RC" in
    0)
      if [ -n "$RT_AUTOCONF6_RAW" ]; then
        RT_AUTOCONF6_STATUS=PASS
        RT_AUTOCONF6_SEV=low
        RT_AUTOCONF6_OBS="/etc/rc.tcpip starts autoconf6 at boot (uncommented '#start' entry for /usr/sbin/autoconf6)"
        RT_AUTOCONF6_MEAN="The IPv6 stateless autoconfiguration daemon is configured to start from /etc/rc.tcpip."
        RT_AUTOCONF6_FIX="n/a"
      else
        RT_AUTOCONF6_STATUS=NOT_ASSESSED
        RT_AUTOCONF6_SEV=low
        RT_AUTOCONF6_OBS="not assessed - rc.tcpip probe returned rc=0 with no matching line"
        RT_AUTOCONF6_MEAN="PTxray did not obtain trustworthy evidence for the autoconf6 boot state."
        RT_AUTOCONF6_FIX="verify the autoconf6 '#start' entry in /etc/rc.tcpip, then rerun PTxray."
      fi
      ;;
    1)
      if [ -z "$RT_AUTOCONF6_RAW" ]; then
        RT_AUTOCONF6_STATUS=FAIL
        RT_AUTOCONF6_SEV=med
        RT_AUTOCONF6_OBS="/etc/rc.tcpip has no uncommented '#start' entry for /usr/sbin/autoconf6"
        RT_AUTOCONF6_MEAN="The IPv6 stateless autoconfiguration daemon is not configured to start from /etc/rc.tcpip."
        RT_AUTOCONF6_FIX="add the uncommented line 'start /usr/sbin/autoconf6 \"\"' to /etc/rc.tcpip and start the daemon for the current boot; PTxray only recommends these actions."
      else
        RT_AUTOCONF6_STATUS=NOT_ASSESSED
        RT_AUTOCONF6_SEV=low
        RT_AUTOCONF6_OBS="not assessed - rc.tcpip probe returned rc=1 with unexpected output"
        RT_AUTOCONF6_MEAN="PTxray did not obtain trustworthy evidence for the autoconf6 boot state."
        RT_AUTOCONF6_FIX="verify the autoconf6 '#start' entry in /etc/rc.tcpip, then rerun PTxray."
      fi
      ;;
    2)
      RT_AUTOCONF6_STATUS=NOT_ASSESSED
      RT_AUTOCONF6_SEV=low
      RT_AUTOCONF6_OBS="not assessed - rc.tcpip probe failed (rc=2); /etc/rc.tcpip may be missing or unreadable"
      RT_AUTOCONF6_MEAN="PTxray could not read /etc/rc.tcpip to determine the autoconf6 boot state."
      RT_AUTOCONF6_FIX="make /etc/rc.tcpip present and readable, then rerun PTxray."
      ;;
    *)
      RT_AUTOCONF6_STATUS=NOT_ASSESSED
      RT_AUTOCONF6_SEV=low
      RT_AUTOCONF6_OBS="not assessed - rc.tcpip probe returned unexpected rc=$RT_AUTOCONF6_RC"
      RT_AUTOCONF6_MEAN="PTxray did not obtain a recognised result from the rc.tcpip probe."
      RT_AUTOCONF6_FIX="verify the autoconf6 '#start' entry in /etc/rc.tcpip, then rerun PTxray."
      ;;
  esac

  add security rctcpip_autoconf6 "IPv6 stateless autoconfiguration daemon boot state" \
    "$RT_AUTOCONF6_STATUS" "$RT_AUTOCONF6_SEV" \
    "$RT_AUTOCONF6_OBS" \
    "$RT_AUTOCONF6_MEAN" \
    "$RT_AUTOCONF6_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # rc_tcpip_ndpd_host — ndpd-host boot start directive in /etc/rc.tcpip.
  # The AIX TCP/IP startup framework reads /etc/rc.tcpip; a '#start
  # /usr/sbin/ndpd-host' directive (the #start token is a directive prefix,
  # not a shell comment) starts the NDP host daemon at boot. Grep rc
  # discriminates: 0 with a match is the compliant state, 1 with no match
  # is the violation, 2 is an unreadable or missing file (indeterminate),
  # and a contradictory rc/stdout pair is unknown.
  typeset RT_NPDD_RAW RT_NPDD_RC
  typeset RT_NPDD_STATUS RT_NPDD_SEV RT_NPDD_OBS RT_NPDD_MEAN RT_NPDD_FIX

  RT_NPDD_RAW=$(aix rc_tcpip_ndpd_host grep '^#start[[:blank:]]/usr/sbin/ndpd-host' /etc/rc.tcpip)
  RT_NPDD_RC=$?

  case "$RT_NPDD_RC" in
    0)
      if [ -n "$RT_NPDD_RAW" ]; then
        RT_NPDD_STATUS=PASS
        RT_NPDD_SEV=low
        RT_NPDD_OBS="the '#start /usr/sbin/ndpd-host' directive is present in /etc/rc.tcpip"
        RT_NPDD_MEAN="The IPv6 Neighbor Discovery Protocol host daemon is configured to start at system boot."
        RT_NPDD_FIX="n/a"
      else
        RT_NPDD_STATUS=NOT_ASSESSED
        RT_NPDD_SEV=low
        RT_NPDD_OBS="not assessed - rc.tcpip probe returned rc=0 with no matching output"
        RT_NPDD_MEAN="PTxray did not obtain trustworthy evidence of the ndpd-host boot configuration."
        RT_NPDD_FIX="make /etc/rc.tcpip readable and rerun PTxray."
      fi
      ;;
    1)
      if [ -z "$RT_NPDD_RAW" ]; then
        RT_NPDD_STATUS=FAIL
        RT_NPDD_SEV=med
        RT_NPDD_OBS="no '#start /usr/sbin/ndpd-host' directive found in /etc/rc.tcpip"
        RT_NPDD_MEAN="The ndpd-host daemon has no boot start entry, so IPv6 Neighbor Discovery Protocol host functions are not started at system boot."
        RT_NPDD_FIX="add the '#start /usr/sbin/ndpd-host' directive to /etc/rc.tcpip so the daemon starts at boot; PTxray only recommends these actions."
      else
        RT_NPDD_STATUS=NOT_ASSESSED
        RT_NPDD_SEV=low
        RT_NPDD_OBS="not assessed - rc.tcpip probe returned contradictory output (rc=1 with a match)"
        RT_NPDD_MEAN="PTxray did not obtain trustworthy evidence of the ndpd-host boot configuration."
        RT_NPDD_FIX="make /etc/rc.tcpip readable and rerun PTxray."
      fi
      ;;
    2)
      RT_NPDD_STATUS=NOT_ASSESSED
      RT_NPDD_SEV=low
      RT_NPDD_OBS="not assessed - /etc/rc.tcpip is missing or unreadable (grep rc=2)"
      RT_NPDD_MEAN="PTxray did not obtain trustworthy evidence of the ndpd-host boot configuration."
      RT_NPDD_FIX="make /etc/rc.tcpip readable and rerun PTxray."
      ;;
    *)
      RT_NPDD_STATUS=NOT_ASSESSED
      RT_NPDD_SEV=low
      RT_NPDD_OBS="not assessed - rc.tcpip probe failed with rc=$RT_NPDD_RC"
      RT_NPDD_MEAN="PTxray did not obtain trustworthy evidence of the ndpd-host boot configuration."
      RT_NPDD_FIX="make /etc/rc.tcpip readable and rerun PTxray."
      ;;
  esac

  add security rc_tcpip_ndpd_host "ndpd-host daemon boot start" \
    "$RT_NPDD_STATUS" "$RT_NPDD_SEV" \
    "$RT_NPDD_OBS" \
    "$RT_NPDD_MEAN" \
    "$RT_NPDD_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # rctcpip_ndpd_router — verify the ndpd-router start directive in
  # /etc/rc.tcpip.  The probe greps for the ndpd-router start-directive line
  # anchored at the beginning of a line.  The verdict is read straight from
  # the probe discriminator: a clean match passes, a clean miss fails, and
  # every other rc/outcome combination is not assessed.
  #
  # Verdict logic:
  #   rc=0  AND  non-empty output  => PASS
  #   rc=1  AND  empty output      => FAIL
  #   rc=0  AND  empty output      => NOT_ASSESSED  (contradictory)
  #   rc=1  AND  non-empty output  => NOT_ASSESSED  (contradictory)
  #   rc=2  AND  any output        => NOT_ASSESSED  (grep error)
  #   rc>2  AND  any output        => NOT_ASSESSED  (unexpected rc)
  #
  typeset RT_NPD_ROUTER_RC RT_NPD_ROUTER_RAW RT_NPD_ROUTER_STATUS
  typeset RT_NPD_ROUTER_OBS RT_NPD_ROUTER_MEAN RT_NPD_ROUTER_FIX RT_NPD_ROUTER_SEV
  RT_NPD_ROUTER_RC=0
  RT_NPD_ROUTER_RAW=""

  RT_NPD_ROUTER_RAW=$(aix rctcpip_ndpd_router grep '^#start[[:blank:]]/usr/sbin/ndpd-router' /etc/rc.tcpip)
  RT_NPD_ROUTER_RC=$?

  case "$RT_NPD_ROUTER_RC" in
    0)
      if [ -n "$RT_NPD_ROUTER_RAW" ]; then
        RT_NPD_ROUTER_STATUS=PASS
        RT_NPD_ROUTER_OBS="ndpd-router start directive present in /etc/rc.tcpip"
        RT_NPD_ROUTER_MEAN="The /etc/rc.tcpip boot inventory carries the ndpd-router start directive."
        RT_NPD_ROUTER_FIX="n/a"
      else
        RT_NPD_ROUTER_STATUS=NOT_ASSESSED
        RT_NPD_ROUTER_OBS="not assessed - ndpd-router rc.tcpip probe rc=0 but output was empty after grep"
        RT_NPD_ROUTER_MEAN="PTxray did not obtain trustworthy /etc/rc.tcpip evidence."
        RT_NPD_ROUTER_FIX="inspect /etc/rc.tcpip, resolve the read problem, and rerun PTxray."
      fi
      ;;
    1)
      if [ -z "$RT_NPD_ROUTER_RAW" ]; then
        RT_NPD_ROUTER_STATUS=FAIL
        RT_NPD_ROUTER_OBS="ndpd-router start directive not present in /etc/rc.tcpip"
        RT_NPD_ROUTER_MEAN="The ndpd-router boot directive is absent from /etc/rc.tcpip, so the boot configuration does not match the required state."
        RT_NPD_ROUTER_FIX="after service-owner approval, restore the ndpd-router entry in /etc/rc.tcpip; PTxray only recommends these actions."
      else
        RT_NPD_ROUTER_STATUS=NOT_ASSESSED
        RT_NPD_ROUTER_OBS="not assessed - ndpd-router rc.tcpip probe rc=1 but output was non-empty (contradictory)"
        RT_NPD_ROUTER_MEAN="PTxray did not obtain trustworthy /etc/rc.tcpip evidence."
        RT_NPD_ROUTER_FIX="inspect /etc/rc.tcpip, resolve the read problem, and rerun PTxray."
      fi
      ;;
    2)
      RT_NPD_ROUTER_STATUS=NOT_ASSESSED
      RT_NPD_ROUTER_OBS="not assessed - ndpd-router rc.tcpip probe grep error (rc=2)"
      RT_NPD_ROUTER_MEAN="PTxray did not obtain trustworthy /etc/rc.tcpip evidence."
      RT_NPD_ROUTER_FIX="inspect /etc/rc.tcpip, resolve the read problem, and rerun PTxray."
      ;;
    *)
      RT_NPD_ROUTER_STATUS=NOT_ASSESSED
      RT_NPD_ROUTER_OBS="not assessed - ndpd-router rc.tcpip probe failed (rc=$RT_NPD_ROUTER_RC)"
      RT_NPD_ROUTER_MEAN="PTxray did not obtain trustworthy /etc/rc.tcpip evidence."
      RT_NPD_ROUTER_FIX="inspect /etc/rc.tcpip, resolve the read problem, and rerun PTxray."
      ;;
  esac

  case "$RT_NPD_ROUTER_STATUS" in
    FAIL) RT_NPD_ROUTER_SEV=high ;;
    *) RT_NPD_ROUTER_SEV=low ;;
  esac

  add security rctcpip_ndpd_router "ndpd-router boot directive" \
    "$RT_NPD_ROUTER_STATUS" "$RT_NPD_ROUTER_SEV" \
    "$RT_NPD_ROUTER_OBS" \
    "$RT_NPD_ROUTER_MEAN" \
    "$RT_NPD_ROUTER_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
# nfs_server_absent — NFS server fileset presence from the package inventory.
# Control 4.4.1.2 (Level 1): the NFS server fileset must not be installed.
# One capture key, lslpp_l (the full `lslpp -L` inventory). A data row naming
# bos.net.nfs.server is a FAIL; absence of such a row is a PASS; a failed
# inventory probe is NOT_ASSESSED. Absence is never inferred from empty or
# failed output: `lslpp -L` prints headers and a legend even when nothing is
# installed, so a clean run with no matching data row is the only PASS source.
typeset NFS_STATUS NFS_OBSERVED NFS_MEANING NFS_FIX
typeset NFS_RAW NFS_RC NFS_AWK_RC
NFS_RAW=""
NFS_RC=126
NFS_AWK_RC=1

# Key is `lslpp_L_all`, not `lslpp_l`. Fixture keys become FILENAMES, and the tree
# already carries `lslpp_L.out` (an orphan from the retired `aix lslpp_L` probe that
# tests/test-failed-logins-honesty.py still guards against reintroducing). On a
# case-insensitive filesystem -- the macOS default, where this repo is developed --
# `lslpp_l.out` and `lslpp_L.out` are the SAME FILE, so capturing this key silently
# overwrote a hand-authored fixture whose deliberately outdated openssh/openssl rows
# are the degraded condition aix72-degraded exists to model. Keys must not differ
# from an existing key by case alone.
NFS_RAW=$(aix lslpp_L_all lslpp -L)
NFS_RC=$?

if [ "$NFS_RC" -ne 0 ]; then
  NFS_STATUS=NOT_ASSESSED
  NFS_OBSERVED="not assessed - package inventory probe failed (rc=$NFS_RC)"
elif [ -z "$NFS_RAW" ]; then
  NFS_STATUS=NOT_ASSESSED
  NFS_OBSERVED="not assessed - package inventory probe returned rc=0 with empty output"
else
  # A data row is any line whose whitespace-delimited fields include the
  # fileset name itself. The header, the dashed separator and the state-code
  # legend never carry a field exactly equal to the fileset name, so exact
  # field equality is the whole discriminator; it also matches the indented
  # rows real `lslpp -L` output uses, which a leading-whitespace filter would
  # miss. Blank lines carry no fields and are skipped.
  printf '%s\n' "$NFS_RAW" | awk '
    /^[ \t]*$/ { next }
    $1 == "bos.net.nfs.server" || $2 == "bos.net.nfs.server" { found = 1 }
    END { if (found) exit 0; else exit 1 }
  '
  NFS_AWK_RC=$?
  case "$NFS_AWK_RC" in
    0)
      NFS_STATUS=FAIL
      NFS_OBSERVED="bos.net.nfs.server is present in the installed-fileset inventory"
      ;;
    1)
      NFS_STATUS=PASS
      NFS_OBSERVED="bos.net.nfs.server is not present in the installed-fileset inventory"
      ;;
    *)
      NFS_STATUS=NOT_ASSESSED
      NFS_OBSERVED="not assessed - package inventory scan failed (rc=$NFS_AWK_RC)"
      ;;
  esac
fi

case "$NFS_STATUS" in
  PASS)
    NFS_MEANING="The package inventory lists no NFS server fileset, so this host cannot export filesystems over NFS."
    NFS_FIX="n/a"
    ;;
  FAIL)
    NFS_MEANING="The NFS server fileset is installed, so this host can export filesystems over NFS."
    NFS_FIX="after confirming no workload needs the NFS server, preview the removal with 'installp -up bos.net.nfs.server' and remove with 'installp -ug bos.net.nfs.server'; PTxray only recommends these actions."
    ;;
  *)
    NFS_MEANING="PTxray did not obtain a trustworthy package-inventory result, so NFS server presence could not be assessed."
    NFS_FIX="run \"lslpp -L\" with read access to the package inventory, resolve the failure, and rerun PTxray."
    ;;
esac

add security nfs_server_absent "NFS server fileset" \
  "$NFS_STATUS" high "$NFS_OBSERVED" \
  "$NFS_MEANING" "$NFS_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # nfs_export_everyone — active NFS exports accessible to unauthenticated clients.
  # All reads are fixture-routed and side-effect free. showmount -e lists the
  # local NFS server's currently exported directories with their access lists;
  # an export line listing (everyone) imposes no client restriction.
  #
  # showmount -e is an RPC query to the local mount daemon, and on a host that
  # exports nothing it exits non-zero with empty stdout — the state captured on
  # both lab boxes on 2026-08-06 (showmount_e.out empty, showmount_e.rc 1).
  # Refusing there would leave this check able only to refuse, which is not
  # coverage. A non-zero rc is therefore resolved against two local, non-RPC
  # probes that ck-nfs-exports already uses: the no-argument exportfs listing
  # (/etc/xtab — the active export table) and /etc/exports (the definition
  # file). The empty conclusion is drawn only when BOTH independently show an
  # empty export set; a failed exportfs, an inconclusive listing, or an
  # unestablished /etc/exports state still refuses, so an rc=1 that actually
  # means "mountd unreachable" can never be laundered into a clean verdict.
  typeset SHOWMOUNT SHOWMOUNT_RC NEE_EVERYONE NEE_ROWS
  typeset NEE_LIVE NEE_LIVE_RC NEE_LIVE_NONE
  typeset NEE_CONF NEE_CONF_RC NEE_CONF_EXISTS_OUT NEE_CONF_EXISTS_RC
  typeset NEE_CONF_NONE NEE_WHY

  SHOWMOUNT=$(aix showmount_e showmount -e); SHOWMOUNT_RC=$?
  NEE_LIVE=$(aix exportfs exportfs); NEE_LIVE_RC=$?
  NEE_CONF_EXISTS_OUT=$(aix etc_exports_exists test -e /etc/exports)
  NEE_CONF_EXISTS_RC=$?
  NEE_CONF=$(aix etc_exports cat /etc/exports); NEE_CONF_RC=$?

  # Corroborator 1 — the active export table. rc is settled before any parsing.
  # AIX prints the no-export sentinel with or without its message number.
  NEE_LIVE_NONE=0
  if [ "$NEE_LIVE_RC" -eq 0 ] && [ -n "$NEE_LIVE" ]; then
    case "$NEE_LIVE" in
      "exportfs: nothing exported") NEE_LIVE_NONE=1 ;;
      "exportfs: "[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9]" nothing exported")
        NEE_LIVE_NONE=1 ;;
      *)
        NEE_LIVE_NONE=$(printf '%s\n' "$NEE_LIVE" | awk '
          {
            text=$0
            sub(/^[ \t]+/, "", text)
            if (text == "") next
            nonblank=1
            if (text !~ /^#/) rows=1
          }
          END {print (nonblank && !rows) ? 1 : 0}
        ')
        ;;
    esac
  fi

  # Corroborator 2 — the definition file. A read failure only settles anything
  # when the existence probe reports the file as genuinely absent.
  NEE_CONF_NONE=0
  if [ "$NEE_CONF_RC" -eq 0 ]; then
    NEE_CONF_NONE=$(printf '%s\n' "$NEE_CONF" | awk '
      {
        text=$0
        sub(/[ \t]*#.*/, "", text)
        if (text !~ /^[ \t]*$/) rows=1
      }
      END {print rows ? 0 : 1}
    ')
  elif [ "$NEE_CONF_EXISTS_RC" -eq 1 ]; then
    NEE_CONF_NONE=1
  fi

  # showmount evidence is parsed only after its rc is known to be 0. OBSERVED is
  # capped at 120 characters so the finding stays one bounded TSV field.
  NEE_EVERYONE=""
  NEE_ROWS=0
  if [ "$SHOWMOUNT_RC" -eq 0 ] && [ -n "$SHOWMOUNT" ]; then
    NEE_EVERYONE=$(printf '%s\n' "$SHOWMOUNT" | awk '
      index($0, "(everyone)") > 0 {
        n++
        if (n <= 3) list = (list == "" ? $1 : list " " $1)
      }
      END {
        if (n == 0) exit 0
        text = n " export(s) shared with everyone: " list
        if (n > 3) text = text " (+" (n - 3) " more)"
        if (substr(text, 118, 1) != "") text = substr(text, 1, 117) "..."
        print text
      }
    ')
    NEE_ROWS=$(printf '%s\n' "$SHOWMOUNT" | awk '$1 ~ /^\// {n++} END {print n+0}')
  fi

  if [ "$SHOWMOUNT_RC" -eq 0 ]; then
    NEE_WHY="showmount -e listed no export (rc=0)"
  else
    NEE_WHY="showmount -e failed (rc=$SHOWMOUNT_RC)"
  fi

  if [ -n "$NEE_EVERYONE" ]; then
    add security nfs_export_everyone "NFS export access" FAIL high \
        "$NEE_EVERYONE" \
        "At least one currently exported directory is accessible to unauthenticated clients; the NFS server imposes no client restriction on it." \
        "remove (everyone) from the access list of each affected export and re-export through the approved change process." "cis-l2"
  elif [ "$SHOWMOUNT_RC" -eq 0 ] && [ "$NEE_ROWS" -gt 0 ]; then
    add security nfs_export_everyone "NFS export access" PASS high \
        "$NEE_ROWS active export(s); every export lists explicit clients" \
        "Every currently exported directory has a client restriction; showmount -e listed no (everyone) access target." \
        "n/a" "cis-l2"
  elif [ "$NEE_LIVE_NONE" -eq 1 ] && [ "$NEE_CONF_NONE" -eq 1 ]; then
    add security nfs_export_everyone "NFS export access" PASS high \
        "no NFS export is active; exportfs and /etc/exports both list none" \
        "This host exports nothing: the active export table reports no exported directory and /etc/exports defines none, so no export is shared with unauthenticated clients." \
        "n/a" "cis-l2"
  elif [ "$NEE_LIVE_RC" -ne 0 ]; then
    add security nfs_export_everyone "NFS export access" NOT_ASSESSED high \
        "not assessed — $NEE_WHY and exportfs failed (rc=$NEE_LIVE_RC)" \
        "Neither the advertised export list nor the local active export table could be read, so no claim about world-accessible exports is possible." \
        "restore access to the local NFS mount daemon and the no-argument exportfs listing, then rerun PTxray." "cis-l2"
  elif [ "$NEE_LIVE_NONE" -ne 1 ]; then
    add security nfs_export_everyone "NFS export access" NOT_ASSESSED high \
        "not assessed — $NEE_WHY; exportfs did not confirm an empty export set" \
        "The advertised export list was unavailable and the local active export table neither proved an empty export set nor could be read for (everyone) access targets." \
        "restore access to the local NFS mount daemon, verify the complete no-argument exportfs listing, then rerun PTxray." "cis-l2"
  else
    add security nfs_export_everyone "NFS export access" NOT_ASSESSED high \
        "not assessed — $NEE_WHY; /etc/exports state not established (rc=$NEE_CONF_RC)" \
        "The active export table reported nothing exported, but /etc/exports could not be read or shows definitions, so the empty export set is not corroborated." \
        "restore read access to /etc/exports, confirm whether its definitions are intentionally dormant, then rerun PTxray." "cis-l2"
  fi
_AIXRAY_SESSION_KEYS=""
  # nfs_export_sec — every NFS export must declare a sec= security flavour and
  # that flavour list must not include none. Reads the lsnfsexp listing once and
  # analyses the captured text; emits one finding per defective export line.
  typeset NSE_RAW NSE_RC NSE_CLASS NSE_ENTRIES NSE_DEFECTS
  typeset NSE_DEFECT_LIST NSE_TAG NSE_PATH

  NSE_RAW=$(aix lsnfsexp lsnfsexp); NSE_RC=$?
  # aix() returns 127 for BOTH a genuinely absent command and a fixture that
  # never captured lsnfsexp. Only the former is determinate non-applicability;
  # a missing capture is an honest refusal (round-3 D3).
  if aix_capture_missing lsnfsexp; then
    add security nfs_export_sec "NFS export security" NOT_ASSESSED low \
        "not assessed — lsnfsexp probe was not captured for this system" \
        "The lsnfsexp capture is absent from this scan's fixture set, so PTxray cannot tell whether the command is genuinely absent or merely unrecorded." \
        "capture 'lsnfsexp' from a representative AIX host, then rerun PTxray." "cis-l2"
  elif [ "$NSE_RC" -eq 127 ]; then
    add security nfs_export_sec "NFS export security" NOT_APPLICABLE low \
        "lsnfsexp not found (rc=127)" \
        "The lsnfsexp command is absent, so no NFS server fileset is installed to constrain." \
        "n/a" "cis-l2"
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="lsnfsexp"
  elif [ "$NSE_RC" -ne 0 ]; then
    add security nfs_export_sec "NFS export security" NOT_ASSESSED low \
        "not assessed — lsnfsexp probe failed (rc=$NSE_RC)" \
        "The lsnfsexp probe exited $NSE_RC, so the exported file system set and its security flavours are unknown." \
        "inspect why lsnfsexp failed, then re-run PTxray." "cis-l2"
  else
    NSE_CLASS=$(printf '%s\n' "$NSE_RAW" | awk '
      {
        text=$0
        sub(/[ \t]*#.*/, "", text)
        if (text ~ /^[ \t]*$/) next
        sub(/^[ \t]+/, "", text)
        sub(/[ \t]+$/, "", text)
        if (text !~ /^\//) next
        path=text
        sub(/[ \t].*$/, "", path)
        has_sec=0
        has_none=0
        count=split(text, toks, /[ \t]+/)
        for (i=1; i<=count; i++) {
          tok=toks[i]
          sub(/^-+/, "", tok)
          if (tok ~ /^sec=/) {
            has_sec=1
            val=tok
            sub(/^sec=/, "", val)
            gsub(/,/, ":", val)
            fcount=split(val, fl, ":")
            for (j=1; j<=fcount; j++) if (fl[j] == "none") has_none=1
          }
        }
        if (has_none) {
          print "NONE|" path
          next
        }
        if (!has_sec) {
          print "MISSING|" path
          next
        }
        print "OK|" path
      }
    ')
    NSE_ENTRIES=$(printf '%s\n' "$NSE_CLASS" | awk -F '|' 'NF {n++} END {print n+0}')
    NSE_DEFECTS=$(printf '%s\n' "$NSE_CLASS" | awk -F '|' '$1=="MISSING" || $1=="NONE" {n++} END {print n+0}')
    if [ "$NSE_ENTRIES" -eq 0 ]; then
      add security nfs_export_sec "NFS export security" PASS low \
          "no NFS exports" \
          "The lsnfsexp listing contains no exported file system, so no insecure export exists to constrain." \
          "n/a" "cis-l2"
    elif [ "$NSE_DEFECTS" -eq 0 ]; then
      add security nfs_export_sec "NFS export security" PASS low \
          "all NFS exports declare a non-none security flavour" \
          "Every exported file system line carries a sec= option and no sec= list includes the none flavour." \
          "n/a" "cis-l2"
    else
      NSE_DEFECT_LIST=$(printf '%s\n' "$NSE_CLASS" \
        | awk -F '|' '$1=="MISSING" || $1=="NONE"')
      while IFS='|' read -r NSE_TAG NSE_PATH; do
        case "$NSE_TAG" in
          MISSING)
            add security nfs_export_sec "NFS export security" FAIL med \
                "$NSE_PATH: export has no sec= security flavour option" \
                "An exported file system line lacks a sec= option, so no explicit NFS security flavour constrains this export." \
                "add a sec= option with a non-none security flavour to this export and re-export it during an approved change." "cis-l2"
            ;;
          NONE)
            add security nfs_export_sec "NFS export security" FAIL med \
                "$NSE_PATH: sec= list includes the none flavour" \
                "An exported file system line declares sec=none or a colon-separated sec= list containing none, allowing unauthenticated NFS access." \
                "remove the none flavour from this export's sec= list, keeping only explicit authentication flavours, and re-export it during an approved change." "cis-l2"
            ;;
        esac
      done <<EOF
$NSE_DEFECT_LIST
EOF
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # clic_installed - CLiC cryptographic software package and kernel-extension
  # state (CIS 4.4.2.1). Two unconditional read-only probes: the installed
  # software inventory filtered for the clic fileset family, and the loaded
  # kernel extensions filtered for crypto modules. A bare "crypt" match is not
  # proof the CLiC extension is loaded, because unrelated hardware crypto
  # drivers match it too; the genkex output must also name the clickext
  # extension. Absence of the fileset row or of the extension is a determinate
  # fail; only a probe rc greater than 1 is an unknown state.
  typeset LSLPP_RAW LSLPP_RC GENKEX_RAW GENKEX_RC
  typeset LSLPP_PRESENT GENKEX_CRYPT GENKEX_LOADED
  typeset CLIC_STATUS CLIC_OBSERVED CLIC_MEANING CLIC_FIX CLIC_SEVERITY

  # The aix helper returns the capture rc as its exit status. It is read here
  # before any pipe, because a pipe would report grep's rc and lose a capture
  # rc>1 (probe failure) before the discriminator can see it.
  LSLPP_RAW=$(aix lslpp_L_clic lslpp -L)
  LSLPP_RC=$?
  GENKEX_RAW=$(aix genkex_crypt genkex)
  GENKEX_RC=$?

  if [ "$LSLPP_RC" -gt 1 ]; then
    CLIC_STATUS=NOT_ASSESSED
    CLIC_OBSERVED="not assessed - lslpp package-inventory probe failed (rc=$LSLPP_RC)"
  elif [ "$GENKEX_RC" -gt 1 ]; then
    CLIC_STATUS=NOT_ASSESSED
    CLIC_OBSERVED="not assessed - genkex kernel-extension probe failed (rc=$GENKEX_RC)"
  else
    LSLPP_PRESENT=0
    GENKEX_CRYPT=0
    GENKEX_LOADED=0
    case "$LSLPP_RAW" in
      *clic*) LSLPP_PRESENT=1 ;;
    esac
    case "$GENKEX_RAW" in
      *crypt*) GENKEX_CRYPT=1 ;;
    esac
    case "$GENKEX_RAW" in
      *clickext*) GENKEX_LOADED=1 ;;
    esac
    if [ "$LSLPP_PRESENT" -eq 1 ] && [ "$GENKEX_LOADED" -eq 1 ]; then
      CLIC_STATUS=PASS
      CLIC_OBSERVED="clic.rte filesets installed; CLiC kernel extension loaded"
    else
      CLIC_STATUS=FAIL
      if [ "$LSLPP_PRESENT" -ne 1 ]; then
        CLIC_OBSERVED="no clic.rte fileset in the installed-software listing"
      elif [ "$GENKEX_CRYPT" -ne 1 ]; then
        CLIC_OBSERVED="clic.rte filesets installed but no crypto kernel extension is loaded"
      else
        CLIC_OBSERVED="clic.rte filesets installed but the CLiC kernel extension is not loaded"
      fi
    fi
  fi

  case "$CLIC_STATUS" in
    PASS)
      CLIC_SEVERITY=low
      CLIC_MEANING="The CLiC cryptographic software package is installed and its kernel extension is loaded."
      CLIC_FIX="n/a"
      ;;
    FAIL)
      CLIC_SEVERITY=med
      CLIC_MEANING="CLiC cryptographic software is not fully installed and active."
      CLIC_FIX="install the CLiC package and ensure its kernel extension is loaded, then rerun PTxray; PTxray only recommends these actions."
      ;;
    *)
      CLIC_SEVERITY=low
      CLIC_MEANING="PTxray did not obtain trustworthy evidence for the CLiC software state."
      CLIC_FIX="resolve the failed probe so lslpp -L and genkex return complete output, then rerun PTxray."
      ;;
  esac

  add security clic_installed "CLiC cryptographic software installation" \
    "$CLIC_STATUS" "$CLIC_SEVERITY" "$CLIC_OBSERVED" \
    "$CLIC_MEANING" "$CLIC_FIX" "cis-l2"
_AIXRAY_SESSION_KEYS=""
  # fs_jfs_nodev — every JFS filesystem must carry the nodev mount option so the
  # kernel never interprets device nodes on it (a privilege-escalation path).
  # The root filesystem on /dev/hd4 is exempt.  Both the filesystem table (lsfs)
  # and the live mount list (mount) are checked, so a filesystem missing nodev in
  # either configuration is caught.
  #
  # Discriminator (applied to each capture, not on the box):
  #   grep jfs | grep -Ev "/dev/hd4|nodev"   -> rows are JFS filesystems
  #                                              lacking nodev (the /dev/hd4
  #                                              exemption is the substring
  #                                              match inside this exclusion)
  #   grep jfs                               -> any JFS rows at all
  #
  # Verdicts:
  #   lsfs rc != 0 or mount rc != 0            -> NOT_ASSESSED (probe failed;
  #                                                 rc=0 is success, any positive
  #                                                 rc means state unknown)
  #   either bad list non-empty                -> FAIL
  #   no JFS rows in lsfs and none in mount    -> NOT_APPLICABLE
  #   otherwise                                -> PASS
  #
  typeset FSJ_LSFS FSJ_LSFS_RC FSJ_MNT FSJ_MNT_RC
  typeset FSJ_LSFS_BAD FSJ_MNT_BAD FSJ_LSFS_JFS FSJ_MNT_JFS
  typeset FSJ_STATUS FSJ_SEVERITY FSJ_OBSERVED FSJ_MEANING FSJ_FIX
  typeset FSJ_BAD1
  FSJ_LSFS_RC=0
  FSJ_MNT_RC=0
  FSJ_LSFS_BAD=""
  FSJ_MNT_BAD=""
  FSJ_LSFS_JFS=""
  FSJ_MNT_JFS=""
  FSJ_STATUS=""
  FSJ_SEVERITY=low
  FSJ_OBSERVED=""
  FSJ_MEANING=""
  FSJ_FIX=""

  FSJ_LSFS=$(aix lsfs lsfs); FSJ_LSFS_RC=$?
  FSJ_MNT=$(aix mount mount); FSJ_MNT_RC=$?

  if [ "$FSJ_LSFS_RC" -eq 0 ] && [ "$FSJ_MNT_RC" -eq 0 ]; then
    FSJ_LSFS_BAD=$(printf '%s\n' "$FSJ_LSFS" | grep jfs | grep -E -v '/dev/hd4|nodev')
    FSJ_MNT_BAD=$(printf '%s\n' "$FSJ_MNT" | grep jfs | grep -E -v '/dev/hd4|nodev')
    if [ -n "$FSJ_LSFS_BAD" ] || [ -n "$FSJ_MNT_BAD" ]; then
      FSJ_STATUS=FAIL
      FSJ_SEVERITY=med
      FSJ_BAD1=$(printf '%s' "$FSJ_LSFS_BAD $FSJ_MNT_BAD" | tr '\n' ' ')
      FSJ_OBSERVED="JFS filesystem(s) without nodev: $FSJ_BAD1"
      FSJ_MEANING="A JFS filesystem is defined or mounted without the nodev mount option, so device nodes on that filesystem are interpreted by the kernel — a local user able to create a file there can forge a device node and escalate privilege. The root filesystem on /dev/hd4 is the single allowed exception."
      FSJ_FIX="add nodev to the filesystem's mount options (e.g. chfs -a options=+nodev <mountpoint>) and remount so it takes effect, then confirm with 'mount'. PTxray only reports this; it does not remediate."
    else
      FSJ_LSFS_JFS=$(printf '%s\n' "$FSJ_LSFS" | grep jfs)
      FSJ_MNT_JFS=$(printf '%s\n' "$FSJ_MNT" | grep jfs)
      if [ -z "$FSJ_LSFS_JFS" ] && [ -z "$FSJ_MNT_JFS" ]; then
        FSJ_STATUS=NOT_APPLICABLE
        FSJ_OBSERVED="no JFS filesystems in lsfs or mount output"
        FSJ_MEANING="No JFS filesystem exists in either the filesystem table or the current mount list, so there is nothing for this control to constrain."
        FSJ_FIX="n/a"
      else
        FSJ_STATUS=PASS
        FSJ_OBSERVED="all JFS filesystems carry nodev"
        FSJ_MEANING="Every JFS filesystem is defined and mounted with the nodev option (or only the exempt root filesystem /dev/hd4 is present), so device nodes on those filesystems are not interpreted by the kernel."
        FSJ_FIX="n/a"
      fi
    fi
  else
    FSJ_STATUS=NOT_ASSESSED
    FSJ_OBSERVED="not assessed — lsfs/mount capture failed (lsfs rc=$FSJ_LSFS_RC, mount rc=$FSJ_MNT_RC)"
    FSJ_MEANING="The nodev state of JFS filesystems could not be assessed because the lsfs or mount probe failed; the state is genuinely unknown."
    FSJ_FIX="run 'lsfs' and 'mount' manually, then rerun PTxray."
  fi

  add security fs_jfs_nodev "JFS nodev mount option" \
    "$FSJ_STATUS" "$FSJ_SEVERITY" \
    "$FSJ_OBSERVED" "$FSJ_MEANING" "$FSJ_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # ftpd_root_denied — FTP daemon deny list blocks root login.
  # Control 4.6.2.1 (CIS IBM AIX 7 v1.2.0, Level 1).  The compliant state is a
  # line reading exactly "root" in /etc/ftpusers.  A bare substring match would
  # accept a different entry (noroot, rootuser) and pass a box that still
  # permits root, so the probe anchors to the whole line.
  typeset FTRD_RAW FTRD_RC
  typeset FTRD_STATUS FTRD_SEV FTRD_OBSERVED FTRD_MEANING FTRD_FIX

  # Single-quoted: inside double quotes the trailing $" is an ambiguous
  # expansion and ksh -n warns on it. It happens to work here, but this ships to
  # AIX ksh88 and a pattern that silently loses its anchor would make the check
  # match "root" anywhere in the line rather than a whole-line root entry.
  FTRD_RAW=$(aix grep_root_ftpusers grep '^root$' /etc/ftpusers)
  FTRD_RC=$?

  case "$FTRD_RC" in
    0)
      # grep matched: at least one exact "root" line.  root is denied.
      FTRD_STATUS=PASS
      FTRD_SEV=low
      FTRD_OBSERVED="root is listed in /etc/ftpusers, so the FTP daemon refuses root login"
      FTRD_MEANING="The FTP deny list contains a root entry, so root cannot authenticate over FTP."
      FTRD_FIX="n/a"
      ;;
    1)
      # grep found no match: /etc/ftpusers exists but has no "root" line.
      FTRD_STATUS=FAIL
      FTRD_SEV=high
      FTRD_OBSERVED="/etc/ftpusers exists but contains no root line, so the FTP daemon permits root login"
      FTRD_MEANING="Without a root entry in the FTP deny list the daemon accepts root, exposing the account to remote password attacks."
      FTRD_FIX="append a line reading 'root' to /etc/ftpusers; PTxray only recommends this action"
      ;;
    2)
      # grep error: /etc/ftpusers does not exist (or is unreadable).  The deny
      # mechanism is absent, so nothing blocks root if the daemon runs.
      FTRD_STATUS=FAIL
      FTRD_SEV=high
      FTRD_OBSERVED="/etc/ftpusers is absent (rc=2), so no FTP deny entry for root exists"
      FTRD_MEANING="With the deny mechanism missing there is no entry blocking root, so root login over FTP is permitted if the daemon runs."
      FTRD_FIX="create /etc/ftpusers containing a line reading 'root'; PTxray only recommends this action"
      ;;
    *)
      # An rc the probe did not anticipate: the state is genuinely unknown.
      FTRD_STATUS=NOT_ASSESSED
      FTRD_SEV=med
      FTRD_OBSERVED="not assessed - /etc/ftpusers probe returned an unexpected status (rc=$FTRD_RC)"
      FTRD_MEANING="PTxray did not obtain a determinate result from the FTP deny-list probe, so it cannot judge root FTP access."
      FTRD_FIX="verify /etc/ftpusers exists and is readable, then rerun PTxray"
      ;;
  esac

  add security ftpd_root_denied "FTP root deny" \
    "$FTRD_STATUS" "$FTRD_SEV" "$FTRD_OBSERVED" \
    "$FTRD_MEANING" "$FTRD_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # ftpd_login_banner — authorized-use banner for an active ftpd.  When ftpd
  # is configured in /etc/inetd.conf the message catalog fileset
  # bos.msg.en_US.net.tcp.client must be installed and catalog set 1 message 9
  # of ftpd.cat must carry the prescribed warning.  With no ftpd configured
  # the banner constrains a service that need not exist and is reported
  # NOT_APPLICABLE.  The catalog message is matched without its printf
  # placeholder prefix.
  typeset FTP_LB_FTP_RAW FTP_LB_FTP_RC
  typeset FTP_LB_LSLPP_RAW FTP_LB_LSLPP_RC FTP_LB_LSLPP_ROW
  typeset FTP_LB_DSPCAT_RAW FTP_LB_DSPCAT_RC FTP_LB_BANNER_OK
  typeset FTP_LB_STATUS FTP_LB_OBSERVED FTP_LB_MEANING FTP_LB_FIX SEVERITY

  FTP_LB_FTP_RAW=$(aix inetd_ftp grep '^ftp[[:blank:]]' /etc/inetd.conf) # network-lint: allow -- reads the LOCAL /etc/inetd.conf capture text (via the aix wrapper), never a network call
  FTP_LB_FTP_RC=$?

  if [ "$FTP_LB_FTP_RC" -eq 0 ] && [ -n "$FTP_LB_FTP_RAW" ]; then
    # ftpd is configured — the banner controls apply
    FTP_LB_LSLPP_RAW=$(aix lslpp_bos_msg lslpp -L "bos.msg.en_US.net.tcp.client")
    FTP_LB_LSLPP_RC=$?
    FTP_LB_LSLPP_ROW=$(printf '%s\n' "$FTP_LB_LSLPP_RAW" | awk -v want='bos.msg.en_US.net.tcp.client' 'index($0, want) { found = 1 } END { print found ? "yes" : "no" }')
    if [ "$FTP_LB_LSLPP_RC" -eq 0 ] && [ "$FTP_LB_LSLPP_ROW" = yes ]; then
      # the message catalog fileset is installed — the banner text decides
      FTP_LB_DSPCAT_RAW=$(aix dspcat_ftpd_banner dspcat /usr/lib/nls/msg/en_US/ftpd.cat 1 9)
      FTP_LB_DSPCAT_RC=$?
      FTP_LB_BANNER_OK=$(printf '%s\n' "$FTP_LB_DSPCAT_RAW" | awk 'index($0, "Authorized uses only. All activity may be monitored and reported") { found = 1 } END { print found ? "yes" : "no" }')
      if [ "$FTP_LB_DSPCAT_RC" -eq 0 ] && [ "$FTP_LB_BANNER_OK" = yes ]; then
        FTP_LB_STATUS=PASS
        FTP_LB_OBSERVED="ftpd active; message catalog installed; catalog set 1 message 9 carries the authorized-use warning"
      elif [ "$FTP_LB_DSPCAT_RC" -eq 0 ]; then
        FTP_LB_STATUS=FAIL
        FTP_LB_OBSERVED="ftpd active; message catalog installed; catalog set 1 message 9 does not carry the expected authorized-use warning"
      else
        FTP_LB_STATUS=NOT_ASSESSED
        FTP_LB_OBSERVED="not assessed - banner probe failed (rc=$FTP_LB_DSPCAT_RC)"
      fi
    elif [ "$FTP_LB_LSLPP_RC" -eq 1 ] && [ "$FTP_LB_LSLPP_ROW" = no ]; then
      FTP_LB_STATUS=FAIL
      FTP_LB_OBSERVED="ftpd active; the message catalog fileset bos.msg.en_US.net.tcp.client is not installed"
    else
      FTP_LB_STATUS=NOT_ASSESSED
      FTP_LB_OBSERVED="not assessed - catalog fileset probe was contradictory or failed (rc=$FTP_LB_LSLPP_RC)"
    fi
  elif [ "$FTP_LB_FTP_RC" -eq 1 ] && [ -z "$FTP_LB_FTP_RAW" ]; then
    FTP_LB_STATUS=NOT_APPLICABLE
    FTP_LB_OBSERVED="ftpd not configured in /etc/inetd.conf; no ftpd login banner is presented"
  else
    FTP_LB_STATUS=NOT_ASSESSED
    FTP_LB_OBSERVED="not assessed - ftpd probe was contradictory or failed (rc=$FTP_LB_FTP_RC)"
  fi

  case "$FTP_LB_STATUS" in
    PASS)
      FTP_LB_MEANING="The active ftpd service presents the required authorized-use warning before login."
      FTP_LB_FIX="n/a"
      ;;
    FAIL)
      FTP_LB_MEANING="An active ftpd service is missing the required authorized-use banner, so users are not warned that the system is monitored."
      FTP_LB_FIX="install the bos.msg.en_US.net.tcp.client fileset and set catalog set 1 message 9 of ftpd.cat to the prescribed warning text; PTxray only recommends these actions."
      ;;
    NOT_APPLICABLE)
      FTP_LB_MEANING="The ftpd service is not configured, so no ftpd login banner is required."
      FTP_LB_FIX="n/a"
      ;;
    *)
      FTP_LB_MEANING="PTxray did not obtain trustworthy evidence for the ftpd login banner configuration."
      FTP_LB_FIX="verify the ftpd service state, the message catalog fileset, and the ftpd.cat message as root, then rerun PTxray."
      ;;
  esac

  case "$FTP_LB_STATUS" in FAIL) SEVERITY=high ;; *) SEVERITY=low ;; esac
  add security ftpd_login_banner "ftpd login banner" \
    "$FTP_LB_STATUS" "$SEVERITY" "$FTP_LB_OBSERVED" \
    "$FTP_LB_MEANING" "$FTP_LB_FIX" "cis-l1"
  if [ "$FTP_LB_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="grep '^ftp[[:blank:]]' /etc/inetd.conf" # network-lint: allow -- evidence display string for the LOCAL inetd.conf grep, no network call
  fi
_AIXRAY_SESSION_KEYS=""

  # ck-ftpd-umask — verify the umask carried in the ftp daemon arguments when # network-lint: allow -- prose comment, no network call
  # the ftp service is registered in /etc/inetd.conf.  CIS control 4.6.2.3 # network-lint: allow -- prose comment, no network call
  # requires those arguments to set the file-creation umask to 027 so files
  # the daemon creates are not exposed to unintended access.
  #
  # Capture: grep for a line whose first field is exactly "ftp" followed by # network-lint: allow -- prose comment, no network call
  # whitespace (not a comment, not a substring in a later field).
  #
  # Verdict logic:
  #   rc=1  AND  empty output                                   => NOT_APPLICABLE
  #   rc=0  AND  single line with "-u 027" or "-u027" in columns 6..10 => PASS
  #   rc=0  AND  single line without a compliant umask           => FAIL
  #   rc=0  AND  empty output (contradictory)                    => NOT_ASSESSED
  #   rc=0  AND  more than one matched line (ambiguous)          => NOT_ASSESSED
  #   rc=1  AND  non-empty output (contradictory)                => NOT_ASSESSED
  #   any other rc (grep failed)                                 => NOT_ASSESSED
  #
  typeset ID_FTPD_RC ID_FTPD_RAW ID_FTPD_CLASS
  typeset ID_FTPD_STATUS ID_FTPD_OBSERVED ID_FTPD_MEANING
  typeset ID_FTPD_FIX SEVERITY
  ID_FTPD_RC=0
  ID_FTPD_RAW=""
  ID_FTPD_CLASS=""

  ID_FTPD_RAW=$(aix inetd_ftp_grep grep '^ftp[[:blank:]]' /etc/inetd.conf) # network-lint: allow -- aix() runs the LOCAL grep on /etc/inetd.conf capture text; no network call
  ID_FTPD_RC=$?

  # Classify a single matched line by its server-argument columns 6..10.
  # A -u flag paired with 027, or a single -u027 token, is compliant.
  if [ "$ID_FTPD_RC" -eq 0 ] && [ -n "$ID_FTPD_RAW" ]; then
    ID_FTPD_CLASS=$(printf '%s\n' "$ID_FTPD_RAW" | awk '
      {
        lines++
        if (lines == 1) {
          n = split($0, f, /[ \t]+/)
          for (i = 6; i <= 10; i++) {
            if (f[i] == "-u027") {
              good = 1
            } else if (f[i] == "-u") {
              if (f[i+1] == "027") {
                good = 1
              }
            }
          }
        }
      }
      END {
        if (lines == 0) {
          print "empty"
        } else if (lines > 1) {
          print "multiple"
        } else if (good) {
          print "pass"
        } else {
          print "fail"
        }
      }')
  fi

  # Compute verdict, then severity, then emit single finding.
  case "$ID_FTPD_RC" in
    0)
      if [ -z "$ID_FTPD_RAW" ]; then
        ID_FTPD_STATUS=NOT_ASSESSED
        ID_FTPD_OBSERVED="not assessed - ftp inetd probe rc=0 but output was empty after grep" # network-lint: allow -- prose finding text, no network call
        ID_FTPD_MEANING="PTxray did not obtain trustworthy ftp service-definition evidence." # network-lint: allow -- prose finding text, no network call
        ID_FTPD_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      else
        case "$ID_FTPD_CLASS" in
          pass)
            ID_FTPD_STATUS=PASS
            ID_FTPD_OBSERVED="ftp service in /etc/inetd.conf sets umask 027" # network-lint: allow -- prose finding text, no network call
            ID_FTPD_MEANING="The ftp daemon arguments set the file-creation umask to 027 as the control requires." # network-lint: allow -- prose finding text, no network call
            ID_FTPD_FIX="n/a"
            ;;
          fail)
            ID_FTPD_STATUS=FAIL
            ID_FTPD_OBSERVED="ftp service in /etc/inetd.conf does not set umask 027" # network-lint: allow -- prose finding text, no network call
            ID_FTPD_MEANING="The ftp daemon arguments either omit the -u flag or set a umask other than 027, so files it creates may be exposed to unintended access." # network-lint: allow -- prose finding text, no network call
            ID_FTPD_FIX="after service-owner approval, edit the ftp definition in /etc/inetd.conf to include -u 027 in the server arguments and refresh inetd; PTxray only recommends these actions." # network-lint: allow -- prose finding text, no network call
            ;;
          multiple)
            ID_FTPD_STATUS=NOT_ASSESSED
            ID_FTPD_OBSERVED="not assessed - ftp inetd probe matched more than one service line" # network-lint: allow -- prose finding text, no network call
            ID_FTPD_MEANING="PTxray did not obtain trustworthy ftp service-definition evidence." # network-lint: allow -- prose finding text, no network call
            ID_FTPD_FIX="inspect /etc/inetd.conf, resolve the duplicate-definition ambiguity, and rerun PTxray."
            ;;
          *)
            ID_FTPD_STATUS=NOT_ASSESSED
            ID_FTPD_OBSERVED="not assessed - ftp inetd probe output could not be classified" # network-lint: allow -- prose finding text, no network call
            ID_FTPD_MEANING="PTxray did not obtain trustworthy ftp service-definition evidence." # network-lint: allow -- prose finding text, no network call
            ID_FTPD_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
            ;;
        esac
      fi
      ;;
    1)
      if [ -z "$ID_FTPD_RAW" ]; then
        ID_FTPD_STATUS=NOT_APPLICABLE
        ID_FTPD_OBSERVED="ftp service not defined in /etc/inetd.conf" # network-lint: allow -- prose finding text, no network call
        ID_FTPD_MEANING="No ftp service definition exists, so there is no daemon umask to constrain." # network-lint: allow -- prose finding text, no network call
        ID_FTPD_FIX="n/a"
      else
        ID_FTPD_STATUS=NOT_ASSESSED
        ID_FTPD_OBSERVED="not assessed - ftp inetd probe rc=1 but output was non-empty (contradictory)" # network-lint: allow -- prose finding text, no network call
        ID_FTPD_MEANING="PTxray did not obtain trustworthy ftp service-definition evidence." # network-lint: allow -- prose finding text, no network call
        ID_FTPD_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      fi
      ;;
    *)
      ID_FTPD_STATUS=NOT_ASSESSED
      ID_FTPD_OBSERVED="not assessed - ftp inetd probe grep failed (rc=$ID_FTPD_RC)" # network-lint: allow -- prose finding text, no network call
      ID_FTPD_MEANING="PTxray did not obtain trustworthy ftp service-definition evidence." # network-lint: allow -- prose finding text, no network call
      ID_FTPD_FIX="inspect /etc/inetd.conf, resolve the read or shape problem, and rerun PTxray."
      ;;
  esac

  case "$ID_FTPD_STATUS" in
    FAIL) SEVERITY=high ;;
    *) SEVERITY=low ;;
  esac

  add security inetd_ftpd_umask "inetd ftpd umask" \
    "$ID_FTPD_STATUS" "$SEVERITY" \
    "$ID_FTPD_OBSERVED" \
    "$ID_FTPD_MEANING" \
    "$ID_FTPD_FIX" \
    "cis-l1"
  if [ "$ID_FTPD_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="grep '^ftp[[:blank:]]' /etc/inetd.conf" # network-lint: allow -- evidence display string for the LOCAL inetd.conf grep, no network call
  fi
_AIXRAY_SESSION_KEYS=""
  # sshd_version — assess whether the installed SSH daemon is major version 9+.
  typeset SSHV_RAW SSHV_RC SSHV_CUT SSHV_STATUS SSHV_SEVERITY
  typeset SSHV_OBSERVED SSHV_MEANING SSHV_FIX SSHV_REASON
  SSHV_STATUS=NOT_ASSESSED
  SSHV_SEVERITY=low
  SSHV_OBSERVED=''
  SSHV_MEANING='PTxray did not obtain one trustworthy parseable SSH daemon version, so it cannot establish whether the daemon is current.'
  SSHV_FIX='resolve why the SSH daemon version could not be read, then rerun PTxray.'
  SSHV_REASON=''

  # Probe via `sshd -V`, not `sshd -i`. Two defects made this check refuse on every
  # real box (both verified live on two lab LPARs, 2026-08-05):
  #   1. `sshd -i` is inetd server mode. With stdin on /dev/null it aborts rather
  #      than printing a version, exiting 255 -- so the check never reached a parse.
  #   2. `sshd -V` prints the version to STDERR, which aix() discards, so stderr
  #      must be preserved to see it at all.
  # Real output on both boxes: "OpenSSH_9.9p2, OpenSSL 3.0.16 11 Feb 2025".
  # Preserving stderr is what aixv() is for; the earlier `aix ... sh -c 'sshd -V
  # 2>&1'` open-coded the same merge through /bin/sh, which made the executed
  # command `sh` and the manifest's declared command a falsehood — an operator
  # reading it to approve the tool was told `sshd`, not "/bin/sh with an
  # embedded program". aixv does the identical 2>&1 in live mode, replays
  # <key>.out then <key>.err in fixture mode, and keeps the probe key, so the
  # captured evidence is unchanged.
  SSHV_RAW=$(aixv sshd_version sshd -V) # network-lint: allow -- `sshd -V` prints a version string and exits; it binds no socket and makes no network call
  SSHV_RC=$?

  # aix() returns 127 for BOTH a genuinely absent sshd and a fixture that never
  # captured sshd -V. Only the former is determinate non-applicability; a missing
  # capture is an honest refusal (round-3 D3).
  if aix_capture_missing sshd_version; then
    SSHV_STATUS=NOT_ASSESSED
    SSHV_OBSERVED='not assessed — sshd_version probe was not captured for this system'
    SSHV_MEANING='The sshd -V capture is absent from this scan fixture set, so PTxray cannot tell whether sshd is genuinely absent or merely unrecorded.'
    SSHV_FIX='capture sshd -V from a representative AIX host, then rerun PTxray.'
    SSHV_REASON='probe not captured'
  elif [ "$SSHV_RC" -eq 127 ]; then
    SSHV_STATUS=NOT_APPLICABLE
    SSHV_OBSERVED='sshd not installed'
    SSHV_MEANING='The SSH daemon is not installed, so no version requirement constrains software on this system.'
    SSHV_FIX='n/a'
  elif [ "$SSHV_RC" -ne 0 ]; then
    SSHV_REASON="sshd -V failed (rc=$SSHV_RC)"
  else
    # `cut -d _ -f 2` yielded "9.9p2," -- which this check's own numeric test then
    # rejected as non-numeric. Take the leading digits of the OpenSSH major version.
    SSHV_CUT=$(printf '%s\n' "$SSHV_RAW" | sed -n 's/^.*OpenSSH_\([0-9][0-9]*\).*$/\1/p' | head -1)
    case "$SSHV_CUT" in
      ''|*[!0-9]*)
        SSHV_REASON='version field is empty, non-numeric, or starts with a non-digit'
        ;;
      *)
        if [ "$SSHV_CUT" -ge 9 ]; then
          SSHV_STATUS=PASS
          SSHV_OBSERVED=$SSHV_CUT
          SSHV_MEANING="The SSH daemon is major version $SSHV_CUT, which is 9 or later."
          SSHV_FIX='n/a'
        else
          SSHV_STATUS=FAIL
          SSHV_SEVERITY=high
          SSHV_OBSERVED=$SSHV_CUT
          SSHV_MEANING="The SSH daemon is major version $SSHV_CUT, older than the required major version 9."
          SSHV_FIX='update the SSH daemon to major version 9 or later; PTxray only recommends these actions.'
        fi
        ;;
    esac
  fi

  if [ "$SSHV_STATUS" = NOT_ASSESSED ]; then
    SSHV_OBSERVED="not assessed — $SSHV_REASON"
  fi
  add security sshd_version "SSH daemon version currency" "$SSHV_STATUS" \
      "$SSHV_SEVERITY" "$SSHV_OBSERVED" "$SSHV_MEANING" "$SSHV_FIX" "cis-l1"
  if [ "$SSHV_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="sshd -V"
  fi
_AIXRAY_SESSION_KEYS=""
  # hosts_equiv_absent — assess absence of the host-based trust databases.
  # The compliant state is /etc/rhosts.equiv and /etc/shosts.equiv both absent.
  # The bracket glob is expanded by this check's own shell before the command
  # runs: a present file is listed (rc=0, non-empty), absence of both leaves the
  # literal path unresolvable (rc=2, empty). Read the paths exactly once; every
  # uncertain evidence shape fails closed.
  typeset HEQ_RAW HEQ_RC

  HEQ_RAW=$(aix hosts_equiv_files ls -l /etc/[rs]hosts.equiv)
  HEQ_RC=$?

  if [ "$HEQ_RC" -eq 0 ] && [ -n "$HEQ_RAW" ]; then
    add security hosts_equiv_absent "Host-based trust databases absent" FAIL med \
        "one or both of /etc/rhosts.equiv and /etc/shosts.equiv exist" \
        "A host-based trust database is present, granting host-equivalent access to accounts on this system without per-user credentials." \
        "remove both /etc/rhosts.equiv and /etc/shosts.equiv after confirming no workflow depends on host-based trust; PTxray only recommends this action." \
        "cis-l1 cis-l2"
  elif [ "$HEQ_RC" -eq 2 ] && [ -z "$HEQ_RAW" ]; then
    add security hosts_equiv_absent "Host-based trust databases absent" PASS med \
        "neither /etc/rhosts.equiv nor /etc/shosts.equiv exists" \
        "No host-based trust database is present; host-equivalent access cannot be granted through these files." \
        "n/a" "cis-l1 cis-l2"
  else
    add security hosts_equiv_absent "Host-based trust databases absent" NOT_ASSESSED med \
        "not assessed — probe failed (rc=$HEQ_RC)" \
        "PTxray did not obtain one trustworthy listing of /etc/rhosts.equiv and /etc/shosts.equiv, so their absence or presence could not be established." \
        "run 'ls -l /etc/[rs]hosts.equiv', correct the capture or path problem, and rerun PTxray." \
        "cis-l1 cis-l2"
  fi
_AIXRAY_SESSION_KEYS=""
  # ssh_sftp_args — assess the SFTP subsystem's enforced umask and logging
  # facility/level from the daemon's normalized effective configuration.
  typeset SSH_SFTP_AVAIL SSH_SFTP_AVAIL_RC SSH_SFTP_SUBSYS SSH_SFTP_SUBSYS_RC
  typeset SSH_SFTP_PARSE SSH_SFTP_STATUS SSH_SFTP_OBSERVED SSH_SFTP_MEANING SSH_SFTP_FIX SSH_SFTP_REASON
  SSH_SFTP_STATUS=NOT_ASSESSED
  SSH_SFTP_OBSERVED=''
  SSH_SFTP_MEANING='PTxray did not obtain one trustworthy effective SFTP subsystem line, so it cannot establish the SFTP umask and logging policy.'
  SSH_SFTP_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  SSH_SFTP_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    SSH_SFTP_REASON='requires root'
  else
    SSH_SFTP_AVAIL=$(aix sshd_available test -x /usr/sbin/sshd)
    SSH_SFTP_AVAIL_RC=$?
    # aix() returns 127 for BOTH a genuinely absent sshd and a fixture that
    # never captured this probe; the NOT_APPLICABLE arm below keys on "not
    # executable" and would otherwise launder a missing capture (round-3 D3).
    if aix_capture_missing sshd_available; then
      SSH_SFTP_STATUS=NOT_ASSESSED
      SSH_SFTP_OBSERVED='not assessed - sshd_available probe was not captured for this system'
      SSH_SFTP_REASON='probe not captured'
    elif [ "$SSH_SFTP_AVAIL_RC" -ne 0 ]; then
      SSH_SFTP_STATUS=NOT_APPLICABLE
      SSH_SFTP_OBSERVED='sshd is not installed, so no SFTP subsystem exists to constrain'
    else
      # The sshd -T capture is filtered with egrep AFTER the aix wrapper so the
      # wrapper's own exit status is not obscured by the pipe (evidence-gate lint).
      # A non-zero wrapper status -- including a missing capture -- is a refusal,
      # never a FAIL or NOT_APPLICABLE.
      SSH_SFTP_SUBSYS_RAW=$(aix sshd_sftp_subsystem /usr/sbin/sshd -T 2>/dev/null) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_SFTP_SUBSYS_RC=$?
      if [ "$SSH_SFTP_SUBSYS_RC" -eq 0 ]; then
        SSH_SFTP_SUBSYS=$(printf '%s\n' "$SSH_SFTP_SUBSYS_RAW" | grep -E -i '^subsystem[[:space:]]+sftp') # network-lint: allow -- LOCAL grep -E filter on the captured sshd -T output; no network call
        if [ -z "$SSH_SFTP_SUBSYS" ]; then
          SSH_SFTP_STATUS=FAIL
          SSH_SFTP_OBSERVED='sshd is present but the effective configuration carries no sftp subsystem line' # network-lint: allow -- prose finding text, no network call
        else
          # network-lint: allow-next=9 -- the awk program below compares the captured subsystem handler names; it parses local config text only, no network call
          SSH_SFTP_PARSE=$(printf '%s\n' "$SSH_SFTP_SUBSYS" | awk '
            {
              handler = $3
              n = split(handler, seg, "/")
              base = seg[n]
              args = ""
              for (i = 4; i <= NF; i++)
                args = args (args == "" ? "" : " ") $i
              if ((base == "sftp-server" || handler == "internal-sftp") &&
                  (args == "-u 027 -f AUTH -l INFO" ||
                   args == "-u 027 -f AUTH -l VERBOSE"))
                valid = 1
            }
            END {
              if (valid) print "VALID"
              else print "INVALID"
            }')
          case "$SSH_SFTP_PARSE" in
            VALID)
              SSH_SFTP_STATUS=PASS
              SSH_SFTP_OBSERVED="effective SFTP subsystem runs with '-u 027 -f AUTH -l INFO' or '-u 027 -f AUTH -l VERBOSE'"
              ;;
            *)
              SSH_SFTP_STATUS=FAIL
              SSH_SFTP_OBSERVED="effective SFTP subsystem line is present but its arguments are not '-u 027 -f AUTH -l INFO' or '-u 027 -f AUTH -l VERBOSE'"
              ;;
          esac
        fi
      else
        SSH_SFTP_REASON="sshd -T subsystem probe failed (rc=$SSH_SFTP_SUBSYS_RC)"
      fi
    fi
  fi

  if [ "$SSH_SFTP_STATUS" = NOT_ASSESSED ]; then
    SSH_SFTP_OBSERVED="not assessed - SFTP subsystem $SSH_SFTP_REASON"
  fi

  case "$SSH_SFTP_STATUS" in
    PASS)
      SSH_SFTP_MEANING='The effective SFTP subsystem enforces a restrictive umask and logs at INFO or VERBOSE to the AUTH facility, preserving security events.'
      SSH_SFTP_FIX='n/a'
      ;;
    FAIL)
      SSH_SFTP_MEANING='The effective SFTP subsystem does not enforce the required umask and logging policy, so transfers may be exposed or go unlogged.'
      SSH_SFTP_FIX="set the SFTP subsystem to run 'sftp-server' or 'internal-sftp' with '-u 027 -f AUTH -l INFO' (or VERBOSE) in sshd_config, validate with 'sshd -T', and restart sshd; PTxray only recommends these actions." # network-lint: allow -- prose finding text, no network call
      ;;
    NOT_APPLICABLE)
      SSH_SFTP_MEANING='sshd is not installed, so there is no SFTP subsystem to constrain.'
      SSH_SFTP_FIX='n/a'
      ;;
    *)
      SSH_SFTP_MEANING='PTxray did not obtain one trustworthy effective SFTP subsystem line, so it cannot establish the SFTP umask and logging policy.'
      SSH_SFTP_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
      ;;
  esac

  add security ssh_sftp_args "SSH SFTP subsystem arguments" "$SSH_SFTP_STATUS" med \
      "$SSH_SFTP_OBSERVED" "$SSH_SFTP_MEANING" "$SSH_SFTP_FIX" "cis-l1"
  if [ "$SSH_SFTP_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="test -x /usr/sbin/sshd"
  fi
_AIXRAY_SESSION_KEYS=""

  # ssh_access_lists — SSH user/group access-control lists from the effective
  # sshd configuration. The SSH daemon must restrict logins by user or group:
  # at least one of AllowUsers/AllowGroups/DenyUsers/DenyGroups must carry a
  # non-empty value. The check verifies presence only; it does not parse or
  # validate the contents of those lists against local site policy.
  typeset SSH_ACL_PKG SSH_ACL_PKG_RC SSH_ACL_PKG_ROW
  typeset SSH_ACL_SSHD_RAW SSH_ACL_SSHD_RC SSH_ACL_LINES SSH_ACL_DIRS
  typeset SSH_ACL_STATUS SSH_ACL_SEV SSH_ACL_OBSERVED SSH_ACL_MEANING SSH_ACL_FIX
  typeset SSH_ACL_REASON
  SSH_ACL_STATUS=NOT_ASSESSED
  SSH_ACL_SEV=low
  SSH_ACL_OBSERVED=''
  SSH_ACL_MEANING='PTxray did not obtain trustworthy effective sshd access-control evidence, so it cannot determine whether logins are restricted by user or group.'
  SSH_ACL_FIX='run sshd -T as root, resolve any configuration or capture error, and rerun PTxray.'
  SSH_ACL_REASON=''

  # 1. sshd package presence — an absent openssh.base.server fileset means the
  #    control constrains a daemon that does not exist on this host. Key on
  #    absence of the fileset row: lslpp -L always emits column headers and a
  #    legend, so empty data is a property of the inventory, not of the probe.
  SSH_ACL_PKG=$(aix sshd_package lslpp -L openssh.base.server)
  SSH_ACL_PKG_RC=$?
  SSH_ACL_PKG_ROW=$(printf '%s\n' "$SSH_ACL_PKG" | awk '
    $1 == "openssh.base.server" { found = 1 }
    END { print found + 0 }')
  # The NOT_APPLICABLE arm below keys on the ABSENCE of a fileset row in the
  # inventory, so a fixture that never captured sshd_package (rc=127, empty
  # output) would parse as "fileset absent" and launder a missing capture into a
  # clean verdict (round-3 D3). Rule that out before reading the row.
  if aix_capture_missing sshd_package; then
    SSH_ACL_STATUS=NOT_ASSESSED
    SSH_ACL_OBSERVED="not assessed - sshd_package probe was not captured for this system"
    SSH_ACL_MEANING="The lslpp -L openssh.base.server capture is absent from this scan fixture set, so PTxray cannot tell whether the fileset is genuinely absent or merely unrecorded."
    SSH_ACL_FIX="capture 'lslpp -L openssh.base.server' from a representative AIX host, then rerun PTxray."
    SSH_ACL_REASON='probe not captured'
  elif [ "$SSH_ACL_PKG_ROW" -eq 0 ]; then
    SSH_ACL_STATUS=NOT_APPLICABLE
    SSH_ACL_OBSERVED="openssh.base.server fileset absent from the package inventory"
    SSH_ACL_MEANING="The OpenSSH server fileset is not installed, so the SSH access-control requirement does not apply to this host."
    SSH_ACL_FIX='n/a'
  elif [ "$SSH_ACL_PKG_RC" -ne 0 ]; then
    SSH_ACL_REASON="lslpp returned the openssh.base.server row with rc=$SSH_ACL_PKG_RC"
  elif [ "${MYUID:-0}" != "0" ]; then
    SSH_ACL_REASON='requires root'
  else
    # 2. effective access-control directives. The monolith shares one sshd -T
    #    capture across all SSH checks; the standalone re-captures the same key.
    if [ "${SSHT_RC+x}" = x ]; then
      SSH_ACL_SSHD_RAW=$SSHT
      SSH_ACL_SSHD_RC=$SSHT_RC
    else
      SSH_ACL_SSHD_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_ACL_SSHD_RC=$?
    fi
    SSH_ACL_LINES=$(printf '%s\n' "$SSH_ACL_SSHD_RAW" |
      grep -E -i '^(AllowUsers|AllowGroups|DenyUsers|DenyGroups)[[:blank:]]')
    case "$SSH_ACL_SSHD_RC" in
      0)
        if [ -n "$SSH_ACL_LINES" ]; then
          SSH_ACL_DIRS=$(printf '%s\n' "$SSH_ACL_LINES" | awk '
            !seen[$1]++ { if (n++) list = list ", "; list = list $1 }
            END { print list }')
          SSH_ACL_STATUS=PASS
          SSH_ACL_OBSERVED="effective sshd configuration restricts access via: $SSH_ACL_DIRS"
          SSH_ACL_MEANING="The SSH daemon enforces login access control by user or group through at least one configured directive."
          SSH_ACL_FIX='n/a'
        else
          SSH_ACL_STATUS=FAIL
          SSH_ACL_SEV=med
          SSH_ACL_OBSERVED="no AllowUsers/AllowGroups/DenyUsers/DenyGroups directive in the effective sshd configuration"
          SSH_ACL_MEANING="The SSH daemon has no user-level or group-level access restriction configured, so the effective configuration does not constrain who may authenticate."
          SSH_ACL_FIX="configure at least one of AllowUsers, AllowGroups, DenyUsers, or DenyGroups with a non-empty value, validate sshd_config, and restart sshd; PTxray only recommends these actions."
        fi
        ;;
      *)
        SSH_ACL_REASON="sshd -T failed (rc=$SSH_ACL_SSHD_RC)"
        ;;
    esac
  fi

  if [ "$SSH_ACL_STATUS" = NOT_ASSESSED ]; then
    SSH_ACL_OBSERVED="not assessed — SSH access lists $SSH_ACL_REASON"
  fi
  add security ssh_access_lists "SSH user/group access lists" \
      "$SSH_ACL_STATUS" "$SSH_ACL_SEV" \
      "$SSH_ACL_OBSERVED" "$SSH_ACL_MEANING" "$SSH_ACL_FIX" "cis-l1"
  if [ "$SSH_ACL_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="lslpp -L openssh.base.server"
  fi
_AIXRAY_SESSION_KEYS=""
  # ssh_kexalgorithms — assess the global effective key-exchange list from `sshd -T`.
  typeset SSH_KEX_RAW SSH_KEX_CAPTURE_RC SSH_KEX_PARSED SSH_KEX_VALUE
  typeset SSH_KEX_BAD SSH_KEX_STATUS SSH_KEX_SEVERITY SSH_KEX_OBSERVED
  typeset SSH_KEX_MEANING SSH_KEX_FIX SSH_KEX_REASON
  SSH_KEX_STATUS=NOT_ASSESSED
  SSH_KEX_SEVERITY=high
  SSH_KEX_OBSERVED=''
  SSH_KEX_MEANING='PTxray did not obtain one trustworthy global effective key-exchange algorithm list, so it cannot establish that no deprecated SSH key-exchange algorithm is in use.'
  SSH_KEX_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  SSH_KEX_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    SSH_KEX_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      SSH_KEX_RAW=$SSHT
      SSH_KEX_CAPTURE_RC=$SSHT_RC
    else
      SSH_KEX_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_KEX_CAPTURE_RC=$?
    fi
    if [ "$SSH_KEX_CAPTURE_RC" -ne 0 ]; then
      SSH_KEX_REASON="sshd -T failed (rc=$SSH_KEX_CAPTURE_RC)"
    elif [ -z "$SSH_KEX_RAW" ]; then
      SSH_KEX_REASON='sshd -T returned empty output'
    else
      SSH_KEX_PARSED=$(printf '%s\n' "$SSH_KEX_RAW" | awk '
        $1 == "kexalgorithms" {
          count++
          if (NF != 2) invalid=1
          else value=$2
        }
        END {
          if (count == 0) print "__ABSENT__"
          else if (count > 1) print "__DUPLICATE__ " count
          else if (invalid) print "__INVALID__"
          else print value
        }')
      case "$SSH_KEX_PARSED" in
        __ABSENT__)
          SSH_KEX_REASON='directive is absent from the captured effective configuration, so the negotiated key-exchange set is unknown'
          ;;
        __DUPLICATE__*)
          SSH_KEX_REASON="directive appears ${SSH_KEX_PARSED#__DUPLICATE__ } times in the captured effective configuration, so the effective list is ambiguous and no single set can be read"
          ;;
        __INVALID__|''|+*|-*|^*|,*|*,|*,,*)
          SSH_KEX_REASON='effective value is unparseable'
          ;;
        *)
          SSH_KEX_VALUE=$SSH_KEX_PARSED
          SSH_KEX_BAD=$(printf '%s\n' "$SSH_KEX_VALUE" | awk -F, '
            BEGIN {
              bad["diffie-hellman-group1-sha1"]=1
              bad["diffie-hellman-group14-sha1"]=1
              bad["diffie-hellman-group-exchange-sha1"]=1
              sep=""
            }
            {
              for (i=1; i<=NF; i++) {
                member=$i
                sub(/^[+^-]/, "", member)
                if (member in bad) {
                  printf "%s%s", sep, $i
                  sep=","
                }
              }
            }
            END {
              if (sep != "") print ""
            }')
          if [ -n "$SSH_KEX_BAD" ]; then
            SSH_KEX_STATUS=FAIL
            SSH_KEX_OBSERVED="kexalgorithms $SSH_KEX_VALUE; barred member(s) $SSH_KEX_BAD"
            SSH_KEX_MEANING='The global effective SSH key-exchange list includes a deprecated algorithm, weakening key-exchange security.'
            SSH_KEX_FIX='remove the barred algorithm from the KexAlgorithms setting, validate it with sshd -T, and restart sshd; PTxray only recommends these actions.'
          else
            SSH_KEX_STATUS=PASS
            SSH_KEX_OBSERVED="kexalgorithms $SSH_KEX_VALUE"
            SSH_KEX_MEANING='The global effective SSH key-exchange list excludes the deprecated algorithms.'
            SSH_KEX_FIX='n/a'
          fi
          ;;
      esac
    fi
  fi

  if [ "$SSH_KEX_STATUS" = NOT_ASSESSED ]; then
    SSH_KEX_OBSERVED="not assessed — kexalgorithms $SSH_KEX_REASON"
  fi
  add security ssh_kexalgorithms "SSH key exchange algorithms" "$SSH_KEX_STATUS" "$SSH_KEX_SEVERITY" \
      "$SSH_KEX_OBSERVED" "$SSH_KEX_MEANING" "$SSH_KEX_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # ssh_permitemptypasswords — assess the global value normalized by `sshd -T`.
  typeset SSH_PEP_RAW SSH_PEP_CAPTURE_RC SSH_PEP_PARSED SSH_PEP_VALUE
  typeset SSH_PEP_STATUS SSH_PEP_SEVERITY SSH_PEP_OBSERVED SSH_PEP_MEANING SSH_PEP_FIX
  typeset SSH_PEP_REASON
  SSH_PEP_STATUS=NOT_ASSESSED
  SSH_PEP_SEVERITY=med
  SSH_PEP_OBSERVED=''
  SSH_PEP_MEANING='PTxray did not obtain one trustworthy global effective PermitEmptyPasswords value, so it cannot establish whether sshd rejects empty-password authentication.'
  SSH_PEP_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  SSH_PEP_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    SSH_PEP_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      SSH_PEP_RAW=$SSHT
      SSH_PEP_CAPTURE_RC=$SSHT_RC
    else
      SSH_PEP_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      SSH_PEP_CAPTURE_RC=$?
    fi
    if [ "$SSH_PEP_CAPTURE_RC" -ne 0 ]; then
      SSH_PEP_REASON="sshd -T failed (rc=$SSH_PEP_CAPTURE_RC)"
    elif [ -z "$SSH_PEP_RAW" ]; then
      SSH_PEP_REASON='sshd -T returned empty output'
    else
      SSH_PEP_PARSED=$(printf '%s\n' "$SSH_PEP_RAW" | awk '
        $1 == "permitemptypasswords" {
          count++
          if (NF != 2) invalid=1
          else if ($2 != "yes" && $2 != "no") invalid=1
          else value=$2
        }
        END {
          if (count != 1) print "__COUNT__"
          else if (invalid) print "__INVALID__"
          else print value
        }')
      case "$SSH_PEP_PARSED" in
        no)
          SSH_PEP_VALUE=no
          SSH_PEP_STATUS=PASS
          SSH_PEP_OBSERVED='PermitEmptyPasswords no'
          SSH_PEP_MEANING='sshd rejects password-less account logins; an account with no password cannot authenticate over SSH.'
          SSH_PEP_FIX='n/a'
          ;;
        yes)
          SSH_PEP_VALUE=yes
          SSH_PEP_STATUS=FAIL
          SSH_PEP_SEVERITY=high
          SSH_PEP_OBSERVED='PermitEmptyPasswords yes'
          SSH_PEP_MEANING='sshd permits accounts with empty passwords to log in, so any account left without a password is reachable without credentials.'
          SSH_PEP_FIX="set 'PermitEmptyPasswords no' in sshd_config, validate the global effective configuration with 'sshd -T', and restart sshd; PTxray only recommends these actions."
          ;;
        __COUNT__)
          SSH_PEP_REASON='effective row is missing or duplicate'
          ;;
        __INVALID__)
          SSH_PEP_REASON='effective value is unparseable'
          ;;
        *)
          SSH_PEP_REASON='effective value is unparseable'
          ;;
      esac
    fi
  fi

  if [ "$SSH_PEP_STATUS" = NOT_ASSESSED ]; then
    SSH_PEP_OBSERVED="not assessed — PermitEmptyPasswords $SSH_PEP_REASON"
  fi
  add security ssh_permitemptypasswords "SSH empty passwords" "$SSH_PEP_STATUS" "$SSH_PEP_SEVERITY" \
      "$SSH_PEP_OBSERVED" "$SSH_PEP_MEANING" "$SSH_PEP_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # ssh_permitrootlogin — assess the PermitRootLogin directive in /etc/ssh/sshd_config. # network-lint: allow -- prose header comment, no network call
  typeset SSH_PR_RAW SSH_PR_RC SSH_PR_LINES
  typeset SSH_PR_STATUS SSH_PR_SEV SSH_PR_OBSERVED SSH_PR_MEANING SSH_PR_FIX SSH_PR_REASON
  SSH_PR_STATUS=NOT_ASSESSED
  SSH_PR_SEV=low
  SSH_PR_OBSERVED=''
  SSH_PR_MEANING='PTxray did not obtain one unambiguous PermitRootLogin directive, so it cannot establish whether direct root login is refused.'
  SSH_PR_FIX='set PermitRootLogin to no in /etc/ssh/sshd_config; PTxray only recommends this action.' # network-lint: allow -- prose finding text, no network call
  SSH_PR_REASON=''

  SSH_PR_RAW=$(aix egrep_permitrootlogin /usr/bin/egrep "^PermitRootLogin" /etc/ssh/sshd_config) # network-lint: allow -- aix() runs the LOCAL egrep on sshd_config capture text; egrep makes no network call
  SSH_PR_RC=$?

  if [ -z "$SSH_PR_RAW" ]; then
    SSH_PR_LINES=0
  else
    SSH_PR_LINES=$(printf '%s\n' "$SSH_PR_RAW" | awk 'NF { n++ } END { print n+0 }')
  fi

  if [ "$SSH_PR_RC" -eq 0 ]; then
    case "$SSH_PR_LINES" in
      1)
        if [ "$SSH_PR_RAW" = "PermitRootLogin no" ]; then
          SSH_PR_STATUS=PASS
          SSH_PR_OBSERVED=$SSH_PR_RAW
          SSH_PR_MEANING='The SSH daemon is configured to refuse direct root login.'
          SSH_PR_FIX='n/a'
        else
          SSH_PR_STATUS=FAIL
          SSH_PR_SEV=high
          SSH_PR_OBSERVED=$SSH_PR_RAW
          SSH_PR_MEANING='A PermitRootLogin directive is present but its value is not no, so direct root login is not refused.'
          SSH_PR_FIX="set 'PermitRootLogin no' in /etc/ssh/sshd_config and restart sshd; PTxray only recommends this action." # network-lint: allow -- prose finding text, no network call
        fi
        ;;
      *)
        SSH_PR_REASON='duplicate or ambiguous PermitRootLogin directives'
        ;;
    esac
  elif [ "$SSH_PR_RC" -eq 1 ]; then
    SSH_PR_STATUS=FAIL
    SSH_PR_SEV=high
    SSH_PR_OBSERVED='PermitRootLogin not configured'
    SSH_PR_MEANING='No uncommented PermitRootLogin directive is present; the OpenSSH default does not refuse direct root login.'
    SSH_PR_FIX="set 'PermitRootLogin no' in /etc/ssh/sshd_config and restart sshd; PTxray only recommends this action." # network-lint: allow -- prose finding text, no network call
  elif [ "$SSH_PR_RC" -eq 2 ]; then
    SSH_PR_STATUS=NOT_APPLICABLE
    SSH_PR_OBSERVED='sshd_config absent'
    SSH_PR_MEANING='No /etc/ssh/sshd_config is present, so there is no SSH server configuration to constrain.' # network-lint: allow -- prose finding text, no network call
    SSH_PR_FIX='n/a'
  else
    SSH_PR_REASON="unexpected egrep rc ($SSH_PR_RC)"
  fi

  if [ "$SSH_PR_STATUS" = NOT_ASSESSED ]; then
    SSH_PR_OBSERVED="not assessed — PermitRootLogin $SSH_PR_REASON"
  fi
  add security ssh_permitrootlogin "SSH PermitRootLogin" "$SSH_PR_STATUS" "$SSH_PR_SEV" \
      "$SSH_PR_OBSERVED" "$SSH_PR_MEANING" "$SSH_PR_FIX" "cis-l2"
_AIXRAY_SESSION_KEYS=""

  # ssh_rekeylimit — assess the global effective rekeylimit normalized by `sshd -T`.
  typeset RKL_RAW RKL_CAPTURE_RC RKL_PARSED RKL_STATUS RKL_SEVERITY
  typeset RKL_OBSERVED RKL_MEANING RKL_FIX RKL_REASON
  RKL_STATUS=NOT_ASSESSED
  RKL_SEVERITY=med
  RKL_OBSERVED=''
  RKL_MEANING='PTxray did not obtain one trustworthy global effective rekeylimit value, so it cannot establish the session-key renegotiation boundary.'
  RKL_FIX='run sshd -T as root, resolve any configuration or host-key error, and rerun PTxray.'
  RKL_REASON=''

  if [ "${MYUID:-0}" != "0" ]; then
    RKL_REASON='requires root'
  else
    if [ "${SSHT_RC+x}" = x ]; then
      RKL_RAW=$SSHT
      RKL_CAPTURE_RC=$SSHT_RC
    else
      RKL_RAW=$(aix sshd_T sshd -T) # network-lint: allow -- reads sshd's LOCAL effective configuration; sshd -T does not make a network call
      RKL_CAPTURE_RC=$?
    fi
    if [ "$RKL_CAPTURE_RC" -ne 0 ]; then
      RKL_REASON="sshd -T failed (rc=$RKL_CAPTURE_RC)"
    elif [ -z "$RKL_RAW" ]; then
      RKL_REASON='sshd -T returned empty output'
    else
