        FSC_REASON="capture failed (rc=$FSC_RC): $FSC_DIAG"
      fi
    fi
  elif [ -z "$FSC_RAW" ]; then
    FSC_REASON="empty"
  else
    # network-lint: allow-next=21 -- the awk program below compares the captured ls pathname to the mailer config file; it parses local capture text only, no network call
    FSC_PARSED=$(printf '%s\n' "$FSC_RAW" | awk '
      NF {
        records++
        if (records != 1 || NF != 9) { bad=1; next }
        mode=$1
        if (length("" mode) != 10) bad=1
        if (substr(mode,1,1) !~ /^[-dlbcps]$/) bad=1
        if (substr(mode,2,1) !~ /^[-r]$/) bad=1
        if (substr(mode,3,1) !~ /^[-w]$/) bad=1
        if (substr(mode,4,1) !~ /^[-xSs]$/) bad=1
        if (substr(mode,5,1) !~ /^[-r]$/) bad=1
        if (substr(mode,6,1) !~ /^[-w]$/) bad=1
        if (substr(mode,7,1) !~ /^[-xSs]$/) bad=1
        if (substr(mode,8,1) !~ /^[-r]$/) bad=1
        if (substr(mode,9,1) !~ /^[-w]$/) bad=1
        if (substr(mode,10,1) !~ /^[-xTt]$/) bad=1
        if ($2 !~ /^[0-9][0-9]*$/) bad=1
        if (length("" $3) < 1) bad=1
        if (length("" $4) < 1) bad=1
        if ($5 !~ /^[0-9][0-9]*$/) bad=1
        if ($NF != "/etc/mail/sendmail.cf") bad=1
      }
      END {
        if (records != 1 || bad) exit 1
        print mode "|" $3 "|" $4
      }
    ')
    FSC_PARSE_RC=$?
    if [ "$FSC_PARSE_RC" -ne 0 ] || [ -z "$FSC_PARSED" ]; then
      FSC_REASON="unparseable"
    else
      FSC_MODE=${FSC_PARSED%%\|*}
      FSC_REST=${FSC_PARSED#*\|}
      FSC_OWNER=${FSC_REST%%\|*}
      FSC_GROUP=${FSC_REST#*\|}
    fi
