  if [ "$FSC_REASON" = "absent" ]; then
    # network-lint: allow-next=3 -- NOT_APPLICABLE finding label and prose name the mailer config file; the add command emits a finding, no network call
    add security fileperm_sendmailcf "sendmail.cf owner/group/mode" NOT_APPLICABLE med \
        "/etc/mail/sendmail.cf absent" \
        "The probe returned the determinate-absence signature ('/etc/mail/sendmail.cf not found', exit $FSC_RC); sendmail need not be installed and the owner/group/mode requirement does not apply." \
        "n/a" "cis-l1"
  elif [ -n "$FSC_REASON" ]; then
