          "/etc/mail/sendmail.cf is owned by root:system with mode -rw-r----- as required." \
          "n/a" "cis-l1"
    else
      FSC_BAD=""
      if [ "$FSC_MODE" != "-rw-r-----" ]; then FSC_BAD="mode"; fi
      if [ "$FSC_OWNER" != "root" ]; then FSC_BAD="${FSC_BAD:+$FSC_BAD }owner"; fi
      if [ "$FSC_GROUP" != "system" ]; then FSC_BAD="${FSC_BAD:+$FSC_BAD }group"; fi
      FSC_OBSERVED="$FSC_OBSERVED; requires -rw-r----- root:system; deviates: $FSC_BAD"
      # network-lint: allow-next=4 -- FAIL finding prose and remediation name the mailer config file; no network call
      add security fileperm_sendmailcf "sendmail.cf owner/group/mode" FAIL med \
          "$FSC_OBSERVED" \
          "/etc/mail/sendmail.cf deviates from the required root:system owner/group and -rw-r----- mode boundary and could let an unintended identity alter trusted mail configuration." \
