  typeset CK_MODE CK_OWNER CK_GROUP CK_REMAIN CK_DIVERGED CK_REMEDIATE

  CK_RAW=$(aix diracc_clientmqueue_ls ls -ld /var/spool/clientmqueue)
  CK_RC=$?

  if [ "$CK_RC" -eq 2 ] && [ -z "$CK_RAW" ]; then
    add security diracc_clientmqueue "/var/spool/clientmqueue access" NOT_APPLICABLE med \
        "path absent" \
        "/var/spool/clientmqueue does not exist, so there is no directory access state to constrain." \
        "n/a" "cis-l1"
  elif [ "$CK_RC" -ne 0 ]; then
    add security diracc_clientmqueue "/var/spool/clientmqueue access" NOT_ASSESSED med \
        "probe failed (rc=$CK_RC)" \
        "PTxray did not obtain a trustworthy ls record, so it cannot claim the directory access boundary is satisfied." \
        "run 'ls -ld /var/spool/clientmqueue', correct the capture or path problem, and rerun PTxray." "cis-l1"
  elif [ -z "$CK_RAW" ]; then
    add security diracc_clientmqueue "/var/spool/clientmqueue access" NOT_ASSESSED med \
        "probe returned no output" \
        "PTxray did not obtain a trustworthy ls record, so it cannot claim the directory access boundary is satisfied." \
        "run 'ls -ld /var/spool/clientmqueue' and confirm the path state, then rerun PTxray." "cis-l1"
  else
    CK_REC=$(printf '%s\n' "$CK_RAW" | awk '{print $1 " " $3 " " $4 " " $9}')
    if [ "$CK_REC" = "drwxrwx--- smmsp smmsp /var/spool/clientmqueue" ]; then
      add security diracc_clientmqueue "/var/spool/clientmqueue access" PASS med \
          "mode=drwxrwx--- owner=smmsp group=smmsp" \
          "/var/spool/clientmqueue has the required directory access boundary." \
          "n/a" "cis-l1"
    else
      CK_VALID=$(printf '%s\n' "$CK_REC" | awk '
        {
          records++
          if (records > 1) exit 1
          if (NF != 4) exit 1
          mode=$1
          if (length("" mode) == 11 && substr(mode, 11, 1) == "+") mode=substr(mode, 1, 10)
          if (length("" mode) != 10 || substr(mode, 1, 1) != "d") exit 1
          if (length($2) < 1 || length($3) < 1) exit 1
          if ($4 != "/var/spool/clientmqueue") exit 1
          print $1 "|" $2 "|" $3
        }
        END { if (records != 1) exit 1 }
