      CK_VALID_RC=$?
      if [ "$CK_VALID_RC" -ne 0 ] || [ -z "$CK_VALID" ]; then
        add security diracc_clientmqueue "/var/spool/clientmqueue access" NOT_ASSESSED med \
            "ls output unparseable" \
            "PTxray did not obtain one trustworthy metadata row, so it cannot claim the directory access boundary is satisfied." \
            "run 'ls -ld /var/spool/clientmqueue', correct the capture or path problem, and rerun PTxray." "cis-l1"
      else
        CK_MODE=${CK_VALID%%\|*}
        CK_REMAIN=${CK_VALID#*\|}
        CK_OWNER=${CK_REMAIN%%\|*}
        CK_GROUP=${CK_REMAIN#*\|}
        CK_DIVERGED=""
        if [ "$CK_MODE" != "drwxrwx---" ]; then CK_DIVERGED="permissions"; fi
        if [ "$CK_OWNER" != "smmsp" ]; then
          if [ -n "$CK_DIVERGED" ]; then CK_DIVERGED="$CK_DIVERGED, owner"; else CK_DIVERGED="owner"; fi
        fi
        if [ "$CK_GROUP" != "smmsp" ]; then
          if [ -n "$CK_DIVERGED" ]; then CK_DIVERGED="$CK_DIVERGED, group"; else CK_DIVERGED="group"; fi
        fi
        CK_REMEDIATE=""
        if [ "$CK_MODE" != "drwxrwx---" ]; then CK_REMEDIATE="chmod 770 /var/spool/clientmqueue"; fi
        if [ "$CK_OWNER" != "smmsp" ] || [ "$CK_GROUP" != "smmsp" ]; then
          if [ -n "$CK_REMEDIATE" ]; then CK_REMEDIATE="$CK_REMEDIATE; "; fi
          CK_REMEDIATE="${CK_REMEDIATE}chown smmsp:smmsp /var/spool/clientmqueue"
