_AIXRAY_SESSION_KEYS=""
  # diracc_mqueue — /var/spool/mqueue presence, ownership, and mode boundary.
  # CIS L1 mapping 4.6.4.5: the directory must exist, be owned by root:system,
  # and carry mode 0700 (drwx------); any other mode, owner, or group is
  # non-compliant, and absence is non-compliance rather than inapplicability.
  typeset DQM_RAW DQM_RC DQM_SHAPE DQM_DETAIL DQM_MODE DQM_OWNER DQM_GROUP
  typeset DQM_OWNER_REST DQM_STATUS DQM_SEV DQM_OBSERVED DQM_MEANING DQM_FIX DQM_BAD

  DQM_RAW=$(aix var_spool_mqueue_ls ls -ld /var/spool/mqueue)
  DQM_RC=$?
  DQM_SHAPE=""; DQM_STATUS=""; DQM_SEV=""; DQM_OBSERVED=""; DQM_MEANING=""; DQM_FIX=""

