    DQM_SEV=low
    DQM_OBSERVED="not assessed - probe of /var/spool/mqueue metadata failed (rc=$DQM_RC); the directory state is unknown"
  else
    DQM_SHAPE=$(printf '%s\n' "$DQM_RAW" | awk '
      /^[ \t]*$/ { next }
      {
        rows++
        if (rows > 1) next
        if (NF != 9) next
        mode = $1
        owner = $3
        group = $4
        if ($NF != "/var/spool/mqueue") { shape = "foreign"; next }
        if (length("" mode) == 0) next
        if (mode != "drwx------") { shape = "viol|" mode "|" owner "|" group; next }
        if (owner != "root") { shape = "viol|" mode "|" owner "|" group; next }
        if (group != "system") { shape = "viol|" mode "|" owner "|" group; next }
        shape = "ok"
