        DQM_GROUP=${DQM_DETAIL##*\|}
        DQM_STATUS=FAIL
        DQM_SEV=high
        DQM_BAD=""
        if [ "$DQM_MODE" != "drwx------" ]; then DQM_BAD="mode"; fi
        if [ "$DQM_OWNER" != "root" ]; then DQM_BAD="${DQM_BAD:+$DQM_BAD }owner"; fi
        if [ "$DQM_GROUP" != "system" ]; then DQM_BAD="${DQM_BAD:+$DQM_BAD }group"; fi
