  add security diracc_mqueue "/var/spool/mqueue mode and ownership" \
    "$DQM_STATUS" "$DQM_SEV" "$DQM_OBSERVED" \
    "$DQM_MEANING" "$DQM_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # shell_timeout_readonly — verify TMOUT/TIMEOUT are bounded and readonly.
  # The probe reads /etc/profile (the file the CIS standard's Remediation
  # section names) and keeps every line matching TMOUT or TIMEOUT.  It reads
  # the file, not the scanner's own shell: the scanner runs as a
  # non-interactive, non-login ksh that never sources /etc/profile, so the
  # readonly attribute configured there is simply absent from the scanner's
  # shell.  On a compliant system /etc/profile carries bounded numeric
  # assignments for both variables and a readonly declaration that covers
  # both and appears after the assignments, per the standard text.
  typeset STR_RAW STR_RC STR_PARSED STR_STATE STR_REST
  typeset STR_TMO_CLS STR_TMO_VAL STR_TO_CLS STR_TO_VAL STR_MISSING STR_TMP STR_BAD
  STR_RAW=$(aix shell_timeout_readonly grep -E 'TMOUT|TIMEOUT' /etc/profile); STR_RC=$?
  if [ "$STR_RC" -ge 2 ]; then
    add security shell_timeout_readonly "Interactive shell inactivity timeout" \
        NOT_ASSESSED low \
        "not assessed — /etc/profile TMOUT/TIMEOUT capture failed (rc=$STR_RC)" \
        "Could not read TMOUT/TIMEOUT evidence from /etc/profile, so idle-shell readonly-timeout enforcement is unknown." \
        "restore read access to /etc/profile, then rerun PTxray." "cis-l2"
  elif [ "$STR_RC" -eq 1 ]; then
    add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
        "no TMOUT, TIMEOUT, or readonly declaration in /etc/profile (grep rc=1)" \
        "No idle-shell timeout is enforced; interactive shell sessions can remain open indefinitely." \
        "set TMOUT=900, TIMEOUT=900, and readonly TMOUT TIMEOUT in /etc/profile, then rerun PTxray." "cis-l2"
  else
    # Parse assignments and readonly declarations.  Comments are stripped;
    # inline trailing shell comments are removed from values.  Assignment
    # ordering matters: the standard requires the readonly statement to be
    # the last statement among these lines, so an assignment that appears
    # after a readonly declaration is an ordering violation.  A readonly or
    # typeset -r declaration may carry its own assignments (for example
    # "readonly TMOUT=900"), which are parsed and also mark the variable
    # readonly.  A line that does not name TMOUT or TIMEOUT as the exact
    # variable being set or declared is neighbour noise (for example
    # LOGIN_TIMEOUT=60) and never voids determinate evidence.
    STR_PARSED=$(printf '%s\n' "$STR_RAW" | awk '
      function trim(s) {
        sub(/^[ \t]+/, "", s)
        sub(/[ \t]+$/, "", s)
        return s
      }
      function strip_quotes(v,   q) {
        q = sprintf("%c", 39)
        if (v ~ /^"[^"]*"$/) v = substr(v, 2, length("" v) - 2)
        else if (length("" v) >= 2 && substr(v, 1, 1) == q && substr(v, length("" v), 1) == q) v = substr(v, 2, length("" v) - 2)
        return v
      }
      function classify(val,   canon) {
        val = strip_quotes(val)
        if (val == "") return "empty"
        if (val !~ /^[0-9]+$/) return "nonnum"
        canon = val
        sub(/^0+/, "", canon)
        if (canon == "") return "zero"
        if (length("" canon) > 3) return "over"
        if (canon + 0 > 900) return "over"
        return "ok"
      }
      function record_assign(name, raw,   sep, suffix) {
        sep = index(raw, ";")
        if (sep > 0) {
          suffix = substr(raw, sep + 1)
          suffix = trim(suffix)
          raw = substr(raw, 1, sep - 1)
          raw = trim(raw)
          gsub(/[ \t]+/, " ", suffix)
          if (suffix != "" && suffix != "export " name) { malformed = 1; return }
        }
        raw = trim(raw)
        raw = strip_quotes(raw)
        raw = trim(raw)
        if (name == "TMOUT") {
          if (tmo_seen && tmo_val != raw) { tmo_conflict = 1 }
          tmo_seen = 1; tmo_val = raw; tmo_cls = classify(raw)
        } else if (name == "TIMEOUT") {
          if (tmoout_seen && tmoout_val != raw) { tmoout_conflict = 1 }
          tmoout_seen = 1; tmoout_val = raw; tmoout_cls = classify(raw)
        }
      }
      function parse_ro_operand(tok,   nm, vv, hit) {
        hit = 0
        if (tok ~ /^(TMOUT|TIMEOUT)[ \t]*=/) {
          nm = tok
          sub(/[=].*/, "", nm)
          sub(/[ \t]+$/, "", nm)
          vv = tok
          sub(/^[^=]*=/, "", vv)
          if (nm == "TMOUT") { tmo_readonly = 1; hit = 1 }
          else if (nm == "TIMEOUT") { tmoout_readonly = 1; hit = 1 }
          record_assign(nm, vv)
        } else {
          # Bare operand: tolerate a trailing statement terminator ("TMOUT;"
          # on "readonly TMOUT;").  Assignments keep their semicolons for
          # record_assign, which owns the separator handling.
          sub(/;+$/, "", tok)
          if (tok == "TMOUT") { tmo_readonly = 1; hit = 1 }
          else if (tok == "TIMEOUT") { tmoout_readonly = 1; hit = 1 }
        }
        return hit
      }
      {
        line = $0
        sub(/^[ \t]+/, "", line)
        if (line ~ /^#/) next
        sub(/[ \t]+#.*/, "", line)
        line = trim(line)
        if (line == "") next

        # readonly declaration — names and/or assigns one or both variables.
        if (line ~ /^readonly[ \t]/) {
          work = line
          sub(/^readonly[ \t]+/, "", work)
          n = split(work, tok, /[ \t]+/)
          for (i = 1; i <= n; i++) {
            if (tok[i] == "") continue
            if (parse_ro_operand(tok[i])) readonly_seen = 1
          }
          next
        }

        # typeset with a -r flag is the ksh88 spelling of readonly.
        if (line ~ /^typeset[ \t]+-/) {
          work = line
          sub(/^typeset[ \t]+/, "", work)
          flags = work
          sub(/[ \t].*/, "", flags)
          if (substr(flags, 1, 1) == "-" && flags ~ /r/) {
            rest = work
            sub(/^[^ \t]+[ \t]+/, "", rest)
            n = split(rest, tok, /[ \t]+/)
            for (i = 1; i <= n; i++) {
              if (tok[i] == "") continue
              if (parse_ro_operand(tok[i])) readonly_seen = 1
            }
          } else if (line ~ /(^|[^A-Za-z0-9_])(TMOUT|TIMEOUT)([^A-Za-z0-9_]|$)/) {
            malformed = 1
          }
          next
        }

        # Bare export of TMOUT and/or TIMEOUT — declares the export, assigns no value.
        if (line ~ /^export[ \t]+/) {
          work = line
          sub(/^export[ \t]+/, "", work)
          n = split(work, tok, /[ \t]+/)
          all_ok = 1
          for (i = 1; i <= n; i++) {
            if (tok[i] == "") continue
            if (tok[i] != "TMOUT" && tok[i] != "TIMEOUT") { all_ok = 0; break }
          }
          if (all_ok) next
        }

        # Assignment: optional export prefix, variable name, equal sign, value.
        # The bracket class in the sub regex defeats the AIX awk /= lexer trap.
        if (line ~ /^(export[ \t]+)?(TMOUT|TIMEOUT)[ \t]*=/) {
          if (readonly_seen) order_bad = 1
          name = line
          sub(/[=].*/, "", name)
          sub(/^export[ \t]+/, "", name)
          name = trim(name)
          val = line
          sub(/^[^=]*=/, "", val)
          record_assign(name, val)
          next
        }

        # Unrecognised line.  If it names TMOUT or TIMEOUT as the exact variable
        # being set or declared, the evidence is malformed (refusal).  Otherwise
        # it is neighbour noise (for example LOGIN_TIMEOUT=60) and must not void
        # determinate TMOUT/TIMEOUT evidence.
        if (line ~ /(^|[^A-Za-z0-9_])(TMOUT|TIMEOUT)([^A-Za-z0-9_]|$)/) malformed = 1
      }
      END {
        if (malformed) print "malformed|"
        else if (tmo_conflict || tmoout_conflict) print "value_conflict|"
        else if (!tmo_seen && !tmoout_seen) print "absent|"
        else if (tmo_seen && !tmoout_seen) print "missing|TIMEOUT"
        else if (!tmo_seen && tmoout_seen) print "missing|TMOUT"
        else if (!readonly_seen) print "no_readonly|" tmo_cls "|" tmo_val "|" tmoout_cls "|" tmoout_val
        else if (tmo_readonly && !tmoout_readonly) print "partial_readonly|TIMEOUT|" tmo_cls "|" tmo_val "|" tmoout_cls "|" tmoout_val
        else if (!tmo_readonly && tmoout_readonly) print "partial_readonly|TMOUT|" tmo_cls "|" tmo_val "|" tmoout_cls "|" tmoout_val
        else if (order_bad) print "order|" tmo_cls "|" tmo_val "|" tmoout_cls "|" tmoout_val
        else print "both|" tmo_cls "|" tmo_val "|" tmoout_cls "|" tmoout_val
      }
    ')
    STR_STATE=${STR_PARSED%%\|*}
    STR_REST=${STR_PARSED#*\|}
    case "$STR_STATE" in
      malformed)
        add security shell_timeout_readonly "Interactive shell inactivity timeout" \
            NOT_ASSESSED low \
            "not assessed — /etc/profile TMOUT/TIMEOUT lines are not parseable" \
            "PTxray found lines matching TMOUT/TIMEOUT in /etc/profile but none parse as an assignment or readonly declaration, so timeout enforcement cannot be established." \
            "inspect TMOUT/TIMEOUT lines in /etc/profile, correct malformed entries, and rerun PTxray." "cis-l2"
        ;;
      value_conflict)
        add security shell_timeout_readonly "Interactive shell inactivity timeout" \
            NOT_ASSESSED low \
            "not assessed — conflicting assignments for the same variable in /etc/profile" \
            "PTxray observed different values assigned to TMOUT or TIMEOUT across multiple lines in /etc/profile; the effective value cannot be determined from grep output alone." \
            "consolidate TMOUT and TIMEOUT to one assignment each in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      absent)
        add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
            "no active TMOUT or TIMEOUT assignment in /etc/profile" \
            "No idle-shell timeout is enforced; interactive shell sessions can remain open indefinitely." \
            "set TMOUT=900, TIMEOUT=900, and readonly TMOUT TIMEOUT in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      missing)
        STR_MISSING=$STR_REST
        add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
            "$STR_MISSING is not configured in /etc/profile; both TMOUT and TIMEOUT must be set" \
            "Only one timeout variable is configured in /etc/profile; both are required by the standard." \
            "add a $STR_MISSING assignment (1–900) and a readonly declaration covering both variables in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      no_readonly)
        STR_TMO_CLS=${STR_REST%%\|*}
        STR_TMP=${STR_REST#*\|}
        STR_TMO_VAL=${STR_TMP%%\|*}
        STR_TMP=${STR_TMP#*\|}
        STR_TO_CLS=${STR_TMP%%\|*}
        STR_TO_VAL=${STR_TMP#*\|}
        add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
            "TMOUT and TIMEOUT are set but not readonly; the interactive user can alter or unset them" \
            "Without readonly, an interactive user can change or unset the timeout, defeating the inactivity lock." \
            "add \"readonly TMOUT TIMEOUT\" as the last relevant statement in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      partial_readonly)
        STR_MISSING=${STR_REST%%\|*}
        STR_TMP=${STR_REST#*\|}
        STR_TMO_CLS=${STR_TMP%%\|*}
        STR_TMP=${STR_TMP#*\|}
        STR_TMO_VAL=${STR_TMP%%\|*}
        STR_TMP=${STR_TMP#*\|}
        STR_TO_CLS=${STR_TMP%%\|*}
        STR_TO_VAL=${STR_TMP#*\|}
        add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
            "$STR_MISSING is not readonly; both TMOUT and TIMEOUT must be readonly" \
            "Only one timeout variable carries the readonly marker; the other can still be altered or unset by the interactive user." \
            "add $STR_MISSING to the readonly declaration in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      order)
        STR_TMO_CLS=${STR_REST%%\|*}
        STR_TMP=${STR_REST#*\|}
        STR_TMO_VAL=${STR_TMP%%\|*}
        STR_TMP=${STR_TMP#*\|}
        STR_TO_CLS=${STR_TMP%%\|*}
        STR_TO_VAL=${STR_TMP#*\|}
        add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
            "readonly declaration precedes TMOUT/TIMEOUT assignment; the standard requires readonly to be the last statement" \
            "A readonly declaration that appears before an assignment line is ineffective: the later assignment would fail at shell parse time, or the readonly would not cover it." \
            "move \"readonly TMOUT TIMEOUT\" to be the last statement among the timeout lines in /etc/profile, then rerun PTxray." "cis-l2"
        ;;
      both)
        STR_TMO_CLS=${STR_REST%%\|*}
        STR_TMP=${STR_REST#*\|}
        STR_TMO_VAL=${STR_TMP%%\|*}
        STR_TMP=${STR_TMP#*\|}
        STR_TO_CLS=${STR_TMP%%\|*}
        STR_TO_VAL=${STR_TMP#*\|}
        if [ "$STR_TMO_CLS" = over ] || [ "$STR_TO_CLS" = over ]; then
          STR_BAD=""
          if [ "$STR_TMO_CLS" = over ]; then STR_BAD="TMOUT=${STR_TMO_VAL}"; fi
          if [ "$STR_TO_CLS" = over ]; then
            if [ -n "$STR_BAD" ]; then STR_BAD="${STR_BAD} and TIMEOUT=${STR_TO_VAL}"; else STR_BAD="TIMEOUT=${STR_TO_VAL}"; fi
          fi
          add security shell_timeout_readonly "Interactive shell inactivity timeout" WARN low \
              "${STR_BAD} above the 900-second cap" \
              "A readonly timeout above 900 seconds still leaves an idle session open for an excessive period." \
              "lower TMOUT and TIMEOUT to 900 seconds or less, keep both readonly, and rerun PTxray." "cis-l2"
        elif [ "$STR_TMO_CLS" = empty ] || [ "$STR_TMO_CLS" = nonnum ] || [ "$STR_TMO_CLS" = zero ] ||
             [ "$STR_TO_CLS" = empty ] || [ "$STR_TO_CLS" = nonnum ] || [ "$STR_TO_CLS" = zero ]; then
          STR_BAD=""
          if [ "$STR_TMO_CLS" = empty ]; then STR_BAD="TMOUT has no value"
          elif [ "$STR_TMO_CLS" = zero ]; then STR_BAD="TMOUT=0"
          elif [ "$STR_TMO_CLS" = nonnum ]; then STR_BAD="TMOUT is not a positive integer"
          fi
          if [ "$STR_TO_CLS" = empty ]; then
            if [ -n "$STR_BAD" ]; then STR_BAD="${STR_BAD} and TIMEOUT has no value"; else STR_BAD="TIMEOUT has no value"; fi
          elif [ "$STR_TO_CLS" = zero ]; then
            if [ -n "$STR_BAD" ]; then STR_BAD="${STR_BAD} and TIMEOUT=0"; else STR_BAD="TIMEOUT=0"; fi
          elif [ "$STR_TO_CLS" = nonnum ]; then
            if [ -n "$STR_BAD" ]; then STR_BAD="${STR_BAD} and TIMEOUT is not a positive integer"; else STR_BAD="TIMEOUT is not a positive integer"; fi
          fi
          add security shell_timeout_readonly "Interactive shell inactivity timeout" FAIL high \
              "${STR_BAD}; idle-shell auto-logout is disabled or unreadable" \
              "A zero, empty, or non-numeric timeout value breaks the enforced inactivity logout even when readonly is set." \
              "set TMOUT and TIMEOUT to a positive integer from 1 through 900, keep both readonly, and rerun PTxray." "cis-l2"
        else
          add security shell_timeout_readonly "Interactive shell inactivity timeout" PASS low \
              "TMOUT=${STR_TMO_VAL} and TIMEOUT=${STR_TO_VAL}, both readonly" \
              "Both timeout variables are readonly with a bounded positive value, so an idle interactive shell auto-logs out." \
              "n/a" "cis-l2"
        fi
        ;;
      *)
        add security shell_timeout_readonly "Interactive shell inactivity timeout" \
            NOT_ASSESSED low \
            "not assessed — /etc/profile TMOUT/TIMEOUT parse returned unrecognised state" \
            "The parsed TMOUT/TIMEOUT evidence from /etc/profile did not map to a known shape, so timeout enforcement is unknown." \
            "inspect /etc/profile TMOUT/TIMEOUT configuration and rerun PTxray." "cis-l2"
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""

  # root_su_restrict — root must reject direct login (console and remote)
  # and must not leave su open to every group. Reads four lsuser attributes
  # in one self-contained capture; no root privilege is required.
  typeset ROOT_SU_RAW ROOT_SU_RC ROOT_SU_PARSED ROOT_SU_TAB ROOT_SU_SHAPE
  typeset ROOT_SU_LOGIN ROOT_SU_RLOGIN ROOT_SU_SU ROOT_SU_SUGROUPS ROOT_SU_VALUE
  ROOT_SU_RAW=$(aix root_su_restrict lsuser -a login rlogin su sugroups root)
  ROOT_SU_RC=$?
  if [ "$ROOT_SU_RC" -ne 0 ]; then
    add security root_su_restrict "Root login and su restrictions" NOT_ASSESSED high \
        "not assessed — lsuser returned exit code $ROOT_SU_RC" \
        "PTxray could not read the root account login and su attributes, so their state is unknown." \
        "run 'lsuser -a login rlogin su sugroups root' with authority to read account attributes and rerun PTxray." \
        "" \
        "cis-l1"
  elif [ -z "$ROOT_SU_RAW" ]; then
    add security root_su_restrict "Root login and su restrictions" NOT_ASSESSED high \
        "not assessed — lsuser returned no attributes (rc=0)" \
        "The root account exists but lsuser produced no output, so PTxray could not discriminate its state." \
        "verify 'lsuser -a login rlogin su sugroups root' returns the four attributes and rerun PTxray." \
        "" \
        "cis-l1"
  else
    # Parse key=value pairs from the lsuser output. Robust to '=' inside
    # values (split on the first '='), leading/trailing whitespace, and
    # any attribute ordering across one or more lines. Emits OK<tab>login
    # <tab>rlogin<tab>su<tab>sugroups when all four are present, else BAD.
    ROOT_SU_PARSED=$(printf '%s\n' "$ROOT_SU_RAW" | awk '
      {
        n = split($0, tok, /[ \t]+/)
        for (i = 1; i <= n; i++) {
          if (tok[i] == "") continue
          eq = index(tok[i], "=")
          if (eq < 2) continue
          key = substr(tok[i], 1, eq - 1)
          val = substr(tok[i], eq + 1)
          sub(/^[ \t]*/, "", val)
          sub(/[ \t]*$/, "", val)
          if (val == "") continue
          if (key == "login") { login = val; login_seen = 1 }
          else if (key == "rlogin") { rlogin = val; rlogin_seen = 1 }
          else if (key == "su") { su = val; su_seen = 1 }
          else if (key == "sugroups") { sugroups = val; sugroups_seen = 1 }
        }
      }
      END {
        if (login_seen == 1 && rlogin_seen == 1 && su_seen == 1 && sugroups_seen == 1)
          printf "OK\t%s\t%s\t%s\t%s\n", login, rlogin, su, sugroups
        else
          print "BAD"
      }')
    ROOT_SU_TAB=$(printf '\t')
    IFS="$ROOT_SU_TAB" read -r ROOT_SU_SHAPE ROOT_SU_LOGIN ROOT_SU_RLOGIN \
      ROOT_SU_SU ROOT_SU_SUGROUPS <<EOF
$ROOT_SU_PARSED
EOF
    case "$ROOT_SU_SHAPE" in
      BAD)
        add security root_su_restrict "Root login and su restrictions" NOT_ASSESSED high \
            "not assessed — lsuser attributes could not be fully parsed (rc=0)" \
            "At least one of login, rlogin, su, or sugroups was missing from the lsuser output, so the root account state is unknown." \
            "confirm 'lsuser -a login rlogin su sugroups root' reports all four attributes and rerun PTxray." \
            "" \
            "cis-l1"
        ;;
      OK)
        ROOT_SU_VALUE="login=$ROOT_SU_LOGIN rlogin=$ROOT_SU_RLOGIN su=$ROOT_SU_SU sugroups=$ROOT_SU_SUGROUPS"
        # su is wide open when it is anything but false and every group is allowed.
        if [ "$ROOT_SU_SU" != "false" ] && [ "$ROOT_SU_SUGROUPS" = "ALL" ]; then
          add security root_su_restrict "Root login and su restrictions" FAIL high "$ROOT_SU_VALUE; su must be false or sugroups a named group, not ALL" \
              "su access to the root account is open to every group: su=$ROOT_SU_SU, sugroups=$ROOT_SU_SUGROUPS." \
              "set su=false for root or restrict sugroups to a named group list, and disable any direct root login." \
              "cis-l1"
        # Direct login is enabled when either the console or the remote path accepts root.
        elif [ "$ROOT_SU_LOGIN" = "true" ] || [ "$ROOT_SU_RLOGIN" = "true" ]; then
          add security root_su_restrict "Root login and su restrictions" FAIL high "$ROOT_SU_VALUE; login and rlogin must be false" \
              "the root account accepts direct login: login=$ROOT_SU_LOGIN, rlogin=$ROOT_SU_RLOGIN." \
              "set login=false and rlogin=false for root so it cannot sign in directly, and restrict su to a named group list." \
              "cis-l1"
        else
          add security root_su_restrict "Root login and su restrictions" PASS high "$ROOT_SU_VALUE" \
              "the root account rejects direct login and does not leave su open to every group." \
              "n/a" \
              "cis-l1"
        fi
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""
  # login_root_shell — root's configured login shell must be /usr/bin/ksh.
  typeset LRS_RAW LRS_RC LRS_SHELL LRS_PARSE_RC LRS_REASON
  LRS_SHELL=""
  LRS_REASON=""

  if [ "${MYUID:-1}" != "0" ]; then
    add security login_root_shell "root login shell" NOT_ASSESSED med \
        "not assessed — non-root run (uid=${MYUID:-1})" \
        "PTxray requires root privileges to read the root account's shell attribute." \
        "rerun PTxray as root." \
        "cis-l1"
  else
    LRS_RAW=$(aix login_root_shell lsuser -a shell root)
    LRS_RC=$?

    if [ "$LRS_RC" -ne 0 ]; then
      LRS_REASON="lsuser capture failed (rc=$LRS_RC)"
    elif [ -z "$LRS_RAW" ]; then
      LRS_REASON="lsuser capture returned empty output"
    else
      LRS_SHELL=$(printf '%s\n' "$LRS_RAW" | awk '
        NF { n++; last=$0 }
        END {
          if (n != 1) exit 1
          if (last !~ /^root shell=/) exit 2
          shell = last
          sub(/^root shell=/, "", shell)
          print shell
        }')
      LRS_PARSE_RC=$?
      case "$LRS_PARSE_RC" in
        0) ;;
        1) LRS_REASON="lsuser output was not exactly one non-blank line" ;;
        2) LRS_REASON="lsuser output did not contain 'root shell='" ;;
        *) LRS_REASON="lsuser output unparseable (parse rc=$LRS_PARSE_RC)" ;;
      esac
    fi

    if [ -n "$LRS_REASON" ]; then
      add security login_root_shell "root login shell" NOT_ASSESSED med \
          "not assessed — $LRS_REASON" \
          "PTxray did not obtain a trustworthy root shell attribute, so it cannot claim the login-shell requirement is satisfied." \
          "run 'lsuser -a shell root', correct the capture problem, and rerun PTxray." \
          "cis-l1"
    elif [ "$LRS_SHELL" = "/usr/bin/ksh" ]; then
      add security login_root_shell "root login shell" PASS med \
          "root shell=/usr/bin/ksh" \
          "The root account is configured with /usr/bin/ksh as its login shell." \
          "n/a" "cis-l1"
    else
      add security login_root_shell "root login shell" FAIL med \
          "root shell=$LRS_SHELL" \
          "The root account's login shell is not /usr/bin/ksh." \
          "set root's login shell to /usr/bin/ksh: 'chuser shell=/usr/bin/ksh root'." \
          "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
# ck-login-core-limit
#
# Reads two system state sources that together decide whether the kernel
# writes process core dump files: the default-stanza core and core_hard
# file-size limits in /etc/security/limits, and the fullcore tunable of the
# sys0 pre-defined device. The compliant state is core=0, core_hard=0 and
# fullcore=false. This fragment only reads state; it never writes.

  typeset LOGIN_CL_LIMITS_RAW LOGIN_CL_LIMITS_RC LOGIN_CL_LIMITS_LINES
  typeset LOGIN_CL_LIMITS_LINE LOGIN_CL_LIMITS_REST
  typeset LOGIN_CL_CORE_VAL LOGIN_CL_CORE_HARD_VAL
  typeset LOGIN_CL_CORE_NORM LOGIN_CL_CORE_HARD_NORM
  typeset LOGIN_CL_FULLCORE_RAW LOGIN_CL_FULLCORE_RC LOGIN_CL_FULLCORE_LINES
  typeset LOGIN_CL_FULLCORE_LINE LOGIN_CL_FULLCORE_FIELD2 LOGIN_CL_FULLCORE_VAL
  typeset LOGIN_CL_LIMITS_STATUS LOGIN_CL_FULLCORE_STATUS
  typeset LOGIN_CL_LIMITS_REASON LOGIN_CL_FULLCORE_REASON LOGIN_CL_REASON
  typeset LOGIN_CL_FAILURE
  LOGIN_CL_LIMITS_RAW=""
  LOGIN_CL_LIMITS_RC=126
  LOGIN_CL_FULLCORE_RAW=""
  LOGIN_CL_FULLCORE_RC=126
  LOGIN_CL_LIMITS_STATUS=""
  LOGIN_CL_FULLCORE_STATUS=""
  LOGIN_CL_LIMITS_REASON=""
  LOGIN_CL_FULLCORE_REASON=""
  LOGIN_CL_REASON=""
  LOGIN_CL_FAILURE=""

  if [ "${MYUID:-0}" != "0" ]; then
    LOGIN_CL_REASON="requires root privileges"
  else
    # Limits probe: default-stanza core and core_hard attributes.
    LOGIN_CL_LIMITS_RAW=$(aix login_core_limit_limits lssec -f /etc/security/limits -s default -a core -a core_hard)
    LOGIN_CL_LIMITS_RC=$?
    if [ "$LOGIN_CL_LIMITS_RC" -ne 0 ]; then
      LOGIN_CL_LIMITS_REASON="limits capture failed (rc=$LOGIN_CL_LIMITS_RC)"
    elif [ -z "$LOGIN_CL_LIMITS_RAW" ]; then
      LOGIN_CL_LIMITS_REASON="limits capture returned empty output"
    else
      LOGIN_CL_LIMITS_LINES=$(printf '%s\n' "$LOGIN_CL_LIMITS_RAW" |
        awk 'NF { count++ } END { print count + 0 }')
      if [ "$LOGIN_CL_LIMITS_LINES" -ne 1 ]; then
        LOGIN_CL_LIMITS_REASON="limits output was not one exact assignment"
      else
        LOGIN_CL_LIMITS_LINE=$(printf '%s\n' "$LOGIN_CL_LIMITS_RAW" |
          awk 'NF { print; exit }')
        case "$LOGIN_CL_LIMITS_LINE" in
          "default core="*" core_hard="*)
            LOGIN_CL_LIMITS_REST=${LOGIN_CL_LIMITS_LINE#default core=}
            LOGIN_CL_CORE_VAL=${LOGIN_CL_LIMITS_REST%% core_hard=*}
            LOGIN_CL_CORE_HARD_VAL=${LOGIN_CL_LIMITS_REST##* core_hard=}
            case "$LOGIN_CL_CORE_VAL" in
              ""|*[!0-9]*)
                LOGIN_CL_LIMITS_REASON="core value was not a non-negative decimal integer"
                ;;
              *)
                LOGIN_CL_CORE_NORM=$LOGIN_CL_CORE_VAL
                while [ "${LOGIN_CL_CORE_NORM#0}" != "$LOGIN_CL_CORE_NORM" ]; do
                  LOGIN_CL_CORE_NORM=${LOGIN_CL_CORE_NORM#0}
                done
                [ -n "$LOGIN_CL_CORE_NORM" ] || LOGIN_CL_CORE_NORM=0
                case "$LOGIN_CL_CORE_HARD_VAL" in
                  "")
                    # An empty value from lssec means the attribute is ABSENT
                    # from the default stanza, not that it is unparseable. That
                    # is determinate: the AIX built-in default applies, and for
                    # core_hard that default is an unlimited hard core limit.
                    # Both lab boxes on 2026-08-05 returned exactly
                    # 'default core=2097151 core_hard=' with no core_hard line
                    # in the stanza, and 'ulimit -Hc' reported 'unlimited' on
                    # both — direct confirmation of the effective value. An
                    # unrestricted hard core limit is what this control
                    # forbids, so it is a FAIL, never a refusal.
                    LOGIN_CL_LIMITS_STATUS=FAIL
                    LOGIN_CL_FAILURE="core=$LOGIN_CL_CORE_VAL and core_hard is unset in the default stanza of /etc/security/limits, so the AIX default unlimited hard core limit applies"
                    ;;
                  *[!0-9]*)
                    LOGIN_CL_LIMITS_REASON="core_hard value was not a non-negative decimal integer"
                    ;;
                  *)
                    LOGIN_CL_CORE_HARD_NORM=$LOGIN_CL_CORE_HARD_VAL
                    while [ "${LOGIN_CL_CORE_HARD_NORM#0}" != "$LOGIN_CL_CORE_HARD_NORM" ]; do
                      LOGIN_CL_CORE_HARD_NORM=${LOGIN_CL_CORE_HARD_NORM#0}
                    done
                    [ -n "$LOGIN_CL_CORE_HARD_NORM" ] || LOGIN_CL_CORE_HARD_NORM=0
                    if [ "$LOGIN_CL_CORE_NORM" != "0" ] || [ "$LOGIN_CL_CORE_HARD_NORM" != "0" ]; then
                      LOGIN_CL_LIMITS_STATUS=FAIL
                      LOGIN_CL_FAILURE="core=$LOGIN_CL_CORE_VAL core_hard=$LOGIN_CL_CORE_HARD_VAL in the default stanza of /etc/security/limits"
                    else
                      LOGIN_CL_LIMITS_STATUS=PASS
                    fi
                    ;;
                esac
                ;;
            esac
            ;;
          *)
            LOGIN_CL_LIMITS_REASON="limits output did not contain the exact requested assignment"
            ;;
        esac
      fi
    fi

    # Fullcore probe: fullcore attribute of the sys0 pre-defined device.
    LOGIN_CL_FULLCORE_RAW=$(aix login_core_limit_fullcore lsattr -El sys0 -a fullcore)
    LOGIN_CL_FULLCORE_RC=$?
    if [ "$LOGIN_CL_FULLCORE_RC" -ne 0 ]; then
      LOGIN_CL_FULLCORE_REASON="fullcore capture failed (rc=$LOGIN_CL_FULLCORE_RC)"
    elif [ -z "$LOGIN_CL_FULLCORE_RAW" ]; then
      LOGIN_CL_FULLCORE_REASON="fullcore capture returned empty output"
    else
      LOGIN_CL_FULLCORE_LINES=$(printf '%s\n' "$LOGIN_CL_FULLCORE_RAW" |
        awk 'NF { count++ } END { print count + 0 }')
      if [ "$LOGIN_CL_FULLCORE_LINES" -ne 1 ]; then
        LOGIN_CL_FULLCORE_REASON="fullcore output was not one exact assignment"
      else
        LOGIN_CL_FULLCORE_LINE=$(printf '%s\n' "$LOGIN_CL_FULLCORE_RAW" |
          awk 'NF { print; exit }')
        case "$LOGIN_CL_FULLCORE_LINE" in
          "fullcore "*)
            LOGIN_CL_FULLCORE_FIELD2=${LOGIN_CL_FULLCORE_LINE#fullcore }
            LOGIN_CL_FULLCORE_VAL=${LOGIN_CL_FULLCORE_FIELD2%% *}
            case "$LOGIN_CL_FULLCORE_VAL" in
              "false")
                LOGIN_CL_FULLCORE_STATUS=PASS
                ;;
              "true")
                LOGIN_CL_FULLCORE_STATUS=FAIL
                if [ -n "$LOGIN_CL_FAILURE" ]; then
                  LOGIN_CL_FAILURE="$LOGIN_CL_FAILURE; fullcore=true on sys0"
                else
                  LOGIN_CL_FAILURE="fullcore=true on sys0"
                fi
                ;;
              *)
                LOGIN_CL_FULLCORE_REASON="fullcore value was not a boolean"
                ;;
            esac
            ;;
          *)
            LOGIN_CL_FULLCORE_REASON="fullcore output did not start with the fullcore attribute"
            ;;
        esac
      fi
    fi
  fi

  if [ -n "$LOGIN_CL_LIMITS_REASON" ] || [ -n "$LOGIN_CL_FULLCORE_REASON" ]; then
    if [ -n "$LOGIN_CL_LIMITS_REASON" ] && [ -n "$LOGIN_CL_FULLCORE_REASON" ]; then
      LOGIN_CL_REASON="limits: $LOGIN_CL_LIMITS_REASON; fullcore: $LOGIN_CL_FULLCORE_REASON"
    elif [ -n "$LOGIN_CL_LIMITS_REASON" ]; then
      LOGIN_CL_REASON=$LOGIN_CL_LIMITS_REASON
    else
      LOGIN_CL_REASON=$LOGIN_CL_FULLCORE_REASON
    fi
  fi

  if [ "$LOGIN_CL_LIMITS_STATUS" = "FAIL" ] || [ "$LOGIN_CL_FULLCORE_STATUS" = "FAIL" ]; then
    add security login_core_limit "Default core file size limits and fullcore tunable" FAIL med \
        "$LOGIN_CL_FAILURE" \
        "The system is able to write process core dump files, and a full-size dump captures process memory that can include credentials and keys." \
        "set core and core_hard to 0 in the default stanza of /etc/security/limits (chsec -f /etc/security/limits -s default -a core=0 -a core_hard=0) and set fullcore=false (chdev -a fullcore=false -l sys0)." \
        "cis-l1"
  elif [ "$LOGIN_CL_LIMITS_STATUS" = "PASS" ] && [ "$LOGIN_CL_FULLCORE_STATUS" = "PASS" ]; then
    add security login_core_limit "Default core file size limits and fullcore tunable" PASS med \
        "core=0 core_hard=0 fullcore=false" \
        "The default-stanza core file size limits are zero and the fullcore tunable is off, so the kernel does not write process core dump files." \
        "n/a" "cis-l1"
  else
    add security login_core_limit "Default core file size limits and fullcore tunable" NOT_ASSESSED med \
        "not assessed — $LOGIN_CL_REASON" \
        "PTxray did not obtain trustworthy core limit and fullcore values." \
        "inspect the default-stanza core attributes in /etc/security/limits and the sys0 fullcore attribute as root, correct capture ambiguity, and rerun PTxray." \
        "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
# ck-login-path-integrity
#
# CIS 4.8.4 — the PATH assignment in /etc/environment must not contain a dot
# entry or an empty path component. This fragment probes the file with two
# read-only captures available to any user; neither requires root.

  typeset PATH_ENV_STAT_RAW PATH_ENV_STAT_RC PATH_ENV_LINE_RAW PATH_ENV_LINE_RC PATH_ENV_CHECK_RAW
  typeset PATH_ENV_STATUS PATH_ENV_OBSERVED PATH_ENV_MEANING PATH_ENV_FIX
  PATH_ENV_STAT_RAW=""
  PATH_ENV_STAT_RC=0
  PATH_ENV_LINE_RAW=""
  PATH_ENV_LINE_RC=0
  PATH_ENV_CHECK_RAW=""
  PATH_ENV_STATUS=NOT_ASSESSED
  PATH_ENV_OBSERVED=""
  PATH_ENV_MEANING="PTxray did not obtain trustworthy evidence about the PATH assignment in /etc/environment, so it cannot establish whether the value is secure."
  PATH_ENV_FIX="verify /etc/environment exists and is readable, then rerun PTxray."

  PATH_ENV_STAT_RAW=$(aix path_env_stat ls -ld /etc/environment)
  PATH_ENV_STAT_RC=$?
  if [ "$PATH_ENV_STAT_RC" -eq 2 ]; then
    PATH_ENV_STATUS=NOT_APPLICABLE
    PATH_ENV_OBSERVED="/etc/environment is absent"
    PATH_ENV_MEANING="The control constrains the PATH assignment in /etc/environment; the file does not exist on this system, so there is nothing to violate the constraint."
    PATH_ENV_FIX="n/a"
  elif [ "$PATH_ENV_STAT_RC" -ne 0 ]; then
    PATH_ENV_OBSERVED="not assessed — file metadata probe failed (rc=$PATH_ENV_STAT_RC)"
  else
    PATH_ENV_LINE_RAW=$(aix path_env_line grep "^PATH=" /etc/environment)
    PATH_ENV_LINE_RC=$?
    if [ "$PATH_ENV_LINE_RC" -eq 127 ]; then
      PATH_ENV_STATUS=NOT_ASSESSED
      PATH_ENV_OBSERVED="not assessed — PATH capture is absent or grep is missing (rc=127)"
      PATH_ENV_MEANING="PTxray has no captured PATH lines from /etc/environment, so it cannot establish whether the value is secure."
      PATH_ENV_FIX="capture /etc/environment for this check, then rerun PTxray."
    elif [ "$PATH_ENV_LINE_RC" -eq 1 ]; then
      PATH_ENV_STATUS=PASS
      PATH_ENV_OBSERVED="no PATH assignment in /etc/environment"
      PATH_ENV_MEANING="The control constrains the PATH assignment in /etc/environment; there is no PATH assignment in the file, so there is nothing to violate the constraint."
      PATH_ENV_FIX="n/a"
    elif [ "$PATH_ENV_LINE_RC" -ne 0 ]; then
      PATH_ENV_STATUS=NOT_ASSESSED
      PATH_ENV_OBSERVED="not assessed — PATH probe failed (rc=$PATH_ENV_LINE_RC)"
      PATH_ENV_MEANING="PTxray could not read the PATH assignment from /etc/environment, so it cannot establish whether the value is secure."
      PATH_ENV_FIX="verify /etc/environment is readable, then rerun PTxray."
    elif [ -z "$PATH_ENV_LINE_RAW" ]; then
      PATH_ENV_STATUS=NOT_ASSESSED
      PATH_ENV_OBSERVED="not assessed — PATH capture was empty (grep returned success but the capture contained no bytes)"
      PATH_ENV_MEANING="The probe reported success but produced no PATH content; the evidence is insufficient to judge the PATH assignment."
      PATH_ENV_FIX="verify /etc/environment contains a readable PATH= line, capture it, then rerun PTxray."
    else
      PATH_ENV_CHECK_RAW=$(printf '%s\n' "$PATH_ENV_LINE_RAW" | awk '
        /^PATH=/ {
          val = substr($0, 6)
          if (val ~ /(:[ \t]*:)|(:[ \t]*$)|(^[ \t]*:)/) {
            print "empty path component: " $0
          } else if (val ~ /(^[ \t]*\.[ \t]*:)|(:[ \t]*\.[ \t]*$)|(:[ \t]*\.[ \t]*:)|(^[ \t]*\.[ \t]*$)/) {
            print "dot entry: " $0
          } else if (val ~ /(:[ \t]*.[ \t]*:)|(:[ \t]*.[ \t]*$)|(^[ \t]*.[ \t]*:)|(^[ \t]*.[ \t]*$)/) {
            print "single-character path component: " $0
          }
        }')
      if [ -n "$PATH_ENV_CHECK_RAW" ]; then
        PATH_ENV_STATUS=FAIL
        PATH_ENV_OBSERVED="insecure $PATH_ENV_CHECK_RAW"
        PATH_ENV_MEANING="The PATH assignment in /etc/environment contains a dot entry, an empty path component, or a single-character relative entry; all directories must be explicitly defined in PATH, and an unprivileged user could place an executable ahead of system binaries."
        PATH_ENV_FIX="remove the dot entry or empty path component from the PATH assignment in /etc/environment, then rerun PTxray."
      else
        PATH_ENV_STATUS=PASS
        PATH_ENV_OBSERVED="PATH assignment in /etc/environment is clean"
        PATH_ENV_MEANING="The PATH assignment in /etc/environment (if present) has no dot entry and no empty path component."
        PATH_ENV_FIX="n/a"
      fi
    fi
  fi

  add security login_path_integrity "PATH assignment integrity" "$PATH_ENV_STATUS" med \
      "$PATH_ENV_OBSERVED" "$PATH_ENV_MEANING" "$PATH_ENV_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""

  # login_root_path — root's login-shell PATH must not carry the current-directory
  # token ('.') or any empty component. A leading colon, trailing colon, or doubled
  # colon in PATH resolves to the current directory at runtime — the same exposure
  # as an explicit '.'. The live runtime PATH is not obtainable honestly: opening
  # a root login shell through the su command (as the deleted probe did) would run
  # customer-authored login-shell code as root and would write /var/adm/sulog,
  # both of which violate PTxray's read-only charter. Instead this check reads the
  # files that DECLARE root's login PATH —
  # /etc/environment, /etc/profile, and /.profile (root's home directory is /) —
  # with a plain grep that executes nothing and writes nothing. It therefore
  # measures the PATH root's login shell is CONFIGURED to receive, never the
  # scanner's live environment.
  typeset LP_RAW LP_RC AWK_RC UNRESOLVED_LINE LS_RAW LS_RC
  typeset ENV_PRESENT PROF_PRESENT DOTPROF_PRESENT
  typeset LP_LINE
  typeset INDETERMINATE_PATHS ABSENT_PATHS ABSENT_DISCLOSURE ABSENT_MEANING

  # -------------------------------------------------------------------
  # Phase 0: establish which declaration files exist on this host.
  # aixv records stdout and stderr separately, then emits out-then-err so
  # the caller sees ls long-format rows (stdout) followed by per-file
  # diagnostics (stderr).
  LS_RAW=$(aixv ls_login_path_files ls -l /etc/environment /etc/profile /.profile)
  LS_RC=$?

  # Default to indeterminate: a declaration file the capture says nothing about
  # is a file PTxray did not read, and that must refuse rather than be assumed
  # absent. The classification below only ever moves a path OFF this default on
  # positive evidence.
  ENV_PRESENT="indeterminate"
  PROF_PRESENT="indeterminate"
  DOTPROF_PRESENT="indeterminate"

  if aix_capture_missing ls_login_path_files; then
    ENV_PRESENT="indeterminate"
    PROF_PRESENT="indeterminate"
    DOTPROF_PRESENT="indeterminate"
  elif [ "$LS_RC" -gt 2 ]; then
    # AIX ls exits 2 when a named operand is missing (verified on a live AIX
    # 7.2 box). A higher rc means the probe itself failed, not merely that a
    # declaration file is absent, so nothing can be classified.
    ENV_PRESENT="indeterminate"
    PROF_PRESENT="indeterminate"
    DOTPROF_PRESENT="indeterminate"
  else
    # Classify each declaration file from the capture alone, line by line:
    # "present" when a long-format row ENDS with the path, "absent" when a
    # line is exactly "<path> not found" (the AIX ls stderr form, verified on
    # a live AIX 7.2 box), "indeterminate" otherwise. Matching per line makes
    # the anchor exact, so a row for /etc/profile never satisfies /.profile.
    # Any other wording leaves the path indeterminate, which refuses -- AIX
    # grep says "can't open <path>" for BOTH an absent and an unreadable file,
    # so absence must be established here or not at all, and guessing it would
    # launder an unread violating PATH into a clean verdict.
    while read LP_LINE; do
      case "$LP_LINE" in
        "/etc/environment not found") ENV_PRESENT="absent" ;;
        "/etc/profile not found")     PROF_PRESENT="absent" ;;
        "/.profile not found")        DOTPROF_PRESENT="absent" ;;
        *"/etc/environment")          ENV_PRESENT="present" ;;
        *"/etc/profile")              PROF_PRESENT="present" ;;
        *"/.profile")                 DOTPROF_PRESENT="present" ;;
      esac
    done <<LPEOF
$LS_RAW
LPEOF
  fi

  # Build the indeterminate and absent lists for use in finding text.
  INDETERMINATE_PATHS=""
  ABSENT_PATHS=""
  case "$ENV_PRESENT" in
    indeterminate) INDETERMINATE_PATHS="/etc/environment" ;;
    absent) ABSENT_PATHS="/etc/environment" ;;
  esac
  case "$PROF_PRESENT" in
    indeterminate) INDETERMINATE_PATHS="${INDETERMINATE_PATHS:+$INDETERMINATE_PATHS, }/etc/profile" ;;
    absent) ABSENT_PATHS="${ABSENT_PATHS:+$ABSENT_PATHS, }/etc/profile" ;;
  esac
  case "$DOTPROF_PRESENT" in
    indeterminate) INDETERMINATE_PATHS="${INDETERMINATE_PATHS:+$INDETERMINATE_PATHS, }/.profile" ;;
    absent) ABSENT_PATHS="${ABSENT_PATHS:+$ABSENT_PATHS, }/.profile" ;;
  esac

  ABSENT_DISCLOSURE=""
  ABSENT_MEANING=""
  if [ -n "$ABSENT_PATHS" ]; then
    ABSENT_DISCLOSURE="; ${ABSENT_PATHS} does not exist on this host and declares no PATH"
    ABSENT_MEANING=" ${ABSENT_PATHS} does not exist on this host and declares no PATH."
  fi

  # -------------------------------------------------------------------
  # Phase 1: read the declared PATH assignments
  LP_RAW=$(aix login_path_decl grep -E '^[ \t]*(export[ \t]+)?PATH=' /etc/environment /etc/profile /.profile)
  LP_RC=$?

  # -------------------------------------------------------------------
  # Decision tree.  The adjudication (awk discriminator) lives in the final
  # else branch so the capture_missing, status, and emptiness gates all
  # structurally guard the use of LP_RAW.
  if aix_capture_missing login_path_decl; then
    add security login_root_path "Root login PATH" NOT_ASSESSED med \
        "not assessed — no capture exists for the declared login PATH probe" \
        "PTxray has no captured read of /etc/environment, /etc/profile, or /.profile, so the PATH declared for root's login shell is unknown." \
        "capture /etc/environment, /etc/profile, and /.profile for this check, then re-run PTxray." "cis-l1"

  elif [ -n "$INDETERMINATE_PATHS" ]; then
    add security login_root_path "Root login PATH" NOT_ASSESSED med \
        "not assessed — cannot establish whether ${INDETERMINATE_PATHS} exists (ls probe rc=$LS_RC)" \
        "PTxray cannot determine whether ${INDETERMINATE_PATHS} exists on this host; this file may declare a violating PATH that was not read. The ls -l probe returned rc $LS_RC." \
        "verify the file exists and is readable, then re-run PTxray." "cis-l1"

  elif [ "$LP_RC" -ge 2 ] && [ -z "$LP_RAW" ]; then
    # grep rc 2 means at least one named file could not be opened, but every
    # file is now classified as present or absent.  An absent file declares
    # nothing — the read is complete over the files that exist.  With no
    # PATH lines captured, this is the same refusal as rc 1.
    add security login_root_path "Root login PATH" NOT_ASSESSED med \
        "not assessed — no PATH assignment found in the declaration files that exist${ABSENT_DISCLOSURE}" \
        "The declaration files that exist on this host were read but no PATH assignment was captured; root's login shell would fall back to a default PATH that PTxray did not measure.${ABSENT_MEANING}" \
        "add an explicit PATH assignment to /etc/environment or a login profile, then re-run PTxray." "cis-l1"

  elif [ "$LP_RC" -eq 1 ]; then
    add security login_root_path "Root login PATH" NOT_ASSESSED med \
        "not assessed — no PATH assignment found in the declaration files that exist${ABSENT_DISCLOSURE}" \
        "The declaration files that exist on this host were read but no PATH assignment was captured; root's login shell would fall back to a default PATH that PTxray did not measure.${ABSENT_MEANING}" \
        "add an explicit PATH assignment to /etc/environment or a login profile, then re-run PTxray." "cis-l1"

  else
    # LP_RC is 0 (grep matched at least one PATH line), or LP_RC >= 2
    # with every file classified as present or absent and LP_RAW non-empty.
    # In either case the read is complete over the files that exist and
    # at least one captured PATH line is available for adjudication.
    # Discriminator contract:
    # awk rc 0 = at least one PATH element ANYWHERE in the capture was
    # adjudicated, no violation was found, and no line was ambiguous, rc 1 = a
    # violating element was found, rc 2 = a PATH line could not be parsed and
    # the state is genuinely unknown, rc 3 = NO PATH element anywhere in the
    # capture was adjudicated (every declaration reduced to all-variable
    # elements). Adjudication is per-capture, not per-declaration: a single
    # all-variable declaration does not refuse the whole check when another
    # declaration was adjudicated. Ordering: a determinate violation (hit)
    # beats everything; an ambiguous line (a ';' suffix that is not
    # "export PATH") outranks PASS, because the unparsed content may hide a
    # violation and the check cannot judge it; PASS needs at least one
    # adjudicated element AND no ambiguous line. An empty or whitespace-only
    # PATH value is a single empty field — the same class as a
    # leading/trailing/doubled colon — and is a FAIL, whether it was empty on
    # the line or emptied by stripping a '; export PATH' suffix; a line that
    # yields no elements at all is the same determinate empty FAIL and is never
    # an unresolved all-variable declaration. Only a genuine variable reference
    # — a $ followed by a name character or an opening brace, such as $PATH,
    # $HOME/bin or ${PATH} — is not statically resolvable and is skipped, not
    # judged; every other element, including $(...) command substitution,
    # backtick substitution, and a bare $, is adjudicated as an ordinary
    # element and fails the not-absolute rule. A '; export PATH' suffix is
    # recognized after stripping trailing whitespace and a carriage return, so
    # CRLF-formatted declaration files parse like LF ones. The unresolvable
    # declaration(s) are printed to stdout whenever any exist, so
    # UNRESOLVED_LINE is populated for both a NOT_ASSESSED (to name them) and a
    # PASS (to disclose what it did not judge).
    # UNRESOLVED_LINE is declared in the bare typeset at the top of this
    # function. Do NOT "tidy" this into `typeset UNRESOLVED_LINE=$(...)`: under
    # ksh, `typeset VAR=$(cmd)` returns the exit status of typeset — 0 — not
    # the command's, so AWK_RC would read 0 for every run and silently turn
    # every FAIL and every refusal into PASS.
    UNRESOLVED_LINE=$(printf '%s\n' "$LP_RAW" | awk '
      function empty(e) {
        return (e == "") || (e ~ /^[ \t]+$/)
      }
      {
        line=$0
        sub(/^\/etc\/environment:/, "", line)
        sub(/^\/etc\/profile:/, "", line)
        sub(/^\/\.profile:/, "", line)
        sub(/^[ \t]+/, "", line)
        sub(/^export[ \t]+/, "", line)
        if (line !~ /^PATH=/) next
        sub(/^PATH=/, "", line)
        # Strip a matching pair of surrounding quotes. Written as two explicit
        # branches with a literal anchored sub() rather than the obvious
        # length()-based tail comparison: tests/lint-ksh88.sh bans `length(`
        # followed by an identifier, because it cannot statically tell the
        # portable POSIX length(string) apart from the gawk-only
        # length(array). Rewriting is the honest fix; loosening the ban would
        # also unban the construct that actually breaks AIX awk.
        if (substr(line,1,1) == "\"") {
          line=substr(line,2)
          sub(/"$/, "", line)
        } else if (substr(line,1,1) == "\047") {
          line=substr(line,2)
          sub(/\047$/, "", line)
        }
        sub(/[ \t]+#.*/, "", line)
        sub(/[ \t]+$/, "", line)
        if (empty(line)) { hit=1; next }
        if (index(line, ";") > 0) {
          semicolon=index(line, ";")
          suffix=substr(line, semicolon+1)
          sub(/^[ \t]+/, "", suffix)
          sub(/[ \t\r]+$/, "", suffix)
          line=substr(line, 1, semicolon-1)
          sub(/[ \t\r]+$/, "", line)
          if (suffix != "export PATH") { ambiguous=1; next }
          # A value emptied by the suffix strip is a determinate empty PATH,
          # the same FAIL as the pre-strip empty check above.
          if (empty(line)) { hit=1; next }
        }
        n=split(line, element, ":")
        # No elements at all is a determinate empty PATH, not an unresolved
        # all-variable declaration: it must reach hit, never the per-capture
        # PASS relaxation.
        if (n == 0) { hit=1; next }
        count=0
        for (i=1; i<=n; i++) {
          piece=element[i]
          # Skip only a genuine variable reference: a $ followed by a name
          # character or an opening brace ($PATH, $HOME/bin, ${PATH}). Anything
          # else starting with $ — $(...), backticks, a bare $ — falls through
          # to ordinary adjudication, where the not-absolute rule fails it.
          if (piece ~ /^\$([A-Za-z0-9_]|[{])/) continue
          count++
          adjudicated++
          if (empty(piece)) { hit=1; continue }
          if (piece == ".") { hit=1; continue }
          if (piece !~ /^\//) { hit=1; continue }
        }
        # count == 0 now means only "every element was a $ reference". The
        # no-elements-at-all case is already handled above (n == 0 -> hit).
        if (count == 0 && n > 0) {
          unresolved=1
          line_norm=$0
          sub(/[ \t\r]+$/, "", line_norm)
          unresolved_list = unresolved_list (unresolved_list == "" ? line_norm : "; " line_norm)
        }
      }
      END {
        # The list is printed whenever it is non-empty, not only on rc 3, so a
        # PASS that left a declaration unadjudicated can still name it in the
        # finding text. The exit code carries the verdict.
        if (unresolved_list != "") print unresolved_list
        if (hit) exit 1
        if (ambiguous) exit 2
        if (adjudicated > 0) exit 0
        if (unresolved) exit 3
        exit 3
      }
    ')
    AWK_RC=$?
    case "$AWK_RC" in
      0)
        if [ -n "$UNRESOLVED_LINE" ]; then
          add security login_root_path "Root login PATH" PASS med \
              "declared root login PATH has no '.', empty, or relative component${ABSENT_DISCLOSURE}" \
              "Every PATH element that was adjudicated — captured from /etc/environment, /etc/profile, and /.profile, the files that declare root's login PATH — is built only from absolute, non-empty directory components: no current-directory token, no leading/trailing/doubled colon, and no relative element. The following declaration(s) were not adjudicated because every element is an unresolved variable reference, and were not judged: ${UNRESOLVED_LINE}.${ABSENT_MEANING}" \
              "n/a" "cis-l1"
        else
          add security login_root_path "Root login PATH" PASS med \
              "declared root login PATH has no '.', empty, or relative component${ABSENT_DISCLOSURE}" \
              "Every PATH element captured from /etc/environment, /etc/profile, and /.profile — the files that declare root's login PATH — is built only from absolute, non-empty directory components: no current-directory token, no leading/trailing/doubled colon, and no relative element. Variable references in an assignment are not statically resolvable and are not judged.${ABSENT_MEANING}" \
              "n/a" "cis-l1"
        fi
        ;;
      1)
        add security login_root_path "Root login PATH" FAIL high \
            "declared root login PATH contains '.' or an empty/relative component${ABSENT_DISCLOSURE}" \
            "A PATH assignment captured from /etc/environment, /etc/profile, or /.profile carries the current-directory token, an empty component (leading, trailing, or doubled colon), or a relative element, so a command invoked from an untrusted directory can resolve against the current directory.${ABSENT_MEANING}" \
            "remove '.' and any empty or relative component from the PATH assigned to root's login shell." "cis-l1"
        ;;
      2)
        add security login_root_path "Root login PATH" NOT_ASSESSED med \
            "not assessed — a declared PATH carries a ';' suffix that is not 'export PATH' and could not be judged${ABSENT_DISCLOSURE}" \
            "A PATH declaration captured from /etc/environment, /etc/profile, or /.profile contains a ';' suffix that is not 'export PATH' (for example, an additional command on the same line). PTxray cannot tell whether the PATH value is clean, so the declared login PATH is not assessed.${ABSENT_MEANING}" \
            "declare root's login PATH as a single assignment with no trailing command, then re-run PTxray." "cis-l1"
        ;;
      3)
        if [ -n "$UNRESOLVED_LINE" ]; then
          add security login_root_path "Root login PATH" NOT_ASSESSED med \
              "not assessed — declared PATH '${UNRESOLVED_LINE}' is built entirely from unresolved variable references${ABSENT_DISCLOSURE}" \
              "The PATH declaration \"${UNRESOLVED_LINE}\" is composed only of variable references (\$VAR) that PTxray cannot statically resolve, so zero of its elements were adjudicated. PASS requires at least one adjudicated element; a declaration that reduces to none cannot be confirmed clean.${ABSENT_MEANING}" \
              "declare a concrete absolute PATH for root's login shell, or include at least one absolute, non-variable component, then re-run PTxray." "cis-l1"
        else
          add security login_root_path "Root login PATH" NOT_ASSESSED med \
              "not assessed — no PATH element in the capture was adjudicated${ABSENT_DISCLOSURE}" \
              "No PATH element captured from /etc/environment, /etc/profile, and /.profile was adjudicated: every declaration reduced to unresolved variable references, or the capture carried no parseable declaration at all. PASS requires at least one adjudicated element, so the declared login PATH cannot be confirmed clean.${ABSENT_MEANING}" \
              "declare a concrete absolute PATH for root's login shell, or include at least one absolute, non-variable component, then re-run PTxray." "cis-l1"
        fi
        ;;
      *)
        add security login_root_path "Root login PATH" NOT_ASSESSED med \
            "not assessed — declared PATH discriminator failed (awk rc=$AWK_RC)${ABSENT_DISCLOSURE}" \
            "PTxray could not test the declared PATH assignments: the discriminator exited with an unexpected status, or a PATH line could not be parsed (for example, more than one command on the line).${ABSENT_MEANING}" \
            "re-run the check; if it persists, collect the captured PATH lines and inspect them manually." "cis-l1"
        ;;
    esac
  fi
_AIXRAY_SESSION_KEYS=""
  # fileperm_motd_write — /etc/motd group/other write-bit boundary.
  # Group-write is the second char of the group triplet, other-write is the
  # second char of the other triplet, in the 10-char mode field from ls -ld.
  typeset FMW_RAW FMW_RC FMW_PARSED FMW_PARSE_RC FMW_MODE FMW_GW FMW_OW FMW_REM FMW_REASON

  FMW_RAW=$(aix ls_motd ls -ld /etc/motd)
  FMW_RC=$?
  FMW_PARSED=""
  FMW_MODE=""
  FMW_GW=""
  FMW_OW=""
  FMW_REASON=""

  if [ "$FMW_RC" -eq 2 ] && [ -z "$FMW_RAW" ]; then
    FMW_REASON="absent"
  elif [ "$FMW_RC" -eq 0 ] && [ -z "$FMW_RAW" ]; then
    FMW_REASON="empty"
  elif [ "$FMW_RC" -eq 0 ]; then
    FMW_PARSED=$(printf '%s\n' "$FMW_RAW" | awk '
      NF {
        records++
        if (records != 1 || NF != 9) { bad=1; next }
        mode=$1
        if (length("" mode) == 11 && substr(mode, 11, 1) == "+") mode=substr(mode, 1, 10)
        if (length("" mode) != 10) { bad=1; next }
        if (substr(mode, 6, 1) != "w" && substr(mode, 6, 1) != "-") { bad=1; next }
        if (substr(mode, 9, 1) != "w" && substr(mode, 9, 1) != "-") { bad=1; next }
        if ($NF != "/etc/motd") { bad=1; next }
        print mode "|" substr(mode, 6, 1) "|" substr(mode, 9, 1)
      }
      END { if (records != 1 || bad) exit 1 }
    ')
    FMW_PARSE_RC=$?
    if [ "$FMW_PARSE_RC" -ne 0 ] || [ -z "$FMW_PARSED" ]; then
      FMW_REASON="unparseable"
    else
      FMW_MODE=${FMW_PARSED%%\|*}
      FMW_REM=${FMW_PARSED#*\|}
      FMW_GW=${FMW_REM%%\|*}
      FMW_OW=${FMW_REM#*\|}
    fi
  else
    FMW_REASON="unexpected probe rc=$FMW_RC"
  fi

  if [ "$FMW_REASON" = "absent" ]; then
    add security fileperm_motd_write "/etc/motd write bits" NOT_APPLICABLE low \
      "/etc/motd absent (ls -ld rc=2, no output)" \
      "/etc/motd does not exist, so the write-bit control constrains no file and has nothing to assess." \
      "n/a" "cis-l1"
  elif [ -n "$FMW_REASON" ]; then
    add security fileperm_motd_write "/etc/motd write bits" NOT_ASSESSED med \
      "not assessed — /etc/motd $FMW_REASON" \
      "PTxray did not obtain one trustworthy mode row for /etc/motd, so it cannot claim the group/other write boundary is satisfied." \
      "run 'ls -ld /etc/motd', correct the capture or path problem, and rerun PTxray." \
      "cis-l1"
  elif [ "$FMW_GW" = "w" ] || [ "$FMW_OW" = "w" ]; then
    add security fileperm_motd_write "/etc/motd write bits" FAIL high \
      "/etc/motd mode=$FMW_MODE group-write=$FMW_GW other-write=$FMW_OW" \
      "/etc/motd is writable by group or other, so a non-owner subject could tamper with the text displayed at login." \
      "remove group and other write bits after validation: 'chmod og-w /etc/motd'; PTxray recommends this command and never executes it." \
      "cis-l1"
  else
    add security fileperm_motd_write "/etc/motd write bits" PASS low \
      "/etc/motd mode=$FMW_MODE group-write=$FMW_GW other-write=$FMW_OW" \
      "/etc/motd is not writable by group or other." \
      "n/a" "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
# 4.9.1 - address-space layout randomization strength, 32- and 64-bit.
# vmo -aF lists kernel tunables in "key = value" form. Six aslr* tunables
# govern ASLR: the system-wide switch (aslr), per-ABI override switches
# (aslr32, aslr64), per-ABI entropy-bit counts (aslr32r, aslr64r), and the
# legacy global disable (aslr_r). Full strength requires all six present with
# exact compliant values; any deviation weakens randomization.

ASLR=$(aix aslr_tunables /usr/sbin/vmo -aF); ASLRRC=$?
if [ "$ASLRRC" -ne 0 ]; then
  add security system_aslr "System ASLR" NOT_ASSESSED med "not assessed - vmo probe failed (rc=$ASLRRC)" \
      "ASLR state could not be read because 'vmo -aF' failed (rc=$ASLRRC); without the six aslr tunables no strength verdict is possible." \
      "run '/usr/sbin/vmo -aF' manually and confirm it succeeds, then rerun PTxray." "cis-l1"
elif [ -z "$ASLR" ]; then
  add security system_aslr "System ASLR" NOT_ASSESSED med "not assessed - vmo returned no output (rc=0)" \
      "ASLR state could not be read because 'vmo -aF' produced no output; the aslr tunables are not observable." \
      "run '/usr/sbin/vmo -aF' manually and confirm it lists tunables, then rerun PTxray." "cis-l1"
else
  ASLRV=$(printf '%s\n' "$ASLR" | awk '
    {
      if ($0 ~ /^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*=[[:space:]]*[^[:space:]]/) {
        tunable++
        key = $1
        if (key == "aslr" || key == "aslr32" || key == "aslr64" ||
            key == "aslr32r" || key == "aslr64r" || key == "aslr_r") {
          val = $0
          sub(/^[[:space:]]*[^=]*=[[:space:]]*/, "", val)
          sub(/[[:space:]]+$/, "", val)
          gsub(/"/, "", val)
          seen[key] = 1
          got[key] = val
        }
      }
    }
    END {
      if (tunable == 0) {
        print "NOT_ASSESSED"
        exit 0
      }
      if (!(seen["aslr"] && seen["aslr32"] && seen["aslr64"] &&
            seen["aslr32r"] && seen["aslr64r"] && seen["aslr_r"])) {
        print "FAIL missing"
        exit 0
      }
      if (got["aslr"] != "2")    { print "FAIL aslr=" got["aslr"] " (required 2)";    exit 0 }
      if (got["aslr32"] != "0")  { print "FAIL aslr32=" got["aslr32"] " (required 0)";  exit 0 }
      if (got["aslr64"] != "0")  { print "FAIL aslr64=" got["aslr64"] " (required 0)";  exit 0 }
      if (got["aslr32r"] != "333")    { print "FAIL aslr32r=" got["aslr32r"] " (required 333)";    exit 0 }
      if (got["aslr64r"] != "33333")  { print "FAIL aslr64r=" got["aslr64r"] " (required 33333)";  exit 0 }
      if (got["aslr_r"] != "0")  { print "FAIL aslr_r=" got["aslr_r"] " (required 0)";  exit 0 }
      print "PASS"
    }')
  case "$ASLRV" in
    PASS)
      add security system_aslr "System ASLR" PASS low "aslr=2 aslr32=0 aslr64=0 aslr32r=333 aslr64r=33333 aslr_r=0" \
          "All six ASLR tunables are present and at full strength for both 32-bit and 64-bit processes." \
          "n/a" "cis-l1"
      ;;
    "FAIL missing")
      add security system_aslr "System ASLR" FAIL med "one or more aslr tunables absent; required aslr=2 aslr32=0 aslr64=0 aslr32r=333 aslr64r=33333 aslr_r=0" \
          "vmo reported tunables but not all six aslr entries; missing aslr tunables means ASLR is not configured to the mandated strength." \
          "confirm the six aslr tunables are defined and at full strength: aslr=2 aslr32=0 aslr64=0 aslr32r=333 aslr64r=33333 aslr_r=0" "cis-l1"
      ;;
    FAIL*)
      add security system_aslr "System ASLR" FAIL med "${ASLRV#FAIL }" \
          "At least one ASLR tunable is present but not at the mandated full-strength value, weakening address-space randomization." \
          "set the deviating tunable(s) back to full strength: aslr=2 aslr32=0 aslr64=0 aslr32r=333 aslr64r=33333 aslr_r=0" "cis-l1"
      ;;
    *)
      add security system_aslr "System ASLR" NOT_ASSESSED med "not assessed - vmo output unparseable (rc=0)" \
          "ASLR state could not be assessed because 'vmo -aF' produced no parseable tunable lines; the output shape is unknown." \
          "run '/usr/sbin/vmo -aF' manually and confirm it lists 'key = value' tunable lines, then rerun PTxray." "cis-l1"
      ;;
  esac
fi
_AIXRAY_SESSION_KEYS=""
  # pw_blank_absent — no account stanza in /etc/security/passwd may carry a
  # password field with nothing stored after the '='. CIS 5.1.1.
  # The readability gate must precede the scan: the scan pipeline exits 0 on
  # empty input, so a missing file would otherwise masquerade as a clean scan.
  typeset PW_READ_RC PW_SCAN_RAW PW_SCAN_RC
  typeset PW_STATUS PW_OBSERVED PW_REASON
  typeset PW_READ_RAW PW_ACCOUNTS

  if [ "${MYUID:-0}" != "0" ]; then
    PW_STATUS=NOT_ASSESSED
    PW_REASON="requires root; capture not executed"
  else
    PW_READ_RAW=$(aix pw_blank_readable test -r /etc/security/passwd)
    PW_READ_RC=$?
    case "$PW_READ_RC" in
      0)
        PW_SCAN_RAW=$(aix pw_blank_scan /usr/bin/egrep -p "password = +$" /etc/security/passwd)
        PW_SCAN_RC=$?
        if [ "$PW_SCAN_RC" -ge 2 ]; then
          PW_STATUS=NOT_ASSESSED
          PW_REASON="probe failed (rc=$PW_SCAN_RC)"
        elif [ -z "$PW_SCAN_RAW" ]; then
          PW_STATUS=PASS
          PW_OBSERVED="no account stanza in /etc/security/passwd carries a blank password"
        else
          PW_ACCOUNTS=$(printf '%s\n' "$PW_SCAN_RAW" | awk '
            /^[^:[:space:]][^:]*:[[:space:]]*$/ {
              owner = $0
              sub(/:[[:space:]]*$/, "", owner)
            }
            /password = +$/ {
              if (owner != "" && !(owner in seen)) {
                seen[owner] = 1
                acc = (acc == "" ? owner : acc ", " owner)
              }
            }
            END {
              if (acc != "") print acc
            }')
          PW_STATUS=FAIL
          if [ -n "$PW_ACCOUNTS" ]; then
            PW_OBSERVED="blank password in /etc/security/passwd: $PW_ACCOUNTS"
          else
            PW_OBSERVED="blank-password stanza matched /etc/security/passwd but no account name was recoverable from the captured lines"
          fi
        fi
        ;;
      *)
        PW_STATUS=NOT_ASSESSED
        PW_REASON="/etc/security/passwd absent or unreadable (rc=$PW_READ_RC)"
        ;;
    esac
  fi

  case "$PW_STATUS" in
    PASS)
      add security pw_blank_absent "Accounts with blank passwords" PASS high \
          "$PW_OBSERVED" \
          "Every account stanza stores a value after 'password =', so no account can be signed into without presenting a password." \
          "n/a" "cis-l1"
      ;;
    FAIL)
      add security pw_blank_absent "Accounts with blank passwords" FAIL high \
          "$PW_OBSERVED" \
          "At least one account stanza has nothing stored after 'password =', so that account can be signed into without supplying a credential." \
          "give each listed account a password ('passwd <user>') or disable it ('chsec -f /etc/security/passwd -s <user> -a flags=ADMIN_LOCKED'); PTxray recommends these commands and never executes them." \
          "cis-l1"
      ;;
    *)
      add security pw_blank_absent "Accounts with blank passwords" NOT_ASSESSED high \
          "not assessed — blank-password scan $PW_REASON" \
          "PTxray could not read /etc/security/passwd trustworthily, so it cannot verify whether any account has a blank password." \
          "verify /etc/security/passwd is present and readable as root, then rerun PTxray." \
          "cis-l1"
      ;;
  esac
_AIXRAY_SESSION_KEYS=""
# account_uid_duplicate — duplicate UID or username boundary in /etc/passwd.
typeset ACD_RAW ACD_RC ACD_DUPS ACD_AWK_RC

ACD_RAW=$(aix passwd_file cat /etc/passwd)
ACD_RC=$?

if [ "$ACD_RC" -ne 0 ]; then
  add security account_uid_duplicate "/etc/passwd duplicate account identities" NOT_ASSESSED med \
      "not assessed — /etc/passwd capture failed (rc=$ACD_RC)" \
      "PTxray could not read /etc/passwd, so it cannot determine whether any two entries share a UID or a username." \
      "run 'cat /etc/passwd', correct the capture or path problem, and rerun PTxray." \
      "cis-l1"
elif [ -z "$ACD_RAW" ]; then
  # Zero bytes is not evidence of uniqueness. The awk duplicate scan on an
  # empty passwd file produces no output and exits 0, which used to render
  # PASS — a clean bill of health over zero evidence. Rendering PASS here
  # would be a false pass.
  add security account_uid_duplicate "/etc/passwd duplicate account identities" NOT_ASSESSED med \
      "not assessed — passwd file capture is empty" \
      "The /etc/passwd capture contained no records, so PTxray has no evidence either way about UID and username uniqueness." \
      "confirm /etc/passwd is readable and non-empty, then rerun PTxray." \
      "cis-l1"
else
  ACD_DUPS=$(printf '%s\n' "$ACD_RAW" | awk -F: '
    NF < 3 { next }
    { uid[$3]++; user[$1]++ }
    END {
      dup = ""
      for (u in uid) if (uid[u] > 1) dup = dup " uid=" u
      for (n in user) if (user[n] > 1) dup = dup " user=" n
      if (dup != "") {
        print substr(dup, 2)
        exit 1
      }
    }
  ')
  ACD_AWK_RC=$?
  case "$ACD_AWK_RC" in
    0)
      add security account_uid_duplicate "/etc/passwd duplicate account identities" PASS med \
          "no duplicate UIDs or usernames in /etc/passwd" \
          "Every /etc/passwd entry has a UID and a username that no other entry shares." \
          "n/a" "cis-l1"
      ;;
    1)
      add security account_uid_duplicate "/etc/passwd duplicate account identities" FAIL high \
          "duplicate account identity: $ACD_DUPS" \
          "Two or more entries in /etc/passwd share a UID or a username, so an account identity is not unique." \
          "$ACD_DUPS" "cis-l1"
      ;;
    *)
      add security account_uid_duplicate "/etc/passwd duplicate account identities" NOT_ASSESSED med \
          "not assessed — duplicate scan failed (awk rc=$ACD_AWK_RC)" \
          "PTxray could not parse the captured /etc/passwd content, so it cannot determine whether duplicate account identities exist." \
          "run 'cat /etc/passwd', correct the capture or path problem, and rerun PTxray." \
          "cis-l1"
      ;;
  esac
fi
_AIXRAY_SESSION_KEYS=""
# group_gid_duplicate — every /etc/group entry must carry a unique numeric
# GID (field 3) and a unique group name (field 1).  One raw capture of
# /etc/group; all deduplication and counting happens in the check's own awk.
typeset GGD_RAW GGD_RC
typeset GGD_STATUS GGD_SEV GGD_OBSERVED GGD_MEANING GGD_FIX
typeset GGD_GID_LIST GGD_NAME_LIST GGD_DUP_GIDS GGD_DUP_NAMES GGD_AWK_RC GGD_AWK_OUT

GGD_RAW=$(aix group_file cat /etc/group)
GGD_RC=$?

if [ "$GGD_RC" -ne 0 ]; then
  GGD_STATUS=NOT_ASSESSED
  GGD_SEV=low
  GGD_OBSERVED="not assessed — group file probe failed (rc=$GGD_RC)"
  GGD_MEANING="PTxray could not reduce /etc/group to its duplicate GIDs and names, so group uniqueness is unproven."
  GGD_FIX="confirm /etc/group is readable, then rerun PTxray."
elif [ -z "$GGD_RAW" ]; then
  # Zero bytes is not evidence of uniqueness. Under the old two-probe form,
  # empty output was the reduction's own answer -- `uniq -d` printing nothing
  # genuinely proved no value repeated. This probe captures the raw file, where
  # empty means only that nothing was read, so the same emptiness that used to
  # justify PASS now justifies nothing at all. Rendering PASS here would be a
  # clean bill issued over no evidence.
  GGD_STATUS=NOT_ASSESSED
  GGD_SEV=low
  GGD_OBSERVED="not assessed — group file capture is empty"
  GGD_MEANING="The /etc/group capture contained no records, so PTxray has no evidence either way about GID and group-name uniqueness."
  GGD_FIX="confirm /etc/group is readable and non-empty, then rerun PTxray."
else
  GGD_AWK_OUT=$(printf '%s' "$GGD_RAW" | awk -F: '
    NF < 3 { bad = 1; next }
    {
      pair = $1 FS $3
      if (!(pair in seen)) {
        seen[pair] = 1
        gid_count[$3]++
        name_count[$1]++
      }
    }
    END {
      if (bad) { print "UNPARSEABLE"; exit 2 }
      has = 0
      for (g in gid_count) if (gid_count[g] > 1) { print "G:" g; has = 1 }
      for (n in name_count) if (name_count[n] > 1) { print "N:" n; has = 1 }
      if (has) exit 1
    }
  ')
  GGD_AWK_RC=$?

  case "$GGD_AWK_RC" in
    0)
      GGD_STATUS=PASS
      GGD_SEV=low
      GGD_OBSERVED="all /etc/group GIDs and group names are unique"
      GGD_MEANING="No two /etc/group entries share a GID or a group name; group identity is unambiguous."
      GGD_FIX="n/a"
      ;;
    1)
      GGD_STATUS=FAIL
      GGD_SEV=high
      GGD_DUP_GIDS=$(printf '%s\n' "$GGD_AWK_OUT" | sed -n 's/^G://p' | sort -n)
      GGD_DUP_NAMES=$(printf '%s\n' "$GGD_AWK_OUT" | sed -n 's/^N://p' | sort)
      GGD_OBSERVED=""
      if [ -n "$GGD_DUP_GIDS" ]; then
        GGD_GID_LIST=$(printf '%s\n' "$GGD_DUP_GIDS" | tr '\n' ' ')
        GGD_OBSERVED="duplicate group GID(s): $GGD_GID_LIST"
      fi
      if [ -n "$GGD_DUP_NAMES" ]; then
        GGD_NAME_LIST=$(printf '%s\n' "$GGD_DUP_NAMES" | tr '\n' ' ')
        if [ -n "$GGD_OBSERVED" ]; then
          GGD_OBSERVED="$GGD_OBSERVED; duplicate group name(s): $GGD_NAME_LIST"
        else
          GGD_OBSERVED="duplicate group name(s): $GGD_NAME_LIST"
        fi
      fi
      GGD_MEANING="Two or more /etc/group entries share a GID or a group name, so group identity is ambiguous."
      GGD_FIX="give every group a unique numeric GID and a unique name via the directory service, then rerun PTxray."
      ;;
    *)
      GGD_STATUS=NOT_ASSESSED
      GGD_SEV=low
      GGD_OBSERVED="not assessed — group file capture unparseable"
      GGD_MEANING="PTxray could not reduce /etc/group to its duplicate GIDs and names, so group uniqueness is unproven."
      GGD_FIX="confirm /etc/group is readable, then rerun PTxray."
      ;;
  esac
fi

add security group_gid_duplicate "Group GID and name uniqueness" \
  "$GGD_STATUS" "$GGD_SEV" "$GGD_OBSERVED" \
  "$GGD_MEANING" "$GGD_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # account_pwdck_valid — account database structural integrity via pwdck -n ALL.
  #
  # The probe runs through aixv (stderr merged), not aix, because pwdck writes
  # its entire defect report to STDERR and exits 114 with a COMPLETELY EMPTY
  # stdout. Under aix()'s blanket '2>/dev/null' this check saw rc=114 with no
  # output and refused — and on both lab boxes (7300-04-00-2546 and
  # 7200-05-11-2546, 2026-08-05) that refusal was hiding a genuine FAIL. rc=114
  # is how pwdck reports that it FOUND PROBLEMS; the diagnostics it printed are
  # the finding.
  #
  # '-n' is report-only ("report errors but do not fix"), so the probe never
  # repairs anything. The flag must not be changed.
  typeset PWDCK_RAW PWDCK_RC PWDCK_SUMMARY PWDCK_REST
  typeset PWDCK_LINES PWDCK_ACCOUNTS PWDCK_NAMES PWDCK_OBSERVED

  PWDCK_RAW=""
  PWDCK_RC=126
  PWDCK_SUMMARY=""
  PWDCK_REST=""
  PWDCK_LINES=0
  PWDCK_ACCOUNTS=0
  PWDCK_NAMES=""
  PWDCK_OBSERVED=""

  PWDCK_RAW=$(aixv pwdck_scan pwdck -n ALL)
  PWDCK_RC=$?

  if [ "$PWDCK_RC" -eq 0 ] && [ -z "$PWDCK_RAW" ]; then
    add security account_pwdck_valid "account database integrity" PASS high \
      "pwdck -n ALL exits 0 with no output" \
      "Every local account /etc/passwd and /etc/security/passwd entry is self-consistent." \
      "n/a" "cis-l1"
  elif [ "$PWDCK_RC" -eq 114 ] && [ -n "$PWDCK_RAW" ]; then
    # Summarise the defect report: how many diagnostic lines it holds, and
    # which accounts they name. pwdck quotes every account name it reports, so
    # the quoted tokens are the affected accounts in first-mention order.
    PWDCK_SUMMARY=$(printf '%s\n' "$PWDCK_RAW" | awk '
      NF { lines++ }
      {
        text = $0
        while (match(text, /"[^"]*"/)) {
          name = substr(text, RSTART + 1, RLENGTH - 2)
          text = substr(text, RSTART + RLENGTH)
          if (name != "" && !(name in seen)) {
            seen[name] = 1
            count++
            order[count] = name
          }
        }
      }
      END {
        shown = count
        if (shown > 8) shown = 8
        joined = ""
        for (i = 1; i <= shown; i++) {
          if (i == 1) {
            joined = order[i]
          } else {
            joined = joined ", " order[i]
          }
        }
        if (count > shown) {
          joined = joined ", and " (count - shown) " more"
        }
        printf "%d|%d|%s\n", lines + 0, count + 0, joined
      }')
    PWDCK_LINES=${PWDCK_SUMMARY%%\|*}
    PWDCK_REST=${PWDCK_SUMMARY#*\|}
    PWDCK_ACCOUNTS=${PWDCK_REST%%\|*}
    PWDCK_NAMES=${PWDCK_REST#*\|}
    if [ -n "$PWDCK_NAMES" ]; then
      PWDCK_OBSERVED="pwdck -n ALL exited 114 with $PWDCK_LINES defect lines naming $PWDCK_ACCOUNTS accounts: $PWDCK_NAMES"
    else
      PWDCK_OBSERVED="pwdck -n ALL exited 114 with $PWDCK_LINES defect lines"
    fi
    add security account_pwdck_valid "account database integrity" FAIL high \
      "$PWDCK_OBSERVED" \
      "pwdck -n ALL exited 114, which is how it reports that it found problems, and it wrote defect lines, so at least one /etc/passwd or /etc/security/passwd stanza is inconsistent." \
      "inspect the reported stanzas and repair the malformed account entries; PTxray recommends a review but never executes a repair." \
      "cis-l1"
  else
    add security account_pwdck_valid "account database integrity" NOT_ASSESSED high \
      "not assessed — pwdck -n ALL returned rc=$PWDCK_RC with an output shape this check cannot judge" \
      "pwdck -n ALL produced neither of its two conclusive results (rc=0 with no output, or rc=114 with a defect report), so the account database state is unknown." \
      "confirm pwdck is present and the capture is healthy, then rerun PTxray." \
      "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
  # pw_maxage_cis — default password maximum age in the default stanza, 1-52 weeks.
  # This diagnostic fragment accepts only one exact attribute-scoped assignment.
  typeset MAXAGE_CIS_RAW MAXAGE_CIS_RC MAXAGE_CIS_PARSED MAXAGE_CIS_STATE
  typeset MAXAGE_CIS_VALUE MAXAGE_CIS_STATUS MAXAGE_CIS_OBSERVED MAXAGE_CIS_REASON

  MAXAGE_CIS_RAW=""
  MAXAGE_CIS_RC=126
  MAXAGE_CIS_PARSED=""
  MAXAGE_CIS_STATE=""
  MAXAGE_CIS_VALUE=""
  MAXAGE_CIS_STATUS=NOT_ASSESSED
  MAXAGE_CIS_OBSERVED=""
  MAXAGE_CIS_REASON=""

  if [ "${MYUID:-0}" != "0" ]; then
    MAXAGE_CIS_REASON="requires root privileges"
  else
    MAXAGE_CIS_RAW=$(aix pw_maxage_cis lssec -f /etc/security/user -s default -a maxage)
    MAXAGE_CIS_RC=$?
    if [ "$MAXAGE_CIS_RC" -ne 0 ]; then
      MAXAGE_CIS_REASON="capture failed (rc=$MAXAGE_CIS_RC)"
    elif [ -z "$MAXAGE_CIS_RAW" ]; then
      MAXAGE_CIS_REASON="capture returned empty output"
    else
      MAXAGE_CIS_PARSED=$(printf '%s\n' "$MAXAGE_CIS_RAW" | awk '
        /^[[:space:]]*$/ { next }
        {
          rows++
          if ($0 !~ /^[[:space:]]*default maxage=[0-9]+[[:space:]]*$/) {
            bad=1
            next
          }
          value=$0
          sub(/^[[:space:]]*default maxage=/, "", value)
          sub(/[[:space:]]*$/, "", value)
          if (value ~ /^0[0-9]/) {
            leading=1
          } else if (length("" value) > 2) {
            over=1
          } else if (length("" value) == 2) {
            if (value > "52") { over=1 } else { within=1 }
          } else {
            if (value == "0") { zero=1 } else { within=1 }
          }
        }
        END {
          if (rows != 1 || bad) {
            print "bad|"
          } else if (leading) {
            print "leading|"
          } else if (over) {
            print "over|" value
          } else if (zero) {
            print "zero|" value
          } else if (within) {
            print "within|" value
          } else {
            print "bad|"
          }
        }')
      MAXAGE_CIS_STATE=${MAXAGE_CIS_PARSED%%\|*}
      MAXAGE_CIS_VALUE=${MAXAGE_CIS_PARSED#*\|}
      case "$MAXAGE_CIS_STATE" in
        within)
          MAXAGE_CIS_STATUS=PASS
          MAXAGE_CIS_OBSERVED="maxage=$MAXAGE_CIS_VALUE"
          ;;
        zero)
          MAXAGE_CIS_STATUS=FAIL
          MAXAGE_CIS_OBSERVED="maxage=$MAXAGE_CIS_VALUE; required between 1 and 52 inclusive"
          ;;
        over)
          MAXAGE_CIS_STATUS=FAIL
          MAXAGE_CIS_OBSERVED="maxage=$MAXAGE_CIS_VALUE; required between 1 and 52 inclusive"
          ;;
        leading)
          MAXAGE_CIS_REASON="value had leading zeros"
          ;;
        *)
          MAXAGE_CIS_REASON="output was not one exact unsigned-decimal assignment"
          ;;
      esac
    fi
  fi

  case "$MAXAGE_CIS_STATUS" in
    PASS)
      add security pw_maxage_cis "Default password maximum age" PASS high \
          "$MAXAGE_CIS_OBSERVED" \
          "The default stanza's maxage value keeps inherited passwords expiring within the approved 1-52 week window." \
          "n/a" "cis-l1"
      ;;
    FAIL)
      add security pw_maxage_cis "Default password maximum age" FAIL high \
          "$MAXAGE_CIS_OBSERVED" \
          "The default stanza's maxage value is outside the approved 1-52 week window; zero disables password expiry and values above 52 keep passwords valid too long." \
          "after access-impact review, set the boundary with 'chsec -f /etc/security/user -s default -a maxage=N'; PTxray only recommends this command." \
          "cis-l1"
      ;;
    *)
      add security pw_maxage_cis "Default password maximum age" NOT_ASSESSED high \
          "not assessed — lssec maxage $MAXAGE_CIS_REASON" \
          "PTxray did not obtain one trustworthy numeric default value." \
          "run 'lssec -f /etc/security/user -s default -a maxage' as root, resolve the evidence problem, and rerun." \
          "cis-l1"
      ;;
  esac
_AIXRAY_SESSION_KEYS=""
  # sudo_version — the sudo command, when installed, must report a release at
  # or above the patched baseline. Absence is determinate non-applicability;
  # an older release is a FAIL; unreadable or unrecognizable version evidence
  # is NOT_ASSESSED.
  typeset SU_BIN_RAW SU_BIN_RC SU_VER_RAW SU_VER_RC SU_VER_STATE
  typeset SU_VER_VERDICT SU_VER_DETAIL

  SU_BIN_RAW=$(aix sudo_binary ls -ld /usr/bin/sudo)
  SU_BIN_RC=$?

  case "$SU_BIN_RC" in
    2)
      add security sudo_version "sudo version currency" NOT_APPLICABLE low \
        "sudo binary absent (/usr/bin/sudo)" \
        "The sudo command is not installed, so the sudo release requirement does not apply to this host." \
        "n/a" "cis-l2"
      F_EVIDENCE_COMMANDS[$((NFIND-1))]="ls -ld /usr/bin/sudo"
      ;;
    0)
      SU_VER_RAW=$(aix sudo_version /usr/bin/sudo --version)
      SU_VER_RC=$?
      if [ "$SU_VER_RC" -ne 0 ]; then
        add security sudo_version "sudo version currency" NOT_ASSESSED low \
          "not assessed — sudo --version probe failed (rc=$SU_VER_RC)" \
          "PTxray could not read the installed sudo release, so it cannot judge whether the version requirement is met." \
          "run /usr/bin/sudo --version to confirm the installed release, then rerun PTxray." "cis-l2"
      elif [ -z "$SU_VER_RAW" ]; then
        add security sudo_version "sudo version currency" NOT_ASSESSED low \
          "not assessed — sudo --version returned no version text (rc=0)" \
          "PTxray obtained no version line from the sudo binary, so the installed release is unknown." \
          "run /usr/bin/sudo --version to confirm the installed release, then rerun PTxray." "cis-l2"
      else
        SU_VER_STATE=$(printf '%s\n' "$SU_VER_RAW" | awk '
          {
            if (verdict != "") next
            if ($0 ~ /^[Ss]udo version [0-9]/) {
              line=$0
              sub(/^[Ss]udo version[ \t]+/, "", line)
              token=line
              sub(/[ \t].*$/, "", token)
              if (token !~ /^[0-9]+[.][0-9]+[.][0-9]+/) {
                verdict="UNPARSEABLE"
                next
              }
              detail=token
              maj=token
              sub(/\..*$/, "", maj)
              rest=token
              sub(/^[0-9]+[.]/, "", rest)
              min=rest
              sub(/\..*$/, "", min)
              rest=rest
              sub(/^[0-9]+[.]/, "", rest)
              pat=rest
              sub(/[^0-9].*$/, "", pat)
              pl=rest
              sub(/^[0-9]+/, "", pl)
              haspl=0
              pln=0
              if (pl ~ /^p[0-9]+$/) {
                haspl=1
                sub(/^p/, "", pl)
                pln=pl+0
              }
              if (maj+0 < 1) { verdict="FAIL"; next }
              if (maj+0 > 1) { verdict="PASS"; next }
              if (min+0 < 9) { verdict="FAIL"; next }
              if (min+0 > 9) { verdict="PASS"; next }
              if (pat+0 < 17) { verdict="FAIL"; next }
              if (pat+0 > 17) { verdict="PASS"; next }
              if (haspl && pln < 1) { verdict="FAIL"; next }
              verdict="PASS"
            }
          }
          END {
            if (verdict == "") verdict="UNPARSEABLE"
            print verdict "|" detail
          }
        ')
        SU_VER_VERDICT=${SU_VER_STATE%%\|*}
        SU_VER_DETAIL=${SU_VER_STATE#*\|}
        case "$SU_VER_VERDICT" in
          PASS)
            add security sudo_version "sudo version currency" PASS low \
              "installed sudo $SU_VER_DETAIL meets the required release" \
              "The installed sudo command reports a release at or above the required baseline." \
              "n/a" "cis-l2"
            ;;
          FAIL)
            add security sudo_version "sudo version currency" FAIL high \
              "installed sudo $SU_VER_DETAIL is older than the required release" \
              "The installed sudo command reports a release below the required baseline, so defects corrected in later releases are not covered by this build." \
              "update the sudo package to the required release or later, then rerun PTxray." "cis-l2"
            ;;
          *)
            add security sudo_version "sudo version currency" NOT_ASSESSED low \
              "not assessed — sudo --version output unparseable (rc=0)" \
              "PTxray found no recognizable version line in the sudo --version output, so the installed release is unknown." \
              "run /usr/bin/sudo --version to confirm the installed release, then rerun PTxray." "cis-l2"
            ;;
        esac
      fi
      ;;
    *)
      add security sudo_version "sudo version currency" NOT_ASSESSED low \
        "not assessed — sudo presence probe failed (rc=$SU_BIN_RC)" \
        "PTxray could not determine whether the sudo command is installed, so the version requirement is unassessed." \
        "confirm /usr/bin/sudo is accessible and readable, then rerun PTxray." "cis-l2"
      ;;
  esac
_AIXRAY_SESSION_KEYS=""
  # ck-sudo-syslog-priority — sudo syslog priority / logfile audit destination.
  # CIS L2 numeric mapping 6.1.2.  sudo is compliant while at least one syslog
  # priority is active, or while a disabled priority is backed by a configured
  # logfile.  Only a disabled priority with no logfile fails.
  typeset SSP_SUDOERS_RAW SSP_SUDOERS_RC SSP_D_RAW SSP_D_RC
  typeset SSP_BADPRI_RAW SSP_BADPRI_RC SSP_GOODPRI_RAW SSP_GOODPRI_RC
  typeset SSP_LOGFILE_RAW SSP_LOGFILE_RC
  typeset SSP_FILE_LIST SSP_STATUS SSP_SEV SSP_OBS SSP_MEAN SSP_FIX

  SSP_SUDOERS_RAW=$(aix sudoers_exists ls -ld /etc/sudoers)
  SSP_SUDOERS_RC=$?

  if [ "$SSP_SUDOERS_RC" -eq 2 ] && [ -z "$SSP_SUDOERS_RAW" ]; then
    SSP_STATUS=NOT_APPLICABLE
    SSP_SEV=low
    SSP_OBS="sudo not installed - /etc/sudoers absent (ls rc=2)"
    SSP_MEAN="There is no sudoers file, so no sudo configuration constrains a logging destination."
    SSP_FIX="n/a"
  elif [ "$SSP_SUDOERS_RC" -ne 0 ] || [ -z "$SSP_SUDOERS_RAW" ]; then
    SSP_STATUS=NOT_ASSESSED
    SSP_SEV=low
    SSP_OBS="not assessed - /etc/sudoers stat probe gave no usable result (rc=$SSP_SUDOERS_RC)"
    SSP_MEAN="PTxray did not obtain trustworthy evidence that a sudoers file exists."
    SSP_FIX="verify /etc/sudoers is present and statable, then rerun PTxray."
  else
    SSP_FILE_LIST="/etc/sudoers"
    SSP_D_RAW=$(aix sudoers_d_exists ls -ld /etc/sudoers.d)
    SSP_D_RC=$?
    if [ "$SSP_D_RC" -eq 0 ]; then
      case "$SSP_D_RAW" in
        d*) SSP_FILE_LIST="/etc/sudoers /etc/sudoers.d/*" ;;
      esac
    fi

    SSP_BADPRI_RAW=$(aix sudoers_badpri_none grep -Ei '^\s*Defaults\s+syslog_badpri=none' $SSP_FILE_LIST)
    SSP_BADPRI_RC=$?
    SSP_GOODPRI_RAW=$(aix sudoers_goodpri_none grep -Ei '^\s*Defaults\s+syslog_goodpri=none' $SSP_FILE_LIST)
    SSP_GOODPRI_RC=$?
    SSP_LOGFILE_RAW=$(aix sudoers_logfile grep -Ei '^\s*Defaults\s+logfile=\S+' $SSP_FILE_LIST)
    SSP_LOGFILE_RC=$?

    if [ "$SSP_BADPRI_RC" -gt 1 ] || [ "$SSP_GOODPRI_RC" -gt 1 ] || [ "$SSP_LOGFILE_RC" -gt 1 ]; then
      SSP_STATUS=NOT_ASSESSED
      SSP_SEV=low
      SSP_OBS="not assessed - a sudoers probe failed (badpri rc=$SSP_BADPRI_RC goodpri rc=$SSP_GOODPRI_RC logfile rc=$SSP_LOGFILE_RC)"
      SSP_MEAN="PTxray could not read every path in the sudoers file list, so the sudo logging state is unknown."
      SSP_FIX="make /etc/sudoers and any /etc/sudoers.d entries readable, then rerun PTxray."
    elif [ "$SSP_BADPRI_RC" -eq 1 ] && [ "$SSP_GOODPRI_RC" -eq 1 ]; then
      SSP_STATUS=PASS
      SSP_SEV=low
      SSP_OBS="neither syslog_badpri nor syslog_goodpri is set to none"
      SSP_MEAN="sudo activity reaches a syslog destination at both priority thresholds."
      SSP_FIX="n/a"
    elif [ "$SSP_LOGFILE_RC" -eq 0 ]; then
      SSP_STATUS=PASS
      SSP_SEV=low
      SSP_OBS="a syslog priority is set to none but a dedicated logfile is configured"
      SSP_MEAN="sudo activity is recorded to the configured logfile even though the syslog priority is disabled."
      SSP_FIX="n/a"
    else
      SSP_STATUS=FAIL
      SSP_SEV=med
      SSP_OBS="a syslog priority is set to none and no dedicated logfile is configured"
      SSP_MEAN="sudo activity has no configured logging destination, so command execution may leave no audit trail."
      SSP_FIX="set syslog_badpri and syslog_goodpri to a real facility.priority, or configure a Defaults logfile; PTxray only recommends these actions."
    fi
  fi

  add security sudo_syslog_priority "sudo logging destination" \
    "$SSP_STATUS" "$SSP_SEV" "$SSP_OBS" "$SSP_MEAN" "$SSP_FIX" "cis-l2"
  if [ "$SSP_STATUS" = "NOT_APPLICABLE" ]; then
    F_EVIDENCE_COMMANDS[$((NFIND-1))]="ls -ld /etc/sudoers"
  fi
_AIXRAY_SESSION_KEYS=""
  # sudo_use_pty — assess that the sudoers tree declares use_pty without negation.
  typeset SUDO_PTY_USE_OUT SUDO_PTY_USE_RC SUDO_PTY_NO_OUT SUDO_PTY_NO_RC
  typeset SUDO_PTY_STATUS SUDO_PTY_OBSERVED SUDO_PTY_MEANING SUDO_PTY_FIX SUDO_PTY_REASON
  SUDO_PTY_STATUS=NOT_ASSESSED
  SUDO_PTY_OBSERVED=''
  SUDO_PTY_MEANING='PTxray could not establish whether sudo runs each command inside an allocated pseudo-terminal.'
  SUDO_PTY_FIX='make the sudoers tree readable and rerun PTxray.'
  SUDO_PTY_REASON=''

  SUDO_PTY_USE_OUT=$(aix sudoers_use_pty grep -Eir '^\s*Defaults\s+([^#]+,\s*)?use_pty(,\s+\S+\s*)*(\s+#.*)?$' /etc/sudoers*) # network-lint: allow -- reads the LOCAL sudoers tree only
  SUDO_PTY_USE_RC=$?
  SUDO_PTY_NO_OUT=$(aix sudoers_no_use_pty grep -Eir '^\s*Defaults\s+([^#]+,\s*)?!use_pty(,\s+\S+\s*)*(\s+#.*)?$' /etc/sudoers*) # network-lint: allow -- reads the LOCAL sudoers tree only
  SUDO_PTY_NO_RC=$?

  case "$SUDO_PTY_USE_RC:$SUDO_PTY_NO_RC" in
    2:2)
      SUDO_PTY_REASON='sudoers tree unreadable (rc=2 on both probes)'
      ;;
    *:0)
      SUDO_PTY_STATUS=FAIL
      SUDO_PTY_OBSERVED='Defaults !use_pty present'
      SUDO_PTY_MEANING='sudoers explicitly disables pseudo-terminal allocation for sudo commands.'
      SUDO_PTY_FIX="remove the '!use_pty' Defaults line and confirm 'use_pty' is declared in /etc/sudoers or an included fragment; PTxray only recommends these actions."
      ;;
    0:*)
      SUDO_PTY_STATUS=PASS
      SUDO_PTY_OBSERVED='Defaults use_pty present'
      SUDO_PTY_MEANING='sudoers requires sudo to allocate a pseudo-terminal for each command.'
      SUDO_PTY_FIX='n/a'
      ;;
    1:1|1:2|2:1)
      SUDO_PTY_STATUS=FAIL
      SUDO_PTY_OBSERVED='Defaults use_pty absent'
      SUDO_PTY_MEANING='sudoers does not require pseudo-terminal allocation for sudo commands.'
      SUDO_PTY_FIX="declare 'Defaults use_pty' in /etc/sudoers or an included fragment; PTxray only recommends these actions."
      ;;
    *)
      SUDO_PTY_REASON="unexpected probe result (use_pty rc=$SUDO_PTY_USE_RC, no_use_pty rc=$SUDO_PTY_NO_RC)"
      ;;
  esac

  if [ "$SUDO_PTY_STATUS" = NOT_ASSESSED ]; then
    SUDO_PTY_OBSERVED="not assessed — $SUDO_PTY_REASON"
  fi
  add security sudo_use_pty "sudo pseudo-terminal allocation" "$SUDO_PTY_STATUS" med \
      "$SUDO_PTY_OBSERVED" "$SUDO_PTY_MEANING" "$SUDO_PTY_FIX" "cis-l2"
_AIXRAY_SESSION_KEYS=""
  # cron_at_deny_absent — at(1) authorization governed by an allow list, deny file absent.
  # Determinate absence is a verdict: at.deny absent is the compliant state here.
  typeset ATD_RAW ATD_RC ATA_RAW ATA_RC ATA_AWK_RC ATA_HAS_ROOT

  ATD_RAW=$(aix at_deny ls -ld /var/adm/cron/at.deny)
  ATD_RC=$?
  ATA_RAW=$(aix at_allow cat /var/adm/cron/at.allow)
  ATA_RC=$?

  ATA_HAS_ROOT=""
  if [ "$ATA_RC" -eq 0 ]; then
    printf '%s\n' "$ATA_RAW" | awk '
      {
        line=$0
        sub(/^[[:space:]]+/, "", line)
        sub(/[[:space:]]+$/, "", line)
        if (line == "root") found=1
      }
      END { if (found) exit 0; exit 1 }
    '
    ATA_AWK_RC=$?
    if [ "$ATA_AWK_RC" -eq 0 ]; then
      ATA_HAS_ROOT="yes"
    fi
  fi

  if [ "$ATD_RC" -eq 0 ] && [ -n "$ATD_RAW" ]; then
    add security cron_at_deny_absent "at(1) access control" FAIL high \
        "/var/adm/cron/at.deny present" \
        "/var/adm/cron/at.deny exists, so at(1) authorization is governed by a deny list; a user not listed is permitted by default instead of being required to appear in the allow list." \
        "remove /var/adm/cron/at.deny after confirming /var/adm/cron/at.allow authorizes the intended users; PTxray recommends this command and never executes it." \
        "cis-l1"
  elif [ "$ATD_RC" -ne 2 ]; then
    add security cron_at_deny_absent "at(1) access control" NOT_ASSESSED low \
        "not assessed — /var/adm/cron/at.deny probe failed (rc=$ATD_RC)" \
        "PTxray could not determine whether /var/adm/cron/at.deny exists, so the at(1) authorization state is unknown." \
        "run 'ls -ld /var/adm/cron/at.deny', correct the capture or path problem, and rerun PTxray." \
        "cis-l1"
  elif [ "$ATA_RC" -eq 0 ] && [ "$ATA_HAS_ROOT" = "yes" ]; then
    add security cron_at_deny_absent "at(1) access control" PASS low \
        "/var/adm/cron/at.deny absent; /var/adm/cron/at.allow authorizes root" \
        "/var/adm/cron/at.deny does not exist and /var/adm/cron/at.allow authorizes root, so at(1) access is governed by the allow list." \
        "n/a" "cis-l1"
  else
    add security cron_at_deny_absent "at(1) access control" FAIL high \
        "/var/adm/cron/at.allow does not authorize root" \
        "/var/adm/cron/at.allow is absent, unreadable, or does not list root, so at(1) access is not governed by an allow list that grants root." \
        "create or repair /var/adm/cron/at.allow so it lists root (and any site-authorized users); PTxray recommends this command and never executes it." \
        "cis-l1"
  fi
_AIXRAY_SESSION_KEYS=""
  # cron_cron_deny_absent — cron access must be governed by cron.allow alone:
  # /var/adm/cron/cron.deny must be absent and /var/adm/cron/cron.allow must
  # name root and adm (one full line each). Determinate absence via rc=2 from
  # ls is the compliant state; a present cron.deny is non-compliant.
  typeset CD_STAT CD_RC CD_STATE CA_RAW CA_RC CA_ROOT CA_ADM CA_REASON

  CD_STATE=''
  CA_REASON=''

  CD_STAT=$(aix cron_deny_stat ls -ld /var/adm/cron/cron.deny)
  CD_RC=$?
  if [ "$CD_RC" -eq 2 ] && [ -z "$CD_STAT" ]; then
    CD_STATE=absent
  elif [ "$CD_RC" -eq 0 ]; then
    CD_STATE=present
  else
    CD_STATE=unknown
  fi

  if [ "$CD_STATE" = unknown ]; then
    add security cron_cron_deny_absent "cron.deny absence and cron.allow membership" NOT_ASSESSED med \
        "not assessed — cron.deny stat probe failed (rc=$CD_RC)" \
        "PTxray could not determine whether /var/adm/cron/cron.deny exists, so it cannot judge cron access control." \
        "run 'ls -ld /var/adm/cron/cron.deny', correct the capture or path problem, and rerun PTxray." \
        "cis-l1"
  elif [ "$CD_STATE" = present ]; then
    add security cron_cron_deny_absent "cron.deny absence and cron.allow membership" FAIL high \
        "/var/adm/cron/cron.deny present" \
        "cron.deny exists, so any user not listed in it is allowed — the weaker access-control path." \
        "remove /var/adm/cron/cron.deny after confirming cron.allow lists the required users; PTxray recommends this action and never executes it." \
        "cis-l1"
  else
    CA_RAW=$(aix cron_allow_contents cat /var/adm/cron/cron.allow)
    CA_RC=$?
    if [ "$CA_RC" -ne 0 ]; then
      CA_REASON="absent or unreadable (rc=$CA_RC)"
    else
      CA_ROOT=$(printf '%s\n' "$CA_RAW" | awk '$0 == "root" { found=1 } END { print found+0 }')
      CA_ADM=$(printf '%s\n' "$CA_RAW" | awk '$0 == "adm" { found=1 } END { print found+0 }')
      if [ "$CA_ROOT" -ne 1 ] || [ "$CA_ADM" -ne 1 ]; then
        CA_REASON="missing a required user"
      fi
    fi
    if [ -n "$CA_REASON" ]; then
      add security cron_cron_deny_absent "cron.deny absence and cron.allow membership" FAIL high \
          "/var/adm/cron/cron.allow $CA_REASON" \
          "cron.deny is absent but cron.allow does not grant cron access to both root and adm, or cannot be read." \
          "create /var/adm/cron/cron.allow listing root and adm one per line; PTxray recommends this action and never executes it." \
          "cis-l1"
    else
      add security cron_cron_deny_absent "cron.deny absence and cron.allow membership" PASS med \
          "/var/adm/cron/cron.deny absent; /var/adm/cron/cron.allow lists root and adm" \
          "cron access is restricted to cron.allow alone and it names the required users." \
          "n/a" "cis-l1"
    fi
  fi
_AIXRAY_SESSION_KEYS=""
  # audit_filesystem_present — audit-subsystem presence bundle.
  # Five presence probes; every one must pass. Content correctness of the
  # audit configuration file is not validated — presence only.
  typeset LFS_RAW LFS_RC LFS_ST LFS_REASON
  typeset CAT_RAW CAT_RC CAT_ST CAT_REASON
  typeset SEC_RAW SEC_RC SEC_ST SEC_REASON SEC_TRIMMED
  typeset CRT_RAW CRT_RC CRT_ST CRT_REASON
  typeset ITAB_RAW ITAB_RC ITAB_ST ITAB_REASON
  typeset REASONS reason

  # Each *_REASON is assigned ONLY on its probe's failure paths, but the verdict
  # below reads all five unconditionally. `typeset` declares without initialising,
  # so on any run where at least one probe succeeds and at least one fails, that
  # read hit an unset parameter under `set -u` and killed checks_security()
  # mid-function -- taking every LATER security finding down with it. On both lab
  # boxes that silently dropped audit_classes_default, syslog_entries and
  # syslogd_inbound, so CIS 8.1.3, 8.2.1 and 8.2.3 resolved to nothing at all and
  # read as unmapped rather than as a crash. Initialise explicitly.
  LFS_REASON=""; CAT_REASON=""; SEC_REASON=""; CRT_REASON=""; ITAB_REASON=""
  REASONS=""

  # --- probe 1: /audit filesystem mounted ---
  # rc 127 means no capture in replay and command-not-found live: the probe did
  # not run, so it refuses rather than judging. rc 1 is a real capture meaning
  # lsfs ran and there is no /audit filesystem, so it stays a determinate FAIL.
  LFS_RAW=$(aix lsfs_audit lsfs /audit); LFS_RC=$?
  if [ "$LFS_RC" -eq 0 ]; then
    if [ -n "$LFS_RAW" ]; then
      LFS_ST=ok
    else
      LFS_ST=na; LFS_REASON="lsfs returned rc=0 with no output"
    fi
  elif [ "$LFS_RC" -eq 1 ]; then
    LFS_ST=fail; LFS_REASON="/audit filesystem not mounted"
  elif [ "$LFS_RC" -eq 127 ]; then
    LFS_ST=na; LFS_REASON="lsfs /audit did not run (rc=127), so the /audit filesystem state was not assessed"
  else
    LFS_ST=na; LFS_REASON="lsfs /audit returned an unexpected rc=$LFS_RC, so the /audit filesystem state was not assessed"
  fi

  # --- probe 2: audit configuration file present and readable ---
  # rc 127 is "probe did not run" (no capture in replay, command not found
  # live) and refuses. rc 1 means cat ran and the file is absent or unreadable,
  # attested by live lab captures, so it stays a determinate FAIL.
  CAT_RAW=$(aix cat_audit_config cat /etc/security/audit/config); CAT_RC=$?
  if [ "$CAT_RC" -eq 0 ]; then
    if [ -n "$CAT_RAW" ]; then
      CAT_ST=ok
    else
      CAT_ST=fail; CAT_REASON="/etc/security/audit/config empty"
    fi
  elif [ "$CAT_RC" -eq 1 ]; then
    CAT_ST=fail; CAT_REASON="/etc/security/audit/config absent or unreadable"
  elif [ "$CAT_RC" -eq 127 ]; then
    CAT_ST=na; CAT_REASON="cat /etc/security/audit/config did not run (rc=127), so the audit configuration file state was not assessed"
  else
    CAT_ST=na; CAT_REASON="cat /etc/security/audit/config returned an unexpected rc=$CAT_RC, so the audit configuration file state was not assessed"
  fi

  # --- probe 3: default-user auditclasses set to the mandated list ---
  SEC_RAW=$(aix lssec_auditclasses lssec -f /usr/lib/security/mkuser.default -s user -a auditclasses); SEC_RC=$?
  SEC_TRIMMED=""
  if [ "$SEC_RC" -eq 0 ]; then
    SEC_TRIMMED=$(printf '%s\n' "$SEC_RAW" | awk 'NF { print }')
    if [ "$SEC_TRIMMED" = "user auditclasses=general,SRC,cron,tcpip" ]; then
      SEC_ST=ok
    else
      SEC_ST=fail; SEC_REASON="default auditclasses do not match the mandated list"
    fi
  else
    SEC_ST=na; SEC_REASON="lssec probe failed (rc=$SEC_RC)"
  fi

  # --- probe 4: cronaudit log-rotation job scheduled ---
  # The whole crontab is captured with the shared crontab_list key (same
  # `crontab -l` as the argv wrapper was handed, but argv-split) and matched
  # in-shell against the basename of field 6 of a non-comment, 6-or-more-field
  # line -- the command actually scheduled -- never a substring scan of the
  # whole file. A wrapper-invoked job (su - root -c cronaudit, a shell script)
  # therefore renders FAIL by design: on a security control, failing closed
  # against an unrecognised invocation is correct, and a false FAIL is visible
  # and arguable where a false PASS is silent. crontab -l lists the invoking
  # user's crontab, not root's, so the probe is guarded on MYUID: unprivileged
  # it refuses; as root, rc 1 is ambiguous between no crontab and an unreadable
  # one, so it refuses too. Any other rc is a genuine probe failure and stays
  # NOT_ASSESSED.
  CRT_RAW=$(aix crontab_list crontab -l); CRT_RC=$?
  if [ "${MYUID:-0}" != "0" ]; then
    CRT_ST=na; CRT_REASON="crontab of the invoking non-root user was read, so root's crontab could not be assessed"
  elif [ "$CRT_RC" -eq 0 ]; then
    if printf '%s\n' "$CRT_RAW" | awk '
      /^[[:space:]]*#/ { next }
      NF < 6 { next }
      {
        executable = $6
        sub(/^.*\//, "", executable)
        if (executable == "cronaudit") {
          found = 1
          exit
        }
      }
      END { if (!found) exit 1 }
    '; then
      CRT_ST=ok
    else
      CRT_ST=fail; CRT_REASON="root crontab was read and schedules no cronaudit job"
    fi
  elif [ "$CRT_RC" -eq 1 ]; then
    CRT_ST=na; CRT_REASON="crontab -l exited 1, which cannot distinguish root having no crontab from root's crontab being unreadable"
  else
    CRT_ST=na; CRT_REASON="crontab probe failed (rc=$CRT_RC)"
  fi

  # --- probe 5: inittab entry starts the audit daemon at boot ---
  # rc 127 is "probe did not run" (no capture in replay, command not found
  # live) and refuses. rc 1 means lsitab ran and the entry is absent, attested
  # by live lab captures, so it stays a determinate FAIL; rc 0 with empty output
  # is the authored-fixture idiom for "ran and printed nothing" and also stays
  # a determinate FAIL.
  ITAB_RAW=$(aix lsitab_audit lsitab audit); ITAB_RC=$?
  if [ "$ITAB_RC" -eq 0 ]; then
    case "$ITAB_RAW" in
      audit:*) ITAB_ST=ok ;;
      "") ITAB_ST=fail; ITAB_REASON="no audit entry in /etc/inittab" ;;
      *) ITAB_ST=fail; ITAB_REASON="inittab audit record malformed" ;;
    esac
  elif [ "$ITAB_RC" -eq 1 ]; then
    ITAB_ST=fail; ITAB_REASON="no audit entry in /etc/inittab"
  elif [ "$ITAB_RC" -eq 127 ]; then
    ITAB_ST=na; ITAB_REASON="lsitab audit did not run (rc=127), so the inittab audit entry was not assessed"
  else
    ITAB_ST=na; ITAB_REASON="lsitab audit returned an unexpected rc=$ITAB_RC, so the inittab audit entry was not assessed"
  fi

  # --- verdict ---
  if [ "$LFS_ST" = ok ] && [ "$CAT_ST" = ok ] && [ "$SEC_ST" = ok ] && [ "$CRT_ST" = ok ] && [ "$ITAB_ST" = ok ]; then
    add security audit_filesystem_present "Audit subsystem present" PASS med \
        "audit subsystem fully present" \
        "The /audit filesystem is mounted, the audit configuration file is present and non-empty, default-user auditclasses match the mandated list, a cronaudit log-rotation job is scheduled, and an inittab entry starts the audit daemon at boot." \
        "n/a" "cis-l2"
  elif [ "$LFS_ST" = fail ] || [ "$CAT_ST" = fail ] || [ "$SEC_ST" = fail ] || [ "$CRT_ST" = fail ] || [ "$ITAB_ST" = fail ]; then
    for reason in "$LFS_REASON" "$CAT_REASON" "$SEC_REASON" "$CRT_REASON" "$ITAB_REASON"; do
      [ -n "$reason" ] && REASONS="${REASONS:+$REASONS; }$reason"
    done
    add security audit_filesystem_present "Audit subsystem present" FAIL high \
        "audit subsystem incomplete: $REASONS" \
        "One or more audit-subsystem presence requirements are not met. This check verifies presence only; the audit configuration file content is not validated." \
        "$REASONS" "cis-l2"
  else
    for reason in "$LFS_REASON" "$CAT_REASON" "$SEC_REASON" "$CRT_REASON" "$ITAB_REASON"; do
      [ -n "$reason" ] && REASONS="${REASONS:+$REASONS; }$reason"
    done
    add security audit_filesystem_present "Audit subsystem present" NOT_ASSESSED med \
        "audit subsystem state unknown: $REASONS" \
        "A probe could not obtain trustworthy evidence, so the audit-subsystem presence state cannot be determined." \
        "$REASONS" "cis-l2"
  fi
_AIXRAY_SESSION_KEYS=""
  # audit_config_valid — CIS IBM AIX 7 v1.2.0 8.1.2 (Level 2): the audit
  # subsystem configuration in /etc/security/audit/config must carry the
  # bin(ary) event-collection stanza values the benchmark prescribes.
  #
  # The probe runs through aixv (stderr preserved), not aix, because cat's
  # exit status alone does not separate a missing file from an unreadable one
  # on AIX, and the two states carry different verdicts (missing = FAIL,
  # unreadable = NOT_ASSESSED). The ENOENT signature is read from the merged
  # capture; on AIX cat prints "Cannot find", on GNU/BSD cat prints
  # "No such file or directory".
  #
  # Assertion list (stanza:key = value), from the 8.1.2 remediation
  # configuration; the same table is in this check's README:
  #   start: binmode=on, streammode=off
  #   bin:   trail=/audit/trail, bin1=/audit/bin1, bin2=/audit/bin2,
  #          binsize=10240, cmds=/etc/security/audit/bincmds
  # A key counts only inside its own stanza, so the stream: stanza's own
  # cmds line never satisfies the bin: cmds assertion. Keys the control does
  # not name (freespace, ignorenonexistentity, backuppath, ...) are not
  # prohibited by it and are ignored — a live compliant box carries them.
  typeset ACV_RAW ACV_RC ACV_STATUS ACV_SEV ACV_OBS ACV_MEAN ACV_FIX
  typeset ACV_MISSING ACV_TOKEN ACV_DETAIL

  ACV_RAW=""
  ACV_RC=126
  ACV_STATUS=""
  ACV_SEV=""
  ACV_OBS=""
  ACV_MEAN=""
  ACV_FIX=""
  ACV_MISSING=0
  ACV_TOKEN=""
  ACV_DETAIL=""

  ACV_RAW=$(aixv audit_config cat /etc/security/audit/config)
  ACV_RC=$?

  if [ "$ACV_RC" -eq 0 ]; then
    if [ -n "$ACV_RAW" ]; then
      # Stanza-scoped parse: a "<name>:" line at column 0 opens a stanza, and
      # every indented "key = value" line below it belongs to that stanza.
      # Whitespace around the indent and the '=' varies on a real box (tabs,
      # spaces, trailing blanks), so it is normalised before comparison.
      ACV_TOKEN=$(printf '%s\n' "$ACV_RAW" | awk '
        BEGIN {
          n = split("start:binmode:on start:streammode:off bin:trail:/audit/trail bin:bin1:/audit/bin1 bin:bin2:/audit/bin2 bin:binsize:10240 bin:cmds:/etc/security/audit/bincmds", spec, " ")
          stanza = ""
        }
        /^[A-Za-z_][A-Za-z_0-9]*:[[:space:]]*$/ {
          stanza = $0
          sub(/:[[:space:]]*$/, "", stanza)
          stanzas++
          next
        }
        /^[[:space:]][[:space:]]*[A-Za-z_][A-Za-z_0-9]*[[:space:]]*=/ {
          if (stanza == "") next
          key = $0
          sub(/^[[:space:]]*/, "", key)
          sub(/[[:space:]]*=.*$/, "", key)
          val = $0
          sub(/^[^=]*=[[:space:]]*/, "", val)
          sub(/[[:space:]]*$/, "", val)
          got[stanza ":" key] = val
          pairs++
          next
        }
        END {
          if (stanzas == 0 || pairs == 0) { print "UNPARSEABLE"; exit }
          bad = 0
          shown = 0
          names = ""
          for (i = 1; i <= n; i++) {
            split(spec[i], f, ":")
            k = f[1] ":" f[2]
            if (!(k in got) || got[k] != f[3]) {
              bad++
              if (shown < 3) {
                if (names != "") names = names ", "
                names = names k
                shown++
              }
            }
          }
          if (bad == 0) { print "OK"; exit }
          msg = "BAD unmet " bad " of " n ": " names
          if (bad > shown) msg = msg " (+" (bad - shown) " more)"
          print msg
        }')
      case "$ACV_TOKEN" in
        OK)
          ACV_STATUS=PASS
          ACV_SEV=low
          ACV_OBS="/etc/security/audit/config matches every prescribed stanza value"
          ACV_MEAN="The audit configuration carries every bin(ary) event-collection stanza value this control prescribes."
          ACV_FIX="n/a"
          ;;
        "BAD "*)
          ACV_DETAIL=${ACV_TOKEN#BAD }
          ACV_STATUS=FAIL
          ACV_SEV=high
          ACV_OBS="/etc/security/audit/config $ACV_DETAIL"
          ACV_MEAN="The audit configuration departs from the prescribed bin(ary) event-collection settings, so audit events are not collected into the prescribed bin trail."
          ACV_FIX="set the unmet stanza values in /etc/security/audit/config to the prescribed bin(ary) collection configuration and restart the audit subsystem; PTxray recommends the edit, it never writes it."
          ;;
        *)
          ACV_STATUS=NOT_ASSESSED
          ACV_SEV=med
          ACV_OBS="not assessed — /etc/security/audit/config carries no stanza values"
          ACV_MEAN="PTxray could not parse any stanza value out of the audit configuration, so it cannot judge whether the prescribed settings are in effect."
          ACV_FIX="inspect /etc/security/audit/config for a valid stanza layout, then rerun PTxray."
          ;;
      esac
    else
      ACV_STATUS=NOT_ASSESSED
      ACV_SEV=med
      ACV_OBS="not assessed — /etc/security/audit/config read back empty"
      ACV_MEAN="PTxray read /etc/security/audit/config successfully but got no content, so it cannot judge the prescribed settings."
      ACV_FIX="verify /etc/security/audit/config has content, then rerun PTxray."
    fi
  else
    case "$ACV_RAW" in
      *"No such file"*|*"Cannot find"*)
        ACV_MISSING=1
        ;;
    esac
    if [ "$ACV_MISSING" -eq 1 ]; then
      ACV_STATUS=FAIL
      ACV_SEV=high
      ACV_OBS="/etc/security/audit/config is missing"
      ACV_MEAN="The audit subsystem configuration file does not exist, so the audit subsystem cannot be in the prescribed compliant state."
      ACV_FIX="recreate /etc/security/audit/config with the compliant stanza values, then rerun PTxray."
    else
      ACV_STATUS=NOT_ASSESSED
      ACV_SEV=med
      ACV_OBS="not assessed — /etc/security/audit/config unreadable (rc=$ACV_RC)"
      ACV_MEAN="PTxray did not obtain a trustworthy read of the audit configuration file, so it cannot assess whether the configuration is compliant."
      ACV_FIX="verify /etc/security/audit/config exists and is readable to the running identity, then rerun PTxray."
    fi
  fi

  add security audit_config_valid "Audit subsystem configuration" \
    "$ACV_STATUS" "$ACV_SEV" "$ACV_OBS" "$ACV_MEAN" "$ACV_FIX" "cis-l2"
_AIXRAY_SESSION_KEYS=""
  # audit_classes_default — required-class coverage of the audit classes default.
  # /etc/security/audit/config must define a `classes:` stanza whose `default =`
  # line names every class in the required set. A readable file that lacks the
  # stanza, lacks the default line, or omits any required class is non-compliant;
  # a zero-byte config is likewise non-compliant. A non-root run and an unreadable
  # or absent file refuse (NOT_ASSESSED).
  typeset AUDC_RAW AUDC_RC AUDC_TOKEN AUDC_MISSING
  typeset AUDC_STATUS AUDC_SEVERITY AUDC_OBSERVED AUDC_MEANING AUDC_FIX
  AUDC_RAW=""; AUDC_RC=127; AUDC_TOKEN=""; AUDC_MISSING=""
  AUDC_STATUS=""; AUDC_SEVERITY=""; AUDC_OBSERVED=""; AUDC_MEANING=""; AUDC_FIX=""

  if [ "${MYUID:-0}" != "0" ]; then
    AUDC_STATUS=NOT_ASSESSED
    AUDC_SEVERITY=med
    AUDC_OBSERVED="not assessed - reading the audit classes config requires root"
    AUDC_MEANING="PTxray did not obtain /etc/security/audit/config, so it cannot claim the default audit class set is compliant."
    AUDC_FIX="re-run ptxray as root, or inspect /etc/security/audit/config manually."
  else
    AUDC_RAW=$(aix cat_audit_config cat /etc/security/audit/config)
    AUDC_RC=$?
    if [ "$AUDC_RC" -ne 0 ]; then
      AUDC_STATUS=NOT_ASSESSED
      AUDC_SEVERITY=med
      AUDC_OBSERVED="not assessed - cannot read /etc/security/audit/config (rc=$AUDC_RC)"
      AUDC_MEANING="PTxray did not obtain /etc/security/audit/config, so it cannot claim the default audit class set is compliant."
      AUDC_FIX="resolve the read error on /etc/security/audit/config and rerun PTxray."
    elif [ -z "$AUDC_RAW" ]; then
      AUDC_STATUS=FAIL
      AUDC_SEVERITY=high
      AUDC_OBSERVED="/etc/security/audit/config is empty"
      AUDC_MEANING="An empty audit configuration cannot define the required default class set, so the requirement is not met."
      AUDC_FIX="populate /etc/security/audit/config with a classes: stanza and its default = line; PTxray recommends the edit, it never writes it."
    else
      AUDC_TOKEN=$(printf '%s\n' "$AUDC_RAW" | awk '
        BEGIN {
          n = split("TE_Untrusted TE_FileWrite TE_Policies TEAdd_Stnz TEDel_Stnz TESwitch_algo TEQuery_Stnz", req, " ")
        }
        # /etc/security/audit/config is an AIX stanza file and comments it with
        # * , not # . A comment is only a * as the first non-blank character;
        # a * anywhere else on the line is data, so a class name that contains
        # one is still parsed literally. A skipped comment still counts as file
        # content so an all-comment config is not misreported as empty.
        /^[ \t]*\*/ {
          saw = 1
          next
        }
        /^classes:/ {
          saw = 1
          stanza = 1
          seen = 1
          next
        }
        {
          if (NF > 0) saw = 1
          if (stanza && NF > 0 && $0 !~ /^[[:space:]]/) stanza = 0
          if (stanza && $0 ~ /default[[:space:]]*=/) {
            got = 1
            rhs = $0
            sub(/^.*default[[:space:]]*=[[:space:]]*/, "", rhs)
            cnt = split(rhs, list, ",")
            for (i = 1; i <= cnt; i++) {
              val = list[i]
              gsub(/^[[:space:]]+|[[:space:]]+$/, "", val)
              for (j = 1; j <= n; j++) if (val == req[j]) have[j] = 1
            }
          }
        }
        END {
          if (!saw) exit
          if (!seen) { print "NO_STANZA"; exit }
          if (!got) { print "NO_DEFAULT"; exit }
          miss = ""
          for (j = 1; j <= n; j++) {
            if (!have[j]) {
              if (miss != "") miss = miss ","
              miss = miss req[j]
            }
          }
          if (miss != "") { print "MISSING:" miss; exit }
          print "OK"
        }')
      case "$AUDC_TOKEN" in
        OK)
          AUDC_STATUS=PASS; AUDC_SEVERITY=low
          AUDC_OBSERVED="audit classes default lists every required class"
          AUDC_MEANING="The audit configuration names every required class in the default event set."
          AUDC_FIX="n/a"
          ;;
        MISSING:*)
          AUDC_MISSING=${AUDC_TOKEN#MISSING:}
          AUDC_STATUS=FAIL; AUDC_SEVERITY=high
          AUDC_OBSERVED="audit classes default omits required class(es): $AUDC_MISSING"
          AUDC_MEANING="The audit default event set omits required classes, so events in those classes are not captured by default."
          AUDC_FIX="add the omitted class(es) to the default = line inside the classes: stanza of /etc/security/audit/config; PTxray recommends the edit, it never writes it."
          ;;
        NO_DEFAULT)
          AUDC_STATUS=FAIL; AUDC_SEVERITY=high
          AUDC_OBSERVED="classes: stanza present but no default = line"
          AUDC_MEANING="The audit configuration has a classes: stanza without a default = line, so the required class set is never selected."
          AUDC_FIX="add a default = line naming every required class inside the classes: stanza of /etc/security/audit/config; PTxray recommends the edit, it never writes it."
          ;;
        NO_STANZA)
          AUDC_STATUS=FAIL; AUDC_SEVERITY=high
          AUDC_OBSERVED="no classes: stanza in the audit config"
          AUDC_MEANING="The audit configuration does not define a classes: stanza, so the required default class set cannot be in effect."
          AUDC_FIX="add a classes: stanza with a default = line naming every required class to /etc/security/audit/config; PTxray recommends the edit, it never writes it."
          ;;
        "")
          AUDC_STATUS=FAIL; AUDC_SEVERITY=high
          AUDC_OBSERVED="audit config is empty or carries no stanzas"
          AUDC_MEANING="The audit configuration carries no classes PTxray could interpret, so the required default class set is not established."
          AUDC_FIX="review /etc/security/audit/config for a classes: stanza with a default = line naming every required class; PTxray recommends the edit, it never writes it."
          ;;
        *)
          AUDC_STATUS=NOT_ASSESSED; AUDC_SEVERITY=med
          AUDC_OBSERVED="unexpected discriminator result '$AUDC_TOKEN'"
          AUDC_MEANING="PTxray could not interpret the audit config discriminator, so it cannot assess the default class set."
          AUDC_FIX="capture /etc/security/audit/config, diagnose the discriminator, and rerun PTxray."
          ;;
      esac
    fi
  fi

  add security audit_classes_default "audit classes default" \
    "$AUDC_STATUS" "$AUDC_SEVERITY" "$AUDC_OBSERVED" "$AUDC_MEANING" "$AUDC_FIX" "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # syslog_entries — does /etc/syslog.conf define at least one active logging rule
  # (a non-blank, non-comment line), and do the three expected log destinations
  # exist on disk?  An empty, all-comment, or destination-less syslog.conf means
  # the box is not collecting logs.  Control 8.2.1, Level 1.
  #
  # Capture 1: egrep -v "(^$)|(^#)" /etc/syslog.conf — active rule lines.
  #   rc=0 with >=1 non-blank line   => active entries
  #   rc=1, or rc=0 with no non-blank line => no active entries
  #   rc>=2                          => capture failure
  #
  # Capture 2: ls -ld of the three expected log destinations.  The parser counts
  #   output lines (one line per existing destination): 3 lines => all present;
  #   fewer => at least one missing; rc=1 or rc>=3 => capture failure.
  #
  # Verdict logic (both captures must answer):
  #   active entries + all targets present    => PASS (low)
  #   active entries + a target missing       => FAIL (med)
  #   no active entries + all targets present => FAIL (med)
  #   no active entries + a target missing    => FAIL (high)
  #   conf capture failure (rc>=2)            => NOT_ASSESSED (low)
  #   targets capture failure (rc=1 or rc>=3) => NOT_ASSESSED (low)
  #
  typeset SE_CFG_RAW SE_CFG_RC SE_CFG_LINES SE_TGT_RAW SE_TGT_RC SE_TGT_LINES
  typeset SE_CONF_STATE SE_TGT_STATE SE_STATUS SE_SEV SE_OBS SE_MEAN SE_FIX

  SE_CFG_RAW=$(aix syslog_conf_entries egrep -v "(^$)|(^#)" /etc/syslog.conf)
  SE_CFG_RC=$?
  SE_TGT_RAW=$(aix syslog_log_targets ls -ld /var/log/syslog/auth.log /var/log/syslog/info.log /var/log/syslog/archive)
  SE_TGT_RC=$?

  # Classify the syslog.conf capture.
  if [ "$SE_CFG_RC" -ge 2 ]; then
    SE_CONF_STATE=failure
  elif [ "$SE_CFG_RC" -eq 0 ]; then
    SE_CFG_LINES=$(printf '%s\n' "$SE_CFG_RAW" | awk 'NF { n++ } END { print n+0 }')
    if [ "$SE_CFG_LINES" -ge 1 ]; then
      SE_CONF_STATE=active
    else
      SE_CONF_STATE=none
    fi
  else
    # rc=1: egrep matched nothing, so no active entries.
    SE_CONF_STATE=none
  fi

  # Classify the log-targets capture by rc gate then output-line count.
  SE_TGT_LINES=$(printf '%s\n' "$SE_TGT_RAW" | awk 'NF { n++ } END { print n+0 }')
  if [ "$SE_TGT_RC" -eq 1 ] || [ "$SE_TGT_RC" -ge 3 ]; then
    SE_TGT_STATE=failure
  elif [ "$SE_TGT_LINES" -eq 3 ]; then
    SE_TGT_STATE=all
  else
    # Fewer than three lines listed: at least one destination did not list.
    SE_TGT_STATE=missing
  fi

  # Verdict.
  if [ "$SE_CONF_STATE" = "failure" ]; then
    SE_STATUS=NOT_ASSESSED
    SE_SEV=low
    SE_OBS="not assessed - syslog.conf capture failed (rc=$SE_CFG_RC)"
    SE_MEAN="PTxray could not read /etc/syslog.conf, so it cannot tell whether active logging rules exist."
    SE_FIX="make /etc/syslog.conf readable, then re-run PTxray."
  elif [ "$SE_TGT_STATE" = "failure" ]; then
    SE_STATUS=NOT_ASSESSED
    SE_SEV=low
    SE_OBS="not assessed - log-target capture failed (rc=$SE_TGT_RC)"
    SE_MEAN="PTxray could not list the expected log destinations, so it cannot tell whether they exist on disk."
    SE_FIX="make the log directory listable, then re-run PTxray."
  elif [ "$SE_CONF_STATE" = "active" ] && [ "$SE_TGT_STATE" = "all" ]; then
    SE_STATUS=PASS
    SE_SEV=low
    SE_OBS="$SE_CFG_LINES active syslog.conf rule line(s); all three expected log destinations present"
    SE_MEAN="syslog.conf defines at least one active logging rule and every expected log output exists on disk, so the box is collecting logs."
    SE_FIX="n/a"
  elif [ "$SE_CONF_STATE" = "active" ] && [ "$SE_TGT_STATE" = "missing" ]; then
    SE_STATUS=FAIL
    SE_SEV=med
    SE_OBS="$SE_CFG_LINES active syslog.conf rule line(s); fewer than three expected log destinations present"
    SE_MEAN="syslog.conf defines logging rules but at least one of the expected log outputs is missing, so some logged events are not being collected."
    SE_FIX="create the missing log destinations that syslog.conf expects, then re-run PTxray."
  elif [ "$SE_CONF_STATE" = "none" ] && [ "$SE_TGT_STATE" = "all" ]; then
    SE_STATUS=FAIL
    SE_SEV=med
    SE_OBS="no active syslog.conf rule lines; all three expected log destinations present"
    SE_MEAN="syslog.conf has no active logging rules, so the syslog daemon is not collecting events even though the destinations exist."
    SE_FIX="add at least one active logging rule to /etc/syslog.conf, then re-run PTxray."
  else
    # No active entries and at least one destination missing.
    SE_STATUS=FAIL
    SE_SEV=high
    SE_OBS="no active syslog.conf rule lines; fewer than three expected log destinations present"
    SE_MEAN="syslog.conf has no active logging rules and expected log outputs are missing, so the box is not collecting logs at all."
    SE_FIX="add active logging rules to /etc/syslog.conf and create the missing log destinations, then re-run PTxray."
  fi

  add security syslog_entries "syslog logging rules and destinations" \
    "$SE_STATUS" "$SE_SEV" \
    "$SE_OBS" \
    "$SE_MEAN" \
    "$SE_FIX" \
    "cis-l1"
_AIXRAY_SESSION_KEYS=""
  # syslog_remote_host — at least one syslog rule must forward to a remote
  # host. A forwarding rule is a non-comment line in /etc/syslog.conf that
  # contains the '@' remote-host sigil; a comment line (first non-whitespace
  # character '#') never counts, even when it names a remote host.
  typeset SRH_RAW SRH_RC SRH_ST SRH_OBS SRH_N SRH_AWK_RC

  SRH_RAW=$(aix syslog_conf cat /etc/syslog.conf)
  SRH_RC=$?
  SRH_ST=""
  SRH_OBS=""

  if [ "$SRH_RC" -eq 2 ]; then
    # ENOENT — the config file is absent, so no forwarding rule can exist.
    SRH_ST=FAIL
    SRH_OBS="no remote target"
  elif [ "$SRH_RC" -ne 0 ]; then
    # Capture failed for an unexpected reason; the state is genuinely unknown.
    SRH_ST=NOT_ASSESSED
    SRH_OBS="capture failed (rc=$SRH_RC)"
  elif [ -z "$SRH_RAW" ]; then
    # rc=0 with nothing read — no config content, hence no forwarding rule.
    SRH_ST=FAIL
    SRH_OBS="no remote target"
  else
    # Count non-comment '@' lines. A line is only parseable as a config line
    # when its first field is a selector (a facility.level token, which always
    # contains a '.'); a non-comment line without a selector is not a syslog
    # config line at all and makes the whole capture unparseable.
    SRH_N=$(printf '%s\n' "$SRH_RAW" | awk '
      !/^[ \t]*#/ {
        if (NF == 0) next
        if (index($1, ".") == 0) { bad = 1; next }
        if (index($0, "@")) n++
      }
      END {
        if (bad) exit 1
        print n + 0
      }
    ')
    SRH_AWK_RC=$?
    if [ "$SRH_AWK_RC" -ne 0 ]; then
      SRH_ST=NOT_ASSESSED
      SRH_OBS="unparseable"
    else
      SRH_N=${SRH_N:-0}
      if [ "$SRH_N" -ge 1 ]; then
        SRH_ST=PASS
        SRH_OBS="$SRH_N forwarding rule(s)"
      else
        SRH_ST=FAIL
        SRH_OBS="no remote target"
      fi
    fi
  fi

  if [ "$SRH_ST" = "PASS" ]; then
    add monitoring syslog_remote_host "Syslog remote host" PASS low "$SRH_OBS" \
        "At least one syslog rule forwards log entries to a remote host." \
        "n/a" "cis-l2"
  elif [ "$SRH_ST" = "FAIL" ]; then
    add monitoring syslog_remote_host "Syslog remote host" FAIL low "$SRH_OBS" \
        "No syslog rule forwards log entries to a remote host; the log survives only until the box dies." \
        "add a '<selector> @<host>' rule to /etc/syslog.conf and run 'refresh -s syslogd' to apply it." \
        "cis-l2"
  else
    add monitoring syslog_remote_host "Syslog remote host" NOT_ASSESSED low "$SRH_OBS" \
        "Remote syslog forwarding could not be assessed because the syslog config capture failed or its output could not be parsed as config lines." \
        "run 'cat /etc/syslog.conf' manually, then re-run PTxray before treating remote logging as configured." \
        "cis-l2"
  fi
_AIXRAY_SESSION_KEYS=""
  # syslogd_inbound — syslogd started with the -r flag (inbound log collection).
  # Reads the process list once; the daemon's argument vector carries both the
  # binary path and the flag, so no second probe is needed. The bracket pattern
  # on the probe avoids matching the grep process itself.
  typeset SYSLOG_PS SYSLOG_PS_RC SYSLOG_LINE SYSLOG_STATUS SYSLOG_OBSERVED
  typeset SYSLOG_MEANING SYSLOG_FIX
  SYSLOG_PS=""
  SYSLOG_PS_RC=0
  SYSLOG_LINE=""
  SYSLOG_STATUS=""
  SYSLOG_OBSERVED=""
  SYSLOG_MEANING=""
  SYSLOG_FIX=""

  SYSLOG_PS=$(aix syslogd_ps ps -ef)
  SYSLOG_PS_RC=$?
  if [ "$SYSLOG_PS_RC" -ne 0 ]; then
    SYSLOG_STATUS=NOT_ASSESSED
    SYSLOG_OBSERVED="not assessed - ps -ef capture failed (rc=$SYSLOG_PS_RC)"
  else
    SYSLOG_LINE=$(printf '%s\n' "$SYSLOG_PS" | grep '[s]yslogd')
    if [ -z "$SYSLOG_LINE" ]; then
      SYSLOG_STATUS=FAIL
      SYSLOG_OBSERVED="no syslogd process present in the process list"
    elif printf '%s\n' "$SYSLOG_LINE" | grep -q '[-]r'; then
      SYSLOG_STATUS=PASS
      SYSLOG_OBSERVED="syslogd running with the -r flag"
    else
      SYSLOG_STATUS=FAIL
      SYSLOG_OBSERVED="syslogd running without the -r flag"
    fi
  fi

  case "$SYSLOG_STATUS" in
    PASS)
      SYSLOG_MEANING="The syslogd daemon is running with -r, so it accepts inbound messages and the configured collection and forwarding paths can deliver them."
      SYSLOG_FIX="n/a"
      ;;
    FAIL)
      SYSLOG_MEANING="The syslogd daemon is not running, or is running without -r, so inbound messages are not collected."
      SYSLOG_FIX="start or restart syslogd with the -r flag ('/usr/sbin/syslogd -r'), confirm the process list shows the flag, then rerun PTxray."
      ;;
    *)
      SYSLOG_MEANING="PTxray did not obtain a trustworthy process list, so it cannot determine the syslogd daemon state."
      SYSLOG_FIX="make 'ps -ef' return a complete readable process list, then rerun PTxray."
      ;;
  esac

  add security syslogd_inbound "syslogd -r flag" \
    "$SYSLOG_STATUS" low "$SYSLOG_OBSERVED" \
    "$SYSLOG_MEANING" "$SYSLOG_FIX" "cis-l1"
}

# ---- H. Config hygiene -----------------------------------------------------------------
function checks_config {
  typeset XN STAT NTPS RESOLV RT TN TZ HOSTS HOSTSRC HOSTSTATE NETSVC NETSVCRC RESORDER ORDERNOTE

  # ntp — daemon running and at least one server configured
  XN=$(aix lssrc_xntpd lssrc -s xntpd)
  STAT=$(printf '%s\n' "$XN" | awk '$1=="xntpd"{print $NF; exit}')
  NTPS=$(aix ntp_conf grep '^server' /etc/ntp.conf | awk 'NF{n++} END{print n+0}')
  if [ "$STAT" = "active" ] && [ "${NTPS:-0}" -ge 1 ]; then
    add config ntp "Time synchronization (NTP)" PASS med "xntpd active, $NTPS server(s)" \
        "The clock is disciplined by NTP — log correlation, Kerberos and TLS all depend on it." "n/a" "stig:V-215208 cis-l1"
  else
    add config ntp "Time synchronization (NTP)" FAIL med "xntpd ${STAT:-inactive}, ${NTPS:-0} server(s)" \
        "No working time sync — clock drift breaks log correlation, Kerberos and TLS." \
        "configure /etc/ntp.conf with a server and start xntpd ('startsrc -s xntpd'; enable at boot)." "stig:V-215208 cis-l1"
  fi

  # dns
  RESOLV=$(aix resolv_conf grep nameserver /etc/resolv.conf | awk 'NF{n++} END{print n+0}')
  if [ "${RESOLV:-0}" -ge 1 ]; then
    add config dns "DNS resolver" PASS low "$RESOLV nameserver(s)" \
        "At least one DNS resolver is configured." "n/a"
  else
    add config dns "DNS resolver" WARN low "no nameserver" \
        "No DNS resolver configured — this may be intentional on an isolated LPAR, or a gap." \
        "add a nameserver to /etc/resolv.conf if this box should resolve names."
  fi

  # default_route
  RT=$(aix netstat_rn netstat -rn)
  if printf '%s\n' "$RT" | grep -q '^default'; then
    add config default_route "Default route" PASS low "default route present" \
        "A default route is configured." "n/a"
  else
    add config default_route "Default route" WARN low "no default route" \
        "No default route — this may be intentional on an isolated LPAR, or a gap." \
        "add a default gateway if off-subnet traffic should route."
  fi

  # tunables — non-default kernel tunables staged for next boot
  # tunables — an unreadable nextboot (permissions, non-root) must not read as
  # "no non-default tunables"; that would be a silent false PASS.
  TNOUT=$(aix tunables_nextboot cat /etc/tunables/nextboot); TNRC=$?
  TN=$(printf '%s\n' "$TNOUT" | awk '!/^#/ && NF>0 {n++} END{print n+0}')
  if [ "$TNRC" -ne 0 ] && [ "${MYUID:-0}" != "0" ]; then
    nr_warn config tunables "Kernel tunables (nextboot)" "the nextboot tunables file" "cat /etc/tunables/nextboot"
  elif [ "${TN:-0}" -gt 0 ]; then
    add config tunables "Kernel tunables (nextboot)" WARN low "$TN changed tunable line(s)" \
        "Kernel tunables are changed from default for next boot — deliberate tuning or archaeology? document each." \
        "review /etc/tunables/nextboot; record why each change exists, or revert to default." ""
  else
    add config tunables "Kernel tunables (nextboot)" PASS low "no non-default tunables" \
        "No non-default kernel tunables set for next boot." "n/a"
  fi

  # tz_set
  TZ=$(aix etc_environment grep '^TZ=' /etc/environment | awk 'NR==1{print}')
  if [ -n "$TZ" ]; then
    add config tz_set "Timezone (TZ)" PASS low "$TZ" \
        "The system timezone is set explicitly." "n/a"
  else
    add config tz_set "Timezone (TZ)" WARN low "TZ not set" \
        "TZ is not set in /etc/environment — timestamps can be ambiguous." \
        "set TZ in /etc/environment to this system's timezone."
  fi

  # host_resolves — static evidence ONLY. A 2026-07-14 lab drill
  # proved that invoking a resolver client here emits a real UDP DNS query
  # whenever the hostname is absent from /etc/hosts. Read and parse the local
  # file instead; an absent entry is the finding, never a reason to query DNS.
  RESORDER=$(printf '%s\n' "${NSORDER:-}" | awk 'NR==1{gsub(/^[ \t]+|[ \t]+$/, ""); print; exit}')
  if [ -n "$RESORDER" ]; then
    ORDERNOTE="NSORDER=$RESORDER"
  else
    NETSVC=$(aix netsvc_conf cat /etc/netsvc.conf); NETSVCRC=$?
    if [ "$NETSVCRC" -eq 0 ]; then
      RESORDER=$(printf '%s\n' "$NETSVC" | awk '
        {
          line=$0
          sub(/[ \t]*#.*/, "", line)
          if (line ~ /^[ \t]*hosts[ \t]*=/) {
            sub(/^[ \t]*hosts[ \t]*=[ \t]*/, "", line)
            gsub(/[ \t]+/, "", line)
            if (line != "") print line
            exit
          }
        }
      ')
    else
      RESORDER=""
    fi
    if [ -n "$RESORDER" ]; then
      ORDERNOTE="/etc/netsvc.conf hosts=$RESORDER"
    else
      ORDERNOTE="resolution order not declared/readable"
    fi
  fi

  HOSTS=$(aix etc_hosts cat /etc/hosts); HOSTSRC=$?
  if [ -z "$HOST" ]; then
    HOSTSTATE=NO_HOSTNAME
  elif [ "$HOSTSRC" -ne 0 ]; then
    HOSTSTATE=UNREADABLE
  else
    HOSTSTATE=$(printf '%s\n' "$HOSTS" | awk -v wanted="$HOST" '
      function valid_ipv4(address, count, octet, i) {
        count=split(address, octet, "[.]")
        if (count != 4) return 0
        for (i=1; i<=4; i++) {
          if (octet[i] !~ /^[0-9][0-9]*$/ || octet[i] + 0 > 255) return 0
        }
        return 1
      }
      function valid_ipv6(address, zone_count, zone, core, rest, first,
                          ipv4, has_ipv4, count, part, piece, i, compressed, effective) {
        zone_count=split(address, zone, "%")
        if (zone_count < 1 || zone_count > 2) return 0
        if (zone_count == 2 && zone[2] !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        core=zone[1]
        if (core !~ /:/ || core ~ /:::/ || core !~ /^[0-9A-Fa-f:.][0-9A-Fa-f:.]*$/) return 0
        if (core ~ /^:[^:]/ || core ~ /[^:]:$/) return 0
        first=index(core, "::")
        if (first > 0) {
          compressed=1
          rest=substr(core, first + 2)
          if (index(rest, "::") > 0) return 0
        }
        if (core ~ /[.]/) {
          ipv4=core
          sub(/^.*:/, "", ipv4)
          if (!valid_ipv4(ipv4)) return 0
          sub(/[^:]*$/, "", core)
          has_ipv4=1
        }
        count=split(core, part, "[:]")
        for (i=1; i<=count; i++) {
          piece=part[i]
          if (piece == "") continue
          if (piece !~ /^[0-9A-Fa-f][0-9A-Fa-f]?[0-9A-Fa-f]?[0-9A-Fa-f]?$/) return 0
          effective++
        }
        effective += 2 * has_ipv4
        if (compressed) return effective < 8
        return effective == 8
      }
      {
        line=$0
        sub(/[ \t]*#.*/, "", line)
        if (line ~ /^[ \t]*$/) next
        $0=line
        if (NF < 2 || (!valid_ipv4($1) && !valid_ipv6($1))) {
          bad=1
          next
        }
        for (i=2; i<=NF; i++) {
          if ($i !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) bad=1
          if (tolower($i) == tolower(wanted)) found=1
        }
        valid++
      }
      END {
        if (bad || valid == 0) print "UNUSABLE"
        else if (found) print "FOUND"
        else print "ABSENT"
      }
    ')
  fi

  case "$HOSTSTATE" in
    FOUND)
      add config host_resolves "Host self-resolution" PASS low \
          "$HOST found in /etc/hosts; $ORDERNOTE" \
          "The hostname has a matching entry in the static local hosts file; this does not claim that live DNS works." "n/a"
      ;;
    ABSENT)
      add config host_resolves "Host self-resolution" WARN low \
          "$HOST does not self-resolve locally — no matching /etc/hosts entry; $ORDERNOTE" \
          "Tools and certs can misbehave when the box has no local entry for its own hostname; PTxray deliberately did not query DNS." \
          "add $HOST to /etc/hosts with the system's intended local address."
      ;;
    UNREADABLE)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — /etc/hosts capture failed (rc=$HOSTSRC); $ORDERNOTE" \
          "PTxray could not inspect the local hosts file and deliberately did not fall back to a live DNS lookup." \
          "make /etc/hosts readable, then re-run PTxray."
      ;;
    NO_HOSTNAME)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — hostname capture was empty; $ORDERNOTE" \
          "PTxray cannot test a local hosts-file entry without a captured hostname and deliberately did not query DNS." \
          "verify that hostname(1) returns this system's hostname, then re-run PTxray."
      ;;
    *)
      add config host_resolves "Host self-resolution" WARN low \
          "not assessed — /etc/hosts capture is empty or malformed; $ORDERNOTE" \
          "PTxray could not safely interpret the local hosts file and deliberately did not fall back to a live DNS lookup." \
          "repair /etc/hosts syntax, then re-run PTxray."
      ;;
  esac
}

# ---- I. Monitoring & operational readiness ---------------------------------------------
_AIXRAY_SESSION_KEYS=""
function checks_monitoring {
  typeset PSE PSERC PSE_OK PSEWHY AG KNOWN_AGENT_ALLOWLIST KNOWN_AGENT_ALLOWLIST_RE
  typeset PERF_COLLECTOR_ALLOWLIST PERF_COLLECTOR_ALLOWLIST_RE
  typeset EN ENDEC2 ENCUST2 ENODM ENODMRC ENODM_OK ENODMWHY
  typeset SYS SYSRAW SYSRC SYS_OK SYSWHY PH CR RC

  KNOWN_AGENT_ALLOWLIST_RE='^(zabbix_agent|zabbix_agentd|nrpe|node_exporter|kuxagent|collectd|njmon|njmon_aix[0-9][0-9]*_v[0-9][0-9]*|nimon|datadog|datadog-agent)$'
  KNOWN_AGENT_ALLOWLIST='zabbix_agent, zabbix_agentd, nrpe, node_exporter, kuxagent, collectd, njmon, njmon_aix<digits>_v<digits>, nimon, datadog, datadog-agent'
  PSE=$(aix ps_e ps -e -o comm); PSERC=$?
  PSE_OK=0; PSEWHY=""
  if [ "$PSERC" -ne 0 ]; then
    PSEWHY="not assessed — ps -e -o comm capture failed (rc=$PSERC)"
  elif [ -z "$PSE" ]; then
    PSEWHY="not assessed — ps -e -o comm capture empty (rc=0)"
  elif printf '%s\n' "$PSE" | awk '
      NR==1{ if(NF != 1 || $1 != "COMMAND") bad=1; next }
      NF{ n++; if(NF != 1) bad=1 }
      END{ if(n==0 || bad) exit 1 }
    '
  then
    PSE_OK=1
  else
    PSEWHY="not assessed — ps -e -o comm capture unparseable (rc=0)"
  fi

  # monitoring_agent — the managed-service hook
  if [ "$PSE_OK" -ne 1 ]; then
    add monitoring monitoring_agent "Monitoring agent" NOT_ASSESSED high \
        "$PSEWHY" \
        "PTxray could not inspect a valid process list, so it cannot determine whether a known monitoring agent is running." \
        "make 'ps -e -o comm' available with its normal AIX output, then re-run PTxray." ""
  else
    AG=$(printf '%s\n' "$PSE" | grep -E "$KNOWN_AGENT_ALLOWLIST_RE" | awk 'NR==1{print $1}')
    if [ -n "$AG" ]; then
      add monitoring monitoring_agent "Monitoring agent" PASS med "$AG running (matched exact command allowlist: $KNOWN_AGENT_ALLOWLIST)" \
          "A known monitoring agent is running — findings on this box can reach someone automatically." "n/a" ""
    else
      add monitoring monitoring_agent "Monitoring agent" WARN high \
          "no KNOWN monitoring agent detected (checked exact commands: $KNOWN_AGENT_ALLOWLIST)" \
          "PTxray checked only the listed known agents and found none; other monitoring may still be present." \
          "confirm monitoring coverage; if none exists, install and point a monitoring agent at this LPAR using an accepted command ($KNOWN_AGENT_ALLOWLIST)." ""
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # errpt_notify — AIX ships ~5 default errnotify stanzas. Believability review 2026-07-13
  # (believability review, finding #7): this used to PASS on a raw stanza-COUNT threshold
  # (>6 stanzas = "custom methods exist, can page a human"), which could — and did —
  # contradict the errors category's errnotify_methods finding, which decodes what the
  # methods actually DO. A box can carry more than 6 stanzas that are ALL still default/
  # diagela (no real site paging) or, in the other direction, carry a genuine custom
  # method among fewer than 7 total stanzas; either way the two checks were reading the
  # same on-box fact through two different, disagreeing lenses. Keep the SAME
  # capture gate and classifier (errnotify_decode) errnotify_methods uses, so
  # agreement between the two rows includes capture validation.
  errnotify_decode; RC=$?
  if [ "$RC" -ne 0 ] || [ "$ERRNOTIFY_OK" -ne 1 ]; then
    add monitoring errpt_notify "Error notification" NOT_ASSESSED med "$ERRNOTIFY_WHY" \
        "PTxray could not validate the errnotify ODM capture, so it cannot determine whether custom error-notification methods can page a human." \
        "make 'odmget errnotify' return complete ODM evidence, then re-run PTxray."
  else
    EN=$(printf '%s\n' "$ERRNOTIFY_ODM" | awk '/^[ \t]*en_name[ \t]*=/{n++} END{print n+0}')
    ENCUST2=$(printf '%s' "$ERRNOTIFY_DEC" | awk -F'\t' '{print $1+0}')
    if [ "${ENCUST2:-0}" -gt 0 ]; then
      add monitoring errpt_notify "Error notification" PASS low "$EN errnotify stanzas ($ENCUST2 custom alert method(s))" \
          "Custom error-notification methods exist beyond the defaults — errors can page a human." "n/a"
    else
      add monitoring errpt_notify "Error notification" WARN med "$EN errnotify stanzas (defaults only)" \
          "Errors log locally and tell no one — the error log only helps if someone happens to read it." \
          "add an errnotify ODM stanza that emails or pages on PERM hardware and disk errors."
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # remote_syslog
  SYSRAW=$(aix syslog_conf grep '@' /etc/syslog.conf); SYSRC=$?
  SYS_OK=0; SYSWHY=""
  if [ "$SYSRC" -ge 2 ]; then
    SYSWHY="not assessed — grep '@' /etc/syslog.conf capture failed (rc=$SYSRC)"
  elif [ "$SYSRC" -eq 1 ]; then
    SYS_OK=1
  elif [ -z "$SYSRAW" ]; then
    SYSWHY="not assessed — grep '@' /etc/syslog.conf capture empty (rc=0)"
  elif printf '%s\n' "$SYSRAW" | awk '
      NF{ n++; if(index($0,"@")==0) bad=1 }
      END{ if(n==0 || bad) exit 1 }
    '
  then
    SYS_OK=1
  else
    SYSWHY="not assessed — grep '@' /etc/syslog.conf capture unparseable (rc=0)"
  fi
  if [ "$SYS_OK" -ne 1 ]; then
    add monitoring remote_syslog "Remote syslog" NOT_ASSESSED low "$SYSWHY" \
        "Remote syslog forwarding could not be assessed because the syslog grep capture failed, returned no evidence, or returned output that does not match the requested '@' lines." \
        "run \"grep '@' /etc/syslog.conf\" manually, then re-run PTxray before treating remote logging as configured." "ffiec:II.C.22"
  else
  if [ "$SYSRC" -eq 1 ]; then
    SYS=0
  else
    SYS=$(printf '%s\n' "$SYSRAW" | awk '!/^[ \t]*#/ && /@/{n++} END{print n+0}')
  fi
  if [ "${SYS:-0}" -ge 1 ]; then
    add monitoring remote_syslog "Remote syslog" PASS low "$SYS forwarding rule(s)" \
        "syslog forwards to a remote collector — logs survive the box." "n/a" "ffiec:II.C.22"
  else
    add monitoring remote_syslog "Remote syslog" WARN low "no remote target" \
        "No remote syslog target — logs die with the box, exactly when you need them." \
        "add an '@loghost' line to /etc/syslog.conf and 'refresh -s syslogd'." "ffiec:II.C.22"
  fi
  fi
_AIXRAY_SESSION_KEYS=""

  # perf_history — reuse ps_e
  PERF_COLLECTOR_ALLOWLIST_RE='^(topasrec|xmwlm|nmon|topas_nmon|njmon|njmon_aix[0-9][0-9]*_v[0-9][0-9]*)$'
  PERF_COLLECTOR_ALLOWLIST='topasrec, xmwlm, nmon, topas_nmon, njmon, njmon_aix<digits>_v<digits>'
  typeset PSE_OK PSEWHY PSE_SHAPE_RC
  PSE_OK=0; PSEWHY=""
  if [ "$PSERC" -ne 0 ]; then
    PSEWHY="not assessed — ps -e -o comm capture failed (rc=$PSERC)"
  elif [ -z "$PSE" ]; then
    PSEWHY="not assessed — ps -e -o comm capture empty (rc=0)"
  else
    printf '%s\n' "$PSE" | awk '
      NR == 1 {
        if (NF != 1 || $1 != "COMMAND") bad=1
        next
      }
      NF {
        rows++
        if (NF != 1) bad=1
      }
      END { if (rows == 0 || bad) exit 1 }
    '
    PSE_SHAPE_RC=$?
    if [ "$PSE_SHAPE_RC" -eq 0 ]; then
      PSE_OK=1
    else
      PSEWHY="not assessed — ps -e -o comm capture unparseable (rc=0)"
    fi
  fi

  if [ "$PSE_OK" -ne 1 ]; then
    add monitoring perf_history "Performance history" NOT_ASSESSED low "$PSEWHY" \
        "PTxray could not validate the process list, so it cannot determine whether a performance-history collector is running." \
        "make 'ps -e -o comm' return a complete process list, then re-run PTxray."
  else
    PH=$(printf '%s\n' "$PSE" | grep -E "$PERF_COLLECTOR_ALLOWLIST_RE" | awk 'NR==1{print $1}')
    if [ -n "$PH" ]; then
      add monitoring perf_history "Performance history" PASS low \
          "collector $PH running (checked exact commands: $PERF_COLLECTOR_ALLOWLIST)" \
          "A performance-history collector is running — sizing and incident forensics have data to work from." "n/a"
    else
      add monitoring perf_history "Performance history" WARN low \
          "none running (checked exact commands: $PERF_COLLECTOR_ALLOWLIST)" \
          "No performance-history collection — sizing and incident forensics become guesswork." \
          "enable one of the accepted collector commands ($PERF_COLLECTOR_ALLOWLIST) so history exists when you need it."
    fi
  fi
_AIXRAY_SESSION_KEYS=""

  # backup_job (root-gated; silent skip unprivileged — F already covers backup evidence)
  CR=$(aix crontab_root crontab -l); RC=$?
  if [ "$RC" -ne 0 ]; then
    if [ "${MYUID:-0}" != "0" ]; then
      :  # cannot read root's crontab unprivileged — skip silently
    else
      add monitoring backup_job "Scheduled backup job" WARN med "no root crontab" \
          "No scheduled backup in root's crontab — where does the mksysb come from?" \
          "schedule mksysb/savevg in root's crontab, or confirm NIM/central backup owns it."
    fi
  elif printf '%s\n' "$CR" | awk '
    /^[[:space:]]*#/ { next }
    NF < 6 { next }
    {
      executable = $6
      sub(/^.*\//, "", executable)
      if (executable == "backup" ||
          executable ~ /(^|[^[:alnum:]])(mksysb|savevg)([^[:alnum:]]|$)/) {
        found = 1
        exit
      }
    }
    END { if (!found) exit 1 }
  '; then
    add monitoring backup_job "Scheduled backup job" PASS med "backup job scheduled" \
        "root's crontab schedules a backup — the mksysb has an owner and a cadence." "n/a"
  else
    add monitoring backup_job "Scheduled backup job" WARN med "no backup in crontab" \
        "No scheduled backup in root's crontab — where does the mksysb come from?" \
        "schedule mksysb/savevg in root's crontab, or confirm NIM/central backup owns it."
  fi
}

# ---- VIOS role depth (fires ONLY when IS_VIOS=1) -------------------------------------
# LAYER 2. Every finding here is built from IBM DOCUMENTED command output formats — NOT
# from a live VIOS (PowerVS gives no padmin access; a real test VIOS arrives with IBM
# Partner Silver tier). They are therefore documentation-grounded and PENDING live-VIOS
# validation; see docs/COVERAGE.md ("VIOS role checks — documentation-grounded, pending
# live-VIOS validation"). Discipline: conservative — WARN/informational, never a confident
# FAIL on a parse we could not verify live; a parse we cannot read degrades to WARN, not a
# hollow PASS. Each finding also carries the single-VIOS limit: the PARTNER VIOS's health
# lives on the other LPAR and a single-box scan cannot see it (dual-VIOS fleet view deferred).
function checks_vios {
  typeset SEAS SEA ESTAT SST LSA HAM CTL PRIO
  typeset SEACNT BADHA NOCTL NOPRIO SEADET
  typeset CLST RC CLBAD CLNODES CLPRESENT
  typeset NPIVRAW NPTOT NPBAD NPLIST NPSPAN NPFCS
  typeset LSNP NPFAB
  typeset VSRAW VSTOT VSBAD VSLIST BACKHD HD RP RPV RSVTOT RSVBAD RSVUNK RSVDET

  # ---- shared signals: CAA cluster presence + per-SEA HA config --------------------
  # Read cluster -status ONCE (used by ssp_cluster below AND by the SEA no-control-channel
  # logic: a CAA/SSP cluster enables the newer control-channel-less SEA failover, so a
  # missing ctl_chan is NOT a hard FAIL when a cluster is present).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  CLST=$(aix cluster_status ioscli cluster -status); RC=$?
  CLPRESENT=0
  if [ "$RC" -eq 0 ] && [ -n "$CLST" ] && printf '%s\n' "$CLST" | grep -qi 'Cluster'; then CLPRESENT=1; fi

  # sea_failover — Shared Ethernet Adapter HA posture (DEEPENED).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # Prefer the CONFIG attributes over parsing entstat sections: 'lsdev -dev <sea> -attr'
  # (== 'lsattr -El <sea>') exposes ha_mode {auto|standby|sharing|disabled}, ctl_chan (the
  # control-channel ent adapter, empty when unset), and priority (1-15). entstat -d <sea>
  # is read only to enrich the observed line with the RUNTIME State (PRIMARY/BACKUP/STANDBY,
  # or LIMBO/RECOVERY = cannot settle a role). Veteran signal: ha_mode=disabled OR an empty
  # ctl_chan (without a CAA cluster) means a second VIOS cannot take over the network cleanly
  # — a network SPOF / split-brain risk for every client LPAR bridged through this SEA. We
  # see only THIS VIOS's side; a clean local config still needs the partner VIOS confirmed.
  # SEA failover attributes. ha_mode=auto and ha_mode=sharing are documented in the IBM
  # mkvdev command reference (power9/9009-42A) and SEA load-sharing scenario (power10/
  # 9786-42H); ha_mode=standby is documented in the IBM Support technote "Verify Shared
  # Ethernet Adapter Configuration and Status"; ctl_chan=entN is the form in every
  # documented mkvdev example. entstat State values (INIT, PRIMARY, BACKUP, PRIMARY_SH,
  # BACKUP_SH, RECOVERY, NOTIFY, LIMBO) are per IBM Docs power9 "Shared Ethernet Adapter
  # failover statistics"; no STANDBY state is documented. ctl_chan is validated to look like
  # 'entN' precisely so an empty value (where awk would otherwise read the description
  # column) degrades to "unset", not a misparse.
  # KNOWN DEFECT (1.0.1 list, HIGH): the ha_mode gate below accepts only auto|standby,
  # so ha_mode=sharing — IBM-documented, supported SEA load sharing (power10 scenario
  # above) — is counted toward BADHA and renders a false FAIL "not failover-ready".
  # Deliberately unchanged in this identifier-scrub chunk; correctness fix queued.
  SEAS=$(aix lsdev_sea ioscli lsdev -type sea | awk 'NR>1 && $1 ~ /^ent[0-9]+$/{print $1}')
  if [ -n "$SEAS" ]; then
    SEACNT=0; BADHA=0; NOCTL=0; NOPRIO=0; SEADET=""
    for SEA in $SEAS; do
      SEACNT=$((SEACNT+1))
      LSA=$(aix "lsattr_sea_$SEA" ioscli lsdev -dev "$SEA" -attr)
      HAM=$(printf '%s\n' "$LSA" | awk '$1=="ha_mode"{print $2; exit}')
      CTL=$(printf '%s\n' "$LSA" | awk '$1=="ctl_chan"{print $2; exit}')
      PRIO=$(printf '%s\n' "$LSA" | awk '$1=="priority"{print $2; exit}')
      [ -z "$HAM" ] && HAM="unknown"
      # ctl_chan is a control-channel adapter (entN) when set; anything else = unset (an
      # empty attr value makes awk read the description word, so anchor on the entN shape).
      case "$CTL" in (ent[0-9]*) : ;; (*) CTL="";; esac
      case "$PRIO" in (''|*[!0-9]*) PRIO="";; esac
      case "$HAM" in (auto|standby) : ;; (*) BADHA=$((BADHA+1));; esac
      [ -z "$CTL" ] && NOCTL=$((NOCTL+1))
      [ -z "$PRIO" ] && NOPRIO=$((NOPRIO+1))
      ESTAT=$(aix "entstat_sea_$SEA" entstat -d "$SEA")
      SST=$(printf '%s\n' "$ESTAT" | awk -F: '/^[ \t]*State:/{v=$2; gsub(/^[ \t]+|[ \t]+$/,"",v); print v; exit}')
      [ -z "$SST" ] && SST="?"
      SEADET="$SEADET${SEADET:+; }$SEA ha_mode=$HAM ctl_chan=${CTL:-none} priority=${PRIO:-unset} state=$SST"
    done
    if [ "$BADHA" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" FAIL high "$SEADET" \
          "A Shared Ethernet Adapter on this VIOS is not configured for failover (ha_mode not auto/standby) — a second VIOS cannot take over the bridge, so every client LPAR bridged through this SEA loses its network the moment this VIOS goes down. This is not a redundant network." \
          "set the SEA for failover ('chdev -dev <sea> -attr ha_mode=auto ctl_chan=<ent> priority=<n>'), give the pair distinct priorities, and confirm the partner VIOS's SEA ('entstat -d <sea>' on both)."
    elif [ "$NOCTL" -gt 0 ] && [ "$CLPRESENT" -eq 0 ]; then
      add resilience sea_failover "SEA failover posture" FAIL high "$SEADET" \
          "A Shared Ethernet Adapter is set to fail over but has no control channel (ctl_chan) and no CAA cluster to replace it — the two VIOS cannot arbitrate primary/backup, so a failover can leave both bridging at once (split-brain: duplicated frames, a broadcast storm) or neither." \
          "add a control-channel adapter/VLAN ('mkvdev -sea ...'/'chdev -dev <sea> -attr ctl_chan=<ent>'), or adopt the CAA control-channel-less method on a supported VIOS level; verify on both VIOS."
    elif [ "$NOCTL" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" WARN med "$SEADET" \
          "A Shared Ethernet Adapter has no ctl_chan, but a CAA cluster is present — the newer control-channel-less SEA failover uses the cluster instead. Likely intentional; confirm it is actually the CAA method and not a half-removed control channel." \
          "confirm the SEA uses CAA-based failover (supported VIOS level + cluster) rather than a lost control channel; check the partner VIOS's SEA config too."
    elif [ "$NOPRIO" -gt 0 ]; then
      add resilience sea_failover "SEA failover posture" WARN med "$SEADET" \
          "The SEA is set for failover with a control channel, but a priority is unset/unreadable — without distinct priorities across the pair the primary/backup roles are undefined and can flap." \
          "set a priority on each side ('chdev -dev <sea> -attr priority=<n>'), distinct between the two VIOS (e.g. 1 and 2)."
    else
      add resilience sea_failover "SEA failover posture" PASS low "$SEADET" \
          "This VIOS's Shared Ethernet Adapter(s) are configured for failover (ha_mode auto/standby, a control channel set, a priority set) — the network bridge is set up to survive this VIOS. Single-box scan: confirm the partner VIOS's SEA (priority + state on the other LPAR) to prove the pair actually fails over." \
          "n/a"
    fi
  fi

  # vios_topology — single-vs-dual VIOS & the box-level SPOF verdict (NEW).
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # A single VIOS is a single point of failure for EVERY client LPAR it serves — both disk
  # AND network. Inherited shops are full of "dual VIOS" that is really one working side (the
  # second was never wired, or was wired and left broken). We infer HA topology from what one
  # box can see: a SEA configured for failover (ha_mode auto/standby + a control channel) OR
  # a CAA/SSP cluster implies a partner VIOS exists. A lone SEA with no HA config, and no
  # cluster, means either a genuinely standalone VIOS or a broken pair — both a SPOF worth
  # flagging. Conservative: WARN when we simply cannot see a partner (an inference, not a
  # confident FAIL); FAIL only when a SEA is present but demonstrably unable to fail over.
  # Verified: reuses the sea_failover attr reads above, which are documented per IBM
  # mkvdev command reference (see sea_failover comment for field sources).
  if [ -n "$SEAS" ] || [ "$CLPRESENT" -eq 1 ]; then
    if [ -n "$SEAS" ] && { [ "$BADHA" -gt 0 ] || [ "$NOCTL" -gt 0 ]; } && [ "$CLPRESENT" -eq 0 ]; then
      add resilience vios_topology "VIOS redundancy topology" FAIL high "SEA present, not failover-ready; no CAA cluster" \
          "This VIOS bridges the network but its SEA is not able to fail over to a partner (no control channel / ha_mode not set) and there is no CAA cluster — so a second VIOS cannot cleanly take over the network. Either this is a standalone VIOS (a single point of failure for every client's disk and network) or a broken pair where the second side was never fully wired." \
          "decide the intent: if it is meant to be an HA pair, wire the SEA control channel + ha_mode on BOTH VIOS and confirm the partner is serving; if it is genuinely standalone, treat this VIOS as a known SPOF (single client outage domain) in the runbook."
    elif { [ -n "$SEAS" ] && [ "$BADHA" -eq 0 ] && [ "$NOCTL" -eq 0 ]; } || [ "$CLPRESENT" -eq 1 ]; then
      add resilience vios_topology "VIOS redundancy topology" PASS low "HA config present (SEA failover / CAA cluster) — partner VIOS implied" \
          "This VIOS carries HA configuration (a failover-ready SEA and/or a CAA cluster), which implies a partner VIOS exists to take over. A single-box scan cannot PROVE the partner is healthy and actually serving — that lives on the other LPAR." \
          "confirm the second VIOS exists, is on a different physical path, and is genuinely serving clients (its own ptxray/entstat/lsmap) — do not assume 'configured for failover' means the partner is up."
    else
      add resilience vios_topology "VIOS redundancy topology" WARN high "no SEA HA config and no CAA cluster visible from this box" \
          "Nothing on this box indicates a partner VIOS — no failover-ready SEA, no CAA cluster. This may be a genuinely single VIOS, in which case every client LPAR's disk AND network depends on this one server: a single point of failure whose loss takes down all its clients." \
          "confirm whether a second VIOS exists and is actually serving; if not, this is a real SPOF — plan a partner VIOS, or document the single-VIOS risk and its blast radius explicitly."
    fi
  fi

  # npiv_maps — virtual FC (NPIV) mappings.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'lsmap -all -npiv': each vfchost has a "Status:" line (LOGGED_IN vs NOT_LOGGED_IN). A
  # vfchost NOT_LOGGED_IN (or with no backing FC name) has no live path to the fabric —
  # the client LPAR it serves has a dead or half virtual-FC path.
  NPIVRAW=$(aix lsmap_npiv ioscli lsmap -all -npiv)
  if [ -n "$NPIVRAW" ] && printf '%s\n' "$NPIVRAW" | grep -q '^Status:'; then
    # Separate awk passes (never a pipe-delimited $()+${%%|*} split — ksh treats a bare
    # '|' in a ${%%} pattern as alternation and strips the whole value to empty).
    NPTOT=$(printf '%s\n' "$NPIVRAW" | awk -F: '/^Status:/{n++} END{print n+0}')
    NPBAD=$(printf '%s\n' "$NPIVRAW" | awk -F: '/^Status:/{s=$2; gsub(/[ \t]/,"",s); if(s!="LOGGED_IN") n++} END{print n+0}')
    NPLIST=$(printf '%s\n' "$NPIVRAW" | awk -F: '
      $1 ~ /^vfchost[0-9]/ { split($0,a," "); name=a[1] }
      /^Status:/ { s=$2; gsub(/[ \t]/,"",s); if (s!="LOGGED_IN") printf "%s%s (%s)", (n++?", ":""), name, s }')
    if [ "${NPBAD:-0}" -gt 0 ]; then
      add storage npiv_maps "Virtual FC (NPIV) mappings" WARN high "$NPBAD of $NPTOT vfchost not logged in: $NPLIST" \
          "One or more virtual-FC host adapters are NOT_LOGGED_IN — the physical FC login to the fabric is down, so the client LPAR mapped to it has a dead or degraded virtual-FC path (if its second path via the partner VIOS is also down, that client loses disk)." \
          "check the physical fibre (fcstat/errpt on this VIOS, the SAN zoning and the switch port); on a dual-VIOS pair confirm the client still has a live path through the other VIOS."
    else
      add storage npiv_maps "Virtual FC (NPIV) mappings" PASS low "$NPTOT vfchost mapping(s), all LOGGED_IN" \
          "Every virtual-FC host adapter on this VIOS is logged in to the fabric — the client LPARs' NPIV paths through this VIOS are live." "n/a"
    fi

    # npiv_redundancy — is the NPIV path ACTUALLY redundant, from this VIOS's view (NEW).
    # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
    # Complements npiv_maps (login status) with the redundancy question a veteran asks:
    #  (1) any vfchost NOT_LOGGED_IN is a DEAD FC path for that client through this VIOS — FAIL
    #      (npiv_maps flags the same at WARN as a mapping issue; here it is the redundancy
    #      verdict: the client is relying on its OTHER VIOS right now).
    #  (2) do the physical FC ports feeding the vfchosts span more than one PHYSICAL ADAPTER?
    #      Two vfc on two ports of the SAME card is not adapter/fabric redundancy — one card
    #      or one fabric event kills them all. We derive the physical adapter from the FC loc
    #      code by stripping the -Tn port suffix (the -Cn card slot is the adapter); lsnports
    #      corroborates how many ports actually see a fabric (fabric column = 1).
    # NPIV parsing. The 'FC name:'/'FC loc code:' line layout and lsnports column order
    # (name physloc fabric tports aports swwpns awwpns) are VERIFIED against IBM Docs
    # power8/8408-44E and power10 "lsmap command" (verbatim example: both labels on one line,
    # no space after colon) and power8/8286-41A "lsnports command" (verbatim header).
    # fabric=1 means connected to the fabric, fabric=0 means not logged in (IBM Support
    # technote "Why IVM GUI does not list NPIV port"); fabric=2 is not established.
    # Conservative: if the physical span cannot be derived, PASS with an informational note
    # rather than a WARN/FAIL on a guess.
    LSNP=$(aix lsnports ioscli lsnports)
    NPFAB=$(printf '%s\n' "$LSNP" | awk 'NR>1 && $3+0>=1{n++} END{print n+0}')
    # distinct physical FC adapter slots feeding NPIV (loc code minus the -Tn port suffix)
    NPSPAN=$(printf '%s\n' "$NPIVRAW" | awk -F'FC loc code:' '
      /FC loc code:/ { v=$2; gsub(/^[ \t]+/,"",v); sub(/[ \t].*/,"",v); sub(/-T[0-9]+.*/,"",v);
                       if (v!="" && !s[v]++) n++ } END{print n+0}')
    # fallback span = distinct physical FC port names (FC name:) if loc codes did not parse
    NPFCS=$(printf '%s\n' "$NPIVRAW" | awk -F'FC name:' '
      /FC name:/ { v=$2; gsub(/^[ \t]+/,"",v); sub(/[ \t].*/,"",v);
                   if (v!="" && !s[v]++) n++ } END{print n+0}')
    [ "${NPSPAN:-0}" -eq 0 ] && NPSPAN=$NPFCS
    if [ "${NPBAD:-0}" -gt 0 ]; then
      add storage npiv_redundancy "NPIV path redundancy" FAIL high "$NPBAD of $NPTOT vfchost NOT_LOGGED_IN: $NPLIST" \
          "One or more virtual-FC host adapters on this VIOS are NOT_LOGGED_IN — that client's FC path THROUGH THIS VIOS is dead. Right now the client is surviving only on its other VIOS's path (if it has one); this side is not providing the redundancy it is supposed to." \
          "restore the physical FC login (fcstat/errpt on this VIOS, SAN zoning, switch port), then confirm the vfchost logs in; verify the client's second path via the partner VIOS is actually up so it is not a single path masquerading as two."
    elif [ "${NPSPAN:-0}" -ge 2 ]; then
      add storage npiv_redundancy "NPIV path redundancy" PASS low "$NPTOT vfchost across $NPSPAN physical FC adapter(s); $NPFAB fabric-connected port(s)" \
          "Every NPIV vfchost is logged in, and they ride more than one physical FC adapter on this VIOS — a single FC card/port loss does not take out all NPIV clients on this side." "n/a"
    else
      add storage npiv_redundancy "NPIV path redundancy" WARN high "all $NPTOT vfchost on a single physical FC adapter" \
          "Every NPIV vfchost is logged in, but they all ride ONE physical FC adapter on this VIOS — no fabric/adapter redundancy from this side. One FC card, port, or fabric event takes out every NPIV client served by this VIOS at once (they then depend entirely on the partner VIOS)." \
          "spread the NPIV maps across a second physical FC adapter/fabric on this VIOS ('vfcmap' to a vfchost backed by a different fcs), and confirm the partner VIOS uses a different adapter/fabric too."
    fi
  fi

  # vscsi_maps — virtual SCSI mappings with a missing backing device.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'lsmap -all': a vhost's VTD names its "Backing device"; VIOS prints "NO VIRTUAL TARGET
  # DEVICE FOUND" for an empty vhost, and a VTD "Status Defined" (not Available) is a
  # broken/offline mapping — either way the client LPAR's vSCSI disk is not being served.
  VSRAW=$(aix lsmap_vscsi ioscli lsmap -all)
  if [ -n "$VSRAW" ] && printf '%s\n' "$VSRAW" | awk '$1 ~ /^vhost[0-9]/{f=1} END{exit f?0:1}'; then
    # Separate awk passes for the same ksh ${%%|*} reason noted in npiv_maps above.
    VSTOT=$(printf '%s\n' "$VSRAW" | awk '$1 ~ /^vhost[0-9]/{n++} END{print n+0}')
    VSBAD=$(printf '%s\n' "$VSRAW" | awk '/NO VIRTUAL TARGET DEVICE FOUND/{n++} $1=="Status" && $2=="Defined"{n++} END{print n+0}')
    VSLIST=$(printf '%s\n' "$VSRAW" | awk '
      $1 ~ /^vhost[0-9]/ { vh=$1 }
      /NO VIRTUAL TARGET DEVICE FOUND/ { printf "%s%s (no VTD)", (n++?", ":""), vh }
      $1=="Status" && $2=="Defined" { printf "%s%s (Defined)", (n++?", ":""), vh }')
    if [ "${VSBAD:-0}" -gt 0 ]; then
      add storage vscsi_maps "Virtual SCSI mappings" WARN high "$VSBAD issue(s) across $VSTOT vhost: $VSLIST" \
          "A virtual-SCSI host adapter has no backing device, or a target device is Defined (offline) — the client LPAR mapped to it is not being served that vSCSI disk (a rebuild or a failed backing hdisk usually left it behind)." \
          "map the missing backing device ('mkvdev -vdev <hdisk> -vadapter <vhost>') or clear the stale one; on a dual-VIOS pair confirm the client still reaches the disk via the other VIOS."
    else
      add storage vscsi_maps "Virtual SCSI mappings" PASS low "$VSTOT vhost mapping(s), all backed" \
          "Every virtual-SCSI host adapter on this VIOS has a live backing device — the client LPARs' vSCSI disks served by this VIOS are mapped." "n/a"
    fi

    # vscsi_reserve — the silent killer of dual-VIOS vSCSI (NEW).
    # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
    # For a LUN to be served by BOTH VIOS (vSCSI failover), the backing hdisk must NOT hold a
    # SCSI reservation: reserve_policy=no_reserve (older attr reserve_lock=no). If a backing
    # LUN is single_path / PR_exclusive / reserve_lock=yes, the OTHER VIOS physically cannot
    # open it — so failover fails SILENTLY: everything looks mapped, the config looks dual,
    # but the moment this VIOS drops, the client's disk does not come back on the partner.
    # This is the highest-value fake-redundancy catch. For each backing hdisk from lsmap -all
    # we read its reserve_policy ('lsdev -dev <hdisk> -attr reserve_policy' == 'lsattr -El
    # <hdisk> -a reserve_policy'). Any backing LUN not no_reserve ⇒ FAIL; a value we cannot
    # read degrades to WARN (older disks expose reserve_lock instead, not reserve_policy).
    # Verified: ioscli 'lsdev -dev <hdisk> -attr reserve_policy' output layout. IBM Docs
    # power7/9117-MMB "Setting the reserve policy attributes of a device" documents the
    # lsattr ROW form: 'reserve_policy no_reserve Reserve Policy True'. The three-line
    # form ("value" header + blank + bare value) is known field behaviour not established
    # in IBM documentation. The parser accepts both forms (a lone known reserve token on
    # its own line, or a reserve_policy lsattr row) and treats anything else as
    # unknown -> WARN. reserve_policy tokens (AIX 7.3 "MPIO device attributes"): no_reserve,
    # single_path, PR_exclusive, PR_shared (case-insensitive). reserve_lock is the older
    # separate attribute (IBM Storage Scale 5.2.2 "Understanding Persistent Reserve"),
    # not a reserve_policy token.
    BACKHD=$(printf '%s\n' "$VSRAW" | awk '$1=="Backing" && $2=="device" && $3!="" && !s[$3]++{print $3}')
    if [ -n "$BACKHD" ]; then
      RSVTOT=0; RSVBAD=0; RSVUNK=0; RSVDET=""
      for HD in $BACKHD; do
        RSVTOT=$((RSVTOT+1))
        RP=$(aix "reserve_$HD" ioscli lsdev -dev "$HD" -attr reserve_policy)
        # Accept both output shapes: ioscli 'value\n\n<val>' (a known reserve token alone on
        # a line) and lsattr 'reserve_policy <val> <desc> True' (the reserve_policy row).
        RPV=$(printf '%s\n' "$RP" | awk '
          $1=="reserve_policy" && NF>=2 { v=$2 }
          $1=="no_reserve" || $1=="single_path" || $1=="PR_exclusive" || $1=="PR_shared" { v=$1 }
          END { print v }')
        if [ -z "$RPV" ]; then
          RSVUNK=$((RSVUNK+1)); RSVDET="$RSVDET${RSVDET:+, }$HD=?"
        elif [ "$RPV" = "no_reserve" ]; then
          RSVDET="$RSVDET${RSVDET:+, }$HD=no_reserve"
        else
          RSVBAD=$((RSVBAD+1)); RSVDET="$RSVDET${RSVDET:+, }$HD=$RPV"
        fi
      done
      if [ "$RSVBAD" -gt 0 ]; then
        add storage vscsi_reserve "vSCSI backing-LUN reservation" FAIL high "$RSVBAD of $RSVTOT backing LUN(s) reserved: $RSVDET" \
            "A backing LUN behind a vSCSI map is holding a SCSI reservation (reserve_policy not no_reserve) — the OTHER VIOS physically cannot open this LUN, so vSCSI failover for that client fails SILENTLY. Everything looks mapped and 'dual', but if this VIOS drops, the client's disk does not come back on the partner. This vSCSI path is not actually redundant." \
            "set the backing disk to no_reserve on this VIOS ('chdev -dev <hdisk> -attr reserve_policy=no_reserve'; older disks: reserve_lock=no) and confirm the SAME on the partner VIOS for the same LUN before relying on failover."
      elif [ "$RSVUNK" -eq "$RSVTOT" ]; then
        add storage vscsi_reserve "vSCSI backing-LUN reservation" WARN med "reserve_policy unreadable on all $RSVTOT backing LUN(s): $RSVDET" \
            "Could not read reserve_policy on the vSCSI backing LUNs — cannot confirm they are no_reserve, which dual-VIOS vSCSI failover requires (older disks expose reserve_lock instead). Not confirming this leaves a common silent-failover trap unchecked." \
            "check each backing hdisk ('lsdev -dev <hdisk> -attr reserve_policy' or 'lsattr -El <hdisk> -a reserve_lock') on BOTH VIOS; they must be no_reserve / reserve_lock=no to fail over."
      else
        add storage vscsi_reserve "vSCSI backing-LUN reservation" PASS low "$RSVTOT backing LUN(s), all no_reserve: $RSVDET" \
            "Every vSCSI backing LUN on this VIOS is no_reserve — the partner VIOS can physically open the same LUNs, so vSCSI failover is viable from this side. Single-box scan: confirm the partner VIOS holds no_reserve on the same LUNs too." "n/a"
      fi
    fi
  fi

  # ssp_cluster — Shared Storage Pool / CAA cluster state (reported ONLY when a cluster
  # exists on this VIOS). Reuses the cluster -status read at the top of this function.
  # documentation-grounded; validate on a live VIOS (IBM Partner Silver test box).
  # 'cluster -status': the pool and each node report a State (OK vs DOWN/DEGRADED). A node
  # DOWN or a degraded pool means the SSP's shared storage is not fully redundant. When no
  # cluster is defined the command errors / prints nothing — skip cleanly (no finding).
  if [ "$CLPRESENT" -eq 1 ]; then
    CLBAD=$(printf '%s\n' "$CLST" | awk '{u=toupper($0)} u ~ /DOWN|DEGRADED|FAILED|INCOMPLETE/{n++} END{print n+0}')
    CLNODES=$(printf '%s\n' "$CLST" | awk '/^[ \t]+[A-Za-z]/ && NR>2 {n++} END{print n+0}')
    if [ "${CLBAD:-0}" -gt 0 ]; then
      add resilience ssp_cluster "Shared Storage Pool cluster" WARN high "cluster reports a node/pool not OK" \
          "The Shared Storage Pool / CAA cluster reports a node down or a degraded pool — SSP-backed client disks may have lost a redundant path or a node's storage access." \
          "check 'cluster -status' and 'lssp -clustername <c>' on both VIOS; investigate the down node's repository-disk and SAN access before it becomes a client outage."
    else
      add resilience ssp_cluster "Shared Storage Pool cluster" PASS low "cluster + ${CLNODES} node(s) report OK" \
          "The Shared Storage Pool / CAA cluster and its nodes report OK — the shared pool backing client disks is healthy on this VIOS's view." "n/a"
    fi
  fi
}

# ---- --flrt-export: FLRT Vulnerability Checker upload files (established pattern) -------------------
# Emit the two inputs IBM's FLRT VC consumes — the full colon — the full colon
# fileset inventory ('lslpp -Lcq' == our 'lslpp -qcL') and the ifix inventory
# ('emgr -lv3') — to timestamped files the admin uploads at esupport.ibm.com/.../flrt/vc.
# Read-only: writes ONLY into <dir> on this box, reads nothing it does not already read.
# Filenames follow FLRT.report: <epoch>_<host>_<oslevel>_<date>.{lslpp,emgr}.txt
if [ -n "$FLRT_EXPORT" ]; then
  if ! mkdir -p "$FLRT_EXPORT" 2>/dev/null; then
    echo "ptxray: --flrt-export: cannot create directory '$FLRT_EXPORT'" >&2; exit 2
  fi
  FLRT_EPOCH=$(date +%s 2>/dev/null); [ -n "$FLRT_EPOCH" ] || FLRT_EPOCH=0
  FLRT_DATE=$(echo "$TODAY" | tr -d ' ')
  FLRT_HOST=$(printf '%s' "${HOST%%.*}" | tr -cd 'A-Za-z0-9_.-'); [ -n "$FLRT_HOST" ] || FLRT_HOST=unknown
  FLRT_OS=${OSLEVEL:-unknown}
  FLRT_BASE="${FLRT_EPOCH}_${FLRT_HOST}_${FLRT_OS}_${FLRT_DATE}"
  FLRT_LSLPP="$FLRT_EXPORT/$FLRT_BASE.lslpp.txt"
  FLRT_EMGR="$FLRT_EXPORT/$FLRT_BASE.emgr.txt"
  umask 077
  aix lslpp_qcL lslpp -qcL > "$FLRT_LSLPP" 2>/dev/null
  aix emgr_lv3 emgr -lv3   > "$FLRT_EMGR"  2>/dev/null
  FLRT_NL=$(awk 'END{print NR+0}' "$FLRT_LSLPP" 2>/dev/null)
  FLRT_NE=$(awk 'END{print NR+0}' "$FLRT_EMGR" 2>/dev/null)
  echo "ptxray: FLRT export written to $FLRT_EXPORT/"
  echo "  $FLRT_BASE.lslpp.txt   ($FLRT_NL lines)  <- upload to IBM FLRT Vulnerability Checker"
  echo "  $FLRT_BASE.emgr.txt    ($FLRT_NE lines)  <- upload to IBM FLRT Vulnerability Checker"
  echo "  then: h""ttps://esupport.ibm.com/customercare/flrt/vc"
  exit 0
fi

# Inventory modules expose fact renderers later in the report and assessment-
# gap checks here. Keep their definitions ahead of both call sites.
_AIXRAY_SESSION_KEYS=""
# Emit one JSON member named "software" from the lslpp -qcL capture already
# held by the patch checks. This module also contributes the corresponding
# assessment finding; the integration build owns both spine calls.
function software_inventory_emit_gap {
  typeset SI_FATAL_REASON
  SI_FATAL_REASON=$1

  printf '%s\n' "$SI_FATAL_REASON" | awk '
    BEGIN {
      classification_gap = "ISV/workload classification uses explicit IBM Java, Python, and Perl lpp_source/name-pair heuristics; every other fileset remains UNCLASSIFIED."
      unmanaged_gap = "Software not registered with lslpp -Lc is not assessed."
      business_gap = "Business criticality, active use, and workload coupling are not established by lslpp -Lc and remain NOT_ASSESSED."
      workload_gap = "Only package-managed IBM Java, Python, and Perl runtimes matched by explicit lpp_source/name-pair heuristics are normalized; package publisher/provenance remains NOT_ASSESSED, and absence does not prove that no other ISV or workload software exists."
    }

    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") {
          result = result "\\\\"
        } else if (character == "\"") {
          result = result "\\\""
        } else if (character == "\t") {
          result = result "\\t"
        } else if (character == "\r") {
          result = result "\\r"
        } else {
          result = result character
        }
      }
      return result
    }

    {
      if (NR > 1) reason = reason "\\n"
      reason = reason $0
    }

    END {
      printf "\"software\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"platform\":\"AIX\","
      printf "\"reason\":\"%s\",", json_escape(reason)
      printf "\"source\":{\"capture\":\"lslpp_qcL\",\"command\":\"lslpp -qcL\","
      printf "\"format\":\"lslpp -Lc colon-delimited (headings suppressed)\",\"rc\":null},"

      printf "\"filesets\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", json_escape(reason)
      printf "\"captured_count\":null,\"emitted_count\":null,"
      printf "\"invalid_row_count\":null,\"invalid_row_marker\":null,"
      printf "\"omitted_count\":null,\"truncated\":null,"
      printf "\"truncation_marker\":null,\"items\":null},"

      printf "\"isv_workloads\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", json_escape(reason)
      printf "\"basis\":null,\"detected_count\":null,"
      printf "\"emitted_count\":null,\"omitted_count\":null,"
      printf "\"truncated\":null,\"truncation_marker\":null,\"items\":null,"
      printf "\"gap\":\"%s\"},", json_escape(workload_gap)
      printf "\"gaps\":[\"%s\",\"%s\",\"%s\"]}", \
        json_escape(classification_gap), json_escape(unmanaged_gap), \
        json_escape(business_gap)
    }
  '
}

function emit_fact_software {
  typeset SI_FILESET_LIMIT SI_WORKLOAD_LIMIT SI_EVIDENCE_LIMIT
  typeset SI_RC SI_CONFIRMED SI_AWK_RC SI_JSON SI_AWK_STATUS SI_JSON_OK

  SI_FILESET_LIMIT=${1:-1000}
  case "$SI_FILESET_LIMIT" in
    [1-9]|[1-9][0-9]|[1-9][0-9][0-9]|1000) ;;
    *) SI_FILESET_LIMIT=1000 ;;
  esac

  SI_WORKLOAD_LIMIT=${2:-100}
  case "$SI_WORKLOAD_LIMIT" in
    [1-9]|[1-9][0-9]|100) ;;
    *) SI_WORKLOAD_LIMIT=100 ;;
  esac

  SI_EVIDENCE_LIMIT=${3:-25}
  case "$SI_EVIDENCE_LIMIT" in
    [1-9]|1[0-9]|2[0-5]) ;;
    *) SI_EVIDENCE_LIMIT=25 ;;
  esac

  SI_RC=${LSLPPQ_RC:-}
  case "$SI_RC" in
    [0-9]|[0-9][0-9]|[0-9][0-9][0-9])
      SI_CONFIRMED=1
      SI_AWK_RC=$SI_RC
      ;;
    *)
      SI_CONFIRMED=0
      SI_AWK_RC=0
      ;;
  esac

  SI_JSON=$(printf '%s\n' "${LSLPPQ:-}" | awk -F: \
    -v confirmed="$SI_CONFIRMED" -v capture_rc="$SI_AWK_RC" \
    -v max_rows="$SI_FILESET_LIMIT" \
    -v max_workloads="$SI_WORKLOAD_LIMIT" \
    -v max_evidence="$SI_EVIDENCE_LIMIT" '
    BEGIN {
      state_name["A"] = "APPLIED"
      state_name["B"] = "BROKEN"
      state_name["C"] = "COMMITTED"
      state_name["E"] = "EFIX_LOCKED"
      state_name["O"] = "OBSOLETE"
      state_name["?"] = "INCONSISTENT"

      classification_gap = "ISV/workload classification uses explicit IBM Java, Python, and Perl lpp_source/name-pair heuristics; every other fileset remains UNCLASSIFIED."
      unmanaged_gap = "Software not registered with lslpp -Lc is not assessed."
      business_gap = "Business criticality, active use, and workload coupling are not established by lslpp -Lc and remain NOT_ASSESSED."
      workload_gap = "Only package-managed IBM Java, Python, and Perl runtimes matched by explicit lpp_source/name-pair heuristics are normalized; package publisher/provenance remains NOT_ASSESSED, and absence does not prove that no other ISV or workload software exists."
    }

    function usable_field(value) {
      return value != "" && value !~ /[[:cntrl:]]/
    }

    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") {
          result = result "\\\\"
        } else if (character == "\"") {
          result = result "\\\""
        } else {
          result = result character
        }
      }
      return result
    }

    function remember_workload(product_id, product_name, category,
                               version, fileset, key, evidence_key, number) {
      key = product_id SUBSEP version
      if (!(key in workload_seen)) {
        workload_seen[key] = 1
        workload_order[++workload_count] = key
        workload_id[key] = product_id
        workload_name[key] = product_name
        workload_category[key] = category
        workload_version[key] = version
      }

      evidence_key = key SUBSEP fileset
      if (!(evidence_key in evidence_seen)) {
        evidence_seen[evidence_key] = 1
        number = ++workload_evidence_count[key]
        workload_evidence[key SUBSEP number] = fileset
      }
    }

    function classify(row, lpp_source, fileset, version, product_id) {
      product_id = ""
      if (lpp_source ~ /^Java[0-9_]+\.(jre|sdk)$/ &&
          fileset == lpp_source) {
        product_id = "ibm-java"
        remember_workload(product_id, "IBM Java", "runtime", version, fileset)
      } else if ((lpp_source ~ /^python[0-9]+$/ ||
                  lpp_source ~ /^python[0-9]+\.[0-9]+$/ ||
                  lpp_source ~ /^python[0-9]+\.[0-9]+\.base$/) &&
                 (fileset == lpp_source ||
                  index(fileset, lpp_source "-") == 1)) {
        product_id = "python"
        remember_workload(product_id, "Python", "runtime", version, fileset)
      } else if (lpp_source == "perl.rte" && fileset == lpp_source) {
        product_id = "perl"
        remember_workload(product_id, "Perl", "runtime", version, fileset)
      }

      if (product_id == "") {
        row_class[row] = "UNCLASSIFIED"
        row_product[row] = ""
      } else {
        row_class[row] = "WORKLOAD_RUNTIME"
        row_product[row] = product_id
      }
    }

    function emit_gaps() {
      printf "\"gaps\":[\"%s\",\"%s\",\"%s\"]", classification_gap, unmanaged_gap, business_gap
    }

    function emit_not_assessed(reason, rc_json) {
      printf "\"software\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"platform\":\"AIX\","
      printf "\"reason\":\"%s\",", reason
      printf "\"source\":{\"capture\":\"lslpp_qcL\",\"command\":\"lslpp -qcL\","
      printf "\"format\":\"lslpp -Lc colon-delimited (headings suppressed)\",\"rc\":%s},", rc_json

      printf "\"filesets\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", reason
      printf "\"captured_count\":null,\"emitted_count\":null,"
      printf "\"invalid_row_count\":null,\"invalid_row_marker\":null,"
      printf "\"omitted_count\":null,\"truncated\":null,"
      printf "\"truncation_marker\":null,\"items\":null},"

      printf "\"isv_workloads\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"reason\":\"%s\",", reason
      printf "\"basis\":null,\"detected_count\":null,"
      printf "\"emitted_count\":null,\"omitted_count\":null,"
      printf "\"truncated\":null,\"truncation_marker\":null,\"items\":null,"
      printf "\"gap\":\"%s\"},", workload_gap
      emit_gaps()
      printf "}"
    }

    /^[ \t\r]*$/ { next }

    {
      saw_nonblank++
      if ($0 !~ /^[ \t]*#/ && NF >= 6 && usable_field($1) && usable_field($2) &&
          usable_field($3) && ($6 in state_name)) {
        row = ++valid_count
        row_lpp[row] = $1
        row_name[row] = $2
        row_version[row] = $3
        row_state_code[row] = $6
        row_state[row] = state_name[$6]
        if ($2 ~ /^bos\.rte(\.|$)/ && !($2 in bos_family_seen)) {
          bos_family_seen[$2] = 1
          bos_family_count++
        }
        classify(row, $1, $2, $3)
      } else {
        invalid_count++
      }
    }

    END {
      if (!confirmed) {
        emit_not_assessed("lslpp -qcL capture return code was not confirmed",
                          "null")
        exit
      }
      if ((capture_rc + 0) != 0) {
        reason = "lslpp -qcL capture failed (rc=" (capture_rc + 0) ")"
        emit_not_assessed(reason, capture_rc + 0)
        exit
      }
      if (valid_count == 0) {
        if (saw_nonblank == 0) {
          reason = "lslpp -qcL capture was empty"
        } else {
          reason = "lslpp -qcL capture had no structurally valid rows (" invalid_count " malformed)"
        }
        emit_not_assessed(reason, "0")
        exit
      }
      if (valid_count < 50 || bos_family_count < 3) {
        reason = "lslpp -qcL capture was implausibly small (" valid_count " structurally valid rows; minimum 50, " (bos_family_count + 0) " distinct bos.rte filesets)"
        emit_not_assessed(reason, "0")
        exit
      }

      emitted_count = valid_count
      if (emitted_count > max_rows) emitted_count = max_rows
      omitted_count = valid_count - emitted_count
      fileset_status = "COMPLETE"
      if (invalid_count > 0 || omitted_count > 0) fileset_status = "PARTIAL"

      fileset_reason = "null"
      if (invalid_count > 0 && omitted_count > 0) {
        fileset_reason = "\"capture contained " invalid_count " malformed rows and output omitted " omitted_count " valid rows\""
      } else if (invalid_count > 0) {
        fileset_reason = "\"capture contained " invalid_count " malformed rows\""
      } else if (omitted_count > 0) {
        fileset_reason = "\"output bounded at " emitted_count " of " valid_count " valid rows\""
      }

      printf "\"software\":{"
      printf "\"status\":\"PARTIAL\",\"platform\":\"AIX\",\"reason\":null,"
      printf "\"source\":{\"capture\":\"lslpp_qcL\",\"command\":\"lslpp -qcL\","
      printf "\"format\":\"lslpp -Lc colon-delimited (headings suppressed)\",\"rc\":0},"

      printf "\"filesets\":{"
      printf "\"status\":\"%s\",\"reason\":%s,", fileset_status, fileset_reason
      printf "\"captured_count\":%d,\"emitted_count\":%d,", valid_count, emitted_count
      printf "\"invalid_row_count\":%d,", invalid_count
      if (invalid_count > 0) {
        if (invalid_count == 1) {
          printf "\"invalid_row_marker\":\"1 malformed row not emitted\","
        } else {
          printf "\"invalid_row_marker\":\"%d malformed rows not emitted\",", invalid_count
        }
      } else {
        printf "\"invalid_row_marker\":null,"
      }
      printf "\"omitted_count\":%d,", omitted_count
      if (omitted_count > 0) {
        printf "\"truncated\":true,"
        if (omitted_count == 1) {
          printf "\"truncation_marker\":\"1 more fileset not emitted (limit %d)\",", max_rows
        } else {
          printf "\"truncation_marker\":\"%d more filesets not emitted (limit %d)\",", omitted_count, max_rows
        }
      } else {
        printf "\"truncated\":false,\"truncation_marker\":null,"
      }

      printf "\"items\":["
      for (row = 1; row <= emitted_count; row++) {
        if (row > 1) printf ","
        printf "{\"lpp_source\":\"%s\",\"name\":\"%s\",", json_escape(row_lpp[row]), json_escape(row_name[row])
        printf "\"version\":\"%s\",\"state_code\":\"%s\",", json_escape(row_version[row]), row_state_code[row]
        printf "\"state\":\"%s\",\"classification\":\"%s\",", row_state[row], row_class[row]
        if (row_product[row] == "") {
          printf "\"normalized_product_id\":null}"
        } else {
          printf "\"normalized_product_id\":\"%s\"}", row_product[row]
        }
      }
      printf "]},"

      printf "\"isv_workloads\":{"
      printf "\"status\":\"PARTIAL\",\"reason\":null,"
      printf "\"basis\":\"package_name_pair_heuristics\","
      workload_emitted = workload_count
      if (workload_emitted > max_workloads) workload_emitted = max_workloads
      workload_omitted = workload_count - workload_emitted
      printf "\"detected_count\":%d,\"emitted_count\":%d,", workload_count, workload_emitted
      printf "\"omitted_count\":%d,", workload_omitted
      if (workload_omitted > 0) {
        printf "\"truncated\":true,"
        if (workload_omitted == 1) {
          printf "\"truncation_marker\":\"1 more workload product not emitted (limit %d)\",", max_workloads
        } else {
          printf "\"truncation_marker\":\"%d more workload products not emitted (limit %d)\",", workload_omitted, max_workloads
        }
      } else {
        printf "\"truncated\":false,\"truncation_marker\":null,"
      }
      printf "\"items\":["
      for (workload = 1; workload <= workload_emitted; workload++) {
        key = workload_order[workload]
        if (workload > 1) printf ","
        printf "{\"product_id\":\"%s\",\"name\":\"%s\",", workload_id[key], workload_name[key]
        printf "\"vendor\":null,\"category\":\"%s\",", workload_category[key]
        evidence_count = workload_evidence_count[key]
        evidence_emitted = evidence_count
        if (evidence_emitted > max_evidence) evidence_emitted = max_evidence
        evidence_omitted = evidence_count - evidence_emitted
        printf "\"version\":\"%s\",", json_escape(workload_version[key])
        printf "\"evidence_count\":%d,\"evidence_emitted_count\":%d,", evidence_count, evidence_emitted
        printf "\"evidence_omitted_count\":%d,", evidence_omitted
        if (evidence_omitted > 0) {
          printf "\"evidence_truncated\":true,"
          if (evidence_omitted == 1) {
            printf "\"evidence_truncation_marker\":\"1 more evidence fileset not emitted (limit %d)\",", max_evidence
          } else {
            printf "\"evidence_truncation_marker\":\"%d more evidence filesets not emitted (limit %d)\",", evidence_omitted, max_evidence
          }
        } else {
          printf "\"evidence_truncated\":false,\"evidence_truncation_marker\":null,"
        }
        printf "\"evidence_filesets\":["
        for (evidence = 1; evidence <= evidence_emitted; evidence++) {
          if (evidence > 1) printf ","
          printf "\"%s\"", json_escape(workload_evidence[key SUBSEP evidence])
        }
        printf "]}"
      }
      printf "],\"gap\":\"%s\"},", workload_gap
      emit_gaps()
      printf "}"
    }
  '); SI_AWK_STATUS=$?
  SI_JSON_OK=0
  case "$SI_JSON" in
    '"software":{'*'}') SI_JSON_OK=1 ;;
  esac
  if [ "$SI_AWK_STATUS" -ne 0 ] || [ -z "$SI_JSON" ] ||
     [ "$SI_JSON_OK" -ne 1 ]; then
    software_inventory_emit_gap \
      "lslpp -qcL software fact emitter failed (rc=$SI_AWK_STATUS)"
  else
    printf '%s' "$SI_JSON"
  fi
}

# The fact emitter deliberately preserves partial inventory. This finding
# separately discloses that inventory is not a currency/use/support assessment.
function check_software_inventory {
  typeset SI_CHECK_RC SI_CHECK_CONFIRMED SI_CHECK_PROFILE
  typeset SI_CHECK_VALID SI_CHECK_BOS SI_CHECK_OBS
  typeset SI_CHECK_MEAN SI_CHECK_FIX

  SI_CHECK_RC=${LSLPPQ_RC:-}
  case "$SI_CHECK_RC" in
    [0-9]|[0-9][0-9]|[0-9][0-9][0-9]) SI_CHECK_CONFIRMED=1 ;;
    *) SI_CHECK_CONFIRMED=0 ;;
  esac

  if [ "$SI_CHECK_CONFIRMED" -ne 1 ]; then
    SI_CHECK_OBS="not assessed — lslpp -qcL capture return code was not confirmed"
    SI_CHECK_MEAN="Without a confirmed inventory-source result, installed software cannot be assessed for completeness, support, active use, or business criticality."
    SI_CHECK_FIX="capture 'lslpp -qcL' with its return code and rerun PTxray."
  elif [ "$SI_CHECK_RC" -ne 0 ]; then
    SI_CHECK_OBS="not assessed — lslpp -qcL capture failed (rc=$SI_CHECK_RC)"
    SI_CHECK_MEAN="The installed-fileset inventory source failed, so software currency and workload coverage could not be assessed."
    SI_CHECK_FIX="restore access to 'lslpp -qcL' and rerun PTxray."
  else
    SI_CHECK_PROFILE=$(printf '%s\n' "${LSLPPQ:-}" | awk -F: '
      function usable(value) {
        return value != "" && value !~ /[[:cntrl:]]/
      }
      /^[ \t\r]*$/ { next }
      {
        nonblank++
        if ($0 !~ /^[ \t]*#/ && NF >= 6 && usable($1) && usable($2) &&
            usable($3) && $6 ~ /^(A|B|C|E|O|[?])$/) {
          valid++
          if ($2 ~ /^bos[.]rte([.]|$)/ && !bos[$2]++) bos_count++
        }
      }
      END { printf "%d:%d:%d\n", nonblank+0, valid+0, bos_count+0 }
    ')
    SI_CHECK_VALID=$(printf '%s\n' "$SI_CHECK_PROFILE" |
      awk -F: '{print $2+0}')
    SI_CHECK_BOS=$(printf '%s\n' "$SI_CHECK_PROFILE" |
      awk -F: '{print $3+0}')
    if [ "$SI_CHECK_VALID" -eq 0 ]; then
      if [ "${SI_CHECK_PROFILE%%:*}" -eq 0 ]; then
        SI_CHECK_OBS="not assessed — lslpp -qcL capture was empty"
      else
        SI_CHECK_OBS="not assessed — lslpp -qcL capture had no structurally valid rows"
      fi
      SI_CHECK_MEAN="No trustworthy installed-fileset inventory was available, so software currency and workload coverage could not be assessed."
      SI_CHECK_FIX="capture the complete colon-delimited output of 'lslpp -qcL' and rerun PTxray."
    elif [ "$SI_CHECK_VALID" -lt 50 ] || [ "$SI_CHECK_BOS" -lt 3 ]; then
      SI_CHECK_OBS="not assessed — lslpp -qcL capture was implausibly small ($SI_CHECK_VALID structurally valid rows; minimum 50, $SI_CHECK_BOS distinct bos.rte filesets)"
      SI_CHECK_MEAN="The capture is too small to represent a normal AIX installed-fileset inventory, so absence of software or workload components cannot be trusted."
      SI_CHECK_FIX="supply a complete 'lslpp -qcL' capture and rerun PTxray."
    else
      SI_CHECK_OBS="not assessed — $SI_CHECK_VALID installed filesets were inventoried, but unmanaged software, active use, support entitlement, and business criticality were not established"
      SI_CHECK_MEAN="A package inventory does not identify software installed outside lslpp, prove which workloads are active, or establish their support and business requirements."
      SI_CHECK_FIX="supplement lslpp inventory with the approved software catalog, runtime/process evidence, support data, and workload ownership records."
    fi
  fi

  add patch software_inventory "Software inventory coverage" \
    NOT_ASSESSED high "$SI_CHECK_OBS" "$SI_CHECK_MEAN" "$SI_CHECK_FIX"
}
_AIXRAY_SESSION_KEYS=""
# Standalone fact and finding producer for AIX adapter firmware and microcode
# inventory. Include-safe: integration calls the fact emitter from the facts
# renderer and the check from the assessment spine.

function adapter_microcode_json_escape {
  awk '
    {
      s=$0
      gsub(/\\/, "\\\\", s)
      gsub(/"/, "\\\"", s)
      gsub(/\t/, "\\t", s)
      gsub(/\r/, "\\r", s)
      gsub(/[\001-\010\013\014\016-\037]/, "", s)
      if (seen++) printf "\\n"
      printf "%s", s
    }
  '
}

function adapter_microcode_lsdev_shape {
  awk '
    function is_location(value) {
      return value ~ /^[0-9][0-9]-[0-9][0-9](-[0-9][0-9])*$/ ||
        value ~ /^[A-Z][0-9][A-Za-z0-9.]*-[A-Za-z0-9][A-Za-z0-9.\/-]*$/
    }
    NF {
      rows++
      if (NF < 3 || $1 !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ ||
          $2 !~ /^[A-Za-z][A-Za-z0-9_-]*$/ || seen[$1]++) {
        bad=1
        next
      }
      first=3
      if (is_location($3)) first=4
      description=""
      for (i=first; i<=NF; i++)
        description=description (description=="" ? "" : " ") $i
      if (description=="") bad=1
    }
    END { if (rows==0 || bad) exit 1 }
  '
}

function adapter_microcode_parse_lsdev {
  awk '
    function is_location(value) {
      return value ~ /^[0-9][0-9]-[0-9][0-9](-[0-9][0-9])*$/ ||
        value ~ /^[A-Z][0-9][A-Za-z0-9.]*-[A-Za-z0-9][A-Za-z0-9.\/-]*$/
    }
    NF {
      first=3
      if (is_location($3)) first=4
      description=""
      for (i=first; i<=NF; i++)
        description=description (description=="" ? "" : " ") $i
      category=$1
      sub(/[0-9][0-9]*$/, "", category)
      if (category=="") category="adapter"
      printf "%s\t%s\t%s\n", $1, category, description
    }
  '
}

# Validate the whole lsmcode capture and print its recognized layout. Bang
# records may have typed continuation rows (for example raid-dasd); columnar
# records require only a device token plus a nonempty remainder, never a fixed
# number of fields.
function adapter_microcode_lsmcode_shape {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function valid_name(value) {
      return value ~ /^[A-Za-z][A-Za-z0-9_.-]*$/
    }
    {
      line=$0
      sub(/\r$/, "", line)
      line=trim(line)
      if (line=="") next

      if (mode=="") {
        bang=index(line, "!")
        if (bang>1) {
          mode="bang"
        } else {
          count=split(line, header, /[ \t]+/)
          has_level=0
          for (i=2; i<=count; i++)
            if (tolower(header[i]) ~ /level/) has_level=1
          if (tolower(header[1])=="device" && has_level) {
            mode="column"
            next
          }
          bad=1
          next
        }
      }

      if (mode=="bang") {
        bang=index(line, "!")
        if (bang>1) {
          name=substr(line, 1, bang-1)
          level=trim(substr(line, bang+1))
          if (!valid_name(name) || level=="" || seen[name]++) bad=1
          else records++
          have_record=1
        } else if (!(have_record && line ~ /^[A-Za-z][A-Za-z0-9-]*:[^ \t]/)) {
          bad=1
        }
      } else {
        if (line ~ /^-+[ \t]+-+/) next
        name=line
        sub(/[ \t].*$/, "", name)
        level=line
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", level)
        level=trim(level)
        if (!valid_name(name) || tolower(name)=="device" ||
            level==line || level=="" || seen[name]++) bad=1
        else records++
      }
    }
    END {
      if (bad || records==0) exit 1
      print mode
    }
  '
}

function adapter_microcode_lsmcode_level {
  typeset wanted layout
  wanted=$1
  layout=$2
  awk -v wanted="$wanted" -v layout="$layout" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function unavailable(value, normalized) {
      value=trim(value)
      normalized=tolower(value)
      gsub(/[ _-]/, "", normalized)
      if (normalized=="unknown" || normalized=="notavailable" ||
          normalized=="notapplicable" || normalized=="none" ||
          normalized=="n/a") return 1
      return 0
    }
    function usable(value) {
      value=trim(value)
      if (unavailable(value)) return 0
      if (value !~ /[0-9]/ || value ~ /[^A-Za-z0-9_.:+#|() \/-]/) return 0
      return 1
    }
    {
      line=$0
      sub(/\r$/, "", line)
      line=trim(line)
      if (line=="") next

      if (layout=="bang") {
        bang=index(line, "!")
        if (bang>1) {
          current=substr(line, 1, bang-1)
          if (current==wanted) {
            if (found) bad=1
            value=trim(substr(line, bang+1))
            found=1
          }
        } else if (current==wanted && line ~ /^[A-Za-z][A-Za-z0-9-]*:/) {
          value=value "|" line
        }
      } else {
        if (!header_seen) {
          header_seen=1
          next
        }
        if (line ~ /^-+[ \t]+-+/) next
        name=line
        sub(/[ \t].*$/, "", name)
        rest=line
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", rest)
        rest=trim(rest)
        if (name==wanted) {
          if (found) bad=1
          value=rest
          found=1
        }
      }
    }
    END {
      if (!found) exit 1
      gsub(/[ \t]+/, " ", value)
      value=trim(value)
      if (bad) exit 3
      if (unavailable(value)) {
        print value
        exit 2
      }
      if (!usable(value)) exit 3
      print value
    }
  '
}

function adapter_microcode_lscfg_shape {
  typeset wanted
  wanted=$1
  awk -v wanted="$wanted" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    {
      line=$0
      sub(/\r$/, "", line)
      if (line ~ /^[ \t]*$/) next

      nonblank++
      if (nonblank==1) {
        header=line
        sub(/^[ \t]+/, "", header)
        name=header
        sub(/[ \t].*$/, "", name)
        remainder=header
        sub(/^[^ \t][^ \t]*[ \t][ \t]*/, "", remainder)
        if (name!=wanted || remainder==header || trim(remainder)=="") bad=1
        next
      }

      if (line ~ /^[ \t]+[^ \t].*[.][.][.]/) {
        label=line
        sub(/^[ \t]+/, "", label)
        sub(/[.][.][.].*$/, "", label)
        if (trim(label)=="") bad=1
        else vpd++
      }
    }
    END { if (bad || nonblank==0 || vpd==0) exit 1 }
  '
}

function adapter_microcode_lscfg_level {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function label_type(value) {
      value=tolower(value)
      if (value ~ /rom level[.][(]alterable[)]/) return 1
      if (value ~ /microcode([ \t]*level)?/) return 2
      if (value ~ /firmware[ \t]*level/) return 3
      if (value ~ /device specific[.][(]z9[)]/) return 4
      return 0
    }
    function field_value(value) {
      if (value ~ /[.][.][.]/)
        sub(/^.*[.][.][.][.]*[ \t]*/, "", value)
      else if (value ~ /:/)
        sub(/^[^:]*:[ \t]*/, "", value)
      else
        return ""
      return trim(value)
    }
    function usable(value, normalized) {
      value=trim(value)
      normalized=tolower(value)
      gsub(/[ _-]/, "", normalized)
      if (normalized=="unknown" || normalized=="notavailable" ||
          normalized=="notapplicable" || normalized=="none" ||
          normalized=="n/a") return 0
      if (value !~ /[0-9]/ || value ~ /[^A-Za-z0-9_.:+#|() \/-]/) return 0
      return 1
    }
    {
      kind=label_type($0)
      candidate=field_value($0)
      if (kind && usable(candidate) && (!found || kind<best)) {
        best=kind
        value=candidate
        found=1
      }
    }
    END {
      if (!found) exit 1
      gsub(/[ \t]+/, " ", value)
      print trim(value)
    }
  '
}

function adapter_microcode_emit_unavailable {
  typeset reason escaped
  reason=$1
  escaped=$(printf '%s' "$reason" | adapter_microcode_json_escape)
  printf '%s' '"adapter_microcode": { "status": "NOT_ASSESSED", "platform": "AIX", '
  printf '%s' '"inventory_source_cmd": "lsdev -Cc adapter", "primary_source_cmd": "lsmcode -A", '
  printf '"capture_gaps": ["%s"], "reason": "%s", "adapters": null }' \
    "$escaped" "$escaped"
}

function emit_fact_adapter_microcode {
  typeset LSDEV_OUT LSDEV_RC LSDEV_ROWS LSDEV_WHY
  typeset LSMCODE_OUT LSMCODE_RC LSMCODE_LAYOUT LSMCODE_SHAPE_RC LSMCODE_WHY
  typeset DEV CATEGORY DESCRIPTION LEVEL SOURCE STATUS REASON
  typeset LSM_LEVEL LSM_LEVEL_RC LSM_REASON LSCFG_OUT LSCFG_RC LSCFG_WHY
  typeset ITEMS ITEM KNOWN UNKNOWN TOP_STATUS TOP_REASON
  typeset EDEV ECATEGORY EDESCRIPTION ELEVEL ESOURCE EREASON ETOP_REASON EGAP

  LSDEV_OUT=$(aix lsdev_adapter lsdev -Cc adapter)
  LSDEV_RC=$?
  if [ "$LSDEV_RC" -ne 0 ]; then
    LSDEV_WHY="lsdev -Cc adapter capture failed (rc=$LSDEV_RC)"
    adapter_microcode_emit_unavailable "$LSDEV_WHY"
    return
  fi
  if [ -z "$LSDEV_OUT" ]; then
    adapter_microcode_emit_unavailable "lsdev -Cc adapter capture empty (rc=0)"
    return
  fi
  if ! printf '%s\n' "$LSDEV_OUT" | adapter_microcode_lsdev_shape; then
    adapter_microcode_emit_unavailable "lsdev -Cc adapter capture unparseable (rc=0)"
    return
  fi
  LSDEV_ROWS=$(printf '%s\n' "$LSDEV_OUT" | adapter_microcode_parse_lsdev)

  LSMCODE_OUT=$(aix lsmcode_A lsmcode -A)
  LSMCODE_RC=$?
  LSMCODE_LAYOUT=""
  LSMCODE_WHY=""
  if [ "$LSMCODE_RC" -ne 0 ]; then
    LSMCODE_WHY="lsmcode -A capture failed (rc=$LSMCODE_RC)"
  elif [ -z "$LSMCODE_OUT" ]; then
    LSMCODE_WHY="lsmcode -A capture empty (rc=0)"
  else
    LSMCODE_LAYOUT=$(printf '%s\n' "$LSMCODE_OUT" | adapter_microcode_lsmcode_shape)
    LSMCODE_SHAPE_RC=$?
    if [ "$LSMCODE_SHAPE_RC" -ne 0 ] || [ -z "$LSMCODE_LAYOUT" ]; then
      LSMCODE_LAYOUT=""
      LSMCODE_WHY="lsmcode -A capture unparseable (rc=0)"
    fi
  fi

  ITEMS=""
  KNOWN=0
  UNKNOWN=0
  while IFS='	' read -r DEV CATEGORY DESCRIPTION
  do
    [ -n "$DEV" ] || continue
    LEVEL=""
    SOURCE=""
    STATUS="NOT_ASSESSED"
    REASON=""
    LSM_REASON="$LSMCODE_WHY"

    if [ -n "$LSMCODE_LAYOUT" ]; then
      LSM_LEVEL=$(printf '%s\n' "$LSMCODE_OUT" |
        adapter_microcode_lsmcode_level "$DEV" "$LSMCODE_LAYOUT")
      LSM_LEVEL_RC=$?
      case "$LSM_LEVEL_RC" in
        0)
          LEVEL=$LSM_LEVEL
          SOURCE="lsmcode -A"
          STATUS="OBSERVED"
          ;;
        1)
          LSM_REASON="lsmcode -A did not report $DEV"
          ;;
        2)
          LSM_REASON="lsmcode -A device reported microcode level $LSM_LEVEL for $DEV"
          ;;
        *)
          LSM_REASON="lsmcode -A record for $DEV unparseable (rc=0)"
          ;;
      esac
    fi

    if [ "$STATUS" != "OBSERVED" ]; then
      LSCFG_OUT=$(aix "lscfg_vpl_$DEV" lscfg -vpl "$DEV")
      LSCFG_RC=$?
      LSCFG_WHY=""
      if [ "$LSCFG_RC" -ne 0 ]; then
        LSCFG_WHY="lscfg -vpl $DEV capture failed (rc=$LSCFG_RC)"
      elif [ -z "$LSCFG_OUT" ]; then
        LSCFG_WHY="lscfg -vpl $DEV capture empty (rc=0)"
      elif ! printf '%s\n' "$LSCFG_OUT" |
          adapter_microcode_lscfg_shape "$DEV"; then
        LSCFG_WHY="lscfg -vpl $DEV capture unparseable (rc=0)"
      else
        LEVEL=$(printf '%s\n' "$LSCFG_OUT" | adapter_microcode_lscfg_level)
        if [ -n "$LEVEL" ]; then
          SOURCE="lscfg -vpl $DEV"
          STATUS="OBSERVED"
        else
          LSCFG_WHY="lscfg -vpl $DEV: no microcode/firmware level reported by device (no usable ROM/MicroCode/Firmware/Z9 VPD value)"
        fi
      fi
      if [ "$STATUS" != "OBSERVED" ]; then
        REASON="$LSM_REASON${LSM_REASON:+; }$LSCFG_WHY"
        SOURCE="lsmcode -A; lscfg -vpl $DEV"
      fi
    fi

    EDEV=$(printf '%s' "$DEV" | adapter_microcode_json_escape)
    ECATEGORY=$(printf '%s' "$CATEGORY" | adapter_microcode_json_escape)
    EDESCRIPTION=$(printf '%s' "$DESCRIPTION" | adapter_microcode_json_escape)
    ESOURCE=$(printf '%s' "$SOURCE" | adapter_microcode_json_escape)
    if [ "$STATUS" = "OBSERVED" ]; then
      ELEVEL=$(printf '%s' "$LEVEL" | adapter_microcode_json_escape)
      ITEM=$(printf '%s' "{ \"name\": \"$EDEV\", \"category\": \"$ECATEGORY\", \"description\": \"$EDESCRIPTION\", \"microcode_level\": \"$ELEVEL\", \"source_cmd\": \"$ESOURCE\", \"status\": \"OBSERVED\", \"reason\": null }")
      KNOWN=$((KNOWN + 1))
    else
      EREASON=$(printf '%s' "$REASON" | adapter_microcode_json_escape)
      ITEM=$(printf '%s' "{ \"name\": \"$EDEV\", \"category\": \"$ECATEGORY\", \"description\": \"$EDESCRIPTION\", \"microcode_level\": null, \"source_cmd\": \"$ESOURCE\", \"status\": \"NOT_ASSESSED\", \"reason\": \"$EREASON\" }")
      UNKNOWN=$((UNKNOWN + 1))
    fi
    if [ -n "$ITEMS" ]; then ITEMS="$ITEMS, $ITEM"; else ITEMS=$ITEM; fi
  done <<EOF
$LSDEV_ROWS
EOF

  TOP_REASON=""
  if [ "$KNOWN" -eq 0 ]; then
    TOP_STATUS="NOT_ASSESSED"
    TOP_REASON="no enumerated adapter had a trustworthy microcode level; see per-adapter reasons"
  elif [ "$UNKNOWN" -eq 0 ]; then
    TOP_STATUS="COMPLETE"
  else
    TOP_STATUS="PARTIAL"
  fi

  printf '"adapter_microcode": { "status": "%s", "platform": "AIX", ' "$TOP_STATUS"
  printf '%s' '"inventory_source_cmd": "lsdev -Cc adapter", "primary_source_cmd": "lsmcode -A", '
  if [ -n "$LSMCODE_WHY" ]; then
    EGAP=$(printf '%s' "$LSMCODE_WHY" | adapter_microcode_json_escape)
    printf '"capture_gaps": ["%s"], ' "$EGAP"
  else
    printf '%s' '"capture_gaps": [], '
  fi
  if [ -n "$TOP_REASON" ]; then
    ETOP_REASON=$(printf '%s' "$TOP_REASON" | adapter_microcode_json_escape)
    printf '"reason": "%s", ' "$ETOP_REASON"
  else
    printf '%s' '"reason": null, '
  fi
  printf '"adapters": [%s] }' "$ITEMS"
}

# A finding is the assessment surface for this tool. Inventory facts remain
# available separately, but they must never be the only evidence that the
# adapter-microcode topic ran.
function check_adapter_microcode {
  typeset AM_OUT AM_RC AM_PHYSICAL AM_NOUN AM_VERB AM_OBS AM_MEAN AM_FIX

  AM_OUT=$(aix lsdev_adapter lsdev -Cc adapter); AM_RC=$?
  if [ "$AM_RC" -ne 0 ]; then
    AM_OBS="not assessed — lsdev -Cc adapter inventory failed (rc=$AM_RC)"
    AM_MEAN="Adapter inventory was unavailable, so this LPAR's physical-adapter microcode ownership and currency could not be assessed."
    AM_FIX="restore access to 'lsdev -Cc adapter', then rerun PTxray; review any physical adapter levels against the current hardware-specific reference."
  elif [ -z "$AM_OUT" ]; then
    AM_OBS="not assessed — lsdev -Cc adapter reported no adapters (rc=0)"
    AM_MEAN="An empty adapter inventory cannot establish whether this LPAR owns physical adapter microcode."
    AM_FIX="verify the complete output of 'lsdev -Cc adapter' and rerun PTxray."
  elif ! printf '%s\n' "$AM_OUT" | adapter_microcode_lsdev_shape; then
    AM_OBS="not assessed — lsdev -Cc adapter inventory was unparseable (rc=0)"
    AM_MEAN="The adapter inventory did not match the expected AIX lsdev structure, so physical-adapter ownership and microcode currency could not be assessed."
    AM_FIX="capture the complete output of 'lsdev -Cc adapter', correct the replay source if needed, and rerun PTxray."
  else
    AM_PHYSICAL=$(printf '%s\n' "$AM_OUT" |
      awk 'NF && /PCI/{n++} END{print n+0}')
    if [ "$AM_PHYSICAL" -eq 0 ]; then
      AM_OBS="not assessed — no physical adapters were reported by lsdev -Cc adapter; virtual and pseudo-device inventory alone has no LPAR-owned adapter microcode to assess"
      AM_MEAN="This LPAR reported only virtual or pseudo adapters; their physical firmware is owned by the VIOS, hypervisor, or cloud provider rather than by this LPAR."
      AM_FIX="review adapter firmware and microcode on the owning VIOS, hypervisor, or provider control plane."
    else
      AM_NOUN=adapters; AM_VERB=were
      if [ "$AM_PHYSICAL" -eq 1 ]; then
        AM_NOUN=adapter; AM_VERB=was
      fi
      AM_OBS="not assessed — $AM_PHYSICAL physical $AM_NOUN $AM_VERB inventoried, but installed levels were not compared with current hardware-specific reference data"
      AM_MEAN="Physical adapters are present, but inventory alone cannot establish whether their installed microcode is current."
      AM_FIX="collect each physical adapter's installed level and compare it with the current IBM hardware-specific microcode guidance."
    fi
  fi

  add lifecycle adapter_microcode "Adapter microcode currency" \
    NOT_ASSESSED high "$AM_OBS" "$AM_MEAN" "$AM_FIX"
}
_AIXRAY_SESSION_KEYS=""
# Emit one JSON member named "storage_layout" from fresh, replayable AIX
# captures and one explicit assessment-gap finding. The integration build owns
# the spine include plus both check and facts-emitter call sites.

function storage_layout_has_nonblank {
  printf '%s\n' "$1" | awk 'NF { found=1 } END { exit(found ? 0 : 1) }'
}

function storage_layout_emit_inventory_gap {
  typeset SL_FATAL_REASON
  SL_FATAL_REASON=$1

  printf '%s\n' "$SL_FATAL_REASON" | awk '
    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") result = result "\\\\"
        else if (character == "\"") result = result "\\\""
        else if (character == "\t") result = result "\\t"
        else if (character == "\r") result = result "\\r"
        else result = result character
      }
      return result
    }
    {
      if (NR > 1) reason = reason "\\n"
      reason = reason $0
    }
    END {
      printf "\"storage_layout\":{"
      printf "\"status\":\"NOT_ASSESSED\",\"platform\":\"AIX\","
      printf "\"reason\":\"%s\",", json_escape(reason)
      printf "\"inventory_source_cmd\":\"lspv\","
      printf "\"size_source_cmd\":\"getconf DISK_SIZE /dev/<hdisk>\","
      printf "\"type_source_cmd\":\"%s\",", \
        json_escape("lsdev -Cc disk -F \"name:status:description\"")
      printf "\"path_source_cmd\":\"%s\",", \
        json_escape("lspath -F \"name parent path_id status\"")
      printf "\"capture_gaps\":[\"%s\"],\"disks\":null}", \
        json_escape(reason)
    }
  '
}

function emit_fact_storage_layout {
  typeset SL_LSPV SL_LSPV_RC SL_LSPV_ROWS SL_SHAPE_RC
  typeset SL_LSDEV SL_LSDEV_RC SL_LSDEV_ROWS SL_LSDEV_REASON
  typeset SL_LSPATH SL_LSPATH_RC SL_LSPATH_ROWS SL_LSPATH_REASON
  typeset SL_DISK SL_PVID SL_VG SL_KEY
  typeset SL_SIZE_RAW SL_SIZE_RC SL_SIZE SL_SIZE_REASON SL_SIZE_KNOWN
  typeset SL_DESC SL_DESC_REASON SL_DESC_KNOWN SL_LOOKUP_RC
  typeset SL_PATH_DATA SL_PATH_REST SL_PATH_COUNT SL_PATH_SUMMARY
  typeset SL_PATH_FAILED SL_PATH_MISSING SL_PATH_NOTE SL_PATH_REASON
  typeset SL_PATH_KNOWN

  # lspv is the inventory authority. A failed, empty, or malformed inventory
  # cannot safely supply device names for any later dynamic capture key.
  SL_LSPV=$(aix lspv lspv); SL_LSPV_RC=$?
  if [ "$SL_LSPV_RC" -ne 0 ]; then
    storage_layout_emit_inventory_gap \
      "lspv capture failed (rc=$SL_LSPV_RC)"
    return 0
  fi
  if ! storage_layout_has_nonblank "$SL_LSPV"; then
    storage_layout_emit_inventory_gap "lspv capture empty (rc=0)"
    return 0
  fi
  SL_LSPV_ROWS=$(printf '%s\n' "$SL_LSPV" | awk '
    function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
    function pvid(value) {
      return value == "none" ||
        (value ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/ &&
         substr(value,16,1) != "" && substr(value,17,1) == "")
    }
    function vg(value) {
      return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
    }
    /^[ \t]*$/ { next }
    {
      rows++
      if (NF < 3 || !hdisk($1) || !pvid($2) || !vg($3) || seen[$1]++) {
        bad=1
        next
      }
      disk[rows]=$1
      disk_pvid[rows]=$2
      disk_vg[rows]=$3
    }
    END {
      if (bad || rows == 0) exit 1
      for (row=1; row<=rows; row++)
        printf "%s\t%s\t%s\n", disk[row], disk_pvid[row], disk_vg[row]
    }
  '); SL_SHAPE_RC=$?
  if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSPV_ROWS" ]; then
    storage_layout_emit_inventory_gap "lspv capture unparseable (rc=0)"
    return 0
  fi

  # Device descriptions are supplemental. Their capture gap must not erase
  # the lspv inventory or prevent independent size/path facts from surfacing.
  SL_LSDEV_REASON=""
  SL_LSDEV_ROWS=""
  SL_LSDEV=$(aix lsdev_disk_fields lsdev -Cc disk -F \
    "name:status:description"); SL_LSDEV_RC=$?
  if [ "$SL_LSDEV_RC" -ne 0 ]; then
    SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture failed (rc=$SL_LSDEV_RC)"
  elif ! storage_layout_has_nonblank "$SL_LSDEV"; then
    SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture empty (rc=0)"
  else
    SL_LSDEV_ROWS=$(printf '%s\n' "$SL_LSDEV" | awk -F ':' '
      function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
      /^[ \t]*$/ { next }
      {
        rows++
        if (NF != 3 || !hdisk($1) ||
            ($2 != "Available" && $2 != "Defined" && $2 != "Stopped") ||
            seen[$1]++) {
          bad=1
          next
        }
        description=$3
        if (description !~ /[^ \t]/) {
          bad=1
          next
        }
        disk[rows]=$1
        disk_description[rows]=description
      }
      END {
        if (bad || rows == 0) exit 1
        for (row=1; row<=rows; row++)
          printf "%s\t%s\n", disk[row], disk_description[row]
      }
    '); SL_SHAPE_RC=$?
    if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSDEV_ROWS" ]; then
      SL_LSDEV_ROWS=""
      SL_LSDEV_REASON="lsdev -Cc disk -F \"name:status:description\" capture unparseable (rc=0)"
    fi
  fi

  # Empty lspath is a normal non-MPIO observation, but it does not prove a
  # numeric zero for every disk. Preserve it as an explicit assessment gap.
  SL_LSPATH_REASON=""
  SL_LSPATH_ROWS=""
  SL_LSPATH=$(aix lspath_disk lspath -F "name parent path_id status")
  SL_LSPATH_RC=$?
  if [ "$SL_LSPATH_RC" -ne 0 ]; then
    SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture failed (rc=$SL_LSPATH_RC)"
  elif ! storage_layout_has_nonblank "$SL_LSPATH"; then
    SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture empty (rc=0); no MPIO paths reported"
  else
    SL_LSPATH_ROWS=$(printf '%s\n' "$SL_LSPATH" | awk '
      function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
      function token(value) {
        return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
      }
      /^[ \t]*$/ { next }
      {
        rows++
        key=$1 SUBSEP $2 SUBSEP $3
        if (NF < 4 || !hdisk($1) || !token($2) ||
            $3 !~ /^[0-9][0-9]*$/ || !token($4) || seen[key]++) {
          bad=1
          next
        }
        disk[rows]=$1
        parent[rows]=$2
        path_id[rows]=$3
        path_status[rows]=$4
      }
      END {
        if (bad || rows == 0) exit 1
        for (row=1; row<=rows; row++)
          printf "%s\t%s\t%s\t%s\n", disk[row], parent[row],
            path_id[row], path_status[row]
      }
    '); SL_SHAPE_RC=$?
    if [ "$SL_SHAPE_RC" -ne 0 ] || [ -z "$SL_LSPATH_ROWS" ]; then
      SL_LSPATH_ROWS=""
      SL_LSPATH_REASON="lspath -F \"name parent path_id status\" capture unparseable (rc=0)"
    fi
  fi

  {
    printf '%s\n' "$SL_LSPV_ROWS" | awk -F '\t' \
      '{ printf "I\t%s\t%s\t%s\n", $1, $2, $3 }'
    [ -n "$SL_LSDEV_REASON" ] && printf 'G\t%s\n' "$SL_LSDEV_REASON"
    [ -n "$SL_LSPATH_REASON" ] && printf 'G\t%s\n' "$SL_LSPATH_REASON"

    printf '%s\n' "$SL_LSPV_ROWS" |
      while read SL_DISK SL_PVID SL_VG; do
        # Each size is independently captured and gated. A plausible-looking
        # payload from a failed command is never used.
        SL_KEY="getconf_disk_size_$SL_DISK"
        SL_SIZE_RAW=$(aix "$SL_KEY" getconf DISK_SIZE "/dev/$SL_DISK")
        SL_SIZE_RC=$?
        SL_SIZE=""
        SL_SIZE_REASON=""
        SL_SIZE_KNOWN=0
        if [ "$SL_SIZE_RC" -ne 0 ]; then
          SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture failed (rc=$SL_SIZE_RC)"
        elif ! storage_layout_has_nonblank "$SL_SIZE_RAW"; then
          SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture empty (rc=0)"
        else
          SL_SIZE=$(printf '%s\n' "$SL_SIZE_RAW" | awk '
            /^[ \t]*$/ { next }
            {
              rows++
              if (NF != 1 || $1 !~ /^[1-9][0-9]*$/) bad=1
              value=$1
            }
            END {
              if (bad || rows != 1) exit 1
              print value
            }
          '); SL_SHAPE_RC=$?
          if [ "$SL_SHAPE_RC" -eq 0 ] && [ -n "$SL_SIZE" ]; then
            SL_SIZE_KNOWN=1
          else
            SL_SIZE=""
            SL_SIZE_REASON="getconf DISK_SIZE /dev/$SL_DISK capture unparseable (rc=0)"
          fi
        fi

        SL_DESC=""
        SL_DESC_REASON=""
        SL_DESC_KNOWN=0
        if [ -n "$SL_LSDEV_REASON" ]; then
          SL_DESC_REASON=$SL_LSDEV_REASON
        else
          SL_DESC=$(printf '%s\n' "$SL_LSDEV_ROWS" | awk -F '\t' \
            -v wanted="$SL_DISK" '
              $1 == wanted { print $2; found=1; exit }
              END { if (!found) exit 1 }
            ')
          SL_LOOKUP_RC=$?
          if [ "$SL_LOOKUP_RC" -eq 0 ] && [ -n "$SL_DESC" ]; then
            SL_DESC_KNOWN=1
          else
            SL_DESC=""
            SL_DESC_REASON="lsdev -Cc disk -F \"name:status:description\" reported no description for $SL_DISK (rc=0)"
          fi
        fi

        SL_PATH_COUNT=""
        SL_PATH_SUMMARY=""
        SL_PATH_NOTE=""
        SL_PATH_REASON=""
        SL_PATH_KNOWN=0
        if [ -n "$SL_LSPATH_REASON" ]; then
          SL_PATH_REASON=$SL_LSPATH_REASON
        else
          SL_PATH_DATA=$(printf '%s\n' "$SL_LSPATH_ROWS" | awk -F '\t' \
            -v wanted="$SL_DISK" '
              $1 == wanted {
                count++
                status=$4
                if (!seen[status]++) order[++states]=status
                if (status == "Failed") failed++
                if (status == "Missing") missing++
              }
              END {
                if (count == 0) exit 1
                printf "%d:", count
                for (state=1; state<=states; state++) {
                  if (state > 1) printf ", "
                  printf "%s=%d", order[state], seen[order[state]]
                }
                printf ":%d:%d", failed+0, missing+0
              }
            ')
          SL_LOOKUP_RC=$?
          if [ "$SL_LOOKUP_RC" -eq 0 ] && [ -n "$SL_PATH_DATA" ]; then
            SL_PATH_COUNT=${SL_PATH_DATA%%:*}
            SL_PATH_REST=${SL_PATH_DATA#*:}
            SL_PATH_SUMMARY=${SL_PATH_REST%%:*}
            SL_PATH_REST=${SL_PATH_REST#*:}
            SL_PATH_FAILED=${SL_PATH_REST%%:*}
            SL_PATH_MISSING=${SL_PATH_REST#*:}
            if [ "$SL_PATH_FAILED" -gt 0 ] || [ "$SL_PATH_MISSING" -gt 0 ]; then
              SL_PATH_NOTE="Failed/Missing path state observed (Failed=$SL_PATH_FAILED, Missing=$SL_PATH_MISSING)"
            fi
            SL_PATH_KNOWN=1
          else
            SL_PATH_REASON="lspath -F \"name parent path_id status\" reported no paths for $SL_DISK (rc=0)"
          fi
        fi

        [ -n "$SL_SIZE_REASON" ] && printf 'G\t%s\n' "$SL_SIZE_REASON"
        [ -n "$SL_DESC_REASON" ] && printf 'G\t%s\n' "$SL_DESC_REASON"
        [ -n "$SL_PATH_REASON" ] && printf 'G\t%s\n' "$SL_PATH_REASON"
        printf 'D\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\tX\n' \
          "$SL_DISK" "$SL_SIZE_KNOWN" "$SL_SIZE" "$SL_SIZE_REASON" \
          "$SL_DESC_KNOWN" "$SL_DESC" "$SL_DESC_REASON" \
          "$SL_PATH_KNOWN" "$SL_PATH_COUNT" "$SL_PATH_SUMMARY" \
          "$SL_PATH_NOTE" "$SL_PATH_REASON"
      done
  } | awk -F '\t' '
    function json_escape(value, result, character) {
      result = ""
      while (value != "") {
        character = substr(value, 1, 1)
        value = substr(value, 2)
        if (character == "\\") result = result "\\\\"
        else if (character == "\"") result = result "\\\""
        else if (character == "\t") result = result "\\t"
        else if (character == "\r") result = result "\\r"
        else result = result character
      }
      return result
    }
    function add_gap(reason) {
      if (reason != "" && !gap_seen[reason]++) gap[++gap_count]=reason
    }
    function add_reason(current, reason) {
      if (reason == "") return current
      if (current == "") return reason
      if (index("; " current "; ", "; " reason "; ") > 0) return current
      return current "; " reason
    }
    $1 == "G" {
      add_gap($2)
      next
    }
    $1 == "I" {
      inventory_pvid[$2]=$3
      inventory_vg[$2]=$4
      next
    }
    $1 == "D" {
      row=++disk_count
      disk[row]=$2
      size_known[row]=$3+0
      size[row]=$4
      size_reason[row]=$5
      description_known[row]=$6+0
      description[row]=$7
      description_reason[row]=$8
      path_known[row]=$9+0
      path_count[row]=$10
      path_summary[row]=$11
      path_note[row]=$12
      path_reason[row]=$13
      next
    }
    END {
      printf "\"storage_layout\":{"
      printf "\"status\":\"%s\",", (gap_count ? "PARTIAL" : "COMPLETE")
      printf "\"platform\":\"AIX\","
      if (gap_count) printf "\"reason\":\"one or more storage-layout facts were not assessed\","
      else printf "\"reason\":null,"
      printf "\"inventory_source_cmd\":\"lspv\","
      printf "\"size_source_cmd\":\"getconf DISK_SIZE /dev/<hdisk>\","
      printf "\"type_source_cmd\":\"%s\",", \
        json_escape("lsdev -Cc disk -F \"name:status:description\"")
      printf "\"path_source_cmd\":\"%s\",", \
        json_escape("lspath -F \"name parent path_id status\"")
      printf "\"capture_gaps\":["
      for (item=1; item<=gap_count; item++) {
        if (item > 1) printf ","
        printf "\"%s\"", json_escape(gap[item])
      }
      printf "],\"disks\":["
      for (row=1; row<=disk_count; row++) {
        if (row > 1) printf ","
        assessed=size_known[row] && description_known[row] && path_known[row]
        reason=""
        if (!size_known[row]) reason=add_reason(reason, size_reason[row])
        if (!description_known[row]) reason=add_reason(reason, description_reason[row])
        if (!path_known[row]) reason=add_reason(reason, path_reason[row])

        printf "{\"hdisk\":\"%s\",", json_escape(disk[row])
        if (size_known[row]) printf "\"size_mb\":%s,", size[row]
        else printf "\"size_mb\":null,"
        printf "\"vg\":\"%s\",", json_escape(inventory_vg[disk[row]])
        printf "\"pvid\":\"%s\",", json_escape(inventory_pvid[disk[row]])
        if (description_known[row])
          printf "\"type_desc\":\"%s\",", json_escape(description[row])
        else printf "\"type_desc\":null,"
        if (path_known[row]) {
          printf "\"path_count\":%s,", path_count[row]
          printf "\"path_status_summary\":\"%s\",", \
            json_escape(path_summary[row])
          if (path_note[row] != "")
            printf "\"path_note\":\"%s\",", json_escape(path_note[row])
          else printf "\"path_note\":null,"
        } else {
          printf "\"path_count\":null,\"path_status_summary\":null,"
          printf "\"path_note\":null,"
        }
        printf "\"status\":\"%s\",", (assessed ? "OBSERVED" : "NOT_ASSESSED")
        if (assessed) printf "\"reason\":null,"
        else printf "\"reason\":\"%s\",", json_escape(reason)
        printf "\"not_assessed\":{"
        separator=""
        if (!size_known[row]) {
          printf "\"size_mb\":\"%s\"", json_escape(size_reason[row])
          separator=","
        }
        if (!description_known[row]) {
          printf "%s\"type_desc\":\"%s\"", separator, \
            json_escape(description_reason[row])
          separator=","
        }
        if (!path_known[row]) {
          printf "%s\"path_count\":\"%s\"", separator, \
            json_escape(path_reason[row])
          printf ",\"path_status_summary\":\"%s\"", \
            json_escape(path_reason[row])
        }
        printf "}}"
      }
      printf "]}"
    }
  '
}

# Storage facts describe what AIX reported. A topology finding still needs an
# approved expected-state baseline; emit the gap explicitly when that is absent.
function check_storage_layout {
  typeset SL_CHECK_OUT SL_CHECK_RC SL_CHECK_ROWS SL_CHECK_SHAPE_RC
  typeset SL_CHECK_COUNT SL_CHECK_NOUN SL_CHECK_VERB SL_CHECK_OBS
  typeset SL_CHECK_MEAN SL_CHECK_FIX

  SL_CHECK_OUT=$(aix lspv lspv); SL_CHECK_RC=$?
  if [ "$SL_CHECK_RC" -ne 0 ]; then
    SL_CHECK_OBS="not assessed — lspv storage inventory failed (rc=$SL_CHECK_RC)"
    SL_CHECK_MEAN="The physical-volume inventory source was unavailable, so storage topology, ownership, and redundancy could not be assessed."
    SL_CHECK_FIX="restore access to 'lspv', provide the approved storage topology baseline, and rerun PTxray."
  elif ! storage_layout_has_nonblank "$SL_CHECK_OUT"; then
    SL_CHECK_OBS="not assessed — lspv reported no storage inventory (rc=0)"
    SL_CHECK_MEAN="An empty physical-volume inventory cannot establish disk ownership, topology, or redundancy."
    SL_CHECK_FIX="verify the complete output of 'lspv', provide the approved storage topology baseline, and rerun PTxray."
  else
    SL_CHECK_ROWS=$(printf '%s\n' "$SL_CHECK_OUT" | awk '
      function hdisk(value) { return value ~ /^hdisk[0-9][0-9]*$/ }
      function pvid(value) {
        return value == "none" ||
          (value ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/ &&
           substr(value,16,1) != "" && substr(value,17,1) == "")
      }
      function vg(value) {
        return value ~ /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/
      }
      /^[ \t]*$/ { next }
      {
        rows++
        if (NF < 3 || !hdisk($1) || !pvid($2) || !vg($3) ||
            seen[$1]++) bad=1
      }
      END {
        if (bad || rows == 0) exit 1
        print rows
      }
    '); SL_CHECK_SHAPE_RC=$?
    if [ "$SL_CHECK_SHAPE_RC" -ne 0 ] || [ -z "$SL_CHECK_ROWS" ]; then
      SL_CHECK_OBS="not assessed — lspv storage inventory was unparseable (rc=0)"
      SL_CHECK_MEAN="The physical-volume capture did not match the expected AIX lspv structure, so topology, ownership, and redundancy could not be assessed."
      SL_CHECK_FIX="capture the complete output of 'lspv', correct the replay source if needed, provide the approved storage topology baseline, and rerun PTxray."
    else
      SL_CHECK_COUNT=$SL_CHECK_ROWS
      SL_CHECK_NOUN=disks
      SL_CHECK_VERB=were
      if [ "$SL_CHECK_COUNT" -eq 1 ]; then
        SL_CHECK_NOUN=disk
        SL_CHECK_VERB=was
      fi
      SL_CHECK_OBS="not assessed — $SL_CHECK_COUNT $SL_CHECK_NOUN $SL_CHECK_VERB inventoried from lspv, but no site-approved expected storage topology, ownership, and redundancy baseline was available"
      SL_CHECK_MEAN="Observed disks and volume groups alone cannot establish whether placement, ownership, pathing, and redundancy match the intended architecture."
      SL_CHECK_FIX="provide the site-approved expected storage topology, ownership, pathing, and redundancy baseline, compare it with this inventory, and rerun PTxray."
    fi
  fi

  add storage storage_layout "Storage layout baseline" \
    NOT_ASSESSED high "$SL_CHECK_OBS" "$SL_CHECK_MEAN" "$SL_CHECK_FIX"
}
_AIXRAY_SESSION_KEYS=""
# Standalone fact and finding producer for AIX interface, route, and resolver
# inventory. Include-safe: integration calls the fact emitter from the facts
# renderer and the check from the assessment spine.

function network_inventory_json_escape {
  awk '
    {
      s=$0
      gsub(/\\/, "\\\\", s)
      gsub(/"/, "\\\"", s)
      gsub(/\t/, "\\t", s)
      gsub(/\r/, "\\r", s)
      gsub(/[\001-\010\013\014\016-\037]/, "", s)
      if (seen++) printf "\\n"
      printf "%s", s
    }
  '
}

function network_inventory_ifconfig_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function netmask(value, raw) {
      if (ipv4(value)) return 1
      raw=value
      sub(/^0[xX]/, "", raw)
      return substr(raw,8,1)!="" && substr(raw,9,1)=="" &&
        raw ~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    function ipv6_prefix(value, slash, address, prefix) {
      slash=index(value, "/")
      if (slash==0) return ipv6(value)
      address=substr(value, 1, slash-1)
      prefix=substr(value, slash+1)
      if (address=="" || prefix !~ /^[0-9][0-9]*$/ ||
          prefix+0>128 || index(prefix, "/")>0) return 0
      return ipv6(address)
    }
    /^[ \t\r]*$/ { next }
    /^[^ \t]/ {
      if ($0 !~ /^[A-Za-z][A-Za-z0-9_.-]*:[ \t]*flags=[^<]*<[^>]*>/) {
        bad=1
        next
      }
      name=$1
      sub(/:.*/, "", name)
      if (name !~ /^[A-Za-z][A-Za-z0-9_.-]*$/ || seen[name]++) bad=1
      current=name
      headers++
      for (i=1; i<=NF; i++) {
        if ($i=="mtu") {
          mtu++
          if (i==NF || $(i+1) !~ /^[1-9][0-9]*$/) bad=1
        }
      }
      next
    }
    {
      if (current=="") { bad=1; next }
      if ($1=="inet") {
        if (!ipv4($2)) { bad=1; next }
        masks=0
        for (i=3; i<=NF; i++) {
          if ($i=="netmask") {
            masks++
            if (i==NF || !netmask($(i+1))) bad=1
          }
        }
        if (masks!=1) bad=1
      } else if ($1=="inet6") {
        if (!ipv6_prefix($2)) bad=1
      } else if ($1=="tcp_sendspace" || $1=="tcp_recvspace" ||
                 $1=="rfc1323") {
        if (NF<2 || NF%2!=0) { bad=1; next }
        for (i=1; i<=NF; i+=2) {
          if (($i!="tcp_sendspace" && $i!="tcp_recvspace" &&
               $i!="rfc1323") ||
              $(i+1) !~ /^[0-9][0-9]*$/) bad=1
        }
      } else {
        bad=1
      }
    }
    END { if (bad || headers==0) exit 1 }
  '
}

function network_inventory_parse_ifconfig {
  awk '
    /^[ \t\r]*$/ { next }
    /^[^ \t]/ {
      name=$1
      sub(/:.*/, "", name)
      flags=$0
      sub(/^[^<]*</, "", flags)
      sub(/>.*/, "", flags)
      count=split(flags, flag, ",")
      state="down"
      for (i=1; i<=count; i++) if (flag[i]=="UP") state="up"
      mtu=""
      for (i=1; i<=NF; i++) if ($i=="mtu") mtu=$(i+1)
      current=name
      printf "I\t%s\t%s\t%s\n", name, state, mtu
      next
    }
    $1=="inet" {
      mask=""
      for (i=3; i<=NF; i++) if ($i=="netmask") mask=$(i+1)
      printf "A\t%s\t%s\t%s\n", current, $2, mask
    }
  '
}

function network_inventory_lsattr_shape {
  awk '
    /^[ \t\r]*$/ { next }
    $1=="mtu" {
      seen++
      if (NF<2 || $2 !~ /^[1-9][0-9]*$/) bad=1
    }
    END { if (bad || seen!=1) exit 1 }
  '
}

function network_inventory_entstat_shape {
  typeset NI_ES_WANTED
  NI_ES_WANTED=$1
  awk -v wanted="$NI_ES_WANTED" '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    /^ETHERNET STATISTICS \(/ {
      value=$0
      sub(/^[^(]*\(/, "", value)
      sub(/\).*/, "", value)
      headers++
      if (value!=wanted) bad=1
    }
    /^Device Type:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      types++
      if (trim(value)=="") bad=1
    }
    END { if (bad || headers!=1 || types!=1) exit 1 }
  '
}

function network_inventory_entstat_type {
  awk '
    /^Device Type:/ {
      sub(/^[^:]*:[ \t]*/, "")
      sub(/[ \t]+$/, "")
      print
      exit
    }
  '
}

function network_inventory_entstat_speed {
  awk '
    function trim(value) {
      sub(/^[ \t]+/, "", value)
      sub(/[ \t]+$/, "", value)
      return value
    }
    function label(kind) {
      if (kind=="media") return "Media Speed Running"
      return "Adapter Data Rate"
    }
    function parse_speed(value, kind, part, unit, shown, number) {
      value=trim(value)
      split(value, part, /[ \t]+/)
      rows[kind]++
      shown=part[1]
      if (part[2]!="") shown=shown " " part[2]
      if (shown_values[kind]!="") shown_values[kind]=shown_values[kind] ", "
      shown_values[kind]=shown_values[kind] shown

      if (part[1] !~ /^[1-9][0-9]*$/) {
        reason[kind]=label(kind) " reported a non-numeric value"
        return
      }
      if (part[2]=="") {
        reason[kind]=label(kind) " value lacked a unit"
        return
      }
      number=part[1]
      unit=tolower(part[2])
      if (unit=="mbps") {
        converted[kind]=number
      } else if (unit=="gbps") {
        converted[kind]=(number * 1000)
      } else {
        reason[kind]=label(kind) " reported an unrecognized unit"
      }
    }
    /^Media Speed Running:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      parse_speed(value, "media")
    }
    /^Adapter Data Rate:/ {
      value=$0
      sub(/^[^:]*:[ \t]*/, "", value)
      parse_speed(value, "rate")
    }
    END {
      if (rows["media"]>0) kind="media"
      else if (rows["rate"]>0) kind="rate"
      else {
        print "NOT_ASSESSED|did not report media speed or adapter data rate"
        exit
      }

      if (rows[kind]!=1) {
        print "NOT_ASSESSED|" label(kind) " reported multiple rows (values: " shown_values[kind] ")"
      } else if (reason[kind]!="") {
        print "NOT_ASSESSED|" reason[kind]
      } else {
        print "OBSERVED|" converted[kind]
      }
    }
  '
}

function network_inventory_netstat_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    {
      lower=tolower($0)
      if ($1=="Routing" && $2=="tables") headers++
      if (lower ~ /protocol family[ \t]+24([ \t(:]|$)/ ||
          lower ~ /internet v6/) {
        family="ipv6"
        families++
        next
      }
      if (lower ~ /protocol family[ \t]+2([ \t(:]|$)/) {
        family="ipv4"
        families++
        next
      }
      if ($1=="default" || $1=="0.0.0.0" ||
          $1=="::/0" || $1=="::0/0") {
        route_family=family
        if ($1=="0.0.0.0") route_family="ipv4"
        if ($1=="::/0" || $1=="::0/0") route_family="ipv6"
        defaults++
        if (NF<3 || $3 !~ /^[A-Za-z][A-Za-z]*$/ || route_family=="" ||
            (route_family=="ipv4" && !ipv4($2)) ||
            (route_family=="ipv6" && !ipv6($2))) bad=1
      }
    }
    END { if (bad || headers!=1 || families==0) exit 1 }
  '
}

function network_inventory_parse_netstat {
  awk '
    {
      lower=tolower($0)
      if (lower ~ /protocol family[ \t]+24([ \t(:]|$)/ ||
          lower ~ /internet v6/) {
        family="ipv6"
        next
      }
      if (lower ~ /protocol family[ \t]+2([ \t(:]|$)/) {
        family="ipv4"
        next
      }
      if ($1=="default" || $1=="0.0.0.0" ||
          $1=="::/0" || $1=="::0/0") {
        route_family=family
        if ($1=="0.0.0.0") route_family="ipv4"
        if ($1=="::/0" || $1=="::0/0") route_family="ipv6"
        iface=""
        for (i=3; i<=NF; i++)
          if ($i ~ /^[A-Za-z][A-Za-z_.-]*[0-9][0-9]*$/) iface=$i
        if (iface=="")
          printf "%s\t%s\t\tPARTIAL\tnetstat -rn default route did not expose an interface\n", route_family, $2
        else
          printf "%s\t%s\t%s\tOBSERVED\t\n", route_family, $2, iface
      }
    }
  '
}

function network_inventory_resolv_shape {
  awk '
    function ipv4(value, part, count, i) {
      count=split(value, part, ".")
      if (count!=4) return 0
      for (i=1; i<=4; i++)
        if (part[i] !~ /^[0-9][0-9]*$/ || part[i]+0>255) return 0
      return 1
    }
    function ipv6_component(value, allow_ipv4) {
      if (index(value, ".")>0) {
        if (!allow_ipv4 || !ipv4(value)) return 0
        return 2
      }
      if (substr(value,1,1)=="" || substr(value,5,1)!="" ||
          value !~ /^[0-9A-Fa-f][0-9A-Fa-f]*$/) return 0
      return 1
    }
    function ipv6_side(value, allow_ipv4, part, count, i, units, size) {
      count=split(value, part, ":")
      units=0
      for (i=1; i<=count; i++) {
        size=ipv6_component(part[i], allow_ipv4 && i==count)
        if (size==0) return -1
        units+=size
      }
      return units
    }
    function ipv6(value, percent, zone, compression, remainder, left,
                  right, left_units, right_units, total) {
      percent=index(value, "%")
      if (percent>0) {
        zone=substr(value, percent+1)
        if (zone=="" || index(zone, "%")>0 ||
            zone !~ /^[A-Za-z0-9_.-][A-Za-z0-9_.-]*$/) return 0
        value=substr(value, 1, percent-1)
      }
      if (value=="" || index(value, ":")==0) return 0
      compression=index(value, "::")
      if (compression>0) {
        remainder=substr(value, compression+2)
        if (index(remainder, "::")>0) return 0
        left=substr(value, 1, compression-1)
        right=remainder
        left_units=0
        right_units=0
        if (left!="") left_units=ipv6_side(left, 0)
        if (right!="") right_units=ipv6_side(right, 1)
        if (left_units<0 || right_units<0) return 0
        total=left_units+right_units
        return total<8
      }
      if (value ~ /^:/ || value ~ /:$/) return 0
      total=ipv6_side(value, 1)
      return total==8
    }
    /^[ \t\r]*$/ { next }
    /^[ \t]*[#;]/ { next }
    {
      if ($1=="nameserver") {
        if (NF<2 || (!ipv4($2) && !ipv6($2))) { bad=1; next }
        for (i=3; i<=NF; i++) {
          if (substr($i,1,1)=="#" || substr($i,1,1)==";") break
          bad=1
        }
      } else if ($1=="domain" || $1=="search" || $1=="sortlist" ||
                 $1=="options" || $1=="lookup") {
        if (NF<2) bad=1
      } else {
        bad=1
      }
    }
    END { if (bad) exit 1 }
  '
}

function network_inventory_parse_resolv {
  awk '
    /^[ \t]*nameserver[ \t]+/ { print $2 }
  '
}

function network_inventory_append_gap {
  typeset NI_AG_CURRENT NI_AG_REASON NI_AG_ESCAPED
  NI_AG_CURRENT=$1
  NI_AG_REASON=$2
  NI_AG_ESCAPED=$(printf '%s' "$NI_AG_REASON" |
    network_inventory_json_escape)
  if [ -n "$NI_AG_CURRENT" ]; then
    printf '%s, "%s"' "$NI_AG_CURRENT" "$NI_AG_ESCAPED"
  else
    printf '"%s"' "$NI_AG_ESCAPED"
  fi
}

function emit_fact_network_inventory {
  typeset NI_IFCONFIG NI_IFCONFIG_RC NI_IF_WHY NI_IF_SOURCE NI_PARSED
  typeset NI_NAMES NI_IF_ITEMS NI_IF_PARTIAL NI_IF NI_STATE NI_HEADER_MTU
  typeset NI_IPV4 NI_MTU NI_MTU_STATUS NI_MTU_REASON NI_MTU_REASON_JSON
  typeset NI_LSATTR NI_LSATTR_RC NI_ADAPTER NI_ADAPTER_TYPE
  typeset NI_ADAPTER_STATUS NI_ADAPTER_REASON NI_ADAPTER_REASON_JSON
  typeset NI_SPEED NI_SPEED_RESULT NI_SPEED_STATUS NI_SPEED_REASON
  typeset NI_SPEED_REASON_JSON
  typeset NI_ENTSTAT NI_ENTSTAT_RC NI_SUFFIX NI_ADAPTER_CANDIDATE
  typeset NI_ITEM_STATUS NI_ITEM_REASON
  typeset NI_ITEM_REASON_ESC NI_ITEM_REASON_JSON NI_ADAPTER_JSON NI_TYPE_ESC
  typeset NI_TYPE_JSON NI_SPEED_JSON NI_MTU_JSON NI_ITEM
  typeset NI_INTERFACES_STATUS NI_INTERFACES_REASON NI_INTERFACES_REASON_JSON
  typeset NI_NETSTAT NI_NETSTAT_RC NI_ROUTE_WHY NI_ROUTE_SOURCE NI_ROUTE_ROWS
  typeset NI_ROUTE_ITEMS NI_ROUTE_STATUS NI_ROUTE_REASON NI_ROUTE_REASON_JSON
  typeset NI_DNS_RAW NI_DNS_RC NI_DNS_WHY NI_DNS_SOURCE NI_DNS_ITEMS
  typeset NI_DNS_STATUS NI_DNS_REASON_JSON NI_GAPS NI_OBSERVED NI_COMPLETE
  typeset NI_TOP_STATUS NI_TOP_REASON NI_TOP_REASON_JSON

  NI_GAPS=""
  NI_IF_ITEMS=""
  NI_IF_PARTIAL=0

  NI_IFCONFIG=$(aix network_ifconfig_a ifconfig -a)
  NI_IFCONFIG_RC=$?
  NI_IF_SOURCE="{ \"capture\": \"network_ifconfig_a\", \"command\": \"ifconfig -a\", \"rc\": $NI_IFCONFIG_RC }"
  NI_IF_WHY=""
  if [ "$NI_IFCONFIG_RC" -ne 0 ]; then
    NI_IF_WHY="ifconfig -a capture failed (rc=$NI_IFCONFIG_RC)"
  elif [ -z "$NI_IFCONFIG" ]; then
    NI_IF_WHY="ifconfig -a capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_IFCONFIG" | network_inventory_ifconfig_shape; then
    NI_IF_WHY="ifconfig -a capture unparseable (rc=0)"
  fi

  if [ -n "$NI_IF_WHY" ]; then
    NI_INTERFACES_STATUS="NOT_ASSESSED"
    NI_INTERFACES_REASON=$NI_IF_WHY
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_IF_WHY")
  else
    NI_PARSED=$(printf '%s\n' "$NI_IFCONFIG" |
      network_inventory_parse_ifconfig)
    NI_NAMES=$(printf '%s\n' "$NI_PARSED" |
      awk -F '\t' '$1=="I" { print $2 }')

    while IFS= read -r NI_IF
    do
      [ -n "$NI_IF" ] || continue
      NI_STATE=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" \
          '$1=="I" && $2==wanted { print $3; exit }')
      NI_HEADER_MTU=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" \
          '$1=="I" && $2==wanted { print $4; exit }')
      NI_IPV4=$(printf '%s\n' "$NI_PARSED" |
        awk -F '\t' -v wanted="$NI_IF" '
          $1=="A" && $2==wanted {
            if (seen++) printf ", "
            printf "{ \"address\": \"%s\", \"netmask\": \"%s\" }", $3, $4
          }')

      NI_MTU=""
      NI_MTU_STATUS="OBSERVED"
      NI_MTU_REASON=""
      if [ -n "$NI_HEADER_MTU" ]; then
        NI_MTU=$NI_HEADER_MTU
      else
        NI_LSATTR=$(aix "network_lsattr_$NI_IF" lsattr -El "$NI_IF")
        NI_LSATTR_RC=$?
        if [ "$NI_LSATTR_RC" -ne 0 ]; then
          NI_MTU_REASON="lsattr -El $NI_IF capture failed (rc=$NI_LSATTR_RC)"
        elif [ -z "$NI_LSATTR" ]; then
          NI_MTU_REASON="lsattr -El $NI_IF capture empty (rc=0)"
        elif ! printf '%s\n' "$NI_LSATTR" |
            network_inventory_lsattr_shape; then
          NI_MTU_REASON="lsattr -El $NI_IF capture unparseable (rc=0)"
        else
          NI_MTU=$(printf '%s\n' "$NI_LSATTR" |
            awk '$1=="mtu" { print $2; exit }')
        fi
        if [ -n "$NI_MTU_REASON" ]; then
          NI_MTU_STATUS="NOT_ASSESSED"
          NI_IF_PARTIAL=1
          NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_MTU_REASON")
        fi
      fi

      NI_ADAPTER=""
      NI_ADAPTER_TYPE=""
      NI_ADAPTER_STATUS="NOT_APPLICABLE"
      NI_ADAPTER_REASON="$NI_IF is not an Ethernet interface"
      NI_SPEED=""
      NI_SPEED_STATUS="NOT_APPLICABLE"
      NI_SPEED_REASON="$NI_IF is not an Ethernet interface"
      NI_SUFFIX=""
      NI_ADAPTER_CANDIDATE=""
      case "$NI_IF" in
        ent*) NI_SUFFIX=${NI_IF#ent} ;;
        en*) NI_SUFFIX=${NI_IF#en} ;;
        et*) NI_SUFFIX=${NI_IF#et} ;;
      esac
      case "$NI_SUFFIX" in
        ''|*[!0-9]*) ;;
        *)
          NI_ADAPTER_CANDIDATE="ent$NI_SUFFIX"
          NI_ENTSTAT=$(aix "network_entstat_$NI_ADAPTER_CANDIDATE" \
            entstat -d "$NI_ADAPTER_CANDIDATE")
          NI_ENTSTAT_RC=$?
          NI_ADAPTER_STATUS="NOT_ASSESSED"
          if [ "$NI_ENTSTAT_RC" -ne 0 ]; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture failed (rc=$NI_ENTSTAT_RC)"
          elif [ -z "$NI_ENTSTAT" ]; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture empty (rc=0)"
          elif ! printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_shape "$NI_ADAPTER_CANDIDATE"; then
            NI_ADAPTER_REASON="entstat -d $NI_ADAPTER_CANDIDATE capture unparseable (rc=0)"
          else
            NI_ADAPTER=$NI_ADAPTER_CANDIDATE
            NI_ADAPTER_TYPE=$(printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_type)
            NI_ADAPTER_STATUS="OBSERVED"
            NI_ADAPTER_REASON=""
            NI_SPEED_RESULT=$(printf '%s\n' "$NI_ENTSTAT" |
              network_inventory_entstat_speed)
          fi

          if [ "$NI_ADAPTER_STATUS" = "OBSERVED" ]; then
            NI_SPEED_STATUS=${NI_SPEED_RESULT%%\|*}
            NI_SPEED=${NI_SPEED_RESULT#*\|}
            if [ "$NI_SPEED_STATUS" = "OBSERVED" ]; then
              NI_SPEED_STATUS="OBSERVED"
              NI_SPEED_REASON=""
            else
              NI_SPEED_REASON=$NI_SPEED
              NI_SPEED=""
              NI_SPEED_STATUS="NOT_ASSESSED"
              if [ "$NI_SPEED_REASON" = \
                  "did not report media speed or adapter data rate" ]; then
                NI_SPEED_REASON="entstat -d $NI_ADAPTER_CANDIDATE $NI_SPEED_REASON"
              fi
            fi
          else
            NI_SPEED_STATUS="NOT_ASSESSED"
            NI_SPEED_REASON=$NI_ADAPTER_REASON
            NI_IF_PARTIAL=1
            NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_ADAPTER_REASON")
          fi
          ;;
      esac

      NI_ITEM_STATUS="OBSERVED"
      NI_ITEM_REASON=""
      if [ "$NI_MTU_STATUS" = "NOT_ASSESSED" ]; then
        NI_ITEM_STATUS="PARTIAL"
        NI_ITEM_REASON="MTU: $NI_MTU_REASON"
      fi
      if [ "$NI_ADAPTER_STATUS" = "NOT_ASSESSED" ]; then
        NI_ITEM_STATUS="PARTIAL"
        if [ -n "$NI_ITEM_REASON" ]; then
          NI_ITEM_REASON="$NI_ITEM_REASON; adapter: $NI_ADAPTER_REASON"
        else
          NI_ITEM_REASON="adapter: $NI_ADAPTER_REASON"
        fi
      fi

      if [ -n "$NI_MTU" ]; then NI_MTU_JSON=$NI_MTU; else NI_MTU_JSON=null; fi
      if [ -n "$NI_ADAPTER" ]; then
        NI_ADAPTER_JSON="\"$NI_ADAPTER\""
      else
        NI_ADAPTER_JSON=null
      fi
      if [ -n "$NI_ADAPTER_TYPE" ]; then
        NI_TYPE_ESC=$(printf '%s' "$NI_ADAPTER_TYPE" |
          network_inventory_json_escape)
        NI_TYPE_JSON="\"$NI_TYPE_ESC\""
      else
        NI_TYPE_JSON=null
      fi
      if [ -n "$NI_SPEED" ]; then NI_SPEED_JSON=$NI_SPEED; else NI_SPEED_JSON=null; fi

      if [ -n "$NI_MTU_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_MTU_REASON" |
          network_inventory_json_escape)
        NI_MTU_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_MTU_REASON_JSON=null
      fi
      if [ -n "$NI_ADAPTER_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ADAPTER_REASON" |
          network_inventory_json_escape)
        NI_ADAPTER_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_ADAPTER_REASON_JSON=null
      fi
      if [ -n "$NI_SPEED_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_SPEED_REASON" |
          network_inventory_json_escape)
        NI_SPEED_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_SPEED_REASON_JSON=null
      fi
      if [ -n "$NI_ITEM_REASON" ]; then
        NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ITEM_REASON" |
          network_inventory_json_escape)
        NI_ITEM_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
      else
        NI_ITEM_REASON_JSON=null
      fi

      NI_ITEM="{ \"name\": \"$NI_IF\", \"ipv4\": [$NI_IPV4], \"ipv4_status\": \"OBSERVED\", \"ipv4_reason\": null, \"state\": \"$NI_STATE\", \"state_status\": \"OBSERVED\", \"state_reason\": null, \"mtu\": $NI_MTU_JSON, \"mtu_status\": \"$NI_MTU_STATUS\", \"mtu_reason\": $NI_MTU_REASON_JSON, \"adapter\": $NI_ADAPTER_JSON, \"adapter_type\": $NI_TYPE_JSON, \"adapter_status\": \"$NI_ADAPTER_STATUS\", \"adapter_reason\": $NI_ADAPTER_REASON_JSON, \"media_speed_mbps\": $NI_SPEED_JSON, \"media_speed_status\": \"$NI_SPEED_STATUS\", \"media_speed_reason\": $NI_SPEED_REASON_JSON, \"status\": \"$NI_ITEM_STATUS\", \"reason\": $NI_ITEM_REASON_JSON }"
      if [ -n "$NI_IF_ITEMS" ]; then
        NI_IF_ITEMS="$NI_IF_ITEMS, $NI_ITEM"
      else
        NI_IF_ITEMS=$NI_ITEM
      fi
    done <<EOF
$NI_NAMES
EOF

    if [ "$NI_IF_PARTIAL" -eq 1 ]; then
      NI_INTERFACES_STATUS="PARTIAL"
      NI_INTERFACES_REASON="one or more interface attributes were not assessed; see per-interface reasons"
    else
      NI_INTERFACES_STATUS="COMPLETE"
      NI_INTERFACES_REASON=""
    fi
  fi

  if [ -n "$NI_INTERFACES_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_INTERFACES_REASON" |
      network_inventory_json_escape)
    NI_INTERFACES_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_INTERFACES_REASON_JSON=null
  fi

  NI_NETSTAT=$(aix network_netstat_rn netstat -rn)
  NI_NETSTAT_RC=$?
  NI_ROUTE_SOURCE="{ \"capture\": \"network_netstat_rn\", \"command\": \"netstat -rn\", \"rc\": $NI_NETSTAT_RC }"
  NI_ROUTE_WHY=""
  NI_ROUTE_ITEMS=""
  if [ "$NI_NETSTAT_RC" -ne 0 ]; then
    NI_ROUTE_WHY="netstat -rn capture failed (rc=$NI_NETSTAT_RC)"
  elif [ -z "$NI_NETSTAT" ]; then
    NI_ROUTE_WHY="netstat -rn capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_NETSTAT" | network_inventory_netstat_shape; then
    NI_ROUTE_WHY="netstat -rn capture unparseable (rc=0)"
  fi

  if [ -n "$NI_ROUTE_WHY" ]; then
    NI_ROUTE_STATUS="NOT_ASSESSED"
    NI_ROUTE_REASON=$NI_ROUTE_WHY
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_ROUTE_WHY")
  else
    NI_ROUTE_ROWS=$(printf '%s\n' "$NI_NETSTAT" |
      network_inventory_parse_netstat)
    NI_ROUTE_ITEMS=$(printf '%s\n' "$NI_ROUTE_ROWS" | awk -F '\t' '
      NF {
        if (seen++) printf ", "
        if ($3=="") iface="null"; else iface="\"" $3 "\""
        if ($5=="") reason="null"; else reason="\"" $5 "\""
        printf "{ \"family\": \"%s\", \"gateway\": \"%s\", \"interface\": %s, \"status\": \"%s\", \"reason\": %s }", $1, $2, iface, $4, reason
      }')
    if printf '%s\n' "$NI_ROUTE_ROWS" |
        awk -F '\t' '$4=="PARTIAL" { found=1 } END { exit !found }'; then
      NI_ROUTE_STATUS="PARTIAL"
      NI_ROUTE_REASON="one or more default routes did not expose an interface"
      NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" \
        "netstat -rn default route did not expose an interface")
    else
      NI_ROUTE_STATUS="COMPLETE"
      NI_ROUTE_REASON=""
    fi
  fi
  if [ -n "$NI_ROUTE_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_ROUTE_REASON" |
      network_inventory_json_escape)
    NI_ROUTE_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_ROUTE_REASON_JSON=null
  fi

  NI_DNS_RAW=$(aix network_resolv_conf cat /etc/resolv.conf)
  NI_DNS_RC=$?
  NI_DNS_SOURCE="{ \"capture\": \"network_resolv_conf\", \"command\": \"cat /etc/resolv.conf\", \"rc\": $NI_DNS_RC }"
  NI_DNS_WHY=""
  NI_DNS_ITEMS=""
  if [ "$NI_DNS_RC" -ne 0 ]; then
    NI_DNS_WHY="cat /etc/resolv.conf capture failed (rc=$NI_DNS_RC)"
  elif [ -z "$NI_DNS_RAW" ]; then
    NI_DNS_WHY="cat /etc/resolv.conf capture empty (rc=0)"
  elif ! printf '%s\n' "$NI_DNS_RAW" | network_inventory_resolv_shape; then
    NI_DNS_WHY="cat /etc/resolv.conf capture unparseable (rc=0)"
  fi

  if [ -n "$NI_DNS_WHY" ]; then
    NI_DNS_STATUS="NOT_ASSESSED"
    NI_GAPS=$(network_inventory_append_gap "$NI_GAPS" "$NI_DNS_WHY")
  else
    NI_DNS_STATUS="COMPLETE"
    NI_DNS_ITEMS=$(printf '%s\n' "$NI_DNS_RAW" |
      network_inventory_parse_resolv |
      awk '{ if (seen++) printf ", "; printf "\"%s\"", $0 }')
  fi
  if [ -n "$NI_DNS_WHY" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_DNS_WHY" |
      network_inventory_json_escape)
    NI_DNS_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_DNS_REASON_JSON=null
  fi

  NI_OBSERVED=0
  NI_COMPLETE=0
  for NI_ITEM_STATUS in \
    "$NI_INTERFACES_STATUS" "$NI_ROUTE_STATUS" "$NI_DNS_STATUS"
  do
    [ "$NI_ITEM_STATUS" != "NOT_ASSESSED" ] && NI_OBSERVED=$((NI_OBSERVED + 1))
    [ "$NI_ITEM_STATUS" = "COMPLETE" ] && NI_COMPLETE=$((NI_COMPLETE + 1))
  done
  if [ "$NI_OBSERVED" -eq 0 ]; then
    NI_TOP_STATUS="NOT_ASSESSED"
    NI_TOP_REASON="no network fact source produced trustworthy output; see capture_gaps"
  elif [ "$NI_COMPLETE" -eq 3 ]; then
    NI_TOP_STATUS="COMPLETE"
    NI_TOP_REASON=""
  else
    NI_TOP_STATUS="PARTIAL"
    NI_TOP_REASON="one or more network fact sources or fields were not assessed; see sub-block reasons and capture_gaps"
  fi
  if [ -n "$NI_TOP_REASON" ]; then
    NI_ITEM_REASON_ESC=$(printf '%s' "$NI_TOP_REASON" |
      network_inventory_json_escape)
    NI_TOP_REASON_JSON="\"$NI_ITEM_REASON_ESC\""
  else
    NI_TOP_REASON_JSON=null
  fi

  printf '"network": { "status": "%s", "platform": "AIX", ' "$NI_TOP_STATUS"
  printf '"reason": %s, "capture_gaps": [%s], ' "$NI_TOP_REASON_JSON" "$NI_GAPS"
  if [ "$NI_INTERFACES_STATUS" = "NOT_ASSESSED" ]; then
    printf '"interfaces": { "status": "%s", "reason": %s, "source": %s, "interfaces": null }, ' \
      "$NI_INTERFACES_STATUS" "$NI_INTERFACES_REASON_JSON" "$NI_IF_SOURCE"
  else
    printf '"interfaces": { "status": "%s", "reason": %s, "source": %s, "interfaces": [%s] }, ' \
      "$NI_INTERFACES_STATUS" "$NI_INTERFACES_REASON_JSON" "$NI_IF_SOURCE" "$NI_IF_ITEMS"
  fi
  if [ "$NI_ROUTE_STATUS" = "NOT_ASSESSED" ]; then
    printf '"routing": { "status": "%s", "reason": %s, "source": %s, "default_gateways": null }, ' \
      "$NI_ROUTE_STATUS" "$NI_ROUTE_REASON_JSON" "$NI_ROUTE_SOURCE"
  else
    printf '"routing": { "status": "%s", "reason": %s, "source": %s, "default_gateways": [%s] }, ' \
      "$NI_ROUTE_STATUS" "$NI_ROUTE_REASON_JSON" "$NI_ROUTE_SOURCE" "$NI_ROUTE_ITEMS"
  fi
  if [ "$NI_DNS_STATUS" = "NOT_ASSESSED" ]; then
    printf '"dns": { "status": "%s", "reason": %s, "source": %s, "resolvers": null } }' \
      "$NI_DNS_STATUS" "$NI_DNS_REASON_JSON" "$NI_DNS_SOURCE"
  else
    printf '"dns": { "status": "%s", "reason": %s, "source": %s, "resolvers": [%s] } }' \
      "$NI_DNS_STATUS" "$NI_DNS_REASON_JSON" "$NI_DNS_SOURCE" "$NI_DNS_ITEMS"
  fi
}

# Network discovery is useful evidence, but without an approved expected-state
# baseline it is not itself a configuration assessment.
function check_network_inventory {
  typeset NI_CHECK_OUT NI_CHECK_RC NI_CHECK_COUNT NI_CHECK_NOUN NI_CHECK_VERB
  typeset NI_CHECK_OBS NI_CHECK_MEAN NI_CHECK_FIX

  NI_CHECK_OUT=$(aix network_ifconfig_a ifconfig -a); NI_CHECK_RC=$?
  if [ "$NI_CHECK_RC" -ne 0 ]; then
    NI_CHECK_OBS="not assessed — ifconfig -a interface inventory failed (rc=$NI_CHECK_RC)"
    NI_CHECK_MEAN="The interface inventory source was unavailable, so expected interfaces, addresses, routes, and resolvers could not be assessed."
    NI_CHECK_FIX="restore access to 'ifconfig -a', provide the site-approved network baseline, and rerun PTxray."
  elif [ -z "$NI_CHECK_OUT" ]; then
    NI_CHECK_OBS="not assessed — ifconfig -a reported no interface inventory (rc=0)"
    NI_CHECK_MEAN="An empty interface capture cannot establish the system's network configuration or compare it with expected state."
    NI_CHECK_FIX="verify the complete output of 'ifconfig -a', provide the site-approved network baseline, and rerun PTxray."
  elif ! printf '%s\n' "$NI_CHECK_OUT" |
      network_inventory_ifconfig_shape; then
    NI_CHECK_OBS="not assessed — ifconfig -a interface inventory was unparseable (rc=0)"
    NI_CHECK_MEAN="The interface capture did not match the expected AIX ifconfig structure, so network configuration could not be assessed."
    NI_CHECK_FIX="capture the complete output of 'ifconfig -a', correct the replay source if needed, provide the site-approved network baseline, and rerun PTxray."
  else
    NI_CHECK_COUNT=$(printf '%s\n' "$NI_CHECK_OUT" |
      network_inventory_parse_ifconfig |
      awk -F '	' '$1=="I" {n++} END{print n+0}')
    NI_CHECK_NOUN=interfaces
    NI_CHECK_VERB=were
    if [ "$NI_CHECK_COUNT" -eq 1 ]; then
      NI_CHECK_NOUN=interface
      NI_CHECK_VERB=was
    fi
    NI_CHECK_OBS="not assessed — $NI_CHECK_COUNT $NI_CHECK_NOUN $NI_CHECK_VERB inventoried from ifconfig -a, but no site-approved expected interface, address, route, and DNS baseline was available"
    NI_CHECK_MEAN="Observed network inventory alone cannot distinguish an intended configuration from a missing, unexpected, or misaddressed interface, route, or resolver."
    NI_CHECK_FIX="provide a site-approved expected interface, address, route, and DNS baseline, compare it with this inventory, and rerun PTxray."
  fi

  add config network_inventory "Network inventory baseline" \
    NOT_ASSESSED med "$NI_CHECK_OBS" "$NI_CHECK_MEAN" "$NI_CHECK_FIX"
}

