function attr_hesc { # HTML attribute escaping for authored finding identifiers
  sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' \
      -e 's/"/\&quot;/g' -e "s/'/\&#39;/g"
}

function finding_label_privacy_attrs { # <finding-id>
  typeset FINDING_LABEL_ID_H
  FINDING_LABEL_ID_H=$(printf '%s' "$1" | attr_hesc)
  case "$1" in
    savevg_*)
      printf 'data-aixray-field="observed" data-aixray-location="finding:%s:label"' \
        "$FINDING_LABEL_ID_H"
      ;;
    *)
      printf 'data-aixray-field="authored" data-aixray-copy-id="finding-label:%s:v1"' \
        "$FINDING_LABEL_ID_H"
      ;;
  esac
}

function finding_guidance_privacy_html { # <finding-id> <meaning>
  typeset FINDING_GUIDANCE_ID_H FINDING_GUIDANCE_MEAN_H
  FINDING_GUIDANCE_ID_H=$(printf '%s' "$1" | attr_hesc)
  FINDING_GUIDANCE_MEAN_H=$(printf '%s' "$2" | hesc)
  printf '%s' '<div data-aixray-field="authored" data-aixray-copy-id="finding:meaning-review-v1">Meaning: Interpret this finding in the context of the local raw assessment.</div>'
  printf '<div data-aixray-field="observed" data-aixray-location="finding:%s:guidance">%s</div>' \
    "$FINDING_GUIDANCE_ID_H" "$FINDING_GUIDANCE_MEAN_H"
}

# render_compliance <standard> — emits ONE compliance report for a standard on stdout.
# Call sites redirect stdout (to a write-guarded tmp file for multi-standard output, or
# straight to the terminal for the single-standard path). Re-enterable: every accumulator
# global is reset on entry so a second call renders a fresh report from the same captured
# findings.
function render_compliance {
  # COMPLIANCE stays a global, not a typeset local: the nested helpers below
  # (ctl_match, rule_lookup) read $COMPLIANCE at call time, and ksh93 does NOT make a
  # caller's typeset-local visible to a called function — a local would render empty
  # control tags.
  COMPLIANCE="$1"
  # accumulator reset — a second render must start from an empty slate
  STDLABEL=""; STDFULL=""; ATTRIB=""; ATTRIB_COPY_ID=""
  ALLRULES=""; NMAP=0; CTAGS=""
  AR_NP=""; AR_P=""; AUDITROWS=""; CTAG_STATUS=""
  CQ=""; CQ_COUNT=0; WL=""
  # the standard vocabulary here must stay consistent with COMPLIANCE_STANDARDS and the
  # --compliance case in the argument loop.
  case "$COMPLIANCE" in
    stig)   STDLABEL="DISA STIG (IBM AIX 7.x)"; STDFULL="DISA STIG for IBM AIX 7.x"; ATTRIB_COPY_ID="compliance:attribution-stig-v1"
            ATTRIB="Control mappings reference the DISA STIG for IBM AIX 7.x (public domain). This report indicates PTxray's read-only observations and is not a certified audit.";;
    cis-l1) STDLABEL="PowerTrue CIS L1 cross-check"; STDFULL="PowerTrue-authored CIS L1 numeric cross-check"; ATTRIB_COPY_ID="compliance:attribution-cis-l1-v1"
            ATTRIB="PowerTrue's cross-check uses control-number references and PowerTrue verdicts only; it is not a certified assessment.";;
    cis-l2) STDLABEL="PowerTrue CIS L2 cross-check"; STDFULL="PowerTrue-authored CIS L2 numeric cross-check"; ATTRIB_COPY_ID="compliance:attribution-cis-l2-v1"
            ATTRIB="PowerTrue's cross-check uses control-number references and PowerTrue verdicts only; it is not a certified assessment.";;
    ffiec)  STDLABEL="FFIEC IT Handbook"; STDFULL="FFIEC IT Handbook alignment"; ATTRIB_COPY_ID="compliance:attribution-ffiec-v1"
            ATTRIB="FFIEC alignment tags reference the public FFIEC IT Examination Handbook (public domain); they indicate coverage territory, not a certified examination. This report indicates PTxray's read-only observations and is not a certified audit.";;
  esac

  COMPLIANCE_VINTAGE_H=$(currency_standard_reference_h "$COMPLIANCE")
  STANDARD_CURRENCY_DISCLOSURE=""
  STANDARD_SI=$(currency_standard_index "$COMPLIANCE")
  if [ -n "$STANDARD_SI" ]; then
    typeset _slabel _sver _sasof _sstat _sthresh _sreason _cls _body
    _slabel=${CU_LABEL[$STANDARD_SI]}
    _sver=${CU_VERSION[$STANDARD_SI]}
    _sasof=${CU_ASOF[$STANDARD_SI]}
    _sstat=${CU_STATUS[$STANDARD_SI]}
    _sthresh=${CU_THRESHOLD[$STANDARD_SI]}
    _sreason=${CU_REASON[$STANDARD_SI]}
    if [ "$_sstat" = "CURRENT" ]; then
      _cls="cov"
      if [ "$_sver" = "unknown" ] || [ -z "$_sver" ]; then
        _body="<b>Control-set currency.</b> Verdicts in this report are graded against $(printf '%s' "$_slabel" | hesc), as of $(printf '%s' "$_sasof" | hesc), which is within its configured $(printf '%s' "$_sthresh" | hesc)-day freshness limit. Currency of other reference sources does not affect these verdicts."
      else
        _body="<b>Control-set currency.</b> Verdicts in this report are graded against $(printf '%s' "$_slabel" | hesc) $(printf '%s' "$_sver" | hesc), as of $(printf '%s' "$_sasof" | hesc), which is within its configured $(printf '%s' "$_sthresh" | hesc)-day freshness limit. Currency of other reference sources does not affect these verdicts."
      fi
    else
      _cls="currency-alert"
      _body="<b>Control-set currency.</b> The control set for this report ($(printf '%s' "$_slabel" | hesc)) is not current: $(printf '%s' "${_sreason:-source currency could not be established}" | hesc). Clean verdicts here are not current-confidence passes."
    fi
    STANDARD_CURRENCY_DISCLOSURE="<div class=\"${_cls}\" data-aixray-field=\"observed\" data-aixray-location=\"report:standard-currency\">${_body}</div>"
  fi

  function ctl_match { # <index> -> space-separated control tags of $COMPLIANCE carried by finding
    typeset tok out; out=""
    for tok in ${F_CTL[$1]}; do
      case "$COMPLIANCE" in
        stig)   case "$tok" in stig:*)  out="$out $tok";; esac;;
        cis-l1) ;;
        cis-l2) ;;  # L2 resolves through the crosswalk, not per-finding tags — see the if/elif below
        ffiec)  case "$tok" in ffiec:*) out="$out $tok";; esac;;
      esac
    done
    if [ "$COMPLIANCE" = "cis-l1" ]; then
      cis_l1_verdicts "$1" | awk -F'|' 'NF>=2{printf "%s%s",(n++?" ":""),$1}'
    elif [ "$COMPLIANCE" = "cis-l2" ]; then
      cis_l2_verdicts "$1" | awk -F'|' 'NF>=2{printf "%s%s",(n++?" ":""),$1}'
    else
      echo $out
    fi
  }
  function chip_of { case "$1" in FAIL) echo RED;; WARN) echo AMBER;; NOT_ASSESSED|NOT_APPLICABLE) echo MUTE;; *) echo GREEN;; esac; }
  # rule-engine detail: concatenate every finding's F_RULES so a control tag that is a
  # rule id can be rendered as its OWN per-rule row (status + observed) instead of the
  # grouped worst-status finding row.
  ALLRULES=""
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    if [ -n "${F_RULES[$i]}" ]; then ALLRULES="$ALLRULES
${F_RULES[$i]}"; fi
    i=$((i+1))
  done
  function rule_lookup { # <tag> -> "status|observed" if the tag is a rule id, else empty
    printf '%s\n' "$ALLRULES" | awk -F'|' -v t="$1" '$1==t{print $2"|"$3; exit}'
  }
  function rulechip { case "$1" in FAIL) echo RED;; PASS) echo GREEN;; NA) echo MUTE;; *) echo AMBER;; esac; }
  function riskcls { case "$1" in Critical) echo crit;; High) echo high;; Medium) echo med;; *) echo low;; esac; }
  function catlbl_of { # <catid> -> display label
    typeset k; k=0
    while [ "$k" -lt 9 ]; do
      [ "${CAT_ID[$k]}" = "$1" ] && { echo "${CAT_LBL[$k]}"; return; }
      k=$((k+1))
    done
  }

  # coverage count + distinct control tags of the chosen standard
  NMAP=0; CTAGS=""
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    M=$(ctl_match $i)
    if [ -n "$M" ]; then
      NMAP=$((NMAP+1))
      for tok in $M; do
        case " $CTAGS " in *" $tok "*) ;; *) CTAGS="$CTAGS $tok";; esac
      done
    fi
    i=$((i+1))
  done

  # (c) auditor summary — one row per distinct control tag; non-PASS first
  AR_NP=""; AR_P=""; CTAG_STATUS=""
  for t in $CTAGS; do
    t_h=$(printf '%s' "$t" | attr_hesc)
    # rule-engine control tag: render ONE row per rule with its own status + observed,
    # sourced from the finding's per-rule detail rather than the grouped worst status.
    rl=""
    case "$COMPLIANCE" in cis-l1|cis-l2) ;; *) rl=$(rule_lookup "$t");; esac
    if [ -n "$rl" ]; then
      rst=${rl%%"|"*}; robs=${rl#*"|"}; rlbl=""
      i=0
      while [ "$i" -lt "$NFIND" ]; do
        case " ${F_CTL[$i]} " in *" $t "*) rlbl=$(printf '%s' "${F_LBL[$i]}"|hesc); break;; esac
        i=$((i+1))
      done
      row="<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:id\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:labels\">$rlbl</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:status\"><span class=\"chip $(rulechip "$rst")\">$rst</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:observed\">$(printf '%s' "$robs"|hesc)</td></tr>"
      if [ "$rst" = "FAIL" ]; then AR_NP="$AR_NP$row"; else AR_P="$AR_P$row"; fi
      CTAG_STATUS="$CTAG_STATUS$t|$rst
"
      continue
    fi
    worst=PASS; labels=""; obs=""; nmapped=0; nneedroot=0; nnotassessed=0; nnotapplicable=0
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      for tok in $(ctl_match $i); do
        if [ "$tok" = "$t" ]; then
          if [ "$COMPLIANCE" = "cis-l1" ]; then
            mapped_status=$(cis_l1_verdicts "$i" | awk -F'|' -v c="$t" '$1==c{print $2; exit}')
            [ -n "$mapped_status" ] || continue
          elif [ "$COMPLIANCE" = "cis-l2" ]; then
            mapped_status=$(cis_l2_verdicts "$i" | awk -F'|' -v c="$t" '$1==c{print $2; exit}')
            [ -n "$mapped_status" ] || continue
          else
            mapped_status=${F_ST[$i]}
          fi
          labels="$labels${labels:+<br>}$(printf '%s' "${F_LBL[$i]}"|hesc)"
          if [ "$COMPLIANCE" = "cis-l1" ]; then
            mapped_obs=$(cis_l1_evidence "$i" "$t" | hesc | awk '
              {printf "%s%s", (n++?"<br>":""), $0}
            ')
          elif [ "$COMPLIANCE" = "cis-l2" ]; then
            mapped_obs=$(cis_l2_evidence "$i" "$t" | hesc | awk '
              {printf "%s%s", (n++?"<br>":""), $0}
            ')
          else
            mapped_obs=$(printf '%s' "${F_OBS[$i]}" | hesc)
          fi
          obs="$obs${obs:+<br>}$mapped_obs"
          nmapped=$((nmapped+1))
          # need-root WARN: observed "n/a" and meaning explicitly says it needs root
          if [ "$mapped_status" = "WARN" ] && [ "${F_OBS[$i]}" = "n/a" ]; then
            case "${F_MEAN[$i]}" in *"needs root"*) nneedroot=$((nneedroot+1));; esac
          fi
          # a literal NOT_ASSESSED finding must count the same way (§62 finding #9's
          # class): it must never silently leave `worst` at its PASS default just
          # because NOT_ASSESSED matches neither the FAIL nor WARN case below.
          [ "$mapped_status" = "NOT_ASSESSED" ] && nnotassessed=$((nnotassessed+1))
          [ "$mapped_status" = "NOT_APPLICABLE" ] && nnotapplicable=$((nnotapplicable+1))
          case "$mapped_status" in
            FAIL) worst=FAIL;;
            WARN) [ "$worst" != "FAIL" ] && worst=WARN;;
            NOT_ASSESSED)
              # Believability review follow-up (2026-07-14, adversarial confirming review,
              # HIGH): a control mapped to a MIX of PASS and NOT_ASSESSED findings
              # (not ALL not-assessed, which the dedicated row below already catches)
              # previously left `worst` at its PASS default -- NOT_ASSESSED matched
              # neither the FAIL nor WARN case, so a control with, say, one PASS and
              # one NOT_ASSESSED finding rendered a plain PASS row, the exact
              # re-hidden-NOT_ASSESSED class this whole review exists to close, just
              # in this THIRD rendering path (compliance auditor rows) instead of
              # cat_status/BANNER. Never downgrades a real FAIL/WARN already recorded.
              case "$worst" in FAIL|WARN) ;; *) worst=NOT_ASSESSED;; esac
              ;;
            NOT_APPLICABLE)
              # An NA lifecycle check is assessed evidence, but it is not a PASS.
              # Preserve a real adverse/unreadable result from another mapped check.
              case "$worst" in FAIL|WARN|NOT_ASSESSED) ;; *) worst=NOT_APPLICABLE;; esac
              ;;
          esac
        fi
      done
      i=$((i+1))
    done
    if [ "$nmapped" -gt 0 ] && [ $((nneedroot+nnotassessed)) -eq "$nmapped" ]; then
      # every mapped finding is either an unassessed need-root WARN or a literal
      # NOT_ASSESSED — an examiner must see NOT ASSESSED (never a WARN that reads as a
      # finding, and never a silently-defaulted PASS).
      row="<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:id\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:labels\">$labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:status\"><span class=\"chip MUTE\">NOT ASSESSED</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:observed\">$obs</td></tr>"
      AR_NP="$AR_NP$row"; ctlst=NOT_ASSESSED
    elif [ "$nmapped" -gt 0 ] && [ "$nnotapplicable" -eq "$nmapped" ]; then
      row="<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:id\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:labels\">$labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:status\"><span class=\"chip MUTE\">NOT APPLICABLE</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:observed\">$obs</td></tr>"
      AR_NP="$AR_NP$row"; ctlst=NOT_APPLICABLE
    else
      ch=$(chip_of "$worst")
      # display text: "NOT ASSESSED" (with space) for the mixed-NOT_ASSESSED case,
      # matching the dedicated all-unassessed row's own wording above -- never the
      # raw internal "NOT_ASSESSED" token.
      wlbl=$worst; [ "$worst" = "NOT_ASSESSED" ] && wlbl="NOT ASSESSED"
      [ "$worst" = "NOT_APPLICABLE" ] && wlbl="NOT APPLICABLE"
      row="<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:id\">$(printf '%s' "$t"|hesc)</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:labels\">$labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$t_h:status\"><span class=\"chip $ch\">$wlbl</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$t_h:observed\">$obs</td></tr>"
      if [ "$worst" = "PASS" ]; then AR_P="$AR_P$row"; else AR_NP="$AR_NP$row"; fi
      ctlst=$worst
    fi
    # what this control ACTUALLY rendered as, for the coverage counters below
    CTAG_STATUS="$CTAG_STATUS$t|$ctlst
"
  done
  AUDITROWS="$AR_NP$AR_P"
  [ -z "$AUDITROWS" ] && AUDITROWS="<tr><td colspan=\"4\" data-aixray-field=\"observed\" data-aixray-location=\"report:no-mapped-findings\">No findings carry a $STDLABEL control tag in this scan.</td></tr>"

  # cis-l1: the crosswalk is the denominator, never the rendered count. Iterate the
  # distinct mapped control numbers derived from $cis_l1_map against the verdict-
  # mapped $CTAGS. A control with a PASS/FAIL verdict is assessed (already rendered
  # above); one whose mapped finding(s) render only NOT_APPLICABLE is resolved but
  # not assessed; any other verdict-less control — including one whose crosswalk
  # source cannot be resolved to a finding in this scan — is REFUSED and must render
  # as NOT ASSESSED, never silently dropped. Unlike the L2 sweep (which appends its
  # refusal rows after the PASS block), L1 splices them into the non-pass block so
  # the heading's "non-pass first" promise holds. A pipeline `while` runs in a
  # subshell under ksh88, so feed every loop from a here-doc redirection.
  if [ "$COMPLIANCE" = "cis-l1" ]; then
    L1_INVENTORY=$(printf '%s\n' "$cis_l1_map" | awk -F'|' 'NF>=2 && !seen[$2]++{print $2}')
    L1_REFUSED_HTML=""
    L1_NA_HTML=""
    while read -r ctl; do
      [ -n "$ctl" ] || continue
      ctl_h=$(printf '%s' "$ctl" | attr_hesc)
      covered=0
      case " $CTAGS " in *" $ctl "*) covered=1;; esac
      [ "$covered" -eq 1 ] && continue
      # Verdict-less: crosswalked but no PASS/FAIL this scan. Resolve each mapped
      # source's effective status from the finding arrays, mirroring
      # cis_l1_verdicts' own nfs_exports WARN downgrade. Any NOT_ASSESSED (or an
      # unresolvable source — a stig:V-nnnnnn rule id, or a finding absent from
      # this scan) makes the control REFUSED; NOT_APPLICABLE only when every
      # resolved mapped finding is NA.
      l1state=""
      l1labels=""
      l1obs=""
      maprows=$(printf '%s\n' "$cis_l1_map" | awk -F'|' -v c="$ctl" '$2==c{print $1}')
      while read -r src; do
        [ -n "$src" ] || continue
        s=${src#finding:}
        i=0
        while [ "$i" -lt "$NFIND" ]; do
          if [ "${F_ID[$i]}" = "$s" ]; then
            st=${F_ST[$i]}
            if [ "$s" = "nfs_exports" ] && [ "$st" = "WARN" ]; then
              case "${F_OBS[$i]}" in
                "partially assessed —"*) st=NOT_ASSESSED;;
              esac
            fi
            l1labels="$l1labels${l1labels:+<br>}$(printf '%s' "${F_LBL[$i]}"|hesc)"
            l1obs="$l1obs${l1obs:+<br>}$(printf '%s' "${F_OBS[$i]}"|hesc)"
            if [ "$st" = "NOT_APPLICABLE" ]; then
              [ -z "$l1state" ] && l1state=NOT_APPLICABLE
            else
              l1state=NOT_ASSESSED
            fi
            break
          fi
          i=$((i+1))
        done
      done <<L1MAPEOF
$maprows
L1MAPEOF
      [ -z "$l1state" ] && l1state=NOT_ASSESSED
      [ -z "$l1labels" ] && l1labels="—"
      [ -z "$l1obs" ] && l1obs="—"
      if [ "$l1state" = "NOT_APPLICABLE" ]; then
        L1_NA_HTML="$L1_NA_HTML<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:id\">$ctl_h</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:labels\">$l1labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:status\"><span class=\"chip MUTE\">NOT APPLICABLE</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:observed\">$l1obs</td></tr>"
      else
        L1_REFUSED_HTML="$L1_REFUSED_HTML<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:id\">$ctl_h</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:labels\">$l1labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:status\"><span class=\"chip MUTE\">NOT ASSESSED</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:observed\">$l1obs</td></tr>"
      fi
    done <<L1EOF
$L1_INVENTORY
L1EOF
    AUDITROWS="$AR_NP$L1_REFUSED_HTML$L1_NA_HTML$AR_P"
  fi

  # cis-l2: the inventory is the denominator, never the rendered count. Iterate
  # $cis_l2_inventory against the mapped $CTAGS and the $cis_l2_map crosswalk.
  # Four states, never collapsed: a control with a PASS/FAIL verdict is assessed;
  # one whose mapped finding(s) render only NOT_APPLICABLE is resolved but not
  # assessed; one whose mapped finding(s) render NOT_ASSESSED (or whose crosswalk
  # cannot be resolved to a finding in this scan) is REFUSED and must render as
  # NOT ASSESSED — never as UNMAPPED; only a control with no $cis_l2_map row at
  # all is UNMAPPED. A pipeline `while` runs in a subshell under ksh88, so feed
  # every loop from a here-doc redirection.
  CIS_L2_COVERED=0
  CIS_L2_REFUSED=0
  CIS_L2_NA=0
  CIS_L2_UNMAPPED=0
  CIS_L2_DENOMINATOR=${cis_l2_total:-0}
  if [ "$COMPLIANCE" = "cis-l2" ]; then
    CIS_L2_REFUSED_HTML=""
    CIS_L2_NA_HTML=""
    CIS_L2_UNMAPPED_HTML=""
    while read -r ctl; do
      [ -n "$ctl" ] || continue
      ctl_h=$(printf '%s' "$ctl" | attr_hesc)
      covered=0
      case " $CTAGS " in *" $ctl "*) covered=1;; esac
      if [ "$covered" -eq 1 ]; then
        # A control now carries a verdict even when that verdict is a refusal, so
        # CTAGS membership no longer means "assessed". Count what the row actually
        # rendered: only a determinate PASS/FAIL/WARN is assessed. Counting a
        # refusal here would launder unread evidence into a coverage claim.
        CIS_L2_CTL_ST=$(printf '%s\n' "$CTAG_STATUS" | awk -F'|' -v c="$ctl" '$1==c{print $2; exit}')
        case "$CIS_L2_CTL_ST" in
          PASS|FAIL|WARN)  CIS_L2_COVERED=$((CIS_L2_COVERED+1));;
          NOT_APPLICABLE)  CIS_L2_NA=$((CIS_L2_NA+1));;
          *)               CIS_L2_REFUSED=$((CIS_L2_REFUSED+1));;
        esac
        continue
      fi
      # No PASS/FAIL verdict this scan. Is the control even crosswalked?
      maprows=$(printf '%s\n' "$cis_l2_map" | awk -F'|' -v c="$ctl" '$2==c{print $1}')
      if [ -z "$maprows" ]; then
        CIS_L2_UNMAPPED=$((CIS_L2_UNMAPPED+1))
        CIS_L2_UNMAPPED_HTML="$CIS_L2_UNMAPPED_HTML<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:id\">$ctl_h</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:labels\">—</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:status\"><span class=\"chip MUTE\">UNMAPPED</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:observed\">—</td></tr>"
        continue
      fi
      # Crosswalked but verdict-less. Resolve the mapped finding's effective
      # status from the finding arrays, mirroring cis_l2_verdicts' own nfs_exports
      # WARN downgrade. Any NOT_ASSESSED (or an unresolvable mapping) makes the
      # control REFUSED; NOT_APPLICABLE only when every mapped finding is NA.
      l2state=""
      l2labels=""
      l2obs=""
      while read -r src; do
        [ -n "$src" ] || continue
        s=${src#finding:}
        i=0
        while [ "$i" -lt "$NFIND" ]; do
          if [ "${F_ID[$i]}" = "$s" ]; then
            st=${F_ST[$i]}
            if [ "$s" = "nfs_exports" ] && [ "$st" = "WARN" ]; then
              case "${F_OBS[$i]}" in
                "partially assessed —"*) st=NOT_ASSESSED;;
              esac
            fi
            l2labels="$l2labels${l2labels:+<br>}$(printf '%s' "${F_LBL[$i]}"|hesc)"
            l2obs="$l2obs${l2obs:+<br>}$(printf '%s' "${F_OBS[$i]}"|hesc)"
            if [ "$st" = "NOT_APPLICABLE" ]; then
              [ -z "$l2state" ] && l2state=NOT_APPLICABLE
            else
              l2state=NOT_ASSESSED
            fi
            break
          fi
          i=$((i+1))
        done
      done <<L2MAPEOF
$maprows
L2MAPEOF
      [ -z "$l2state" ] && l2state=NOT_ASSESSED
      if [ "$l2state" = "NOT_APPLICABLE" ]; then
        CIS_L2_NA=$((CIS_L2_NA+1))
        CIS_L2_NA_HTML="$CIS_L2_NA_HTML<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:id\">$ctl_h</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:labels\">$l2labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:status\"><span class=\"chip MUTE\">NOT APPLICABLE</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:observed\">$l2obs</td></tr>"
      else
        CIS_L2_REFUSED=$((CIS_L2_REFUSED+1))
        CIS_L2_REFUSED_HTML="$CIS_L2_REFUSED_HTML<tr><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:id\">$ctl_h</td><td class=\"ctl\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:labels\">$l2labels</td><td data-aixray-field=\"technical\" data-aixray-location=\"control:$ctl_h:status\"><span class=\"chip MUTE\">NOT ASSESSED</span></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"control:$ctl_h:observed\">$l2obs</td></tr>"
      fi
    done <<EOF
$cis_l2_inventory
EOF
    AUDITROWS="$AUDITROWS$CIS_L2_REFUSED_HTML$CIS_L2_NA_HTML$CIS_L2_UNMAPPED_HTML"
    COV_HTML="<div class=\"cov\" data-aixray-field=\"observed\" data-aixray-location=\"report:automation-coverage\"><b>Automation coverage.</b> PTxray automates ${NMAP} finding(s) mapped to this standard. ${CIS_L2_COVERED} of ${CIS_L2_DENOMINATOR} CIS L2 inventory controls are assessed in this scan; ${CIS_L2_REFUSED} refused, ${CIS_L2_NA} not applicable, ${CIS_L2_UNMAPPED} unmapped. A compliance program also requires manual/organizational review — see the manual-review section below.</div>"
  else
    COV_HTML="<div class=\"cov\" data-aixray-field=\"observed\" data-aixray-location=\"report:automation-coverage\"><b>Automation coverage.</b> PTxray automates ${NMAP} finding(s) mapped to this standard. A compliance program also requires manual/organizational review — see the manual-review section below. N is the count of findings carrying a ${STDLABEL} control tag in this scan; no full control-set total is claimed.</div>"
  fi

  # (d) critical-first queue — Critical then High across every category
  CQ=""
  CQ_COUNT=0
  for want in Critical High; do
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      rk=$(risk_of "${F_ST[$i]}" "${F_SEV[$i]}")
      if [ "$rk" = "$want" ]; then
        finding_h=$(printf '%s' "${F_ID[$i]}" | attr_hesc)
        CQ="$CQ<tr><td data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:risk\"><span class=\"risk $(riskcls "$rk")\">$rk</span></td><td data-aixray-field=\"observed\" data-aixray-location=\"finding:$finding_h:category\">$(catlbl_of "${F_CAT[$i]}"|hesc)</td><td class=\"ctl\" $(finding_label_privacy_attrs "${F_ID[$i]}")>$(printf '%s' "${F_LBL[$i]}"|hesc)</td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$finding_h:observed\">$(printf '%s' "${F_OBS[$i]}"|hesc)</td></tr>"
        CQ_COUNT=$((CQ_COUNT+1))
      fi
      i=$((i+1))
    done
  done
  [ -z "$CQ" ] && CQ="<tr><td colspan=\"4\" data-aixray-field=\"authored\" data-aixray-copy-id=\"compliance:no-high-risk-v1\">No Critical or High risk items in this scan.</td></tr>"

  # (d) remediation worklist — every non-PASS finding grouped by category in display order
  WL=""
  ci=0
  while [ "$ci" -lt 9 ]; do
    seg=""
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      if [ "${F_CAT[$i]}" = "${CAT_ID[$ci]}" ] &&
         [ "${F_ST[$i]}" != "PASS" ] && [ "${F_ST[$i]}" != "NOT_APPLICABLE" ]; then
        rk=$(risk_of "${F_ST[$i]}" "${F_SEV[$i]}")
        tg=""
        if [ "$COMPLIANCE" = "cis-l1" ]; then
          tg=$(cis_l1_verdicts "$i" | awk -F'|' 'NF>=2{printf "%s%s %s",(n++?", ":""),$1,$2}')
        elif [ "$COMPLIANCE" = "cis-l2" ]; then
          tg=$(cis_l2_verdicts "$i" | awk -F'|' 'NF>=2{printf "%s%s %s",(n++?", ":""),$1,$2}')
        else
          for tok in ${F_CTL[$i]}; do tg="$tg${tg:+, }$tok"; done
        fi
        [ -z "$tg" ] && tg="—"
        finding_h=$(printf '%s' "${F_ID[$i]}" | attr_hesc)
        seg="$seg<tr class=\"${F_ST[$i]}\" data-aixray-finding-id=\"$finding_h\"><td data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:risk\"><span class=\"risk $(riskcls "$rk")\">$rk</span></td>"
        seg="$seg<td class=\"ctl\" $(finding_label_privacy_attrs "${F_ID[$i]}")>$(printf '%s' "${F_LBL[$i]}"|hesc)</td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$finding_h:observed\">$(printf '%s' "${F_OBS[$i]}"|hesc)</td>"
        seg="$seg<td data-aixray-container=\"fields\">$(finding_guidance_privacy_html "${F_ID[$i]}" "${F_MEAN[$i]}")</td>"
        seg="$seg<td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:controls\">$(printf '%s' "$tg"|hesc)</td></tr>"
      fi
      i=$((i+1))
    done
    if [ -n "$seg" ]; then
      WL="$WL<div class=\"cathead\"><span class=\"cl\">$(catlbl_of "${CAT_ID[$ci]}"|hesc)</span></div>"
      WL="$WL<table><thead><tr><th>Risk</th><th>Finding</th><th>Observed</th><th>What it means</th><th>Control tags</th></tr></thead><tbody>$seg</tbody></table>"
      WL="$WL$MITIGATE_CTA"
    fi
    ci=$((ci+1))
  done
  [ -z "$WL" ] && WL="<p class=\"none\" data-aixray-field=\"authored\" data-aixray-copy-id=\"compliance:no-open-findings-v1\">No open findings — every check passed in this scan.</p>"
# ---- compliance executive summary ----------------------------------------------------------
EXEC_SUMMARY=""
EXEC_SUMMARY_NOTE=""
EXEC_TOTAL_PASS=0; EXEC_TOTAL_ASSESSED=0; EXEC_TOTAL_NA_SUM=0

case "$COMPLIANCE" in
  cis-l1|cis-l2)
    EXEC_MAP_NAME="cis_l1_map"
    [ "$COMPLIANCE" = "cis-l2" ] && EXEC_MAP_NAME="cis_l2_map"
    EXEC_MAP_VALUE=$(eval "printf '%s\\n' \"\$$EXEC_MAP_NAME\"")

    # Serialize EVERY crosswalk source's status, keyed by the FULL map token
    # ("finding:<id>" and "stig:V-nnnnnn"), so a rule-engine source resolves here
    # exactly as it does in cis_l1_verdicts/cis_l2_verdicts. Keying by a bare
    # finding id made every stig: source unresolvable, and determinate measured
    # rule verdicts were reported as refusals.
    EXEC_FINDING_STATUSES=""
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      EXEC_SRC_ST=${F_ST[$i]}
      # Same partial-NFS downgrade cis_l1_verdicts applies in shell, where the
      # observed text is available: a partially assessed export set cannot prove
      # its mapped control passed.
      if [ "${F_ID[$i]}" = "nfs_exports" ] && [ "$EXEC_SRC_ST" = "WARN" ]; then
        case "${F_OBS[$i]}" in
          "partially assessed —"*) EXEC_SRC_ST=NOT_ASSESSED;;
        esac
      fi
      EXEC_FINDING_STATUSES="${EXEC_FINDING_STATUSES}finding:${F_ID[$i]}|${EXEC_SRC_ST}
"
      if [ -n "${F_RULES[$i]}" ]; then
        EXEC_FINDING_STATUSES="${EXEC_FINDING_STATUSES}$(printf '%s\n' "${F_RULES[$i]}" | awk -F'|' 'NF>=2{print $1 "|" $2}')
"
      fi
      i=$((i+1))
    done

    # Phase 1: expanded sections (>25% of DISTINCT controls)
    EXEC_EXPANDED=$(printf '%s\n' "$EXEC_MAP_VALUE" | awk -F'|' '
      NF >= 2 {
        control = $2
        if (!(control in seen)) {
          seen[control] = 1
          split(control, p, ".")
          sc[p[1]]++
          tc++
        }
      }
      END {
        for (s in sc) {
          pct = int(sc[s] * 100 / tc)
          if (pct > 25) printf "%s ", s
        }
      }')

    # Phase 2: per-control rollup + section grouping
    EXEC_AWK_OUT=$(
      {
        printf '%s\n' "$EXEC_FINDING_STATUSES"
        printf '---\n'
        printf '%s\n' "$EXEC_MAP_VALUE"
      } | awk -F'|' -v expanded="$EXEC_EXPANDED" '
      function is_expanded(sec) {
        return index(" " expanded " ", " " sec " ") > 0
      }
      function worst_status(a, b) {
        if (a == "FAIL" || b == "FAIL") return "FAIL"
        if (a == "WARN" || b == "WARN") return "WARN"
        if (a == "NOT_ASSESSED" || b == "NOT_ASSESSED") return "NOT_ASSESSED"
        if (a == "NOT_APPLICABLE" || b == "NOT_APPLICABLE") return "NOT_APPLICABLE"
        return "PASS"
      }
      BEGIN { mode = "status" }
      /^---$/ { mode = "map"; next }
      mode == "status" && NF >= 2 { status[$1] = $2; next }
      mode == "map" && NF >= 2 {
        source = $1; control = $2
        st = status[source]
        # Unresolvable source → refusal, never a void
        if (st == "") st = "NOT_ASSESSED"
        # SOURCE STATUS LADDER -- identical to cis_l1_verdicts/cis_l2_verdicts.
        if (st == "NA") st = "NOT_APPLICABLE"
        if (source == "finding:nfs_exports" && st == "WARN") st = "PASS"
        else if (st == "WARN") st = "FAIL"
        # Roll up to control: worst status wins
        if (!(control in control_status)) control_status[control] = st
        else control_status[control] = worst_status(control_status[control], st)
        if (!(control in control_seen)) {
          control_seen[control] = 1
          np = split(control, parts, ".")
          control_section[control] = parts[1]
          if (np >= 2) control_child[control] = parts[1] "." parts[2]
          else control_child[control] = parts[1]
          total_controls++
        }
      }
      END {
        # Group controls into sections
        for (c in control_status) {
          section = control_section[c]
          child = control_child[c]
          if (is_expanded(section)) key = child; else key = section
          st = control_status[c]
          if (st == "PASS") { pass[key]++; assessed[key]++ }
          else if (st == "FAIL") { fail[key]++; assessed[key]++ }
          else if (st == "WARN") { warn[key]++; assessed[key]++ }
          else if (st == "NOT_ASSESSED") na[key]++
          else if (st == "NOT_APPLICABLE") nap[key]++
          has_ctrls[key] = 1
        }

        # Overall totals
        total_pass = 0; total_assessed = 0; total_na_sum = 0; total_napp_sum = 0
        for (c in control_status) {
          st = control_status[c]
          if (st == "PASS") total_pass++
          if (st == "PASS" || st == "FAIL" || st == "WARN") total_assessed++
          if (st == "NOT_ASSESSED") total_na_sum++
          if (st == "NOT_APPLICABLE") total_napp_sum++
        }

        # Sort keys
        nkeys = 0
        for (k in has_ctrls) keys[nkeys++] = k
        for (i = 0; i < nkeys; i++)
          for (j = i+1; j < nkeys; j++) {
            split(keys[i], pa, "."); split(keys[j], pb, ".")
            if (pa[1]+0 > pb[1]+0 || (pa[1] == pb[1] && pa[2]+0 > pb[2]+0)) {
              tmp = keys[i]; keys[i] = keys[j]; keys[j] = tmp
            }
          }

        for (i = 0; i < nkeys; i++) {
          key = keys[i]
          p = pass[key]+0; f = fail[key]+0; w = warn[key]+0
          n = na[key]+0; np = nap[key]+0
          d = p + f + w + n + np
          a = assessed[key]+0
          if (d == 0) {
            printf "BAR|%s|section %s|0|0|0|0|0|no assessed controls|na\n", key, key
            continue
          }
          fp = int(f*100/d); wp = int(w*100/d); napct = int(n*100/d); nappct = int(np*100/d)
          pp = 100 - fp - wp - napct - nappct
          if      (f > 0)          cls = "fail"
          else if (w > 0 || n > 0) cls = "warn"
          else if (p == 0 && np > 0) cls = "na"
          else                     cls = "pass"
          lbl = p " of " a " pass"
          if (f  > 0) lbl = lbl " · " f " fail"
          if (w  > 0) lbl = lbl " · " w " warn"
          if (n  > 0) lbl = lbl " · " n " not assessed"
          if (np > 0) lbl = lbl " · " np " n/a"
          printf "BAR|%s|section %s|%d|%d|%d|%d|%d|%s|%s\n", key, key, pp, fp, wp, napct, nappct, lbl, cls
        }

        # Overall summary line
        if (total_assessed > 0) {
          overall_pct = int(total_pass * 100 / total_assessed)
          printf "SUMMARY|%d|%d|%d|%d|%d\n", total_pass, total_assessed, overall_pct, total_na_sum, total_napp_sum
        }
      }')

    # Parse awk output into HTML bars
    EXEC_OLD_IFS="$IFS"; IFS='
'
    for EXEC_LINE in $EXEC_AWK_OUT; do
      IFS='|'
      set -- $EXEC_LINE
      IFS='
'
      EXEC_TYPE=$1
      if [ "$EXEC_TYPE" = "SUMMARY" ]; then
        EXEC_TOTAL_PASS=$2; EXEC_TOTAL_ASSESSED=$3; EXEC_OVERALL_PCT=$4
        EXEC_TOTAL_NA_SUM=$5; EXEC_TOTAL_NAPP=$6
        continue
      fi
      EXEC_KEY=$2; EXEC_LABEL=$3
      EXEC_PP=$4; EXEC_FP=$5; EXEC_WP=$6; EXEC_NAPCT=$7; EXEC_NAPPCT=$8
      EXEC_LBL=$9; EXEC_CLS=${10}

      EXEC_METER=""
      [ "$EXEC_PP"    -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill pass\" style=\"width:${EXEC_PP}%\"></span>"
      [ "$EXEC_FP"    -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill fail\" style=\"width:${EXEC_FP}%\"></span>"
      [ "$EXEC_WP"    -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill warn\" style=\"width:${EXEC_WP}%\"></span>"
      [ "$EXEC_NAPCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill na\" style=\"width:${EXEC_NAPCT}%\"></span>"
      [ "$EXEC_NAPPCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill napp\" style=\"width:${EXEC_NAPPCT}%\"></span>"

      EXEC_SUMMARY="$EXEC_SUMMARY<div class=\"area-bar ${EXEC_CLS}\" data-aixray-container=\"fields\"><span class=\"area-label\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-section:${EXEC_KEY}\">section ${EXEC_KEY}</span><span class=\"area-meter\">${EXEC_METER}</span><span class=\"area-count\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-section-count:${EXEC_KEY}\">${EXEC_LBL}</span></div>"
    done
    IFS="$EXEC_OLD_IFS"

    if [ "$EXEC_TOTAL_ASSESSED" -gt 0 ]; then
      EXEC_NA_NOTE_HTML=""
      [ "$EXEC_TOTAL_NA_SUM" -gt 0 ] && EXEC_NA_NOTE_HTML=" <span class=\"na-note\">· ${EXEC_TOTAL_NA_SUM} not assessed</span>"
      EXEC_NAPP_NOTE_HTML=""
      [ "$EXEC_TOTAL_NAPP" -gt 0 ] && EXEC_NAPP_NOTE_HTML=" <span class=\"napp-note\">· ${EXEC_TOTAL_NAPP} n/a</span>"
      EXEC_TOTAL_NEEDS_ATTENTION=$(( FAIL + WARN + NASSESSED ))
      EXEC_TOTAL_NOTE_HTML=""
      [ "$EXEC_TOTAL_NEEDS_ATTENTION" -gt 0 ] && EXEC_TOTAL_NOTE_HTML=" — ${EXEC_TOTAL_NEEDS_ATTENTION} findings need attention and are listed below; pass and not-applicable controls are accounted for in the counts above rather than repeated in the list."
      EXEC_SUMMARY_NOTE="<p class=\"exec-summary-note\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-overall\">Overall: <b>${EXEC_TOTAL_PASS} of ${EXEC_TOTAL_ASSESSED} assessed controls passed</b> (${EXEC_OVERALL_PCT}%).${EXEC_NA_NOTE_HTML}${EXEC_NAPP_NOTE_HTML}${EXEC_TOTAL_NOTE_HTML} Not-assessed counts appear as the solid grey segment; not-applicable counts appear as the outlined pale segment. Absent segments mean zero.</p>"
    fi
    ;;

  *)
    # STIG / FFIEC: CAT_ID grouping (same logic as §7.1)
    EXEC_TOTAL_PASS=0; EXEC_TOTAL_ASSESSED=0; EXEC_TOTAL_NA_SUM=0; EXEC_TOTAL_NAPP=0
    ci=0
    while [ "$ci" -lt 9 ]; do
      EXEC_CT=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} + ${CN[$ci]} + ${CNA[$ci]} ))
      if [ "$EXEC_CT" -gt 0 ]; then
        EXEC_ASSESSED=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} ))
        EXEC_TOTAL_PASS=$(( EXEC_TOTAL_PASS + ${CP[$ci]} ))
        EXEC_TOTAL_ASSESSED=$(( EXEC_TOTAL_ASSESSED + EXEC_ASSESSED ))
        EXEC_TOTAL_NA_SUM=$(( EXEC_TOTAL_NA_SUM + ${CN[$ci]} ))
        EXEC_TOTAL_NAPP=$(( EXEC_TOTAL_NAPP + ${CNA[$ci]} ))
        if   [ "${CF[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="fail"
        elif [ "${CW[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="warn"
        elif [ "${CN[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="warn"
        else EXEC_BAR_CLASS="pass"; fi
        EXEC_DEN=$(( EXEC_ASSESSED + ${CN[$ci]} + ${CNA[$ci]} ))
        if [ "$EXEC_DEN" -gt 0 ]; then
          EXEC_FAIL_PCT=$(( ${CF[$ci]} * 100 / EXEC_DEN ))
          EXEC_WARN_PCT=$(( ${CW[$ci]} * 100 / EXEC_DEN ))
          EXEC_NA_PCT=$(( ${CN[$ci]} * 100 / EXEC_DEN ))
          EXEC_NAPP_PCT=$(( ${CNA[$ci]} * 100 / EXEC_DEN ))
          EXEC_PASS_PCT=$(( 100 - EXEC_FAIL_PCT - EXEC_WARN_PCT - EXEC_NA_PCT - EXEC_NAPP_PCT ))
        else
          EXEC_PASS_PCT=0; EXEC_FAIL_PCT=0; EXEC_WARN_PCT=0; EXEC_NA_PCT=0; EXEC_NAPP_PCT=0
        fi
        EXEC_METER=""
        [ "$EXEC_PASS_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill pass\" style=\"width:${EXEC_PASS_PCT}%\"></span>"
        [ "$EXEC_FAIL_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill fail\" style=\"width:${EXEC_FAIL_PCT}%\"></span>"
        [ "$EXEC_WARN_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill warn\" style=\"width:${EXEC_WARN_PCT}%\"></span>"
        [ "$EXEC_NA_PCT"  -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill na\" style=\"width:${EXEC_NA_PCT}%\"></span>"
        [ "$EXEC_NAPP_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill napp\" style=\"width:${EXEC_NAPP_PCT}%\"></span>"
        EXEC_LABEL="${CP[$ci]} of ${EXEC_ASSESSED} pass"
        [ "${CF[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"fail-count\">${CF[$ci]} fail</span>"
        [ "${CW[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"warn-count\">${CW[$ci]} warn</span>"
        [ "${CN[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"na-count\">${CN[$ci]} not assessed</span>"
        [ "${CNA[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"napp-count\">${CNA[$ci]} n/a</span>"
        EXEC_SUMMARY="$EXEC_SUMMARY<div class=\"area-bar ${EXEC_BAR_CLASS}\" data-aixray-container=\"fields\"><span class=\"area-label\" data-aixray-field=\"authored\" data-aixray-copy-id=\"finding-label:cat-${CAT_ID[$ci]}:v1\">$(printf '%s' "${CAT_LBL[$ci]}"|hesc)</span><span class=\"area-meter\">${EXEC_METER}</span><span class=\"area-count\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-area-count:${CAT_ID[$ci]}\">${EXEC_LABEL}</span></div>"
      else
        EXEC_SUMMARY="$EXEC_SUMMARY<div class=\"area-bar na\" data-aixray-container=\"fields\"><span class=\"area-label\" data-aixray-field=\"authored\" data-aixray-copy-id=\"finding-label:cat-${CAT_ID[$ci]}:v1\">$(printf '%s' "${CAT_LBL[$ci]}"|hesc)</span><span class=\"area-meter\"><span class=\"area-meter-fill na\" style=\"width:100%\"></span></span><span class=\"area-count\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-area-count:${CAT_ID[$ci]}\">no findings emitted</span></div>"
      fi
      ci=$((ci+1))
    done
    if [ "$EXEC_TOTAL_ASSESSED" -gt 0 ]; then
      EXEC_OVERALL_PCT=$(( EXEC_TOTAL_PASS * 100 / EXEC_TOTAL_ASSESSED ))
      EXEC_NA_NOTE_HTML=""
      [ "$EXEC_TOTAL_NA_SUM" -gt 0 ] && EXEC_NA_NOTE_HTML=" <span class=\"na-note\">· ${EXEC_TOTAL_NA_SUM} not assessed</span>"
      EXEC_NAPP_NOTE_HTML=""
      [ "$EXEC_TOTAL_NAPP" -gt 0 ] && EXEC_NAPP_NOTE_HTML=" <span class=\"napp-note\">· ${EXEC_TOTAL_NAPP} n/a</span>"
      EXEC_TOTAL_NEEDS_ATTENTION=$(( FAIL + WARN + NASSESSED ))
      EXEC_TOTAL_NOTE_HTML=""
      [ "$EXEC_TOTAL_NEEDS_ATTENTION" -gt 0 ] && EXEC_TOTAL_NOTE_HTML=" — ${EXEC_TOTAL_NEEDS_ATTENTION} findings need attention and are listed below; pass and not-applicable controls are accounted for in the counts above rather than repeated in the list."
      EXEC_SUMMARY_NOTE="<p class=\"exec-summary-note\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-overall\">Overall: <b>${EXEC_TOTAL_PASS} of ${EXEC_TOTAL_ASSESSED} assessed checks passed</b> (${EXEC_OVERALL_PCT}%).${EXEC_NA_NOTE_HTML}${EXEC_NAPP_NOTE_HTML}${EXEC_TOTAL_NOTE_HTML} Not-assessed counts appear as the solid grey segment; not-applicable counts appear as the outlined pale segment. Absent segments mean zero.</p>"
    fi
    ;;
esac

EXEC_COMPLIANCE_BLOCK="<section class=\"exec-summary\" aria-labelledby=\"exec-title\"><h2 id=\"exec-title\">Page 1 · Executive summary</h2><p class=\"exec-summary-note\" data-aixray-field=\"authored\" data-aixray-copy-id=\"report:exec-compliance-disclosure-v1\">Grouped by benchmark section. Expanded sections (more than 25% of controls) split into numbered subsections. Pass/warn/fail/not-assessed/not-applicable segments are shown proportionally; absent segments mean zero. Bar outline colour reflects the worst finding in that area. Unresolvable map entries render as NOT_ASSESSED — a refusal, never a void.</p><div class=\"area-bars\">${EXEC_SUMMARY}</div>${EXEC_SUMMARY_NOTE}</section>"

  cat <<HTML
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="aixray-report-version" content="1">
<meta name="aixray-privacy-schema" content="1">
<meta name="aixray-report-date" content="${REPORT_DATE}">
<meta name="aixray-report-host" content="${HOST_ATTR}">
<title>PTxray compliance — ${STDLABEL} — ${HOST_H}</title>
<style>
@font-face{font-family:'Plex Sans';src:url(data:font/woff2;base64,${report_font_plex_sans_variable_b64}) format('woff2');font-weight:300 700;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_semibold_b64}) format('woff2');font-weight:600;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_medium_b64}) format('woff2');font-weight:500;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_regular_b64}) format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_medium_b64}) format('woff2');font-weight:500;font-display:swap}
:root{
  --slate:#1B1F24; --slate2:#23272E; --slate3:#2B3038;
  --ink:#23272E; --body:#5C5F63; --mute:#8A929B;
  --cream:#F4F2EE; --line:#E2DDD5; --bg:#ffffff;
  --copper:#C2703D; --copper-d:#A85A2C; --copper-l:#D98A5A;
  --red:#B23A2C; --amber:#A9781A; --green:#2E7D52; --na:#8A929B;
  --red-t:#f7ece9; --amber-t:#f7f1e6; --green-t:#eef4ef; --na-t:#f1f1ef;
  --sans:'Plex Sans',-apple-system,system-ui,sans-serif;
  --serif:'Plex Serif',Georgia,serif;
  --mono:'Plex Mono',ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme:dark){:root{
  --slate:#0e1114; --slate2:#161a1f; --slate3:#1e242b; --ink:#eef0f2; --body:#b7bcc2; --mute:#8A929B;
  --cream:#191d22; --line:#2a3037; --bg:#111418;
  --red:#d6584a; --amber:#c99436; --green:#46a578; --na:#8a929b;
  --red-t:#20140f; --amber-t:#1f1810; --green-t:#0f1e16; --na-t:#181b1f;
}}
:root[data-theme="dark"]{--slate:#0e1114;--slate2:#161a1f;--slate3:#1e242b;--ink:#eef0f2;--body:#b7bcc2;--mute:#8A929B;--cream:#191d22;--line:#2a3037;--bg:#111418;--red:#d6584a;--amber:#c99436;--green:#46a578;--na:#8a929b;--red-t:#20140f;--amber-t:#1f1810;--green-t:#0f1e16;--na-t:#181b1f}
:root[data-theme="light"]{--slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;--ink:#23272E;--body:#5C5F63;--mute:#8A929B;--cream:#F4F2EE;--line:#E2DDD5;--bg:#ffffff;--red:#B23A2C;--amber:#A9781A;--green:#2E7D52;--na:#8A929B;--red-t:#f7ece9;--amber-t:#f7f1e6;--green-t:#eef4ef;--na-t:#f1f1ef}

*{box-sizing:border-box;border-radius:0}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--bg);color:var(--body);font-family:var(--sans);font-size:13.5px;line-height:1.55;-webkit-font-smoothing:antialiased;max-width:940px;margin-inline:auto}
b{color:var(--ink);font-weight:600}

.band{position:relative;background:var(--slate);color:#fff;padding:32px 40px 26px;overflow:hidden}
.band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px);background-size:26px 26px;mask-image:linear-gradient(120deg,#000,transparent 78%)}
.band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--copper)}
.band>*{position:relative}
.wm{font-family:var(--serif);font-size:27px;font-weight:600;color:#fff;line-height:1;letter-spacing:-.2px}
.tag{display:block;font-family:var(--mono);font-size:10px;letter-spacing:2.4px;color:#9aa2ab;text-transform:uppercase;margin-top:10px}
.ey{font-family:var(--mono);font-size:10.5px;letter-spacing:3px;text-transform:uppercase;color:var(--copper-l);margin-top:20px;font-weight:500}
h1{font-family:var(--serif);color:#fff;font-size:23px;font-weight:600;margin:7px 0 0;letter-spacing:-.2px;text-wrap:balance}
.review-offer{display:inline-block;margin-top:14px;color:var(--copper-l);font-family:var(--mono);font-size:11px;font-weight:600;line-height:1.45;text-decoration:none}
h2{font-family:var(--serif);color:var(--ink);font-size:15.5px;font-weight:600;margin:30px 40px 0;padding:0 0 8px;border-bottom:2px solid var(--ink)}
h2 .sub{font-family:var(--mono);font-size:9.5px;letter-spacing:1px;color:var(--mute);text-transform:uppercase;font-weight:500}

.meta{padding:13px 40px;background:var(--cream);border-bottom:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--mute);display:flex;flex-wrap:wrap;gap:5px 4px;align-items:center}
.meta b{color:var(--ink)}
.ro{display:inline-block;background:var(--bg);color:var(--green);font-family:var(--mono);font-size:10px;font-weight:600;padding:2px 9px;letter-spacing:.5px;border:1px solid color-mix(in srgb,var(--green) 40%,var(--line))}
.currency-attestation{padding:16px 0 10px;border-bottom:1px solid var(--line);background:var(--bg)}
.currency-alert,.currency-verified{margin:0 40px 12px;padding:13px 16px;font-family:var(--mono);font-size:11px;font-weight:600}
.currency-alert{background:var(--red-t);border:2px solid var(--red);color:var(--red)}
.currency-verified{background:var(--green-t);border-left:4px solid var(--green);color:var(--green)}
.currency-attestation h2{margin:0 40px;padding:0 0 7px;border-bottom:2px solid var(--ink);font-size:15.5px}
.currency-attestation .currency-table{margin-top:2px;margin-bottom:0;font-family:var(--mono);font-size:10.5px}
.cov{margin:18px 40px;padding:14px 16px;background:var(--cream);border-left:3px solid var(--copper);font-size:12px;color:var(--ink)}
.cov b{color:var(--ink)}
.privacy-callout{margin:18px 40px;padding:14px 16px;background:var(--cream);border-left:4px solid var(--copper);font-size:12px;color:var(--ink)}
.privacy-callout code{font-family:var(--mono);font-size:11px}

.exec-summary{margin:22px 40px 14px}
.exec-summary h2{font-family:var(--serif);font-size:18px;font-weight:600;color:var(--ink);margin:0 0 16px;padding:0 0 8px;border-bottom:2px solid var(--ink)}
.area-bars{display:grid;gap:6px}
.area-bar{display:grid;grid-template-columns:200px minmax(0,1fr) auto;gap:10px;align-items:center;padding:6px 0}
.area-bar.fail .area-meter{box-shadow:inset 0 0 0 1px var(--red)}
.area-bar.warn .area-meter{box-shadow:inset 0 0 0 1px var(--amber)}
.area-bar.pass .area-meter{box-shadow:inset 0 0 0 1px var(--green)}
.area-bar.na .area-meter{box-shadow:inset 0 0 0 1px var(--na)}
.area-label{font-weight:600;color:var(--ink);font-size:11.5px;text-align:right}
.area-meter{display:flex;height:14px;background:var(--line)}
.area-meter-fill{display:block;height:100%}
.area-meter-fill.pass{background:var(--green)}
.area-meter-fill.warn{background:var(--amber)}
.area-meter-fill.fail{background:var(--red)}
.area-meter-fill.na{background:var(--na)}
.area-meter-fill.napp{background:var(--na-t);box-shadow:inset 0 0 0 1px var(--na)}
.area-count{font-family:var(--mono);font-size:10.5px;color:var(--mute);font-variant-numeric:tabular-nums;white-space:nowrap}
.area-count .fail-count{color:var(--red);font-weight:600}
.area-count .warn-count{color:var(--amber);font-weight:600}
.area-count .na-count{color:var(--mute)}
.area-count .napp-count{color:var(--mute)}
.exec-summary-note{margin:18px 0 0;font-size:11px;color:var(--mute)}
.exec-summary-note b{color:var(--ink)}
.exec-summary-note .na-note{color:var(--na)}
.exec-summary-note .napp-note{color:var(--na)}

.cathead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:30px 40px 0;padding:0 0 8px;border-bottom:2px solid var(--ink)}
.cathead .cl{font-family:var(--serif);font-size:15.5px;color:var(--ink);font-weight:600}
.cathead .cr{display:flex;align-items:center;gap:10px}
.cathead .cnt{font-family:var(--mono);font-size:10.5px;color:var(--mute);font-variant-numeric:tabular-nums}
.chip{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.8px;padding:3px 9px;color:#fff;text-transform:uppercase}
.chip.RED{background:var(--red)}.chip.AMBER{background:var(--amber)}.chip.GREEN{background:var(--green)}.chip.INCOMPLETE,.chip.MUTE{background:var(--na)}
.risk{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.5px;padding:3px 8px;color:#fff;display:inline-block;white-space:nowrap;text-transform:uppercase}
.risk.crit,.risk.high{background:var(--red)}.risk.med{background:var(--amber)}.risk.low{background:var(--na)}

table{width:calc(100% - 80px);margin:2px 40px 6px;border-collapse:separate;border-spacing:0;font-size:12.5px}
thead th{color:var(--mute);font-family:var(--mono);font-size:9.5px;letter-spacing:1.1px;text-transform:uppercase;text-align:left;font-weight:600;padding:10px 12px 7px;border-bottom:1px solid var(--line)}
td{padding:11px 12px;border-bottom:1px solid var(--line);vertical-align:top}
td.ctl{font-weight:600;color:var(--ink);width:19%}
td.st{font-family:var(--mono);font-weight:600;width:7%;font-size:10px}
td.st.PASS{color:var(--green)}td.st.WARN{color:var(--amber)}td.st.FAIL{color:var(--red)}td.st.NOT_ASSESSED,td.st.NOT_APPLICABLE{color:var(--na)}
td.sev{font-family:var(--mono);color:var(--mute);text-transform:uppercase;font-size:9.5px;width:6%;letter-spacing:.4px}
td.obs{font-family:var(--mono);font-size:11px;color:var(--ink);width:20%;word-break:break-word}
tr.FAIL td:first-child{box-shadow:inset 4px 0 var(--red)}
tr.WARN td:first-child{box-shadow:inset 4px 0 var(--amber)}
tr.PASS td:first-child{box-shadow:inset 4px 0 color-mix(in srgb,var(--green) 55%,transparent)}
tr.NOT_ASSESSED td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.NOT_APPLICABLE td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.FAIL{background:var(--red-t)}tr.WARN{background:var(--amber-t)}tr.NOT_ASSESSED,tr.NOT_APPLICABLE{background:var(--na-t)}
.mitigate{margin:2px 40px 16px;font-family:var(--mono);font-size:10px;letter-spacing:.3px;color:var(--mute)}
.mitigate a{color:var(--copper-d);font-weight:600;text-decoration:none}
.cta a{color:var(--copper-d);font-weight:600;text-decoration:none}

.plan-card{margin:22px 40px 14px;padding:20px;background:var(--cream);border:2px solid var(--copper);color:var(--body)}
.plan-card-main{display:grid;grid-template-columns:minmax(0,1fr) 32mm;gap:20px;align-items:start}
.plan-card-copy{min-width:0}
.plan-copy-status{display:inline-block;margin:0 0 9px;padding:3px 8px;background:var(--copper-d);color:#fff;font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.7px}
.plan-card h2{margin:0;padding:0;border:0;color:var(--ink);font-family:var(--serif);font-size:20px;line-height:1.2}
.plan-link{margin:14px 0 0}.plan-link a{display:inline-block;padding:9px 12px;background:var(--slate);color:#fff;font-weight:600;text-decoration:none}
.plan-card a:focus-visible{outline:3px solid var(--copper);outline-offset:3px}
.plan-fallback{margin:9px 0 0;color:var(--ink);font-family:var(--mono);font-size:10.5px;overflow-wrap:anywhere}
.plan-qr{margin:0;display:flex;flex-direction:column;align-items:center;gap:7px;color:var(--body)}
.plan-qr svg{display:block;width:32mm;height:32mm;max-width:none;flex:none;background:#fff}
.plan-qr figcaption{max-width:32mm;font-size:9.5px;line-height:1.35;text-align:center}
.plan-safe-send{margin-top:16px;padding:12px 14px;background:var(--bg);border-left:4px solid var(--copper);color:var(--ink);font-size:11px;overflow-wrap:anywhere}
.plan-safe-send p{margin:0}.plan-safe-send p + p{margin-top:7px}
.plan-safe-send code{font-family:var(--mono);font-size:10px}.plan-safe-send a{color:var(--copper-d);font-weight:600}

.manual{margin:6px 40px 10px;font-size:12px;color:var(--body)}.manual li{margin:6px 0}.manual b{color:var(--ink)}
.none{margin:10px 40px;color:var(--green);font-size:12px}
.attrib{margin:22px 40px 0;padding:12px 16px;background:var(--cream);border-left:3px solid var(--na);font-size:11px;color:var(--body)}
footer{margin:26px 40px 34px;padding:15px 0 0;border-top:2px solid var(--copper);font-family:var(--mono);font-size:10px;letter-spacing:.4px;color:var(--mute);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
footer b,footer a{color:var(--copper-d)}

.page-break{margin:30px 40px 0;border-top:3px solid var(--copper)}
@media screen{.page-break{padding-top:14px}}

@media print{
  @page{
    margin:18mm 12mm 18mm;
    @top-left{content:"PTxray · ${PRINT_HOST}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @top-right{content:"${REPORT_DATE}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-left{content:"PowerTrue Systems";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-right{content:"Page " counter(page) " of " counter(pages);font-family:var(--mono);font-size:8pt;color:#5C5F63}
  }
  :root,:root[data-theme="dark"],:root[data-theme="light"]{
    --slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;
    --ink:#23272E;--body:#5C5F63;--mute:#6B7280;
    --cream:#F4F2EE;--line:#D8D3CB;--bg:#ffffff;
    --red:#9F2F23;--amber:#805B12;--green:#236641;--na:#666E78;
    --red-t:#F7ECE9;--amber-t:#F7F1E6;--green-t:#EEF4EF;--na-t:#F1F1EF;
  }
  html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  body{max-width:none;background:#fff;color:var(--body);font-size:10pt;line-height:1.4}
  .band::before{display:none}
  .band,.meta,.score,.banner,.scorebox,.cov,.attrib,footer,li{break-inside:avoid;page-break-inside:avoid}
  .plan-card,.plan-card-main,.plan-safe-send,.plan-qr{break-inside:avoid;page-break-inside:avoid}
  .plan-card{margin-left:0;margin-right:0}
  .plan-card h2{break-before:auto;page-break-before:auto;break-after:auto;page-break-after:auto}
  .plan-qr svg{width:32mm;height:32mm}
  .exec-summary h2{break-before:auto;page-break-before:auto}
  .page-break{border-top:0;margin:0;break-before:page;page-break-before:always}
  .page-break + *{break-before:auto;page-break-before:auto}
  .exec-summary{break-inside:avoid;page-break-inside:avoid}
  .area-bar{break-inside:avoid;page-break-inside:avoid}
  h2,.cathead{break-after:avoid-page;page-break-after:avoid}
  h2,.score + .cathead,table + .cathead{break-before:page;page-break-before:always}
  .currency-attestation{break-inside:avoid;page-break-inside:avoid}
  .currency-attestation h2{break-before:auto;page-break-before:auto}
  thead{display:table-header-group}
  tr,td{break-inside:avoid;page-break-inside:avoid}
  h2,.cathead,.cov,.manual,.none,.attrib,footer{margin-left:0;margin-right:0}
  table{width:100%;margin-left:0;margin-right:0;font-size:9pt}
  .cta,.mitigate{display:none}
}
@media (max-width:620px){
  .band,.meta,.score,.cathead,footer{padding-inline:22px;margin-inline:0}
  h2,.cov,.manual,.none,.attrib{margin-inline:22px}
  table{width:calc(100% - 44px);margin-inline:22px}
  .scorebox{min-width:calc(50% - 1px)}
  .plan-card{margin-inline:22px;padding:16px}
  .plan-card-main{grid-template-columns:1fr}
  .area-bar{grid-template-columns:1fr;gap:3px;padding:8px 0}
  .area-label{text-align:left}
  .exec-summary{margin-inline:22px}
}
</style></head><body>
<div class="band"><div class="wm"><span data-aixray-field="authored" data-aixray-copy-id="product:brand-name-v1">PTxray</span><div class="tag" data-aixray-field="authored" data-aixray-copy-id="product:brand-tag-compliance-v1">by PowerTrue Systems · AIX · IBM Power · VIOS</div></div><div class="ey" data-aixray-field="authored" data-aixray-copy-id="product:compliance-report-v1">Compliance report</div><h1>Compliance report — <span data-aixray-field="technical" data-aixray-location="report:compliance-label">${STDLABEL}</span> — <span data-aixray-field="identity" data-aixray-location="report:title-host">${HOST_H}</span></h1><a class="review-offer" href="mailto:review@powertruesystems.com" data-aixray-field="authored" data-aixray-copy-id="product:review-cta-v1">${REVIEW_CTA}</a></div>
<div class="meta"><b>Host:</b> <span data-aixray-field="identity" data-aixray-location="report:host">${HOST_H}</span> &nbsp;·&nbsp; <b>Generated:</b> <span data-aixray-field="technical" data-aixray-location="report:generated-date">${NOW}</span> &nbsp;·&nbsp; <b>Reference data:</b> <span data-aixray-field="observed" data-aixray-location="report:reference-data">${COMPLIANCE_VINTAGE_H}${FLRTVC_HTML_META}</span> &nbsp;·&nbsp; <b>Standard:</b> <span data-aixray-field="technical" data-aixray-location="report:compliance-standard">${STDFULL}</span> &nbsp;·&nbsp; <span class="ro" data-aixray-field="authored" data-aixray-copy-id="product:read-only-v1">READ-ONLY — nothing was changed</span></div>
<div class="privacy-callout" data-aixray-field="authored" data-aixray-copy-id="raw-privacy-callout-v1">This raw report contains identifying system data. Create a separate pseudonymized review copy before sharing: <code>./ptxray-review-pack.sh --pseudonymize &lt;this-report&gt;</code>. Inspect the review copy and local removals manifest before anything leaves this machine.</div>
${CURRENCY_HTML_BLOCK}
${COV_HTML}
${EXEC_COMPLIANCE_BLOCK}
<h2>Critical-first queue <span class="sub">Critical then High risk · work top-down</span></h2>
<table><thead><tr><th>Risk</th><th>Category</th><th>Finding</th><th>Observed</th></tr></thead><tbody>${CQ}</tbody></table>
$(plan_card_html "$CQ_COUNT")
<div class="page-break"></div>
<h2>Page 2 · Complete assessment detail</h2>
<h2>Auditor control summary <span class="sub">one row per mapped control · non-pass first</span></h2>
<table><thead><tr><th>Control</th><th>Mapped finding(s)</th><th>Status</th><th>Observed evidence</th></tr></thead><tbody>${AUDITROWS}</tbody></table>
<h2>Remediation worklist <span class="sub">every open finding, grouped by category</span></h2>
${WL}
<h2>Manual review <span class="sub">outside the tool's read-only view</span></h2>
<ul class="manual">
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-hmc-v1"><b>HMC currency &amp; config</b> — HMC firmware level and managed-system settings need HMC access; this tool runs inside the LPAR and cannot see the HMC.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-entitlement-v1"><b>SWMA / hardware maintenance entitlement</b> — software-maintenance and warranty coverage live in IBM's entitlement systems, not on the box.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-dr-v1"><b>DR / replication evidence</b> — an offsite/recovery story (failover site, replicated storage, tested runbook) is an organizational fact the tool cannot observe locally.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-runbook-v1"><b>Documented runbook &amp; alerting ownership</b> — who gets paged, and the written procedure they follow, are process artifacts, not system state.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-admin-inventory-v1"><b>Administrator account inventory</b> — whether a current inventory of administrator accounts exists, who owns it, how often it is reconciled against the box, and how joiners, movers and leavers reach it are facts about a process, not host state.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-user-inventory-v1"><b>User account inventory</b> — the same questions for ordinary user accounts: whether the inventory is current, who maintains it, on what cadence it is reconciled, and how joiners, movers and leavers reach it.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-flrtvc-cadence-v1"><b>FLRTVC checking cadence</b> — whether the fix-level vulnerability checker is run on a defined schedule, who owns that cadence, where its reports are retained, and how the findings it raises are driven to closure are operational facts no host scan can establish.</li>
<li data-aixray-field="authored" data-aixray-copy-id="compliance:manual-physical-v1"><b>Physical &amp; organizational controls</b> — data-center access, change control, separation of duties and staff training are program-level controls no host scan can measure.</li>
</ul>
<div class="attrib" data-aixray-field="authored" data-aixray-copy-id="${ATTRIB_COPY_ID}">${ATTRIB}</div>
${STANDARD_CURRENCY_DISCLOSURE}
<footer><span data-aixray-field="authored" data-aixray-copy-id="product:footer-report-v1">PTxray · by PowerTrue Systems · read-only · this report is yours to keep</span><a href="mailto:review@powertruesystems.com" data-aixray-field="authored" data-aixray-copy-id="product:review-cta-v1">${REVIEW_CTA}</a></footer>
<div class="cta" style="padding:14px 32px;background:var(--cream);font-family:var(--sans);font-size:12px;color:var(--ink)">
  <p style="margin:0 0 6px" data-aixray-field="authored" data-aixray-copy-id="product:book-cta-v1">${BOOK_CTA}</p>
  <p data-aixray-field="authored" data-aixray-copy-id="product:privacy-reminder-v1">Your raw report contains your hostname, addresses, and configuration. Create a separate pseudonymized review candidate with <code>./ptxray-review-pack.sh --pseudonymize &lt;this-report&gt;</code>. Inspect the candidate and local removals manifest before sharing; never send the local decode key or local manifest.</p>
  <p data-aixray-field="authored" data-aixray-copy-id="product:review-email-v1"><a href="mailto:review@powertruesystems.com">review@powertruesystems.com</a></p>
</div>
</body></html>
