  return $?
}

if [ "$FORMAT" = "compliance" ]; then
  # render loop — capture/assess ran once above; each selected standard gets one report
  # from the same snapshot (shared-snapshot contract). Mid-loop failure continues to the
  # next standard; the final rc is the worst of any failure.
  NSTD=0
  for _std in $COMPLIANCE_LIST; do NSTD=$((NSTD+1)); done
  # File output when more than one standard, or when a single standard was selected with
  # an explicit --out (menu path, fix-cycle-2 R2 ruling): write one file per standard into
  # OUT_DIR. Single standard with no --out still writes to stdout (byte-identical to the
  # pre-refactor CLI path).
  if [ "$NSTD" -gt 1 ] || [ -n "$OUT_DIR" ]; then
    if ! mkdir -p "$OUT_DIR" 2>/dev/null; then
      echo "ptxray: --out: cannot create directory '$OUT_DIR'" >&2
      exit 2
    fi
    REPORT_RC=0
    n=1
    for std in $COMPLIANCE_LIST; do
      echo "[$n of $NSTD] Rendering $std ..." >&2
      # write through the same guards the --html --out path applies: umask 077 + set -C on
      # a per-run tmp file, refuse a directory/symlink destination, atomic mv, verify a real
      # regular file landed. A failure is a per-standard ptxray diagnostic and the loop
      # continues to the next standard.
      REPORT_FILE="$OUT_DIR/aixray-$REPORT_HOST-$REPORT_DATE-$std.html"
      REPORT_TMP="$OUT_DIR/.aixray-$REPORT_HOST-$REPORT_DATE-$std.html.tmp.$$"
      # A pre-planted symlink at the predictable report name is refused up front (before
      # any mv could replace it) so a hostile link is never silently swapped for a real
      # report — the victim target stays untouched and the standard reports a failure.
      if (umask 077; set -C; render_compliance "$std" > "$REPORT_TMP") 2>/dev/null &&
         [ ! -d "$REPORT_FILE" ] &&
         [ ! -L "$REPORT_FILE" ] &&
         mv -f "$REPORT_TMP" "$REPORT_FILE" 2>/dev/null &&
         [ -f "$REPORT_FILE" ] &&
         [ ! -L "$REPORT_FILE" ]; then
        printf 'Report ready: %s\n' "$REPORT_FILE" >&2
      else
        rm -f "$REPORT_TMP"
        echo "ptxray: --out: cannot write report '$REPORT_FILE'" >&2
        REPORT_RC=1
      fi
      n=$((n+1))
    done
    if [ "$REPORT_RC" -eq 0 ]; then
      finish_report
    fi
    exit "$REPORT_RC"
  else
    # single standard writes to stdout — byte-identical to the pre-refactor path
    render_compliance "$COMPLIANCE_LIST"
    REPORT_RC=$?
    if [ "$REPORT_RC" -eq 0 ]; then
      finish_report
      exit 0
    fi
    exit "$REPORT_RC"
  fi
fi

function prepare_facts {
  # identity
  FACT_ID_UNREAD=""; FACT_ID_NA=""
  [ -z "$FACT_FRAME_SERIAL" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD frame_serial"
  [ -z "$FACT_PARTITION_ID" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD partition_id"
  [ -z "$FACT_PARTITION_NAME" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD partition_name"
  [ -z "$UC_MODEL" ] && FACT_ID_UNREAD="$FACT_ID_UNREAD machine_type"
  if [ -n "$FACT_ID_UNREAD" ]; then FACT_ID_BASIS=partial; else FACT_ID_BASIS=observed; fi

  # os
  FACT_OS_UNREAD=""; FACT_OS_NA=""
  [ -z "$OSLEVEL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD oslevel_s"
  [ -z "$REL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD release"
  [ -z "$FACT_OS_TL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD tl"
  [ -z "$FACT_OS_SP" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD sp"
  [ -z "$BWEEK" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD build_week"
  [ -z "$FACT_OS_EOS" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD eos_date"
  [ -z "$FACT_OS_EOSPS" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD eosps_date"
  [ -z "$UC_LATEST" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD tl_latest"
  case "$ROLE" in
    vios) [ -z "$UC_IOSL" ] && FACT_OS_UNREAD="$FACT_OS_UNREAD vios_level";;
    aix) FACT_OS_NA="$FACT_OS_NA vios_level";;
    *) FACT_OS_UNREAD="$FACT_OS_UNREAD vios_level";;
  esac
  FACT_OS_BASIS=observed
  if [ -n "$FACT_OS_UNREAD" ]; then
    FACT_OS_BASIS=partial
    if [ "$FACT_OS_SOURCE_READ" -eq 0 ]; then
      if [ "$ROLE" != vios ] || [ -z "$UC_IOSL" ]; then FACT_OS_BASIS=not_assessed; fi
    fi
  fi

  # firmware / hardware lifecycle
  FACT_FW_UNREAD=""; FACT_FW_NA=""
  [ -z "$UC_FW" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD level"
  [ -z "$UC_FWFAM" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD family"
  [ -z "$FACT_HW_GEN" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD hw_generation"
  [ -z "$FACT_HW_EOS" ] && FACT_FW_UNREAD="$FACT_FW_UNREAD hw_eos_date"
  case "$FACT_FW_UAK_EXPIRY" in
    '') FACT_FW_UNREAD="$FACT_FW_UNREAD firmware_uak_expiry";;
    NOT_APPLICABLE) FACT_FW_NA="$FACT_FW_NA firmware_uak_expiry";;
  esac
  case "$FACT_AIX_UAK_EXPIRY" in
    '') FACT_FW_UNREAD="$FACT_FW_UNREAD aix_uak_expiry";;
    NOT_APPLICABLE) FACT_FW_NA="$FACT_FW_NA aix_uak_expiry";;
  esac
  FACT_FW_BASIS=observed
  if [ -n "$FACT_FW_UNREAD" ]; then
    FACT_FW_BASIS=partial
    if [ -z "$UC_FW" ] && [ -z "$UC_FWFAM" ] && [ -z "$UC_MODEL" ]; then FACT_FW_BASIS=not_assessed; fi
  fi

  # capacity.cpu. Applicability is decided only after mode/capping is known.
  FACT_CPU_UNREAD=""; FACT_CPU_NA=""
  FACT_CPU_ENT_OUT="$FACT_CPU_ENT"; FACT_CPU_WEIGHT_OUT="$FACT_CPU_WEIGHT"; FACT_CPU_ENTC_OUT="$FACT_CPU_ENTC"
  [ -z "$FACT_CPU_MODE" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD mode"
  [ -z "$FACT_CPU_CAPPED" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD capped"
  if [ "$FACT_CPU_MODE" = dedicated ]; then
    FACT_CPU_ENT_OUT=""; FACT_CPU_WEIGHT_OUT=""; FACT_CPU_ENTC_OUT=""
    FACT_CPU_NA="$FACT_CPU_NA entitled_capacity variable_weight entc_pct"
  else
    [ -z "$FACT_CPU_ENT_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD entitled_capacity"
    if [ "$FACT_CPU_CAPPED" = true ]; then
      FACT_CPU_WEIGHT_OUT=""; FACT_CPU_NA="$FACT_CPU_NA variable_weight"
    else
      [ -z "$FACT_CPU_WEIGHT_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD variable_weight"
    fi
    [ -z "$FACT_CPU_ENTC_OUT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD entc_pct"
  fi
  [ -z "$FACT_CPU_OVP" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD online_vcpus"
  [ -z "$FACT_CPU_SMT" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD smt"
  [ -z "$FACT_CPU_PHYSC" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD physc"
  [ -z "$FACT_CPU_IDLE" ] && FACT_CPU_UNREAD="$FACT_CPU_UNREAD idle_pct"
  FACT_CPU_BASIS=observed
  if [ "$FACT_CPU_LPI_READ" -eq 0 ] && [ "$FACT_CPU_SAMPLE_READ" -eq 0 ]; then
    FACT_CPU_BASIS=not_assessed
  elif [ -n "$FACT_CPU_UNREAD" ]; then
    FACT_CPU_BASIS=partial
  fi

  # capacity.memory. svmon is the primary block read; when it is unavailable the
  # block is not assessed even if the independent vmstat percentages survived.
  FACT_MEM_UNREAD=""; FACT_MEM_NA=""
  [ -z "$FACT_MEM_TOTAL" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD total_mb"
  [ -z "$FACT_MEM_INUSE" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD inuse_mb"
  [ -z "$FACT_MEM_AVAILABLE" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD available_mb"
  [ -z "$FACT_MEM_PINNED" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD pinned_mb"
  [ -z "$FACT_MEM_COMP" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD computational_pct"
  [ -z "$FACT_MEM_NUMPERM" ] && FACT_MEM_UNREAD="$FACT_MEM_UNREAD numperm_pct"
  if [ "$FACT_MEM_PRIMARY_READ" -eq 0 ]; then
    FACT_MEM_BASIS=not_assessed
  elif [ -n "$FACT_MEM_UNREAD" ]; then
    FACT_MEM_BASIS=partial
  else
    FACT_MEM_BASIS=observed
  fi

  # capacity.paging
  FACT_PAGING_UNREAD=""; FACT_PAGING_NA=""
  [ -z "$FACT_PAGING_SPACES" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD spaces"
  [ -z "$FACT_PAGING_MAX" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD max_used_pct"
  [ -z "$FACT_PAGING_ROOT" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD all_in_rootvg"
  [ -z "$FACT_PAGING_DUP" ] && FACT_PAGING_UNREAD="$FACT_PAGING_UNREAD shares_pv"
  if [ "$FACT_PAGING_READ" -eq 0 ]; then
    FACT_PAGING_BASIS=not_assessed
  elif [ -n "$FACT_PAGING_UNREAD" ]; then
    FACT_PAGING_BASIS=partial
  else
    FACT_PAGING_BASIS=observed
  fi

  # capacity.storage
  FACT_STORAGE_UNREAD=""; FACT_STORAGE_NA=""
  if [ -z "$FACT_STORAGE_FS_ROWS" ]; then
    FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD filesystems worst_fs_used_pct worst_fs_mount max_inode_pct"
  else
    if [ -z "$FACT_STORAGE_WORST_FS_PCT" ] || [ -z "$FACT_STORAGE_WORST_FS_MOUNT" ]; then
      FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_fs_used_pct worst_fs_mount"
    fi
    [ -z "$FACT_STORAGE_MAX_INODE" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD max_inode_pct"
  fi
  [ -z "$FACT_STORAGE_WORST_VG_PCT" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_vg_free_pct"
  [ -z "$FACT_STORAGE_WORST_VG" ] && FACT_STORAGE_UNREAD="$FACT_STORAGE_UNREAD worst_vg"
  if [ "$FACT_STORAGE_DF_READ" -eq 0 ] && [ "$FACT_STORAGE_VG_READ" -eq 0 ]; then
    FACT_STORAGE_BASIS=not_assessed
  elif [ -n "$FACT_STORAGE_UNREAD" ]; then
    FACT_STORAGE_BASIS=partial
  else
    FACT_STORAGE_BASIS=observed
  fi

  # The capacity-level envelope is an aggregate only. Nulls are disclosed once,
  # in their owning nested block, never duplicated here.
  FACT_CAP_UNREAD=""; FACT_CAP_NA=""
  if [ "$FACT_CPU_BASIS" = not_assessed ] && [ "$FACT_MEM_BASIS" = not_assessed ] &&
     [ "$FACT_PAGING_BASIS" = not_assessed ] && [ "$FACT_STORAGE_BASIS" = not_assessed ]; then
    FACT_CAP_BASIS=not_assessed
  elif [ "$FACT_CPU_BASIS" != observed ] || [ "$FACT_MEM_BASIS" != observed ] ||
       [ "$FACT_PAGING_BASIS" != observed ] || [ "$FACT_STORAGE_BASIS" != observed ]; then
    FACT_CAP_BASIS=partial
  else
    FACT_CAP_BASIS=observed
  fi

  # recovery
  FACT_REC_UNREAD=""; FACT_REC_NA=""; FACT_REC_POWERHA_OUT="$FACT_RECOVERY_POWERHA"
  [ -z "$FACT_RECOVERY_ALT" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD alt_disk_present"
  [ -z "$FACT_RECOVERY_MIRROR" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD rootvg_mirror"
  [ -z "$FACT_RECOVERY_MIRROR_DISKS" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD rootvg_mirror_disks"
  [ -z "$FACT_RECOVERY_BOOTLIST" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD bootlist_devices"
  [ -z "$FACT_RECOVERY_NIM" ] && FACT_REC_UNREAD="$FACT_REC_UNREAD nim_client"
  if [ "$FACT_RECOVERY_POWERHA_APPLICABLE" = 0 ]; then
    FACT_REC_POWERHA_OUT=""; FACT_REC_NA="$FACT_REC_NA powerha_state"
  elif [ -z "$FACT_REC_POWERHA_OUT" ]; then
    FACT_REC_UNREAD="$FACT_REC_UNREAD powerha_state"
  fi
  if [ "$FACT_RECOVERY_MKSYSB" = unreadable ] || [ -n "$FACT_REC_UNREAD" ]; then
    FACT_REC_BASIS=partial
  else
    FACT_REC_BASIS=observed
  fi
}

function emit_fact_filesystems {
  if [ -z "$FACT_STORAGE_FS_ROWS" ]; then printf 'null'; return; fi
  printf '%s\n' "$FACT_STORAGE_FS_ROWS" | awk -F'\t' '
    function jescape(s){
      gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
      gsub(/[\001-\010\013\014\016-\037]/,"",s); return s
    }
    function jnum(v){return v=="?" ? "null" : v}
    BEGIN{printf "["}
    NF>=4{printf "%s{ \"mount\": \"%s\", \"size_mb\": %s, \"used_pct\": %s, \"iused_pct\": %s }",(n++?", ":""),jescape($1),$2,jnum($3),jnum($4)}
    END{printf "]"}'
}

if [ "$FORMAT" = "json" ]; then
  prepare_facts
  printf '{\n'
  printf '  "tool": "aixray",\n  "contract": "1.1",\n  "version": "%s",\n  "platform": "aix",\n  "role": "%s",\n' "$VERSION" "$ROLE"
  printf '  "host": "%s",\n  "generated": "%s",\n  "read_only": true,\n  "data_vintage": "%s",\n' \
         "$(printf '%s' "$HOST"|jesc)" "$(printf '%s' "$NOW"|jesc)" "$DATA_VINTAGE"
  printf '  "currency": '
  emit_currency_json
  printf ',\n'
  if [ "${FV_PROVENANCE_REAL:-0}" = 1 ]; then
    FV_META_AGE_JSON=null
    [ -n "$FLRTVC_DATA_AGE" ] && FV_META_AGE_JSON=$FLRTVC_DATA_AGE
    printf '  "flrtvc_data": { "source": "%s", "version": %s, "apar_csv_vintage": %s, "apar_csv_age_days": %s },\n' \
      "$(printf '%s' "$FLRTVC_DATA_SOURCE" | jesc)" \
      "$(jn "$FLRTVC_DATA_VERSION")" "$(jn "$FLRTVC_DATA_VINTAGE")" "$FV_META_AGE_JSON"
  fi
  printf '  "summary": { "pass": %d, "warn": %d, "fail": %d, "not_assessed": %d, "score_pct": %d, "banner": "%s", "message": "%s" },\n' \
         "$PASS" "$WARN" "$FAIL" "$NASSESSED" "$SCORE" "$BANNER" "$(printf '%s' "$BMSG"|jesc)"
  printf '  "categories": [\n'
  ci=0
  while [ "$ci" -lt 9 ]; do
    CT=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} ))
    if [ "$CT" -gt 0 ]; then CSC=$(( ${CP[$ci]} * 100 / CT )); else CSC=0; fi
    sep=','; [ "$ci" -eq 8 ] && sep=''
    printf '    { "id": "%s", "label": "%s", "pass": %d, "warn": %d, "fail": %d, "not_assessed": %d, "score_pct": %d, "status": "%s" }%s\n' \
           "${CAT_ID[$ci]}" "$(printf '%s' "${CAT_LBL[$ci]}"|jesc)" "${CP[$ci]}" "${CW[$ci]}" "${CF[$ci]}" "${CN[$ci]}" "$CSC" "$(cat_status $ci)" "$sep"
    ci=$((ci+1))
  done
  printf '  ],\n'
  printf '  "findings": [\n'
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    sep=','; [ "$i" -eq $((NFIND-1)) ] && sep=''
    if [ -z "${F_CTL[$i]}" ]; then
      CJ='[]'
    else
      CJ='['; cfirst=1
      for ctl in ${F_CTL[$i]}; do
        [ "$cfirst" -eq 1 ] && cfirst=0 || CJ="$CJ, "
        CJ="$CJ\"$ctl\""
      done
      CJ="$CJ]"
    fi
    # optional rules array — grouped rule-engine findings only (F_RULES non-empty)
    if [ -z "${F_RULES[$i]}" ]; then
      RSUF=""
    else
      RJ=$(printf '%s\n' "${F_RULES[$i]}" | awk -F'|' '
        function jescape(s){
          gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
          gsub(/\n/,"\\n",s); gsub(/[\001-\010\013\014\016-\037]/,"",s)
          return s
        }
        BEGIN{printf "["}
        NF>=3 && $1!=""{ printf "%s{ \"id\": \"%s\", \"status\": \"%s\", \"observed\": \"%s\" }", (n++?", ":""), jescape($1), jescape($2), jescape($3) }
        END{printf "]"}')
      RSUF=", \"rules\": $RJ"
    fi
    # optional exposures array — apar_scan only (F_EXPOSURES non-empty). Report-derived
    # fields (fileset names, bulletin URLs, apar/ifix labels) are external IBM text and
    # MUST be JSON-escaped like any ordinary finding — "these are tightly-structured
    # identifiers" is not itself a safety boundary (adversarial review round 3, item 5): a
    # stray quote/backslash/control byte here would previously have produced invalid or
    # injectable JSON. jescape() mirrors the shell jesc() helper exactly.
    if [ -z "${F_EXPOSURES[$i]}" ]; then
      EXPSUF=""
    else
      EJ=$(printf '%s\n' "${F_EXPOSURES[$i]}" | awk -F'\t' '
        function jescape(s){
          gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\t/,"\\t",s); gsub(/\r/,"\\r",s)
          gsub(/\n/,"\\n",s); gsub(/[\001-\010\013\014\016-\037]/,"",s)
          return s
        }
        # apars (field 7): semicolon-joined list of ALL non-CVE identifiers from the row
        # (never just the first — adversarial review round 3, item 4) — a JSON array, never
        # mislabeled a singular "apar" since many of these are ifix labels, not APAR
        # numbers, and IBM own compact report does not distinguish the two.
        function apars_json(s,  cnt,a,i,out){
          if(s=="")return "[]"
          cnt=split(s,a,";")
          out="["
          for(i=1;i<=cnt;i++) out=out (i>1?", ":"") "\"" jescape(a[i]) "\""
          return out "]"
        }
        BEGIN{printf "["}
        NF>=14{ printf "%s{ \"cve\": \"%s\", \"hiper\": %s, \"fileset\": \"%s\", \"installed\": \"%s\", \"vulnerable_range\": \"%s\", \"fixed_at_or_above\": %s, \"apars\": %s, \"ifix\": \"%s\", \"bulletin\": \"%s\", \"cvss\": %s, \"reboot\": \"%s\", \"abstract\": %s }", (n++?", ":""), jescape($1), ($2=="1"?"true":"false"), jescape($3), jescape($4), jescape($5), ($6==""?"null":"\"" jescape($6) "\""), apars_json($7), jescape($8), jescape($9), ($10==""?"null":$10), jescape($11), ($14==""?"null":"\"" jescape($14) "\"") }
        END{printf "]"}')
      EXPSUF=", \"exposures\": $EJ"
    fi
    # completion_state — apar_scan only, top-level on the finding block so the
    # report carries the shared completion-state model (§4) machine-readably.
    if [ -z "${F_COMPLETION[$i]}" ]; then
      COMPSUF=""
    else
      COMPSUF=", \"completion_state\": \"$(printf '%s' "${F_COMPLETION[$i]}" | jesc)\""
    fi
    if [ -z "${F_EVIDENCE_COMMANDS[$i]}" ]; then
      EVSUF=""
    else
      EVSUF=", \"evidence\": { \"source_commands\": $(jcmds "${F_EVIDENCE_COMMANDS[$i]}") }"
    fi
    if [ -z "${F_REASON[$i]}" ]; then
      PROJSUF=""
    else
      PROJSUF=", \"reason\": \"$(printf '%s' "${F_REASON[$i]}" | jesc)\""
      [ "${F_STALE[$i]}" -eq 1 ] && PROJSUF="$PROJSUF, \"stale\": true"
    fi
    CIS_ROWS=$(cis_l1_verdicts "$i")
    if [ -z "$CIS_ROWS" ]; then
      CISSUF=""
    else
      CISJ=$(printf '%s\n' "$CIS_ROWS" | awk -F'|' '
        BEGIN{printf "["}
        NF>=2{printf "%s{ \"control\": \"%s\", \"verdict\": \"%s\" }",(n++?", ":""),$1,$2}
        END{printf "]"}')
      CISSUF=", \"cis_l1\": $CISJ"
    fi
    printf '    { "id": "%s", "category": "%s", "label": "%s", "status": "%s", "severity": "%s", "observed": "%s", "meaning": "%s", "fix": "%s", "controls": %s%s%s%s%s%s%s }%s\n' \
      "$(printf '%s' "${F_ID[$i]}"|jesc)" "${F_CAT[$i]}" "$(printf '%s' "${F_LBL[$i]}"|jesc)" "${F_ST[$i]}" "${F_SEV[$i]}" \
      "$(printf '%s' "${F_OBS[$i]}"|jesc)" "$(printf '%s' "${F_MEAN[$i]}"|jesc)" "$(printf '%s' "${F_FIX[$i]}"|jesc)" "$CJ" "$RSUF" "$EXPSUF" "$COMPSUF" "$EVSUF" "$CISSUF" "$PROJSUF" "$sep"
    i=$((i+1))
  done
  printf '  ],\n'
  printf '  "facts": {\n'
  printf '    "identity": { "hostname": "%s", "frame_serial": %s, "partition_id": %s, "partition_name": %s, "machine_type": %s, "role": "%s", "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(printf '%s' "$HOST" | jesc)" "$(jn "$FACT_FRAME_SERIAL")" "$(jnum "$FACT_PARTITION_ID")" \
    "$(jn "$FACT_PARTITION_NAME")" "$(jn "$UC_MODEL")" "$ROLE" "$FACT_ID_BASIS" \
    "$(jlist "$FACT_ID_UNREAD")" "$(jlist "$FACT_ID_NA")"
  printf '    "os": { "oslevel_s": %s, "release": %s, "tl": %s, "sp": %s, "build_week": %s, "eos_date": %s, "eosps_date": %s, "tl_latest": %s, "vios_level": %s, "source_commands": { "oslevel_s": %s, "vios_role": %s, "vios_level": %s }, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$OSLEVEL")" "$(jn "$REL")" "$(jn "$FACT_OS_TL")" "$(jn "$FACT_OS_SP")" "$(jn "$BWEEK")" \
    "$(jn "$FACT_OS_EOS")" "$(jn "$FACT_OS_EOSPS")" "$(jn "$UC_LATEST")" "$(jn "$UC_IOSL")" \
    "$(jcmds "oslevel -s")" "$(jcmds "ls /usr/ios/cli/ioscli")" "$(jcmds "$FACT_OS_VIOS_COMMANDS")" \
    "$FACT_OS_BASIS" "$(jlist "$FACT_OS_UNREAD")" "$(jlist "$FACT_OS_NA")"
  printf '    "firmware": { "level": %s, "family": %s, "hw_generation": %s, "hw_eos_date": %s, "firmware_uak_expiry": %s, "aix_uak_expiry": %s, "source_commands": { "level": %s, "family": %s, "hw_eos_date": %s, "firmware_uak_expiry": %s, "aix_uak_expiry": %s }, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$UC_FW")" "$(jn "$UC_FWFAM")" "$(jn "$FACT_HW_GEN")" "$(jn "$FACT_HW_EOS")" "$(jn "$FACT_FW_UAK_EXPIRY")" "$(jn "$FACT_AIX_UAK_EXPIRY")" \
    "$(jcmds "lsmcode -c|prtconf")" "$(jcmds "prtconf")" "$(jcmds "prtconf")" "$(jcmds "$FACT_FW_UAK_COMMANDS")" "$(jcmds "$FACT_AIX_UAK_COMMANDS")" \
    "$FACT_FW_BASIS" "$(jlist "$FACT_FW_UNREAD")" "$(jlist "$FACT_FW_NA")"
  printf '    %s,\n' "$(emit_fact_software)"
  printf '    %s,\n' "$(emit_fact_adapter_microcode)"
  printf '    "capacity": {\n'
  printf '      "snapshot": true,\n'
  printf '      "cpu": { "mode": %s, "capped": %s, "entitled_capacity": %s, "online_vcpus": %s, "variable_weight": %s, "smt": %s, "physc": %s, "entc_pct": %s, "idle_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$FACT_CPU_MODE")" "$(jbool "$FACT_CPU_CAPPED")" "$(jnum "$FACT_CPU_ENT_OUT")" \
    "$(jnum "$FACT_CPU_OVP")" "$(jnum "$FACT_CPU_WEIGHT_OUT")" "$(jnum "$FACT_CPU_SMT")" \
    "$(jnum "$FACT_CPU_PHYSC")" "$(jnum "$FACT_CPU_ENTC_OUT")" "$(jnum "$FACT_CPU_IDLE")" \
    "$FACT_CPU_BASIS" "$(jlist "$FACT_CPU_UNREAD")" "$(jlist "$FACT_CPU_NA")"
  printf '      "memory": { "total_mb": %s, "inuse_mb": %s, "available_mb": %s, "pinned_mb": %s, "computational_pct": %s, "numperm_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jnum "$FACT_MEM_TOTAL")" "$(jnum "$FACT_MEM_INUSE")" "$(jnum "$FACT_MEM_AVAILABLE")" \
    "$(jnum "$FACT_MEM_PINNED")" "$(jnum "$FACT_MEM_COMP")" "$(jnum "$FACT_MEM_NUMPERM")" \
    "$FACT_MEM_BASIS" "$(jlist "$FACT_MEM_UNREAD")" "$(jlist "$FACT_MEM_NA")"
  printf '      "paging": { "spaces": %s, "max_used_pct": %s, "all_in_rootvg": %s, "shares_pv": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jnum "$FACT_PAGING_SPACES")" "$(jnum "$FACT_PAGING_MAX")" "$(jbool "$FACT_PAGING_ROOT")" \
    "$(jbool "$FACT_PAGING_DUP")" "$FACT_PAGING_BASIS" "$(jlist "$FACT_PAGING_UNREAD")" "$(jlist "$FACT_PAGING_NA")"
  printf '      "storage": { "filesystems": %s, "worst_fs_used_pct": %s, "worst_fs_mount": %s, "worst_vg_free_pct": %s, "worst_vg": %s, "max_inode_pct": %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(emit_fact_filesystems)" "$(jnum "$FACT_STORAGE_WORST_FS_PCT")" "$(jn "$FACT_STORAGE_WORST_FS_MOUNT")" \
    "$(jnum "$FACT_STORAGE_WORST_VG_PCT")" "$(jn "$FACT_STORAGE_WORST_VG")" "$(jnum "$FACT_STORAGE_MAX_INODE")" \
    "$FACT_STORAGE_BASIS" "$(jlist "$FACT_STORAGE_UNREAD")" "$(jlist "$FACT_STORAGE_NA")"
  printf '      "basis": "%s", "unreadable": %s, "not_applicable": %s\n' \
    "$FACT_CAP_BASIS" "$(jlist "$FACT_CAP_UNREAD")" "$(jlist "$FACT_CAP_NA")"
  printf '    },\n'
  printf '    %s,\n' "$(emit_fact_storage_layout)"
  FACT_ALT_DISK_RECOVERY=$(emit_fact_alt_disk_recoverability)
  case "$FACT_ALT_DISK_RECOVERY" in
    *'"basis":"partial"'*|*'"basis":"not_assessed"'*) FACT_REC_BASIS=partial;;
  esac
  printf '    "recovery": { "mksysb_evidence": %s, "alt_disk_present": %s, "rootvg_mirror": %s, "rootvg_mirror_disks": %s, "bootlist_devices": %s, "nim_client": %s, "powerha_state": %s, %s, "basis": "%s", "unreadable": %s, "not_applicable": %s },\n' \
    "$(jn "$FACT_RECOVERY_MKSYSB")" "$(jbool "$FACT_RECOVERY_ALT")" "$(jn "$FACT_RECOVERY_MIRROR")" \
    "$(jnum "$FACT_RECOVERY_MIRROR_DISKS")" "$(jnum "$FACT_RECOVERY_BOOTLIST")" "$(jbool "$FACT_RECOVERY_NIM")" \
    "$(jn "$FACT_REC_POWERHA_OUT")" "$FACT_ALT_DISK_RECOVERY" "$FACT_REC_BASIS" \
    "$(jlist "$FACT_REC_UNREAD")" "$(jlist "$FACT_REC_NA")"
  printf '    %s\n' "$(emit_fact_network_inventory)"
  printf '  },\n'
  # upgrade_readiness — on-box facts for Blueprint's stepped upgrade-path sequencing (current
  # OS/TL, firmware, VIOS, machine type). The full OS x firmware x VIOS x HMC COMPATIBILITY
  # MATRIX is FLRT web-service output, not derivable on-box or from apar.csv — this block
  # captures current levels only and says so explicitly; it never invents the matrix.
  printf '  "upgrade_readiness": {\n'
  printf '    "current": { "os_release": %s, "os_tl_sp": %s, "latest_tl_for_release": %s, "role": "%s", "vios_level": %s, "firmware_level": %s, "firmware_family": %s, "machine_type_model": %s },\n' \
    "$(jn "$OSLEVEL")" "$(jn "$TLLEVEL")" "$(jn "$UC_LATEST")" "$ROLE" "$(jn "$UC_IOSL")" "$(jn "$UC_FW")" "$(jn "$UC_FWFAM")" "$(jn "$UC_MODEL")"
  printf '    "recommended_upgrade_path": %s,\n' "$(jn "$UC_UPGTEXT")"
  printf '    "hmc": { "observable_from_lpar": false, "note": "HMC firmware level and managed-system settings need HMC access; this tool runs inside the LPAR and cannot see the HMC." },\n'
  printf '    "flrt_compat_matrix": { "derivable_on_box": false, "note": "The full OS x firmware x VIOS x HMC cross-product compatibility matrix is IBM FLRT web-service output, not on-box data or apar.csv content -- this block captures only the levels observable from inside this LPAR; submit them to the FLRT web tool for the compatibility matrix.", "web_tool": "h''ttps://esupport.ibm.com/customercare/flrt/sas?page=../jsp/flrtos.jsp" }\n'
  printf '  }\n}\n'
  REPORT_RC=$?
  if [ "$REPORT_RC" -eq 0 ]; then
    finish_report
    exit 0
  fi
  exit "$REPORT_RC"
fi

# ---- HTML ------------------------------------------------------------------------------
# role-aware framing: a VIOS report should read as a VIOS report, not a generic LPAR one.
if [ "$IS_VIOS" -eq 1 ]; then
  SNAP_EY="Virtual I/O Server health check"; SNAP_H1="VIOS posture snapshot"
else
  SNAP_EY="System Health Check"; SNAP_H1="Posture snapshot"
fi

# C2: surface the full CVSS ladder ahead of category detail. This native v1
# path has no KEV-feed input, so Known-Exploited is explicitly NOT ASSESSED;
# the Contract-v2 report fills that tier when an-flrtvc receives --kev-json.
CVSS_APAR_INDEX=-1
i=0
while [ "$i" -lt "$NFIND" ]; do
  [ "${F_ID[$i]}" = "apar_scan" ] && { CVSS_APAR_INDEX=$i; break; }
  i=$((i+1))
done
if [ "$CVSS_APAR_INDEX" -lt 0 ] || [ "${F_ST[$CVSS_APAR_INDEX]}" = "NOT_ASSESSED" ]; then
  if [ "$CVSS_APAR_INDEX" -ge 0 ]; then
    CVSS_NA_REASON=$(printf '%s' "${F_OBS[$CVSS_APAR_INDEX]}" | hesc)
  else
    CVSS_NA_REASON="FLRTVC evidence was not present in this run"
  fi
  CVSSBLOCK="<section id=\"cvss-ladder\" class=\"cvss\"><div class=\"cathead\"><span class=\"cl\">CVE exposure ladder</span></div><div class=\"cov\"><b>NOT ASSESSED</b> — <span data-aixray-field=\"observed\" data-aixray-location=\"finding:apar_scan:observed\">$CVSS_NA_REASON</span>. <span data-aixray-field=\"authored\" data-aixray-copy-id=\"native:cvss-uncompleted-v1\">No zero counts are inferred from an uncompleted run.</span></div></section>"
else
  CVSS_DATA=${F_EXPOSURES[$CVSS_APAR_INDEX]}
  CVSS_NUMERIC_ROWS=$(printf '%s\n' "$CVSS_DATA" | awk -F'\t' '
    function he(s){gsub(/&/,"\\&amp;",s);gsub(/</,"\\&lt;",s);gsub(/>/,"\\&gt;",s);return s}
    function add(t,s){items[t]=items[t] (items[t]!=""?"<br>":"") s; count[t]++}
    NF>=13 {
      score=$10
      if($12!="1")t="Unscored"
      else if(score=="" || score+0==0)t="None"
      else if(score+0>=9)t="Critical"
      else if(score+0>=7)t="High"
      else if(score+0>=4)t="Medium"
      else t="Low"
      ident=$1; if(ident=="")ident=$7; if(ident=="")ident=$3
      detail=he(ident) " — " he($3) " " he($4)
      if($12!="1")detail=detail " · CVSS NOT ASSESSED"
      else if(score!="")detail=detail " · CVSS " he(score)
      else detail=detail " · CVSS none"
      if($2=="1")detail=detail " · HIPER"
      if($6!="")detail=detail " · fixed at/above " he($6)
      if($9!="")detail=detail " · bulletin " he($9)
      add(t,detail)
    }
    END {
      order[1]="Critical";order[2]="High";order[3]="Medium";order[4]="Low";order[5]="None";order[6]="Unscored"
      for(i=1;i<=6;i++){
        t=order[i]; detail=items[t]; if(detail=="")detail="—"
        printf "<tr data-tier=\"%s\" data-count=\"%d\"><td class=\"ctl\" data-aixray-field=\"technical\" data-aixray-location=\"report:cvss-tier\">%s</td><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"report:cvss-count\">%d</td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"finding:apar_scan:exposures\">%s</td></tr>",t,count[t]+0,t,count[t]+0,detail
      }
    }
  ')
  CVSS_NOTE=""
  [ "${F_ST[$CVSS_APAR_INDEX]}" = "WARN" ] && CVSS_NOTE="<div class=\"cov\" data-aixray-container=\"fields\"><b data-aixray-field=\"authored\" data-aixray-copy-id=\"native:cvss-currency-label-v1\">Currency warning.</b> <span data-aixray-field=\"observed\" data-aixray-location=\"finding:apar_scan:observed\">$(printf '%s' "${F_OBS[$CVSS_APAR_INDEX]}" | hesc)</span></div>"
  CVSS_INCOMPLETE_ROWS=$(printf '%s\n' "$CVSS_DATA" | awk -F'\t' 'NF>=13 && $13!="1"{n++} END{print n+0}')
  if [ "$CVSS_INCOMPLETE_ROWS" -gt 0 ]; then
    CVSS_NOTE="$CVSS_NOTE<div class=\"cov\" data-aixray-container=\"fields\"><b data-aixray-field=\"authored\" data-aixray-copy-id=\"native:cvss-incomplete-label-v1\">Incomplete CVSS evidence.</b> <span data-aixray-field=\"technical\" data-aixray-location=\"report:cvss-incomplete-count\">$CVSS_INCOMPLETE_ROWS</span><span data-aixray-field=\"authored\" data-aixray-copy-id=\"native:cvss-incomplete-detail-v1\"> exposure record(s) came from a row whose CVSS field was incomplete or malformed. Recovered scores remain listed; unscored CVEs are NOT ASSESSED and are not guessed into the None tier.</span></div>"
  fi
  CVSSBLOCK="<section id=\"cvss-ladder\" class=\"cvss\"><div class=\"cathead\"><span class=\"cl\">CVE exposure ladder</span><span class=\"cr\"><span class=\"cnt\">worst first · every exposure listed</span></span></div>$CVSS_NOTE<table><thead><tr><th>Tier</th><th>Count</th><th>Actual CVE / exposure list</th></tr></thead><tbody><tr data-tier=\"Known-Exploited\"><td class=\"ctl\" data-aixray-field=\"technical\" data-aixray-location=\"report:kev-tier\">Known-Exploited</td><td class=\"obs\" data-aixray-field=\"technical\" data-aixray-location=\"report:kev-status\">NOT ASSESSED</td><td class=\"obs\" data-aixray-field=\"authored\" data-aixray-copy-id=\"native:kev-not-supplied-v1\">No dated KEV feed was supplied to this native report path; zero is not assumed.</td></tr>$CVSS_NUMERIC_ROWS</tbody></table></section>"
fi

# Complete, uncapped action inventory. CVE tier is read only from recovered
# FLRT exposure rows; an absent score/row stays absent rather than being
# guessed. The native report has no KEV input, disclosed in the ladder below.
function action_cve_tier { # <finding-index> -> tier or empty
  typeset ACTION_INDEX
  ACTION_INDEX=$1
  [ -n "${F_EXPOSURES[$ACTION_INDEX]}" ] || return 0
  printf '%s\n' "${F_EXPOSURES[$ACTION_INDEX]}" | awk -F'\t' '
    NF>=13 {
      rows++
      if($2=="1") hiper=1
      if($12!="1") unscored++
      else if($10!="") {
        score=$10+0
        if(!have || score>max){max=score;have=1}
      } else assessed_none=1
    }
    END {
      if(!rows) exit
      if(hiper){printf "Critical / HIPER";exit}
      if(max>=9){printf "Critical";exit}
      if(unscored)exit
      if(!have || max==0){printf "None";exit}
      if(max>=7){printf "High";exit}
      if(max>=4){printf "Medium";exit}
      printf "Low"
    }
  '
}

function action_priority { # <finding-index> <cve-tier> -> numeric sort bucket
  typeset ACTION_INDEX ACTION_TIER ACTION_STATUS ACTION_SEVERITY
  ACTION_INDEX=$1; ACTION_TIER=$2
  ACTION_STATUS=${F_ST[$ACTION_INDEX]}; ACTION_SEVERITY=${F_SEV[$ACTION_INDEX]}
  case "$ACTION_TIER" in Critical*) echo 1; return;; esac
  case "$ACTION_STATUS:$ACTION_SEVERITY" in
    FAIL:critical|FAIL:high) echo 2;;
    FAIL:med|FAIL:medium) echo 3;;
    FAIL:low) echo 4;;
    WARN:critical|WARN:high) echo 5;;
    WARN:med|WARN:medium) echo 6;;
    WARN:low) echo 7;;
    *) echo 8;;
  esac
}

function cve_tier_rank { # <cve-tier> -> numeric sort rank, lower ranks first (0 = worst)
  typeset CTR_TIER
  CTR_TIER=$1
  case "$CTR_TIER" in
    "Critical / HIPER") echo 0;;
    "Critical") echo 1;;
    "High") echo 2;;
    "Medium") echo 3;;
    "Low") echo 4;;
    *) echo 5;;
  esac
}

function framework_corroboration { # <finding-index> -> count of DISTINCT framework prefixes
  typeset FC_IDX FC_TOK FC_PFX FC_SEEN FC_N
  FC_IDX=$1
  FC_SEEN=" "
  FC_N=0
  for FC_TOK in ${F_CTL[$FC_IDX]}; do
    FC_PFX=${FC_TOK%%:*}
    case "$FC_SEEN" in
      *" $FC_PFX "*) : ;;
      *) FC_SEEN="$FC_SEEN$FC_PFX "; FC_N=$((FC_N+1));;
    esac
  done
  echo "$FC_N"
}

function selected_in_category { # <category> <selected finding indices> -> how many selected
  typeset SIC_CAT SIC_LIST SIC_IDX SIC_N
  SIC_CAT=$1; SIC_LIST=$2; SIC_N=0
  for SIC_IDX in $SIC_LIST; do
    [ "${F_CAT[$SIC_IDX]}" = "$SIC_CAT" ] && SIC_N=$((SIC_N+1))
  done
  echo "$SIC_N"
}

ACTION_ROWS=""
ACTION_COUNT=0
ACTION_PRIORITY=1
while [ "$ACTION_PRIORITY" -le 8 ]; do
  i=0
  while [ "$i" -lt "$NFIND" ]; do
    ACTION_STATUS=${F_ST[$i]}
    if [ "$ACTION_STATUS" = "FAIL" ] || [ "$ACTION_STATUS" = "WARN" ]; then
      ACTION_TIER=$(action_cve_tier "$i")
      ACTION_FINDING_PRIORITY=$(action_priority "$i" "$ACTION_TIER")
      if [ "$ACTION_FINDING_PRIORITY" -eq "$ACTION_PRIORITY" ]; then
        ACTION_COUNT=$((ACTION_COUNT+1))
        ACTION_ID_H=$(printf '%s' "${F_ID[$i]}" | attr_hesc)
        ACTION_LABEL_H=$(printf '%s' "${F_LBL[$i]}" | hesc)
        ACTION_OBS_H=$(printf '%s' "${F_OBS[$i]}" | hesc)
        ACTION_TIER_H=$(printf '%s' "$ACTION_TIER" | hesc)
        [ -n "$ACTION_TIER_H" ] || ACTION_TIER_H='—'
        ACTION_ROWS="$ACTION_ROWS<tr class=\"$ACTION_STATUS\" data-action-index=\"$i\" data-finding-id=\"$ACTION_ID_H\" data-aixray-finding-id=\"$ACTION_ID_H\" data-priority=\"$ACTION_PRIORITY\"><td class=\"action-priority\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$ACTION_ID_H:action-priority\">$ACTION_COUNT</td><td class=\"ctl\" data-aixray-container=\"fields\"><span $(finding_label_privacy_attrs "${F_ID[$i]}")>$ACTION_LABEL_H</span><div class=\"action-id\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$ACTION_ID_H:action-label\">$(printf '%s' "${F_ID[$i]}" | hesc) — $ACTION_STATUS</div></td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$ACTION_ID_H:observed\">$ACTION_OBS_H</td><td class=\"sev\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$ACTION_ID_H:severity\">${F_SEV[$i]}</td><td class=\"cis\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$ACTION_ID_H:cis\">$(cis_l1_html "$i")</td><td class=\"action-tier\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$ACTION_ID_H:cve-tier\">$ACTION_TIER_H</td></tr>"
      fi
    fi
    i=$((i+1))
  done
  ACTION_PRIORITY=$((ACTION_PRIORITY+1))
done

if [ "$ACTION_COUNT" -eq 0 ]; then
  ACTION_ROWS='<tr class="none"><td colspan="6" data-aixray-field="authored" data-aixray-copy-id="native:no-action-findings-v1">No FAIL/WARN findings were emitted in this run.</td></tr>'
fi
ACTIONBLOCK="<section id=\"remediation-actions\" class=\"actions\"><div class=\"cathead\"><span class=\"cl\">Remediation Action List</span><span class=\"cr\"><span class=\"cnt\">$ACTION_COUNT action(s) · complete · worst first</span></span></div><div class=\"cov\" data-aixray-field=\"authored\" data-aixray-copy-id=\"native:action-order-v1\">Work from top to bottom. Every FAIL and WARN is its own line; PASS and NOT_ASSESSED findings remain summarized in the detail below.</div><table><thead><tr><th>Priority</th><th>Finding</th><th>Observed evidence</th><th>Severity</th><th>CIS L1 check</th><th>CVE tier</th></tr></thead><tbody>$ACTION_ROWS</tbody></table></section>"

CATBLOCKS=""
ci=0
while [ "$ci" -lt 9 ]; do
  CT=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} + ${CN[$ci]} + ${CNA[$ci]} ))
  if [ "$CT" -gt 0 ]; then
    CST=$(cat_status $ci)
    NACNT=""; [ "${CN[$ci]}" -gt 0 ] && NACNT=" · ${CN[$ci]} not assessed"
    NAPPCNT=""; [ "${CNA[$ci]}" -gt 0 ] && NAPPCNT=" · ${CNA[$ci]} n/a"
    CATBLOCKS="$CATBLOCKS<div class=\"cathead\"><span class=\"cl\">$(printf '%s' "${CAT_LBL[$ci]}"|hesc)</span><span class=\"cr\"><span class=\"chip $CST\">$CST</span> <span class=\"cnt\">${CP[$ci]} pass · ${CW[$ci]} warn · ${CF[$ci]} fail${NACNT}${NAPPCNT}</span></span></div>"
    CATBLOCKS="$CATBLOCKS<table><thead><tr><th>Check</th><th>Status</th><th>Sev</th><th>CIS L1 check</th><th>Observed</th><th>What it means</th></tr></thead><tbody>"
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      if [ "${F_CAT[$i]}" = "${CAT_ID[$ci]}" ]; then
        st="${F_ST[$i]}"
        finding_h=$(printf '%s' "${F_ID[$i]}" | attr_hesc)
        CATBLOCKS="$CATBLOCKS<tr class=\"$st\" data-aixray-finding-id=\"$finding_h\"><td class=\"ctl\" $(finding_label_privacy_attrs "${F_ID[$i]}")>$(printf '%s' "${F_LBL[$i]}"|hesc)</td><td class=\"st $st\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:status\">$st</td>"
        CATBLOCKS="$CATBLOCKS<td class=\"sev\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:severity\">${F_SEV[$i]}</td><td class=\"cis\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$finding_h:cis\">$(cis_l1_html "$i")</td><td class=\"obs\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$finding_h:observed\">$(printf '%s' "${F_OBS[$i]}"|hesc)</td>"
        CATBLOCKS="$CATBLOCKS<td data-aixray-container=\"fields\">$(finding_guidance_privacy_html "${F_ID[$i]}" "${F_MEAN[$i]}")</td></tr>"
      fi
      i=$((i+1))
    done
    CATBLOCKS="$CATBLOCKS</tbody></table>"
    if [ "${CF[$ci]}" -gt 0 ] || [ "${CW[$ci]}" -gt 0 ]; then
      CATBLOCKS="$CATBLOCKS$MITIGATE_CTA"
    fi
  fi
  ci=$((ci+1))
done

START_HERE_ITEMS=""
START_HERE_NOTE=""
TOP_RISK_COUNT=0
TR_TAB=$(printf '\t')
TR_SELECTED=""
for TOP_RISK_STATUS in FAIL WARN; do
  [ "$TOP_RISK_COUNT" -ge 5 ] && break
  for TOP_RISK_SEVERITY in high med low; do
    [ "$TOP_RISK_COUNT" -ge 5 ] && break
    # Collect the bucket's candidates into a sortable record. The record keeps
    # ONLY the sort keys plus the finding index; observed text stays out of the
    # sort so arbitrary characters cannot corrupt it. Keys are fixed-width so a
    # plain lexical sort is correct: tier rank (0 worst .. 5), then 100 minus
    # the corroboration count (descending count = ascending key), then the
    # finding id. The id tie-break is deliberately arbitrary — it exists only
    # to make the output deterministic, not as a risk judgement.
    TR_SORTED=""
    i=0
    while [ "$i" -lt "$NFIND" ]; do
      if [ "${F_ST[$i]}" = "$TOP_RISK_STATUS" ] && \
         [ "${F_SEV[$i]}" = "$TOP_RISK_SEVERITY" ]; then
        TR_TIER=$(action_cve_tier "$i")
        TR_TIER_RANK=$(cve_tier_rank "$TR_TIER")
        TR_CORR=$(framework_corroboration "$i")
        TR_CKEY=$((100 - TR_CORR))
        case "$TR_CKEY" in
          ???) : ;;
          ??) TR_CKEY="0$TR_CKEY" ;;
          ?) TR_CKEY="00$TR_CKEY" ;;
        esac
        TR_SORTED="$TR_SORTED${TR_TIER_RANK}${TR_TAB}${TR_CKEY}${TR_TAB}${F_ID[$i]}${TR_TAB}${i}\n"
      fi
      i=$((i+1))
    done
    [ -z "$TR_SORTED" ] && continue
    TR_SORTED=$(printf '%b' "$TR_SORTED" | sort)
    set -A TR_RANK; set -A TR_CKEY; set -A TR_RID; set -A TR_RIDX
    TR_RN=0
    while IFS="$TR_TAB" read -r TR_V_RANK TR_V_CKEY TR_V_ID TR_V_IDX; do
      TR_RANK[$TR_RN]=$TR_V_RANK
      TR_CKEY[$TR_RN]=$TR_V_CKEY
      TR_RID[$TR_RN]=$TR_V_ID
      TR_RIDX[$TR_RN]=$TR_V_IDX
      TR_RN=$((TR_RN+1))
    done <<AIXRAY_TR_EOF
$TR_SORTED
AIXRAY_TR_EOF
    # Two passes over the same bucket, same order. Pass 1 caps a category at
    # two entries so one condition or one control family cannot consume all
    # five slots; pass 2 relaxes the cap so a lower-severity finding is never
    # chosen ahead of a higher-severity one just because the cap filled up.
    TR_PASS=1
    while [ "$TR_PASS" -le 2 ]; do
      j=0
      while [ "$j" -lt "$TR_RN" ] && [ "$TOP_RISK_COUNT" -lt 5 ]; do
        TR_IDX=${TR_RIDX[$j]}
        case " $TR_SELECTED " in
          *" $TR_IDX "*) j=$((j+1)); continue ;;
        esac
        if [ "$TR_PASS" -eq 2 ] || \
           [ "$(selected_in_category "${F_CAT[$TR_IDX]}" "$TR_SELECTED")" -lt 2 ]; then
          TOP_RISK_LABEL=$(printf '%s' "${F_LBL[$TR_IDX]}" | hesc)
          TOP_RISK_OBSERVED=$(printf '%s' "${F_OBS[$TR_IDX]}" | hesc)
          TOP_RISK_ID_H=$(printf '%s' "${F_ID[$TR_IDX]}" | attr_hesc)
          START_HERE_ITEMS="$START_HERE_ITEMS<li class=\"top-risk $TOP_RISK_STATUS\" data-severity=\"$TOP_RISK_SEVERITY\" data-aixray-finding-id=\"$TOP_RISK_ID_H\"><div class=\"top-risk-head\"><span class=\"top-risk-label\" $(finding_label_privacy_attrs "${F_ID[$TR_IDX]}")>$TOP_RISK_LABEL</span><span class=\"top-risk-rank\" data-aixray-field=\"technical\" data-aixray-location=\"finding:$TOP_RISK_ID_H:top-risk-rank\">$TOP_RISK_STATUS · $TOP_RISK_SEVERITY</span></div><div class=\"top-risk-observed\" data-aixray-field=\"observed\" data-aixray-location=\"finding:$TOP_RISK_ID_H:top-risk-observed\"><b>Observed:</b> $TOP_RISK_OBSERVED</div></li>"
          TR_SELECTED="$TR_SELECTED $TR_IDX "
          TOP_RISK_COUNT=$((TOP_RISK_COUNT+1))
        fi
        j=$((j+1))
      done
      TR_PASS=$((TR_PASS+1))
    done
  done
done
[ "$TOP_RISK_COUNT" -eq 0 ] && START_HERE_NOTE='<p class="start-here-none" data-aixray-field="authored" data-aixray-copy-id="native:no-actionable-findings-v1">No actionable FAIL or WARN finding was identified. Inspect every NOT_ASSESSED gap before treating this report as clear.</p>'
# ---- executive summary: per-area breakdown bars (CAT_ID) ----------------------------------
EXEC_SUMMARY=""
EXEC_SUMMARY_NOTE=""
EXEC_TOTAL_PASS=0; EXEC_TOTAL_ASSESSED=0; EXEC_TOTAL_NA=0; EXEC_TOTAL_NAPP=0
ci=0
while [ "$ci" -lt 9 ]; do
  EXEC_CT=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} + ${CN[$ci]} + ${CNA[$ci]} ))
  if [ "$EXEC_CT" -gt 0 ]; then
    EXEC_ASSESSED=$(( ${CP[$ci]} + ${CW[$ci]} + ${CF[$ci]} ))
    EXEC_TOTAL_PASS=$(( EXEC_TOTAL_PASS + ${CP[$ci]} ))
    EXEC_TOTAL_ASSESSED=$(( EXEC_TOTAL_ASSESSED + EXEC_ASSESSED ))
    EXEC_TOTAL_NA=$(( EXEC_TOTAL_NA + ${CN[$ci]} ))
    EXEC_TOTAL_NAPP=$(( EXEC_TOTAL_NAPP + ${CNA[$ci]} ))

    if   [ "${CF[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="fail"
    elif [ "${CW[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="warn"
    elif [ "${CN[$ci]}" -gt 0 ]; then EXEC_BAR_CLASS="warn"
    else EXEC_BAR_CLASS="pass"; fi

    EXEC_DEN=$(( EXEC_ASSESSED + ${CN[$ci]} + ${CNA[$ci]} ))
    if [ "$EXEC_DEN" -gt 0 ]; then
      EXEC_FAIL_PCT=$(( ${CF[$ci]} * 100 / EXEC_DEN ))
      EXEC_WARN_PCT=$(( ${CW[$ci]} * 100 / EXEC_DEN ))
      EXEC_NA_PCT=$(( ${CN[$ci]} * 100 / EXEC_DEN ))
      EXEC_NAPP_PCT=$(( ${CNA[$ci]} * 100 / EXEC_DEN ))
      EXEC_PASS_PCT=$(( 100 - EXEC_FAIL_PCT - EXEC_WARN_PCT - EXEC_NA_PCT - EXEC_NAPP_PCT ))
    else
      EXEC_PASS_PCT=0; EXEC_FAIL_PCT=0; EXEC_WARN_PCT=0; EXEC_NA_PCT=0; EXEC_NAPP_PCT=0
    fi

    EXEC_METER=""
    [ "$EXEC_PASS_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill pass\" style=\"width:${EXEC_PASS_PCT}%\"></span>"
    [ "$EXEC_FAIL_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill fail\" style=\"width:${EXEC_FAIL_PCT}%\"></span>"
    [ "$EXEC_WARN_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill warn\" style=\"width:${EXEC_WARN_PCT}%\"></span>"
    [ "$EXEC_NA_PCT"  -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill na\" style=\"width:${EXEC_NA_PCT}%\"></span>"
    [ "$EXEC_NAPP_PCT" -gt 0 ] && EXEC_METER="$EXEC_METER<span class=\"area-meter-fill napp\" style=\"width:${EXEC_NAPP_PCT}%\"></span>"

    EXEC_LABEL="${CP[$ci]} of ${EXEC_ASSESSED} pass"
    [ "${CF[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"fail-count\">${CF[$ci]} fail</span>"
    [ "${CW[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"warn-count\">${CW[$ci]} warn</span>"
    [ "${CN[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"na-count\">${CN[$ci]} not assessed</span>"
    [ "${CNA[$ci]}" -gt 0 ] && EXEC_LABEL="$EXEC_LABEL · <span class=\"napp-count\">${CNA[$ci]} n/a</span>"

    EXEC_SUMMARY="$EXEC_SUMMARY<div class=\"area-bar ${EXEC_BAR_CLASS}\" data-aixray-container=\"fields\"><span class=\"area-label\" data-aixray-field=\"authored\" data-aixray-copy-id=\"finding-label:cat-${CAT_ID[$ci]}:v1\">$(printf '%s' "${CAT_LBL[$ci]}"|hesc)</span><span class=\"area-meter\">${EXEC_METER}</span><span class=\"area-count\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-area-count:${CAT_ID[$ci]}\">${EXEC_LABEL}</span></div>"
  else
    EXEC_SUMMARY="$EXEC_SUMMARY<div class=\"area-bar na\" data-aixray-container=\"fields\"><span class=\"area-label\" data-aixray-field=\"authored\" data-aixray-copy-id=\"finding-label:cat-${CAT_ID[$ci]}:v1\">$(printf '%s' "${CAT_LBL[$ci]}"|hesc)</span><span class=\"area-meter\"><span class=\"area-meter-fill na\" style=\"width:100%\"></span></span><span class=\"area-count\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-area-count:${CAT_ID[$ci]}\">no findings emitted</span></div>"
  fi
  ci=$((ci+1))
done

if [ "$EXEC_TOTAL_ASSESSED" -gt 0 ]; then
  EXEC_OVERALL_PCT=$(( EXEC_TOTAL_PASS * 100 / EXEC_TOTAL_ASSESSED ))
  EXEC_NA_NOTE=""
  [ "$EXEC_TOTAL_NA" -gt 0 ] && EXEC_NA_NOTE=" <span class=\"na-note\">· ${EXEC_TOTAL_NA} not assessed</span>"
  EXEC_NAPP_NOTE=""
  [ "$EXEC_TOTAL_NAPP" -gt 0 ] && EXEC_NAPP_NOTE=" <span class=\"napp-note\">· ${EXEC_TOTAL_NAPP} n/a</span>"
  EXEC_TOTAL_FINDINGS=$(( EXEC_TOTAL_ASSESSED + EXEC_TOTAL_NA + EXEC_TOTAL_NAPP ))
  EXEC_TOTAL_NOTE=""
  [ "$EXEC_TOTAL_FINDINGS" -gt 0 ] && EXEC_TOTAL_NOTE=" — ${EXEC_TOTAL_FINDINGS} findings in total, every one listed in the detail below."
  EXEC_SUMMARY_NOTE="<p class=\"exec-summary-note\" data-aixray-field=\"technical\" data-aixray-location=\"report:exec-overall\">Overall: <b>${EXEC_TOTAL_PASS} of ${EXEC_TOTAL_ASSESSED} assessed checks passed</b> (${EXEC_OVERALL_PCT}%).${EXEC_NA_NOTE}${EXEC_NAPP_NOTE}${EXEC_TOTAL_NOTE} Not-assessed counts appear as the solid grey segment; not-applicable counts appear as the outlined pale segment. Absent segments mean zero.</p>"
fi

function emit_html_report {
cat <<HTML
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="aixray-report-version" content="1">
<meta name="aixray-privacy-schema" content="1">
<meta name="aixray-report-date" content="${REPORT_DATE}">
<meta name="aixray-report-host" content="${HOST_ATTR}">
<title>PTxray — ${HOST_H}</title>
<style>
@font-face{font-family:'Plex Sans';src:url(data:font/woff2;base64,${report_font_plex_sans_variable_b64}) format('woff2');font-weight:300 700;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_semibold_b64}) format('woff2');font-weight:600;font-display:swap}
@font-face{font-family:'Plex Serif';src:url(data:font/woff2;base64,${report_font_plex_serif_medium_b64}) format('woff2');font-weight:500;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_regular_b64}) format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Plex Mono';src:url(data:font/woff2;base64,${report_font_plex_mono_medium_b64}) format('woff2');font-weight:500;font-display:swap}
:root{
  --slate:#1B1F24; --slate2:#23272E; --slate3:#2B3038;
  --ink:#23272E; --body:#5C5F63; --mute:#8A929B;
  --cream:#F4F2EE; --line:#E2DDD5; --bg:#ffffff;
  --copper:#C2703D; --copper-d:#A85A2C; --copper-l:#D98A5A;
  --red:#B23A2C; --amber:#A9781A; --green:#2E7D52; --na:#8A929B;
  --red-t:#f7ece9; --amber-t:#f7f1e6; --green-t:#eef4ef; --na-t:#f1f1ef;
  --sans:'Plex Sans',-apple-system,system-ui,sans-serif;
  --serif:'Plex Serif',Georgia,serif;
  --mono:'Plex Mono',ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme:dark){:root{
  --slate:#0e1114; --slate2:#161a1f; --slate3:#1e242b; --ink:#eef0f2; --body:#b7bcc2; --mute:#8A929B;
  --cream:#191d22; --line:#2a3037; --bg:#111418;
  --red:#d6584a; --amber:#c99436; --green:#46a578; --na:#8a929b;
  --red-t:#20140f; --amber-t:#1f1810; --green-t:#0f1e16; --na-t:#181b1f;
}}
:root[data-theme="dark"]{--slate:#0e1114;--slate2:#161a1f;--slate3:#1e242b;--ink:#eef0f2;--body:#b7bcc2;--mute:#8A929B;--cream:#191d22;--line:#2a3037;--bg:#111418;--red:#d6584a;--amber:#c99436;--green:#46a578;--na:#8a929b;--red-t:#20140f;--amber-t:#1f1810;--green-t:#0f1e16;--na-t:#181b1f}
:root[data-theme="light"]{--slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;--ink:#23272E;--body:#5C5F63;--mute:#8A929B;--cream:#F4F2EE;--line:#E2DDD5;--bg:#ffffff;--red:#B23A2C;--amber:#A9781A;--green:#2E7D52;--na:#8A929B;--red-t:#f7ece9;--amber-t:#f7f1e6;--green-t:#eef4ef;--na-t:#f1f1ef}

*{box-sizing:border-box;border-radius:0}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{margin:0;background:var(--bg);color:var(--body);font-family:var(--sans);font-size:13.5px;line-height:1.55;-webkit-font-smoothing:antialiased;max-width:940px;margin-inline:auto}
b{color:var(--ink);font-weight:600}

.band{position:relative;background:var(--slate);color:#fff;padding:32px 40px 26px;overflow:hidden}
.band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--copper) 12%,transparent) 1px,transparent 1px);background-size:26px 26px;mask-image:linear-gradient(120deg,#000,transparent 78%)}
.band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--copper)}
.band>*{position:relative}
.wm{font-family:var(--serif);font-size:27px;font-weight:600;color:#fff;line-height:1;letter-spacing:-.2px}
.tag{display:block;font-family:var(--mono);font-size:10px;letter-spacing:2.4px;color:#9aa2ab;text-transform:uppercase;margin-top:10px}
.ey{font-family:var(--mono);font-size:10.5px;letter-spacing:3px;text-transform:uppercase;color:var(--copper-l);margin-top:20px;font-weight:500}
h1{font-family:var(--serif);color:#fff;font-size:23px;font-weight:600;margin:7px 0 0;letter-spacing:-.2px;text-wrap:balance}
.review-offer{display:inline-block;margin-top:14px;color:var(--copper-l);font-family:var(--mono);font-size:11px;font-weight:600;line-height:1.45;text-decoration:none}

.meta{padding:13px 40px;background:var(--cream);border-bottom:1px solid var(--line);font-family:var(--mono);font-size:11px;color:var(--mute);display:flex;flex-wrap:wrap;gap:5px 4px;align-items:center}
.meta b{color:var(--ink)}
.ro{display:inline-block;background:var(--bg);color:var(--green);font-family:var(--mono);font-size:10px;font-weight:600;padding:2px 9px;letter-spacing:.5px;border:1px solid color-mix(in srgb,var(--green) 40%,var(--line))}
.currency-attestation{padding:16px 0 10px;border-bottom:1px solid var(--line);background:var(--bg)}
.currency-alert,.currency-verified{margin:0 40px 12px;padding:13px 16px;font-family:var(--mono);font-size:11px;font-weight:600}
.currency-alert{background:var(--red-t);border:2px solid var(--red);color:var(--red)}
.currency-verified{background:var(--green-t);border-left:4px solid var(--green);color:var(--green)}
.currency-attestation h2{margin:0 40px;padding:0 0 7px;border-bottom:2px solid var(--ink);font-family:var(--serif);font-size:15.5px;color:var(--ink)}
.currency-attestation .currency-table{margin-top:2px;margin-bottom:0;font-family:var(--mono);font-size:10.5px}
.privacy-callout{margin:18px 40px;padding:14px 16px;background:var(--cream);border-left:4px solid var(--copper);font-size:12px;color:var(--ink)}
.privacy-callout code{font-family:var(--mono);font-size:11px}

.score{display:flex;flex-wrap:wrap;gap:0;padding:24px 40px 8px;align-items:stretch}
.banner{order:-1;flex-basis:100%;display:flex;align-items:center;gap:12px;margin-bottom:12px;padding:15px 20px;color:#fff;font-weight:600;font-size:14.5px;line-height:1.35}
.banner::before{content:"";width:10px;height:10px;background:rgba(255,255,255,.95);flex:none}
.banner.RED{background:var(--red)}.banner.AMBER{background:var(--amber)}
.banner.GREEN{background:var(--green)}.banner.INCOMPLETE{background:var(--mute)}
.scorebox{flex:1;min-width:96px;padding:14px 18px;border:1px solid var(--line);border-left:none;background:var(--bg)}
.scorebox:first-child{border-left:1px solid var(--line)}
.scorebox .n{font-family:var(--serif);font-size:31px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums;line-height:1;border-left:3px solid var(--line);padding-left:11px}
.scorebox:first-child .n{border-left-color:var(--copper)}
.scorebox:nth-child(2) .n{border-left-color:var(--green)}
.scorebox:nth-child(3) .n{border-left-color:var(--amber)}
.scorebox:nth-child(4) .n{border-left-color:var(--red)}
.scorebox:nth-child(5) .n{border-left-color:var(--na)}
.scorebox:nth-child(6) .n{border-left-color:var(--na)}
.scorebox .l{font-family:var(--mono);font-size:9.5px;letter-spacing:1.3px;text-transform:uppercase;color:var(--mute);margin-top:8px;padding-left:14px}

.exec-summary{margin:22px 40px 14px}
.exec-summary h2{font-family:var(--serif);font-size:18px;font-weight:600;color:var(--ink);margin:0 0 16px;padding:0 0 8px;border-bottom:2px solid var(--ink)}
.area-bars{display:grid;gap:6px}
.area-bar{display:grid;grid-template-columns:200px minmax(0,1fr) auto;gap:10px;align-items:center;padding:6px 0}
.area-bar.fail .area-meter{box-shadow:inset 0 0 0 1px var(--red)}
.area-bar.warn .area-meter{box-shadow:inset 0 0 0 1px var(--amber)}
.area-bar.pass .area-meter{box-shadow:inset 0 0 0 1px var(--green)}
.area-bar.na .area-meter{box-shadow:inset 0 0 0 1px var(--na)}
.area-label{font-weight:600;color:var(--ink);font-size:11.5px;text-align:right}
.area-meter{display:flex;height:14px;background:var(--line)}
.area-meter-fill{display:block;height:100%}
.area-meter-fill.pass{background:var(--green)}
.area-meter-fill.warn{background:var(--amber)}
.area-meter-fill.fail{background:var(--red)}
.area-meter-fill.na{background:var(--na)}
.area-meter-fill.napp{background:var(--na-t);box-shadow:inset 0 0 0 1px var(--na)}
.area-count{font-family:var(--mono);font-size:10.5px;color:var(--mute);font-variant-numeric:tabular-nums;white-space:nowrap}
.area-count .fail-count{color:var(--red);font-weight:600}
.area-count .warn-count{color:var(--amber);font-weight:600}
.area-count .na-count{color:var(--mute)}
.area-count .napp-count{color:var(--mute)}
.exec-summary-note{margin:18px 0 0;font-size:11px;color:var(--mute)}
.exec-summary-note b{color:var(--ink)}
.exec-summary-note .na-note{color:var(--na)}
.exec-summary-note .napp-note{color:var(--na)}

.start-here{margin:18px 40px 8px;padding:18px 20px;background:var(--cream);border-left:4px solid var(--copper)}
.start-here h2{margin:0;padding:0;border:0;font-family:var(--serif);font-size:18px;font-weight:600;color:var(--ink)}
.start-here-copy{margin:5px 0 0;color:var(--body);font-size:12px}
.start-here-review{display:inline-block;margin-top:10px;color:var(--copper-d);font-family:var(--mono);font-size:11px;font-weight:600;line-height:1.45;text-decoration:none}
.top-risks{margin:12px 0 0;padding-left:26px}
.top-risk{margin:8px 0;padding:11px 13px;background:var(--bg);border:1px solid var(--line);border-left:4px solid var(--amber)}
.top-risk.FAIL{border-left-color:var(--red)}
.top-risk-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px}
.top-risk-label{font-weight:600;color:var(--ink)}
.top-risk-rank{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.5px;text-transform:uppercase;color:var(--mute);white-space:nowrap}
.top-risk-observed{margin-top:5px;font-size:11.5px;overflow-wrap:anywhere}
.top-risk-observed{font-family:var(--mono);color:var(--ink)}
.start-here-none{margin:12px 0 0;padding:10px 12px;background:var(--bg);border-left:4px solid var(--na);color:var(--ink)}

.plan-card{margin:22px 40px 14px;padding:20px;background:var(--cream);border:2px solid var(--copper);color:var(--body)}
.plan-card-main{display:grid;grid-template-columns:minmax(0,1fr) 32mm;gap:20px;align-items:start}
.plan-card-copy{min-width:0}
.plan-copy-status{display:inline-block;margin:0 0 9px;padding:3px 8px;background:var(--copper-d);color:#fff;font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.7px}
.plan-card h2{margin:0;padding:0;border:0;color:var(--ink);font-family:var(--serif);font-size:20px;line-height:1.2}
.plan-link{margin:14px 0 0}.plan-link a{display:inline-block;padding:9px 12px;background:var(--slate);color:#fff;font-weight:600;text-decoration:none}
.plan-card a:focus-visible{outline:3px solid var(--copper);outline-offset:3px}
.plan-fallback{margin:9px 0 0;color:var(--ink);font-family:var(--mono);font-size:10.5px;overflow-wrap:anywhere}
.plan-qr{margin:0;display:flex;flex-direction:column;align-items:center;gap:7px;color:var(--body)}
.plan-qr svg{display:block;width:32mm;height:32mm;max-width:none;flex:none;background:#fff}
.plan-qr figcaption{max-width:32mm;font-size:9.5px;line-height:1.35;text-align:center}
.plan-safe-send{margin-top:16px;padding:12px 14px;background:var(--bg);border-left:4px solid var(--copper);color:var(--ink);font-size:11px;overflow-wrap:anywhere}
.plan-safe-send p{margin:0}.plan-safe-send p + p{margin-top:7px}
.plan-safe-send code{font-family:var(--mono);font-size:10px}.plan-safe-send a{color:var(--copper-d);font-weight:600}

.cathead{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:30px 40px 0;padding:0 0 8px;border-bottom:2px solid var(--ink)}
.cathead .cl{font-family:var(--serif);font-size:15.5px;color:var(--ink);font-weight:600}
.cathead .cr{display:flex;align-items:center;gap:10px}
.cathead .cnt{font-family:var(--mono);font-size:10.5px;color:var(--mute);font-variant-numeric:tabular-nums}
.cvss .cov{margin-top:10px}.cvss table{margin-bottom:14px}
.actions .cov{margin-top:10px}.actions table{margin-bottom:14px}
.action-priority{font-family:var(--serif);font-size:16px;font-weight:600;color:var(--ink);width:5%}
.action-id{font-family:var(--mono);font-size:9px;color:var(--mute);margin-top:4px}
.action-tier{font-family:var(--mono);font-size:9.5px;white-space:nowrap}
.chip{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.8px;padding:3px 9px;color:#fff;text-transform:uppercase}
.chip.RED{background:var(--red)}.chip.AMBER{background:var(--amber)}.chip.GREEN{background:var(--green)}.chip.INCOMPLETE,.chip.MUTE{background:var(--na)}

table{width:calc(100% - 80px);margin:2px 40px 6px;border-collapse:separate;border-spacing:0;font-size:12.5px}
thead th{color:var(--mute);font-family:var(--mono);font-size:9.5px;letter-spacing:1.1px;text-transform:uppercase;text-align:left;font-weight:600;padding:10px 12px 7px;border-bottom:1px solid var(--line)}
td{padding:11px 12px;border-bottom:1px solid var(--line);vertical-align:top}
td.ctl{font-weight:600;color:var(--ink);width:19%}
td.st{font-family:var(--mono);font-weight:600;width:7%;font-size:10px}
td.st.PASS{color:var(--green)}td.st.WARN{color:var(--amber)}td.st.FAIL{color:var(--red)}td.st.NOT_ASSESSED,td.st.NOT_APPLICABLE{color:var(--na)}
td.sev{font-family:var(--mono);color:var(--mute);text-transform:uppercase;font-size:9.5px;width:6%;letter-spacing:.4px}
td.cis{font-family:var(--mono);color:var(--ink);font-size:9.5px;white-space:nowrap;width:9%}
td.obs{font-family:var(--mono);font-size:11px;color:var(--ink);width:20%;word-break:break-word}
tr.FAIL td:first-child{box-shadow:inset 4px 0 var(--red)}
tr.WARN td:first-child{box-shadow:inset 4px 0 var(--amber)}
tr.PASS td:first-child{box-shadow:inset 4px 0 color-mix(in srgb,var(--green) 55%,transparent)}
tr.NOT_ASSESSED td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.NOT_APPLICABLE td:first-child{box-shadow:inset 4px 0 var(--na)}
tr.FAIL{background:var(--red-t)}tr.WARN{background:var(--amber-t)}tr.NOT_ASSESSED,tr.NOT_APPLICABLE{background:var(--na-t)}
.mitigate{margin:2px 40px 16px;font-family:var(--mono);font-size:10px;letter-spacing:.3px;color:var(--mute)}
.mitigate a{color:var(--copper-d);font-weight:600;text-decoration:none}

footer{margin:26px 40px 34px;padding:15px 0 0;border-top:2px solid var(--copper);font-family:var(--mono);font-size:10px;letter-spacing:.4px;color:var(--mute);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
footer b,footer a{color:var(--copper-d)}
.cta a{color:var(--copper-d);font-weight:600;text-decoration:none}

.page-break{margin:30px 40px 0;border-top:3px solid var(--copper)}
@media screen{.page-break{padding-top:14px}}

@media print{
  @page{
    margin:18mm 12mm 18mm;
    @top-left{content:"PTxray · ${PRINT_HOST}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @top-right{content:"${REPORT_DATE}";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-left{content:"PowerTrue Systems";font-family:var(--mono);font-size:8pt;color:#5C5F63}
    @bottom-right{content:"Page " counter(page) " of " counter(pages);font-family:var(--mono);font-size:8pt;color:#5C5F63}
  }
  :root,:root[data-theme="dark"],:root[data-theme="light"]{
    --slate:#1B1F24;--slate2:#23272E;--slate3:#2B3038;
    --ink:#23272E;--body:#5C5F63;--mute:#6B7280;
    --cream:#F4F2EE;--line:#D8D3CB;--bg:#ffffff;
    --red:#9F2F23;--amber:#805B12;--green:#236641;--na:#666E78;
    --red-t:#F7ECE9;--amber-t:#F7F1E6;--green-t:#EEF4EF;--na-t:#F1F1EF;
  }
  html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  body{max-width:none;background:#fff;color:var(--body);font-size:10pt;line-height:1.4}
  .band::before{display:none}
  .band,.meta,.score,.banner,.scorebox,.cov,.attrib,footer,li{break-inside:avoid;page-break-inside:avoid}
  .plan-card,.plan-card-main,.plan-safe-send,.plan-qr{break-inside:avoid;page-break-inside:avoid}
  .plan-card{margin-left:0;margin-right:0}
  .plan-card h2{break-before:auto;page-break-before:auto;break-after:auto;page-break-after:auto}
  .plan-qr svg{width:32mm;height:32mm}
  .exec-summary h2{break-before:auto;page-break-before:auto}
  .page-break{border-top:0;margin:0;break-before:page;page-break-before:always}
  .page-break + *{break-before:auto;page-break-before:auto}
  .exec-summary{break-inside:avoid;page-break-inside:avoid}
  .area-bar{break-inside:avoid;page-break-inside:avoid}
  h2,.cathead{break-after:avoid-page;page-break-after:avoid}
  h2,.start-here + .cathead,table + .cathead{break-before:page;page-break-before:always}
  .start-here h2{break-before:auto;page-break-before:auto}
  .currency-attestation{break-inside:avoid;page-break-inside:avoid}
  .currency-attestation h2{break-before:auto;page-break-before:auto}
  thead{display:table-header-group}
  tr,td{break-inside:avoid;page-break-inside:avoid}
  h2,.start-here,.cathead,.cov,.manual,.none,.attrib,footer{margin-left:0;margin-right:0}
  table{width:100%;margin-left:0;margin-right:0;font-size:9pt}
  .cta,.mitigate{display:none}
}
@media (max-width:620px){
  .band,.meta,.score,.cathead,footer{padding-inline:22px;margin-inline:0}
  .start-here{margin-inline:22px;padding:16px}
  .top-risk-head{align-items:flex-start;flex-direction:column;gap:3px}
  table{width:calc(100% - 44px);margin-inline:22px}
  .scorebox{min-width:calc(50% - 1px)}
  .plan-card{margin-inline:22px;padding:16px}
  .plan-card-main{grid-template-columns:1fr}
  .area-bar{grid-template-columns:1fr;gap:3px;padding:8px 0}
  .area-label{text-align:left}
  .exec-summary{margin-inline:22px}
}
</style></head><body>
<div class="band"><div class="wm"><span data-aixray-field="authored" data-aixray-copy-id="product:brand-name-v1">PTxray</span><div class="tag" data-aixray-field="authored" data-aixray-copy-id="product:brand-tag-native-v1">by PowerTrue Systems · AIX · IBM Power · VIOS</div></div><div class="ey" data-aixray-field="technical" data-aixray-location="report:report-kind">${SNAP_EY}</div><h1><span data-aixray-field="technical" data-aixray-location="report:title-kind">${SNAP_H1}</span> — <span data-aixray-field="identity" data-aixray-location="report:title-host">${HOST_H}</span></h1><a class="review-offer" href="mailto:review@powertruesystems.com" data-aixray-field="authored" data-aixray-copy-id="product:review-cta-v1">${REVIEW_CTA}</a></div>
<div class="meta"><b>Host:</b> <span data-aixray-field="identity" data-aixray-location="report:host">${HOST_H}</span> &nbsp;·&nbsp; <b>Generated:</b> <span data-aixray-field="technical" data-aixray-location="report:generated-date">${NOW}</span> &nbsp;·&nbsp; <b>Reference data:</b> <span data-aixray-field="observed" data-aixray-location="report:reference-data">${DATA_VINTAGE_H}${FLRTVC_HTML_META}</span> &nbsp;·&nbsp; <span class="ro" data-aixray-field="authored" data-aixray-copy-id="product:read-only-v1">READ-ONLY — nothing was changed</span></div>
<div class="privacy-callout" data-aixray-field="authored" data-aixray-copy-id="raw-privacy-callout-v1">This raw report contains identifying system data. Create a separate pseudonymized review copy before sharing: <code>./ptxray-review-pack.sh --pseudonymize &lt;this-report&gt;</code>. Inspect the review copy and local removals manifest before anything leaves this machine.</div>
${CURRENCY_HTML_BLOCK}
<div class="score">
  <div class="scorebox"><div class="n" data-aixray-field="technical" data-aixray-location="report:pass-rate">${SCORE}%</div><div class="l">Pass rate</div></div>
  <div class="scorebox"><div class="n" style="color:var(--green)" data-aixray-field="technical" data-aixray-location="report:pass-count">${PASS}</div><div class="l">Pass</div></div>
  <div class="scorebox"><div class="n" style="color:var(--amber)" data-aixray-field="technical" data-aixray-location="report:warn-count">${WARN}</div><div class="l">Warn</div></div>
  <div class="scorebox"><div class="n" style="color:var(--red)" data-aixray-field="technical" data-aixray-location="report:fail-count">${FAIL}</div><div class="l">Fail</div></div>
  <div class="scorebox"><div class="n" style="color:var(--mute)" data-aixray-field="technical" data-aixray-location="report:not-assessed-count">${NASSESSED}</div><div class="l">Not assessed</div></div>
  <div class="scorebox"><div class="n" style="color:var(--mute)" data-aixray-field="technical" data-aixray-location="report:not-applicable-count">${NOTAPPLICABLE}</div><div class="l">Not applicable</div></div>
  <div class="banner ${BANNER}" data-aixray-field="observed" data-aixray-location="report:posture-banner">${BANNER} — ${BMSG}</div></div>
<section class="exec-summary" aria-labelledby="exec-title">
  <h2 id="exec-title">Page 1 · Executive summary</h2>
  <div class="area-bars">${EXEC_SUMMARY}</div>
  ${EXEC_SUMMARY_NOTE}
</section>
<section class="start-here" id="start-here" aria-labelledby="start-here-title">
  <h2 id="start-here-title">Start here: top risks</h2>
  <p class="start-here-copy" data-aixray-field="authored" data-aixray-copy-id="native:top-risk-order-v2">Work these in order: FAIL before WARN, then native severity high, med, and low. Within a tier, findings that more independent benchmarks require come first, at most two per area, and finding id breaks any remaining tie.</p>
  <a class="start-here-review" href="mailto:review@powertruesystems.com" data-aixray-field="authored" data-aixray-copy-id="product:review-cta-v1">${REVIEW_CTA}</a>
  <ol class="top-risks">${START_HERE_ITEMS}</ol>
${START_HERE_NOTE}
</section>
$(plan_card_html "$TOP_RISK_COUNT")
<div class="page-break"></div>
<h2>Page 2 · Complete assessment detail</h2>
${ACTIONBLOCK}
${CVSSBLOCK}
${CATBLOCKS}
<footer><span data-aixray-field="authored" data-aixray-copy-id="product:footer-snapshot-v1">PTxray · by PowerTrue Systems · read-only · this snapshot is yours to keep</span><a href="mailto:review@powertruesystems.com" data-aixray-field="authored" data-aixray-copy-id="product:review-cta-v1">${REVIEW_CTA}</a></footer>
<div class="cta" style="padding:14px 32px;background:var(--cream);font-family:var(--sans);font-size:12px;color:var(--ink)">
  <p style="margin:0 0 6px" data-aixray-field="authored" data-aixray-copy-id="product:book-cta-v1">${BOOK_CTA}</p>
  <p data-aixray-field="authored" data-aixray-copy-id="product:privacy-reminder-v1">Your raw report contains your hostname, addresses, and configuration. Create a separate pseudonymized review candidate with <code>./ptxray-review-pack.sh --pseudonymize &lt;this-report&gt;</code>. Inspect the candidate and local removals manifest before sharing; never send the local decode key or local manifest.</p>
  <p data-aixray-field="authored" data-aixray-copy-id="product:review-email-v1"><a href="mailto:review@powertruesystems.com">review@powertruesystems.com</a></p>
</div>
</body></html>
HTML
}

if [ -n "$OUT_DIR" ]; then
  if ! mkdir -p "$OUT_DIR" 2>/dev/null; then
    if [ "$OUT_EXPLICIT" -eq 1 ]; then
      echo "ptxray: --out: cannot create directory '$OUT_DIR'" >&2
    else
      echo "ptxray: cannot write the report in the current directory — cd to a writable directory, or use --out DIR" >&2
    fi
    exit 2
  fi
  REPORT_FILE="$OUT_DIR/aixray-$REPORT_HOST-$REPORT_DATE.html"
  REPORT_TMP="$OUT_DIR/.aixray-$REPORT_HOST-$REPORT_DATE.html.tmp.$$"
  if (umask 077; set -C; emit_html_report > "$REPORT_TMP") &&
     [ ! -d "$REPORT_FILE" ] &&
     mv -f "$REPORT_TMP" "$REPORT_FILE" &&
     [ -f "$REPORT_FILE" ] &&
     [ ! -L "$REPORT_FILE" ]; then
    printf 'Report ready: %s — open it in your browser. To save a PDF: Print -> Save as PDF.\n' "$REPORT_FILE" >&2
    finish_report "$REPORT_FILE"
    exit 0
  else
    rm -f "$REPORT_TMP"
    if [ "$OUT_EXPLICIT" -eq 1 ]; then
      echo "ptxray: --out: cannot write report '$REPORT_FILE'" >&2
    else
      echo "ptxray: cannot write the report in the current directory — cd to a writable directory, or use --out DIR" >&2
    fi
    exit 2
  fi
else
  if emit_html_report; then
    finish_report
    exit 0
  else
    REPORT_RC=$?
    exit "$REPORT_RC"
  fi
fi
